                      </div>
                    </CardContent>
                  </Card>
                </div>
              )}
            </>
          )}
        </TabsContent>

        {/* Sessions Tab */}
        <TabsContent value="sessions">
          <DataTable
            title="Session Costs"
            description="Per-session AI usage breakdown"
            icon={FileText}
            data={sessions}
