              ) : userDetails ? (
                <>
                  {/* Usage Summary */}
                  <div className="grid grid-cols-2 gap-3">
                    <div className="rounded-lg bg-gray-800/50 p-3">
                      <div className="text-xs text-gray-400">Total Cost</div>
                      <div className="text-xl font-bold text-green-400">
                        {formatCost(userDetails.usage?.totalCost || 0)}
                      </div>
                    </div>
                    <div className="rounded-lg bg-gray-800/50 p-3">
                      <div className="text-xs text-gray-400">Budget Used</div>
                      <div className="text-xl font-bold text-white">
                        {(userDetails.usage?.budgetUsedPercent || 0).toFixed(1)}%
                      </div>
                    </div>
                  </div>

                  {/* Sessions */}
                  <div>
                    <h3 className="mb-2 text-sm font-medium text-gray-400">Recent Sessions</h3>
                    <div className="space-y-2">
                      {userDetails.sessions?.length > 0 ? (
                        userDetails.sessions.map((session: any) => (
                          <div key={session.sessionId} className="rounded-lg bg-gray-800/30 p-3">
                            <div className="mb-1 flex items-center justify-between">
                              <span className="text-sm text-white">{session.scenarioTitle}</span>
                              <span className="font-mono text-sm text-green-400">
                                {formatCost(session.cost)}
                              </span>
                            </div>
                            <div className="flex items-center gap-2">
                              <Badge
                                variant="outline"
                                className="border-gray-700 text-xs text-gray-400"
                              >
                                {session.pattern}
                              </Badge>
                              <Badge
                                className={`text-xs ${getDifficultyColor(session.difficulty)}`}
                              >
                                {session.difficulty}
                              </Badge>
                              <span className="ml-auto text-xs text-gray-500">
                                {formatTokens(session.tokens)} tokens
                              </span>
                            </div>
                          </div>
                        ))
                      ) : (
                        <div className="py-4 text-center text-gray-500">No sessions found</div>
                      )}
                    </div>
                  </div>
                </>
              ) : (
                <div className="py-8 text-center text-gray-500">Failed to load user details</div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Clear Cache Dialog */}
      <AlertDialog open={clearCacheDialogOpen} onOpenChange={setClearCacheDialogOpen}>
        <AlertDialogContent className="border-gray-800 bg-gray-900">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-white">Clear AI Cache</AlertDialogTitle>
            <AlertDialogDescription className="text-gray-400">
              This will clear all cached AI responses. This may temporarily increase API costs as
              the cache rebuilds.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="border-gray-700 bg-gray-800 text-gray-300 hover:bg-gray-700">
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={handleClearCache}
              disabled={clearingCache}
              className="bg-red-600 text-white hover:bg-red-700"
            >
              {clearingCache ? "Clearing..." : "Clear Cache"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Set Budget Dialog */}
      <AlertDialog open={budgetDialogOpen} onOpenChange={setBudgetDialogOpen}>
        <AlertDialogContent className="border-gray-800 bg-gray-900">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-white">Set Custom Budget</AlertDialogTitle>
            <AlertDialogDescription className="text-gray-400">
              Set a custom monthly AI budget for{" "}
              <strong className="text-white">{selectedUser?.email}</strong>.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="py-4">
            <div className="flex items-center gap-2">
              <span className="text-white">$</span>
              <Input
                type="number"
                placeholder="e.g., 50.00"
                value={newBudget}
                onChange={(e) => setNewBudget(e.target.value)}
                className="border-gray-700 bg-gray-800 text-white"
                min={0}
                max={10000}
                step={0.01}
              />
            </div>
            <p className="mt-2 text-xs text-gray-500">
              Default: Free $0.50 | Pro $25 | Enterprise $100
            </p>
          </div>
          <AlertDialogFooter>
            <AlertDialogCancel
              className="border-gray-700 bg-gray-800 text-gray-300 hover:bg-gray-700"
              onClick={() => {
                setNewBudget("")
              }}
            >
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={handleSetBudget}
              disabled={settingBudget || !newBudget}
              className="bg-[#00d9ff] text-black hover:bg-[#00d9ff]/80"
            >
              {settingBudget ? "Setting..." : "Set Budget"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

"use client"

import { useEffect, useState, useCallback } from "react"
import { useAuth } from "@/lib/auth-context"
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Switch } from "@/components/ui/switch"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  Megaphone,
  RefreshCw,
  Plus,
  Edit2,
  Trash2,
  Eye,
  X,
  AlertCircle,
  Info,
  AlertTriangle,
  CheckCircle,
  Bell,
  Users,
  Calendar,
  ExternalLink,
  MoreHorizontal,
  Power,
  PowerOff,
} from "lucide-react"
import { logger } from "@/lib/logger"
import { cn } from "@/lib/utils"

interface Announcement {
  id: string
  title: string
  message: string
  type: "banner" | "modal" | "toast" | "page"
  priority: "info" | "warning" | "critical" | "success"
  targetAudience: "all" | "free" | "pro" | "enterprise" | "specific"
  startDate: string
  endDate?: string
  dismissible: boolean
  active: boolean
  createdAt: string
  views: number
  dismissals: number
  cta?: {
    text: string
    url: string
  }
}

const priorityConfig = {
  info: {
    icon: Info,
    label: "Info",
    color: "bg-accent/10 text-accent border-accent/20",
    iconColor: "text-accent",
    badgeClass: "bg-accent/10 text-accent border-accent/20",
  },
  warning: {
    icon: AlertTriangle,
    label: "Warning",
    color: "bg-amber-500/10 text-amber-400 border-amber-500/20",
    iconColor: "text-amber-400",
    badgeClass: "bg-amber-500/10 text-amber-400 border-amber-500/20",
  },
  critical: {
    icon: AlertCircle,
    label: "Critical",
    color: "bg-destructive/10 text-destructive border-destructive/20",
    iconColor: "text-destructive",
    badgeClass: "bg-destructive/10 text-destructive border-destructive/20",
  },
  success: {
    icon: CheckCircle,
    label: "Success",
    color: "bg-neural/10 text-neural border-neural/20",
    iconColor: "text-neural",
    badgeClass: "bg-neural/10 text-neural border-neural/20",
  },
}

const typeConfig = {
  banner: { label: "Banner", description: "Top banner across all pages" },
  modal: { label: "Modal", description: "Popup dialog on first visit" },
  toast: { label: "Toast", description: "Temporary notification" },
  page: { label: "Page", description: "Dedicated announcement page" },
}

const audienceConfig = {
  all: { label: "All Users", icon: Users },
  free: { label: "Free", icon: Users },
  pro: { label: "Pro", icon: Users },
  enterprise: { label: "Enterprise", icon: Users },
  specific: { label: "Specific", icon: Users },
}

const defaultAnnouncement: {
  title: string
  message: string
  type: "banner" | "modal" | "toast" | "page"
  priority: "info" | "warning" | "critical" | "success"
  targetAudience: "all" | "free" | "pro" | "enterprise" | "specific"
  targetUserIds: string
  startDate: string
  endDate: string
  dismissible: boolean
  active: boolean
  cta: { text: string; url: string }
} = {
  title: "",
  message: "",
  type: "banner",
  priority: "info",
  targetAudience: "all",
  targetUserIds: "",
  startDate: new Date().toISOString().slice(0, 16),
  endDate: "",
  dismissible: true,
  active: true,
  cta: { text: "", url: "" },
}

export default function AnnouncementsPage() {
  const { firebaseUser } = useAuth()
  const [announcements, setAnnouncements] = useState<Announcement[]>([])
  const [stats, setStats] = useState({ total: 0, active: 0, totalViews: 0, totalDismissals: 0 })
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)
  const [saving, setSaving] = useState(false)

  // Dialog state
  const [dialogOpen, setDialogOpen] = useState(false)
  const [editingAnnouncement, setEditingAnnouncement] = useState<Partial<Announcement> | null>(null)
  const [formData, setFormData] = useState(defaultAnnouncement)
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null)

  const loadAnnouncements = useCallback(
    async (showRefreshing = false) => {
      if (!firebaseUser) return

      if (showRefreshing) setRefreshing(true)

      try {
        const token = await firebaseUser.getIdToken()
        const response = await fetch("/api/admin/announcements", {
          headers: { Authorization: `Bearer ${token}` },
        })

        if (response.ok) {
          const data = await response.json()
          if (data.success) {
            setAnnouncements(data.announcements)
            setStats(data.stats)
          }
        }
      } catch (error) {
        logger.error("Error loading announcements", { error })
      } finally {
        setLoading(false)
        setRefreshing(false)
      }
    },
    [firebaseUser]
  )

  useEffect(() => {
    loadAnnouncements()
  }, [loadAnnouncements])

  const handleOpenCreate = () => {
    setEditingAnnouncement(null)
    setFormData(defaultAnnouncement)
    setDialogOpen(true)
  }

  const handleOpenEdit = (announcement: Announcement) => {
    setEditingAnnouncement(announcement)
    setFormData({
      title: announcement.title || "",
      message: announcement.message || "",
      type: announcement.type || "banner",
      priority: announcement.priority || "info",
      targetAudience: announcement.targetAudience || "all",
      targetUserIds: (announcement as any).targetUserIds?.join(", ") || "",
      startDate: announcement.startDate?.slice(0, 16) || "",
      endDate: announcement.endDate?.slice(0, 16) || "",
      dismissible: announcement.dismissible ?? true,
      active: announcement.active ?? true,
      cta: announcement.cta || { text: "", url: "" },
    })
    setDialogOpen(true)
  }

  const handleSave = async () => {
    if (!firebaseUser) return

    setSaving(true)
    try {
      const token = await firebaseUser.getIdToken()
      const method = editingAnnouncement ? "PUT" : "POST"

      const body: any = editingAnnouncement
        ? { id: editingAnnouncement.id, ...formData }
        : { ...formData }

      if (formData.targetAudience === "specific" && formData.targetUserIds) {
        body.targetUserIds = formData.targetUserIds
          .split(",")
          .map((id: string) => id.trim())
          .filter((id: string) => id.length > 0)
      } else {
        delete body.targetUserIds
      }

      if (!body.cta?.text && !body.cta?.url) {
        body.cta = undefined as any
      }

      const response = await fetch("/api/admin/announcements", {
        method,
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
      })

      if (response.ok) {
        setDialogOpen(false)
        loadAnnouncements(true)
      }
    } catch (error) {
      logger.error("Error saving announcement", { error })
    } finally {
      setSaving(false)
    }
  }

  const handleDelete = async (id: string) => {
    if (!firebaseUser) return

    try {
      const token = await firebaseUser.getIdToken()
      const response = await fetch(`/api/admin/announcements?id=${id}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      })

      if (response.ok) {
        setDeleteConfirmId(null)
        loadAnnouncements(true)
      }
    } catch (error) {
      logger.error("Error deleting announcement", { error })
    }
  }

  const handleToggleActive = async (announcement: Announcement) => {
    if (!firebaseUser) return

    try {
      const token = await firebaseUser.getIdToken()
      await fetch("/api/admin/announcements", {
        method: "PUT",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          id: announcement.id,
          active: !announcement.active,
        }),
      })

      loadAnnouncements(true)
    } catch (error) {
      logger.error("Error toggling announcement", { error })
    }
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    })
  }

  const formatNumber = (num: number) => {
    if (num >= 1000000) return `${(num / 1000000).toFixed(1)}M`
    if (num >= 1000) return `${(num / 1000).toFixed(1)}K`
    return num.toString()
  }

  if (loading) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="relative">
            <div className="border-muted h-12 w-12 rounded-full border-2" />
            <div className="border-accent absolute inset-0 h-12 w-12 animate-spin rounded-full border-t-2" />
          </div>
          <p className="text-muted-foreground text-sm">Loading announcements...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="font-heading text-foreground text-2xl font-bold tracking-tight sm:text-3xl">
            Announcements
          </h1>
          <p className="text-muted-foreground mt-1 text-sm">
            Manage system announcements and user notifications
          </p>
        </div>

        <div className="flex items-center gap-2">
          <Button
            onClick={() => loadAnnouncements(true)}
            disabled={refreshing}
            variant="outline"
            size="sm"
            className="h-9"
          >
            <RefreshCw className={cn("mr-2 h-4 w-4", refreshing && "animate-spin")} />
            Refresh
          </Button>

          <Button
            onClick={handleOpenCreate}
            size="sm"
            className="bg-accent text-accent-foreground hover:bg-accent/90 h-9"
          >
            <Plus className="mr-2 h-4 w-4" />
            New Announcement
          </Button>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
        <Card className="border-border bg-card">
          <CardContent className="p-5">
            <div className="flex items-center gap-4">
              <div className="bg-accent/10 flex h-11 w-11 items-center justify-center rounded-xl">
                <Megaphone className="text-accent h-5 w-5" />
              </div>
              <div>
                <p className="text-foreground text-2xl font-bold tracking-tight">{stats.total}</p>
                <p className="text-muted-foreground text-xs">Total</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="border-border bg-card">
          <CardContent className="p-5">
            <div className="flex items-center gap-4">
              <div className="bg-neural/10 flex h-11 w-11 items-center justify-center rounded-xl">
                <Bell className="text-neural h-5 w-5" />
              </div>
              <div>
                <p className="text-foreground text-2xl font-bold tracking-tight">{stats.active}</p>
                <p className="text-muted-foreground text-xs">Active</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="border-border bg-card">
          <CardContent className="p-5">
            <div className="flex items-center gap-4">
              <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-amber-500/10">
                <Eye className="h-5 w-5 text-amber-400" />
              </div>
              <div>
                <p className="text-foreground text-2xl font-bold tracking-tight">
                  {formatNumber(stats.totalViews)}
                </p>
                <p className="text-muted-foreground text-xs">Views</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="border-border bg-card">
          <CardContent className="p-5">
            <div className="flex items-center gap-4">
              <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-purple-500/10">
                <X className="h-5 w-5 text-purple-400" />
              </div>
              <div>
                <p className="text-foreground text-2xl font-bold tracking-tight">
                  {formatNumber(stats.totalDismissals)}
                </p>
                <p className="text-muted-foreground text-xs">Dismissals</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Announcements List */}
      <Card className="border-border bg-card">
        <CardHeader className="border-border border-b pb-4">
          <div className="flex items-center gap-3">
            <div className="bg-accent/10 flex h-9 w-9 items-center justify-center rounded-lg">
              <Megaphone className="text-accent h-4 w-4" />
            </div>
            <div>
              <CardTitle className="text-base font-semibold">All Announcements</CardTitle>
              <CardDescription className="text-xs">
                {announcements.length} announcement{announcements.length !== 1 ? "s" : ""}
              </CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          {announcements.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16">
              <div className="bg-muted/50 flex h-14 w-14 items-center justify-center rounded-2xl">
                <Megaphone className="text-muted-foreground h-7 w-7" />
              </div>
              <p className="text-foreground mt-4 text-sm font-medium">No announcements yet</p>
              <p className="text-muted-foreground mt-1 text-xs">
                Create your first announcement to communicate with users
              </p>
              <Button onClick={handleOpenCreate} variant="outline" size="sm" className="mt-4">
                <Plus className="mr-2 h-4 w-4" />
                Create Announcement
              </Button>
            </div>
          ) : (
            <div className="divide-border divide-y">
              {announcements.map((announcement) => {
                const PriorityIcon = priorityConfig[announcement.priority].icon
                const isExpired =
                  announcement.endDate && new Date(announcement.endDate) < new Date()
                const isInactive = !announcement.active || isExpired

                return (
                  <div
                    key={announcement.id}
                    className={cn(
                      "group hover:bg-muted/30 flex items-start gap-4 p-4 transition-colors",
                      isInactive && "opacity-60"
                    )}
                  >
                    {/* Priority Icon */}
                    <div
                      className={cn(
                        "mt-0.5 flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-lg",
                        priorityConfig[announcement.priority].color
                      )}
                    >
                      <PriorityIcon className="h-4 w-4" />
                    </div>

                    {/* Content */}
                    <div className="min-w-0 flex-1 space-y-2">
                      <div className="flex flex-wrap items-center gap-2">
                        <h3 className="text-foreground font-medium">{announcement.title}</h3>

                        {/* Status badges */}
                        <div className="flex flex-wrap items-center gap-1.5">
                          <Badge
                            variant="outline"
                            className={cn(
                              "text-[10px] tracking-wide uppercase",
                              priorityConfig[announcement.priority].badgeClass
                            )}
                          >
                            {announcement.priority}
                          </Badge>
                          <Badge
                            variant="outline"
                            className="border-border text-muted-foreground text-[10px] tracking-wide uppercase"
                          >
                            {announcement.type}
                          </Badge>
                          <Badge
                            variant="outline"
                            className="border-purple-500/20 bg-purple-500/10 text-[10px] tracking-wide text-purple-400 uppercase"
                          >
                            <Users className="mr-1 h-2.5 w-2.5" />
                            {announcement.targetAudience}
                          </Badge>

                          {!announcement.active && (
                            <Badge
                              variant="outline"
                              className="border-border text-muted-foreground bg-muted/50 text-[10px] tracking-wide uppercase"
                            >
                              <PowerOff className="mr-1 h-2.5 w-2.5" />
                              Inactive
                            </Badge>
                          )}
                          {isExpired && (
                            <Badge
                              variant="outline"
                              className="border-destructive/20 text-destructive bg-destructive/10 text-[10px] tracking-wide uppercase"
                            >
                              Expired
                            </Badge>
                          )}
                        </div>
                      </div>

                      <p className="text-muted-foreground line-clamp-2 text-sm">
                        {announcement.message}
                      </p>

                      {/* Meta info */}
                      <div className="text-muted-foreground flex flex-wrap items-center gap-4 text-xs">
                        <span className="flex items-center gap-1">
                          <Calendar className="h-3 w-3" />
                          {formatDate(announcement.createdAt)}
                        </span>
                        {announcement.endDate && (
                          <span className="flex items-center gap-1">
                            <span className="text-muted-foreground/60">Ends:</span>
                            {formatDate(announcement.endDate)}
                          </span>
                        )}
                        <span className="flex items-center gap-1">
                          <Eye className="h-3 w-3" />
                          {formatNumber(announcement.views)}
                        </span>
                        <span className="flex items-center gap-1">
                          <X className="h-3 w-3" />
                          {formatNumber(announcement.dismissals)}
                        </span>
                        {announcement.cta && (
                          <span className="text-accent flex items-center gap-1">
                            <ExternalLink className="h-3 w-3" />
                            {announcement.cta.text}
                          </span>
                        )}
                      </div>
                    </div>

                    {/* Actions */}
                    <div className="flex items-center gap-1 opacity-0 transition-opacity group-hover:opacity-100">
                      <Button
                        variant="ghost"
                        size="icon"
                        className={cn(
                          "h-8 w-8",
                          announcement.active
                            ? "text-neural hover:text-neural hover:bg-neural/10"
                            : "text-muted-foreground hover:text-foreground"
                        )}
                        onClick={() => handleToggleActive(announcement)}
                        title={announcement.active ? "Deactivate" : "Activate"}
                      >
                        {announcement.active ? (
                          <Power className="h-4 w-4" />
                        ) : (
                          <PowerOff className="h-4 w-4" />
                        )}
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="text-muted-foreground hover:text-foreground h-8 w-8"
                        onClick={() => handleOpenEdit(announcement)}
                        title="Edit"
                      >
                        <Edit2 className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="text-muted-foreground hover:text-destructive h-8 w-8"
                        onClick={() => setDeleteConfirmId(announcement.id)}
                        title="Delete"
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                )
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="border-border bg-card max-w-2xl">
          <DialogHeader>
            <DialogTitle className="text-lg font-semibold">
              {editingAnnouncement ? "Edit Announcement" : "Create Announcement"}
            </DialogTitle>
            <DialogDescription className="text-muted-foreground text-sm">
              {editingAnnouncement
                ? "Update the announcement details below"
                : "Create a new announcement to communicate with your users"}
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-5 py-4">
            {/* Title */}
            <div className="space-y-2">
              <Label className="text-sm font-medium">Title</Label>
              <Input
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                placeholder="Announcement title"
                className="h-10"
              />
            </div>

            {/* Message */}
            <div className="space-y-2">
              <Label className="text-sm font-medium">Message</Label>
              <Textarea
                value={formData.message}
                onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                placeholder="Announcement message..."
                className="min-h-[100px] resize-none"
              />
            </div>

            {/* Type and Priority */}
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label className="text-sm font-medium">Type</Label>
                <Select
                  value={formData.type}
                  onValueChange={(value: any) => setFormData({ ...formData, type: value })}
                >
                  <SelectTrigger className="h-10">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {Object.entries(typeConfig).map(([value, config]) => (
                      <SelectItem key={value} value={value}>
                        <div className="flex flex-col">
                          <span className="font-medium capitalize">{config.label}</span>
                          <span className="text-muted-foreground text-xs">
                            {config.description}
                          </span>
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label className="text-sm font-medium">Priority</Label>
                <Select
                  value={formData.priority}
                  onValueChange={(value: any) => setFormData({ ...formData, priority: value })}
                >
                  <SelectTrigger className="h-10">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {Object.entries(priorityConfig).map(([value, config]) => (
                      <SelectItem key={value} value={value}>
                        <div className="flex items-center gap-2">
                          <config.icon className={cn("h-4 w-4", config.iconColor)} />
                          <span className="capitalize">{config.label}</span>
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            {/* Target Audience and Dismissible */}
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label className="text-sm font-medium">Target Audience</Label>
                <Select
                  value={formData.targetAudience}
                  onValueChange={(value: any) =>
                    setFormData({ ...formData, targetAudience: value })
                  }
                >
                  <SelectTrigger className="h-10">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {Object.entries(audienceConfig).map(([value, config]) => (
                      <SelectItem key={value} value={value}>
                        <div className="flex items-center gap-2">
                          <config.icon className="text-muted-foreground h-4 w-4" />
                          <span>{config.label}</span>
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label className="text-sm font-medium">Dismissible</Label>
                <div className="border-input bg-background flex h-10 items-center gap-3 rounded-md border px-3">
                  <Switch
                    checked={formData.dismissible}
                    onCheckedChange={(checked) =>
                      setFormData({ ...formData, dismissible: checked })
                    }
                  />
                  <span className="text-muted-foreground text-sm">
                    {formData.dismissible ? "Users can dismiss" : "Cannot be dismissed"}
                  </span>
                </div>
              </div>
            </div>

            {/* Target User IDs (conditional) */}
            {formData.targetAudience === "specific" && (
              <div className="space-y-2">
                <Label className="text-sm font-medium">Target User IDs</Label>
                <Textarea
                  value={formData.targetUserIds}
                  onChange={(e) => setFormData({ ...formData, targetUserIds: e.target.value })}
                  placeholder="Enter user IDs separated by commas (e.g., user123, user456)"
                  className="min-h-[80px] resize-none"
                />
                <p className="text-muted-foreground text-xs">
                  Comma-separated list of Firebase user IDs to target
                </p>
              </div>
            )}

            {/* Date Range */}
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label className="text-sm font-medium">Start Date & Time</Label>
                <Input
                  type="datetime-local"
                  value={formData.startDate}
                  onChange={(e) => setFormData({ ...formData, startDate: e.target.value })}
                  className="h-10"
                />
              </div>

              <div className="space-y-2">
                <Label className="text-sm font-medium">End Date & Time (Optional)</Label>
                <Input
                  type="datetime-local"
                  value={formData.endDate}
                  onChange={(e) => setFormData({ ...formData, endDate: e.target.value })}
                  className="h-10"
                />
              </div>
            </div>

            {/* CTA */}
            <div className="space-y-2">
              <Label className="text-sm font-medium">Call to Action (Optional)</Label>
              <div className="grid grid-cols-2 gap-4">
                <Input
                  value={formData.cta?.text || ""}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      cta: { ...formData.cta!, text: e.target.value },
                    })
                  }
                  placeholder="Button text"
                  className="h-10"
                />
                <Input
                  value={formData.cta?.url || ""}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      cta: { ...formData.cta!, url: e.target.value },
                    })
                  }
                  placeholder="Button URL"
                  className="h-10"
                />
              </div>
            </div>

            {/* Active Toggle */}
            <div className="border-border bg-muted/30 flex items-center gap-3 rounded-lg border p-4">
              <Switch
                checked={formData.active}
                onCheckedChange={(checked) => setFormData({ ...formData, active: checked })}
              />
              <div>
                <Label className="text-sm font-medium">Active immediately</Label>
                <p className="text-muted-foreground text-xs">
                  When enabled, the announcement will be visible to users right away
                </p>
              </div>
            </div>
          </div>

          <DialogFooter className="gap-2 sm:gap-0">
            <Button variant="outline" onClick={() => setDialogOpen(false)}>
              Cancel
            </Button>
            <Button
              onClick={handleSave}
              disabled={saving || !formData.title || !formData.message}
              className="bg-accent text-accent-foreground hover:bg-accent/90"
            >
              {saving ? (
                <>
                  <RefreshCw className="mr-2 h-4 w-4 animate-spin" />
                  Saving...
                </>
              ) : editingAnnouncement ? (
                "Update"
              ) : (
                "Create"
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={!!deleteConfirmId} onOpenChange={() => setDeleteConfirmId(null)}>
        <DialogContent className="border-border bg-card max-w-md">
          <DialogHeader>
            <DialogTitle className="text-lg font-semibold">Delete Announcement</DialogTitle>
            <DialogDescription className="text-muted-foreground text-sm">
              Are you sure you want to delete this announcement? This action cannot be undone.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="gap-2 sm:gap-0">
            <Button variant="outline" onClick={() => setDeleteConfirmId(null)}>
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={() => deleteConfirmId && handleDelete(deleteConfirmId)}
            >
              Delete
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

"use client"

import { useEffect, useState, useCallback } from "react"
import { useAuth } from "@/lib/auth-context"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { DataTable, Column, renderBadge } from "@/components/admin/shared"
import {
  ClipboardList,
  RefreshCw,
  Download,
  Shield,
  UserCog,
  Search,
  Calendar,
  Filter,
  Activity,
} from "lucide-react"
import { logger } from "@/lib/logger"

interface AuditLogEntry {
  id: string
  adminId: string
  adminEmail?: string
  action: string
  details: Record<string, any>
  timestamp: string
  ip?: string
  userAgent?: string
}

interface AuditStats {
  last24h: number
  last7d: number
  total: number
}

const actionColors: Record<string, "default" | "success" | "warning" | "error"> = {
  grant_role: "success",
  revoke_role: "warning",
  delete_user: "error",
  update_settings: "default",
  budget_change: "warning",
  impersonate_user: "warning",
  export_data: "default",
  create_announcement: "success",
  login: "default",
}

const actionIcons: Record<string, React.ComponentType<{ className?: string }>> = {
  grant_role: Shield,
  revoke_role: Shield,
  delete_user: UserCog,
  update_settings: Activity,
  impersonate_user: UserCog,
}

export default function AuditLogPage() {
  const { firebaseUser } = useAuth()
  const [logs, setLogs] = useState<AuditLogEntry[]>([])
  const [stats, setStats] = useState<AuditStats | null>(null)
  const [availableActions, setAvailableActions] = useState<string[]>([])
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)
  const [exporting, setExporting] = useState(false)

  // Filters
  const [searchQuery, setSearchQuery] = useState("")
  const [actionFilter, setActionFilter] = useState<string>("all")
  const [startDate, setStartDate] = useState("")
  const [endDate, setEndDate] = useState("")

  // Pagination
  const [cursor, setCursor] = useState<string | null>(null)
  const [hasMore, setHasMore] = useState(false)

  const loadLogs = useCallback(
    async (showRefreshing = false, append = false) => {
      if (!firebaseUser) return

      if (showRefreshing) setRefreshing(true)
      if (!append) setLoading(true)

      try {
        const token = await firebaseUser.getIdToken()
        const params = new URLSearchParams({
          limit: "50",
        })

        if (append && cursor) {
          params.set("cursor", cursor)
        }
        if (actionFilter && actionFilter !== "all") {
          params.set("action", actionFilter)
        }
        if (startDate) {
          params.set("startDate", startDate)
        }
        if (endDate) {
          params.set("endDate", endDate)
        }

        const response = await fetch(`/api/admin/audit?${params.toString()}`, {
          headers: { Authorization: `Bearer ${token}` },
        })

        if (response.ok) {
          const data = await response.json()
          if (data.success) {
            if (append) {
              setLogs((prev) => [...prev, ...data.logs])
            } else {
              setLogs(data.logs)
            }
            setStats(data.stats)
            setAvailableActions(data.filters?.actions || [])
            setHasMore(data.pagination?.hasMore || false)
            setCursor(data.pagination?.nextCursor || null)
          }
        }
      } catch (error) {
        logger.error("Error loading audit logs", { error })
      } finally {
        setLoading(false)
        setRefreshing(false)
      }
    },
    [firebaseUser, actionFilter, startDate, endDate, cursor]
  )

  useEffect(() => {
    loadLogs()
  }, [actionFilter, startDate, endDate]) // Reload when filters change

  const handleExport = async () => {
    if (!firebaseUser) return

    setExporting(true)
    try {
      const token = await firebaseUser.getIdToken()
      const response = await fetch("/api/admin/audit", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          startDate: startDate || undefined,
          endDate: endDate || undefined,
          format: "csv",
        }),
      })

      if (response.ok) {
        const blob = await response.blob()
        const url = window.URL.createObjectURL(blob)
        const a = document.createElement("a")
        a.href = url
        a.download = `audit-logs-${new Date().toISOString().split("T")[0]}.csv`
        document.body.appendChild(a)
        a.click()
        document.body.removeChild(a)
        window.URL.revokeObjectURL(url)
      }
    } catch (error) {
      logger.error("Error exporting audit logs", { error })
    } finally {
      setExporting(false)
    }
  }

  const formatDetails = (details: Record<string, any>): string => {
    const parts: string[] = []
    if (details.targetUserId) parts.push(`User: ${details.targetUserId.substring(0, 8)}...`)
    if (details.targetEmail) parts.push(`Email: ${details.targetEmail}`)
    if (details.role) parts.push(`Role: ${details.role}`)
    if (details.deletedDocuments) parts.push(`Docs deleted: ${details.deletedDocuments}`)
    if (details.amount) parts.push(`Amount: $${details.amount}`)
    return parts.join(" | ") || JSON.stringify(details).substring(0, 50)
  }

  // Filter logs by search query (client-side)
  const filteredLogs = logs.filter((log) => {
    if (!searchQuery) return true
    const query = searchQuery.toLowerCase()
    return (
      log.action.toLowerCase().includes(query) ||
      log.adminId.toLowerCase().includes(query) ||
      (log.adminEmail?.toLowerCase().includes(query) ?? false) ||
      JSON.stringify(log.details).toLowerCase().includes(query)
    )
  })

  const columns: Column<AuditLogEntry>[] = [
    {
      key: "timestamp",
      label: "Time",
      width: "160px",
      render: (value) => (
        <span className="text-sm whitespace-nowrap text-gray-300">
          {new Date(value).toLocaleString()}
        </span>
      ),
    },
    {
      key: "action",
      label: "Action",
      width: "150px",
      render: (value) => {
        const color = actionColors[value] || "default"
        return renderBadge(value.replace(/_/g, " ").toUpperCase(), color)
      },
    },
    {
      key: "adminEmail",
      label: "Admin",
      render: (value, row) => (
        <div className="flex flex-col">
          <span className="text-sm text-white">{value || "System"}</span>
          <span className="text-xs text-gray-500">{row.adminId.substring(0, 12)}...</span>
        </div>
      ),
    },
    {
      key: "details",
      label: "Details",
      render: (value) => <span className="text-sm text-gray-400">{formatDetails(value)}</span>,
    },
    {
      key: "ip",
      label: "IP",
      width: "120px",
      render: (value) => <span className="font-mono text-xs text-gray-500">{value || "N/A"}</span>,
    },
  ]

  if (loading && logs.length === 0) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <div className="h-12 w-12 animate-spin rounded-full border-b-2 border-[#00d9ff]"></div>
      </div>
    )
  }

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="font-heading text-3xl font-bold text-white">Audit Log</h1>
          <p className="mt-1 text-gray-400">Track all admin actions for compliance and security</p>
        </div>

        <div className="flex items-center gap-3">
          <Button
            onClick={handleExport}
            disabled={exporting}
            variant="outline"
            size="sm"
            className="border-gray-700 text-gray-400 hover:text-white"
          >
            <Download className={`mr-2 h-4 w-4 ${exporting ? "animate-pulse" : ""}`} />
            Export CSV
          </Button>

          <Button
            onClick={() => loadLogs(true)}
            disabled={refreshing}
            variant="outline"
            size="sm"
            className="border-gray-700 text-gray-400 hover:text-white"
          >
            <RefreshCw className={`mr-2 h-4 w-4 ${refreshing ? "animate-spin" : ""}`} />
            Refresh
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
        <Card className="border-gray-800 bg-gray-900/50">
          <CardContent className="p-6">
            <div className="flex items-center gap-3">
              <div className="rounded-lg bg-[#00d9ff]/20 p-3">
                <Activity className="h-6 w-6 text-[#00d9ff]" />
              </div>
              <div>
                <p className="text-3xl font-bold text-white">{stats?.last24h || 0}</p>
                <p className="text-sm text-gray-400">Actions (24h)</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="border-gray-800 bg-gray-900/50">
          <CardContent className="p-6">
            <div className="flex items-center gap-3">
              <div className="rounded-lg bg-yellow-500/20 p-3">
                <ClipboardList className="h-6 w-6 text-yellow-400" />
              </div>
              <div>
                <p className="text-3xl font-bold text-white">{stats?.last7d || 0}</p>
                <p className="text-sm text-gray-400">Actions (7d)</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="border-gray-800 bg-gray-900/50">
          <CardContent className="p-6">
            <div className="flex items-center gap-3">
              <div className="rounded-lg bg-purple-500/20 p-3">
                <Shield className="h-6 w-6 text-purple-400" />
              </div>
              <div>
                <p className="text-3xl font-bold text-white">{availableActions.length}</p>
                <p className="text-sm text-gray-400">Action Types</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card className="border-gray-800 bg-gray-900/50">
        <CardContent className="p-4">
          <div className="flex flex-wrap items-center gap-4">
            <div className="flex items-center gap-2">
              <Filter className="h-4 w-4 text-gray-400" />
              <span className="text-sm text-gray-400">Filters:</span>
            </div>

            <div className="relative max-w-xs flex-1">
              <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 transform text-gray-400" />
              <Input
                placeholder="Search logs..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="border-gray-700 bg-gray-800 pl-10 text-white"
              />
            </div>

            <Select value={actionFilter} onValueChange={setActionFilter}>
              <SelectTrigger className="w-[180px] border-gray-700 bg-gray-800 text-white">
                <SelectValue placeholder="Action type" />
              </SelectTrigger>
              <SelectContent className="border-gray-700 bg-gray-800">
                <SelectItem value="all" className="text-white">
                  All Actions
                </SelectItem>
                {availableActions.map((action) => (
                  <SelectItem key={action} value={action} className="text-white">
                    {action.replace(/_/g, " ")}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>

            <div className="flex items-center gap-2">
              <Calendar className="h-4 w-4 text-gray-400" />
              <Input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="w-[140px] border-gray-700 bg-gray-800 text-white"
                placeholder="Start date"
              />
              <span className="text-gray-500">to</span>
              <Input
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                className="w-[140px] border-gray-700 bg-gray-800 text-white"
                placeholder="End date"
              />
            </div>

            {(actionFilter !== "all" || startDate || endDate || searchQuery) && (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => {
                  setActionFilter("all")
                  setStartDate("")
                  setEndDate("")
                  setSearchQuery("")
                }}
                className="text-gray-400 hover:text-white"
              >
                Clear filters
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Audit Log Table */}
      <DataTable
        title="Admin Actions"
        icon={ClipboardList}
        data={filteredLogs}
        columns={columns}
        keyExtractor={(row) => row.id}
        loading={loading}
        emptyMessage="No audit logs found"
      />

      {/* Load More */}
      {hasMore && (
        <div className="flex justify-center">
          <Button
            onClick={() => loadLogs(false, true)}
            variant="outline"
            className="border-gray-700 text-gray-400 hover:text-white"
          >
            Load More
          </Button>
        </div>
      )}

      {/* Compliance Info */}
      <Card className="border-blue-500/30 bg-blue-900/20">
        <CardContent className="p-6">
          <div className="flex items-center gap-4">
            <div className="rounded-lg bg-blue-500/20 p-3">
              <Shield className="h-6 w-6 text-blue-400" />
            </div>
            <div>
              <h3 className="font-semibold text-white">Compliance & Security</h3>
              <p className="text-sm text-blue-300/70">
                All admin actions are logged with timestamps, user IDs, and IP addresses. Logs are
                retained for compliance purposes and can be exported for audits.
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { useEffect, useState, useCallback } from "react"
import { useAuth } from "@/lib/auth-context"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { TimeSeriesChart } from "@/components/admin/charts"
import { AlertCircle, RefreshCw, ExternalLink, Bug, AlertTriangle } from "lucide-react"
import { logger } from "@/lib/logger"

interface ErrorEvent {
  timestamp: string
  errorType?: string
  errorMessage?: string
  page?: string
  userId?: string
}

export default function ErrorsPage() {
  const { firebaseUser } = useAuth()
  const [errors, setErrors] = useState<ErrorEvent[]>([])
  const [errorStats, setErrorStats] = useState<{
    total: number
    byType: Record<string, number>
    trend: Array<{ date: string; count: number }>
  } | null>(null)
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)
  const [timeRange, setTimeRange] = useState("7d")

  const loadErrors = useCallback(async (showRefreshing = false) => {
    if (!firebaseUser) return

    if (showRefreshing) setRefreshing(true)

    try {
      const token = await firebaseUser.getIdToken()
      const response = await fetch(`/api/admin/analytics?timeRange=${timeRange}`, {
        headers: { Authorization: `Bearer ${token}` },
      })

      if (response.ok) {
        const data = await response.json()
        if (data.success && data.metrics) {
          setErrors(data.metrics.errors.recent || [])

          // Group errors by date for trend
          const errorsByDate: Record<string, number> = {}
          data.metrics.errors.recent.forEach((err: ErrorEvent) => {
            if (err.timestamp) {
              const date = new Date(err.timestamp).toISOString().split("T")[0]
              errorsByDate[date] = (errorsByDate[date] || 0) + 1
            }
          })

          // Group errors by type
          const errorsByType: Record<string, number> = {}
          data.metrics.errors.recent.forEach((err: ErrorEvent) => {
            const type = err.errorType || "Unknown"
            errorsByType[type] = (errorsByType[type] || 0) + 1
          })

          setErrorStats({
            total: data.metrics.errors.total,
            byType: errorsByType,
            trend: Object.entries(errorsByDate)
              .map(([date, count]) => ({ date, count }))
              .sort((a, b) => a.date.localeCompare(b.date)),
          })
        }
      }
    } catch (error) {
      logger.error("Error loading admin errors", { error, timeRange })
    } finally {
      setLoading(false)
      setRefreshing(false)
    }
  }, [firebaseUser, timeRange])

  useEffect(() => {
    loadErrors()
  }, [loadErrors])

  const getErrorSeverity = (errorType?: string): "critical" | "warning" | "info" => {
    if (!errorType) return "info"
    const lower = errorType.toLowerCase()
    if (lower.includes("critical") || lower.includes("fatal") || lower.includes("crash")) {
      return "critical"
    }
    if (lower.includes("warning") || lower.includes("warn")) {
      return "warning"
    }
    return "info"
  }

  const getSeverityColor = (severity: "critical" | "warning" | "info") => {
    switch (severity) {
      case "critical":
        return "bg-red-600/20 text-red-400 border-red-600/30"
      case "warning":
        return "bg-yellow-600/20 text-yellow-400 border-yellow-600/30"
      default:
        return "bg-gray-600/20 text-gray-400 border-gray-600/30"
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#00d9ff]"></div>
      </div>
    )
  }

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-heading font-bold text-white">Error Monitoring</h1>
          <p className="text-gray-400 mt-1">Track and analyze application errors</p>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex gap-1 bg-gray-900 rounded-lg p-1">
            {["7d", "30d", "90d", "all"].map((range) => (
              <Button
                key={range}
                size="sm"
                variant={timeRange === range ? "default" : "ghost"}
                onClick={() => setTimeRange(range)}
                className={
                  timeRange === range
                    ? "bg-[#00d9ff] text-black hover:bg-[#00d9ff]/80"
                    : "text-gray-400 hover:text-white hover:bg-gray-800"
                }
              >
                {range === "all" ? "All" : range.toUpperCase()}
              </Button>
            ))}
          </div>

          <Button
            onClick={() => loadErrors(true)}
            disabled={refreshing}
            variant="outline"
            size="sm"
            className="border-gray-700 text-gray-400 hover:text-white"
          >
            <RefreshCw className={`h-4 w-4 mr-2 ${refreshing ? "animate-spin" : ""}`} />
            Refresh
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <Card className="bg-gray-900/50 border-gray-800">
          <CardContent className="p-6">
            <div className="flex items-center gap-3">
              <div className="p-3 bg-red-500/20 rounded-lg">
                <AlertCircle className="h-6 w-6 text-red-400" />
              </div>
              <div>
                <p className="text-3xl font-bold text-white">{errorStats?.total || 0}</p>
                <p className="text-sm text-gray-400">Total Errors</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-gray-900/50 border-gray-800">
          <CardContent className="p-6">
            <div className="flex items-center gap-3">
              <div className="p-3 bg-yellow-500/20 rounded-lg">
                <AlertTriangle className="h-6 w-6 text-yellow-400" />
              </div>
              <div>
                <p className="text-3xl font-bold text-white">
                  {Object.keys(errorStats?.byType || {}).length}
                </p>
                <p className="text-sm text-gray-400">Error Types</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-gray-900/50 border-gray-800 md:col-span-2">
          <CardContent className="p-6">
            <p className="text-sm text-gray-400 mb-3">Errors by Type</p>
            <div className="flex flex-wrap gap-2">
              {Object.entries(errorStats?.byType || {})
                .sort(([, a], [, b]) => b - a)
                .slice(0, 6)
                .map(([type, count]) => (
                  <Badge
                    key={type}
                    className={getSeverityColor(getErrorSeverity(type))}
                  >
                    {type}: {count}
                  </Badge>
                ))}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Error Trend */}
      {errorStats?.trend && errorStats.trend.length > 0 && (
        <TimeSeriesChart
          title="Error Trend"
          subtitle="Errors over time"
          data={errorStats.trend}
          series={[{ key: "count", name: "Errors", color: "#EF4444" }]}
          icon={Bug}
        />
      )}

      {/* Sentry Integration CTA */}
      <Card className="bg-purple-900/20 border-purple-500/30">
        <CardContent className="p-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-purple-500/20 rounded-lg">
                <Bug className="h-6 w-6 text-purple-400" />
              </div>
              <div>
                <h3 className="text-white font-semibold">Enhanced Error Tracking</h3>
                <p className="text-purple-300/70 text-sm">
                  Connect Sentry for stack traces, source maps, and release tracking
                </p>
              </div>
            </div>
            <div className="flex items-center gap-2 text-purple-400 text-sm">
              <span>Set <code className="bg-purple-900/30 px-1 rounded">SENTRY_DSN</code> to enable</span>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Error List */}
      <Card className="bg-gray-900/50 border-gray-800">
        <CardHeader>
          <CardTitle className="text-white flex items-center gap-2">
            <AlertCircle className="h-5 w-5 text-red-400" />
            Recent Errors
          </CardTitle>
        </CardHeader>
        <CardContent>
          {errors.length === 0 ? (
            <div className="text-center py-8">
              <AlertCircle className="h-12 w-12 text-green-400 mx-auto mb-4" />
              <p className="text-green-400 font-medium">No errors recorded</p>
              <p className="text-gray-500 text-sm mt-1">Your application is running smoothly</p>
            </div>
          ) : (
            <div className="space-y-3 max-h-[500px] overflow-y-auto">
              {errors.map((error, index) => {
                const severity = getErrorSeverity(error.errorType)
                return (
                  <div
                    key={index}
                    className="bg-gray-800/50 border border-gray-700 p-4 rounded-lg hover:border-gray-600 transition-colors"
                  >
                    <div className="flex items-start justify-between mb-2">
                      <div className="flex items-center gap-2">
                        <Badge className={getSeverityColor(severity)}>
                          {error.errorType || "Error"}
                        </Badge>
                        {error.page && (
                          <span className="text-xs text-gray-500">
                            on {error.page}
                          </span>
                        )}
                      </div>
                      <span className="text-xs text-gray-500">
                        {new Date(error.timestamp).toLocaleString()}
                      </span>
                    </div>

                    <p className="text-sm text-gray-300 font-mono break-all">
                      {error.errorMessage || "No message available"}
                    </p>

                    {error.userId && (
                      <p className="text-xs text-gray-500 mt-2">
                        User: {error.userId.substring(0, 12)}...
                      </p>
                    )}
                  </div>
                )
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { useEffect, useState, useCallback } from "react"
import { useAuth } from "@/lib/auth-context"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { FunnelChart, TimeSeriesChart, CohortHeatmap } from "@/components/admin/charts"
import { TrendingUp, RefreshCw, AlertCircle, Users } from "lucide-react"
import { logger } from "@/lib/logger"

interface FunnelData {
  stages: Array<{ name: string; value: number; color?: string }>
  conversionRates: {
    visitToSignup: number
    signupToSession: number
    sessionToComplete: number
    completeToSubscribe: number
    overallConversion: number
  }
  trend?: Array<{ date: string; signups: number; sessions: number; completed: number }>
}

interface CohortData {
  cohort: string
  size: number
  retention: number[]
}

export default function FunnelPage() {
  const { firebaseUser } = useAuth()
  const [funnel, setFunnel] = useState<FunnelData | null>(null)
  const [cohorts, setCohorts] = useState<CohortData[]>([])
  const [periodLabels, setPeriodLabels] = useState<string[]>([])
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)
  const [timeRange, setTimeRange] = useState("30d")
  const [cohortType, setCohortType] = useState<"weekly" | "monthly">("monthly")

  const loadData = useCallback(async (showRefreshing = false) => {
    if (!firebaseUser) return

    if (showRefreshing) setRefreshing(true)

    try {
      const token = await firebaseUser.getIdToken()
      const headers = { Authorization: `Bearer ${token}` }

      const [funnelRes, cohortRes] = await Promise.all([
        fetch(`/api/admin/funnel?timeRange=${timeRange}`, { headers }),
        fetch(`/api/admin/cohorts?type=${cohortType}&cohorts=6`, { headers }),
      ])

      if (funnelRes.ok) {
        const funnelData = await funnelRes.json()
        if (funnelData.success) {
          setFunnel(funnelData.funnel)
        }
      }

      if (cohortRes.ok) {
        const cohortData = await cohortRes.json()
        if (cohortData.success) {
          setCohorts(cohortData.data)
          setPeriodLabels(cohortData.summary?.periodLabels || [])
        }
      }
    } catch (error) {
      logger.error("Error loading funnel data", { error, timeRange, cohortType })
    } finally {
      setLoading(false)
      setRefreshing(false)
    }
  }, [firebaseUser, timeRange, cohortType])

  useEffect(() => {
    loadData()
  }, [loadData])

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#00d9ff]"></div>
      </div>
    )
  }

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-heading font-bold text-white">Conversion Funnel</h1>
          <p className="text-gray-400 mt-1">User journey analysis and retention cohorts</p>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex gap-1 bg-gray-900 rounded-lg p-1">
            {["7d", "30d", "90d", "all"].map((range) => (
              <Button
                key={range}
                size="sm"
                variant={timeRange === range ? "default" : "ghost"}
                onClick={() => setTimeRange(range)}
                className={
                  timeRange === range
                    ? "bg-[#00d9ff] text-black hover:bg-[#00d9ff]/80"
                    : "text-gray-400 hover:text-white hover:bg-gray-800"
                }
              >
                {range === "all" ? "All" : range.toUpperCase()}
              </Button>
            ))}
          </div>

          <Button
            onClick={() => loadData(true)}
            disabled={refreshing}
            variant="outline"
            size="sm"
            className="border-gray-700 text-gray-400 hover:text-white"
          >
            <RefreshCw className={`h-4 w-4 mr-2 ${refreshing ? "animate-spin" : ""}`} />
            Refresh
          </Button>
        </div>
      </div>

      {/* Main Funnel */}
      {funnel ? (
        <FunnelChart
          title="User Conversion Funnel"
          subtitle={`${timeRange.toUpperCase()} period`}
          stages={funnel.stages}
          icon={TrendingUp}
        />
      ) : (
        <Card className="bg-gray-900/50 border-gray-800">
          <CardContent className="p-8 text-center">
            <AlertCircle className="h-12 w-12 text-gray-500 mx-auto mb-4" />
            <p className="text-gray-400">No funnel data available</p>
          </CardContent>
        </Card>
      )}

      {/* Conversion Rates */}
      {funnel && (
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
          {[
            { label: "Visit → Signup", value: funnel.conversionRates.visitToSignup },
            { label: "Signup → Session", value: funnel.conversionRates.signupToSession },
            { label: "Session → Complete", value: funnel.conversionRates.sessionToComplete },
            { label: "Complete → Subscribe", value: funnel.conversionRates.completeToSubscribe },
            { label: "Overall", value: funnel.conversionRates.overallConversion, highlight: true },
          ].map((rate) => (
            <Card
              key={rate.label}
              className={`border-gray-800 ${rate.highlight ? "bg-[#00d9ff]/10 border-[#00d9ff]/30" : "bg-gray-900/50"}`}
            >
              <CardContent className="p-4 text-center">
                <div className={`text-2xl font-bold ${rate.highlight ? "text-[#00d9ff]" : "text-white"}`}>
                  {rate.value.toFixed(1)}%
                </div>
                <p className="text-xs text-gray-400 mt-1">{rate.label}</p>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Funnel Trend */}
      {funnel?.trend && funnel.trend.length > 0 && (
        <TimeSeriesChart
          title="Funnel Trend"
          subtitle="Daily signups, sessions, and completions"
          data={funnel.trend}
          series={[
            { key: "signups", name: "Signups", color: "#00d9ff" },
            { key: "sessions", name: "Sessions", color: "#FBBF24" },
            { key: "completed", name: "Completed", color: "#00ff88" },
          ]}
          icon={TrendingUp}
        />
      )}

      {/* Cohort Selector */}
      <div className="flex items-center gap-4">
        <h2 className="text-xl font-bold text-white">Retention Cohorts</h2>
        <div className="flex gap-1 bg-gray-900 rounded-lg p-1">
          {(["weekly", "monthly"] as const).map((type) => (
            <Button
              key={type}
              size="sm"
              variant={cohortType === type ? "default" : "ghost"}
              onClick={() => setCohortType(type)}
              className={
                cohortType === type
                  ? "bg-[#00d9ff] text-black hover:bg-[#00d9ff]/80"
                  : "text-gray-400 hover:text-white hover:bg-gray-800"
              }
            >
              {type.charAt(0).toUpperCase() + type.slice(1)}
            </Button>
          ))}
        </div>
      </div>

      {/* Cohort Heatmap */}
      {cohorts.length > 0 ? (
        <CohortHeatmap
          title="User Retention"
          subtitle={`${cohortType === "weekly" ? "Weekly" : "Monthly"} cohorts`}
          data={cohorts}
          periodLabels={periodLabels}
          icon={Users}
        />
      ) : (
        <Card className="bg-gray-900/50 border-gray-800">
          <CardContent className="p-8 text-center">
            <AlertCircle className="h-12 w-12 text-gray-500 mx-auto mb-4" />
            <p className="text-gray-400">No cohort data available</p>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

"use client"

import { useEffect, useState, useCallback } from "react"
import { useAuth } from "@/lib/auth-context"
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { MetricCard } from "@/components/admin/charts"
import {
  Shield,
  AlertTriangle,
  Database,
  RefreshCw,
  Loader2,
  AlertCircle,
  Clock,
  Ban,
  DollarSign,
  Activity,
  CheckCircle,
  XCircle,
  Zap,
} from "lucide-react"

interface RateLimitData {
  totalRequests: number
  blockedRequests: number
  blockRate: number
  uniqueIdentifiers: number
  byEndpoint: Record<string, { total: number; blocked: number; blockRate: number }>
  topOffenders: Array<{
    identifier: string
    blockedCount: number
    lastBlocked: string
    endpoints: string[]
  }>
  hourlyTrend: Array<{ hour: string; total: number; blocked: number }>
  alerts: {
    highBlockRate: boolean
    ddosIndicator: boolean
    bruteForceIndicator: boolean
  }
}

interface CostAnomalyData {
  stats: {
    total: number
    unacknowledged: number
    byType: Record<string, number>
    bySeverity: { warning: number; critical: number }
    last24Hours: number
    estimatedLoss: number
  }
  recentAnomalies: Array<{
    id: string
    type: string
    severity: string
    description: string
    cost: number
    threshold: number
    context: Record<string, any>
    timestamp: string
    acknowledged: boolean
  }>
}

interface QueryPerfData {
  totalQueries: number
  averageDurationMs: number
  slowQueries: number
  slowQueryRate: number
  costlyQueries: number
  byCollection: Record<string, {
    count: number
    avgDurationMs: number
    avgDocumentCount: number
    slowCount: number
  }>
  byOperation: Record<string, { count: number; avgDurationMs: number }>
  slowestQueries: Array<{
    collection: string
    operation: string
    durationMs: number
    documentCount: number
    filters?: string[]
    timestamp: string
  }>
  recommendations: string[]
}

export default function InfrastructurePage() {
  const { firebaseUser } = useAuth()
  const [rateLimitData, setRateLimitData] = useState<RateLimitData | null>(null)
  const [costAnomalyData, setCostAnomalyData] = useState<CostAnomalyData | null>(null)
  const [queryPerfData, setQueryPerfData] = useState<QueryPerfData | null>(null)
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [acknowledging, setAcknowledging] = useState<string | null>(null)

  const loadData = useCallback(async () => {
    if (!firebaseUser) return

    setRefreshing(true)
    setError(null)

    try {
      const token = await firebaseUser.getIdToken()

      const [rateRes, costRes, queryRes] = await Promise.all([
        fetch("/api/admin/rate-limits?hours=24", {
          headers: { Authorization: `Bearer ${token}` },
        }),
        fetch("/api/admin/cost-anomalies", {
          headers: { Authorization: `Bearer ${token}` },
        }),
        fetch("/api/admin/query-performance?hours=24", {
          headers: { Authorization: `Bearer ${token}` },
        }),
      ])

      const [rate, cost, query] = await Promise.all([
        rateRes.json(),
        costRes.json(),
        queryRes.json(),
      ])

      if (rate.success) setRateLimitData(rate.data)
      if (cost.success) setCostAnomalyData(cost.data)
      if (query.success) setQueryPerfData(query.data)
    } catch (error) {
      setError(error instanceof Error ? error.message : "Failed to load data")
    } finally {
      setLoading(false)
      setRefreshing(false)
    }
  }, [firebaseUser])

  const acknowledgeAnomaly = async (anomalyId: string) => {
    if (!firebaseUser) return

    setAcknowledging(anomalyId)
    try {
      const token = await firebaseUser.getIdToken()
      await fetch("/api/admin/cost-anomalies", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ action: "acknowledge", anomalyId }),
      })
      await loadData()
    } catch (error) {
      console.error("Failed to acknowledge anomaly:", error)
    } finally {
      setAcknowledging(null)
    }
  }

  useEffect(() => {
    loadData()
  }, [loadData])

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Loader2 className="h-12 w-12 animate-spin text-[#00d9ff]" />
      </div>
    )
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4">
        <AlertCircle className="h-12 w-12 text-red-400" />
        <p className="text-red-400">{error}</p>
        <Button onClick={() => loadData()} variant="outline">
          Retry
        </Button>
      </div>
    )
  }

  const hasActiveAlerts =
    rateLimitData?.alerts.highBlockRate ||
    rateLimitData?.alerts.ddosIndicator ||
    rateLimitData?.alerts.bruteForceIndicator ||
    (costAnomalyData?.stats.unacknowledged || 0) > 0

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-heading font-bold text-white">Infrastructure Health</h1>
          <p className="text-gray-400 mt-1">Rate limits, cost monitoring, and database performance</p>
        </div>

        <div className="flex items-center gap-3">
          {hasActiveAlerts && (
            <Badge variant="destructive" className="animate-pulse">
              <AlertTriangle className="h-3 w-3 mr-1" />
              Active Alerts
            </Badge>
          )}
          <Button
            onClick={loadData}
            variant="outline"
            size="sm"
            disabled={refreshing}
            className="border-gray-700 text-gray-400 hover:text-white"
          >
            {refreshing ? (
              <Loader2 className="h-4 w-4 mr-2 animate-spin" />
            ) : (
              <RefreshCw className="h-4 w-4 mr-2" />
            )}
            Refresh
          </Button>
        </div>
      </div>

      {/* Rate Limiting Section */}
      <div className="space-y-6">
        <h2 className="text-xl font-semibold text-white flex items-center gap-2">
          <Shield className="h-5 w-5 text-blue-400" />
          Rate Limiting (Last 24h)
        </h2>

        {/* Alerts */}
        {(rateLimitData?.alerts.highBlockRate ||
          rateLimitData?.alerts.ddosIndicator ||
          rateLimitData?.alerts.bruteForceIndicator) && (
          <Card className="bg-red-900/20 border-red-500/30">
            <CardContent className="p-4">
              <div className="flex items-center gap-3">
                <AlertTriangle className="h-5 w-5 text-red-400" />
                <div>
                  <p className="text-red-400 font-medium">Security Alerts Detected</p>
                  <div className="flex gap-2 mt-1">
                    {rateLimitData?.alerts.highBlockRate && (
                      <Badge variant="destructive">High Block Rate</Badge>
                    )}
                    {rateLimitData?.alerts.ddosIndicator && (
                      <Badge variant="destructive">Possible DDoS</Badge>
                    )}
                    {rateLimitData?.alerts.bruteForceIndicator && (
                      <Badge variant="destructive">Brute Force Attempt</Badge>
                    )}
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <MetricCard
            title="Total Requests"
            value={rateLimitData?.totalRequests.toLocaleString() || 0}
            subtitle="Last 24 hours"
            icon={Activity}
          />
          <MetricCard
            title="Blocked Requests"
            value={rateLimitData?.blockedRequests.toLocaleString() || 0}
            subtitle={`${(rateLimitData?.blockRate || 0).toFixed(2)}% block rate`}
            icon={Ban}
            valueColor={(rateLimitData?.blockRate || 0) > 5 ? "text-red-400" : "text-green-400"}
          />
          <MetricCard
            title="Unique IPs"
            value={rateLimitData?.uniqueIdentifiers || 0}
            subtitle="Distinct clients"
            icon={Shield}
          />
          <MetricCard
            title="Top Offenders"
            value={rateLimitData?.topOffenders.length || 0}
            subtitle="IPs with blocks"
            icon={AlertTriangle}
            valueColor={(rateLimitData?.topOffenders.length || 0) > 10 ? "text-yellow-400" : "text-gray-300"}
          />
        </div>

        {/* Rate Limit by Endpoint */}
        <Card className="bg-gray-900/50 border-gray-800">
          <CardHeader>
            <CardTitle className="text-white">By Endpoint</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
              {Object.entries(rateLimitData?.byEndpoint || {}).map(([endpoint, stats]) => (
                <div key={endpoint} className="bg-gray-800/50 rounded-lg p-3">
                  <p className="text-xs text-gray-400 truncate">{endpoint}</p>
                  <p className="text-lg font-bold text-white">{stats.total.toLocaleString()}</p>
                  <p className={`text-xs ${stats.blockRate > 5 ? 'text-red-400' : 'text-gray-500'}`}>
                    {stats.blocked} blocked ({stats.blockRate.toFixed(1)}%)
                  </p>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Top Offenders */}
        {rateLimitData?.topOffenders && rateLimitData.topOffenders.length > 0 && (
          <Card className="bg-gray-900/50 border-gray-800">
            <CardHeader>
              <CardTitle className="text-white">Top Offenders</CardTitle>
              <CardDescription>IPs with the most blocked requests</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-gray-800 text-gray-400">
                      <th className="text-left py-2 px-3">IP Address</th>
                      <th className="text-right py-2 px-3">Blocked</th>
                      <th className="text-left py-2 px-3">Endpoints</th>
                      <th className="text-left py-2 px-3">Last Blocked</th>
                    </tr>
                  </thead>
                  <tbody>
                    {rateLimitData.topOffenders.slice(0, 10).map((offender) => (
                      <tr key={offender.identifier} className="border-b border-gray-800/50 hover:bg-gray-800/30">
                        <td className="py-2 px-3 font-mono text-gray-300">{offender.identifier}</td>
                        <td className="py-2 px-3 text-right text-red-400 font-bold">{offender.blockedCount}</td>
                        <td className="py-2 px-3">
                          <div className="flex flex-wrap gap-1">
                            {offender.endpoints.slice(0, 3).map((ep) => (
                              <Badge key={ep} variant="outline" className="text-xs">{ep}</Badge>
                            ))}
                            {offender.endpoints.length > 3 && (
                              <Badge variant="outline" className="text-xs">+{offender.endpoints.length - 3}</Badge>
                            )}
                          </div>
                        </td>
                        <td className="py-2 px-3 text-gray-500 text-xs">
                          {new Date(offender.lastBlocked).toLocaleString()}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </CardContent>
          </Card>
        )}
      </div>

      {/* Cost Anomalies Section */}
      <div className="space-y-6">
        <h2 className="text-xl font-semibold text-white flex items-center gap-2">
          <DollarSign className="h-5 w-5 text-yellow-400" />
          Cost Anomalies
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <MetricCard
            title="Total Anomalies"
            value={costAnomalyData?.stats.total || 0}
            subtitle="All time"
            icon={AlertTriangle}
          />
          <MetricCard
            title="Unacknowledged"
            value={costAnomalyData?.stats.unacknowledged || 0}
            subtitle="Needs review"
            icon={AlertCircle}
            valueColor={(costAnomalyData?.stats.unacknowledged || 0) > 0 ? "text-red-400" : "text-green-400"}
          />
          <MetricCard
            title="Last 24 Hours"
            value={costAnomalyData?.stats.last24Hours || 0}
            subtitle="Recent anomalies"
            icon={Clock}
          />
          <MetricCard
            title="Est. Excess Cost"
            value={`$${(costAnomalyData?.stats.estimatedLoss || 0).toFixed(2)}`}
            subtitle="Above thresholds"
            icon={DollarSign}
            valueColor="text-red-400"
          />
        </div>

        {/* Severity Breakdown */}
        <div className="grid grid-cols-2 gap-4">
          <Card className="bg-yellow-900/20 border-yellow-500/30">
            <CardContent className="p-4 flex items-center justify-between">
              <div>
                <p className="text-yellow-400 font-medium">Warnings</p>
                <p className="text-3xl font-bold text-yellow-400">{costAnomalyData?.stats.bySeverity.warning || 0}</p>
              </div>
              <AlertTriangle className="h-10 w-10 text-yellow-500/50" />
            </CardContent>
          </Card>
          <Card className="bg-red-900/20 border-red-500/30">
            <CardContent className="p-4 flex items-center justify-between">
              <div>
                <p className="text-red-400 font-medium">Critical</p>
                <p className="text-3xl font-bold text-red-400">{costAnomalyData?.stats.bySeverity.critical || 0}</p>
              </div>
              <XCircle className="h-10 w-10 text-red-500/50" />
            </CardContent>
          </Card>
        </div>

        {/* Recent Anomalies */}
        <Card className="bg-gray-900/50 border-gray-800">
          <CardHeader>
            <CardTitle className="text-white">Recent Anomalies</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {costAnomalyData?.recentAnomalies.slice(0, 10).map((anomaly) => (
                <div
                  key={anomaly.id}
                  className={`p-3 rounded-lg border ${
                    anomaly.severity === 'critical'
                      ? 'bg-red-900/20 border-red-500/30'
                      : 'bg-yellow-900/20 border-yellow-500/30'
                  }`}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <Badge variant={anomaly.severity === 'critical' ? 'destructive' : 'default'}>
                          {anomaly.severity}
                        </Badge>
                        <Badge variant="outline">{anomaly.type}</Badge>
                        {anomaly.acknowledged && (
                          <Badge variant="outline" className="text-green-400 border-green-500">
                            <CheckCircle className="h-3 w-3 mr-1" />
                            Acknowledged
                          </Badge>
                        )}
                      </div>
                      <p className="text-gray-300 text-sm">{anomaly.description}</p>
                      <p className="text-xs text-gray-500 mt-1">
                        Cost: ${anomaly.cost.toFixed(4)} (threshold: ${anomaly.threshold.toFixed(2)})
                        {' • '}
                        {new Date(anomaly.timestamp).toLocaleString()}
                      </p>
                    </div>
                    {!anomaly.acknowledged && (
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => acknowledgeAnomaly(anomaly.id)}
                        disabled={acknowledging === anomaly.id}
                      >
                        {acknowledging === anomaly.id ? (
                          <Loader2 className="h-4 w-4 animate-spin" />
                        ) : (
                          'Acknowledge'
                        )}
                      </Button>
                    )}
                  </div>
                </div>
              ))}
              {(!costAnomalyData?.recentAnomalies || costAnomalyData.recentAnomalies.length === 0) && (
                <p className="text-center text-gray-500 py-8">No anomalies detected. System is healthy!</p>
              )}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Query Performance Section */}
      <div className="space-y-6">
        <h2 className="text-xl font-semibold text-white flex items-center gap-2">
          <Database className="h-5 w-5 text-green-400" />
          Database Performance (Last 24h)
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <MetricCard
            title="Total Queries"
            value={queryPerfData?.totalQueries.toLocaleString() || 0}
            subtitle="Tracked queries"
            icon={Database}
          />
          <MetricCard
            title="Avg Duration"
            value={`${(queryPerfData?.averageDurationMs || 0).toFixed(0)}ms`}
            subtitle="Per query"
            icon={Clock}
            valueColor={(queryPerfData?.averageDurationMs || 0) > 200 ? "text-yellow-400" : "text-green-400"}
          />
          <MetricCard
            title="Slow Queries"
            value={queryPerfData?.slowQueries || 0}
            subtitle={`${(queryPerfData?.slowQueryRate || 0).toFixed(1)}% of total`}
            icon={Zap}
            valueColor={(queryPerfData?.slowQueryRate || 0) > 5 ? "text-red-400" : "text-green-400"}
          />
          <MetricCard
            title="Costly Queries"
            value={queryPerfData?.costlyQueries || 0}
            subtitle=">100 docs per query"
            icon={AlertTriangle}
          />
        </div>

        {/* Recommendations */}
        {queryPerfData?.recommendations && queryPerfData.recommendations.length > 0 && (
          <Card className="bg-blue-900/20 border-blue-500/30">
            <CardHeader>
              <CardTitle className="text-white flex items-center gap-2">
                <Zap className="h-5 w-5 text-blue-400" />
                Optimization Recommendations
              </CardTitle>
            </CardHeader>
            <CardContent>
              <ul className="space-y-2">
                {queryPerfData.recommendations.map((rec, idx) => (
                  <li key={idx} className="flex items-start gap-2 text-blue-300 text-sm">
                    <span className="text-blue-400 mt-1">•</span>
                    {rec}
                  </li>
                ))}
              </ul>
            </CardContent>
          </Card>
        )}

        {/* By Collection */}
        <Card className="bg-gray-900/50 border-gray-800">
          <CardHeader>
            <CardTitle className="text-white">By Collection</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-gray-800 text-gray-400">
                    <th className="text-left py-2 px-3">Collection</th>
                    <th className="text-right py-2 px-3">Queries</th>
                    <th className="text-right py-2 px-3">Avg Time</th>
                    <th className="text-right py-2 px-3">Avg Docs</th>
                    <th className="text-right py-2 px-3">Slow</th>
                  </tr>
                </thead>
                <tbody>
                  {Object.entries(queryPerfData?.byCollection || {}).map(([collection, stats]) => (
                    <tr key={collection} className="border-b border-gray-800/50 hover:bg-gray-800/30">
                      <td className="py-2 px-3 text-gray-300 font-mono">{collection}</td>
                      <td className="py-2 px-3 text-right text-white">{stats.count.toLocaleString()}</td>
                      <td className={`py-2 px-3 text-right ${stats.avgDurationMs > 500 ? 'text-yellow-400' : 'text-gray-300'}`}>
                        {stats.avgDurationMs.toFixed(0)}ms
                      </td>
                      <td className={`py-2 px-3 text-right ${stats.avgDocumentCount > 50 ? 'text-yellow-400' : 'text-gray-300'}`}>
                        {stats.avgDocumentCount.toFixed(0)}
                      </td>
                      <td className={`py-2 px-3 text-right ${stats.slowCount > 0 ? 'text-red-400' : 'text-gray-500'}`}>
                        {stats.slowCount}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </CardContent>
        </Card>

        {/* Slowest Queries */}
        {queryPerfData?.slowestQueries && queryPerfData.slowestQueries.length > 0 && (
          <Card className="bg-gray-900/50 border-gray-800">
            <CardHeader>
              <CardTitle className="text-white">Slowest Queries</CardTitle>
              <CardDescription>Queries taking more than 1 second</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {queryPerfData.slowestQueries.map((query, idx) => (
                  <div key={idx} className="p-3 bg-gray-800/30 rounded-lg">
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center gap-2">
                        <Badge variant="outline">{query.collection}</Badge>
                        <Badge variant="outline">{query.operation}</Badge>
                      </div>
                      <span className="text-red-400 font-mono">{query.durationMs}ms</span>
                    </div>
                    <div className="text-sm text-gray-400">
                      <span>{query.documentCount} documents</span>
                      {query.filters && query.filters.length > 0 && (
                        <span className="ml-2">• Filters: {query.filters.join(', ')}</span>
                      )}
                    </div>
                    <p className="text-xs text-gray-500 mt-1">
                      {new Date(query.timestamp).toLocaleString()}
                    </p>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  )
}

"use client"

import { useEffect, useState, useCallback } from "react"
import { useAuth } from "@/lib/auth-context"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import {
  MetricCard,
  TimeSeriesChart,
  FunnelChart,
  DistributionChart,
} from "@/components/admin/charts"
import {
  PageHeader,
  DashboardSkeleton,
} from "@/components/admin/shared"
import {
  Users,
  DollarSign,
  Terminal,
  TrendingUp,
  AlertCircle,
  Activity,
  RefreshCw,
  Crown,
  Zap,
  LayoutDashboard,
} from "lucide-react"
import { logger } from "@/lib/logger"

interface AnalyticsMetrics {
  users: {
    total: number
    byTier: {
      free: number
      pro: number
      enterprise: number
    }
  }
  sessions: {
    total: number
    completed: number
    inProgress: number
    avgPerformanceScore: number
    byType: Record<string, number>
    byDifficulty: Record<string, number>
  }
  revenue: {
    mrr: number
    arr: number
  }
  analytics: {
    totalEvents: number
    byEventType: Record<string, number>
    codeExecutions: {
      total: number
      passed: number
      passRate: number
    }
  }
  errors: {
    total: number
    recent: Array<{
      timestamp: string
      errorType?: string
      errorMessage?: string
    }>
  }
  timeSeries?: {
    users: Array<{ date: string; total: number; free: number; pro: number; enterprise: number }>
    sessions: Array<{ date: string; total: number; completed: number }>
    revenue: Array<{ date: string; mrr: number }>
  }
}

interface FunnelData {
  stages: Array<{ name: string; value: number; color?: string }>
  conversionRates: {
    visitToSignup: number
    signupToSession: number
    sessionToComplete: number
    completeToSubscribe: number
    overallConversion: number
  }
}

export default function AdminDashboard() {
  const { firebaseUser } = useAuth()
  const [metrics, setMetrics] = useState<AnalyticsMetrics | null>(null)
  const [funnel, setFunnel] = useState<FunnelData | null>(null)
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)
  const [timeRange, setTimeRange] = useState("7d")
  const [error, setError] = useState<string | null>(null)

  const loadMetrics = useCallback(async (showRefreshing = false) => {
    if (!firebaseUser) return

    if (showRefreshing) setRefreshing(true)
    setError(null)

    try {
      const token = await firebaseUser.getIdToken()
      const headers = { Authorization: `Bearer ${token}` }

      // Fetch analytics and funnel data in parallel
      const [analyticsRes, funnelRes] = await Promise.all([
        fetch(`/api/admin/analytics?timeRange=${timeRange}`, { headers }),
        fetch(`/api/admin/funnel?timeRange=${timeRange}`, { headers }),
      ])

      if (!analyticsRes.ok) {
        throw new Error("Failed to load analytics")
      }

      const analyticsData = await analyticsRes.json()
      if (analyticsData.success && analyticsData.metrics) {
        setMetrics(analyticsData.metrics)
      }

      if (funnelRes.ok) {
        const funnelData = await funnelRes.json()
        if (funnelData.success && funnelData.funnel) {
          setFunnel(funnelData.funnel)
        }
      }
    } catch (err) {
      logger.error("Error loading admin metrics", { error: err, timeRange })
      setError(err instanceof Error ? err.message : "Failed to load data")
    } finally {
      setLoading(false)
      setRefreshing(false)
    }
  }, [firebaseUser, timeRange])

  useEffect(() => {
    loadMetrics()
  }, [loadMetrics])

  const handleRefresh = () => loadMetrics(true)

  if (loading) {
    return <DashboardSkeleton />
  }

  if (error || !metrics) {
    return (
      <Card className="bg-red-900/20 border-red-500/30">
        <CardContent className="p-8 text-center">
          <AlertCircle className="h-12 w-12 text-red-400 mx-auto mb-4" />
          <p className="text-red-400 font-medium">{error || "Failed to load analytics data"}</p>
          <Button onClick={handleRefresh} className="mt-4" variant="outline">
            Try Again
          </Button>
        </CardContent>
      </Card>
    )
  }

  const conversionRate = metrics.users.total > 0
    ? ((metrics.users.byTier.pro / metrics.users.total) * 100).toFixed(1)
    : "0"

  const completionRate = metrics.sessions.total > 0
    ? ((metrics.sessions.completed / metrics.sessions.total) * 100).toFixed(1)
    : "0"

  // Prepare tier distribution data
  const tierDistribution = [
    { name: "Free", value: metrics.users.byTier.free, color: "#6B7280" },
    { name: "Pro", value: metrics.users.byTier.pro, color: "#FBBF24" },
    { name: "Enterprise", value: metrics.users.byTier.enterprise, color: "#A855F7" },
  ]

  // Prepare difficulty distribution
  const difficultyDistribution = Object.entries(metrics.sessions.byDifficulty).map(
    ([name, value]) => ({
      name: name.charAt(0).toUpperCase() + name.slice(1),
      value,
      color: name === "easy" ? "#00ff88" : name === "medium" ? "#FBBF24" : "#EF4444",
    })
  )

  return (
    <div className="space-y-8">
      {/* Header */}
      <PageHeader
        title="Dashboard Overview"
        subtitle="Real-time platform analytics and metrics"
        timeRange={timeRange}
        onTimeRangeChange={setTimeRange}
        onRefresh={handleRefresh}
        refreshing={refreshing}
      />

      {/* Key Metrics Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <MetricCard
          title="Total Users"
          value={metrics.users.total}
          subtitle={`${metrics.users.byTier.pro} Pro (${conversionRate}%)`}
          icon={Users}
          sparklineData={metrics.timeSeries?.users.slice(-7).map((u) => u.total)}
          sparklineColor="#00d9ff"
        />
        <MetricCard
          title="MRR"
          value={`$${metrics.revenue.mrr.toLocaleString()}`}
          subtitle={`ARR: $${metrics.revenue.arr.toLocaleString()}`}
          icon={DollarSign}
          valueColor="text-green-400"
          iconColor="text-green-400"
          sparklineData={metrics.timeSeries?.revenue.slice(-7).map((r) => r.mrr)}
          sparklineColor="#00ff88"
        />
        <MetricCard
          title="Sessions"
          value={metrics.sessions.total}
          subtitle={`${completionRate}% completion rate`}
          icon={Terminal}
          sparklineData={metrics.timeSeries?.sessions.slice(-7).map((s) => s.total)}
          sparklineColor="#FBBF24"
        />
        <MetricCard
          title="Avg Score"
          value={`${metrics.sessions.avgPerformanceScore}%`}
          subtitle="Across all sessions"
          icon={TrendingUp}
          valueColor="text-[#00d9ff]"
        />
      </div>

      {/* Charts Row 1 */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* User Growth Chart */}
        {metrics.timeSeries?.users && metrics.timeSeries.users.length > 0 && (
          <TimeSeriesChart
            title="User Growth"
            subtitle={timeRange.toUpperCase()}
            data={metrics.timeSeries.users}
            series={[
              { key: "free", name: "Free", color: "#6B7280" },
              { key: "pro", name: "Pro", color: "#FBBF24" },
              { key: "enterprise", name: "Enterprise", color: "#A855F7" },
            ]}
            stacked
            icon={Users}
          />
        )}

        {/* Revenue Chart */}
        {metrics.timeSeries?.revenue && metrics.timeSeries.revenue.length > 0 && (
          <TimeSeriesChart
            title="Revenue Trend"
            subtitle="MRR over time"
            data={metrics.timeSeries.revenue}
            series={[{ key: "mrr", name: "MRR", color: "#00ff88" }]}
            icon={DollarSign}
            valueFormatter={(v) => `$${v.toLocaleString()}`}
          />
        )}
      </div>

      {/* Charts Row 2 */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Conversion Funnel */}
        {funnel && (
          <div className="lg:col-span-2">
            <FunnelChart
              title="Conversion Funnel"
              subtitle={timeRange.toUpperCase()}
              stages={funnel.stages}
              icon={TrendingUp}
            />
          </div>
        )}

        {/* Tier Distribution */}
        <DistributionChart
          title="User Tiers"
          data={tierDistribution}
          type="pie"
          icon={Crown}
          height={280}
        />
      </div>

      {/* Charts Row 3 */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Sessions Chart */}
        {metrics.timeSeries?.sessions && metrics.timeSeries.sessions.length > 0 && (
          <div className="lg:col-span-2">
            <TimeSeriesChart
              title="Session Activity"
              subtitle="Sessions started vs completed"
              data={metrics.timeSeries.sessions}
              series={[
                { key: "total", name: "Started", color: "#00d9ff" },
                { key: "completed", name: "Completed", color: "#00ff88" },
              ]}
              icon={Activity}
            />
          </div>
        )}

        {/* Difficulty Distribution */}
        {difficultyDistribution.length > 0 && (
          <DistributionChart
            title="Session Difficulty"
            data={difficultyDistribution}
            type="bar"
            icon={Zap}
            height={280}
          />
        )}
      </div>

      {/* Code Execution Stats */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card className="bg-gray-900/50 border-gray-800">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <Zap className="h-5 w-5 text-[#00d9ff]" />
              Code Executions
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <div className="flex justify-between items-center">
                <span className="text-gray-400">Total Executions</span>
                <span className="text-2xl font-bold text-white">
                  {metrics.analytics.codeExecutions.total.toLocaleString()}
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-gray-400">Passed</span>
                <span className="text-xl font-semibold text-green-400">
                  {metrics.analytics.codeExecutions.passed.toLocaleString()}
                </span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-gray-400">Pass Rate</span>
                <div className="flex items-center gap-2">
                  <div className="w-24 h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div
                      className="h-full bg-green-400 rounded-full"
                      style={{ width: `${metrics.analytics.codeExecutions.passRate}%` }}
                    />
                  </div>
                  <span className="text-[#00d9ff] font-semibold">
                    {metrics.analytics.codeExecutions.passRate}%
                  </span>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Event Types */}
        <Card className="bg-gray-900/50 border-gray-800 lg:col-span-2">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <Activity className="h-5 w-5 text-[#00d9ff]" />
              Analytics Events ({metrics.analytics.totalEvents.toLocaleString()} total)
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {Object.entries(metrics.analytics.byEventType)
                .sort(([, a], [, b]) => b - a)
                .slice(0, 8)
                .map(([eventType, count]) => (
                  <div key={eventType} className="bg-gray-800/50 p-3 rounded-lg">
                    <div className="text-xl font-bold text-white">{count.toLocaleString()}</div>
                    <p className="text-xs text-gray-400 capitalize truncate">
                      {eventType.replace(/_/g, " ")}
                    </p>
                  </div>
                ))}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Recent Errors */}
      {metrics.errors.total > 0 && (
        <Card className="bg-gray-900/50 border-gray-800">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <AlertCircle className="h-5 w-5 text-red-400" />
              Recent Errors ({metrics.errors.total})
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3 max-h-64 overflow-y-auto">
              {metrics.errors.recent.slice(0, 5).map((error, index) => (
                <div
                  key={index}
                  className="bg-red-900/10 border border-red-500/20 p-3 rounded-lg"
                >
                  <div className="flex items-start justify-between">
                    <Badge className="bg-red-600/20 text-red-400 border-red-600/30">
                      {error.errorType || "Error"}
                    </Badge>
                    <span className="text-xs text-gray-500">
                      {new Date(error.timestamp).toLocaleString()}
                    </span>
                  </div>
                  <p className="text-sm text-red-300 mt-2 line-clamp-2">
                    {error.errorMessage || "Unknown error"}
                  </p>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

"use client"

import { useState, useEffect, useCallback } from "react"
import { useAuth } from "@/lib/auth-context"
import {
  Clock,
  Zap,
  AlertCircle,
  CheckCircle,
  XCircle,
  MessageSquare,
  RefreshCw,
  Filter,
  User,
  Globe,
  Calendar,
  Loader2,
} from "lucide-react"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { cn } from "@/lib/utils"

type RateLimitType = "rate_limit" | "budget_exceeded" | "concurrent_limit" | "session_limit"

interface RateLimitFeedback {
  id: string
  type: RateLimitType
  code: string | null
  systemMessage: string
  userMessage: string | null
  feedbackTimestamp: string
  endpoint: string | null
  tier: string | null
  userId: string | null
  userEmail: string | null
  clientIp: string
  userAgent: string | null
  status: "pending" | "reviewed" | "resolved" | "dismissed"
  reviewedBy: string | null
  reviewedAt: string | null
  resolution: string | null
  notes: string | null
  createdAt: string
  updatedAt: string
}

interface FeedbackCounts {
  pending: number
  reviewed: number
  resolved: number
  dismissed: number
  total: number
}

const typeColors: Record<RateLimitType, string> = {
  rate_limit: "text-amber-500 bg-amber-500/10 border-amber-500/30",
  budget_exceeded: "text-red-500 bg-red-500/10 border-red-500/30",
  concurrent_limit: "text-blue-500 bg-blue-500/10 border-blue-500/30",
  session_limit: "text-purple-500 bg-purple-500/10 border-purple-500/30",
}

function getTypeIcon(type: RateLimitType) {
  switch (type) {
    case "rate_limit":
      return Clock
    case "budget_exceeded":
      return AlertCircle
    case "concurrent_limit":
      return Zap
    case "session_limit":
      return AlertCircle
    default:
      return AlertCircle
  }
}

const statusColors: Record<string, string> = {
  pending: "bg-yellow-500/10 text-yellow-500 border-yellow-500/30",
  reviewed: "bg-blue-500/10 text-blue-500 border-blue-500/30",
  resolved: "bg-green-500/10 text-green-500 border-green-500/30",
  dismissed: "bg-gray-500/10 text-gray-400 border-gray-500/30",
}

export default function RateLimitsPage() {
  const { firebaseUser } = useAuth()
  const [feedback, setFeedback] = useState<RateLimitFeedback[]>([])
  const [counts, setCounts] = useState<FeedbackCounts>({
    pending: 0,
    reviewed: 0,
    resolved: 0,
    dismissed: 0,
    total: 0,
  })
  const [loading, setLoading] = useState(true)
  const [statusFilter, setStatusFilter] = useState("pending")
  const [typeFilter, setTypeFilter] = useState<string | null>(null)
  const [selectedFeedback, setSelectedFeedback] = useState<RateLimitFeedback | null>(null)
  const [updating, setUpdating] = useState(false)

  const fetchFeedback = useCallback(async () => {
    if (!firebaseUser) return

    setLoading(true)
    try {
      const token = await firebaseUser.getIdToken()
      const params = new URLSearchParams({
        status: statusFilter,
        limit: "50",
      })
      if (typeFilter) {
        params.set("type", typeFilter)
      }

      const response = await fetch(`/api/rate-limit-feedback?${params}`, {
        headers: { Authorization: `Bearer ${token}` },
      })

      if (response.ok) {
        const data = await response.json()
        setFeedback(data.feedback)
        setCounts(data.counts)
      }
    } catch (error) {
      console.error("Failed to fetch feedback:", error)
    } finally {
      setLoading(false)
    }
  }, [firebaseUser, statusFilter, typeFilter])

  useEffect(() => {
    fetchFeedback()
  }, [fetchFeedback])

  const updateFeedbackStatus = async (
    feedbackId: string,
    status: string,
    resolution?: string,
    notes?: string
  ) => {
    if (!firebaseUser) return

    setUpdating(true)
    try {
      const token = await firebaseUser.getIdToken()
      const response = await fetch("/api/rate-limit-feedback", {
        method: "PATCH",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ feedbackId, status, resolution, notes }),
      })

      if (response.ok) {
        // Refresh the list
        await fetchFeedback()
        setSelectedFeedback(null)
      }
    } catch (error) {
      console.error("Failed to update feedback:", error)
    } finally {
      setUpdating(false)
    }
  }

  const formatDate = (dateStr: string | null) => {
    if (!dateStr) return "N/A"
    return new Date(dateStr).toLocaleString()
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-white">Rate Limit Feedback</h1>
          <p className="mt-1 text-sm text-gray-400">
            Review user reports of incorrect rate limiting
          </p>
        </div>
        <Button onClick={fetchFeedback} disabled={loading} variant="outline" className="gap-2">
          <RefreshCw className={cn("h-4 w-4", loading && "animate-spin")} />
          Refresh
        </Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 gap-4 md:grid-cols-5">
        {[
          { label: "Pending", value: counts.pending, color: "text-yellow-500" },
          { label: "Reviewed", value: counts.reviewed, color: "text-blue-500" },
          { label: "Resolved", value: counts.resolved, color: "text-green-500" },
          { label: "Dismissed", value: counts.dismissed, color: "text-gray-400" },
          { label: "Total", value: counts.total, color: "text-white" },
        ].map((stat) => (
          <div key={stat.label} className="rounded-lg border border-gray-800 bg-gray-900/50 p-4">
            <p className="text-sm text-gray-400">{stat.label}</p>
            <p className={cn("mt-1 text-2xl font-bold", stat.color)}>{stat.value}</p>
          </div>
        ))}
      </div>

      {/* Filters */}
      <div className="flex items-center gap-4">
        <div className="flex items-center gap-2">
          <Filter className="h-4 w-4 text-gray-400" />
          <span className="text-sm text-gray-400">Filter:</span>
        </div>

        {/* Status filter */}
        <div className="flex gap-1">
          {["pending", "reviewed", "resolved", "dismissed", "all"].map((status) => (
            <button
              key={status}
              onClick={() => setStatusFilter(status)}
              className={cn(
                "rounded-lg px-3 py-1.5 text-xs font-medium capitalize transition-colors",
                statusFilter === status
                  ? "border border-[#00d9ff]/30 bg-[#00d9ff]/20 text-[#00d9ff]"
                  : "bg-gray-800 text-gray-400 hover:text-white"
              )}
            >
              {status}
            </button>
          ))}
        </div>

        {/* Type filter */}
        <select
          value={typeFilter || ""}
          onChange={(e) => setTypeFilter(e.target.value || null)}
          className="rounded-lg border border-gray-700 bg-gray-800 px-3 py-1.5 text-xs text-gray-300"
        >
          <option value="">All Types</option>
          <option value="rate_limit">Rate Limit</option>
          <option value="budget_exceeded">Budget Exceeded</option>
          <option value="concurrent_limit">Concurrent Limit</option>
          <option value="session_limit">Session Limit</option>
        </select>
      </div>

      {/* Feedback list */}
      <div className="overflow-hidden rounded-lg border border-gray-800 bg-gray-900/50">
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-[#00d9ff]" />
          </div>
        ) : feedback.length === 0 ? (
          <div className="py-12 text-center">
            <CheckCircle className="mx-auto mb-3 h-12 w-12 text-green-500" />
            <p className="text-gray-400">No feedback matching filters</p>
          </div>
        ) : (
          <div className="divide-y divide-gray-800">
            {feedback.map((item) => {
              const TypeIcon = getTypeIcon(item.type)

              return (
                <div
                  key={item.id}
                  className={cn(
                    "cursor-pointer p-4 transition-colors hover:bg-gray-800/30",
                    selectedFeedback?.id === item.id && "bg-gray-800/50"
                  )}
                  onClick={() => setSelectedFeedback(item)}
                >
                  <div className="flex items-start gap-4">
                    {/* Type icon */}
                    <div className={cn("rounded-lg border p-2", typeColors[item.type])}>
                      <TypeIcon className="h-4 w-4" />
                    </div>

                    {/* Content */}
                    <div className="min-w-0 flex-1">
                      <div className="flex flex-wrap items-center gap-2">
                        <span className="text-sm font-medium text-white">
                          {item.type.replace(/_/g, " ").replace(/\b\w/g, (l) => l.toUpperCase())}
                        </span>
                        {item.code && (
                          <code className="rounded bg-gray-800 px-1.5 py-0.5 text-xs text-gray-400">
                            {item.code}
                          </code>
                        )}
                        <Badge
                          variant="outline"
                          className={cn("text-xs", statusColors[item.status])}
                        >
                          {item.status}
                        </Badge>
                      </div>

                      <p className="mt-1 line-clamp-2 text-sm text-gray-400">
                        {item.systemMessage}
                      </p>

                      {item.userMessage && (
                        <div className="mt-2 flex items-start gap-2">
                          <MessageSquare className="mt-0.5 h-3.5 w-3.5 text-gray-500" />
                          <p className="line-clamp-2 text-xs text-gray-500 italic">
                            "{item.userMessage}"
                          </p>
                        </div>
                      )}

                      <div className="mt-2 flex items-center gap-4 text-xs text-gray-500">
                        <span className="flex items-center gap-1">
                          <User className="h-3 w-3" />
                          {item.userEmail || item.userId?.slice(0, 8) || "Anonymous"}
                        </span>
                        <span className="flex items-center gap-1">
                          <Globe className="h-3 w-3" />
                          {item.clientIp}
                        </span>
                        <span className="flex items-center gap-1">
                          <Calendar className="h-3 w-3" />
                          {formatDate(item.createdAt)}
                        </span>
                        {item.tier && (
                          <Badge variant="outline" className="text-xs">
                            {item.tier}
                          </Badge>
                        )}
                      </div>
                    </div>

                    {/* Quick actions */}
                    <div className="flex items-center gap-1">
                      <button
                        onClick={(e) => {
                          e.stopPropagation()
                          updateFeedbackStatus(item.id, "resolved")
                        }}
                        className="rounded p-1.5 text-gray-400 transition-colors hover:bg-green-500/10 hover:text-green-500"
                        title="Mark as resolved"
                      >
                        <CheckCircle className="h-4 w-4" />
                      </button>
                      <button
                        onClick={(e) => {
                          e.stopPropagation()
                          updateFeedbackStatus(item.id, "dismissed")
                        }}
                        className="rounded p-1.5 text-gray-400 transition-colors hover:bg-red-500/10 hover:text-red-500"
                        title="Dismiss"
                      >
                        <XCircle className="h-4 w-4" />
                      </button>
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>

      {/* Detail panel */}
      {selectedFeedback && (
        <div className="fixed inset-y-0 right-0 z-50 w-full max-w-lg overflow-y-auto border-l border-gray-800 bg-gray-900 shadow-xl">
          <div className="sticky top-0 flex items-center justify-between border-b border-gray-800 bg-gray-900/95 p-4 backdrop-blur-sm">
            <h2 className="font-semibold text-white">Feedback Details</h2>
            <button
              onClick={() => setSelectedFeedback(null)}
              className="rounded p-2 text-gray-400 hover:bg-gray-800 hover:text-white"
            >
              <XCircle className="h-4 w-4" />
            </button>
          </div>

          <div className="space-y-6 p-4">
            {/* Type & Status */}
            <div className="flex items-center gap-3">
              <div className={cn("rounded-lg border p-2", typeColors[selectedFeedback.type])}>
                {(() => {
                  const Icon = getTypeIcon(selectedFeedback.type)
                  return <Icon className="h-5 w-5" />
                })()}
              </div>
              <div>
                <p className="font-medium text-white">
                  {selectedFeedback.type
                    .replace(/_/g, " ")
                    .replace(/\b\w/g, (l) => l.toUpperCase())}
                </p>
                {selectedFeedback.code && (
                  <code className="text-xs text-gray-400">{selectedFeedback.code}</code>
                )}
              </div>
              <Badge
                variant="outline"
                className={cn("ml-auto", statusColors[selectedFeedback.status])}
              >
                {selectedFeedback.status}
              </Badge>
            </div>

            {/* System Message */}
            <div>
              <label className="text-xs tracking-wider text-gray-500 uppercase">
                System Message
              </label>
              <p className="mt-1 rounded-lg bg-gray-800/50 p-3 text-sm text-gray-300">
                {selectedFeedback.systemMessage}
              </p>
            </div>

            {/* User Message */}
            {selectedFeedback.userMessage && (
              <div>
                <label className="text-xs tracking-wider text-gray-500 uppercase">
                  User Feedback
                </label>
                <p className="mt-1 rounded-lg bg-gray-800/50 p-3 text-sm text-gray-300 italic">
                  "{selectedFeedback.userMessage}"
                </p>
              </div>
            )}

            {/* User Info */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs tracking-wider text-gray-500 uppercase">User</label>
                <p className="mt-1 text-sm text-gray-300">
                  {selectedFeedback.userEmail || selectedFeedback.userId || "Anonymous"}
                </p>
              </div>
              <div>
                <label className="text-xs tracking-wider text-gray-500 uppercase">Tier</label>
                <p className="mt-1 text-sm text-gray-300 capitalize">
                  {selectedFeedback.tier || "Unknown"}
                </p>
              </div>
              <div>
                <label className="text-xs tracking-wider text-gray-500 uppercase">IP Address</label>
                <p className="mt-1 font-mono text-sm text-gray-300">{selectedFeedback.clientIp}</p>
              </div>
              <div>
                <label className="text-xs tracking-wider text-gray-500 uppercase">
                  Reported At
                </label>
                <p className="mt-1 text-sm text-gray-300">
                  {formatDate(selectedFeedback.createdAt)}
                </p>
              </div>
            </div>

            {/* User Agent */}
            {selectedFeedback.userAgent && (
              <div>
                <label className="text-xs tracking-wider text-gray-500 uppercase">User Agent</label>
                <p className="mt-1 rounded bg-gray-800/50 p-2 font-mono text-xs break-all text-gray-400">
                  {selectedFeedback.userAgent}
                </p>
              </div>
            )}

            {/* Actions */}
            <div className="border-t border-gray-800 pt-4">
              <label className="mb-3 block text-xs tracking-wider text-gray-500 uppercase">
                Update Status
              </label>
              <div className="flex flex-wrap gap-2">
                {["reviewed", "resolved", "dismissed"].map((status) => (
                  <Button
                    key={status}
                    onClick={() => updateFeedbackStatus(selectedFeedback.id, status)}
                    disabled={updating || selectedFeedback.status === status}
                    variant={selectedFeedback.status === status ? "default" : "outline"}
                    size="sm"
                    className="capitalize"
                  >
                    {updating ? <Loader2 className="mr-1 h-3 w-3 animate-spin" /> : null}
                    {status}
                  </Button>
                ))}
              </div>
            </div>

            {/* Review Info */}
            {selectedFeedback.reviewedAt && (
              <div className="rounded-lg bg-gray-800/30 p-3 text-sm">
                <p className="text-gray-400">
                  Reviewed by <span className="text-gray-300">{selectedFeedback.reviewedBy}</span>
                  {" on "}
                  <span className="text-gray-300">{formatDate(selectedFeedback.reviewedAt)}</span>
                </p>
                {selectedFeedback.resolution && (
                  <p className="mt-2 text-gray-300">{selectedFeedback.resolution}</p>
                )}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import { useEffect, useState, useCallback } from "react"
import { useAuth } from "@/lib/auth-context"
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { MetricCard } from "@/components/admin/charts"
import { DataTable, Column, renderBadge } from "@/components/admin/shared/DataTable"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Scale,
  Brain,
  TrendingUp,
  TrendingDown,
  AlertTriangle,
  CheckCircle,
  RefreshCw,
  Shield,
  MessageSquare,
  Target,
  Activity,
  Zap,
  BarChart3,
} from "lucide-react"
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  Legend,
} from "recharts"
import { logger } from "@/lib/logger"
import type {
  ConstitutionalAIStats,
  ConstitutionalAIIntervention,
  AnalyticsTimeSeriesPoint,
  ConflictSummary,
  CritiqueAspect,
} from "@/lib/scoring/analytics-types"

const ASPECT_COLORS: Record<CritiqueAspect, string> = {
  fairness: "#00d9ff",
  tone: "#00ff88",
  accuracy: "#ff6b6b",
  actionability: "#ffd93d",
}

const ASPECT_LABELS: Record<CritiqueAspect, string> = {
  fairness: "Fairness",
  tone: "Tone",
  accuracy: "Accuracy",
  actionability: "Actionability",
}

interface ScoringAnalyticsData {
  stats: ConstitutionalAIStats
  timeSeries?: AnalyticsTimeSeriesPoint[]
  recentInterventions: ConstitutionalAIIntervention[]
}

export default function ScoringPage() {
  const { firebaseUser } = useAuth()
  const [activeTab, setActiveTab] = useState("overview")
  const [timeRange, setTimeRange] = useState<"7d" | "30d" | "90d" | "all">("30d")
  const [scenarioType, setScenarioType] = useState<"all" | "dsa" | "system_design" | "bug_fix">(
    "all"
  )
  const [data, setData] = useState<ScoringAnalyticsData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const loadData = useCallback(async () => {
    if (!firebaseUser) return

    setLoading(true)
    setError(null)

    try {
      const token = await firebaseUser.getIdToken()
      const params = new URLSearchParams({
        timeRange,
        scenarioType,
        includeTimeSeries: "true",
        includeConflicts: "true",
      })

      const response = await fetch(`/api/admin/scoring?${params}`, {
        headers: { Authorization: `Bearer ${token}` },
      })

      const result = await response.json()

      if (result.success) {
        setData(result.data)
      } else {
        setError(result.error || "Failed to load data")
      }
    } catch (err) {
      logger.error("Error loading scoring analytics", { error: err })
      setError("Failed to load scoring analytics")
    } finally {
      setLoading(false)
    }
  }, [firebaseUser, timeRange, scenarioType])

  useEffect(() => {
    loadData()
  }, [loadData])

  const formatPercentage = (value: number) => `${value.toFixed(1)}%`
  const formatScore = (value: number) => (value >= 0 ? `+${value.toFixed(1)}` : value.toFixed(1))

  // Prepare chart data
  const aspectPieData = data
    ? Object.entries(data.stats.scoreCritiqueStats.byAspect)
        .filter(([, count]) => count > 0)
        .map(([aspect, count]) => ({
          name: ASPECT_LABELS[aspect as CritiqueAspect],
          value: count,
          color: ASPECT_COLORS[aspect as CritiqueAspect],
        }))
    : []

  const categoryBarData = data
    ? Object.entries(data.stats.categoryStats).map(([category, stats]) => ({
        category: category.charAt(0).toUpperCase() + category.slice(1).replace(/([A-Z])/g, " $1"),
        increases: stats.totalIncreases,
        decreases: -stats.totalDecreases,
        avgIncrease: stats.avgIncrease,
        avgDecrease: -stats.avgDecrease,
      }))
    : []

  // Intervention table columns
  const interventionColumns: Column<ConstitutionalAIIntervention>[] = [
    {
      key: "scenarioTitle",
      label: "Problem",
      render: (_, row) => (
        <div>
          <span className="text-sm text-white">{row.scenarioTitle}</span>
          <div className="mt-1">
            <Badge variant="outline" className="border-gray-700 text-xs text-gray-400 capitalize">
              {row.scenarioType.replace("_", " ")}
            </Badge>
          </div>
        </div>
      ),
    },
    {
      key: "scoreCritique",
      label: "Score Critique",
      render: (_, row) => (
        <div className="flex flex-col gap-1">
          {row.scoreCritique.madeChanges ? (
            <>
              <div className="flex items-center gap-2">
                <span
                  className={row.scoreCritique.overallDelta > 0 ? "text-green-400" : "text-red-400"}
                >
                  {row.scoreCritique.overallDelta > 0 ? (
                    <TrendingUp className="inline h-4 w-4" />
                  ) : (
                    <TrendingDown className="inline h-4 w-4" />
                  )}
                  {formatScore(row.scoreCritique.overallDelta)}
                </span>
                <span className="text-xs text-gray-500">
                  ({row.scoreCritique.originalOverall} → {row.scoreCritique.adjustedOverall})
                </span>
              </div>
              <div className="flex flex-wrap gap-1">
                {row.scoreCritique.aspectsViolated.map((aspect) => (
                  <Badge
                    key={aspect}
                    className="text-xs"
                    style={{
                      backgroundColor: `${ASPECT_COLORS[aspect]}20`,
                      color: ASPECT_COLORS[aspect],
                      borderColor: `${ASPECT_COLORS[aspect]}50`,
                    }}
                  >
                    {ASPECT_LABELS[aspect]}
                  </Badge>
                ))}
              </div>
            </>
          ) : (
            <span className="text-sm text-gray-500">No changes</span>
          )}
        </div>
      ),
    },
    {
      key: "feedbackCritique",
      label: "Feedback Critique",
      render: (_, row) =>
        row.feedbackCritique.madeChanges ? (
          <div className="flex flex-wrap gap-1">
            {row.feedbackCritique.aspectsViolated.map((aspect) => (
              <Badge
                key={aspect}
                className="text-xs"
                style={{
                  backgroundColor: `${ASPECT_COLORS[aspect]}20`,
                  color: ASPECT_COLORS[aspect],
                  borderColor: `${ASPECT_COLORS[aspect]}50`,
                }}
              >
                {ASPECT_LABELS[aspect]}
              </Badge>
            ))}
          </div>
        ) : (
          <span className="text-sm text-gray-500">No changes</span>
        ),
    },
    {
      key: "context",
      label: "Context",
      render: (_, row) => (
