} from "lucide-react"
import {
  getAllPricingTiers,
  getProviderCostInfo,
  AI_BUDGET_CAPS,
} from "@/lib/pricing"
import { PageHeader, SettingsCardSkeleton } from "@/components/admin/shared"
import { logger } from "@/lib/logger"

interface AdminUser {
  userId: string
  email: string
  role: "super_admin" | "admin" | "analyst" | "support"
  grantedBy: string
  grantedAt: string | null
  lastAccess: string | null
  active: boolean
}

const ROLE_LABELS: Record<string, { label: string; color: string }> = {
  super_admin: { label: "Super Admin", color: "bg-purple-600/20 text-purple-400 border-purple-600/30" },
  admin: { label: "Admin", color: "bg-blue-600/20 text-blue-400 border-blue-600/30" },
  analyst: { label: "Analyst", color: "bg-green-600/20 text-green-400 border-green-600/30" },
  support: { label: "Support", color: "bg-yellow-600/20 text-yellow-400 border-yellow-600/30" },
}

export default function AdminSettingsPage() {
  const { firebaseUser } = useAuth()
  const [activeTab, setActiveTab] = useState<"pricing" | "ai" | "admins">("admins")
  const [admins, setAdmins] = useState<AdminUser[]>([])
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)

  // Add admin form
  const [showAddForm, setShowAddForm] = useState(false)
  const [newAdminEmail, setNewAdminEmail] = useState("")
  const [newAdminUserId, setNewAdminUserId] = useState("")
  const [newAdminRole, setNewAdminRole] = useState<string>("analyst")
  const [addingAdmin, setAddingAdmin] = useState(false)

  // Revoke dialog
  const [revokeDialogOpen, setRevokeDialogOpen] = useState(false)
  const [adminToRevoke, setAdminToRevoke] = useState<AdminUser | null>(null)
  const [revoking, setRevoking] = useState(false)

  // Alerts
  const [successMessage, setSuccessMessage] = useState<string | null>(null)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)

  const pricingTiers = getAllPricingTiers()
  const providerCosts = getProviderCostInfo()

  const loadAdmins = useCallback(async (showRefresh = false) => {
    if (!firebaseUser) return

    if (showRefresh) setRefreshing(true)

    try {
      const token = await firebaseUser.getIdToken()
      const response = await fetch("/api/admin/admins", {
        headers: { Authorization: `Bearer ${token}` },
      })

      if (response.ok) {
        const data = await response.json()
        if (data.success) {
          setAdmins(data.admins)
        }
      } else if (response.status === 403) {
        // Not super_admin, just show env admin info
        setAdmins([])
      }
    } catch (error) {
      logger.error("Error loading admins", { error })
    } finally {
      setLoading(false)
      setRefreshing(false)
    }
  }, [firebaseUser])

  useEffect(() => {
    loadAdmins()
  }, [loadAdmins])

  const handleAddAdmin = async () => {
    if (!firebaseUser || !newAdminEmail || !newAdminUserId) return

    setAddingAdmin(true)
    setErrorMessage(null)

    try {
      const token = await firebaseUser.getIdToken()
      const response = await fetch("/api/admin/admins", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          userId: newAdminUserId,
          email: newAdminEmail,
          role: newAdminRole,
        }),
      })

      const data = await response.json()

      if (response.ok && data.success) {
        setSuccessMessage(`Admin role granted to ${newAdminEmail}`)
        setNewAdminEmail("")
        setNewAdminUserId("")
        setNewAdminRole("analyst")
        setShowAddForm(false)
        await loadAdmins()
        setTimeout(() => setSuccessMessage(null), 3000)
      } else {
        setErrorMessage(data.error || "Failed to add admin")
      }
    } catch (error) {
      logger.error("Error adding admin", { error })
      setErrorMessage("Failed to add admin")
    } finally {
      setAddingAdmin(false)
    }
  }

  const handleRevokeAdmin = async () => {
    if (!firebaseUser || !adminToRevoke) return

    setRevoking(true)
    setErrorMessage(null)

    try {
      const token = await firebaseUser.getIdToken()
      const response = await fetch(`/api/admin/admins?userId=${adminToRevoke.userId}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      })

      const data = await response.json()

      if (response.ok && data.success) {
        setSuccessMessage(`Admin access revoked for ${adminToRevoke.email}`)
        setRevokeDialogOpen(false)
        setAdminToRevoke(null)
        await loadAdmins()
        setTimeout(() => setSuccessMessage(null), 3000)
      } else {
        setErrorMessage(data.error || "Failed to revoke admin")
      }
    } catch (error) {
      logger.error("Error revoking admin", { error })
      setErrorMessage("Failed to revoke admin")
    } finally {
      setRevoking(false)
    }
  }

  if (loading) {
    return (
      <div className="space-y-8">
        <PageHeader title="Settings" subtitle="Platform configuration and admin management" />
        <div className="flex gap-2 border-b border-gray-800 pb-4">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-9 w-24 animate-pulse bg-gray-800 rounded-md" />
          ))}
        </div>
        <div className="grid grid-cols-1 gap-6">
          <SettingsCardSkeleton />
          <SettingsCardSkeleton />
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-8">
      {/* Header */}
      <PageHeader
        title="Settings"
        subtitle="Platform configuration and admin management"
        onRefresh={() => loadAdmins(true)}
        refreshing={refreshing}
      />

      {/* Alerts */}
      {successMessage && (
        <div className="flex items-center gap-2 rounded-lg border border-green-500/30 bg-green-900/20 p-3">
          <CheckCircle className="h-5 w-5 text-green-400" />
          <span className="text-sm text-green-300">{successMessage}</span>
        </div>
      )}
      {errorMessage && (
        <div className="flex items-center gap-2 rounded-lg border border-red-500/30 bg-red-900/20 p-3">
          <AlertCircle className="h-5 w-5 text-red-400" />
          <span className="text-sm text-red-300">{errorMessage}</span>
          <Button
            onClick={() => setErrorMessage(null)}
            variant="ghost"
            size="sm"
            className="ml-auto text-red-400 hover:text-red-300"
          >
            Dismiss
          </Button>
        </div>
      )}

      {/* Tabs */}
      <div className="flex gap-2 border-b border-gray-800 pb-4">
        {[
          { id: "admins", label: "Admin Users", icon: Shield },
          { id: "pricing", label: "Pricing", icon: DollarSign },
          { id: "ai", label: "AI Providers", icon: Cpu },
        ].map((tab) => (
          <Button
            key={tab.id}
            variant={activeTab === tab.id ? "default" : "ghost"}
            onClick={() => setActiveTab(tab.id as typeof activeTab)}
            className={
              activeTab === tab.id
                ? "bg-[#00d9ff] text-black hover:bg-[#00d9ff]/80"
                : "text-gray-400 hover:text-white hover:bg-gray-800"
            }
          >
            <tab.icon className="h-4 w-4 mr-2" />
            {tab.label}
          </Button>
        ))}
      </div>

      {/* Admin Users Tab */}
      {activeTab === "admins" && (
        <div className="space-y-6">
          {/* Admin List */}
          <Card className="bg-gray-900/50 border-gray-800">
            <CardHeader>
              <div className="flex items-center justify-between">
                <div>
                  <CardTitle className="text-white flex items-center gap-2">
                    <Shield className="h-5 w-5 text-[#00d9ff]" />
                    Admin Users
                  </CardTitle>
                  <CardDescription className="text-gray-400">
                    Manage who has access to the admin dashboard
                  </CardDescription>
                </div>
                <Button
                  onClick={() => setShowAddForm(!showAddForm)}
                  className="bg-[#00d9ff] text-black hover:bg-[#00d9ff]/80"
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Add Admin
                </Button>
              </div>
            </CardHeader>
            <CardContent className="space-y-4">
              {/* Add Admin Form */}
              {showAddForm && (
                <div className="p-4 bg-gray-800/50 rounded-lg border border-gray-700 space-y-4">
                  <h4 className="text-sm font-medium text-white">Add New Admin</h4>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div>
                      <label className="text-xs text-gray-400 mb-1 block">User ID</label>
                      <Input
                        placeholder="Firebase User ID"
                        value={newAdminUserId}
                        onChange={(e) => setNewAdminUserId(e.target.value)}
                        className="border-gray-700 bg-gray-800 text-white"
                      />
                    </div>
                    <div>
                      <label className="text-xs text-gray-400 mb-1 block">Email</label>
                      <Input
                        placeholder="admin@example.com"
                        value={newAdminEmail}
                        onChange={(e) => setNewAdminEmail(e.target.value)}
                        className="border-gray-700 bg-gray-800 text-white"
                      />
                    </div>
                    <div>
                      <label className="text-xs text-gray-400 mb-1 block">Role</label>
                      <Select value={newAdminRole} onValueChange={setNewAdminRole}>
                        <SelectTrigger className="border-gray-700 bg-gray-800 text-white">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent className="bg-gray-800 border-gray-700">
                          <SelectItem value="admin">Admin - Full access</SelectItem>
                          <SelectItem value="analyst">Analyst - Read-only analytics</SelectItem>
                          <SelectItem value="support">Support - User management</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                  </div>
                  <div className="flex justify-end gap-2">
                    <Button
                      variant="outline"
                      onClick={() => setShowAddForm(false)}
                      className="border-gray-700 text-gray-400"
                    >
                      Cancel
                    </Button>
                    <Button
                      onClick={handleAddAdmin}
                      disabled={addingAdmin || !newAdminEmail || !newAdminUserId}
                      className="bg-[#00d9ff] text-black hover:bg-[#00d9ff]/80"
                    >
                      {addingAdmin ? (
                        <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      ) : (
                        <Plus className="h-4 w-4 mr-2" />
                      )}
                      Add Admin
                    </Button>
                  </div>
                </div>
              )}

              {/* Admin List */}
              <div className="space-y-2">
                {admins.length === 0 ? (
                  <div className="text-center py-8 text-gray-500">
                    <Shield className="h-12 w-12 mx-auto mb-4 opacity-50" />
                    <p>No additional admins configured.</p>
                    <p className="text-sm mt-1">Only the environment admin has access.</p>
                  </div>
                ) : (
                  admins.map((admin) => (
                    <div
                      key={admin.userId}
                      className="flex items-center justify-between p-4 bg-gray-800/30 rounded-lg border border-gray-700/50 hover:border-gray-600/50 transition-colors"
                    >
                      <div className="flex items-center gap-4">
                        <div className="flex h-10 w-10 items-center justify-center rounded-full bg-gradient-to-br from-[#00d9ff] to-[#00ff88]">
                          <User className="h-5 w-5 text-black" />
                        </div>
                        <div>
                          <p className="text-white font-medium">{admin.email}</p>
                          <div className="flex items-center gap-3 mt-1 text-xs text-gray-500">
                            <span className="font-mono">{admin.userId.substring(0, 12)}...</span>
                            {admin.lastAccess && (
                              <span className="flex items-center gap-1">
                                <Clock className="h-3 w-3" />
                                Last: {new Date(admin.lastAccess).toLocaleDateString()}
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center gap-3">
                        <Badge className={ROLE_LABELS[admin.role]?.color || "bg-gray-600"}>
                          {ROLE_LABELS[admin.role]?.label || admin.role}
                        </Badge>
                        {admin.role !== "super_admin" && admin.grantedBy !== "system" && (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => {
                              setAdminToRevoke(admin)
                              setRevokeDialogOpen(true)
                            }}
                            className="text-red-400 hover:bg-red-500/10 hover:text-red-300"
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        )}
                        {admin.grantedBy === "system" && (
                          <span className="text-xs text-gray-500">Environment</span>
                        )}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </CardContent>
          </Card>

          {/* Permissions Matrix */}
          <Card className="bg-gray-900/50 border-gray-800">
            <CardHeader>
              <CardTitle className="text-white">Permission Matrix</CardTitle>
              <CardDescription className="text-gray-400">
                What each role can access
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-gray-800">
                      <th className="text-left text-gray-400 py-3 px-4">Permission</th>
                      <th className="text-center text-purple-400 py-3 px-4">Super Admin</th>
                      <th className="text-center text-blue-400 py-3 px-4">Admin</th>
                      <th className="text-center text-green-400 py-3 px-4">Analyst</th>
                      <th className="text-center text-yellow-400 py-3 px-4">Support</th>
                    </tr>
                  </thead>
                  <tbody>
                    {[
                      { name: "View Analytics", roles: [true, true, true, false] },
                      { name: "View Revenue", roles: [true, true, true, false] },
                      { name: "Export Data", roles: [true, true, true, false] },
                      { name: "View Users", roles: [true, true, true, true] },
                      { name: "Manage Users", roles: [true, true, false, true] },
                      { name: "View AI Usage", roles: [true, true, true, false] },
                      { name: "Manage Budgets", roles: [true, true, false, false] },
                      { name: "View Errors", roles: [true, true, true, true] },
                      { name: "Manage Settings", roles: [true, true, false, false] },
                      { name: "Manage Admins", roles: [true, false, false, false] },
                    ].map((perm) => (
                      <tr key={perm.name} className="border-b border-gray-800/50 hover:bg-gray-800/30">
                        <td className="py-3 px-4 text-white">{perm.name}</td>
                        {perm.roles.map((has, i) => (
                          <td key={i} className="text-center py-3 px-4">
                            {has ? (
                              <CheckCircle className="h-4 w-4 text-green-400 mx-auto" />
                            ) : (
                              <span className="text-gray-600">-</span>
                            )}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Pricing Tab */}
      {activeTab === "pricing" && (
        <div className="space-y-6">
          {/* Info Banner */}
          <Card className="bg-blue-900/20 border-blue-500/30">
            <CardContent className="p-4 flex items-start gap-3">
              <AlertCircle className="h-5 w-5 text-blue-400 flex-shrink-0 mt-0.5" />
              <div>
                <p className="text-blue-300 text-sm">
                  Pricing is currently managed in <code className="bg-blue-900/30 px-1.5 py-0.5 rounded text-[#00d9ff]">lib/config.ts</code>.
                  Changes require a code deployment.
                </p>
                <p className="text-blue-400/70 text-xs mt-1">
                  Dynamic pricing configuration via Firestore is planned for a future release.
                </p>
              </div>
            </CardContent>
          </Card>

          {/* Pricing Tiers */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {pricingTiers.map((tier) => (
              <Card
                key={tier.tier}
                className={`bg-gray-900/50 border-gray-800 ${
                  tier.tier === "pro" ? "ring-2 ring-yellow-500/30" : ""
                }`}
              >
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <CardTitle className="text-white">{tier.name}</CardTitle>
                    {tier.tier === "pro" && (
                      <Badge className="bg-yellow-600/20 text-yellow-400 border-yellow-600/30">
                        Popular
                      </Badge>
                    )}
                  </div>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div>
                    <span className="text-4xl font-bold text-white">
                      ${tier.monthlyPrice}
                    </span>
                    <span className="text-gray-400">/month</span>
                  </div>

                  <div className="space-y-3 text-sm">
                    <div className="flex justify-between py-2 border-b border-gray-800">
                      <span className="text-gray-400">Annual Price</span>
                      <span className="text-white font-medium">${tier.annualPrice}/year</span>
                    </div>
                    <div className="flex justify-between py-2 border-b border-gray-800">
                      <span className="text-gray-400">AI Budget Cap</span>
                      <span className="text-[#00d9ff] font-medium">${tier.aiBudgetCap}/month</span>
                    </div>
                    <div className="flex justify-between py-2">
                      <span className="text-gray-400">Sessions/Month</span>
                      <span className="text-white font-medium">
                        {tier.sessionsPerMonth ?? "Unlimited"}
                      </span>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>

          {/* Budget Caps Summary */}
          <Card className="bg-gray-900/50 border-gray-800">
            <CardHeader>
              <CardTitle className="text-white flex items-center gap-2">
                <Cpu className="h-5 w-5 text-[#00d9ff]" />
                AI Budget Caps
              </CardTitle>
              <CardDescription className="text-gray-400">
                Monthly AI API spending limits per subscription tier
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-3 gap-4">
                {Object.entries(AI_BUDGET_CAPS).map(([tier, cap]) => (
                  <div
                    key={tier}
                    className="bg-gray-800/50 p-6 rounded-lg text-center border border-gray-700/50"
                  >
                    <div className="text-3xl font-bold text-white">${cap}</div>
                    <div className="text-sm text-gray-400 capitalize mt-1">{tier}</div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* AI Providers Tab */}
      {activeTab === "ai" && (
        <div className="space-y-6">
          {/* Provider Costs */}
          <Card className="bg-gray-900/50 border-gray-800">
            <CardHeader>
              <CardTitle className="text-white flex items-center gap-2">
                <Cpu className="h-5 w-5 text-[#00d9ff]" />
                AI Provider Costs
              </CardTitle>
              <CardDescription className="text-gray-400">
                Cost per 1,000 tokens (input + output averaged)
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                {providerCosts.map((provider) => (
                  <div
                    key={provider.provider}
                    className="flex items-center justify-between p-4 bg-gray-800/30 rounded-lg border border-gray-700/50"
                  >
                    <div className="flex items-center gap-3">
                      <div className="h-10 w-10 rounded-lg bg-gradient-to-br from-[#00d9ff]/20 to-[#00ff88]/20 flex items-center justify-center">
                        <Cpu className="h-5 w-5 text-[#00d9ff]" />
                      </div>
                      <div>
                        <span className="text-white font-medium">
                          {provider.displayName}
                        </span>
                        <span className="text-gray-500 text-sm block">
                          {provider.provider}
                        </span>
                      </div>
                    </div>
                    <div className="text-right">
                      <span className="text-[#00ff88] font-mono text-lg">
                        ${provider.costPer1kTokens.toFixed(6)}
                      </span>
                      <span className="text-gray-500 text-sm block">/1K tokens</span>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>

          {/* Provider Status */}
          <Card className="bg-gray-900/50 border-gray-800">
            <CardHeader>
              <CardTitle className="text-white">Provider Status</CardTitle>
              <CardDescription className="text-gray-400">
                Active AI providers in your environment
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {["Gemini", "Claude", "OpenAI", "Deepseek"].map((provider) => (
                  <div
                    key={provider}
                    className="flex items-center gap-3 p-4 bg-gray-800/30 rounded-lg border border-gray-700/50"
                  >
                    <div className="h-2 w-2 rounded-full bg-green-400 animate-pulse" />
                    <span className="text-white">{provider}</span>
                    <Badge className="ml-auto bg-green-600/20 text-green-400 border-green-600/30 text-xs">
                      Active
                    </Badge>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>

          {/* Environment Variables */}
          <Card className="bg-gray-900/50 border-gray-800">
            <CardHeader>
              <CardTitle className="text-white">Required Environment Variables</CardTitle>
              <CardDescription className="text-gray-400">
                API keys needed for AI providers
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                {[
                  { key: "GOOGLE_AI_API_KEY", provider: "Gemini" },
                  { key: "ANTHROPIC_API_KEY", provider: "Claude" },
                  { key: "OPENAI_API_KEY", provider: "OpenAI" },
                  { key: "DEEPSEEK_API_KEY", provider: "Deepseek" },
                ].map((env) => (
                  <div
                    key={env.key}
                    className="flex items-center justify-between p-3 bg-gray-800/30 rounded-lg"
                  >
                    <code className="text-[#00d9ff] font-mono text-sm">{env.key}</code>
                    <span className="text-gray-500 text-sm">{env.provider}</span>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Revoke Admin Dialog */}
      <AlertDialog open={revokeDialogOpen} onOpenChange={setRevokeDialogOpen}>
        <AlertDialogContent className="border-gray-800 bg-gray-900">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-white">Revoke Admin Access</AlertDialogTitle>
            <AlertDialogDescription className="text-gray-400">
              Are you sure you want to revoke admin access for{" "}
              <strong className="text-white">{adminToRevoke?.email}</strong>?
              <br /><br />
              They will no longer be able to access the admin dashboard.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="border-gray-700 bg-gray-800 text-gray-300 hover:bg-gray-700">
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={handleRevokeAdmin}
              disabled={revoking}
              className="bg-red-600 text-white hover:bg-red-700"
            >
              {revoking ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Revoking...
                </>
              ) : (
                "Revoke Access"
              )}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

"use client"

import { useEffect, useState, useCallback } from "react"
import { useAuth } from "@/lib/auth-context"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { MetricCard, TimeSeriesChart, DistributionChart } from "@/components/admin/charts"
import {
  PageHeader,
  MetricsGridSkeleton,
  ChartSkeleton,
  UserListSkeleton,
} from "@/components/admin/shared"
import { UserProfileDrawer } from "@/components/admin/UserProfileDrawer"
import { Users, UserPlus, Crown, Search, RefreshCw, Trash2, X, Eye, Loader2 } from "lucide-react"
import { logger } from "@/lib/logger"

interface UserProfile {
  id: string
  email: string
  full_name?: string
  auth_provider?: string
  subscription_tier: string
  subscription_status?: string
  created_at: string
  updated_at?: string
  onboarding_completed?: boolean
  stripe_customer_id?: string | null
}

export default function UsersPage() {
  const { firebaseUser } = useAuth()
  const [metrics, setMetrics] = useState<any>(null)
  const [users, setUsers] = useState<UserProfile[]>([])
  const [loading, setLoading] = useState(true)
  const [usersLoading, setUsersLoading] = useState(false)
  const [timeRange, setTimeRange] = useState("30d")
  const [searchQuery, setSearchQuery] = useState("")
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false)
  const [userToDelete, setUserToDelete] = useState<UserProfile | null>(null)
  const [deleting, setDeleting] = useState(false)
  const [profileDrawerOpen, setProfileDrawerOpen] = useState(false)
  const [selectedUserId, setSelectedUserId] = useState<string | null>(null)
  const [authToken, setAuthToken] = useState<string | null>(null)

  // Protected emails - these users cannot be deleted
  // SECURITY: Load from environment variable (UI check only - real protection is server-side)
  const PROTECTED_EMAILS = (process.env.NEXT_PUBLIC_ADMIN_PROTECTED_EMAILS || "")
    .split(",")
    .map((email: string) => email.trim().toLowerCase())
    .filter((email: string) => email.length > 0)

  const loadData = useCallback(async () => {
    if (!firebaseUser) return

    try {
      const token = await firebaseUser.getIdToken()
      setAuthToken(token) // Store token for profile drawer
      const response = await fetch(`/api/admin/analytics?timeRange=${timeRange}`, {
        headers: { Authorization: `Bearer ${token}` },
      })

      if (response.ok) {
        const data = await response.json()
        if (data.success) {
          setMetrics(data.metrics)
        }
      }
    } catch (error) {
      logger.error("Error loading user data", { error, timeRange })
    } finally {
      setLoading(false)
    }
  }, [firebaseUser, timeRange])

  const loadUsers = useCallback(async () => {
    if (!firebaseUser) return

    setUsersLoading(true)
    try {
      const token = await firebaseUser.getIdToken()
      const params = new URLSearchParams({
        page: page.toString(),
        limit: "50",
      })
      if (searchQuery) {
        params.append("search", searchQuery)
      }

      const response = await fetch(`/api/admin/users?${params}`, {
        headers: { Authorization: `Bearer ${token}` },
      })

      if (response.ok) {
        const data = await response.json()
        if (data.success) {
          setUsers(data.users)
          setTotalPages(data.pagination.totalPages)
        }
      }
    } catch (error) {
      logger.error("Error loading users list", { error, search: searchQuery })
    } finally {
      setUsersLoading(false)
    }
  }, [firebaseUser, page, searchQuery])

  useEffect(() => {
    loadData()
  }, [loadData])

  useEffect(() => {
    loadUsers()
  }, [loadUsers])

  const handleDelete = async () => {
    if (!userToDelete || !firebaseUser) return

    setDeleting(true)
    try {
      const token = await firebaseUser.getIdToken()
      const response = await fetch("/api/admin/users", {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ userId: userToDelete.id }),
      })

      if (response.ok) {
        // Reload users and metrics
        await loadUsers()
        await loadData()
        setDeleteDialogOpen(false)
        setUserToDelete(null)
      } else {
        const data = await response.json()
        alert(`Failed to delete user: ${data.error || "Unknown error"}`)
      }
    } catch (error) {
      logger.error("Error deleting user", { error, userId: userToDelete?.id })
      alert("Failed to delete user")
    } finally {
      setDeleting(false)
    }
  }

  const isProtected = (email: string) => PROTECTED_EMAILS.includes(email.toLowerCase())

  if (loading) {
    return (
      <div className="space-y-8">
        <PageHeader title="Users" subtitle="User management and analytics" />
        <MetricsGridSkeleton count={4} />
        <ChartSkeleton height={280} />
        <UserListSkeleton rows={8} />
      </div>
    )
  }

  const tierDistribution = metrics
    ? [
        { name: "Free", value: metrics.users.byTier.free, color: "#6B7280" },
        { name: "Pro", value: metrics.users.byTier.pro, color: "#FBBF24" },
        { name: "Enterprise", value: metrics.users.byTier.enterprise, color: "#A855F7" },
      ]
    : []

  const conversionRate =
    metrics && metrics.users.total > 0
      ? ((metrics.users.byTier.pro / metrics.users.total) * 100).toFixed(1)
      : "0"

  return (
    <div className="space-y-8">
      {/* Header */}
      <PageHeader
        title="Users"
        subtitle="User management and analytics"
        timeRange={timeRange}
        onTimeRangeChange={setTimeRange}
        onRefresh={loadData}
      />

      {/* Key Metrics */}
      {metrics && (
        <>
          <div className="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-4">
            <MetricCard
              title="Total Users"
              value={metrics.users.total}
              icon={Users}
              sparklineData={metrics.timeSeries?.users.slice(-7).map((u: any) => u.total)}
              sparklineColor="#00d9ff"
            />
            <MetricCard
              title="Pro Users"
              value={metrics.users.byTier.pro}
              subtitle={`${conversionRate}% of total`}
              icon={Crown}
              iconColor="text-yellow-400"
              valueColor="text-yellow-400"
            />
            <MetricCard title="Free Users" value={metrics.users.byTier.free} icon={UserPlus} />
            <MetricCard
              title="Enterprise"
              value={metrics.users.byTier.enterprise}
              icon={Users}
              iconColor="text-purple-400"
              valueColor="text-purple-400"
            />
          </div>

          {/* User Growth Chart */}
          {metrics.timeSeries?.users && (
            <TimeSeriesChart
              title="User Growth"
              subtitle="Total users over time"
              data={metrics.timeSeries.users}
              series={[
                { key: "free", name: "Free", color: "#6B7280" },
                { key: "pro", name: "Pro", color: "#FBBF24" },
                { key: "enterprise", name: "Enterprise", color: "#A855F7" },
              ]}
              stacked
              icon={Users}
            />
          )}

          {/* Distribution */}
          <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
            <DistributionChart
              title="User Distribution"
              data={tierDistribution}
              type="pie"
              icon={Users}
            />

            <Card className="border-gray-800 bg-gray-900/50">
              <CardHeader>
                <CardTitle className="text-white">Tier Breakdown</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                {[
                  { tier: "Free", count: metrics.users.byTier.free, color: "gray" },
                  { tier: "Pro", count: metrics.users.byTier.pro, color: "yellow" },
                  { tier: "Enterprise", count: metrics.users.byTier.enterprise, color: "purple" },
                ].map((item) => (
                  <div key={item.tier} className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <Badge
                        className={
                          item.color === "yellow"
                            ? "border-yellow-600/30 bg-yellow-600/20 text-yellow-400"
                            : item.color === "purple"
                              ? "border-purple-600/30 bg-purple-600/20 text-purple-400"
                              : "border-gray-600/30 bg-gray-600/20 text-gray-400"
                        }
                      >
                        {item.tier}
                      </Badge>
                    </div>
                    <div className="flex items-center gap-4">
                      <span className="font-semibold text-white">{item.count}</span>
                      <div className="h-2 w-32 overflow-hidden rounded-full bg-gray-700">
                        <div
                          className={`h-full rounded-full ${
                            item.color === "yellow"
                              ? "bg-yellow-400"
                              : item.color === "purple"
                                ? "bg-purple-400"
                                : "bg-gray-400"
                          }`}
                          style={{
                            width: `${metrics.users.total > 0 ? (item.count / metrics.users.total) * 100 : 0}%`,
                          }}
                        />
                      </div>
                      <span className="w-12 text-sm text-gray-500">
                        {metrics.users.total > 0
                          ? ((item.count / metrics.users.total) * 100).toFixed(0)
                          : 0}
                        %
                      </span>
                    </div>
                  </div>
                ))}
              </CardContent>
            </Card>
          </div>
        </>
      )}

      {/* User List */}
      <Card className="border-gray-800 bg-gray-900/50">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-white">All Users</CardTitle>
            <div className="flex items-center gap-2">
              <div className="relative">
                <Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 transform text-gray-400" />
                <Input
                  placeholder="Search users..."
                  value={searchQuery}
                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
                    setSearchQuery(e.target.value)
                    setPage(1)
                  }}
                  className="w-64 border-gray-700 bg-gray-800 pl-10 text-white"
                />
              </div>
              <Button
                onClick={loadUsers}
                variant="outline"
                size="sm"
                className="border-gray-700 text-gray-400 hover:text-white"
                disabled={usersLoading}
              >
                <RefreshCw className={`mr-2 h-4 w-4 ${usersLoading ? "animate-spin" : ""}`} />
                Refresh
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {usersLoading ? (
            <div className="flex items-center justify-center py-12">
              <div className="h-8 w-8 animate-spin rounded-full border-b-2 border-[#00d9ff]"></div>
            </div>
          ) : users.length === 0 ? (
            <div className="py-12 text-center text-gray-400">No users found</div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-gray-800">
                    <th className="px-4 py-3 text-left text-sm font-medium text-gray-400">Email</th>
                    <th className="px-4 py-3 text-left text-sm font-medium text-gray-400">Name</th>
                    <th className="px-4 py-3 text-left text-sm font-medium text-gray-400">
                      Provider
                    </th>
                    <th className="px-4 py-3 text-left text-sm font-medium text-gray-400">Tier</th>
                    <th className="px-4 py-3 text-left text-sm font-medium text-gray-400">
                      Created
                    </th>
                    <th className="px-4 py-3 text-left text-sm font-medium text-gray-400">
                      Status
                    </th>
                    <th className="px-4 py-3 text-right text-sm font-medium text-gray-400">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {users.map((user: UserProfile) => {
                    const protectedUser = isProtected(user.email)
                    return (
                      <tr
                        key={user.id}
                        className="border-b border-gray-800/50 hover:bg-gray-800/30"
                      >
                        <td className="px-4 py-3">
                          <div className="text-white">{user.email}</div>
                          <div className="font-mono text-xs text-gray-500">
                            {user.id.substring(0, 20)}...
                          </div>
                        </td>
                        <td className="px-4 py-3 text-gray-300">{user.full_name || "-"}</td>
                        <td className="px-4 py-3">
                          <Badge
                            className={
                              user.auth_provider === "github"
                                ? "border-gray-600/30 bg-gray-600/20 text-gray-300"
                                : user.auth_provider === "google"
                                  ? "border-blue-600/30 bg-blue-600/20 text-blue-300"
                                  : "border-gray-600/30 bg-gray-600/20 text-gray-400"
                            }
                          >
                            {user.auth_provider || "-"}
                          </Badge>
                        </td>
                        <td className="px-4 py-3">
                          <Badge
                            className={
                              user.subscription_tier === "pro"
                                ? "border-yellow-600/30 bg-yellow-600/20 text-yellow-400"
                                : user.subscription_tier === "enterprise"
                                  ? "border-purple-600/30 bg-purple-600/20 text-purple-400"
                                  : "border-gray-600/30 bg-gray-600/20 text-gray-400"
                            }
                          >
                            {user.subscription_tier || "free"}
                          </Badge>
                        </td>
                        <td className="px-4 py-3 text-sm text-gray-400">
                          {user.created_at ? new Date(user.created_at).toLocaleDateString() : "-"}
                        </td>
                        <td className="px-4 py-3">
                          {protectedUser ? (
                            <Badge className="border-green-600/30 bg-green-600/20 text-green-400">
                              Protected
                            </Badge>
                          ) : (
                            <Badge className="border-gray-600/30 bg-gray-600/20 text-gray-400">
                              {user.subscription_status || "none"}
                            </Badge>
                          )}
                        </td>
                        <td className="px-4 py-3 text-right">
                          <div className="flex items-center justify-end gap-1">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => {
                                setSelectedUserId(user.id)
                                setProfileDrawerOpen(true)
                              }}
                              className="text-[#00d9ff] hover:bg-[#00d9ff]/10 hover:text-[#00d9ff]/80"
                              title="View Profile"
                            >
                              <Eye className="h-4 w-4" />
                            </Button>
                            {protectedUser ? (
                              <span className="ml-2 text-sm text-gray-500">Protected</span>
                            ) : (
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => {
                                  setUserToDelete(user)
                                  setDeleteDialogOpen(true)
                                }}
                                className="text-red-400 hover:bg-red-900/20 hover:text-red-300"
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                            )}
                          </div>
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>

              {/* Pagination */}
              {totalPages > 1 && (
                <div className="mt-4 flex items-center justify-between border-t border-gray-800 pt-4">
                  <div className="text-sm text-gray-400">
                    Page {page} of {totalPages}
                  </div>
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setPage((p: number) => Math.max(1, p - 1))}
                      disabled={page === 1}
                      className="border-gray-700 text-gray-400 hover:text-white"
                    >
                      Previous
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setPage((p: number) => Math.min(totalPages, p + 1))}
                      disabled={page === totalPages}
                      className="border-gray-700 text-gray-400 hover:text-white"
                    >
                      Next
                    </Button>
                  </div>
                </div>
              )}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent className="border-gray-800 bg-gray-900">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-white">Delete User</AlertDialogTitle>
            <AlertDialogDescription className="text-gray-400">
              Are you sure you want to delete{" "}
              <strong className="text-white">{userToDelete?.email}</strong>?
              <br />
              <br />
              This will permanently delete:
              <ul className="mt-2 list-inside list-disc space-y-1 text-sm">
                <li>User profile and all Firestore data</li>
                <li>All interview sessions</li>
                <li>All learning progress and mastery data</li>
                <li>All analytics and usage data</li>
                <li>Firebase Auth account</li>
                <li>Pinecone vectors (if configured)</li>
              </ul>
              <br />
              <strong className="text-red-400">This action cannot be undone.</strong>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="border-gray-700 bg-gray-800 text-gray-300 hover:bg-gray-700">
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              disabled={deleting}
              className="bg-red-600 text-white hover:bg-red-700"
            >
              {deleting ? "Deleting..." : "Delete User"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* User Profile Drawer */}
      <UserProfileDrawer
        isOpen={profileDrawerOpen}
        onClose={() => {
          setProfileDrawerOpen(false)
          setSelectedUserId(null)
        }}
        userId={selectedUserId}
        token={authToken}
      />
    </div>
  )
}

/**
 * Admin Algorithm Research API
 *
 * GET /api/admin/algorithm-research
 * Returns comprehensive A/B testing comparison between SM-2 and FSRS algorithms
 *
 * Query params:
 * - refresh: boolean - Force regenerate aggregate comparison
 *
 * Requires admin authentication
 */

import { NextRequest, NextResponse } from "next/server"
import { adminDb } from "@/lib/firebase-admin"
import { verifyAdminAccess } from "@/lib/admin/middleware"
import {
  getAlgorithmDistribution,
  migrateExistingUsers,
  getAggregateComparison,
  generateAggregateComparison,
  getRecentEvents,
} from "@/lib/spaced-repetition"
import type { AlgorithmComparisonAggregate } from "@/lib/types"

export async function GET(request: NextRequest) {
  try {
    // Verify Admin SDK is initialized
    if (!adminDb) {
      return NextResponse.json(
        {
          success: false,
          error: "Firebase Admin SDK not initialized.",
        },
        { status: 500 }
      )
    }

    // Verify admin access
    const authResult = await verifyAdminAccess(request)
    if (!authResult.authorized) {
      return NextResponse.json(
        { success: false, error: authResult.error },
        { status: authResult.status || 403 }
      )
    }

    // Parse query params
    const { searchParams } = new URL(request.url)
    const forceRefresh = searchParams.get("refresh") === "true"

    // Get algorithm distribution
    const distribution = await getAlgorithmDistribution()

    // Get or generate aggregate comparison
    let comparison: AlgorithmComparisonAggregate | null = null

    if (forceRefresh) {
      comparison = await generateAggregateComparison()
    } else {
      comparison = await getAggregateComparison()

      // If no comparison exists or it's older than 1 hour, regenerate
      if (!comparison || isStale(comparison.last_updated, 60)) {
        comparison = await generateAggregateComparison()
      }
    }

    // Get recent events for detailed analysis
    const recentEvents = await getRecentEvents(50)

    // Calculate additional insights
    const insights = calculateInsights(comparison)

    return NextResponse.json({
      success: true,
      data: {
        distribution,
        comparison,
        recentEvents: recentEvents.map((event) => ({
          id: event.id || "",
          algorithm: event.algorithm || "sm2",
          score: event.score ?? 0,
          quality_rating: event.quality_rating ?? 0,
          pattern: event.pattern || "Unknown",
          difficulty: event.difficulty || "medium",
          pre_retention: event.pre_review?.predicted_retention ?? 0,
          actual_retention: event.actual_retention ?? false,
          retention_as_predicted: event.retention_as_predicted ?? false,
          interval_days: event.post_review?.new_interval_days ?? 0,
          timestamp: event.timestamp || new Date().toISOString(),
        })),
        insights,
        lastUpdated: comparison?.last_updated || new Date().toISOString(),
      },
    })
  } catch (error) {
    console.error("Admin algorithm research API error:", error)
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 }
    )
  }
}

/**
 * POST /api/admin/algorithm-research
 *
 * Actions:
 * - action: 'migrate' - Assign algorithms to users without one
 * - action: 'regenerate' - Force regenerate aggregate comparison
 */
export async function POST(request: NextRequest) {
  try {
    if (!adminDb) {
      return NextResponse.json(
        { success: false, error: "Firebase Admin SDK not initialized." },
        { status: 500 }
      )
    }

    const authResult = await verifyAdminAccess(request)
    if (!authResult.authorized) {
      return NextResponse.json(
        { success: false, error: authResult.error },
        { status: authResult.status || 403 }
      )
    }

    const body = await request.json()
    const { action } = body

    switch (action) {
      case "migrate": {
        const result = await migrateExistingUsers()
        return NextResponse.json({
          success: true,
          message: `Migrated ${result.migrated} users (SM-2: ${result.sm2_assigned}, FSRS: ${result.fsrs_assigned})`,
          data: result,
        })
      }

      case "regenerate": {
        const comparison = await generateAggregateComparison()
        return NextResponse.json({
          success: true,
          message: "Aggregate comparison regenerated",
          data: comparison,
        })
      }

      case "migrate-notification-preferences": {
        // Backfill notification preferences for existing users
        const profiles = await adminDb.collection("profiles").get()
        let migrated = 0
        const batch = adminDb.batch()

        profiles.docs.forEach((doc) => {
          const data = doc.data()
          if (!data.notification_preferences) {
            batch.update(doc.ref, {
              notification_preferences: {
                email_notifications_enabled: true,
                inactivity_reminders: true,
                spaced_repetition_reminders: true,
                milestone_celebrations: true,
                marketing_emails: false,
              },
            })
            migrated++
          }
        })

        if (migrated > 0) {
          await batch.commit()
        }

        return NextResponse.json({
          success: true,
          message: `Added notification preferences to ${migrated} users`,
          data: { migrated },
        })
      }

      case "backfill-research": {
        // Backfill research data from existing problem mastery and session summaries
        // This populates algorithm_research_metrics for users who practiced before tracking was added
        const result = await backfillResearchData()
        return NextResponse.json({
          success: true,
          message: `Backfilled research data for ${result.usersProcessed} users (${result.researchSummariesCreated} research summaries, ${result.userStatsUpdated} user_stats)`,
          data: result,
        })
      }

      default:
        return NextResponse.json(
          { success: false, error: `Unknown action: ${action}` },
          { status: 400 }
        )
    }
  } catch (error) {
    console.error("Admin algorithm research POST error:", error)
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 }
    )
  }
}

/**
 * Backfill research data from existing problem mastery and session summaries
 * This creates algorithm_research_metrics/summary documents for users who practiced
 * before research tracking was added, and updates user_stats if missing
 */
async function backfillResearchData(): Promise<{
  usersProcessed: number
  researchSummariesCreated: number
  userStatsUpdated: number
  errors: string[]
}> {
  const result = {
    usersProcessed: 0,
    researchSummariesCreated: 0,
    userStatsUpdated: 0,
    errors: [] as string[],
  }

  try {
    // Get all user profiles
    const profilesSnap = await adminDb.collection("profiles").get()
    const userIds = profilesSnap.docs.map((doc) => doc.id)

    for (const userId of userIds) {
      try {
        result.usersProcessed++

        // Get user's algorithm assignment
        const profileData = profilesSnap.docs.find((d) => d.id === userId)?.data()
        const algorithm = (profileData?.spaced_repetition_algorithm || "sm2") as "sm2" | "fsrs"

        // Check if research summary already exists
        const existingSummary = await adminDb
          .collection("algorithm_research_metrics")
          .doc(userId)
          .collection("summary")
          .doc("current")
          .get()

        // Get problem mastery data (unified collection)
        const masterySnap = await adminDb
          .collection("problem_mastery")
          .doc(userId)
          .collection("problems")
          .get()

        // Get session summaries
        const sessionsSnap = await adminDb
          .collection("users")
          .doc(userId)
          .collection("session_summaries")
          .orderBy("completedAt", "desc")
          .limit(100)
          .get()

        const sessions = sessionsSnap.docs.map((d) => d.data())
        const masteryDocs = masterySnap.docs.map((d) => d.data())

        // Skip if no data to backfill
        if (sessions.length === 0 && masteryDocs.length === 0) {
          continue
        }

        // Create research summary if it doesn't exist
        if (!existingSummary.exists && (sessions.length > 0 || masteryDocs.length > 0)) {
          const totalReviews = masteryDocs.reduce((sum, m) => sum + (m.review_count || 1), 0)
          const totalScore = sessions.reduce((sum, s) => sum + (s.performanceScore || 0), 0)
          const avgScore = sessions.length > 0 ? Math.round(totalScore / sessions.length) : 0
          const retainedCount = sessions.filter((s) => (s.performanceScore || 0) >= 56).length
          const retentionRate =
            sessions.length > 0 ? Math.round((retainedCount / sessions.length) * 100) : 0
          const problemsMastered = masteryDocs.filter(
            (m) => m.mastery_level === "mastered" || m.mastery_level === "reviewing"
          ).length

          const totalMinutes = sessions.reduce((sum, s) => sum + (s.durationMinutes || 0), 0)

          // Get first and last review dates
          const sortedSessions = [...sessions].sort(
            (a, b) =>
              new Date(a.completedAt || 0).getTime() - new Date(b.completedAt || 0).getTime()
          )
          const firstReview = sortedSessions[0]?.completedAt || new Date().toISOString()
          const lastReview =
            sortedSessions[sortedSessions.length - 1]?.completedAt || new Date().toISOString()

          // Calculate average time to mastery from actual mastery data
          // Time from first review to mastery level
          const masteredProblems = masteryDocs.filter(
            (m) => m.mastery_level === "mastered" || m.mastery_level === "reviewing"
          )
          let avgTimeToMastery: number | null = null
          if (masteredProblems.length > 0) {
            const timeToMasteryDays = masteredProblems
              .filter((m) => m.first_reviewed_at && m.mastered_at)
              .map((m) => {
                const first = new Date(m.first_reviewed_at).getTime()
                const mastered = new Date(m.mastered_at).getTime()
                return Math.max(1, Math.round((mastered - first) / (1000 * 60 * 60 * 24)))
              })

            if (timeToMasteryDays.length > 0) {
              avgTimeToMastery = Math.round(
                timeToMasteryDays.reduce((sum, d) => sum + d, 0) / timeToMasteryDays.length
              )
            }
          }
          // Fallback: estimate based on total days active vs problems mastered
          if (avgTimeToMastery === null) {
            const daysActive =
              new Set(sessions.map((s) => s.completedAt?.split("T")[0]).filter(Boolean)).size || 1
            avgTimeToMastery =
              problemsMastered > 0 ? Math.round(daysActive / problemsMastered) : null
          }

          // Calculate interval accuracy from mastery data
          // Compare predicted vs actual retention (score >= 56 means retained)
          const accuratePredictions = sessions.filter((s) => {
            const predicted = (s.predicted_retention || 50) >= 50 // Predicted to retain if >= 50%
            const actual = (s.performanceScore || 0) >= 56 // Actually retained if score >= 56
            return predicted === actual
          }).length
          const intervalAccuracy =
            sessions.length > 0 ? Math.round((accuratePredictions / sessions.length) * 100) : null

          const now = new Date().toISOString()
          const daysActiveSet = new Set(
            sessions.map((s) => s.completedAt?.split("T")[0]).filter(Boolean)
          )
          const daysActiveCount = daysActiveSet.size || 1

          const researchSummary = {
            user_id: userId,
            algorithm,
            algorithm_assigned_at: profileData?.created_at || now,
            algorithm_user_overridden: false,
            total_reviews: totalReviews,
            total_problems_seen: masteryDocs.length || sessions.length,
            total_time_spent_minutes: totalMinutes,
            total_days_active: daysActiveCount,
            lifetime_average_score: avgScore,
            lifetime_retention_rate: retentionRate,
            lifetime_lapse_rate: 100 - retentionRate,
            problems_mastered: problemsMastered,
            problems_learning: masteryDocs.length - problemsMastered,
            problems_struggling: 0,
            average_time_to_mastery_days: avgTimeToMastery,
            longest_streak: profileData?.longest_streak_days || 1,
            current_streak: profileData?.streak_days || 0,
            average_daily_reviews: totalReviews / Math.max(1, daysActiveCount),
            average_session_length_minutes:
              sessions.length > 0 ? Math.round(totalMinutes / sessions.length) : 0,
            weekly_averages: [],
            average_interval_accuracy: intervalAccuracy,
            interval_distribution: {
              "1-3_days": 0,
              "4-7_days": 0,
              "8-14_days": 0,
              "15-30_days": 0,
              "31-60_days": 0,
              "60+_days": 0,
            },
            first_review_at: firstReview,
            last_review_at: lastReview,
            created_at: now,
            updated_at: now,
          }

          // Populate interval distribution from mastery data
          for (const mastery of masteryDocs) {
            const interval = mastery.interval_days || 1
            if (interval <= 3) researchSummary.interval_distribution["1-3_days"]++
            else if (interval <= 7) researchSummary.interval_distribution["4-7_days"]++
            else if (interval <= 14) researchSummary.interval_distribution["8-14_days"]++
            else if (interval <= 30) researchSummary.interval_distribution["15-30_days"]++
            else if (interval <= 60) researchSummary.interval_distribution["31-60_days"]++
            else researchSummary.interval_distribution["60+_days"]++
          }

          await adminDb
            .collection("algorithm_research_metrics")
            .doc(userId)
            .collection("summary")
            .doc("current")
            .set(researchSummary)

          result.researchSummariesCreated++
        }

        // Check and update user_stats if missing or empty
        const userStatsDoc = await adminDb.collection("user_stats").doc(userId).get()
        const existingStats = userStatsDoc.data()

        if (!userStatsDoc.exists || (existingStats?.totalSessions || 0) === 0) {
          if (sessions.length > 0) {
            // Rebuild user_stats from session summaries
            const patternStats: Record<string, any> = {}
            const difficultyStats: Record<string, any> = {}
            let totalMinutes = 0
            let totalScore = 0

            for (const session of sessions) {
              totalMinutes += session.durationMinutes || 0
              totalScore += session.performanceScore || 0

              const pattern = session.pattern || "unknown"
              if (!patternStats[pattern]) {
                patternStats[pattern] = {
                  sessions: 0,
                  totalScore: 0,
                  averageScore: 0,
                  bestScore: 0,
                }
              }
              patternStats[pattern].sessions++
              patternStats[pattern].totalScore += session.performanceScore || 0
              patternStats[pattern].bestScore = Math.max(
                patternStats[pattern].bestScore,
                session.performanceScore || 0
              )

              const difficulty = session.difficulty || "medium"
              if (!difficultyStats[difficulty]) {
                difficultyStats[difficulty] = { sessions: 0, totalScore: 0, averageScore: 0 }
              }
              difficultyStats[difficulty].sessions++
              difficultyStats[difficulty].totalScore += session.performanceScore || 0
            }

            // Calculate averages
            for (const p of Object.values(patternStats) as any[]) {
              p.averageScore = p.sessions > 0 ? Math.round(p.totalScore / p.sessions) : 0
            }
            for (const d of Object.values(difficultyStats) as any[]) {
              d.averageScore = d.sessions > 0 ? Math.round(d.totalScore / d.sessions) : 0
            }

            const userStats = {
              userId,
              totalSessions: sessions.length,
              totalPracticeMinutes: totalMinutes,
              totalScore,
              averageScore: sessions.length > 0 ? Math.round(totalScore / sessions.length) : 0,
              patternStats,
              difficultyStats,
              lastSessionAt: sessions[0]?.completedAt,
              createdAt: new Date(),
              updatedAt: new Date(),
            }

            await adminDb.collection("user_stats").doc(userId).set(userStats, { merge: true })
            result.userStatsUpdated++
          }
        }
      } catch (userError) {
        result.errors.push(
          `User ${userId}: ${userError instanceof Error ? userError.message : "Unknown error"}`
        )
      }
    }

    // Regenerate aggregate comparison with new data
    await generateAggregateComparison()
  } catch (error) {
    result.errors.push(`Global error: ${error instanceof Error ? error.message : "Unknown error"}`)
  }

  return result
}

/**
 * Check if timestamp is older than N minutes
 */
function isStale(timestamp: string, minutes: number): boolean {
  const then = new Date(timestamp).getTime()
  const now = Date.now()
  return now - then > minutes * 60 * 1000
}

/**
 * Calculate additional insights from the comparison data
 */
function calculateInsights(comparison: AlgorithmComparisonAggregate | null) {
  if (!comparison) {
    return {
      summary: "Not enough data for insights yet.",
      recommendations: [],
      keyFindings: [],
    }
  }

  const { sm2, fsrs } = comparison
  const { comparison: comp } = comparison

  const keyFindings: string[] = []
  const recommendations: string[] = []

  // Sample size check
  if (!comp.sufficient_sample_size) {
    keyFindings.push(
      `Sample size insufficient: SM-2 has ${sm2.total_users} users, FSRS has ${fsrs.total_users} users. Need 30+ each for valid comparison.`
    )
    recommendations.push("Continue collecting data before drawing conclusions.")
  }

  // Retention rate comparison
  if (Math.abs(comp.retention_rate_difference) >= 5) {
    const winner = comp.retention_rate_difference > 0 ? "FSRS" : "SM-2"
    const diff = Math.abs(comp.retention_rate_difference)
    const winnerRate = winner === "FSRS" ? fsrs.average_retention_rate : sm2.average_retention_rate
    const loserRate = winner === "FSRS" ? sm2.average_retention_rate : fsrs.average_retention_rate
    keyFindings.push(
      `${winner} shows ${diff}% higher retention rate (${winnerRate}% vs ${loserRate}%)`
    )
  }

  // Score comparison
  if (Math.abs(comp.average_score_difference) >= 3) {
    const winner = comp.average_score_difference > 0 ? "FSRS" : "SM-2"
    const diff = Math.abs(comp.average_score_difference)
    keyFindings.push(`${winner} users score ${diff} points higher on average`)
  }

  // Time to mastery
  if (comp.time_to_mastery_difference_days > 2) {
    keyFindings.push(
      `FSRS users master problems ${comp.time_to_mastery_difference_days} days faster on average`
    )
  } else if (comp.time_to_mastery_difference_days < -2) {
    keyFindings.push(
      `SM-2 users master problems ${Math.abs(comp.time_to_mastery_difference_days)} days faster on average`
    )
  }

  // Engagement
  if (Math.abs(comp.engagement_difference) >= 0.5) {
    const winner = comp.engagement_difference > 0 ? "FSRS" : "SM-2"
    keyFindings.push(
      `${winner} users complete ${Math.abs(comp.engagement_difference).toFixed(1)} more reviews per day`
    )
  }

  // Churn analysis
  if (sm2.churn_rate_30d > fsrs.churn_rate_30d + 10) {
    keyFindings.push(
      `SM-2 has ${sm2.churn_rate_30d - fsrs.churn_rate_30d}% higher 30-day churn rate`
    )
    recommendations.push("Consider switching new users to FSRS to reduce churn.")
  } else if (fsrs.churn_rate_30d > sm2.churn_rate_30d + 10) {
    keyFindings.push(
      `FSRS has ${fsrs.churn_rate_30d - sm2.churn_rate_30d}% higher 30-day churn rate`
    )
  }

  // Overall winner
  let summary = "Results are inconclusive. Need more data."
  if (comp.overall_winner && comp.confidence_level) {
    summary = `${comp.overall_winner.toUpperCase()} appears to be the better algorithm with ${comp.confidence_level}% confidence.`

    if (comp.overall_winner === "fsrs") {
      recommendations.push("Consider migrating all new users to FSRS algorithm.")
      recommendations.push("Prepare migration plan for existing SM-2 users.")
    } else {
      recommendations.push("Keep SM-2 as the default algorithm.")
      recommendations.push("Investigate why FSRS is underperforming - may need parameter tuning.")
    }
  }

  return {
    summary,
    keyFindings,
    recommendations,
  }
}

import { NextRequest, NextResponse } from "next/server"
import { FieldPath } from "firebase-admin/firestore"
import { adminDb, adminAuth } from "@/lib/firebase-admin"
import {
  getFirebaseAnalyticsOverview,
  getFirebaseAnalyticsEvents,
  getFirebaseAnalyticsAcquisition,
  getFirebaseAnalyticsConversions,
} from "@/lib/firebase-analytics-admin"
import { verifyAdminAccess, parseAdminQueryParams } from "@/lib/admin/middleware"
import { calculateMRR, calculateARR, getMonthlyPrice } from "@/lib/pricing"
import { adminCache, getCacheKey, CACHE_TTL } from "@/lib/admin/cache"
import {
  format,
  eachDayOfInterval,
  eachWeekOfInterval,
  eachMonthOfInterval,
  startOfDay,
  startOfWeek,
  startOfMonth,
  parseISO,
} from "date-fns"

type UserForTimeSeries = { createdAt: string; tier: string }

/**
 * Generate time-series data for charts
 */
async function generateTimeSeriesData(
  usersForSeries: UserForTimeSeries[],
  sessionsSnapshot: FirebaseFirestore.QuerySnapshot | { docs: any[] },
  startDate: Date | null,
  timeRange: string
): Promise<{
  users: Array<{ date: string; total: number; free: number; pro: number; enterprise: number }>
  sessions: Array<{ date: string; total: number; completed: number }>
  revenue: Array<{ date: string; mrr: number }>
}> {
  const now = new Date()
  const start = startDate || new Date(now.getFullYear() - 1, 0, 1)

  // Determine interval based on time range
  let intervals: Date[]
  let dateFormat: string
  let getIntervalStart: (date: Date) => Date

  if (timeRange === "7d") {
    intervals = eachDayOfInterval({ start, end: now })
    dateFormat = "MMM d"
    getIntervalStart = startOfDay
  } else if (timeRange === "30d") {
    intervals = eachDayOfInterval({ start, end: now })
    dateFormat = "MMM d"
    getIntervalStart = startOfDay
  } else if (timeRange === "90d") {
    intervals = eachWeekOfInterval({ start, end: now })
    dateFormat = "MMM d"
    getIntervalStart = startOfWeek
  } else {
    intervals = eachMonthOfInterval({ start, end: now })
    dateFormat = "MMM yyyy"
    getIntervalStart = startOfMonth
  }

  // Initialize data structures
  const usersByDate: Record<
    string,
    { total: number; free: number; pro: number; enterprise: number }
  > = {}
  const sessionsByDate: Record<string, { total: number; completed: number }> = {}

  // Initialize all intervals
  intervals.forEach((date) => {
    const key = format(date, "yyyy-MM-dd")
    usersByDate[key] = { total: 0, free: 0, pro: 0, enterprise: 0 }
    sessionsByDate[key] = { total: 0, completed: 0 }
  })

  // Process users for growth (from auth + profiles merge)
  usersForSeries.forEach((user) => {
    const createdAt = user.createdAt
    if (createdAt) {
      try {
        const date = typeof createdAt === "string" ? parseISO(createdAt) : new Date(createdAt)
        const intervalStart = getIntervalStart(date)
        const key = format(intervalStart, "yyyy-MM-dd")

        if (usersByDate[key]) {
          usersByDate[key].total++
          const tier = user.tier || "free"
          if (tier === "pro") usersByDate[key].pro++
          else if (tier === "enterprise") usersByDate[key].enterprise++
          else usersByDate[key].free++
        }
      } catch {
        // Skip invalid dates
      }
    }
  })

  // Process sessions
  if (sessionsSnapshot.docs) {
    sessionsSnapshot.docs.forEach((doc: any) => {
      const session = doc.data()
      const startedAt = session.started_at

      if (startedAt) {
        try {
          const date =
            typeof startedAt === "string"
              ? parseISO(startedAt)
              : startedAt.toDate?.() || new Date(startedAt)

          const intervalStart = getIntervalStart(date)
          const key = format(intervalStart, "yyyy-MM-dd")

          if (sessionsByDate[key]) {
            sessionsByDate[key].total++
            if (session.completed_at) {
              sessionsByDate[key].completed++
            }
          }
        } catch {
          // Skip invalid dates
        }
      }
    })
  }

  // Convert to arrays with cumulative counts for users
  const cumulativeUsers = { total: 0, free: 0, pro: 0, enterprise: 0 }
  const users = intervals.map((date) => {
    const key = format(date, "yyyy-MM-dd")
    const data = usersByDate[key] || { total: 0, free: 0, pro: 0, enterprise: 0 }

    cumulativeUsers.total += data.total
    cumulativeUsers.free += data.free
    cumulativeUsers.pro += data.pro
    cumulativeUsers.enterprise += data.enterprise

    return {
      date: format(date, dateFormat),
      total: cumulativeUsers.total,
      free: cumulativeUsers.free,
      pro: cumulativeUsers.pro,
      enterprise: cumulativeUsers.enterprise,
    }
  })

  // Sessions are not cumulative
  const sessions = intervals.map((date) => {
    const key = format(date, "yyyy-MM-dd")
    const data = sessionsByDate[key] || { total: 0, completed: 0 }
    return {
      date: format(date, dateFormat),
      total: data.total,
      completed: data.completed,
    }
  })

  // Calculate revenue based on cumulative pro/enterprise users
  const revenue = users.map((u) => ({
    date: u.date,
    mrr: u.pro * getMonthlyPrice("pro") + u.enterprise * getMonthlyPrice("enterprise"),
  }))

  return { users, sessions, revenue }
}

/**
 * Admin Analytics API
 * Returns aggregate metrics for admin dashboard
 *
 * Requires admin authentication via Firebase ID token
 */

export async function GET(request: NextRequest) {
  try {
    // Verify Admin SDK is initialized
    if (!adminDb) {
      return NextResponse.json(
        {
          success: false,
          error: "Firebase Admin SDK not initialized. Check server configuration.",
        },
        { status: 500 }
      )
    }

    // Verify admin access using RBAC middleware
    const authResult = await verifyAdminAccess(request)
    if (!authResult.authorized) {
      return NextResponse.json(
        { success: false, error: authResult.error },
        { status: authResult.status || 403 }
      )
    }

    // Parse query params using middleware helper
    const { timeRange, startDate } = parseAdminQueryParams(request)

    // Check cache first
    const cacheKey = getCacheKey("analytics", { timeRange })
    const cachedResponse = adminCache.get<any>(cacheKey)
    if (cachedResponse) {
      return NextResponse.json({
        ...cachedResponse,
        cached: true,
      })
    }

    // Fetch all users from Firebase Auth (Google, GitHub, etc.) - matches user list
    const authUsers: import("firebase-admin/auth").UserRecord[] = []
    let pageToken: string | undefined
    try {
      do {
        const result = await adminAuth.listUsers(1000, pageToken)
        authUsers.push(...result.users)
        pageToken = result.pageToken
      } while (pageToken)
    } catch (error) {
      console.error("Error fetching auth users:", error)
    }

    const totalUsers = authUsers.length

    // Build profile map for tier data
    const profileMap = new Map<string, { subscription_tier?: string; created_at?: string }>()
    const PROFILE_BATCH = 30
    for (let i = 0; i < authUsers.length; i += PROFILE_BATCH) {
      const batch = authUsers.slice(i, i + PROFILE_BATCH)
      const ids = batch.map((u) => u.uid)
      const profilesSnap = await adminDb
        .collection("profiles")
        .where(FieldPath.documentId(), "in", ids)
        .get()
      profilesSnap.docs.forEach((doc) => profileMap.set(doc.id, doc.data()))
    }

    // Count by subscription tier (auth users without profile = free)
    const tierCounts = { free: 0, pro: 0, enterprise: 0 }
    authUsers.forEach((authUser) => {
      const profile = profileMap.get(authUser.uid)
      const tier = profile?.subscription_tier || "free"
      if (tier in tierCounts) {
        tierCounts[tier as keyof typeof tierCounts]++
      }
    })

    // Build user list for time-series (createdAt from auth or profile, tier from profile)
    const usersForTimeSeries: UserForTimeSeries[] = authUsers.map((authUser) => {
      const profile = profileMap.get(authUser.uid)
      const createdAt =
        authUser.metadata?.creationTime || profile?.created_at || new Date().toISOString()
      const tier = profile?.subscription_tier || "free"
      return { createdAt, tier }
    })

    // Fetch sessions (with time range filter if applicable)
    let sessionsSnapshot
    try {
      if (startDate) {
        sessionsSnapshot = await adminDb
          .collection("interview_sessions")
          .where("started_at", ">=", startDate.toISOString())
          .get()
      } else {
        sessionsSnapshot = await adminDb.collection("interview_sessions").get()
      }
    } catch (error) {
      console.error("Error fetching sessions:", error)
      sessionsSnapshot = { size: 0, docs: [] } as any
    }

    const totalSessions = sessionsSnapshot.size || 0
    let completedSessions = 0
    let totalPerformanceScore = 0
    let sessionsWithScore = 0

    const sessionsByType: Record<string, number> = {}
    const sessionsByDifficulty: Record<string, number> = {}

    if (sessionsSnapshot.docs) {
      sessionsSnapshot.docs.forEach((doc: any) => {
        const session = doc.data()

        if (session.completed_at) {
          completedSessions++
        }

        if (session.performance_score !== undefined) {
          totalPerformanceScore += session.performance_score
          sessionsWithScore++
        }

        // Count by type
        const type = session.type || "unknown"
        sessionsByType[type] = (sessionsByType[type] || 0) + 1

        // Count by difficulty
        const difficulty = session.difficulty || "unknown"
        sessionsByDifficulty[difficulty] = (sessionsByDifficulty[difficulty] || 0) + 1
      })
    }

    const avgPerformanceScore =
      sessionsWithScore > 0 ? Math.round(totalPerformanceScore / sessionsWithScore) : 0

    // Fetch analytics events
    let eventsSnapshot
    try {
      if (startDate) {
        eventsSnapshot = await adminDb
          .collection("analytics_events")
          .where("timestamp", ">=", startDate.toISOString())
          .get()
      } else {
        eventsSnapshot = await adminDb.collection("analytics_events").get()
      }
    } catch (error) {
      console.error("Error fetching analytics events:", error)
      eventsSnapshot = { size: 0, docs: [] } as any
    }

    const eventCounts: Record<string, number> = {}
    let totalCodeExecutions = 0
    let passedCodeExecutions = 0

    if (eventsSnapshot.docs) {
      eventsSnapshot.docs.forEach((doc: any) => {
        const event = doc.data()
        const eventName = event.event_name || "unknown"
        eventCounts[eventName] = (eventCounts[eventName] || 0) + 1

        if (eventName === "code_execution") {
          totalCodeExecutions++
          if (event.properties?.passed) {
            passedCodeExecutions++
          }
        }
      })
    }

    const codeExecutionPassRate =
      totalCodeExecutions > 0 ? Math.round((passedCodeExecutions / totalCodeExecutions) * 100) : 0

    // Calculate revenue metrics using centralized pricing
    const mrr = calculateMRR(tierCounts)

    // Fetch recent errors (last 100) - handle potential index error gracefully
    let recentErrors: Array<{
      timestamp: string
      errorType?: string
      errorMessage?: string
      page?: string
      userId?: string
    }> = []

    try {
      const errorsSnapshot = await adminDb
        .collection("analytics_events")
        .where("event_name", "==", "error")
        .orderBy("timestamp", "desc")
        .limit(100)
        .get()

      recentErrors = errorsSnapshot.docs.map((doc) => {
        const data = doc.data()
        return {
          timestamp: data.timestamp,
          errorType: data.properties?.errorType,
          errorMessage: data.properties?.errorMessage,
          page: data.properties?.page,
          userId: data.properties?.userId,
        }
      })
    } catch (error) {
      console.error("Error fetching errors (may need composite index):", error)
      // Try without orderBy as fallback
      try {
        const errorsSnapshot = await adminDb
          .collection("analytics_events")
          .where("event_name", "==", "error")
          .limit(100)
          .get()

        recentErrors = errorsSnapshot.docs
          .map((doc) => {
            const data = doc.data()
            return {
              timestamp: data.timestamp,
              errorType: data.properties?.errorType,
              errorMessage: data.properties?.errorMessage,
              page: data.properties?.page,
              userId: data.properties?.userId,
            }
          })
          .sort((a, b) => (b.timestamp || "").localeCompare(a.timestamp || ""))
          .slice(0, 100)
      } catch (fallbackError) {
        console.error("Error fetching errors (fallback):", fallbackError)
      }
    }

    // Generate time-series data for charts
    const timeSeries = await generateTimeSeriesData(
      usersForTimeSeries,
      sessionsSnapshot,
      startDate,
      timeRange
    )

    // Fetch Firebase Analytics data (if configured)
    const days = timeRange === "7d" ? 7 : timeRange === "30d" ? 30 : timeRange === "90d" ? 90 : 365
    const firebaseAnalytics = await getFirebaseAnalyticsOverview(days)
    const firebaseEvents = await getFirebaseAnalyticsEvents(
      [
        "sign_up",
        "login",
        "session_start",
        "session_complete",
        "purchase",
        "code_execution",
        "ai_interaction",
      ],
      days
    )
    const firebaseAcquisition = await getFirebaseAnalyticsAcquisition(days)
    const firebaseConversions = await getFirebaseAnalyticsConversions(days)

    const responseData = {
      success: true,
      timeRange,
      metrics: {
        users: {
          total: totalUsers,
          byTier: tierCounts,
        },
        sessions: {
          total: totalSessions,
          completed: completedSessions,
          inProgress: totalSessions - completedSessions,
          avgPerformanceScore,
          byType: sessionsByType,
          byDifficulty: sessionsByDifficulty,
        },
        revenue: {
          mrr,
          arr: calculateARR(mrr),
        },
        analytics: {
          totalEvents: eventsSnapshot.size || 0,
          byEventType: eventCounts,
          codeExecutions: {
            total: totalCodeExecutions,
            passed: passedCodeExecutions,
            passRate: codeExecutionPassRate,
          },
        },
        errors: {
          total: recentErrors.length,
          recent: recentErrors,
        },
        // Firebase Analytics data (if available)
        firebaseAnalytics: firebaseAnalytics
          ? {
              activeUsers: firebaseAnalytics.activeUsers,
              newUsers: firebaseAnalytics.newUsers,
              pageViews: firebaseAnalytics.pageViews,
              sessions: firebaseAnalytics.sessions,
              avgSessionDuration: firebaseAnalytics.avgSessionDuration,
              bounceRate: firebaseAnalytics.bounceRate,
              engagementRate: firebaseAnalytics.engagementRate,
              eventsByType: firebaseAnalytics.eventsByType,
              acquisition: firebaseAcquisition || [],
              conversions: firebaseConversions || {},
            }
          : null,
        // Time-series data for charts
        timeSeries,
      },
    }

    // Cache the response for 30 seconds
    adminCache.set(cacheKey, responseData, CACHE_TTL.ANALYTICS)

    return NextResponse.json(responseData)
  } catch (error) {
    console.error("Admin analytics API error:", error)
    const errorMessage = error instanceof Error ? error.message : "Failed to fetch analytics"
    const errorStack = error instanceof Error ? error.stack : undefined
    console.error("Error details:", { errorMessage, errorStack })
    return NextResponse.json(
      {
        success: false,
        error: errorMessage,
        details: process.env.NODE_ENV === "development" ? errorStack : undefined,
      },
      { status: 500 }
    )
  }
}

/**
 * Announcements API
 *
 * Manage system announcements for user communication
 * Supports different announcement types: banner, modal, toast
 */

import { NextRequest, NextResponse } from "next/server"
import { adminDb } from "@/lib/firebase-admin"
import { verifyToken, getAdminRole } from "@/lib/admin/rbac"
import { Timestamp } from "firebase-admin/firestore"
import type { FullAnnouncement } from "@/lib/types/announcements"

export const dynamic = "force-dynamic"

// Re-export for backwards compatibility
export type Announcement = FullAnnouncement

// GET - List announcements
export async function GET(request: NextRequest) {
  try {
    const authHeader = request.headers.get("Authorization")
    if (!authHeader?.startsWith("Bearer ")) {
      return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 })
    }

    const token = authHeader.substring(7)
    const auth = await verifyToken(token)
    if (!auth.valid || !auth.userId) {
      return NextResponse.json({ success: false, error: "Invalid token" }, { status: 401 })
    }

    const role = await getAdminRole(auth.userId)
    if (!role) {
      return NextResponse.json(
        { success: false, error: "Insufficient permissions" },
        { status: 403 }
      )
    }

    if (!adminDb) {
      return NextResponse.json({ success: false, error: "Database not available" }, { status: 500 })
    }

    const { searchParams } = new URL(request.url)
    const activeOnly = searchParams.get("active") === "true"
    const limit = Math.min(parseInt(searchParams.get("limit") || "50"), 100)

    let query = adminDb.collection("announcements").orderBy("createdAt", "desc")

    if (activeOnly) {
      query = query.where("active", "==", true)
    }

    query = query.limit(limit)

    const snapshot = await query.get()
    const announcements: Announcement[] = snapshot.docs.map((doc) => {
      const data = doc.data()
      return {
        id: doc.id,
        title: data.title || "",
        message: data.message || "",
        type: data.type || "banner",
        priority: data.priority || "info",
        targetAudience: data.targetAudience || "all",
        targetUserIds: data.targetUserIds || [],
        startDate: data.startDate?.toDate?.()?.toISOString() || data.startDate,
        endDate: data.endDate?.toDate?.()?.toISOString() || data.endDate,
        dismissible: data.dismissible ?? true,
        active: data.active ?? false,
        createdBy: data.createdBy,
        createdAt: data.createdAt?.toDate?.()?.toISOString() || data.createdAt,
        updatedAt: data.updatedAt?.toDate?.()?.toISOString() || data.updatedAt,
        views: data.views || 0,
        dismissals: data.dismissals || 0,
        cta: data.cta,
      }
    })

    // Get stats
    const activeCount = announcements.filter((a) => a.active).length
    const totalViews = announcements.reduce((sum, a) => sum + a.views, 0)
    const totalDismissals = announcements.reduce((sum, a) => sum + a.dismissals, 0)

    return NextResponse.json({
      success: true,
      announcements,
      stats: {
        total: announcements.length,
        active: activeCount,
        totalViews,
        totalDismissals,
      },
    })
  } catch (error) {
    console.error("[Announcements API] GET Error:", error)
    return NextResponse.json(
      { success: false, error: "Failed to fetch announcements" },
      { status: 500 }
    )
  }
}

