/**
 * Admin Audit Log API
 *
 * Provides access to admin action audit logs with filtering, pagination, and export
 */

import { NextRequest, NextResponse } from "next/server"
import { adminDb } from "@/lib/firebase-admin"
import { verifyToken, getAdminRole, PERMISSIONS, hasPermission } from "@/lib/admin/rbac"

export const dynamic = "force-dynamic"

interface AuditLogEntry {
  id: string
  adminId: string
  adminEmail?: string
  action: string
  details: Record<string, any>
  timestamp: string
  ip?: string
  userAgent?: string
}

export async function GET(request: NextRequest) {
  try {
    // Verify auth
    const authHeader = request.headers.get("Authorization")
    if (!authHeader?.startsWith("Bearer ")) {
      return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 })
    }

    const token = authHeader.substring(7)
    const auth = await verifyToken(token)
    if (!auth.valid || !auth.userId) {
      return NextResponse.json({ success: false, error: "Invalid token" }, { status: 401 })
    }

    // Check admin role (only admins and super_admins can view audit logs)
    const role = await getAdminRole(auth.userId)
    if (!role || !["super_admin", "admin"].includes(role)) {
      return NextResponse.json(
        { success: false, error: "Insufficient permissions" },
        { status: 403 }
      )
    }

    if (!adminDb) {
      return NextResponse.json({ success: false, error: "Database not available" }, { status: 500 })
    }

    // Parse query params
    const { searchParams } = new URL(request.url)
    const limit = Math.min(parseInt(searchParams.get("limit") || "50"), 200)
    const cursor = searchParams.get("cursor")
    const action = searchParams.get("action")
    const adminId = searchParams.get("adminId")
    const startDate = searchParams.get("startDate")
    const endDate = searchParams.get("endDate")

    // Build query
    let query = adminDb.collection("admin_audit_log").orderBy("timestamp", "desc")

    // Apply filters
    if (action) {
      query = query.where("action", "==", action)
    }
    if (adminId) {
      query = query.where("adminId", "==", adminId)
    }

    // Date range filtering
    if (startDate) {
      query = query.where("timestamp", ">=", new Date(startDate))
    }
    if (endDate) {
      query = query.where("timestamp", "<=", new Date(endDate))
    }

    // Pagination
    if (cursor) {
      const cursorDoc = await adminDb.collection("admin_audit_log").doc(cursor).get()
      if (cursorDoc.exists) {
        query = query.startAfter(cursorDoc)
      }
    }

    query = query.limit(limit + 1) // Get one extra to check for more pages

    const snapshot = await query.get()
    const hasMore = snapshot.docs.length > limit
    const docs = hasMore ? snapshot.docs.slice(0, -1) : snapshot.docs

    const logs: AuditLogEntry[] = docs.map((doc) => {
      const data = doc.data()
      return {
        id: doc.id,
        adminId: data.adminId,
        adminEmail: data.adminEmail,
        action: data.action,
        details: data.details || {},
        timestamp: data.timestamp?.toDate?.()?.toISOString() || data.timestamp,
        ip: data.ip,
        userAgent: data.userAgent,
      }
    })

    // Get unique actions for filter dropdown
    const actionsSnapshot = await adminDb
      .collection("admin_audit_log")
      .orderBy("timestamp", "desc")
      .limit(500)
      .get()

    const uniqueActions = [...new Set(actionsSnapshot.docs.map((d) => d.data().action as string))]

    // Get summary stats
    const now = new Date()
    const last24h = new Date(now.getTime() - 24 * 60 * 60 * 1000)
    const last7d = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000)

    const stats24hSnapshot = await adminDb
      .collection("admin_audit_log")
      .where("timestamp", ">=", last24h)
      .get()

    const stats7dSnapshot = await adminDb
      .collection("admin_audit_log")
      .where("timestamp", ">=", last7d)
      .get()

    return NextResponse.json({
      success: true,
      logs,
      pagination: {
        hasMore,
        nextCursor: hasMore && docs.length > 0 ? docs[docs.length - 1].id : null,
      },
      filters: {
        actions: uniqueActions,
      },
      stats: {
        last24h: stats24hSnapshot.size,
        last7d: stats7dSnapshot.size,
        total: snapshot.size,
      },
    })
  } catch (error) {
    console.error("[Admin Audit API] Error:", error)
    return NextResponse.json(
      { success: false, error: "Failed to fetch audit logs" },
      { status: 500 }
    )
  }
}

// Export audit logs as CSV
export async function POST(request: NextRequest) {
  try {
    // Verify auth
    const authHeader = request.headers.get("Authorization")
    if (!authHeader?.startsWith("Bearer ")) {
      return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 })
    }

    const token = authHeader.substring(7)
    const auth = await verifyToken(token)
    if (!auth.valid || !auth.userId) {
      return NextResponse.json({ success: false, error: "Invalid token" }, { status: 401 })
    }

    // Only super_admin can export audit logs
    const role = await getAdminRole(auth.userId)
    if (role !== "super_admin") {
      return NextResponse.json(
        { success: false, error: "Only super admins can export audit logs" },
        { status: 403 }
      )
    }

    if (!adminDb) {
      return NextResponse.json({ success: false, error: "Database not available" }, { status: 500 })
    }

    const body = await request.json()
    const { startDate, endDate, format = "csv" } = body

    // Build query
    let query = adminDb.collection("admin_audit_log").orderBy("timestamp", "desc")

    if (startDate) {
      query = query.where("timestamp", ">=", new Date(startDate))
    }
    if (endDate) {
      query = query.where("timestamp", "<=", new Date(endDate))
    }

    // Limit export to 10000 records
    query = query.limit(10000)

    const snapshot = await query.get()

    const logs = snapshot.docs.map((doc) => {
      const data = doc.data()
      return {
        id: doc.id,
        adminId: data.adminId,
        adminEmail: data.adminEmail || "",
        action: data.action,
        details: JSON.stringify(data.details || {}),
        timestamp: data.timestamp?.toDate?.()?.toISOString() || data.timestamp,
        ip: data.ip || "",
      }
    })

    if (format === "csv") {
      // Generate CSV
      const headers = ["ID", "Timestamp", "Admin ID", "Admin Email", "Action", "Details", "IP"]
      const rows = logs.map((log) => [
        log.id,
        log.timestamp,
        log.adminId,
        log.adminEmail,
        log.action,
        log.details,
        log.ip,
      ])

      const csv = [
        headers.join(","),
        ...rows.map((row) => row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(",")),
      ].join("\n")

      return new NextResponse(csv, {
        headers: {
          "Content-Type": "text/csv",
          "Content-Disposition": `attachment; filename="audit-logs-${new Date().toISOString().split("T")[0]}.csv"`,
        },
      })
    }

    return NextResponse.json({
      success: true,
      logs,
      exportedAt: new Date().toISOString(),
      count: logs.length,
    })
  } catch (error) {
    console.error("[Admin Audit Export API] Error:", error)
    return NextResponse.json(
      { success: false, error: "Failed to export audit logs" },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from "next/server"
import { adminDb } from "@/lib/firebase-admin"
import {
  verifyAdminAccess,
  requirePermission,
  successResponse,
  errorResponse,
  unauthorizedResponse,
} from "@/lib/admin/middleware"
import { PERMISSIONS } from "@/lib/admin/rbac"
import { logAdminAction } from "@/lib/admin/audit"

export const dynamic = "force-dynamic"
export const maxDuration = 300

const COLLECTIONS = [
  { name: "interview_sessions", field: "user_id" },
  { name: "profile_quota", field: "user_id" },
  { name: "payment_history", field: "user_id" },
  { name: "email_notifications", field: "user_id" },
  { name: "promo_code_usage", field: "userId" },
  { name: "sessions", field: "userId" },
  { name: "session_vectors", field: "userId" },
  { name: "user_learning_state", field: null, idIsUserId: true },
  { name: "problem_mastery", field: "userId" },
  { name: "analytics_events", field: "userId" },
  { name: "user_roadmaps", field: "userId" },
  { name: "performance_profiles", field: "userId" },
]

/**
 * Check authorization - supports both Firebase token (admin) and cron secret
 */
async function checkAuth(req: NextRequest): Promise<{
  authorized: boolean
  adminId?: string
  source: 'admin' | 'cron'
  error?: string
}> {
  const authHeader = req.headers.get("Authorization")

  // Check for cron secret (for automated jobs)
  const cronSecret = process.env.CRON_SECRET
  if (cronSecret && authHeader === `Bearer ${cronSecret}`) {
    return { authorized: true, adminId: 'cron-job', source: 'cron' }
  }

  // Check for admin token with proper RBAC
  const authResult = await requirePermission(req, PERMISSIONS.MANAGE_SETTINGS)
  if (authResult.authorized) {
    return {
      authorized: true,
      adminId: authResult.context!.userId,
      source: 'admin',
    }
  }

  return { authorized: false, source: 'admin', error: authResult.error }
}

// GET = dry run (preview orphans)
export async function GET(req: NextRequest) {
  const auth = await checkAuth(req)
  if (!auth.authorized) {
    return unauthorizedResponse(auth.error || 'Unauthorized', 401)
  }

  const result = await findOrphans(false)
  return successResponse(result)
}

// POST = delete orphans
export async function POST(req: NextRequest) {
  const auth = await checkAuth(req)
  if (!auth.authorized) {
    return unauthorizedResponse(auth.error || 'Unauthorized', 401)
  }

  const result = await findOrphans(true)

  // Log the action
  if (auth.adminId) {
    await logAdminAction(auth.adminId, 'cleanup_orphans', {
      source: auth.source,
      results: result.results,
      totalDeleted: result.totalDeleted,
    })
  }

  return successResponse(result)
}

async function findOrphans(deleteMode: boolean) {
  const profiles = await adminDb.collection("profiles").get()
  const validIds = new Set(profiles.docs.map(d => d.id))

  const results: Record<string, number> = {}
  let totalDeleted = 0

  for (const col of COLLECTIONS) {
    const snap = await adminDb.collection(col.name).get()
    const orphans = snap.docs.filter(doc => {
      const uid = col.idIsUserId ? doc.id : doc.data()[col.field!]
      return uid && !validIds.has(uid)
    })

    results[col.name] = orphans.length

    if (deleteMode && orphans.length > 0) {
      const batch = adminDb.batch()
      orphans.forEach(doc => batch.delete(doc.ref))
      await batch.commit()
      totalDeleted += orphans.length
    }
  }

  return { mode: deleteMode ? "deleted" : "preview", results, totalDeleted, validProfiles: validIds.size }
}

import { NextRequest, NextResponse } from "next/server"
import { adminDb } from "@/lib/firebase-admin"
import { verifyAdminAccess } from "@/lib/admin/middleware"
import { format, startOfMonth, startOfWeek, differenceInWeeks, differenceInMonths, subMonths } from "date-fns"

interface CohortData {
  cohort: string
  size: number
  retention: number[]
}

/**
 * Cohort Analytics API
 * Returns user retention cohort data for the admin dashboard
 */
export async function GET(request: NextRequest) {
  try {
    // Verify admin access
    const authResult = await verifyAdminAccess(request)
    if (!authResult.authorized) {
      return NextResponse.json(
        { success: false, error: authResult.error },
        { status: authResult.status || 403 }
      )
    }

    if (!adminDb) {
      return NextResponse.json(
        { success: false, error: "Database not available" },
        { status: 500 }
      )
    }

    const { searchParams } = new URL(request.url)
    const cohortType = searchParams.get("type") || "monthly" // weekly or monthly
    const numCohorts = parseInt(searchParams.get("cohorts") || "6", 10)

    // Get all users with their signup dates
    const profilesSnapshot = await adminDb.collection("profiles").get()
    const sessionsSnapshot = await adminDb.collection("interview_sessions").get()

    // Build user activity map: userId -> Set of activity dates
    const userActivity: Map<string, Set<string>> = new Map()

    sessionsSnapshot.docs.forEach((doc) => {
      const session = doc.data()
      const userId = session.user_id
      const startedAt = session.started_at

      if (userId && startedAt) {
        try {
          const date = typeof startedAt === "string"
            ? new Date(startedAt)
            : startedAt.toDate?.() || new Date(startedAt)

          const periodKey = cohortType === "weekly"
            ? format(startOfWeek(date), "yyyy-MM-dd")
            : format(startOfMonth(date), "yyyy-MM")

          if (!userActivity.has(userId)) {
            userActivity.set(userId, new Set())
          }
          userActivity.get(userId)!.add(periodKey)
        } catch {
          // Skip invalid dates
        }
      }
    })

    // Build cohorts
    const now = new Date()
    const cohorts: CohortData[] = []

    for (let i = numCohorts - 1; i >= 0; i--) {
      const cohortStart = cohortType === "weekly"
        ? startOfWeek(new Date(now.getTime() - i * 7 * 24 * 60 * 60 * 1000))
        : startOfMonth(subMonths(now, i))

      const cohortEnd = cohortType === "weekly"
        ? new Date(cohortStart.getTime() + 7 * 24 * 60 * 60 * 1000)
        : startOfMonth(subMonths(now, i - 1))

      const cohortLabel = cohortType === "weekly"
        ? format(cohortStart, "MMM d")
        : format(cohortStart, "MMM yyyy")

      const cohortKey = cohortType === "weekly"
        ? format(cohortStart, "yyyy-MM-dd")
        : format(cohortStart, "yyyy-MM")

      // Find users who signed up in this cohort
      const cohortUsers: string[] = []

      profilesSnapshot.docs.forEach((doc) => {
        const profile = doc.data()
        const createdAt = profile.created_at || profile.createdAt

        if (createdAt) {
          try {
            const date = typeof createdAt === "string"
              ? new Date(createdAt)
              : createdAt.toDate?.() || new Date(createdAt)

            if (date >= cohortStart && date < cohortEnd) {
              cohortUsers.push(doc.id)
            }
          } catch {
            // Skip invalid dates
          }
        }
      })

      if (cohortUsers.length === 0) {
        cohorts.push({
          cohort: cohortLabel,
          size: 0,
          retention: [],
        })
        continue
      }

      // Calculate retention for each subsequent period
      const maxPeriods = cohortType === "weekly" ? 8 : 6 // 8 weeks or 6 months
      const periodsToCalculate = Math.min(maxPeriods, numCohorts - cohorts.length)
      const retention: number[] = []

      for (let p = 0; p < periodsToCalculate; p++) {
        const periodStart = cohortType === "weekly"
          ? startOfWeek(new Date(cohortStart.getTime() + p * 7 * 24 * 60 * 60 * 1000))
          : startOfMonth(subMonths(now, i - p))

        const periodKey = cohortType === "weekly"
          ? format(periodStart, "yyyy-MM-dd")
          : format(periodStart, "yyyy-MM")

        // Count users active in this period
        let activeUsers = 0
        cohortUsers.forEach((userId) => {
          const activity = userActivity.get(userId)
          if (activity?.has(periodKey)) {
            activeUsers++
          }
        })

        const retentionRate = (activeUsers / cohortUsers.length) * 100
        retention.push(Math.round(retentionRate * 10) / 10)
      }

      cohorts.push({
        cohort: cohortLabel,
        size: cohortUsers.length,
        retention,
      })
    }

    // Calculate average retention per period
    const avgRetention: number[] = []
    const maxRetentionPeriods = Math.max(...cohorts.map((c) => c.retention.length))

    for (let p = 0; p < maxRetentionPeriods; p++) {
      const values = cohorts
        .filter((c) => c.retention[p] !== undefined)
        .map((c) => c.retention[p])

      if (values.length > 0) {
        avgRetention.push(
          Math.round((values.reduce((a, b) => a + b, 0) / values.length) * 10) / 10
        )
      }
    }

    return NextResponse.json({
      success: true,
      cohortType,
      data: cohorts,
      summary: {
        totalCohorts: cohorts.length,
        totalUsers: cohorts.reduce((sum, c) => sum + c.size, 0),
        avgRetention,
        periodLabels: cohortType === "weekly"
          ? ["W1", "W2", "W3", "W4", "W5", "W6", "W7", "W8"]
          : ["M1", "M2", "M3", "M4", "M5", "M6"],
      },
    })
  } catch (error) {
    console.error("Cohort analytics API error:", error)
    return NextResponse.json(
      { success: false, error: "Failed to fetch cohort data" },
      { status: 500 }
    )
  }
}

/**
 * Email Diagnostics Endpoint
 *
 * GET /api/admin/email-diagnostics
 *
 * Provides comprehensive diagnostics about email system:
 * - Configuration status (BREVO_API_KEY, CRON_SECRET)
 * - Recent email activity from email_notifications collection
 * - Email statistics (sent, failed, by type)
 * - Cron job status
 *
 * Requires admin authentication
 */

import { NextRequest, NextResponse } from "next/server"
import { adminDb } from "@/lib/firebase-admin"
import { verifyAdminAccess } from "@/lib/admin/middleware"

export async function GET(request: NextRequest) {
  try {
    // Verify admin access
    const authResult = await verifyAdminAccess(request)
    if (!authResult.authorized) {
      return NextResponse.json(
        { success: false, error: authResult.error },
        { status: authResult.status || 403 }
      )
    }

    // Check configuration
    const config = {
      BREVO_API_KEY: {
        configured: !!process.env.BREVO_API_KEY,
        length: process.env.BREVO_API_KEY?.length || 0,
        preview: process.env.BREVO_API_KEY
          ? `${process.env.BREVO_API_KEY.substring(0, 8)}...${process.env.BREVO_API_KEY.substring(process.env.BREVO_API_KEY.length - 4)}`
          : "Not set",
      },
      CRON_SECRET: {
        configured: !!process.env.CRON_SECRET,
        length: process.env.CRON_SECRET?.length || 0,
      },
      NEXT_PUBLIC_APP_URL: {
        configured: !!process.env.NEXT_PUBLIC_APP_URL,
        value: process.env.NEXT_PUBLIC_APP_URL || "Not set",
      },
    }

    // Get recent email notifications (last 100)
    const recentEmails: any[] = []
    const emailStats = {
      total: 0,
      sent: 0,
      failed: 0,
      byType: {} as Record<string, { sent: number; failed: number }>,
      last24Hours: { sent: 0, failed: 0 },
      last7Days: { sent: 0, failed: 0 },
    }

    try {
      const twentyFourHoursAgo = new Date(Date.now() - 24 * 60 * 60 * 1000)
      const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000)

      const emailsSnapshot = await adminDb
        .collection("email_notifications")
        .orderBy("created_at", "desc")
        .limit(100)
        .get()

      emailStats.total = emailsSnapshot.size

      emailsSnapshot.docs.forEach((doc) => {
        const data = doc.data()
        const createdAt = new Date(data.created_at)

        recentEmails.push({
          id: doc.id,
          ...data,
        })

        // Count by status
        if (data.status === "sent") {
          emailStats.sent++
        } else if (data.status === "failed") {
          emailStats.failed++
        }

        // Count by time period
        if (createdAt >= twentyFourHoursAgo) {
          if (data.status === "sent") emailStats.last24Hours.sent++
          if (data.status === "failed") emailStats.last24Hours.failed++
        }
        if (createdAt >= sevenDaysAgo) {
          if (data.status === "sent") emailStats.last7Days.sent++
          if (data.status === "failed") emailStats.last7Days.failed++
        }

        // Count by type
        const emailType = data.email_type || "unknown"
        if (!emailStats.byType[emailType]) {
          emailStats.byType[emailType] = { sent: 0, failed: 0 }
        }
        if (data.status === "sent") {
          emailStats.byType[emailType].sent++
        } else if (data.status === "failed") {
          emailStats.byType[emailType].failed++
        }
      })
    } catch (error: any) {
      console.error("[Email Diagnostics] Error fetching email notifications:", error)
      // Continue even if collection doesn't exist yet
    }

    // Get user profile stats related to emails
    const profileStats = {
      total: 0,
      withEmail: 0,
      welcomeEmailSent: 0,
      emailNotificationsEnabled: 0,
    }

    try {
      const profilesSnapshot = await adminDb.collection("profiles").limit(1000).get()

      profileStats.total = profilesSnapshot.size

      profilesSnapshot.docs.forEach((doc) => {
        const data = doc.data()
        if (data.email) profileStats.withEmail++
        if (data.welcome_email_sent) profileStats.welcomeEmailSent++
        if (data.notification_preferences?.email_notifications_enabled) {
          profileStats.emailNotificationsEnabled++
        }
      })
    } catch (error: any) {
      console.error("[Email Diagnostics] Error fetching profiles:", error)
    }

    // Determine overall health
    const health = {
      status: "healthy" as "healthy" | "degraded" | "unhealthy",
      issues: [] as string[],
    }

    if (!config.BREVO_API_KEY.configured) {
      health.status = "unhealthy"
      health.issues.push("BREVO_API_KEY not configured")
    }

    if (!config.CRON_SECRET.configured) {
      health.status = health.status === "unhealthy" ? "unhealthy" : "degraded"
      health.issues.push("CRON_SECRET not configured")
    }

    if (emailStats.total === 0) {
      health.status = health.status === "unhealthy" ? "unhealthy" : "degraded"
      health.issues.push("No email notifications found - emails may not have been sent yet")
    }

    if (emailStats.failed > emailStats.sent && emailStats.total > 10) {
      health.status = health.status === "unhealthy" ? "unhealthy" : "degraded"
      health.issues.push("High failure rate detected")
    }

    return NextResponse.json({
      success: true,
      timestamp: new Date().toISOString(),
      health,
      configuration: config,
      statistics: {
        emails: emailStats,
        profiles: profileStats,
      },
      recentEmails: recentEmails.slice(0, 20), // Return last 20 for preview
      recommendations: generateRecommendations(config, emailStats, profileStats),
    })
  } catch (error: any) {
    console.error("[Email Diagnostics] Error:", error)
    return NextResponse.json(
      {
        success: false,
        error: error.message || "Failed to generate diagnostics",
      },
      { status: 500 }
    )
  }
}

function generateRecommendations(config: any, emailStats: any, profileStats: any): string[] {
  const recommendations: string[] = []

  if (!config.BREVO_API_KEY.configured) {
    recommendations.push("Set BREVO_API_KEY environment variable in Vercel")
  }

  if (!config.CRON_SECRET.configured) {
    recommendations.push("Set CRON_SECRET environment variable for cron job authentication")
  }

  if (emailStats.total === 0) {
    recommendations.push("No emails have been sent yet. Test with /api/test-email endpoint")
    recommendations.push("Check if cron job is running: /api/cron/email-notifications")
  }

  if (emailStats.failed > 0 && emailStats.failed > emailStats.sent) {
    recommendations.push("High email failure rate detected. Check Brevo dashboard for errors")
    recommendations.push("Verify BREVO_API_KEY is valid and has proper permissions")
  }

  if (profileStats.withEmail > profileStats.welcomeEmailSent) {
    const pending = profileStats.withEmail - profileStats.welcomeEmailSent
    recommendations.push(`${pending} users haven't received welcome emails yet`)
  }

  if (profileStats.emailNotificationsEnabled < profileStats.withEmail * 0.8) {
    recommendations.push(
      "Many users have email notifications disabled. Consider re-engagement campaign"
    )
  }

  return recommendations
}

/**
 * Feature Flags API
 *
 * Manage feature flags for gradual rollouts, A/B testing, and kill switches
 */

import { NextRequest, NextResponse } from "next/server"
import { adminDb } from "@/lib/firebase-admin"
import { verifyToken, getAdminRole } from "@/lib/admin/rbac"
import { Timestamp } from "firebase-admin/firestore"

export const dynamic = "force-dynamic"

export interface FeatureFlag {
  id: string
  key: string
  name: string
  description: string
  enabled: boolean
  type: "release" | "experiment" | "ops" | "permission" | "kill_switch"
  rolloutPercentage: number
  targetTiers: string[]
  targetUserIds: string[]
  environment: "all" | "production" | "staging" | "development"
  createdBy: string
  createdAt: string
  updatedAt: string
  expiresAt?: string
}

// GET - List feature flags
export async function GET(request: NextRequest) {
  try {
    const authHeader = request.headers.get("Authorization")
    if (!authHeader?.startsWith("Bearer ")) {
      return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 })
    }

    const token = authHeader.substring(7)
    const auth = await verifyToken(token)
    if (!auth.valid || !auth.userId) {
      return NextResponse.json({ success: false, error: "Invalid token" }, { status: 401 })
    }

    const role = await getAdminRole(auth.userId)
    if (!role) {
      return NextResponse.json(
        { success: false, error: "Insufficient permissions" },
        { status: 403 }
      )
    }

    if (!adminDb) {
      return NextResponse.json({ success: false, error: "Database not available" }, { status: 500 })
    }

    const snapshot = await adminDb.collection("feature_flags").orderBy("createdAt", "desc").get()

    const flags: FeatureFlag[] = snapshot.docs.map((doc) => {
      const data = doc.data()
      return {
        id: doc.id,
        key: data.key,
        name: data.name,
        description: data.description,
        enabled: data.enabled ?? false,
        type: data.type || "release",
        rolloutPercentage: data.rolloutPercentage ?? 100,
        targetTiers: data.targetTiers || [],
        targetUserIds: data.targetUserIds || [],
        environment: data.environment || "all",
        createdBy: data.createdBy,
        createdAt: data.createdAt?.toDate?.()?.toISOString() || data.createdAt,
        updatedAt: data.updatedAt?.toDate?.()?.toISOString() || data.updatedAt,
        expiresAt: data.expiresAt?.toDate?.()?.toISOString() || data.expiresAt,
      }
    })

    const stats = {
      total: flags.length,
      enabled: flags.filter((f) => f.enabled).length,
      experiments: flags.filter((f) => f.type === "experiment").length,
      killSwitches: flags.filter((f) => f.type === "kill_switch").length,
    }

    return NextResponse.json({ success: true, flags, stats })
  } catch (error) {
    console.error("[Feature Flags API] GET Error:", error)
    return NextResponse.json(
      { success: false, error: "Failed to fetch feature flags" },
      { status: 500 }
    )
  }
}

// POST - Create feature flag
export async function POST(request: NextRequest) {
  try {
    const authHeader = request.headers.get("Authorization")
    if (!authHeader?.startsWith("Bearer ")) {
      return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 })
    }

    const token = authHeader.substring(7)
    const auth = await verifyToken(token)
    if (!auth.valid || !auth.userId) {
      return NextResponse.json({ success: false, error: "Invalid token" }, { status: 401 })
    }

    const role = await getAdminRole(auth.userId)
    if (!role || !["super_admin", "admin"].includes(role)) {
      return NextResponse.json(
        { success: false, error: "Insufficient permissions" },
        { status: 403 }
      )
    }

    if (!adminDb) {
      return NextResponse.json({ success: false, error: "Database not available" }, { status: 500 })
    }

    const body = await request.json()
    const {
      key,
      name,
      description = "",
      enabled = false,
      type = "release",
      rolloutPercentage = 100,
      targetTiers = [],
      targetUserIds = [],
      environment = "all",
      expiresAt,
    } = body

    if (!key || !name) {
      return NextResponse.json(
        { success: false, error: "Key and name are required" },
        { status: 400 }
      )
    }

    // Check for duplicate key
    const existing = await adminDb.collection("feature_flags").where("key", "==", key).get()

    if (!existing.empty) {
      return NextResponse.json(
        { success: false, error: "A flag with this key already exists" },
        { status: 400 }
      )
    }

    const now = Timestamp.now()
    const flagData = {
      key,
      name,
      description,
      enabled,
      type,
      rolloutPercentage,
      targetTiers,
      targetUserIds,
      environment,
      createdBy: auth.userId,
      createdAt: now,
      updatedAt: now,
      expiresAt: expiresAt ? Timestamp.fromDate(new Date(expiresAt)) : null,
    }

    const docRef = await adminDb.collection("feature_flags").add(flagData)

    await adminDb.collection("admin_audit_log").add({
      adminId: auth.userId,
      action: "create_feature_flag",
      details: { flagId: docRef.id, key, name },
      timestamp: now,
    })

    return NextResponse.json({ success: true, flagId: docRef.id })
  } catch (error) {
    console.error("[Feature Flags API] POST Error:", error)
    return NextResponse.json(
      { success: false, error: "Failed to create feature flag" },
      { status: 500 }
    )
  }
}

// PUT - Update feature flag
export async function PUT(request: NextRequest) {
  try {
    const authHeader = request.headers.get("Authorization")
    if (!authHeader?.startsWith("Bearer ")) {
      return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 })
    }

    const token = authHeader.substring(7)
    const auth = await verifyToken(token)
    if (!auth.valid || !auth.userId) {
      return NextResponse.json({ success: false, error: "Invalid token" }, { status: 401 })
    }

    const role = await getAdminRole(auth.userId)
    if (!role || !["super_admin", "admin"].includes(role)) {
      return NextResponse.json(
        { success: false, error: "Insufficient permissions" },
        { status: 403 }
      )
    }

    if (!adminDb) {
      return NextResponse.json({ success: false, error: "Database not available" }, { status: 500 })
    }

    const body = await request.json()
    const { id, ...updates } = body

    if (!id) {
      return NextResponse.json({ success: false, error: "Flag ID is required" }, { status: 400 })
    }

    const docRef = adminDb.collection("feature_flags").doc(id)
    const doc = await docRef.get()

    if (!doc.exists) {
      return NextResponse.json({ success: false, error: "Feature flag not found" }, { status: 404 })
    }

    const updateData: Record<string, any> = {
      ...updates,
      updatedAt: Timestamp.now(),
    }

    if (updates.expiresAt) {
      updateData.expiresAt = Timestamp.fromDate(new Date(updates.expiresAt))
    }

    await docRef.update(updateData)

    await adminDb.collection("admin_audit_log").add({
      adminId: auth.userId,
      action: "update_feature_flag",
      details: { flagId: id, updates: Object.keys(updates) },
      timestamp: Timestamp.now(),
    })

    return NextResponse.json({ success: true })
  } catch (error) {
    console.error("[Feature Flags API] PUT Error:", error)
    return NextResponse.json(
      { success: false, error: "Failed to update feature flag" },
      { status: 500 }
    )
  }
}

// DELETE - Delete feature flag
export async function DELETE(request: NextRequest) {
  try {
    const authHeader = request.headers.get("Authorization")
    if (!authHeader?.startsWith("Bearer ")) {
      return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 })
    }

    const token = authHeader.substring(7)
    const auth = await verifyToken(token)
    if (!auth.valid || !auth.userId) {
      return NextResponse.json({ success: false, error: "Invalid token" }, { status: 401 })
    }

    const role = await getAdminRole(auth.userId)
    if (role !== "super_admin") {
      return NextResponse.json(
        { success: false, error: "Only super admins can delete feature flags" },
        { status: 403 }
      )
    }

    if (!adminDb) {
      return NextResponse.json({ success: false, error: "Database not available" }, { status: 500 })
    }

    const { searchParams } = new URL(request.url)
    const id = searchParams.get("id")

    if (!id) {
      return NextResponse.json({ success: false, error: "Flag ID is required" }, { status: 400 })
    }

    await adminDb.collection("feature_flags").doc(id).delete()

    await adminDb.collection("admin_audit_log").add({
      adminId: auth.userId,
      action: "delete_feature_flag",
      details: { flagId: id },
      timestamp: Timestamp.now(),
    })

    return NextResponse.json({ success: true })
  } catch (error) {
    console.error("[Feature Flags API] DELETE Error:", error)
    return NextResponse.json(
      { success: false, error: "Failed to delete feature flag" },
      { status: 500 }
    )
  }
}

/**
 * Feedback Collection API
 *
 * Manage user feedback, feature requests, and NPS surveys
 */

import { NextRequest, NextResponse } from "next/server"
import { adminDb } from "@/lib/firebase-admin"
import { verifyToken, getAdminRole } from "@/lib/admin/rbac"
import { Timestamp } from "firebase-admin/firestore"

export const dynamic = "force-dynamic"

export interface FeedbackItem {
  id: string
  userId: string
  userEmail?: string
  type: "feedback" | "feature_request" | "bug_report" | "nps"
  content: string
  rating?: number
  npsScore?: number
  status: "new" | "reviewed" | "in_progress" | "resolved" | "declined"
  priority: "low" | "medium" | "high" | "critical"
  category?: string
  votes: number
  createdAt: string
  updatedAt: string
  adminNotes?: string
}

// GET - List feedback
export async function GET(request: NextRequest) {
  try {
    const authHeader = request.headers.get("Authorization")
    if (!authHeader?.startsWith("Bearer ")) {
      return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 })
    }

    const token = authHeader.substring(7)
    const auth = await verifyToken(token)
    if (!auth.valid || !auth.userId) {
      return NextResponse.json({ success: false, error: "Invalid token" }, { status: 401 })
    }

    const role = await getAdminRole(auth.userId)
    if (!role) {
      return NextResponse.json(
        { success: false, error: "Insufficient permissions" },
        { status: 403 }
      )
    }

    if (!adminDb) {
      return NextResponse.json({ success: false, error: "Database not available" }, { status: 500 })
    }

    const { searchParams } = new URL(request.url)
    const status = searchParams.get("status")
    const type = searchParams.get("type")
    const limit = Math.min(parseInt(searchParams.get("limit") || "50"), 200)

    let query = adminDb.collection("feedback").orderBy("createdAt", "desc")

    if (status && status !== "all") {
      query = query.where("status", "==", status)
    }
    if (type && type !== "all") {
      query = query.where("type", "==", type)
    }

    query = query.limit(limit)

    const snapshot = await query.get()
    const feedback: FeedbackItem[] = snapshot.docs.map((doc) => {
      const data = doc.data()
      return {
        id: doc.id,
        userId: data.userId,
        userEmail: data.userEmail,
        type: data.type || "feedback",
        content: data.content,
        rating: data.rating,
        npsScore: data.npsScore,
        status: data.status || "new",
        priority: data.priority || "medium",
        category: data.category,
        votes: data.votes || 0,
        createdAt: data.createdAt?.toDate?.()?.toISOString() || data.createdAt,
        updatedAt: data.updatedAt?.toDate?.()?.toISOString() || data.updatedAt,
        adminNotes: data.adminNotes,
      }
    })

    // Calculate stats
    const allFeedbackSnapshot = await adminDb.collection("feedback").get()
    const allFeedback = allFeedbackSnapshot.docs.map((d) => d.data())

    const npsScores = allFeedback.filter((f) => f.npsScore !== undefined).map((f) => f.npsScore)
    const promoters = npsScores.filter((s) => s >= 9).length
    const detractors = npsScores.filter((s) => s <= 6).length
    const npsScore =
      npsScores.length > 0 ? Math.round(((promoters - detractors) / npsScores.length) * 100) : 0

    const stats = {
      total: allFeedback.length,
      new: allFeedback.filter((f) => f.status === "new").length,
      inProgress: allFeedback.filter((f) => f.status === "in_progress").length,
      resolved: allFeedback.filter((f) => f.status === "resolved").length,
      featureRequests: allFeedback.filter((f) => f.type === "feature_request").length,
      bugReports: allFeedback.filter((f) => f.type === "bug_report").length,
      npsScore,
      avgRating:
        allFeedback.filter((f) => f.rating).length > 0
          ? Math.round(
              (allFeedback.filter((f) => f.rating).reduce((s, f) => s + f.rating, 0) /
                allFeedback.filter((f) => f.rating).length) *
                10
            ) / 10
          : 0,
    }

    return NextResponse.json({ success: true, feedback, stats })
  } catch (error) {
    console.error("[Feedback API] GET Error:", error)
    return NextResponse.json({ success: false, error: "Failed to fetch feedback" }, { status: 500 })
  }
}

// POST - Submit feedback (for users) or create feedback (for admins)
export async function POST(request: NextRequest) {
  try {
    const authHeader = request.headers.get("Authorization")
    if (!authHeader?.startsWith("Bearer ")) {
      return NextResponse.json({ success: false, error: "Unauthorized" }, { status: 401 })
    }

    const token = authHeader.substring(7)
    const auth = await verifyToken(token)
    if (!auth.valid || !auth.userId) {
      return NextResponse.json({ success: false, error: "Invalid token" }, { status: 401 })
    }

    if (!adminDb) {
