function convertToCSV(data: any, type: string): string {
  if (!data || (Array.isArray(data) && data.length === 0)) {
    return "No data available"
  }

  if (type === "comparison") {
    // Single object - convert to key-value pairs
    const lines = ["metric,value"]
    for (const [key, value] of Object.entries(data)) {
      lines.push(`${key},"${value}"`)
    }
    return lines.join("\n")
  }

  // Array of objects
  const array = Array.isArray(data) ? data : [data]
  if (array.length === 0) return "No data available"

  const headers = Object.keys(array[0])
  const lines = [headers.join(",")]

  for (const row of array) {
    const values = headers.map((h) => {
      const val = row[h]
      if (val === null || val === undefined) return ""
      if (
        typeof val === "string" &&
        (val.includes(",") || val.includes('"') || val.includes("\n"))
      ) {
        return `"${val.replace(/"/g, '""')}"`
      }
      return String(val)
    })
    lines.push(values.join(","))
  }

  return lines.join("\n")
}

/**
 * Admin Revenue API
 *
 * Returns accurate revenue metrics from actual Stripe payments.
 * Uses payment_history collection (populated by webhooks) and can optionally
 * fetch live data from Stripe.
 *
 * GET /api/admin/revenue
 * Query params:
 * - timeRange: '7d' | '30d' | '90d' | 'all'
 * - live: 'true' to fetch fresh data from Stripe (slower)
 *
 * Requires admin authentication
 */

import { NextRequest, NextResponse } from 'next/server'
import Stripe from 'stripe'
import { adminDb } from '@/lib/firebase-admin'
import { verifyAdminAccess, parseAdminQueryParams } from '@/lib/admin/middleware'
import { adminCache, getCacheKey, CACHE_TTL } from '@/lib/admin/cache'
import { getMonthlyPrice, getAnnualPrice } from '@/lib/pricing'

// Initialize Stripe
const stripe = process.env.STRIPE_SECRET_KEY
  ? new Stripe(process.env.STRIPE_SECRET_KEY, { apiVersion: '2025-12-15.clover' as any })
  : null

interface RevenueMetrics {
  // Actual revenue from payments
  actual: {
    total_collected: number // Total collected in time range
    mrr_equivalent: number // Estimated MRR from actual payments
    refunds: number
    net_revenue: number
  }
  // Calculated revenue (for comparison)
  calculated: {
    mrr: number // Based on subscriber counts
    arr: number
  }
  // Breakdown by subscription type
  byType: {
    monthly: {
      subscribers: number
      revenue: number
      avgPayment: number
    }
    yearly: {
      subscribers: number
      revenue: number
      avgPayment: number
      mrrEquivalent: number
    }
  }
  // Payments with discounts
  discounts: {
    paymentsWithDiscount: number
    totalDiscountAmount: number
    avgDiscountPercent: number
  }
  // Recent payments
  recentPayments: Array<{
    id: string
    user_id: string
    amount: number
    currency: string
    type: 'subscription' | 'one_time'
    status: string
    description?: string
    created_at: string
  }>
  // Time series for charts
  timeSeries: Array<{
    date: string
    revenue: number
    payments: number
    refunds: number
  }>
}

export async function GET(request: NextRequest) {
  try {
    // Verify Admin SDK is initialized
    if (!adminDb) {
      return NextResponse.json(
        { success: false, error: 'Firebase Admin SDK not initialized.' },
        { status: 500 }
      )
    }

    // Verify admin access
    const authResult = await verifyAdminAccess(request)
    if (!authResult.authorized) {
      return NextResponse.json(
        { success: false, error: authResult.error },
        { status: authResult.status || 403 }
      )
    }

    const { searchParams } = new URL(request.url)
    const { timeRange, startDate } = parseAdminQueryParams(request)
    const fetchLive = searchParams.get('live') === 'true'

    // Check cache (skip if fetching live data)
    const cacheKey = getCacheKey('revenue', { timeRange })
    if (!fetchLive) {
      const cached = adminCache.get<any>(cacheKey)
      if (cached) {
        return NextResponse.json({ ...cached, cached: true })
      }
    }

    // Fetch payment history from Firestore
    let paymentsQuery = adminDb.collection('payment_history')
    if (startDate) {
      paymentsQuery = paymentsQuery.where('created_at', '>=', startDate.toISOString()) as any
    }
    const paymentsSnapshot = await paymentsQuery.orderBy('created_at', 'desc').get()

    // Fetch profiles to count subscribers by type
    const profilesSnapshot = await adminDb.collection('profiles').get()

    // Calculate subscriber breakdown
    const subscribersByType = {
      monthly: { count: 0, totalRevenue: 0 },
      yearly: { count: 0, totalRevenue: 0 },
    }

    profilesSnapshot.docs.forEach((doc) => {
      const profile = doc.data()
      if (profile.subscription_tier === 'pro' && profile.subscription_status === 'active') {
        if (profile.subscription_type === 'yearly') {
          subscribersByType.yearly.count++
        } else {
          subscribersByType.monthly.count++
        }
      }
    })

    // Process payment history
    let totalCollected = 0
    let totalRefunds = 0
    let paymentsWithDiscount = 0
    let totalDiscountAmount = 0

    const monthlyPayments: number[] = []
    const yearlyPayments: number[] = []
    const recentPayments: RevenueMetrics['recentPayments'] = []
    const dailyRevenue: Record<string, { revenue: number; payments: number; refunds: number }> = {}

    paymentsSnapshot.docs.forEach((doc) => {
      const payment = doc.data()
      const amountInDollars = (payment.amount || 0) / 100

      // Track by date
      const dateKey = payment.created_at?.split('T')[0] || 'unknown'
      if (!dailyRevenue[dateKey]) {
        dailyRevenue[dateKey] = { revenue: 0, payments: 0, refunds: 0 }
      }

      if (payment.status === 'succeeded') {
        totalCollected += amountInDollars
        dailyRevenue[dateKey].revenue += amountInDollars
        dailyRevenue[dateKey].payments++

        // Track by type
        if (payment.type === 'one_time' || payment.description?.toLowerCase().includes('yearly')) {
          yearlyPayments.push(amountInDollars)
          subscribersByType.yearly.totalRevenue += amountInDollars
        } else {
          monthlyPayments.push(amountInDollars)
          subscribersByType.monthly.totalRevenue += amountInDollars
        }

        // Check for discounts (if payment is less than standard price)
        const expectedMonthly = getMonthlyPrice('pro')
        const expectedYearly = getAnnualPrice('pro')
        if (payment.type === 'subscription' && amountInDollars < expectedMonthly && amountInDollars > 0) {
          paymentsWithDiscount++
          totalDiscountAmount += expectedMonthly - amountInDollars
        } else if (payment.type === 'one_time' && amountInDollars < expectedYearly && amountInDollars > 0) {
          paymentsWithDiscount++
          totalDiscountAmount += expectedYearly - amountInDollars
        }
      } else if (payment.status === 'refunded') {
        totalRefunds += Math.abs(amountInDollars)
        dailyRevenue[dateKey].refunds += Math.abs(amountInDollars)
      }

      // Add to recent payments (first 50)
      if (recentPayments.length < 50) {
        recentPayments.push({
          id: doc.id,
          user_id: payment.user_id,
          amount: amountInDollars,
          currency: payment.currency || 'usd',
          type: payment.type,
          status: payment.status,
          description: payment.description,
          created_at: payment.created_at,
        })
      }
    })

    // Calculate MRR equivalent from actual payments
    // Monthly payments contribute directly
    // Yearly payments contribute 1/12 per month
    const monthlyMRR = subscribersByType.monthly.count * getMonthlyPrice('pro')
    const yearlyMRREquivalent = (subscribersByType.yearly.totalRevenue / 12) || 0

    // Calculate averages
    const avgMonthlyPayment = monthlyPayments.length > 0
      ? monthlyPayments.reduce((a, b) => a + b, 0) / monthlyPayments.length
      : 0
    const avgYearlyPayment = yearlyPayments.length > 0
      ? yearlyPayments.reduce((a, b) => a + b, 0) / yearlyPayments.length
      : 0
    const avgDiscountPercent = paymentsWithDiscount > 0
      ? (totalDiscountAmount / paymentsWithDiscount) / getMonthlyPrice('pro') * 100
      : 0

    // Create time series
    const timeSeries = Object.entries(dailyRevenue)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([date, data]) => ({
        date,
        revenue: Math.round(data.revenue * 100) / 100,
        payments: data.payments,
        refunds: Math.round(data.refunds * 100) / 100,
      }))

    // Calculated revenue (for comparison)
    const tierCounts = { free: 0, pro: 0, enterprise: 0 }
    profilesSnapshot.docs.forEach((doc) => {
      const tier = doc.data().subscription_tier || 'free'
      if (tier in tierCounts) {
        tierCounts[tier as keyof typeof tierCounts]++
      }
    })

    const calculatedMRR = tierCounts.pro * getMonthlyPrice('pro') +
      tierCounts.enterprise * getMonthlyPrice('enterprise')

    // Optionally fetch live data from Stripe
    let stripeData = null
    if (fetchLive && stripe) {
      try {
        const now = Math.floor(Date.now() / 1000)
        const rangeStart = startDate ? Math.floor(startDate.getTime() / 1000) : now - 30 * 24 * 60 * 60

        // Get balance
        const balance = await stripe.balance.retrieve()

        // Get recent charges
        const charges = await stripe.charges.list({
          created: { gte: rangeStart },
          limit: 100,
        })

        let stripeTotal = 0
        let stripeRefunds = 0
        charges.data.forEach((charge) => {
          if (charge.status === 'succeeded') {
            stripeTotal += charge.amount
          }
          if (charge.refunded) {
            stripeRefunds += charge.amount_refunded
          }
        })

        stripeData = {
          available: balance.available.reduce((sum, b) => sum + b.amount, 0) / 100,
          pending: balance.pending.reduce((sum, b) => sum + b.amount, 0) / 100,
          totalCharges: stripeTotal / 100,
          totalRefunds: stripeRefunds / 100,
          chargeCount: charges.data.length,
        }
      } catch (stripeError) {
        console.error('Error fetching Stripe data:', stripeError)
      }
    }

    const response = {
      success: true,
      timeRange,
      metrics: {
        actual: {
          total_collected: Math.round(totalCollected * 100) / 100,
          mrr_equivalent: Math.round((monthlyMRR + yearlyMRREquivalent) * 100) / 100,
          refunds: Math.round(totalRefunds * 100) / 100,
          net_revenue: Math.round((totalCollected - totalRefunds) * 100) / 100,
        },
        calculated: {
          mrr: calculatedMRR,
          arr: calculatedMRR * 12,
        },
        byType: {
          monthly: {
            subscribers: subscribersByType.monthly.count,
            revenue: Math.round(subscribersByType.monthly.totalRevenue * 100) / 100,
            avgPayment: Math.round(avgMonthlyPayment * 100) / 100,
          },
          yearly: {
            subscribers: subscribersByType.yearly.count,
            revenue: Math.round(subscribersByType.yearly.totalRevenue * 100) / 100,
            avgPayment: Math.round(avgYearlyPayment * 100) / 100,
            mrrEquivalent: Math.round(yearlyMRREquivalent * 100) / 100,
          },
        },
        discounts: {
          paymentsWithDiscount,
          totalDiscountAmount: Math.round(totalDiscountAmount * 100) / 100,
          avgDiscountPercent: Math.round(avgDiscountPercent * 10) / 10,
        },
        recentPayments,
        timeSeries,
        stripe: stripeData,
      },
    }

    // Cache for 60 seconds
    adminCache.set(cacheKey, response, CACHE_TTL.REVENUE || 60)

    return NextResponse.json(response)
  } catch (error) {
    console.error('Admin revenue API error:', error)
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    )
  }
}

/**
 * Admin Usage API
 *
 * Endpoints for viewing and managing user usage data.
 * Requires admin authentication via Firebase ID token with RBAC.
 */

import { NextRequest, NextResponse } from "next/server"
import { adminDb } from "@/lib/firebase-admin"
import {
  getAdminUsageStats,
  getUserUsageSummary,
  getServiceBreakdown,
  getUserServiceBreakdown,
  getGranularUsageBreakdown,
  getDailyUsageTrends,
  BUDGET_CAPS,
  DEEPGRAM_COSTS,
  EMBEDDING_COSTS,
  PROVIDER_COSTS,
} from "@/lib/usage-tracking"
import { getCacheStats } from "@/lib/ai-cache"
import {
  verifyAdminAccess,
  requirePermission,
  successResponse,
  errorResponse,
  unauthorizedResponse,
  type AdminContext,
} from "@/lib/admin/middleware"
import { PERMISSIONS } from "@/lib/admin/rbac"
import { logAdminAction } from "@/lib/admin/audit"

/**
 * GET /api/admin/usage
 *
 * Get usage statistics
 *
 * Query params:
 * - view: 'overview' | 'users' | 'user' | 'sessions' | 'scenarios' (default: 'overview')
 * - userId: string (required if view=user)
 * - limit: number (for pagination, default: 50)
 * - offset: number (for pagination, default: 0)
 */
export async function GET(request: NextRequest) {
  // Verify admin access with VIEW_AI_USAGE permission
  const authResult = await requirePermission(request, PERMISSIONS.VIEW_AI_USAGE)
  if (!authResult.authorized) {
    return unauthorizedResponse(authResult.error!, authResult.status || 403)
  }

  const adminContext = authResult.context!

  const { searchParams } = new URL(request.url)
  const view = searchParams.get("view") || "overview"
  const userId = searchParams.get("userId")
  const limit = parseInt(searchParams.get("limit") || "50", 10)
  const offset = parseInt(searchParams.get("offset") || "0", 10)

  try {
    switch (view) {
      case "overview": {
        // Get all usage data in parallel for performance
        const [stats, cacheStats, serviceBreakdown, granularBreakdown, dailyTrends] =
          await Promise.all([
            getAdminUsageStats(),
            getCacheStats(),
            getServiceBreakdown(),
            getGranularUsageBreakdown(),
            getDailyUsageTrends(30),
          ])

        return NextResponse.json({
          success: true,
          data: {
            overview: {
              totalUsers: stats.totalUsers,
              totalCost: stats.totalCost,
              totalRequests: stats.totalRequests,
              totalTokens: dailyTrends.totals.tokens,
              averageCostPerUser: stats.totalUsers > 0 ? stats.totalCost / stats.totalUsers : 0,
              averageTokensPerRequest:
                dailyTrends.totals.requests > 0
                  ? Math.round(dailyTrends.totals.tokens / dailyTrends.totals.requests)
                  : 0,
            },
            cache: cacheStats,
            topUsers: stats.userStats.slice(0, 20),
            budgetCaps: BUDGET_CAPS,
            // Service breakdown by type
            services: serviceBreakdown.byService,
            providers: serviceBreakdown.byProvider,
            // Granular breakdown by pattern, difficulty, scenario
            granular: {
              byPattern: granularBreakdown.byPattern,
              byDifficulty: granularBreakdown.byDifficulty,
              topCostlyScenarios: granularBreakdown.topCostlyScenarios.slice(0, 10),
              topTokenScenarios: granularBreakdown.topTokenScenarios.slice(0, 10),
            },
            // Daily trends for charting
            trends: {
              daily: dailyTrends.daily,
              totals: dailyTrends.totals,
            },
            // Cost reference
            costs: {
              llm: PROVIDER_COSTS,
              voice: DEEPGRAM_COSTS,
              embeddings: EMBEDDING_COSTS,
            },
          },
        })
      }

      case "users": {
        // Get all users with usage
        const stats = await getAdminUsageStats()

        return NextResponse.json({
          success: true,
          data: {
            users: stats.userStats,
            total: stats.userStats.length,
          },
        })
      }

      case "user": {
        if (!userId) {
          return NextResponse.json({ error: "userId is required for user view" }, { status: 400 })
        }

        const summary = await getUserUsageSummary(userId)
        if (!summary) {
          return NextResponse.json({ error: "User not found or no usage data" }, { status: 404 })
        }

        // Get user profile and service breakdown
        const userDoc = await adminDb.collection("users").doc(userId).get()
        const profile = userDoc.data()
        const serviceBreakdown = await getUserServiceBreakdown(userId)

        // Get user's sessions with costs
        let userSessions: any[] = []
        try {
          const sessionsSnapshot = await adminDb
            .collection("interview_sessions")
            .where("user_id", "==", userId)
            .orderBy("created_at", "desc")
            .limit(20)
            .get()

          userSessions = await Promise.all(
            sessionsSnapshot.docs.map(async (doc) => {
              const session = doc.data()

              // Get cost for this session from usage_events
              let sessionCost = 0
              let sessionTokens = 0

              try {
                const eventsSnapshot = await adminDb
                  .collection("usage_events")
                  .where("sessionId", "==", doc.id)
                  .get()

                for (const event of eventsSnapshot.docs) {
                  sessionCost += event.data().cost || 0
                  sessionTokens += event.data().totalTokens || 0
                }
              } catch {
                // usage_events query failed
              }

              return {
                sessionId: doc.id,
                scenarioTitle: session.scenario_title || "Unknown",
                scenarioType: session.scenario_type || "dsa",
                difficulty: session.difficulty || "medium",
                pattern: session.pattern || "unknown",
                status: session.status || "in_progress",
                cost: sessionCost,
                tokens: sessionTokens,
                createdAt:
                  session.created_at?.toDate?.()?.toISOString() || session.created_at || null,
              }
            })
          )
        } catch (err) {
          console.error("[Admin Usage API] Error fetching user sessions:", err)
        }

        return NextResponse.json({
          success: true,
          data: {
            user: {
              id: userId,
              email: profile?.email,
              tier: profile?.subscription_tier || "free",
              createdAt: profile?.created_at,
            },
            usage: summary,
            services: serviceBreakdown,
            sessions: userSessions,
          },
        })
      }

      case "sessions": {
        // Get recent sessions with their costs
        // Note: Firestore doesn't support offset, so we use simple limit for now
        const sessionsSnapshot = await adminDb
          .collection("interview_sessions")
          .orderBy("created_at", "desc")
          .limit(limit)
          .get()

        const sessions = await Promise.all(
          sessionsSnapshot.docs.map(async (doc) => {
            const session = doc.data()

            // Get cost for this session from usage_events
            let cost = 0
            let tokens = 0
            let requestCount = 0

            try {
              const eventsSnapshot = await adminDb
                .collection("usage_events")
                .where("sessionId", "==", doc.id)
                .get()

              for (const event of eventsSnapshot.docs) {
                cost += event.data().cost || 0
                tokens += event.data().totalTokens || 0
                requestCount++
              }
            } catch {
              // usage_events query failed, use 0
            }

            // Get user email
            let userEmail = "Unknown"
            if (session.user_id) {
              try {
                const userDoc = await adminDb.collection("users").doc(session.user_id).get()
                userEmail = userDoc.data()?.email || "Unknown"
              } catch {
                // User lookup failed
              }
            }

            return {
              sessionId: doc.id,
              userId: session.user_id,
              userEmail,
              scenarioTitle: session.scenario_title || "Unknown",
              scenarioId: session.scenario_id,
              scenarioType: session.scenario_type || "dsa",
              difficulty: session.difficulty || "medium",
              pattern: session.pattern || "unknown",
              status: session.status || "in_progress",
              cost,
              tokens,
              requestCount,
              performanceScore: session.performance_score,
              createdAt:
                session.created_at?.toDate?.()?.toISOString() || session.created_at || null,
              completedAt:
                session.completed_at?.toDate?.()?.toISOString() || session.completed_at || null,
            }
          })
        )

        return NextResponse.json({
          success: true,
          data: {
            sessions,
            total: sessions.length,
          },
        })
      }

      case "scenarios": {
        // Get scenario stats from interview_sessions directly
        // Group by scenario_id and aggregate
        const sessionsSnapshot = await adminDb
          .collection("interview_sessions")
          .orderBy("created_at", "desc")
          .limit(500)
          .get()

        // Aggregate by scenario
        const scenarioMap = new Map<
          string,
          {
            scenarioId: string
            scenarioTitle: string
            pattern: string
            difficulty: string
            sessionCount: number
            totalCost: number
            totalTokens: number
          }
        >()

        // First pass: aggregate sessions
        for (const doc of sessionsSnapshot.docs) {
          const session = doc.data()
          const scenarioId = session.scenario_id || "unknown"

          if (!scenarioMap.has(scenarioId)) {
            scenarioMap.set(scenarioId, {
              scenarioId,
              scenarioTitle: session.scenario_title || "Unknown",
              pattern: session.pattern || "unknown",
              difficulty: session.difficulty || "medium",
              sessionCount: 0,
              totalCost: 0,
              totalTokens: 0,
            })
          }

          const entry = scenarioMap.get(scenarioId)!
          entry.sessionCount++
        }

        // Second pass: get costs from usage_events for each scenario
        const scenarioStats = await Promise.all(
          Array.from(scenarioMap.values()).map(async (scenario) => {
            let cost = 0
            let tokens = 0
            let requests = 0

            try {
              const eventsSnapshot = await adminDb
                .collection("usage_events")
                .where("scenarioId", "==", scenario.scenarioId)
                .limit(1000)
                .get()

              for (const event of eventsSnapshot.docs) {
                cost += event.data().cost || 0
                tokens += event.data().totalTokens || 0
                requests++
              }
            } catch {
              // usage_events query failed
            }

            return {
              ...scenario,
              cost,
              tokens,
              requests,
              avgTokensPerRequest: requests > 0 ? Math.round(tokens / requests) : 0,
              avgCostPerSession: scenario.sessionCount > 0 ? cost / scenario.sessionCount : 0,
            }
          })
        )

        // Sort by cost descending
        scenarioStats.sort((a, b) => b.cost - a.cost)

        return NextResponse.json({
          success: true,
          data: {
            scenarios: scenarioStats.slice(0, 50),
          },
        })
      }

      default:
        return errorResponse(`Unknown view: ${view}`, 400)
    }
  } catch (error) {
    console.error("[Admin Usage API] Error fetching usage data:", error)
    return errorResponse(error instanceof Error ? error.message : "Failed to fetch usage data", 500)
  }
}

// Budget validation constants
const MIN_BUDGET = 0
const MAX_BUDGET = 10000 // $10,000 max budget cap

/**
 * POST /api/admin/usage
 *
 * Admin actions
 *
 * Body:
 * - action: 'set_budget' | 'clear_cache'
 * - userId: string (for set_budget)
 * - budget: number (for set_budget)
 */
export async function POST(request: NextRequest) {
  // Verify admin access with MANAGE_BUDGETS permission
  const authResult = await requirePermission(request, PERMISSIONS.MANAGE_BUDGETS)
  if (!authResult.authorized) {
    return unauthorizedResponse(authResult.error!, authResult.status || 403)
  }

  const adminContext = authResult.context!

  try {
    const body = await request.json()
    const { action, userId, budget } = body

    switch (action) {
      case "set_budget": {
        // Validate required fields
        if (!userId || typeof userId !== "string") {
          return errorResponse("userId is required and must be a string", 400)
        }

        if (budget === undefined || budget === null) {
          return errorResponse("budget is required", 400)
        }

        // Validate budget is a number
        const budgetNum = Number(budget)
        if (isNaN(budgetNum)) {
          return errorResponse("budget must be a valid number", 400)
        }

        // Validate budget range
        if (budgetNum < MIN_BUDGET || budgetNum > MAX_BUDGET) {
          return errorResponse(`budget must be between $${MIN_BUDGET} and $${MAX_BUDGET}`, 400)
        }

        // Verify user exists
        const userDoc = await adminDb.collection("profiles").doc(userId).get()
        if (!userDoc.exists) {
          return errorResponse("User not found", 404)
        }

        // Update user's custom budget
        await adminDb.collection("profiles").doc(userId).update({
          custom_budget_cap: budgetNum,
          updated_at: new Date().toISOString(),
        })

        // Log admin action
        await logAdminAction(adminContext.userId, "set_user_budget", {
          targetUserId: userId,
          previousBudget: userDoc.data()?.custom_budget_cap,
          newBudget: budgetNum,
        })

        return successResponse({
          message: `Budget set to $${budgetNum} for user ${userId}`,
          userId,
          budget: budgetNum,
        })
      }

      case "clear_cache": {
        // Import clearCache dynamically to avoid circular deps
        const { clearCache } = await import("@/lib/ai-cache")
        const cleared = await clearCache()

        // Log admin action
        await logAdminAction(adminContext.userId, "clear_cache", {
          timestamp: new Date().toISOString(),
        })

        return successResponse({
          message: "AI cache cleared successfully",
          cleared,
        })
      }

      default:
        return errorResponse(`Unknown action: ${action}`, 400)
    }
  } catch (error) {
    console.error("[Admin Usage API] Error performing action:", error)
    return errorResponse(error instanceof Error ? error.message : "Failed to perform action", 500)
  }
}

