/**
 * GET /api/admin/users
 * List all users with pagination (from Firebase Auth - includes Google, GitHub, etc.)
 *
 * Fetches from Firebase Auth (source of truth for all sign-ups) and merges with
 * Firestore profiles for subscription/onboarding data.
 */
const MAX_AUTH_USERS = 5000 // Cap to prevent timeout on listUsers
const AUTH_BATCH_SIZE = 1000 // Firebase listUsers max per call

function getAuthProvider(authUser: import("firebase-admin/auth").UserRecord): string {
  const provider = authUser.providerData?.[0]?.providerId
  if (provider === "google.com") return "google"
  if (provider === "github.com") return "github"
  return provider || "unknown"
}

export async function GET(request: NextRequest) {
  const authResult = await verifyAdminAccess(request)
  if (!authResult.authorized) {
    return unauthorizedResponse(authResult.error!, authResult.status || 401)
  }

  try {
    const { searchParams } = new URL(request.url)
    const page = Math.max(1, parseInt(searchParams.get("page") || "1", 10))
    const limit = Math.min(100, Math.max(1, parseInt(searchParams.get("limit") || "50", 10)))
    const search = (searchParams.get("search") || "").toLowerCase()

    // 1. Fetch all users from Firebase Auth (Google, GitHub, etc.)
    const authUsers: import("firebase-admin/auth").UserRecord[] = []
    let pageToken: string | undefined

    do {
      const result = await adminAuth.listUsers(AUTH_BATCH_SIZE, pageToken)
      authUsers.push(...result.users)
      pageToken = result.pageToken
      if (authUsers.length >= MAX_AUTH_USERS) break
    } while (pageToken)

    // 2. Batch fetch profiles for these users (Firestore 'in' supports up to 30)
    const profileMap = new Map<string, FirebaseFirestore.DocumentData>()
    const PROFILE_BATCH = 30
    for (let i = 0; i < authUsers.length; i += PROFILE_BATCH) {
      const batch = authUsers.slice(i, i + PROFILE_BATCH)
      const ids = batch.map((u) => u.uid)
      const profilesSnap = await adminDb
        .collection("profiles")
        .where(FieldPath.documentId(), "in", ids)
        .get()
      profilesSnap.docs.forEach((doc) => profileMap.set(doc.id, doc.data()))
    }

    // 3. Merge auth + profile, sort by creation (newest first)
    let users = authUsers.map((authUser) => {
      const profile = profileMap.get(authUser.uid)
      const createdAt =
        authUser.metadata?.creationTime || profile?.created_at || new Date().toISOString()
      return {
        id: authUser.uid,
        email: authUser.email || profile?.email || "",
        full_name: authUser.displayName || profile?.full_name || "",
        auth_provider: getAuthProvider(authUser),
        subscription_tier: profile?.subscription_tier || "free",
        subscription_status: profile?.subscription_status || "none",
        created_at: createdAt,
        updated_at: profile?.updated_at || "",
        onboarding_completed: profile?.onboarding_completed || false,
        stripe_customer_id: profile?.stripe_customer_id || null,
      }
    })

    users.sort((a, b) => (b.created_at || "").localeCompare(a.created_at || ""))

    // 4. Apply search filter
    if (search) {
      users = users.filter(
        (user) =>
          user.email.toLowerCase().includes(search) ||
          (user.full_name || "").toLowerCase().includes(search) ||
          user.id.toLowerCase().includes(search) ||
          (user.auth_provider || "").toLowerCase().includes(search)
      )
    }

    const total = users.length
    const startIndex = (page - 1) * limit
    const paginatedUsers = users.slice(startIndex, startIndex + limit)

    return successResponse({
      users: paginatedUsers,
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
        isSearchResult: !!search,
        searchCapped: authUsers.length >= MAX_AUTH_USERS,
      },
    })
  } catch (error: any) {
    logger.error("Error listing users", { error })
    return errorResponse(error.message || "Failed to list users", 500)
  }
}

/**
 * DELETE /api/admin/users
 * Delete a user and all their data
 *
 * Features:
 * - Rate limiting (max 5 deletions per minute per admin)
 * - Idempotency (returns success if user already deleted)
 * - Protected emails (cannot delete certain accounts)
 * - Full audit logging
 */
export async function DELETE(request: NextRequest) {
  // Require MANAGE_USERS permission
  const authResult = await requirePermission(request, PERMISSIONS.MANAGE_USERS)
  if (!authResult.authorized) {
    return unauthorizedResponse(authResult.error!, authResult.status || 401)
  }

  const adminId = authResult.context!.userId

  try {
    const body = await request.json()
    const { userId } = body

    if (!userId || typeof userId !== "string") {
      return errorResponse("userId is required and must be a string", 400)
    }

    // Distributed rate limiting check (works across serverless instances)
    const rateLimitResult = await adminDeletionRateLimit(request)
    if (rateLimitResult) {
      logger.warn("Rate limit exceeded for user deletion", { adminId, userId })
      return rateLimitResult
    }

    // 1. Get user profile and auth user for protected check
    const [profileDoc, authUser] = await Promise.all([
      adminDb.collection("profiles").doc(userId).get(),
      adminAuth.getUser(userId).catch(() => null),
    ])
    const profileData = profileDoc.exists ? profileDoc.data() : null

    // Idempotency: If neither profile nor auth user exists, already deleted
    if (!profileDoc.exists && !authUser) {
      logger.info("User already deleted (idempotent)", { userId, adminId })
      return successResponse({
        message: "User not found or already deleted",
        userId,
        alreadyDeleted: true,
      })
    }

    const emailForCheck = profileData?.email || authUser?.email || ""
    if (emailForCheck && PROTECTED_EMAILS.includes(emailForCheck.toLowerCase())) {
      logger.warn("Attempted to delete protected user", {
        userId,
        email: emailForCheck,
        adminId,
      })
      return errorResponse("This user account is protected and cannot be deleted", 403)
    }

    logger.info("Admin deleting user", { userId, email: emailForCheck, adminId })

    // 2. Cancel any active Stripe subscription
    if (profileData?.stripe_subscription_id) {
      try {
        await stripe.subscriptions.cancel(profileData.stripe_subscription_id)
        logger.info("Cancelled Stripe subscription", {
          userId,
          subscriptionId: profileData.stripe_subscription_id,
        })
      } catch (stripeError) {
        logger.error("Failed to cancel Stripe subscription", {
          error: stripeError,
          subscriptionId: profileData.stripe_subscription_id,
        })
      }
    }

    // 3. Delete all user data from Firestore collections
    const batch = adminDb.batch()
    let deletedDocCount = 0

    for (const col of collectionsToDelete) {
      try {
        // Collections where document ID is the userId
        if (col.name === "profiles" || col.name === "user_learning_state") {
          const docRef = adminDb.collection(col.name).doc(userId)
          const doc = await docRef.get()
          if (doc.exists) {
            batch.delete(docRef)
            deletedDocCount++
          }
        } else if (col.field) {
          // Query and delete documents by field
          const snapshot = await adminDb.collection(col.name).where(col.field, "==", userId).get()

          snapshot.docs.forEach((doc) => {
            batch.delete(doc.ref)
            deletedDocCount++
          })
        }
      } catch (colError) {
        logger.error("Error deleting from collection", { collection: col.name, error: colError })
      }
    }

    // Commit the batch delete
    await batch.commit()

    // 4. Delete user vectors from Pinecone (if configured)
    if (process.env.PINECONE_API_KEY) {
      try {
        const pinecone = new Pinecone({ apiKey: process.env.PINECONE_API_KEY })
        const indexName = process.env.PINECONE_INDEX_NAME || "codesparring-rag"
        const index = pinecone.index(indexName)

        const userNamespaces = [
          "mockmate_solution",
          "mockmate_feedback",
          "mockmate_hint",
          "mockmate_onboarding",
          "mockmate_user-performance",
          "mockmate_general",
        ]

        for (const namespace of userNamespaces) {
          try {
            await index.namespace(namespace).deleteMany({
              filter: {
                $or: [{ userId: { $eq: userId } }, { user_id: { $eq: userId } }],
              },
            })
          } catch (nsError) {
            // Namespace might not exist, continue
          }
        }
      } catch (pineconeError) {
        logger.error("Failed to delete Pinecone vectors", { error: pineconeError, userId })
      }
    }

    // 5. Delete the Firebase Auth user account
    let authDeleted = false
    try {
      await adminAuth.deleteUser(userId)
      authDeleted = true
      logger.info("Deleted Firebase Auth user", { userId })
    } catch (authDeleteError: any) {
      // User might already be deleted from Auth
      if (authDeleteError.code === "auth/user-not-found") {
        authDeleted = true
        logger.info("Firebase Auth user already deleted", { userId })
      } else {
        logger.error("Failed to delete Firebase Auth user", { error: authDeleteError, userId })
      }
    }

    // 6. Log the admin action for audit trail
    await logAdminAction(adminId, "delete_user", {
      targetUserId: userId,
      targetEmail: emailForCheck,
      targetTier: profileData?.subscription_tier,
      deletedDocuments: deletedDocCount,
      stripeSubscriptionCancelled: !!profileData?.stripe_subscription_id,
      authDeleted,
    })

    return successResponse({
      message: "User and all associated data have been permanently deleted",
      deletedDocuments: deletedDocCount,
      userId,
      email: emailForCheck,
    })
  } catch (error: any) {
    logger.error("Error deleting user", { error, adminId })
    return errorResponse(error.message || "Failed to delete user", 500)
  }
}

import { NextRequest, NextResponse } from "next/server"
import {
  generateHints,
  getNextHint,
  type HintGenerationRequest,
  type StruggleMetrics,
  type GeneratedHint,
  type HintTrigger,
} from "@/lib/agents/hints"
import type {
  BaseHintRequestPayload,
  GenerateHintsPayload,
  GetNextHintPayload,
  HintApiRequestBody,
  HintTestResults,
} from "@/lib/agents/hints/contracts"
import { rateLimit } from "@/lib/rate-limit"
import { validateProblemText, validateUserCode, withTimeout, TimeoutError } from "@/lib/rag/utils"
import { embedAndStoreHint, getSimilarHintsFromRAG } from "@/lib/rag"
import type { DSAPattern } from "@/lib/types/dsa-patterns"
import { verifyAuth } from "@/lib/auth-helpers"
import { logger } from "@/lib/logger"

// Rate limit: 15 requests per minute for hint generation (AI-intensive)
const hintRateLimit = rateLimit({
  interval: 60 * 1000,
  uniqueTokenPerInterval: 500,
  maxRequests: 15,
  prefix: "rl:hints",
})

/**
 * Hint Agent API
 *
 * Endpoints for AI-powered hint generation:
 * - POST: Generate personalized hints based on current state
 *
 * Actions:
 * - generate: Generate all hints for current problem state
 * - get-next: Get the next unrevealed hint
 */

export async function POST(request: NextRequest) {
  try {
    // Verify authentication
    const authResult = await verifyAuth(request)
    if (!authResult.authenticated || !authResult.userId) {
      return NextResponse.json({ error: "Authentication required" }, { status: 401 })
    }

    const authenticatedUserId = authResult.userId

    // Apply rate limiting
    const rateLimitResponse = await hintRateLimit(request)
    if (rateLimitResponse) {
      return rateLimitResponse
    }

    const body = (await request.json()) as HintApiRequestBody

    switch (body.action) {
      case "generate": {
        const params: GenerateHintsPayload = { ...body, userId: authenticatedUserId }
        return handleGenerateHints(params)
      }
      case "get-next": {
        const params: GetNextHintPayload = { ...body, userId: authenticatedUserId }
        return handleGetNextHint(params)
      }
      default:
        return NextResponse.json(
          { error: `Unknown action: ${(body as { action?: string }).action}` },
          { status: 400 }
        )
    }
  } catch (error) {
    logger.error("[Hint Agent API] Error:", { error })
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Hint generation failed" },
      { status: 500 }
    )
  }
}

function buildStruggleMetrics(
  struggleMetrics: Partial<StruggleMetrics> | undefined,
  hintsRevealedFallback = 0
): StruggleMetrics {
  return {
    timeSpentMinutes: struggleMetrics?.timeSpentMinutes ?? 0,
    codeChanges: struggleMetrics?.codeChanges ?? 0,
    testsRun: struggleMetrics?.testsRun ?? 0,
    testsFailed: struggleMetrics?.testsFailed ?? 0,
    hintsRevealed: struggleMetrics?.hintsRevealed ?? hintsRevealedFallback,
    lastCodeChangeMinutesAgo: struggleMetrics?.lastCodeChangeMinutesAgo ?? 0,
    errorCount: struggleMetrics?.errorCount ?? 0,
  }
}

function mapRagHintToGeneratedHint(
  ragHint: {
    id: string
    level?: number
    category?: string
    problemTitle: string
    content: string
    similarity: number
    pattern?: string
  },
  fallbackLevel: 1 | 2 | 3 | 4
): GeneratedHint {
  return {
    id: `rag_${ragHint.id}`,
    level: (ragHint.level || fallbackLevel) as 1 | 2 | 3 | 4,
    category: (ragHint.category || "approach") as GeneratedHint["category"],
    title: `Insight from ${ragHint.problemTitle}`,
    content: ragHint.content,
    isBlurred: true,
    source: "rag",
    relevanceScore: ragHint.similarity,
    metadata: {
      pattern: ragHint.pattern as DSAPattern,
      relatedConcepts: [],
    },
  }
}

function buildHintRequest(
  params: BaseHintRequestPayload,
  fullMetrics: StruggleMetrics
): HintGenerationRequest {
  return {
    userId: params.userId,
    problemId: params.problemId,
    problemTitle: params.problemTitle,
    problemText: params.problemText,
    problemPattern: params.problemPattern as DSAPattern | undefined,
    difficulty: (params.difficulty ?? "medium") as "easy" | "medium" | "hard",
    userCode: params.userCode ?? "",
    language: params.language ?? "javascript",
    struggleMetrics: fullMetrics,
    testResults: params.testResults as HintTestResults | undefined,
    optimalComplexity: params.optimalComplexity,
    constraints: params.constraints,
  }
}

/**
 * Generate personalized hints
 */
async function handleGenerateHints(params: GenerateHintsPayload) {
  const {
    userId,
    problemId,
    problemTitle,
    problemText,
    problemPattern,
    difficulty = "medium",
    userCode = "",
    language = "javascript",
    struggleMetrics = {},
    testResults,
    existingHints,
    trigger = "initial",
    optimalComplexity,
    constraints,
  } = params

  // Validate required fields
  if (!userId || !problemId) {
    return NextResponse.json({ error: "userId and problemId are required" }, { status: 400 })
  }

  // Validate and sanitize problem text
  const problemValidation = validateProblemText(problemText)
  if (!problemValidation.valid) {
    return NextResponse.json({ error: problemValidation.error }, { status: 400 })
  }

  // Validate user code if provided
  const codeValidation = validateUserCode(userCode)
  if (!codeValidation.valid) {
    return NextResponse.json({ error: codeValidation.error }, { status: 400 })
  }

  const fullMetrics = buildStruggleMetrics(struggleMetrics)

  // Build request with sanitized inputs
  const request: HintGenerationRequest = {
    ...buildHintRequest(
      {
        ...params,
        userCode: codeValidation.sanitized!,
        problemText: problemValidation.sanitized!,
      },
      fullMetrics
    ),
    problemText: problemValidation.sanitized!,
    userCode: codeValidation.sanitized!,
    existingHints,
    trigger,
  }

  try {
    // First, try to retrieve similar hints from RAG (fast path)
    let ragHints: GeneratedHint[] = []
    try {
      const similarHints = await getSimilarHintsFromRAG(
        problemValidation.sanitized!,
        codeValidation.sanitized!,
        {
          problemId,
          pattern: problemPattern,
          limit: 3,
          minSimilarity: 0.5, // Higher threshold for quality
        }
      )

      // Convert RAG hints to GeneratedHint format
      ragHints = similarHints.map((h) => mapRagHintToGeneratedHint(h, 2))

      logger.info("[Hints API] Retrieved hints from RAG", { count: ragHints.length, problemId })
    } catch (ragError) {
      // Non-blocking - continue without RAG hints
      logger.warn("[Hints API] RAG hint retrieval failed:", { error: ragError })
    }

    // Generate new hints with timeout (45 seconds for AI-intensive operation)
    const response = await withTimeout(generateHints(request), 45000, "Hint generation")

    // Generated hints are based on the candidate's current code. RAG hints stay supplementary.
    const allHints = [...response.hints, ...ragHints]

    // Deduplicate by content similarity (simple check)
    const seenContent = new Set<string>()
    const uniqueHints = allHints.filter((hint) => {
      const contentKey = hint.content.substring(0, 50).toLowerCase()
      if (seenContent.has(contentKey)) return false
      seenContent.add(contentKey)
      return true
    })

    // Store generated hints in RAG for future retrieval (non-blocking)
    storeHintsInRAG(
      response.hints.filter((h) => h.source === "ai" || h.source === "pattern-knowledge"),
      problemId,
      problemTitle,
      problemPattern,
      difficulty,
      userId
    ).catch((err) => logger.error("[Hints API] Failed to store hints in RAG:", { error: err }))

    return NextResponse.json({
      hints: uniqueHints,
      struggleLevel: response.struggleLevel,
      recommendedRevealLevel: response.recommendedRevealLevel,
      personalizationApplied: response.personalizationApplied,
      ragHintsCount: ragHints.length,
      metadata: {
        ...response.metadata,
        ragContextUsed: ragHints.length > 0,
      },
    })
  } catch (error) {
    if (error instanceof TimeoutError) {
      return NextResponse.json(
        { error: "Hint generation timed out. Please try again." },
        { status: 504 }
      )
    }
    throw error
  }
}

/**
 * Store generated hints in RAG vector DB for future retrieval
 */
async function storeHintsInRAG(
  hints: GeneratedHint[],
  problemId: string,
  problemTitle: string,
  problemPattern: string | undefined,
  difficulty: string,
  userId: string
): Promise<void> {
  // Only store AI-generated and pattern-knowledge hints (not RAG or user-history)
  const hintsToStore = hints.filter((h) => h.source === "ai" || h.source === "pattern-knowledge")

  if (hintsToStore.length === 0) return

  logger.info("[Hints API] Storing hints in RAG", { count: hintsToStore.length, problemId })

  for (const hint of hintsToStore) {
    try {
      await embedAndStoreHint(problemId, hint.content, hint.level, {
        problemTitle,
        problemType: difficulty === "hard" ? "dsa-hard" : "dsa",
        pattern: problemPattern || hint.metadata?.pattern,
        category: hint.category,
        tags: hint.metadata?.relatedConcepts || [],
        userId,
      })
    } catch (err) {
      // Log but don't fail - storing hints is non-critical
      logger.warn("[Hints API] Failed to store hint:", { hintId: hint.id, error: err })
    }
  }
}

/**
 * Get the next unrevealed hint
 */
async function handleGetNextHint(params: GetNextHintPayload) {
  const {
    userId,
    problemId,
    problemTitle,
    problemText,
    problemPattern,
    difficulty = "medium",
    userCode = "",
    language = "javascript",
    struggleMetrics = {},
    testResults,
    previousHintIds = [],
  } = params

  // Validate required fields
  if (!userId || !problemId || !problemText) {
    return NextResponse.json(
      { error: "userId, problemId, and problemText are required" },
      { status: 400 }
    )
  }

  const fullMetrics = buildStruggleMetrics(struggleMetrics, previousHintIds.length)

  // First, try to get a relevant hint from RAG if we haven't shown many hints yet
  if (previousHintIds.length < 2) {
    try {
      const ragHints = await getSimilarHintsFromRAG(problemText, userCode, {
        problemId,
        pattern: problemPattern,
        hintLevel: (previousHintIds.length + 1) as 1 | 2 | 3 | 4,
        limit: 1,
        minSimilarity: 0.6, // Higher threshold for single hint
      })

      if (ragHints.length > 0) {
        const ragHint = ragHints[0]
        // Check if this hint wasn't already shown
        if (!previousHintIds.includes(`rag_${ragHint.id}`)) {
          const hint = mapRagHintToGeneratedHint(
            ragHint,
            (previousHintIds.length + 1) as 1 | 2 | 3 | 4
          )

          return NextResponse.json({
            hint,
            message: "Retrieved similar hint from knowledge base",
            source: "rag",
          })
        }
      }
    } catch (ragError) {
      logger.warn("[Hints API] RAG retrieval failed for get-next:", { error: ragError })
    }
  }

  // Fall back to generating a new hint
  const request: HintGenerationRequest = buildHintRequest(
    {
      userId,
      problemId,
      problemTitle,
      problemText,
      problemPattern: problemPattern as DSAPattern | undefined,
      difficulty: difficulty as "easy" | "medium" | "hard",
      userCode,
      language,
      testResults,
    },
    fullMetrics
  )

  const hint = await getNextHint(request, previousHintIds)

  if (!hint) {
    return NextResponse.json({
      hint: null,
      message: "No more hints available",
    })
  }

  // Store the new hint in RAG for future use (non-blocking)
  if (hint.source === "ai" || hint.source === "pattern-knowledge") {
    embedAndStoreHint(problemId, hint.content, hint.level, {
      problemTitle,
      problemType: difficulty === "hard" ? "dsa-hard" : "dsa",
      pattern: problemPattern || hint.metadata?.pattern,
      category: hint.category,
      tags: hint.metadata?.relatedConcepts || [],
      userId,
    }).catch((err) => logger.warn("[Hints API] Failed to store hint:", { error: err }))
  }

  return NextResponse.json({
    hint,
    message: "Hint generated successfully",
    source: hint.source,
  })
}

/**
 * User Announcements API
 *
 * Fetches active announcements for the current user based on their tier
 * Handles view tracking and dismissal
 */

import { NextRequest, NextResponse } from "next/server"
import { adminDb } from "@/lib/firebase-admin"
import { verifyToken } from "@/lib/admin/rbac"
import { Timestamp, FieldValue } from "firebase-admin/firestore"
import { logger } from "@/lib/logger"
import type { Announcement } from "@/lib/types/announcements"

export const dynamic = "force-dynamic"

// Re-export for backwards compatibility
export type UserAnnouncement = Announcement

// GET - Fetch active announcements for the current user
export async function GET(request: NextRequest) {
  try {
    if (!adminDb) {
      logger.debug("[Announcements] Database not available")
      return NextResponse.json({ success: true, announcements: [] })
    }

    // Get auth token if present (announcements can work for logged out users too)
    const authHeader = request.headers.get("Authorization")
    let userId: string | null = null
    let userTier: string = "free"

    if (authHeader?.startsWith("Bearer ")) {
      const token = authHeader.substring(7)
      try {
        const auth = await verifyToken(token)
        if (auth.valid && auth.userId) {
          userId = auth.userId

          // Get user's subscription tier
          const userDoc = await adminDb.collection("profiles").doc(userId).get()
          if (userDoc.exists) {
            userTier = userDoc.data()?.subscription_tier || "free"
          }
        }
      } catch {
        // Continue without auth - show public announcements
      }
    }

    const now = Timestamp.now()
    const nowDate = now.toDate()

    // Priority order for sorting (higher = more important)
    const priorityOrder: Record<string, number> = {
      critical: 4,
      warning: 3,
      success: 2,
      info: 1,
    }

    // Fetch all announcements and filter in code to avoid composite index requirement
    let snapshot
    try {
      snapshot = await adminDb.collection("announcements").get()

      logger.debug("[Announcements] Total announcements in DB", { count: snapshot.docs.length })
    } catch (queryError: unknown) {
      logger.error("[Announcements] Query error", { error: queryError as Error })
      return NextResponse.json({ success: true, announcements: [] })
    }

    // Get user's dismissed announcements
    let dismissedIds: string[] = []
    if (userId) {
      const dismissedDoc = await adminDb
        .collection("user_dismissed_announcements")
        .doc(userId)
        .get()

      if (dismissedDoc.exists) {
        dismissedIds = dismissedDoc.data()?.announcementIds || []
      }
    } else {
      // For non-logged in users, check cookie/header
      const dismissedHeader = request.headers.get("X-Dismissed-Announcements")
      if (dismissedHeader) {
        try {
          dismissedIds = JSON.parse(dismissedHeader)
        } catch {
          // Ignore invalid JSON
        }
      }
    }

    const announcements: UserAnnouncement[] = []
    const viewedIds: string[] = []

    for (const doc of snapshot.docs) {
      const data = doc.data()
      const announcementId = doc.id

      // Skip inactive announcements
      if (!data.active) {
        logger.debug("[Announcements] Skipping - not active", { announcementId })
        continue
      }

      // Skip dismissed announcements (if dismissible)
      if (data.dismissible && dismissedIds.includes(announcementId)) {
        logger.debug("[Announcements] Skipping - dismissed by user", { announcementId })
        continue
      }

      // Check date range - handle both Firestore Timestamps and ISO strings
      let startDate: Date
      if (data.startDate?.toDate) {
        startDate = data.startDate.toDate()
      } else if (data.startDate) {
        startDate = new Date(data.startDate)
      } else {
        startDate = new Date(0) // Default to epoch if no start date
      }

      let endDate: Date | null = null
      if (data.endDate?.toDate) {
        endDate = data.endDate.toDate()
      } else if (data.endDate) {
        endDate = new Date(data.endDate)
      }

      if (nowDate < startDate) {
        console.log(
          "[User Announcements API] Skipping",
          announcementId,
          "- not started yet. Start:",
          startDate,
          "Now:",
          nowDate
        )
        continue // Not started yet
      }

      if (endDate && nowDate > endDate) {
        console.log(
          "[User Announcements API] Skipping",
          announcementId,
          "- expired. End:",
          endDate,
          "Now:",
          nowDate
        )
        continue // Expired
      }

      // Check target audience
      const targetAudience = data.targetAudience || "all"
      if (targetAudience !== "all") {
        if (targetAudience === "specific") {
          // Check if user is in the specific list
          const targetUserIds = data.targetUserIds || []
          if (!userId || !targetUserIds.includes(userId)) {
            console.log(
              "[User Announcements API] Skipping",
              announcementId,
              "- user not in specific list"
            )
            continue
          }
        } else {
          // Check subscription tier
          if (targetAudience !== userTier) {
            console.log(
              "[User Announcements API] Skipping",
              announcementId,
              "- tier mismatch. Required:",
              targetAudience,
              "User:",
              userTier
            )
            continue
          }
        }
      }

      logger.debug("[Announcements] Including announcement", { announcementId, title: data.title })
      announcements.push({
        id: announcementId,
        title: data.title,
        message: data.message,
        type: data.type || "banner",
        priority: data.priority || "info",
        dismissible: data.dismissible ?? true,
        cta: data.cta || undefined,
      })

      viewedIds.push(announcementId)
    }

    // Sort announcements by priority (critical first) then by newest
    announcements.sort((a, b) => {
      const priorityDiff = (priorityOrder[b.priority] || 0) - (priorityOrder[a.priority] || 0)
      if (priorityDiff !== 0) return priorityDiff
      // Both have same priority, already sorted by createdAt from Firestore
      return 0
    })

    // Limit to 10 announcements after filtering and sorting
    const limitedAnnouncements = announcements.slice(0, 10)
    const limitedViewedIds = viewedIds.slice(0, 10)

    // Increment view counts (fire and forget)
    if (limitedViewedIds.length > 0) {
      Promise.all(
        limitedViewedIds.map((id) =>
          adminDb
            .collection("announcements")
            .doc(id)
            .update({
              views: FieldValue.increment(1),
            })
            .catch(() => {
              // Ignore errors - view tracking is not critical
            })
        )
      ).catch(() => {})
    }

    return NextResponse.json({
      success: true,
      announcements: limitedAnnouncements,
    })
  } catch (error: unknown) {
    logger.error("[Announcements] GET Error", { error: error as Error })
    return NextResponse.json({ success: true, announcements: [] })
  }
}

// POST - Dismiss an announcement
export async function POST(request: NextRequest) {
  try {
    if (!adminDb) {
      return NextResponse.json({ success: true })
    }

    const body = await request.json()
    const { announcementId } = body

    if (!announcementId) {
      return NextResponse.json(
        { success: false, error: "Announcement ID is required" },
        { status: 400 }
      )
    }

    // Get auth token
    const authHeader = request.headers.get("Authorization")
    let userId: string | null = null

    if (authHeader?.startsWith("Bearer ")) {
      const token = authHeader.substring(7)
      try {
        const auth = await verifyToken(token)
        if (auth.valid && auth.userId) {
          userId = auth.userId
        }
      } catch {
        // Continue without auth
      }
    }

    // Update dismissal count on announcement
    const announcementRef = adminDb.collection("announcements").doc(announcementId)
    const announcementDoc = await announcementRef.get()

    if (!announcementDoc.exists) {
      return NextResponse.json({ success: false, error: "Announcement not found" }, { status: 404 })
    }

    // Check if announcement is dismissible
    if (!announcementDoc.data()?.dismissible) {
      return NextResponse.json(
        { success: false, error: "This announcement cannot be dismissed" },
        { status: 400 }
      )
    }

    // Increment dismissal count
    await announcementRef.update({
      dismissals: FieldValue.increment(1),
    })

    // Store dismissal for logged-in users
    if (userId) {
      const userDismissedRef = adminDb.collection("user_dismissed_announcements").doc(userId)
      const userDismissedDoc = await userDismissedRef.get()

      if (userDismissedDoc.exists) {
        const currentIds = userDismissedDoc.data()?.announcementIds || []
        if (!currentIds.includes(announcementId)) {
          await userDismissedRef.update({
            announcementIds: [...currentIds, announcementId],
            updatedAt: Timestamp.now(),
          })
        }
      } else {
        await userDismissedRef.set({
          announcementIds: [announcementId],
          createdAt: Timestamp.now(),
          updatedAt: Timestamp.now(),
        })
      }
    }

    return NextResponse.json({
      success: true,
      // Return the ID so client can store in localStorage for non-logged-in users
      announcementId,
    })
  } catch (error: unknown) {
    logger.error("[Announcements] POST Error", { error: error as Error })
    return NextResponse.json(
      { success: false, error: "Failed to dismiss announcement" },
      { status: 500 }
    )
  }
}

