export async function POST(request: NextRequest) {
  try {
    console.log("[Welcome Email API] Request received")
    // Verify Firebase ID token for authentication
    const authHeader = request.headers.get("authorization")
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      console.error("[Welcome Email API] Missing authorization header")
      return NextResponse.json({ error: "Authentication required" }, { status: 401 })
    }

    const token = authHeader.substring(7)
    let authenticatedUserId: string

    try {
      const decodedToken = await adminAuth.verifyIdToken(token)
      authenticatedUserId = decodedToken.uid
    } catch {
      return NextResponse.json({ error: "Invalid authentication token" }, { status: 401 })
    }

    const body = await request.json()
    const { userId, email, displayName } = body

    if (!userId || !email) {
      return NextResponse.json({ error: "userId and email are required" }, { status: 400 })
    }

    // Security: Only allow users to send welcome emails to themselves
    if (userId !== authenticatedUserId) {
      return NextResponse.json(
        { error: "Cannot send welcome email for another user" },
        { status: 403 }
      )
    }

    // Check if welcome email already sent
    const profileRef = db.collection("profiles").doc(userId)
    const profileSnap = await profileRef.get()

    if (profileSnap.exists) {
      const profile = profileSnap.data()
      if (profile?.welcome_email_sent) {
        console.log("[Welcome Email API] Welcome email already sent for user:", userId)
        return NextResponse.json({
          success: true,
          message: "Welcome email already sent",
          skipped: true,
        })
      }
    }

    // Send welcome email
    console.log("[Welcome Email API] Sending welcome email to:", email)
    const result = await sendWelcomeEmail(userId, email, displayName)
    console.log("[Welcome Email API] Email send result:", result.success, result.error || "success")

    // Always create in-app notification and initialize preferences, even if email fails
    await Promise.all([
      createWelcomeNotification(userId, displayName),
      initializeNotificationPreferences(userId),
    ])

    if (result.success) {
      // Mark welcome email as sent
      await profileRef.set(
        {
          welcome_email_sent: true,
          welcome_notification_sent: true,
          last_email_sent_at: new Date().toISOString(),
          emails_sent_today: 1,
          notification_preferences: {
            email_notifications_enabled: true,
            welcome_email: true,
            inactivity_reminders: true,
            spaced_repetition_reminders: true,
            milestone_celebrations: true,
            marketing_emails: false,
          },
        },
        { merge: true }
      )

      // Log the email notification
      await db.collection("email_notifications").add({
        user_id: userId,
        email_type: "welcome",
        status: "sent",
        scheduled_at: new Date().toISOString(),
        sent_at: new Date().toISOString(),
        created_at: new Date().toISOString(),
        source: "api",
      })

      // Record analytics for notification
      try {
        const analyticsRef = db.collection("notification_analytics").doc(userId)
        await analyticsRef.set(
          {
            userId,
            totalSent: 1,
            totalOpened: 0,
            totalDismissed: 0,
            byType: {
              welcome: { sent: 1, lastSentAt: new Date().toISOString() },
            },
            openRate: 0,
            updatedAt: new Date().toISOString(),
          },
          { merge: true }
        )
      } catch (analyticsError) {
        console.warn("[Welcome API] Failed to update analytics:", analyticsError)
      }
    } else {
      // Even if email failed, mark that we tried and created in-app notification
      await profileRef.set(
        {
          welcome_notification_sent: true,
          welcome_email_failed: true,
          welcome_email_error: result.error,
          notification_preferences: {
            email_notifications_enabled: true,
            welcome_email: true,
            inactivity_reminders: true,
            spaced_repetition_reminders: true,
            milestone_celebrations: true,
            marketing_emails: false,
          },
        },
        { merge: true }
      )

      // Log the failed email notification for debugging
      await db.collection("email_notifications").add({
        user_id: userId,
        email_type: "welcome",
        status: "failed",
        error: result.error || "Unknown error",
        scheduled_at: new Date().toISOString(),
        created_at: new Date().toISOString(),
        source: "api",
      })
      console.error("[Welcome API] Email failed, logged to email_notifications:", result.error)
    }

    return NextResponse.json({
      success: result.success,
      messageId: result.messageId,
      error: result.error,
      inAppNotificationCreated: true,
    })
  } catch (error: any) {
    console.error("[Welcome Email API] Unexpected error:", error)
    console.error("[Welcome Email API] Error stack:", error?.stack)
    return NextResponse.json(
      {
        success: false,
        error: error.message || "Failed to send welcome email",
      },
      { status: 500 }
    )
  }
}

/**
 * AST-Based Code Execution API
 *
 * This endpoint uses true AST parsing to:
 * 1. Extract function signature from reference solution
 * 2. Auto-generate test inputs from type hints
 * 3. Run both reference and user code
 * 4. Compare outputs
 *
 * No hardcoded test cases needed!
 */

import { NextRequest, NextResponse } from "next/server"
import { executeRateLimit } from "@/lib/rate-limit"
import { enforceQuota } from "@/lib/quota-enforcement"
import { logger } from "@/lib/logger"
import {
  extractSignature,
  generateInputsFromSignature,
  validateWithAST,
  type FunctionSignature,
} from "@/lib/validators"

export const dynamic = "force-dynamic"

// Example reference solutions for common problems
const REFERENCE_SOLUTIONS: Record<string, { code: string; functionName: string }> = {
  "two-sum": {
    functionName: "twoSum",
    code: `
def twoSum(nums: list[int], target: int) -> list[int]:
    """Find two indices whose values sum to target."""
    seen = {}
    for i, n in enumerate(nums):
        if target - n in seen:
            return [seen[target - n], i]
        seen[n] = i
    return []
`
  },
  "valid-palindrome": {
    functionName: "isPalindrome",
    code: `
def isPalindrome(s: str) -> bool:
    """Check if string is a valid palindrome."""
    s = ''.join(c.lower() for c in s if c.isalnum())
    return s == s[::-1]
`
  },
  "reverse-string": {
    functionName: "reverseString",
    code: `
def reverseString(s: list[str]) -> list[str]:
    """Reverse a list of characters in-place."""
    left, right = 0, len(s) - 1
    while left < right:
        s[left], s[right] = s[right], s[left]
        left += 1
        right -= 1
    return s
`
  },
  "contains-duplicate": {
    functionName: "containsDuplicate",
    code: `
def containsDuplicate(nums: list[int]) -> bool:
    """Check if array contains any duplicates."""
    return len(nums) != len(set(nums))
`
  },
  "maximum-subarray": {
    functionName: "maxSubArray",
    code: `
def maxSubArray(nums: list[int]) -> int:
    """Find the contiguous subarray with the largest sum."""
    max_sum = current_sum = nums[0]
    for n in nums[1:]:
        current_sum = max(n, current_sum + n)
        max_sum = max(max_sum, current_sum)
    return max_sum
`
  }
}

export async function POST(request: NextRequest) {
  // Apply rate limiting
  const rateLimitResponse = await executeRateLimit(request)
  if (rateLimitResponse) {
    return rateLimitResponse
  }

  // Enforce quota
  const quotaResult = await enforceQuota(request)
  if (!quotaResult.allowed && quotaResult.response) {
    return quotaResult.response
  }

  try {
    const {
      code,
      scenarioId,
      language = "python",
      // Optional: provide custom reference solution
      referenceSolution,
      functionName: customFunctionName,
      testCount = 5
    } = await request.json()

    logger.info("AST Execute API called", { scenarioId, language })

    if (!code) {
      return NextResponse.json({ error: "Code is required" }, { status: 400 })
    }

    // Get reference solution
    let refSolution: string
    let funcName: string

    if (referenceSolution && customFunctionName) {
      // Use provided reference
      refSolution = referenceSolution
      funcName = customFunctionName
    } else if (scenarioId && REFERENCE_SOLUTIONS[scenarioId]) {
      // Use built-in reference
      refSolution = REFERENCE_SOLUTIONS[scenarioId].code
      funcName = REFERENCE_SOLUTIONS[scenarioId].functionName
    } else {
      return NextResponse.json(
        { error: "Either scenarioId or referenceSolution+functionName required" },
        { status: 400 }
      )
    }

    // Step 1: Extract signature from reference (for debugging/info)
    const signature = await extractSignature(refSolution, language as 'python' | 'javascript', funcName)

    if ('error' in signature) {
      return NextResponse.json(
        { error: `Failed to parse reference solution: ${signature.error}` },
        { status: 400 }
      )
    }

    const funcSignature = Array.isArray(signature) ? signature[0] : signature

    // Step 2: Run full AST-based validation
    const validationResult = await validateWithAST(
      code,
      refSolution,
      language as 'python' | 'javascript' | 'typescript',
      funcName,
      testCount
    )

    // Format results for frontend compatibility
    const results = validationResult.results.map((r, i) => ({
      description: `Test case ${i + 1}`,
      input: r.input,
      expected: r.expected,
      actual: r.actual,
      passed: r.passed,
      error: r.error || null
    }))

    const passedCount = results.filter(r => r.passed).length
    const totalCount = results.length
    const passRate = totalCount > 0 ? Math.round((passedCount / totalCount) * 100) : 0

    return NextResponse.json({
      success: validationResult.passed,
      results,
      summary: {
        total: totalCount,
        passed: passedCount,
        failed: totalCount - passedCount,
        passRate
      },
      // AST-specific info
      ast: {
        referenceSignature: validationResult.referenceSignature,
        userSignature: validationResult.userSignature,
        signatureMatch: validationResult.signatureMatch,
        // Show what types were detected
        detectedParams: funcSignature?.params?.map(p => ({
          name: p.name,
          type: p.type?.name || 'unknown',
          kind: p.type?.kind || 'unknown'
        }))
      },
      error: null
    })
  } catch (error) {
    logger.error("AST Execute API error", { error })
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Failed to execute code" },
      { status: 500 }
    )
  }
}

/**
 * GET endpoint to extract signature from code (useful for debugging)
 */
export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const scenarioId = searchParams.get('scenarioId')

  if (!scenarioId || !REFERENCE_SOLUTIONS[scenarioId]) {
    return NextResponse.json({
      availableScenarios: Object.keys(REFERENCE_SOLUTIONS),
      message: "Provide ?scenarioId=two-sum to see signature"
    })
  }

  const ref = REFERENCE_SOLUTIONS[scenarioId]
  const signature = await extractSignature(ref.code, 'python', ref.functionName)

  return NextResponse.json({
    scenarioId,
    functionName: ref.functionName,
    signature,
    referenceSolution: ref.code
  })
}

/**
 * Feedback Persist API - Save streaming feedback results to Firestore
 *
 * The streaming endpoint (/api/feedback/stream) runs in Edge runtime which
 * cannot access Firebase Admin SDK. This endpoint is called after streaming
 * completes to persist the results to Firestore.
 *
 * Also calculates and saves:
 * - mastery_score (for spaced repetition)
 * - technical_score (average of understanding, problemSolving, codeQuality)
 *
 * NOTE: Silent notes should be passed from client (generated in Edge streaming
 * endpoint). We don't generate them here to avoid Vercel Hobby 10s timeout.
 */

import { NextRequest, NextResponse } from "next/server"
import { adminDb } from "@/lib/firebase-admin"
import { FieldValue } from "firebase-admin/firestore"
import { logger } from "@/lib/logger"
import {
  calculateMasteryScore,
  type MasteryScoreInput,
} from "@/lib/spaced-repetition/mastery-score"
import { completeFeedbackSections } from "@/lib/feedback/structured-feedback-schema"
import type { BugfixEvidenceSummary, BugfixScoreBreakdown } from "@/lib/bugfix/types"

// Vercel Hobby plan has 10 second timeout for serverless functions
// We skip AI calls here to stay within limits - silent notes should be
// passed from the client (generated in Edge streaming endpoint)
export const maxDuration = 10

interface PersistRequest {
  sessionId: string
  userId: string

  // Final scores (from streaming)
  scores: {
    understanding: number
    problemSolving: number
    codeQuality: number
    communication: number
    overall: number
  }

  // Rich feedback content
  feedback: {
    raw: string
    tldr: string
    whatWorked: string[]
    fixNext: string[]
    actionPlan: string[]
  }

  // Session context for mastery calculation
  testsPassed: number
  testsTotal: number
  timeSpentMinutes: number
  hintsUsed: number
  difficulty: "easy" | "medium" | "hard"
  scenarioType: "dsa" | "system-design" | "bugfix"
  scenarioTitle: string
  scenarioId?: string
  scenarioPattern?: string

  // Silent notes (generated by Edge streaming endpoint)
  silentNotes?: Array<{
    type: string
    userSaid: string
    correct?: string
    context?: string
  }>
  bugfixEvidenceSummary?: BugfixEvidenceSummary
  bugfixScoreBreakdown?: BugfixScoreBreakdown
  bugfixPostSessionReport?: Record<string, unknown>

  // Optional context (no longer used for AI generation, kept for logging)
  conversationTranscript?: Array<{
    role: string
    content: string
  }>
  efficiencyMetrics?: {
    optimalTimeComplexity?: string
    optimalSpaceComplexity?: string
  }
}

export async function POST(request: NextRequest) {
  const startTime = Date.now()

  try {
    const body: PersistRequest = await request.json()
    const {
      sessionId,
      userId,
      scores,
      feedback,
      testsPassed,
      testsTotal,
      timeSpentMinutes,
      hintsUsed,
      difficulty,
      scenarioType,
      scenarioTitle,
      scenarioId,
      scenarioPattern,
      silentNotes: providedSilentNotes,
      bugfixEvidenceSummary,
      bugfixScoreBreakdown,
      bugfixPostSessionReport,
      conversationTranscript,
      efficiencyMetrics,
    } = body

    if (!sessionId || !userId) {
      return NextResponse.json({ error: "sessionId and userId are required" }, { status: 400 })
    }

    if (!scores || !feedback) {
      return NextResponse.json({ error: "scores and feedback are required" }, { status: 400 })
    }

    logger.info("[Feedback Persist] Processing request", {
      sessionId,
      userId,
      overallScore: scores.overall,
      hasFeedback: !!feedback.raw,
    })

    // ========================================
    // 1. Calculate Mastery Score
    // ========================================
    const masteryInput: MasteryScoreInput = {
      testCasesPassed: testsPassed,
      testCasesTotal: testsTotal,
      timeSpentMinutes: timeSpentMinutes || 30, // Default 30 min if not provided
      hintsUsed: hintsUsed || 0,
      hintsTotal: 5, // Default assumption
      problemDifficulty: difficulty || "medium",
    }

    const masteryResult = calculateMasteryScore(masteryInput)
    const masteryScore = masteryResult.masteryScore

    // Technical score = average of understanding, problemSolving, codeQuality (excludes communication)
    const technicalScore = Math.round(
      (scores.understanding + scores.problemSolving + scores.codeQuality) / 3
    )

    logger.info("[Feedback Persist] Scores calculated", {
      sessionId,
      masteryScore,
      technicalScore,
      overallScore: scores.overall,
      passRate: testsTotal > 0 ? Math.round((testsPassed / testsTotal) * 100) : 0,
    })

    // ========================================
    // 2. Use Silent Notes from Edge Streaming (no AI call here)
    // ========================================
    // Silent notes are generated in the Edge streaming endpoint which has no timeout.
    // We just receive and save them here.
    const silentNotes = providedSilentNotes || []

    if (silentNotes.length > 0) {
      logger.info("[Feedback Persist] Received silent notes from streaming", {
        sessionId,
        silentNotesCount: silentNotes.length,
      })
    } else if (
      conversationTranscript &&
      conversationTranscript.length > 2 &&
      scenarioType !== "system-design"
    ) {
      // Log if we expected but didn't receive silent notes
      logger.info("[Feedback Persist] No silent notes received from streaming", {
        sessionId,
        transcriptLength: conversationTranscript.length,
      })
    }

    const completeFeedback = completeFeedbackSections(feedback, {
      rawFeedback: feedback.raw,
      scenarioTitle,
      testsPassed,
      testsTotal,
      overallScore: scores.overall,
    })

    // ========================================
    // 3. Update Firestore Session
    // ========================================
    const updateData = {
      // Feedback content
      feedback: feedback.raw,
      feedback_status: "complete" as const,

      // Scores
      performance_score: scores.overall,
      mastery_score: masteryScore,
      technical_score: technicalScore,
      efficiency_score: masteryResult.components.timeEfficiencyScore,

      // Score breakdown (for detailed display)
      score_breakdown: {
        understandingScore: scores.understanding,
        problemSolvingScore: scores.problemSolving,
        codeQualityScore: scores.codeQuality,
        communicationScore: scores.communication,
        overallScore: scores.overall,
      },

      // Structured feedback
      structured_feedback: {
        scores: scores,
        tldr: completeFeedback.tldr,
        whatWorked: completeFeedback.whatWorked,
        fixNext: completeFeedback.fixNext,
        actionPlan: completeFeedback.actionPlan,
        rawFeedback: feedback.raw,
      },

      // Silent notes (things interviewer noticed but didn't correct)
      silent_notes: silentNotes,

      ...(scenarioType === "bugfix" && {
        bugfix_evidence_summary: bugfixEvidenceSummary || null,
        bugfix_score_breakdown: bugfixScoreBreakdown || null,
        bugfix_post_session_report: bugfixPostSessionReport || null,
      }),

      // Mastery breakdown (for analytics/debugging)
      mastery_breakdown: {
        masteryScore: masteryScore,
        components: masteryResult.components,
        timeAnalysis: masteryResult.timeAnalysis,
      },

      // Timestamps
      feedback_persisted_at: FieldValue.serverTimestamp(),
      updated_at: FieldValue.serverTimestamp(),
    }

    await adminDb.collection("interview_sessions").doc(sessionId).update(updateData)

    const latencyMs = Date.now() - startTime

    logger.info("[Feedback Persist] Successfully persisted", {
      sessionId,
      latencyMs,
      masteryScore,
      technicalScore,
      overallScore: scores.overall,
      silentNotesCount: silentNotes.length,
    })

    return NextResponse.json({
      success: true,
      masteryScore,
      technicalScore,
      overallScore: scores.overall,
      silentNotesCount: silentNotes.length,
      latencyMs,
    })
  } catch (error) {
    logger.error("[Feedback Persist] Error", { error })
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Failed to persist feedback" },
      { status: 500 }
    )
  }
}

/**
 * Feedback Process API - Background job processor for rich feedback
 *
 * This endpoint processes pending feedback jobs. It can be:
 * 1. Called directly after instant feedback (fire-and-forget)
 * 2. Called by a cron job to process queued jobs
 * 3. Called manually to retry failed jobs
 *
 * The heavy AI operations happen here, not in the user-facing request.
 */

import { NextRequest, NextResponse } from "next/server"
import { adminDb } from "@/lib/firebase-admin"
import { FieldValue } from "firebase-admin/firestore"
import { generateFeedbackResponse } from "@/lib/ai-providers"
import { logger } from "@/lib/logger"
import type { FeedbackScores, StructuredFeedback } from "@/lib/feedback"
import {
  preScreenConversation,
  validateConversationWithAI,
  getDefaultValidation,
  analyzeAICodeOverlap,
  analyzeCodeCompleteness,
  isBlankDesignTemplate,
  calculateValidatedScores,
  applyScoreFloors,
  critiqueScores,
  parseFeedbackSections,
  completeStructuredFeedback,
  injectScoresIntoFeedback,
  sanitizeFeedbackForScoreConsistency,
  buildSilentNotesContext,
} from "@/lib/feedback"
import {
  extractConversationEvidence,
  buildEvidenceSummary,
} from "@/lib/feedback/structured-extraction"
import { analyzeTranscriptForMistakes } from "@/lib/feedback/transcript-analysis"

// Vercel Pro allows up to 5 minutes for background functions
export const maxDuration = 300

interface ProcessRequest {
  jobId?: string // Process specific job
  processAll?: boolean // Process all pending jobs
  limit?: number // Max jobs to process
}

export async function POST(request: NextRequest) {
  const startTime = Date.now()

  try {
    const body: ProcessRequest = await request.json()
    const { jobId, processAll = false, limit = 5 } = body

    // Get jobs to process
    let jobs: FirebaseFirestore.QueryDocumentSnapshot[] = []

    if (jobId) {
      // Process specific job
      const jobDoc = await adminDb.collection("feedback_jobs").doc(jobId).get()
      if (jobDoc.exists && ["pending", "failed"].includes(jobDoc.data()?.status)) {
        jobs = [jobDoc as FirebaseFirestore.QueryDocumentSnapshot]
      }
    } else if (processAll) {
      // Process pending jobs
      const snapshot = await adminDb
        .collection("feedback_jobs")
        .where("status", "==", "pending")
        .orderBy("createdAt", "asc")
        .limit(limit)
        .get()
      jobs = snapshot.docs
    }

    if (jobs.length === 0) {
      return NextResponse.json({ message: "No jobs to process", processed: 0 })
    }

    logger.info("[Feedback Process] Starting batch", {
      jobCount: jobs.length,
      firstJob: jobs[0]?.id,
    })

    const results: Array<{ jobId: string; status: "complete" | "failed"; error?: string }> = []

    // Process jobs sequentially to avoid overloading AI providers
    for (const jobDoc of jobs) {
      const job = jobDoc.data()
      const currentJobId = jobDoc.id

      try {
        // Mark as processing
        await adminDb.collection("feedback_jobs").doc(currentJobId).update({
          status: "processing",
          startedAt: FieldValue.serverTimestamp(),
          progress: 0,
        })

        // Process the job
        const result = await processJob(currentJobId, job)

        // Mark as complete
        await adminDb.collection("feedback_jobs").doc(currentJobId).update({
          status: "complete",
          completedAt: FieldValue.serverTimestamp(),
          output: result,
          progress: 100,
        })

        // Update the interview session with final feedback
        await adminDb
          .collection("interview_sessions")
          .doc(job.sessionId)
          .update({
            feedback_status: "complete",
            feedback: result.feedback,
            performance_score: result.scores.overall,
            technical_score: result.technicalScore,
            score_breakdown: {
              understandingScore: result.scores.understanding,
              problemSolvingScore: result.scores.problemSolving,
              codeQualityScore: result.scores.codeQuality,
              communicationScore: result.scores.communication,
              overallScore: result.scores.overall,
            },
            structured_feedback: result.structured,
            updated_at: FieldValue.serverTimestamp(),
          })

        results.push({ jobId: currentJobId, status: "complete" })

        logger.info("[Feedback Process] Job completed", {
          jobId: currentJobId,
          sessionId: job.sessionId,
          overallScore: result.scores.overall,
        })
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : "Unknown error"

        // Mark as failed
        await adminDb.collection("feedback_jobs").doc(currentJobId).update({
          status: "failed",
          error: errorMessage,
          failedAt: FieldValue.serverTimestamp(),
        })

        results.push({ jobId: currentJobId, status: "failed", error: errorMessage })

        logger.error("[Feedback Process] Job failed", {
          jobId: currentJobId,
          error: errorMessage,
        })
      }
    }

    const totalTime = Date.now() - startTime

    return NextResponse.json({
      processed: results.length,
      results,
      totalTimeMs: totalTime,
    })
  } catch (error) {
    logger.error("[Feedback Process] Batch error", { error })
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Processing failed" },
      { status: 500 }
    )
  }
}

/**
 * Process a single feedback job - this is where the heavy AI work happens
 */
async function processJob(
  jobId: string,
  job: FirebaseFirestore.DocumentData
): Promise<{
  feedback: string
  scores: FeedbackScores
  technicalScore: number
  structured: StructuredFeedback
  constitutionalAICritique?: Record<string, unknown>
}> {
  const input = job.input
  const {
    code,
    language,
    scenarioTitle,
    scenarioType,
    scenarioId,
    scenarioDifficulty,
    testsPassed,
    testsTotal,
    efficiencyScore,
    conversationTranscript,
    partnerMessages,
    efficiencyMetrics,
    silentNotes,
  } = input

  // Update progress
  const updateProgress = async (progress: number) => {
    await adminDb.collection("feedback_jobs").doc(jobId).update({ progress })
  }

  // ========================================
  // PHASE 1: Pre-processing (10%)
  // ========================================
  await updateProgress(10)

  const passRate = testsTotal > 0 ? (testsPassed / testsTotal) * 100 : 0
  const preScreen = preScreenConversation(conversationTranscript)
  const aiCodeOverlap = analyzeAICodeOverlap(code, partnerMessages)
  const hasBlindCopying = aiCodeOverlap.hasHighOverlap && !aiCodeOverlap.modificationsMade

  // Prepare transcript messages
  const transcriptMessages =
    conversationTranscript && Array.isArray(conversationTranscript)
      ? conversationTranscript.map(
          (msg: { type?: string; role?: string; message?: string; content?: string }) => ({
            role:
              msg.type === "user" || msg.role === "user" || msg.role === "candidate"
                ? ("user" as const)
                : ("interviewer" as const),
            content: msg.message || msg.content || "",
          })
        )
      : []

  // ========================================
  // PHASE 2: AI Validation & Extraction (40%)
  // ========================================
  await updateProgress(20)

  // Run AI operations in parallel
  const shouldValidateWithAI =
    scenarioType === "system-design"
      ? true
      : preScreen.hasContent &&
        !preScreen.suspiciousPatterns.possibleGibberish &&
        preScreen.candidateMessageCount >= 1

  const [aiValidation, extractedEvidence] = await Promise.all([
    shouldValidateWithAI
      ? validateConversationWithAI(
          conversationTranscript,
          code,
          efficiencyMetrics
            ? {
                time: efficiencyMetrics.estimatedTimeComplexity,
                space: efficiencyMetrics.estimatedSpaceComplexity,
              }
            : null
        ).catch(() => getDefaultValidation())
      : Promise.resolve(getDefaultValidation()),
    transcriptMessages.length > 0
      ? extractConversationEvidence(transcriptMessages, {
          title: scenarioTitle,
          optimalTimeComplexity: efficiencyMetrics?.optimalTimeComplexity || "O(n)",
          optimalSpaceComplexity: efficiencyMetrics?.optimalSpaceComplexity || "O(1)",
          criticalEdgeCases: ["empty input", "single element", "null values"],
        }).catch(() => undefined)
      : Promise.resolve(undefined),
  ])

  await updateProgress(40)

  // Reconcile evidence sources
  if (extractedEvidence) {
    if (extractedEvidence.approach.explained && extractedEvidence.approach.quote) {
      aiValidation.approachExplained = true
      aiValidation.approachQuality =
        aiValidation.approachQuality === "none" ? "basic" : aiValidation.approachQuality
    }
    if (extractedEvidence.timeComplexity.mentioned) {
      aiValidation.complexityDiscussed = true
      if (extractedEvidence.timeComplexity.value) {
        aiValidation.complexityAccurate = extractedEvidence.timeComplexity.isCorrect ?? false
        aiValidation.statedComplexity = extractedEvidence.timeComplexity.value
      }
    }
    if (extractedEvidence.edgeCases.mentionedByCandidate.length > 0) {
      aiValidation.edgeCasesConsidered = true
    }
  }

  // ========================================
  // PHASE 3: Score Calculation (50%)
  // ========================================
  await updateProgress(50)

  // Calculate validated scores
  const validatedScores = calculateValidatedScores(
    passRate,
    efficiencyMetrics,
    preScreen,
    aiValidation,
    scenarioType,
    code,
    extractedEvidence
  )

  // Apply AI copying penalty
  if (hasBlindCopying && scenarioType !== "system-design") {
    validatedScores.understanding = Math.min(
      validatedScores.understanding,
      Math.max(30, validatedScores.understanding - 25)
    )
  }

  // Apply score floors
  const algorithmicScores = applyScoreFloors(
    validatedScores,
    passRate,
    efficiencyMetrics?.efficiencyScore,
    aiValidation
  )

  // ========================================
  // PHASE 4: Constitutional AI Critique (60%)
  // ========================================
  await updateProgress(60)

  const scoreCritique = await critiqueScores(algorithmicScores, {
    passRate,
    scenarioType: scenarioType || "dsa",
    aiValidation,
    codeCompleteness: code ? analyzeCodeCompleteness(code, language || "python") : undefined,
    hasBlindCopying,
    extractedEvidence,
    problemContext: {
      title: scenarioTitle,
      optimalTimeComplexity: efficiencyMetrics?.optimalTimeComplexity || "O(n)",
      optimalSpaceComplexity: efficiencyMetrics?.optimalSpaceComplexity || "O(1)",
    },
    conversationTranscript: conversationTranscript?.map(
      (msg: { type?: string; role?: string; message?: string; content?: string }) => ({
        role: msg.type === "user" || msg.role === "user" ? "candidate" : "interviewer",
        content: msg.message || msg.content || "",
      })
    ),
  })

  const finalScores =
    scoreCritique.madeChanges && scoreCritique.adjustedScores
      ? scoreCritique.adjustedScores
      : algorithmicScores

  // ========================================
  // PHASE 5: Transcript Analysis (70%)
  // ========================================
  await updateProgress(70)

  let analyzedSilentNotes = silentNotes || []
  if (transcriptMessages.length > 0 && scenarioType !== "system-design") {
    try {
      const analysisResult = await analyzeTranscriptForMistakes(
        transcriptMessages,
        {
          title: scenarioTitle,
          optimalTimeComplexity: efficiencyMetrics?.optimalTimeComplexity || "O(n)",
          optimalSpaceComplexity: efficiencyMetrics?.optimalSpaceComplexity || "O(1)",
          criticalEdgeCases: ["empty input", "single element", "null/undefined values"],
          scenarioType,
        },
        extractedEvidence
      )

      if (analysisResult.silentNotes.length > 0) {
        const existingKeys = new Set(
          analyzedSilentNotes.map(
            (n: { type: string; context?: string }) => `${n.type}:${n.context || ""}`
          )
        )
        const newNotes = analysisResult.silentNotes.filter(
          (n) => !existingKeys.has(`${n.type}:${n.context || ""}`)
        )
        analyzedSilentNotes = [...analyzedSilentNotes, ...newNotes]
      }
    } catch {
      // Continue with existing notes
    }
  }

  // ========================================
  // PHASE 6: Generate AI Feedback (90%)
  // ========================================
  await updateProgress(80)

  // Build prompt (simplified version - full version in generate-feedback)
  const systemInstruction = buildSystemInstruction(scenarioType)
  const prompt = buildPrompt({
    scenarioTitle,
    scenarioType,
    passRate,
    finalScores,
    aiValidation: aiValidation as unknown as Record<string, unknown>,
    extractedEvidence: extractedEvidence as unknown as Record<string, unknown> | undefined,
    analyzedSilentNotes,
    code,
    language,
    efficiencyMetrics,
    testsPassed,
    testsTotal,
  })

  const aiResponse = await generateFeedbackResponse(systemInstruction, prompt, [], {
    userId: job.userId,
    sessionId: job.sessionId,
    scenarioId,
  })

  await updateProgress(90)

  // ========================================
  // PHASE 7: Post-processing (100%)
  // ========================================
  const rawFeedback = aiResponse.text

  // Inject authoritative scores
  const feedbackWithScores = injectScoresIntoFeedback(rawFeedback, finalScores, scenarioType)

  // Sanitize for consistency
  const finalFeedback = sanitizeFeedbackForScoreConsistency(feedbackWithScores, finalScores, {
    approachExplained: extractedEvidence?.approach.explained ?? aiValidation.approachExplained,
    complexityDiscussed:
      extractedEvidence?.timeComplexity.mentioned ?? aiValidation.complexityDiscussed,
  })

  // Build structured response
  const sections = parseFeedbackSections(finalFeedback)

  const scores: FeedbackScores = {
    understanding: finalScores.understanding,
    problemSolving: finalScores.problemSolving,
    codeQuality: finalScores.codeQuality,
    communication: finalScores.communication,
    correctness: finalScores.codeQuality,
    efficiency: efficiencyMetrics?.efficiencyScore || 50,
    reasoningExplanation: finalScores.communication,
    aiCollaboration: 50,
    overall: finalScores.overall,
  }

  const structured: StructuredFeedback = completeStructuredFeedback(
    {
      scores,
      tldr: sections.tldr,
      whatWorked: sections.whatWorked,
      fixNext: sections.fixNext,
      actionPlan: sections.actionPlan,
      aiWatchlist: sections.aiWatchlist,
      rawFeedback: finalFeedback,
    },
    {
      rawFeedback: finalFeedback,
      scenarioTitle,
      testsPassed,
      testsTotal,
    }
  )

  // Calculate technical score (same as instant)
  const technicalScore = Math.round(
    (finalScores.understanding + finalScores.problemSolving + finalScores.codeQuality) / 3
  )

  return {
    feedback: finalFeedback,
    scores,
    technicalScore,
    structured,
    ...(scoreCritique.madeChanges
      ? {
          constitutionalAICritique: {
            critiques: scoreCritique.critiques,
            reasoning: scoreCritique.reasoning,
            originalScores: algorithmicScores,
            adjustedScores: scoreCritique.adjustedScores,
          },
        }
      : {}),
  }
}

function buildSystemInstruction(scenarioType: string): string {
  const baseRules = `
IMPORTANT: Scores are PRE-CALCULATED. Just reference them in your feedback. Focus on actionable narrative.

RULES:
- ~200 words max. Be concise.
- Focus on actionable improvements.
- Reference the conversation and discussion quality.
`

  if (scenarioType === "system-design") {
    return `You are a brutally honest senior system design interviewer at a FAANG company. Be direct—if they didn't try, call it out.
${baseRules}

## OUTPUT FORMAT FOR SYSTEM DESIGN

**TL;DR** – One sentence summary.

**Score Snapshot** (use PRE-CALCULATED SCORES)
- Requirements: X/100
- Architecture: X/100
- Scalability: X/100
- Communication: X/100
- Overall: X/100

**What Worked**
- specific strengths

**Fix Next**
- specific improvements

**Action Plan**
1. Immediate action
2. Short-term goal
3. Long-term goal
`
  }

  return `You are a senior interviewer delivering a focused, constructive technical debrief. Be HONEST about gaps, but RECOGNIZE ACHIEVEMENTS.
${baseRules}

## OUTPUT FORMAT

**TL;DR** – One sentence summary.

**Score Snapshot** (use PRE-CALCULATED SCORES)
- Understanding: X/100
- Problem-Solving: X/100
- Code Quality: X/100
- Communication: X/100
- Overall: X/100

**What Worked**
- specific strengths

**Fix Next**
- specific improvements

**Action Plan**
1. Immediate action
2. Short-term goal
3. Long-term goal
`
}

function buildPrompt(data: {
  scenarioTitle: string
  scenarioType: string
  passRate: number
  finalScores: Record<string, number>
  aiValidation: Record<string, unknown>
  extractedEvidence?: Record<string, unknown>
  analyzedSilentNotes: unknown[]
  code: string
  language: string
  efficiencyMetrics?: Record<string, unknown>
  testsPassed: number
  testsTotal: number
}): string {
  const {
    scenarioTitle,
    scenarioType,
    passRate,
    finalScores,
    aiValidation,
    extractedEvidence,
    analyzedSilentNotes,
    code,
    language,
    efficiencyMetrics,
    testsPassed,
    testsTotal,
  } = data

  const evidenceSummary = extractedEvidence
    ? buildEvidenceSummary(
        extractedEvidence as unknown as Parameters<typeof buildEvidenceSummary>[0]
      )
    : ""
  const silentNotesContext = buildSilentNotesContext(
    analyzedSilentNotes as Parameters<typeof buildSilentNotesContext>[0]
  )

  return `Generate interview feedback for:

PROBLEM: ${scenarioTitle} (${scenarioType?.toUpperCase() || "DSA"})

TEST RESULTS:
- Passed: ${testsPassed}/${testsTotal} (${Math.round(passRate)}%)

PRE-CALCULATED SCORES (use these exactly):
${
  scenarioType === "system-design"
    ? `- Requirements: ${finalScores.understanding}/100
- Architecture: ${finalScores.problemSolving}/100
- Scalability: ${finalScores.codeQuality}/100
- Communication: ${finalScores.communication}/100`
    : `- Understanding: ${finalScores.understanding}/100
- Problem-Solving: ${finalScores.problemSolving}/100
- Code Quality: ${finalScores.codeQuality}/100
- Communication: ${finalScores.communication}/100`
}
- Overall: ${finalScores.overall}/100

COMMUNICATION ANALYSIS:
- Approach explained: ${(aiValidation as Record<string, unknown>).approachExplained ? "YES" : "NO"}
- Complexity discussed: ${(aiValidation as Record<string, unknown>).complexityDiscussed ? "YES" : "NO"}

${evidenceSummary ? `EXTRACTED EVIDENCE:\n${evidenceSummary}\n` : ""}
${silentNotesContext}

CODE (${language || "javascript"}):
\`\`\`
${code?.slice(0, 1500) || "[No code]"}
\`\`\`

${
  efficiencyMetrics
    ? `EFFICIENCY:
- Time: ${(efficiencyMetrics as Record<string, unknown>).estimatedTimeComplexity || "N/A"}
- Space: ${(efficiencyMetrics as Record<string, unknown>).estimatedSpaceComplexity || "N/A"}
- Score: ${(efficiencyMetrics as Record<string, unknown>).efficiencyScore || "N/A"}/100`
    : ""
}

Generate concise, actionable feedback using the scores above.`
}

/**
 * Streaming Feedback API - Edge Function with NO TIMEOUT
 *
 * Edge functions don't timeout when streaming responses.
 * This allows us to run all AI operations and stream the result
 * without hitting Vercel's 10s hobby plan limit.
 *
 * Flow:
 * 1. Receive session data
 * 2. Calculate instant scores (no AI, < 100ms)
 * 3. Stream scores immediately
 * 4. Run AI operations
 * 5. Stream rich feedback as it generates
 */

import { NextRequest } from "next/server"
import {
  generateFeedbackResponseEdge,
  validateConversationEdge,
  extractConversationEvidenceEdge,
} from "@/lib/ai-providers-edge"
// Direct imports to avoid pulling in Node.js dependencies via barrel exports
import { preScreenConversation } from "@/lib/feedback/pre-screening"
import { analyzeCodeCompleteness } from "@/lib/feedback/completeness-analysis"
import { parseFeedbackSections, buildSilentNotesContext } from "@/lib/feedback/parsers"
import { completeFeedbackSections } from "@/lib/feedback/structured-feedback-schema"
import { calculateInstantScores, buildSignalsFromMetrics } from "@/lib/feedback/score-accumulator"
import {
  analyzeAICodeOverlap,
  getDefaultValidation,
  calculateValidatedScores,
  applyScoreFloors,
  buildEvidenceSummary,
} from "@/lib/feedback/edge-utils"
import { analyzeTranscriptForMistakesEdge } from "@/lib/feedback/transcript-analysis-edge"
import { summarizeBugfixEvidence } from "@/lib/bugfix/evidence"
import { buildBugfixPostSessionReport } from "@/lib/bugfix/report"
import { calculateBugfixEvidenceScore } from "@/lib/bugfix/scoring"
import { scoreBugfixSemantics, BUGFIX_SEMANTIC_NEUTRAL } from "@/lib/bugfix/semantic-scorer"
import type {
  BugfixEvidenceEvent,
  BugfixEvidenceSummary,
  BugfixScoreBreakdown,
} from "@/lib/bugfix/types"

// CRITICAL: Edge runtime for no timeout on streaming
export const runtime = "edge"

export async function POST(request: NextRequest) {
  const encoder = new TextEncoder()

  // Create a TransformStream for streaming
  const stream = new TransformStream()
  const writer = stream.writable.getWriter()

  // Helper to send SSE events
  const sendEvent = async (event: string, data: unknown) => {
    const payload = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`
    await writer.write(encoder.encode(payload))
  }

  // Process in background while streaming
  const processRequest = async () => {
    try {
      const body = await request.json()
      const {
        sessionId,
        userId,
        code,
        language,
        testsPassed,
        testsTotal,
        scenarioType,
        scenarioTitle,
        scenarioId,
        scenarioDifficulty,
        scenarioPattern,
        conversationTranscript,
        partnerMessages,
        phaseTracking,
        silentNotes: existingSilentNotes,
        efficiencyMetrics,
        submittedFromPhase,
        testsRanBeforeSubmit,
        bugfixEvidenceEvents,
        bugfixExpectedTouchedFiles,
        bugfixRootCause,
        bugfixPrevention,
        bugfixRootCauseRubric,
        bugfixGroundTruth,
      } = body

      // ========================================
      // PHASE 1: Instant Scores (< 100ms, no AI)
      // ========================================
      await sendEvent("phase", { phase: "calculating_scores", message: "Calculating scores..." })

      const codeAnalysis = code
        ? analyzeCodeCompleteness(code, language || "javascript")
        : { isIncomplete: true, hasActualLogic: false }

      // Derive actual message counts from transcript (not hardcoded 0)
      const transcriptArray =
        conversationTranscript && Array.isArray(conversationTranscript)
          ? conversationTranscript
          : []
      const candidateMessageCount = transcriptArray.filter(
        (m: { role?: string; type?: string }) =>
          m.role === "candidate" || m.role === "user" || m.type === "user"
      ).length
      const interviewerMessageCount = transcriptArray.filter(
        (m: { role?: string; type?: string }) =>
          m.role === "interviewer" || m.type === "interviewer"
      ).length

      const signals = buildSignalsFromMetrics({
        testsPassed,
        testsTotal,
        efficiencyScore: efficiencyMetrics?.efficiencyScore ?? 50,
        codeLength: code?.length || 0,
        hasActualLogic: codeAnalysis.hasActualLogic,
        approachExplained: phaseTracking?.conversationTracker?.approachExplained || false,
        complexityDiscussed: phaseTracking?.conversationTracker?.timeComplexityMentioned || false,
        edgeCasesIdentified: phaseTracking?.conversationTracker?.edgeCasesMentioned || [],
        hintsViewed: [],
        totalInterviewerMessages: interviewerMessageCount,
        totalChatMessages: candidateMessageCount,
        aiSuggestionsCopiedBlindly: 0,
        testsRanBeforeSubmit: testsRanBeforeSubmit ?? false,
        submittedFromPhase: submittedFromPhase || "unknown",
        scenarioType: scenarioType || "dsa",
        difficulty: scenarioDifficulty || "medium",
      })

      const instantScores = calculateInstantScores(signals)

      // Send instant scores immediately
      await sendEvent("scores", {
        understanding: instantScores.understanding,
        problemSolving: instantScores.problemSolving,
        codeQuality: instantScores.codeQuality,
        communication: instantScores.communication,
        overall: instantScores.overall,
        flags: {
          silentSolution: instantScores.silentSolution,
          incompleteSolution: instantScores.incompleteSolution,
          aiCopyingDetected: instantScores.aiCopyingDetected,
        },
      })

      // ========================================
      // PHASE 2: AI Validation (parallel)
      // ========================================
      await sendEvent("phase", { phase: "analyzing", message: "Analyzing your interview..." })

      const passRate = testsTotal > 0 ? (testsPassed / testsTotal) * 100 : 0
      const preScreen = preScreenConversation(conversationTranscript)
      const aiCodeOverlap = analyzeAICodeOverlap(code, partnerMessages)
      const hasBlindCopying = aiCodeOverlap.hasHighOverlap && !aiCodeOverlap.modificationsMade
      const bugfixEvidenceSummary: BugfixEvidenceSummary | null =
        scenarioType === "bugfix" && Array.isArray(bugfixEvidenceEvents)
          ? summarizeBugfixEvidence({
              events: bugfixEvidenceEvents as BugfixEvidenceEvent[],
              expectedTouchedFiles: Array.isArray(bugfixExpectedTouchedFiles)
                ? bugfixExpectedTouchedFiles
                : [],
            })
          : null
      const bugfixScoreBreakdownPreSemantic: BugfixScoreBreakdown | null = bugfixEvidenceSummary
        ? calculateBugfixEvidenceScore(bugfixEvidenceSummary, {
            difficulty: scenarioDifficulty || "medium",
          })
        : null

      // Prepare transcript
      const transcriptMessages =
        conversationTranscript && Array.isArray(conversationTranscript)
          ? conversationTranscript.map(
              (msg: { type?: string; role?: string; message?: string; content?: string }) => ({
                role:
                  msg.type === "user" || msg.role === "user" || msg.role === "candidate"
                    ? ("user" as const)
                    : ("interviewer" as const),
                content: msg.message || msg.content || "",
              })
            )
          : []

      // Run validation, extraction, and silent notes analysis in parallel
      const shouldValidateWithAI =
        scenarioType === "system-design" ||
        (preScreen.hasContent && preScreen.candidateMessageCount >= 1)

      // Problem context for silent notes analysis
      const problemContext = {
        title: scenarioTitle || "Unknown Problem",
        optimalTimeComplexity: efficiencyMetrics?.optimalTimeComplexity || "O(n)",
        optimalSpaceComplexity: efficiencyMetrics?.optimalSpaceComplexity || "O(1)",
        criticalEdgeCases: ["empty input", "single element", "null values"],
        scenarioType: scenarioType || "dsa",
      }

      const [aiValidation, extractedEvidence, silentNotesAnalysis, bugfixSemanticScores] =
        await Promise.all([
          shouldValidateWithAI
            ? validateConversationEdge(
                transcriptMessages,
                code,
                efficiencyMetrics
                  ? {
                      time: efficiencyMetrics.estimatedTimeComplexity,
                      space: efficiencyMetrics.estimatedSpaceComplexity,
                    }
                  : null
              ).catch(() => getDefaultValidation())
            : Promise.resolve(getDefaultValidation()),
          transcriptMessages.length > 0
            ? extractConversationEvidenceEdge(transcriptMessages, problemContext).catch(() => null)
            : Promise.resolve(null),
          // Generate silent notes if we don't have existing ones and have transcript
          !existingSilentNotes?.length && transcriptMessages.length >= 2
            ? analyzeTranscriptForMistakesEdge(
                transcriptMessages.map((m) => ({
                  role: m.role,
                  content: m.content,
                })),
                problemContext
              ).catch((err) => {
                console.warn("[Streaming Feedback] Silent notes analysis failed:", err)
                return { silentNotes: [], analysisMetadata: null }
              })
            : Promise.resolve({ silentNotes: existingSilentNotes || [], analysisMetadata: null }),
          scenarioType === "bugfix" && bugfixEvidenceSummary && bugfixScoreBreakdownPreSemantic
            ? scoreBugfixSemantics({
                deterministicSubScores: bugfixScoreBreakdownPreSemantic,
                evidenceSummary: bugfixEvidenceSummary,
                rootCauseRubric: Array.isArray(bugfixRootCauseRubric) ? bugfixRootCauseRubric : [],
                bugDescription: typeof bugfixGroundTruth === "string" ? bugfixGroundTruth : "",
                conversationExcerpt: transcriptMessages
                  .slice(-10)
                  .map((m) => `${m.role.toUpperCase()}: ${m.content}`)
                  .join("\n\n")
                  .slice(0, 2000),
              }).catch(() => BUGFIX_SEMANTIC_NEUTRAL)
            : Promise.resolve(BUGFIX_SEMANTIC_NEUTRAL),
        ])

      // Use generated silent notes or existing ones
      const finalSilentNotes = silentNotesAnalysis.silentNotes || existingSilentNotes || []
      if (silentNotesAnalysis.analysisMetadata) {
        console.log("[Streaming Feedback] Silent notes generated:", {
          count: finalSilentNotes.length,
          algorithmicDetections: silentNotesAnalysis.analysisMetadata.algorithmicDetections,
          semanticDetections: silentNotesAnalysis.analysisMetadata.semanticDetections,
        })
      }

      // Reconcile evidence - extracted evidence overrides AI when it finds concrete quotes
      if (extractedEvidence) {
        if (extractedEvidence.approach.explained) {
          aiValidation.approachExplained = true
        }
        if (extractedEvidence.timeComplexity.mentioned) {
          aiValidation.complexityDiscussed = true
          if (extractedEvidence.timeComplexity.isCorrect !== undefined) {
            aiValidation.complexityAccurate = extractedEvidence.timeComplexity.isCorrect
          }
        }
        if (extractedEvidence.edgeCases.mentionedByCandidate.length > 0) {
          aiValidation.edgeCasesConsidered = true
        }
      }

      // ========================================
      // PHASE 3: Calculate Final Scores
      // ========================================
      // Note: extractedEvidence is already merged into aiValidation above
      const bugfixScoreBreakdown: BugfixScoreBreakdown | null = bugfixEvidenceSummary
        ? calculateBugfixEvidenceScore(bugfixEvidenceSummary, {
            difficulty: scenarioDifficulty || "medium",
            semanticOverrides: bugfixSemanticScores,
          })
        : null

      const validatedScores = calculateValidatedScores(
        passRate,
        efficiencyMetrics,
        preScreen,
        aiValidation,
        scenarioType,
        code,
        null // Evidence already merged into aiValidation
      )

      if (hasBlindCopying && scenarioType !== "system-design") {
        validatedScores.understanding = Math.max(30, validatedScores.understanding - 25)
      }

      let finalScores = applyScoreFloors(
        validatedScores,
        passRate,
        efficiencyMetrics?.efficiencyScore,
        aiValidation
      )

      if (bugfixScoreBreakdown) {
        finalScores = {
          ...mapBugfixScoreToFeedbackScores(bugfixScoreBreakdown),
          silentSolution: finalScores.silentSolution,
        }
      }

      // Send refined scores
      await sendEvent("refined_scores", {
        understanding: finalScores.understanding,
        problemSolving: finalScores.problemSolving,
        codeQuality: finalScores.codeQuality,
        communication: finalScores.communication,
        overall: finalScores.overall,
      })

      // ========================================
      // PHASE 4: Generate AI Feedback
      // ========================================
      await sendEvent("phase", {
        phase: "generating",
        message: "Generating personalized feedback...",
      })

      const systemInstruction = buildSystemInstruction(scenarioType)
      const prompt = buildPrompt({
        scenarioTitle,
        scenarioType,
        passRate,
        finalScores: finalScores as unknown as Record<string, number>,
        aiValidation: aiValidation as unknown as Record<string, unknown>,
        extractedEvidence,
        bugfixEvidenceSummary,
        bugfixScoreBreakdown,
        bugfixSemanticScores,
        bugfixRootCause,
        bugfixPrevention,
        bugfixRootCauseRubric: Array.isArray(bugfixRootCauseRubric) ? bugfixRootCauseRubric : [],
        silentNotes: finalSilentNotes,
        code,
        language,
        efficiencyMetrics,
        testsPassed,
        testsTotal,
      })

      const aiResponse = await generateFeedbackResponseEdge(systemInstruction, prompt)

      const feedback = aiResponse.text

      // Parse sections
      const parsedSections = parseFeedbackSections(feedback)
      const sections = completeFeedbackSections(parsedSections, {
        rawFeedback: feedback,
        scenarioTitle,
        testsPassed,
        testsTotal,
        overallScore: finalScores.overall,
      })

      // ========================================
      // PHASE 5: Stream Final Results
      // ========================================
      await sendEvent("phase", { phase: "complete", message: "Done!" })

      await sendEvent("feedback", {
        raw: feedback,
        tldr: sections.tldr || "",
        whatWorked: sections.whatWorked || [],
        fixNext: sections.fixNext || [],
        actionPlan: sections.actionPlan || [],
        silentNotes: finalSilentNotes,
        bugfixEvidenceSummary,
        bugfixScoreBreakdown,
        bugfixPostSessionReport:
          bugfixEvidenceSummary && bugfixScoreBreakdown
            ? buildBugfixPostSessionReport({
                evidence: bugfixEvidenceSummary,
                score: bugfixScoreBreakdown,
                rootCauseText: typeof bugfixRootCause === "string" ? bugfixRootCause : undefined,
                preventionText: typeof bugfixPrevention === "string" ? bugfixPrevention : undefined,
              })
            : undefined,
        scores: {
          understanding: finalScores.understanding,
          problemSolving: finalScores.problemSolving,
          codeQuality: finalScores.codeQuality,
          communication: finalScores.communication,
          overall: finalScores.overall,
        },
      })

      await sendEvent("done", { success: true })
    } catch (error) {
      console.error("[Streaming Feedback] Error", error)
      await sendEvent("error", {
        message: error instanceof Error ? error.message : "Failed to generate feedback",
      })
    } finally {
      await writer.close()
    }
  }

  // Start processing (don't await - let it stream)
  processRequest()

  // Return the stream immediately
  return new Response(stream.readable, {
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache",
      Connection: "keep-alive",
    },
  })
}

function buildSystemInstruction(scenarioType: string): string {
  const baseRules = `
IMPORTANT: Scores are PRE-CALCULATED. Reference them in your feedback. Focus on actionable narrative.

RULES:
- ~200 words max. Be concise.
- Focus on actionable improvements.
- Be specific - reference actual code/conversation.
`

  if (scenarioType === "system-design") {
    return `You are a senior system design interviewer. Be direct and specific.
${baseRules}

FORMAT:
**TL;DR** – One sentence.
**Score Snapshot** (use PRE-CALCULATED SCORES)
**What Worked** – 2-3 specific strengths with evidence
**Fix Next** – 2-3 specific improvements
**Action Plan** – 3 concrete next steps
`
  }

  if (scenarioType === "bugfix") {
    return `You are a senior debugging interviewer. Be direct, evidence-based, and specific.
${baseRules}

FORMAT:
**TL;DR** – One sentence.
**Debugging Score Snapshot** (use PRE-CALCULATED SCORES)
**What Worked** – 2-3 specific strengths with evidence from files, tests, or notes
**Fix Next** – 2-3 concrete debugging process improvements
**Action Plan** – 3 concrete next debugging habits
`
  }

  return `You are a senior technical interviewer. Be honest about gaps but recognize achievements.
${baseRules}

FORMAT:
**TL;DR** – One sentence.
**Score Snapshot** (use PRE-CALCULATED SCORES)
**What Worked** – 2-3 specific strengths with evidence
**Fix Next** – 2-3 specific improvements
**Action Plan** – 3 concrete next steps
`
}

function buildPrompt(data: {
  scenarioTitle: string
  scenarioType: string
  passRate: number
  finalScores: Record<string, number>
  aiValidation: Record<string, unknown>
  extractedEvidence?: unknown
  bugfixEvidenceSummary?: BugfixEvidenceSummary | null
  bugfixScoreBreakdown?: BugfixScoreBreakdown | null
  bugfixSemanticScores?: Record<string, unknown> | null
  bugfixRootCause?: unknown
  bugfixPrevention?: unknown
  bugfixRootCauseRubric?: string[]
  silentNotes: unknown[]
  code: string
  language: string
  efficiencyMetrics?: Record<string, unknown>
  testsPassed: number
  testsTotal: number
}): string {
  const {
    scenarioTitle,
    scenarioType,
    passRate,
    finalScores,
    aiValidation,
    extractedEvidence,
    bugfixEvidenceSummary,
    bugfixScoreBreakdown,
    bugfixSemanticScores,
    bugfixRootCause,
    bugfixPrevention,
    bugfixRootCauseRubric,
    silentNotes,
    code,
    language,
    efficiencyMetrics,
    testsPassed,
    testsTotal,
  } = data

  const evidenceSummary = extractedEvidence
    ? buildEvidenceSummary(extractedEvidence as Parameters<typeof buildEvidenceSummary>[0])
    : ""
  const silentNotesContext = buildSilentNotesContext(
    silentNotes as Parameters<typeof buildSilentNotesContext>[0]
  )
  const bugfixEvidenceContext =
    scenarioType === "bugfix" && bugfixEvidenceSummary && bugfixScoreBreakdown
      ? buildBugfixEvidenceContext({
          summary: bugfixEvidenceSummary,
          score: bugfixScoreBreakdown,
          rootCause: typeof bugfixRootCause === "string" ? bugfixRootCause : "",
          prevention: typeof bugfixPrevention === "string" ? bugfixPrevention : "",
          rubric: bugfixRootCauseRubric || [],
          semanticRationale: (bugfixSemanticScores?.scoringRationale as string) || "",
        })
      : ""

  return `Generate specific, actionable interview feedback.

PROBLEM: ${scenarioTitle} (${scenarioType?.toUpperCase() || "DSA"})

TEST RESULTS: ${testsPassed}/${testsTotal} passed (${Math.round(passRate)}%)

PRE-CALCULATED SCORES (use exactly):
${
  scenarioType === "system-design"
    ? `- Requirements: ${finalScores.understanding}/100
- Architecture: ${finalScores.problemSolving}/100
- Scalability: ${finalScores.codeQuality}/100
- Communication: ${finalScores.communication}/100`
    : scenarioType === "bugfix"
      ? `- Investigation: ${finalScores.understanding}/100
- Debugging Process: ${finalScores.problemSolving}/100
- Fix Quality: ${finalScores.codeQuality}/100
- Communication: ${finalScores.communication}/100`
      : `- Understanding: ${finalScores.understanding}/100
- Problem-Solving: ${finalScores.problemSolving}/100
- Code Quality: ${finalScores.codeQuality}/100
- Communication: ${finalScores.communication}/100`
}
- Overall: ${finalScores.overall}/100

COMMUNICATION:
- Approach explained: ${(aiValidation as Record<string, unknown>).approachExplained ? "YES" : "NO"}
- Complexity discussed: ${(aiValidation as Record<string, unknown>).complexityDiscussed ? "YES" : "NO"}

${evidenceSummary ? `EVIDENCE FROM CONVERSATION:\n${evidenceSummary}\n` : ""}
${bugfixEvidenceContext}
${silentNotesContext}

CODE (${language || "javascript"}):
\`\`\`
${code?.slice(0, 1500) || "[No code]"}
\`\`\`

${
  efficiencyMetrics
    ? `
COMPLEXITY:
- Time: ${(efficiencyMetrics as Record<string, unknown>).estimatedTimeComplexity || "N/A"}
- Space: ${(efficiencyMetrics as Record<string, unknown>).estimatedSpaceComplexity || "N/A"}
`
    : ""
}

CRITICAL: Be SPECIFIC. Reference actual code patterns, conversation quotes, or test failures.
Do NOT give generic advice. Make it clear you analyzed THIS session.`
}

function averageScores(values: number[]): number {
  return Math.round(values.reduce((sum, value) => sum + value, 0) / values.length)
}

function mapBugfixScoreToFeedbackScores(score: BugfixScoreBreakdown) {
  return {
    understanding: averageScores([
      score.reproductionDiscipline,
      score.codebaseNavigation,
      score.evidenceGathering,
      score.hypothesisQuality,
    ]),
    problemSolving: averageScores([
      score.rootCauseUnderstanding,
      score.regressionPrevention,
      score.hypothesisQuality,
    ]),
    codeQuality: averageScores([
      score.verificationDiscipline,
      score.minimalFixQuality,
      score.overEditControl,
    ]),
    communication: score.communication,
    overall: score.overall,
  }
}

function buildBugfixEvidenceContext(params: {
  summary: BugfixEvidenceSummary
  score: BugfixScoreBreakdown
  rootCause: string
  prevention: string
  rubric: string[]
  semanticRationale: string
}): string {
  const { summary, score, rootCause, prevention, rubric, semanticRationale } = params

  return `
BUGFIX SESSION EVIDENCE:
- Reproduced before editing: ${summary.reproducedBeforeEditing ? "YES" : "NO"}
- Files inspected: ${summary.inspectedFiles.join(", ") || "none recorded"}
- Tests/docs inspected: ${summary.inspectedTestOrDocs.join(", ") || "none recorded"}
- Edited files: ${summary.editedFiles.join(", ") || "none recorded"}
- Over-edited files: ${summary.overEditedFiles.join(", ") || "none"}
- Visible test runs: ${summary.visibleTestsRun}
- Final pass rate: ${Math.round(summary.finalPassRate)}%
- Hypotheses captured: ${summary.hypothesisCount}
- Root cause captured: ${rootCause.trim() || "not captured"}
- Prevention idea captured: ${prevention.trim() || "not captured"}
- AI partner uses: ${summary.aiPartnerUseCount}
- AI shortcut requests: ${summary.aiShortcutCount}

ROOT CAUSE RUBRIC (expected criteria):
${rubric.map((r, i) => `  ${i + 1}. ${r}`).join("\n")}

CANDIDATE ROOT CAUSE: "${rootCause}"
CANDIDATE PREVENTION: "${prevention}"

SEMANTIC SCORING RATIONALE: "${semanticRationale}"

BUGFIX SCORE BREAKDOWN:
- Reproduction Discipline: ${score.reproductionDiscipline}/100
- Codebase Navigation: ${score.codebaseNavigation}/100
- Evidence Gathering: ${score.evidenceGathering}/100
- Hypothesis Quality: ${score.hypothesisQuality}/100
- Minimal Fix Quality: ${score.minimalFixQuality}/100
- Verification Discipline: ${score.verificationDiscipline}/100
- Over-Edit Control: ${score.overEditControl}/100
- Root Cause Understanding: ${score.rootCauseUnderstanding}/100
- Regression Prevention: ${score.regressionPrevention}/100
- AI Collaboration Quality: ${score.aiCollaborationQuality}/100
`
}

