/**
 * Notification Preferences API
 *
 * GET /api/notifications/preferences - Get user notification preferences
 * PUT /api/notifications/preferences - Update user notification preferences
 */

import { NextRequest, NextResponse } from 'next/server'
import { verifyAuth } from '@/lib/auth-helpers'
import {
  getNotificationPreferencesServer,
  updateNotificationPreferencesServer,
} from '@/lib/notification-helpers-server'
import type { NotificationType } from '@/lib/rag/knowledge-base/notification-knowledge'
import type { NotificationChannel } from '@/lib/types/notifications'

/**
 * GET /api/notifications/preferences
 * Returns user's notification preferences
 */
export async function GET(request: NextRequest) {
  try {
    const authResult = await verifyAuth(request)
    if (!authResult.authenticated || !authResult.userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const preferences = await getNotificationPreferencesServer(authResult.userId)

    return NextResponse.json({ preferences })
  } catch (error: any) {
    console.error('Error fetching notification preferences:', error)
    return NextResponse.json(
      { error: 'Failed to fetch preferences' },
      { status: 500 }
    )
  }
}

/**
 * PUT /api/notifications/preferences
 *
 * Body options:
 *   1. Full update: { preferences: Partial<NotificationPreferences> }
 *
 *   2. FCM token update: { fcmToken: string }
 *
 *   3. Toggle type: { toggleType: NotificationType, enabled: boolean }
 *
 *   4. Update channels: {
 *        type: NotificationType,
 *        channels: NotificationChannel[]
 *      }
 *
 *   5. Update quiet hours: {
 *        quietHours: { enabled: boolean, start: number, end: number }
 *      }
 */
export async function PUT(request: NextRequest) {
  try {
    const authResult = await verifyAuth(request)
    if (!authResult.authenticated || !authResult.userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const userId = authResult.userId
    const body = await request.json()

    // Handle FCM token update
    if (body.fcmToken !== undefined) {
      await updateNotificationPreferencesServer(userId, { fcmToken: body.fcmToken })
      return NextResponse.json({ success: true, message: 'FCM token updated' })
    }

    // Handle type toggle
    if (body.toggleType !== undefined) {
      const prefs = await getNotificationPreferencesServer(userId)
      const typePreferences = {
        ...prefs.typePreferences,
        [body.toggleType as NotificationType]: {
          ...prefs.typePreferences[body.toggleType as NotificationType],
          enabled: body.enabled ?? true,
        },
      }
      await updateNotificationPreferencesServer(userId, { typePreferences })
      return NextResponse.json({ success: true, message: 'Type preference updated' })
    }

    // Handle channel update for specific type
    if (body.type && body.channels) {
      const prefs = await getNotificationPreferencesServer(userId)
      const typePreferences = {
        ...prefs.typePreferences,
        [body.type]: {
          ...prefs.typePreferences[body.type as NotificationType],
          channels: body.channels as NotificationChannel[],
        },
      }
      await updateNotificationPreferencesServer(userId, { typePreferences })
      return NextResponse.json({ success: true, message: 'Channel preferences updated' })
    }

    // Handle quiet hours update
    if (body.quietHours !== undefined) {
      await updateNotificationPreferencesServer(userId, {
        quietHours: body.quietHours,
      })
      return NextResponse.json({ success: true, message: 'Quiet hours updated' })
    }

    // Handle global enabled toggle
    if (body.enabled !== undefined) {
      await updateNotificationPreferencesServer(userId, {
        enabled: body.enabled,
      })
      return NextResponse.json({ success: true, message: 'Notifications toggled' })
    }

    // Handle global channel toggles
    if (body.channels !== undefined) {
      await updateNotificationPreferencesServer(userId, {
        channels: body.channels,
      })
      return NextResponse.json({ success: true, message: 'Channels updated' })
    }

    // Handle timezone update
    if (body.timezone !== undefined) {
      await updateNotificationPreferencesServer(userId, {
        timezone: body.timezone,
      })
      return NextResponse.json({ success: true, message: 'Timezone updated' })
    }

    // Handle full preferences update
    if (body.preferences) {
      const updated = await updateNotificationPreferencesServer(userId, body.preferences)
      return NextResponse.json({ success: true, preferences: updated })
    }

    return NextResponse.json(
      { error: 'No valid update field provided' },
      { status: 400 }
    )
  } catch (error: any) {
    console.error('Error updating notification preferences:', error)
    return NextResponse.json(
      { error: 'Failed to update preferences' },
      { status: 500 }
    )
  }
}

/**
 * Notifications API
 *
 * GET /api/notifications - Get in-app notifications for notification center
 * POST /api/notifications - Trigger notification evaluation for user
 */

import { NextRequest, NextResponse } from 'next/server'
import { verifyAuth } from '@/lib/auth-helpers'
import {
  getInAppNotificationsServer,
  getUnreadInAppNotificationsServer,
  markInAppNotificationReadServer,
  markAllInAppNotificationsReadServer,
  getNotificationAnalyticsServer,
} from '@/lib/notification-helpers-server'
import {
  processUserNotifications,
  sendNotification,
} from '@/lib/services/notification-service'
import type { NotificationType } from '@/lib/rag/knowledge-base/notification-knowledge'
import type { NotificationTriggerContext } from '@/lib/types/notifications'

/**
 * GET /api/notifications
 * Query params:
 *   - unread=true: Get only unread notifications
 *   - limit=20: Number of notifications to return
 */
export async function GET(request: NextRequest) {
  try {
    const authResult = await verifyAuth(request)
    if (!authResult.authenticated || !authResult.userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const userId = authResult.userId
    const { searchParams } = new URL(request.url)
    const unreadOnly = searchParams.get('unread') === 'true'
    const limitParam = parseInt(searchParams.get('limit') || '20', 10)

    const notifications = unreadOnly
      ? await getUnreadInAppNotificationsServer(userId, limitParam)
      : await getInAppNotificationsServer(userId, limitParam)

    // Get unread count
    const unreadCount = unreadOnly
      ? notifications.length
      : (await getUnreadInAppNotificationsServer(userId, 100)).length

    // Get analytics summary
    const analytics = await getNotificationAnalyticsServer(userId)

    return NextResponse.json({
      notifications,
      unreadCount,
      analytics: {
        openRate: analytics.openRate,
        totalSent: analytics.totalSent,
      },
    })
  } catch (error: any) {
    console.error('Error fetching notifications:', error)
    return NextResponse.json(
      { error: 'Failed to fetch notifications' },
      { status: 500 }
    )
  }
}

/**
 * POST /api/notifications
 * Body options:
 *   1. { action: 'evaluate', context: NotificationTriggerContext }
 *      - Evaluate triggers and send applicable notifications
 *
 *   2. { action: 'send', type: NotificationType, variables: Record<string, any> }
 *      - Send a specific notification
 *
 *   3. { action: 'read', notificationId: string }
 *      - Mark a notification as read
 *
 *   4. { action: 'readAll' }
 *      - Mark all notifications as read
 */
export async function POST(request: NextRequest) {
  try {
    const authResult = await verifyAuth(request)
    if (!authResult.authenticated || !authResult.userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const userId = authResult.userId
    const body = await request.json()

    switch (body.action) {
      case 'evaluate': {
        const context: NotificationTriggerContext = {
          userId,
          ...body.context,
        }

        const result = await processUserNotifications(userId, context)

        return NextResponse.json({
          success: true,
          processed: result.processed,
          sent: result.sent,
          errors: result.errors,
        })
      }

      case 'send': {
        if (!body.type) {
          return NextResponse.json(
            { error: 'Notification type required' },
            { status: 400 }
          )
        }

        const result = await sendNotification(
          userId,
          body.type as NotificationType,
          body.variables || {},
          body.priority || 'medium'
        )

        return NextResponse.json(result)
      }

      case 'read': {
        if (!body.notificationId) {
          return NextResponse.json(
            { error: 'Notification ID required' },
            { status: 400 }
          )
        }

        // Verify user owns the notification before marking as read
        const marked = await markInAppNotificationReadServer(body.notificationId, userId)
        if (!marked) {
          return NextResponse.json(
            { error: 'Notification not found or access denied' },
            { status: 404 }
          )
        }

        return NextResponse.json({ success: true })
      }

      case 'readAll': {
        await markAllInAppNotificationsReadServer(userId)

        return NextResponse.json({ success: true })
      }

      default:
        return NextResponse.json(
          { error: 'Invalid action. Use: evaluate, send, read, or readAll' },
          { status: 400 }
        )
    }
  } catch (error: any) {
    console.error('Error processing notification action:', error)
    return NextResponse.json(
      { error: 'Failed to process notification action' },
      { status: 500 }
    )
  }
}

