            if (scenario.type === "bugfix") {
              resetBugfixSessionState()
              setBugfixEvidenceEvents([
                createBugfixEvidenceEvent({ type: "session_started", timestamp: Date.now() }),
                createBugfixEvidenceEvent({ type: "incident_read", timestamp: Date.now() + 1 }),
