            : { skill_level: experienceLevel },
          workspaceContext: chatWorkspaceContext,
          currentCode: code,
          scenarioTitle: selectedScenario?.title,
          scenarioType: selectedScenario?.type,
          scenarioCompany: targetCompany,
          isProactive: false,
