                      ? "grid-cols-1" // Focus mode: editor only
                      : "grid-cols-1 lg:grid-cols-[260px_minmax(0,1fr)_240px] xl:grid-cols-[280px_minmax(0,1fr)_260px] 2xl:grid-cols-[320px_minmax(0,1fr)_280px]"
