                  <ProblemColumn
                    ctx={{
                      activePanel,
                      bugfixReflection: {
                        hypothesis: bugfixHypothesis,
                        rootCause: bugfixRootCause,
                        prevention: bugfixPrevention,
                      },
                      elapsedTime,
                      fetchRAGHints,
                      fileInputRef,
                      focusMode,
                      handleFileUpload,
                      hintAgent,
                      hintFeedback,
                      hintFetchStatus,
                      isInterviewStarted,
                      ragHints,
                      realInterviewMode,
                      revealedAIHintIndices,
                      revealedHintIndices,
                      revealedHints,
                      selectedScenario,
                      setIsCodeViewerOpen,
                      onBugfixReflectionChange: handleBugfixReflectionChange,
                      onBugfixReflectionCommit: handleBugfixReflectionCommit,
                      setRevealedAIHintIndices,
                      setRevealedHintIndices,
                      setSelectedFile,
                      setShowOptimalApproach,
                      showOptimalApproach,
