                </div>
                <div>
                  {metrics.recentSessions.length === 0 ? (
                    <p className="p-6 text-sm text-zinc-600">No sessions yet</p>
                  ) : (
                    <div className="divide-y divide-zinc-800/50">
                      {metrics.recentSessions.slice(0, 5).map((session) => (
                        <Link
                          key={session.id}
                          href={`/sessions/${session.id}`}
                          className="group flex items-center justify-between p-4 transition-colors hover:bg-zinc-800/30"
                        >
                          <div className="flex items-center gap-4">
                            <div
                              className={`flex h-10 w-10 items-center justify-center rounded-lg font-mono text-sm ${session.performanceScore >= 80 ? "bg-emerald-500/10 text-emerald-400" : ""} ${session.performanceScore >= 60 && session.performanceScore < 80 ? "bg-amber-500/10 text-amber-400" : ""} ${session.performanceScore < 60 ? "bg-red-500/10 text-red-400" : ""} `}
                            >
                              {session.performanceScore}
                            </div>
                            <div>
                              <div className="flex items-center gap-2">
                                <span className="text-sm text-white capitalize">
                                  {(session.pattern || "unknown").replace(/-/g, " ")}
                                </span>
                                <span
                                  className={`rounded px-1.5 py-0.5 text-[10px] tracking-wider uppercase ${session.difficulty === "easy" ? "text-emerald-500" : ""} ${session.difficulty === "medium" ? "text-amber-500" : ""} ${session.difficulty === "hard" ? "text-red-500" : ""} `}
                                >
                                  {session.difficulty}
                                </span>
                              </div>
                              <div className="mt-0.5 flex items-center gap-3 text-xs text-zinc-500">
                                <span>{session.durationMinutes} min</span>
                                <span>
                                  {new Date(session.completedAt).toLocaleDateString("en-US", {
                                    month: "short",
                                    day: "numeric",
                                  })}
                                </span>
                              </div>
                            </div>
                          </div>
                          <ChevronRight className="h-4 w-4 text-zinc-600 transition-colors group-hover:text-zinc-400" />
                        </Link>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              {/* CTA - Minimal */}
              <div className="flex items-center justify-between rounded-2xl border border-zinc-800/50 bg-zinc-900/30 p-6">
                <div>
                  <h3 className="mb-1 font-medium text-white">Ready for more practice?</h3>
                  <p className="text-sm text-zinc-500">
                    Keep building your skills with targeted sessions.
                  </p>
                </div>
                <Link href="/interview">
                  <Button
                    variant="outline"
                    className="border-zinc-700 text-white hover:bg-zinc-800"
                  >
                    Practice now
                    <ArrowRight className="ml-2 h-4 w-4" />
                  </Button>
                </Link>
              </div>
            </>
          )}
        </div>
      </div>

      <Footer />
    </main>
  )
}

"use client"

import { useState, useEffect, useCallback } from "react"
import { useRouter } from "next/navigation"
import dynamic from "next/dynamic"
import { useAuth } from "@/lib/auth-context"
import { Header } from "@/components/header"
import { Footer } from "@/components/footer"
import { type DueItem } from "@/components/practice"
import { Button } from "@/components/ui/button"
import { Tooltip, TooltipTrigger, TooltipContent } from "@/components/ui/tooltip"
import { Loader2, Lock, ArrowRight, HelpCircle, List, CalendarDays } from "lucide-react"
import Link from "next/link"

// Dynamic imports for heavy components - reduces initial bundle size
const StreakBanner = dynamic(
  () => import("@/components/practice").then((mod) => mod.StreakBanner),
  { ssr: false, loading: () => <div className="h-16 animate-pulse rounded-lg bg-white/5" /> }
)

const DueForReview = dynamic(
  () => import("@/components/practice").then((mod) => mod.DueForReview),
  { ssr: false, loading: () => <div className="h-64 animate-pulse rounded-lg bg-white/5" /> }
)

const PatternMastery = dynamic(
  () => import("@/components/practice").then((mod) => mod.PatternMastery),
  { ssr: false, loading: () => <div className="h-48 animate-pulse rounded-lg bg-white/5" /> }
)

const ReviewCalendar = dynamic(
  () => import("@/components/practice").then((mod) => mod.ReviewCalendar),
  { ssr: false, loading: () => <div className="h-96 animate-pulse rounded-lg bg-white/5" /> }
)

interface StatsData {
  overall: {
    total_problems_seen: number
    problems_mastered: number
    problems_reviewing: number
    problems_learning: number
    problems_new: number
    mastery_percentage: number
    streak_days: number
    longest_streak_days: number
    total_reviews: number
    average_score: number
    total_time_minutes: number
  }
  by_pattern: {
    pattern: string
    total: number
    mastered: number
    reviewing?: number
    learning?: number
    new_count?: number
    average_score: number
    mastery_percentage: number
    weakest_problem_id?: string
    weakest_problem_title?: string
  }[]
  by_difficulty: {
    difficulty: "easy" | "medium" | "hard"
    total: number
    mastered: number
    average_score: number
  }[]
  daily_goal: number
  daily_progress: number
  problems_today: string[]
}

interface DueData {
  due_now: DueItem[]
  due_in_minutes: DueItem[] // FSRS learning steps
  due_today: DueItem[]
  upcoming: DueItem[]
  user_algorithm?: "sm2" | "fsrs"
  stats: {
    total_due: number
    overdue_count: number
    learning_steps_due?: number
    streak_at_risk: boolean
  }
  settings?: {
    max_daily_reviews: number
    is_overwhelmed: boolean
    defer_count: number
  }
}

export default function PracticePage() {
  const router = useRouter()
  const { user, loading: authLoading, initialized } = useAuth()
  const [stats, setStats] = useState<StatsData | null>(null)
  const [due, setDue] = useState<DueData | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [isPro, setIsPro] = useState<boolean | null>(null)
  const [isDeferring, setIsDeferring] = useState(false)
  const [viewMode, setViewMode] = useState<"list" | "calendar">("list")

  const getAuthToken = useCallback(async () => {
    const { auth } = await import("@/lib/firebase")
    const currentUser = auth.currentUser
    if (!currentUser) return null
    return currentUser.getIdToken()
  }, [])

  const fetchData = useCallback(async () => {
    try {
      const token = await getAuthToken()
      if (!token) return

      const headers = {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      }

      const [statsRes, dueRes] = await Promise.all([
        fetch("/api/spaced-repetition/stats", { headers }),
        fetch("/api/spaced-repetition/due", { headers }),
      ])

      if (!statsRes.ok || !dueRes.ok) {
        throw new Error("Failed to fetch data")
      }

      const [statsData, dueData] = await Promise.all([statsRes.json(), dueRes.json()])

      setStats(statsData)
      setDue(dueData)
    } catch (err) {
      // Error logged via monitoring; user sees friendly message
      setError("Failed to load practice data. Please try refreshing the page.")
    } finally {
      setIsLoading(false)
    }
  }, [getAuthToken])

  const handleSkipProblem = async (problemId: string) => {
    try {
      const token = await getAuthToken()
      if (!token) return

      const res = await fetch("/api/spaced-repetition/skip", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ problem_id: problemId }),
      })

      if (res.ok) {
        const dueRes = await fetch("/api/spaced-repetition/due", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        })
        if (dueRes.ok) {
          const dueData = await dueRes.json()
          setDue(dueData)
        }
      }
    } catch (err) {
      // Skip error is non-critical
    }
  }

  const handleMarkReviewed = async (problemId: string, scenarioId: string) => {
    try {
      const token = await getAuthToken()
      if (!token) return

      const res = await fetch("/api/spaced-repetition/mark-reviewed", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ problem_id: problemId, scenario_id: scenarioId }),
      })

      if (res.ok) {
        // Refresh both due items and stats
        const [dueRes, statsRes] = await Promise.all([
          fetch("/api/spaced-repetition/due", {
            headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
          }),
          fetch("/api/spaced-repetition/stats", {
            headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
          }),
        ])

        if (dueRes.ok) {
          const dueData = await dueRes.json()
          setDue(dueData)
        }
        if (statsRes.ok) {
          const statsData = await statsRes.json()
          setStats(statsData)
        }
      }
    } catch (err) {
      // Review error is non-critical
    }
  }

  const handleBatchDefer = async () => {
    try {
      setIsDeferring(true)
      const token = await getAuthToken()
      if (!token) return

      const res = await fetch("/api/spaced-repetition/batch-defer", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({}), // Use user's default max_daily_reviews
      })

      if (res.ok) {
        // Refresh due items to show updated queue
        const dueRes = await fetch("/api/spaced-repetition/due", {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        })
        if (dueRes.ok) {
          const dueData = await dueRes.json()
          setDue(dueData)
        }
      }
    } catch (err) {
      // Defer error is non-critical
    } finally {
      setIsDeferring(false)
    }
  }

  // Check subscription
  useEffect(() => {
    const checkSubscription = async () => {
      if (!user) return

      try {
        const { auth } = await import("@/lib/firebase")
        const currentUser = auth.currentUser
        if (!currentUser) return

        const token = await currentUser.getIdToken()

        const res = await fetch("/api/user/profile", {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        })

        if (res.ok) {
          const profile = await res.json()
          setIsPro(
            profile.subscription_tier === "pro" || profile.subscription_tier === "enterprise"
          )
        } else {
          setIsPro(false)
        }
      } catch {
        setIsPro(false)
      }
    }

    if (initialized && user) {
      checkSubscription()
    }
  }, [user, initialized])

  useEffect(() => {
    if (initialized && user && isPro) {
      fetchData()
    }
  }, [initialized, user, isPro, fetchData])

  useEffect(() => {
    if (initialized && !user && !authLoading) {
      router.push("/login?redirect=/practice")
    }
  }, [initialized, user, authLoading, router])

  if (!initialized || authLoading || isPro === null) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-black">
        <Loader2 className="h-6 w-6 animate-spin text-white" />
      </div>
    )
  }

  // Upgrade prompt for non-Pro users
  if (!isPro) {
    return (
      <div className="min-h-screen bg-black">
        <Header />
        <main className="container mx-auto px-4 pt-24 pb-16">
          <div className="mx-auto max-w-lg text-center">
            <div className="mx-auto mb-6 flex h-16 w-16 items-center justify-center rounded-full bg-gray-800">
              <Lock className="h-8 w-8 text-gray-500" />
            </div>
            <h1 className="mb-3 text-2xl font-bold text-white">Spaced Repetition Practice</h1>
            <p className="mb-8 text-gray-400">
              Smart practice sessions with spaced repetition to maximize your learning and
              retention.
            </p>
            <div className="mx-auto mb-8 max-w-sm space-y-3 text-left">
              {[
                "Optimized review intervals",
                "Pattern mastery tracking",
                "Personalized recommendations",
                "Daily goals and streaks",
              ].map((feature, i) => (
                <div key={i} className="flex items-center gap-3 text-gray-300">
                  <div className="h-1.5 w-1.5 rounded-full bg-white" />
                  <span>{feature}</span>
                </div>
              ))}
            </div>
            <Link href="/pricing">
              <Button className="bg-white text-black hover:bg-gray-200">
                Upgrade to Pro
                <ArrowRight className="ml-2 h-4 w-4" />
              </Button>
            </Link>
          </div>
        </main>
        <Footer />
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-black">
      <Header />
      <main className="container mx-auto px-4 pt-24 pb-16">
        <div className="mx-auto max-w-5xl">
          {/* Page Header */}
          <div className="mb-8">
            <h1 className="mb-1 text-2xl font-bold text-white">Practice</h1>
            <p className="text-gray-500">Review problems at optimal intervals</p>
          </div>

          {error && (
            <div className="mb-6 rounded-lg border border-rose-500/10 bg-rose-500/5 p-4 text-sm text-rose-400">
              {error}
            </div>
          )}

          {/* Streak Banner */}
          <div className="mb-8 border-b border-white/5 pb-6">
            <StreakBanner
              streakDays={stats?.overall.streak_days || 0}
              dailyGoal={stats?.daily_goal || 5}
              dailyProgress={stats?.daily_progress || 0}
              longestStreak={stats?.overall.longest_streak_days}
              isLoading={isLoading}
            />
          </div>

          {/* Main Content */}
          <div className="space-y-8">
            {/* View Toggle */}
            <div className="mb-4 flex items-center justify-end">
              <div className="inline-flex rounded-lg border border-white/10 bg-white/5 p-1">
                <button
                  onClick={() => setViewMode("list")}
                  className={`flex items-center gap-2 rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
                    viewMode === "list"
                      ? "bg-white/10 text-white"
                      : "text-gray-500 hover:text-gray-300"
                  }`}
                >
                  <List className="h-4 w-4" />
                  List
                </button>
                <button
                  onClick={() => setViewMode("calendar")}
                  className={`flex items-center gap-2 rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
                    viewMode === "calendar"
                      ? "bg-white/10 text-white"
                      : "text-gray-500 hover:text-gray-300"
                  }`}
                >
                  <CalendarDays className="h-4 w-4" />
                  Calendar
                </button>
              </div>
            </div>

            {/* Due for Review - List View */}
            {viewMode === "list" && (
              <div className="rounded-xl border border-white/5 bg-gray-900/30 p-6">
                <DueForReview
                  dueNow={due?.due_now || []}
                  dueInMinutes={due?.due_in_minutes || []}
                  dueToday={due?.due_today || []}
                  upcoming={due?.upcoming || []}
                  totalDue={due?.stats.total_due || 0}
                  overdueCount={due?.stats.overdue_count || 0}
                  userAlgorithm={due?.user_algorithm}
                  onSkip={handleSkipProblem}
                  onMarkReviewed={handleMarkReviewed}
                  isLoading={isLoading}
                  // Overwhelm management
                  maxDailyReviews={due?.settings?.max_daily_reviews}
                  isOverwhelmed={due?.settings?.is_overwhelmed}
                  deferCount={due?.settings?.defer_count}
                  onBatchDefer={handleBatchDefer}
                  isDeferring={isDeferring}
                />
              </div>
            )}

            {/* Due for Review - Calendar View */}
            {viewMode === "calendar" && (
              <div className="rounded-xl border border-white/5 bg-gray-900/30 p-6">
                <ReviewCalendar
                  dueItems={[
                    ...(due?.due_now || []),
                    ...(due?.due_in_minutes || []),
                    ...(due?.due_today || []),
                  ]}
                  upcoming={due?.upcoming || []}
                />
              </div>
            )}

            {/* Pattern Mastery */}
            <div className="rounded-xl border border-white/5 bg-gray-900/30 p-6">
              <PatternMastery patterns={stats?.by_pattern || []} isLoading={isLoading} />
            </div>
          </div>

          {/* Stats Summary */}
          {stats && !isLoading && (
            <div className="mt-8 grid grid-cols-2 gap-4 md:grid-cols-4">
              <div className="py-4 text-center">
                <div className="text-2xl font-bold text-white">
                  {stats.overall.total_problems_seen}
                </div>
                <div className="text-sm text-gray-500">Problems</div>
              </div>
              <div className="py-4 text-center">
                <div className="text-2xl font-bold text-emerald-400">
                  {stats.overall.problems_mastered}
                </div>
                <div className="text-sm text-gray-500">Mastered</div>
              </div>
              <div className="py-4 text-center">
                <div className="text-2xl font-bold text-white">{stats.overall.average_score}%</div>
                <div className="flex items-center justify-center gap-1 text-sm text-gray-500">
                  Review Avg
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <HelpCircle className="h-3 w-3 cursor-help text-gray-600" />
                    </TooltipTrigger>
                    <TooltipContent className="max-w-xs bg-zinc-800 text-zinc-200">
                      <p>
                        Review Average: Your average score across spaced repetition reviews. This
                        tracks how well you perform when revisiting problems over time.
                      </p>
                    </TooltipContent>
                  </Tooltip>
                </div>
              </div>
              <div className="py-4 text-center">
                <div className="text-2xl font-bold text-white">
                  {Math.round(stats.overall.total_time_minutes / 60)}h
                </div>
                <div className="text-sm text-gray-500">Practice Time</div>
              </div>
            </div>
          )}
        </div>
      </main>
      <Footer />
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { motion, AnimatePresence } from 'framer-motion'
import { ChevronLeft, Loader2, AlertCircle, RefreshCw, Crown, ArrowRight } from 'lucide-react'
import Link from 'next/link'

import { Header } from '@/components/header'
import { CompanySelector, InterviewDatePicker, SkillAssessment, AssessmentResult } from '@/components/roadmap'
import { useRoadmapStore } from '@/lib/stores/roadmap-store'
import { getCompanyById } from '@/lib/data/company-questions'
import { generatePersonalizedRoadmap } from '@/lib/roadmap/prioritization-algorithm'
import { UserRoadmapAssessment } from '@/lib/data/company-questions/types'
import { scenarios } from '@/lib/scenarios'
import { useAuth } from '@/lib/auth-context'

type Step = 'company' | 'date' | 'assessment' | 'generating'

export default function NewRoadmapPage() {
  const router = useRouter()
  const [step, setStep] = useState<Step>('company')
  const [isGenerating, setIsGenerating] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const { user, firebaseUser } = useAuth()

  const {
    selectedCompany,
    selectedDate,
    selectCompany,
    selectDate,
    setActiveRoadmap,
    resetWizard,
  } = useRoadmapStore()

  // Reset wizard on mount
  useEffect(() => {
    resetWizard()
  }, [resetWizard])

  const handleCompanySelect = (companyId: string) => {
    selectCompany(companyId as any)
    setStep('date')
  }

  const handleDateSelect = (date: Date) => {
    selectDate(date)
    setStep('assessment')
  }

  const handleAssessmentComplete = async (result: AssessmentResult) => {
    if (!selectedCompany || !selectedDate) return

    if (!user?.id || !firebaseUser) {
      setError('You must be logged in to create a roadmap')
      setStep('assessment')
      return
    }

    setStep('generating')
    setIsGenerating(true)
    setError(null)

    try {
      // Get Firebase ID token for authentication
      const idToken = await firebaseUser.getIdToken()

      // Calculate days remaining
      const now = new Date()
      const daysRemaining = Math.max(1, Math.ceil((selectedDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24)))

      // Build assessment object
      const assessment: UserRoadmapAssessment = {
        targetCompany: selectedCompany,
        interviewDate: selectedDate,
        daysRemaining,
        experienceLevel: result.experienceLevel,
        problemsSolvedEstimate: result.problemsSolved,
        patternFamiliarity: result.patternFamiliarity,
        hoursPerDay: result.hoursPerDay,
        preferredDifficulty: 'mixed',
        targetScore: 80,
      }

      // Call API endpoint to create and save roadmap to Firebase
      const response = await fetch('/api/roadmap', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${idToken}`,
        },
        body: JSON.stringify({
          targetCompany: selectedCompany,
          interviewDate: selectedDate.toISOString(),
          experienceLevel: result.experienceLevel,
          problemsSolved: result.problemsSolved,
          hoursPerDay: result.hoursPerDay,
          patternFamiliarity: result.patternFamiliarity,
        }),
      })

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({ error: 'Failed to create roadmap' }))
        // Handle Pro-only feature restriction - stay on generating step and show upgrade prompt
        if (errorData.code === 'PRO_REQUIRED') {
          // Brief delay so user sees the generation started
          await new Promise(resolve => setTimeout(resolve, 1500))
          setError('PRO_REQUIRED')
          setIsGenerating(false)
          // Stay on generating step - don't go back to assessment
          return
        }
        throw new Error(errorData.error || 'Failed to create roadmap')
      }

      const data = await response.json()
      const roadmap = data.roadmap

      if (!roadmap) {
        throw new Error('Failed to generate roadmap')
      }

      // Set active roadmap in store
      setActiveRoadmap(roadmap)

      // Navigate to roadmap view
      router.push('/roadmap')
    } catch (err) {
      console.error('Error generating roadmap:', err)
      setError(err instanceof Error ? err.message : 'Failed to generate roadmap')
      setStep('assessment')
    } finally {
      setIsGenerating(false)
    }
  }

  const handleBack = () => {
    if (step === 'date') {
      setStep('company')
    } else if (step === 'assessment') {
      setStep('date')
    }
  }

  const companyData = selectedCompany ? getCompanyById(selectedCompany) : null

  // Check for rate limit error
  const isRateLimited = error?.toLowerCase().includes('rate') || error?.toLowerCase().includes('limit') || error?.toLowerCase().includes('too many')
  const isProRequired = error === 'PRO_REQUIRED'

  return (
    <div className="min-h-screen bg-background">
      <Header />

      {/* Progress steps */}
      <div className="container mx-auto px-4 py-6 pt-24">
        <div className="flex items-center justify-center gap-2 mb-8">
          <StepIndicator label="Company" active={step === 'company'} completed={!!selectedCompany} />
          <StepConnector completed={!!selectedCompany} />
          <StepIndicator label="Date" active={step === 'date'} completed={!!selectedDate} />
          <StepConnector completed={!!selectedDate} />
          <StepIndicator label="Assessment" active={step === 'assessment'} completed={step === 'generating'} />
          <StepConnector completed={step === 'generating'} />
          <StepIndicator label="Generate" active={step === 'generating'} completed={false} />
        </div>

        {/* Pro Upgrade Prompt - only show when NOT on generating step (generating step has its own UI) */}
        {isProRequired && step !== 'generating' && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            className="max-w-2xl mx-auto mb-6 p-6 rounded-xl border bg-gradient-to-r from-yellow-500/10 to-orange-500/10 border-yellow-500/30"
          >
            <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4">
              <div className="w-12 h-12 rounded-full bg-yellow-500 flex items-center justify-center shrink-0">
                <Crown className="h-6 w-6 text-black" />
              </div>
              <div className="flex-1">
                <h3 className="font-bold text-foreground text-lg mb-1">Upgrade to Pro for Personalized Roadmaps</h3>
                <p className="text-sm text-muted-foreground mb-3">
                  Get AI-powered study plans tailored to your target company, interview date, and skill level.
                  Pro includes spaced repetition, pattern mastery tracking, and more.
                </p>
