export function InteractiveTour({ isOpen, userId, userName, onComplete, onSkip }: InteractiveTourProps) {
  const router = useRouter()
  const [currentStep, setCurrentStep] = useState(0)

  const step = tourSteps[currentStep]
  const isLastStep = currentStep === tourSteps.length - 1
  const isFirstStep = currentStep === 0
  const Icon = step.icon

  // Handle keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isOpen) return
      if (e.key === "ArrowRight" || e.key === "Enter") handleNext()
      if (e.key === "ArrowLeft") handlePrev()
      if (e.key === "Escape") handleSkip()
    }

    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [isOpen, currentStep])

  const handleNext = () => {
    if (isLastStep) {
      handleComplete()
    } else {
      setCurrentStep(prev => prev + 1)
    }
  }

  const handlePrev = () => {
    if (!isFirstStep) {
      setCurrentStep(prev => prev - 1)
    }
  }

  const handleComplete = async () => {
    try {
      const profileRef = doc(db, "profiles", userId)
      await setDoc(profileRef, {
        tour_completed: true,
        tour_completed_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      }, { merge: true })
    } catch (error) {
      console.error("Failed to save tour completion:", error)
    }
    onComplete()
  }

  const handleSkip = async () => {
    try {
      const profileRef = doc(db, "profiles", userId)
      await setDoc(profileRef, {
        tour_completed: true,
        tour_skipped: true,
        tour_completed_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      }, { merge: true })
    } catch (error) {
      console.error("Failed to save tour skip:", error)
    }
    onSkip()
  }

  if (!isOpen) return null

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-md"
      >
        {/* Skip button */}
        <button
          onClick={handleSkip}
          className="absolute top-6 right-6 text-gray-400 hover:text-white transition-colors flex items-center gap-2 text-sm"
        >
          Skip tour
          <X className="h-4 w-4" />
        </button>

        <div className="w-full max-w-xl mx-4">
          {/* Progress bar */}
          <div className="flex gap-1.5 mb-6 justify-center">
            {tourSteps.map((_, idx) => (
              <button
                key={idx}
                onClick={() => setCurrentStep(idx)}
                className={`h-1.5 rounded-full transition-all duration-300 ${
                  idx === currentStep
                    ? "w-8 bg-[#00d9ff]"
                    : idx < currentStep
                    ? "w-3 bg-[#00d9ff]/50 hover:bg-[#00d9ff]/70"
                    : "w-3 bg-gray-700 hover:bg-gray-600"
                }`}
              />
            ))}
          </div>

          {/* Content */}
          <motion.div
            key={step.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ duration: 0.3 }}
            className="bg-gray-900 border border-gray-800 rounded-2xl overflow-hidden shadow-2xl"
          >
            {/* Icon header */}
            <div className={`p-6 bg-gradient-to-br ${step.color} relative overflow-hidden`}>
              <div className="absolute inset-0 opacity-20">
                <div className="absolute top-2 left-2 w-24 h-24 rounded-full bg-white/20 blur-3xl" />
                <div className="absolute bottom-2 right-2 w-20 h-20 rounded-full bg-black/20 blur-2xl" />
              </div>

              <div className="relative flex flex-col items-center text-center">
                <div className="p-3 bg-white/20 rounded-xl backdrop-blur-sm mb-3">
                  <Icon className="h-8 w-8 text-white" />
                </div>
                <h2 className="text-xl font-heading font-bold text-white mb-1">
                  {step.id === "welcome" && userName
                    ? `Hey ${userName}, welcome to CodeSparring!`
                    : step.title}
                </h2>
                <p className="text-white/90 text-sm max-w-md">
                  {step.description}
                </p>
              </div>
            </div>

            {/* Visual or details */}
            <div className="p-5">
              {/* Visualization based on step */}
              {step.visual === "forgetting-curve" && <ForgettingCurveVisual />}
              {step.visual === "roadmap" && <RoadmapVisual />}
              {step.visual === "interview" && <InterviewVisual />}
              {step.visual === "review" && <ReviewVisual />}

              {/* Details list */}
              {step.details && !step.visual && (
                <div className="space-y-2">
                  {step.details.map((detail, idx) => (
                    <motion.div
                      key={idx}
                      initial={{ opacity: 0, x: -10 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: idx * 0.1 }}
                      className="flex items-start gap-3 p-3 bg-gray-800/50 rounded-lg"
                    >
                      <div className="p-1 rounded-full bg-[#00d9ff]/20 mt-0.5">
                        <Zap className="h-3 w-3 text-[#00d9ff]" />
                      </div>
                      <span className="text-gray-300 text-sm">{detail}</span>
                    </motion.div>
                  ))}
                </div>
              )}

              {/* Details under visual */}
              {step.details && step.visual && (
                <div className="mt-4 space-y-2">
                  {step.details.map((detail, idx) => (
                    <motion.div
                      key={idx}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      transition={{ delay: 0.5 + idx * 0.1 }}
                      className="flex items-center gap-2 text-sm text-gray-400"
                    >
                      <div className="w-1 h-1 rounded-full bg-[#00d9ff]" />
                      {detail}
                    </motion.div>
                  ))}
                </div>
              )}
            </div>

            {/* Navigation */}
            <div className="px-5 py-4 border-t border-gray-800 flex items-center justify-between">
              <Button
                variant="ghost"
                size="sm"
                onClick={handlePrev}
                disabled={isFirstStep}
                className={`text-gray-400 hover:text-white ${isFirstStep ? "invisible" : ""}`}
              >
                <ArrowLeft className="mr-1 h-4 w-4" />
                Back
              </Button>

              <span className="text-xs text-gray-500">
                {currentStep + 1} / {tourSteps.length}
              </span>

              <Button
                size="sm"
                onClick={handleNext}
                className="bg-[#00d9ff] hover:bg-[#00d9ff]/80 text-black font-medium"
              >
                {isLastStep ? "Start Practicing" : "Next"}
                <ArrowRight className="ml-1 h-4 w-4" />
              </Button>
            </div>
          </motion.div>

          {/* Keyboard hint */}
          <p className="text-center text-gray-600 text-xs mt-4">
            Press <kbd className="px-1.5 py-0.5 bg-gray-800 rounded text-gray-400">→</kbd> or{" "}
            <kbd className="px-1.5 py-0.5 bg-gray-800 rounded text-gray-400">Enter</kbd> to continue
          </p>
        </div>
      </motion.div>
    </AnimatePresence>
  )
}

"use client"

import { useState, useEffect } from "react"
import { useAuth } from "@/lib/auth-context"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import {
  BookOpen,
  Target,
  TrendingUp,
  TrendingDown,
  Minus,
  Lightbulb,
  ChevronRight,
  Sparkles,
} from "lucide-react"

interface LearningStep {
  step: number
  focus: string
  recommendation: string
  estimatedProblems: number
  currentScore?: number
}

interface UserProfile {
  totalSessions: number
  averageScore: number
  recentTrend: "improving" | "stable" | "declining"
}

interface LearningRecommendationsProps {
  userId: string
  currentProblemType?: string
  currentDifficulty?: string
  performanceScore?: number
  onSelectProblem?: (problemType: string, difficulty: string) => void
}

export function LearningRecommendations({
  userId,
  currentProblemType,
  currentDifficulty,
  performanceScore,
  onSelectProblem,
}: LearningRecommendationsProps) {
  const { firebaseUser } = useAuth()
  const [learningPath, setLearningPath] = useState<LearningStep[]>([])
  const [profile, setProfile] = useState<UserProfile | null>(null)
  const [message, setMessage] = useState<string>("")
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    async function fetchRecommendations() {
      if (!userId || !firebaseUser) return

      setLoading(true)
      setError(null)

      try {
        const token = await firebaseUser.getIdToken()
        const response = await fetch("/api/rag", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            action: "get-learning-path",
            userId,
            targetSkills: currentProblemType ? [currentProblemType] : [],
          }),
        })

        if (!response.ok) {
          const data = await response.json().catch(() => null)
          throw new Error(data?.error || "Failed to fetch recommendations")
        }

        const data = await response.json()
        setLearningPath(data.learningPath || [])
        setProfile(data.profile || null)
        setMessage(data.message || "")
      } catch (err) {
        console.error("Error fetching learning recommendations:", err)
        setError("Unable to load recommendations")
      } finally {
        setLoading(false)
      }
    }

    fetchRecommendations()
  }, [userId, currentProblemType, firebaseUser])

  const getTrendIcon = (trend?: string) => {
    switch (trend) {
      case "improving":
        return <TrendingUp className="h-4 w-4 text-green-500" />
      case "declining":
        return <TrendingDown className="h-4 w-4 text-red-500" />
      default:
        return <Minus className="h-4 w-4 text-gray-500" />
    }
  }

  const getTrendColor = (trend?: string) => {
    switch (trend) {
      case "improving":
        return "text-green-600 bg-green-50"
      case "declining":
        return "text-red-600 bg-red-50"
      default:
        return "text-gray-600 bg-gray-50"
    }
  }

  if (loading) {
    return (
      <Card className="w-full">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <BookOpen className="h-5 w-5" />
            Loading Recommendations...
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <Skeleton className="h-20 w-full" />
          <Skeleton className="h-20 w-full" />
          <Skeleton className="h-20 w-full" />
        </CardContent>
      </Card>
    )
  }

  if (error) {
    return (
      <Card className="w-full">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <BookOpen className="h-5 w-5" />
            Learning Path
          </CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-muted-foreground">{error}</p>
