export function ProductTour({ isOpen, userId, userName, onComplete, onSkip }: ProductTourProps) {
  const [currentStep, setCurrentStep] = useState(0)
  const [isAnimating, setIsAnimating] = useState(false)

  const step = tourSteps[currentStep]
  const isLastStep = currentStep === tourSteps.length - 1
  const isFirstStep = currentStep === 0

  const handleNext = () => {
    if (isAnimating) return
    setIsAnimating(true)

    if (isLastStep) {
      handleComplete()
    } else {
      setCurrentStep(prev => prev + 1)
    }

    setTimeout(() => setIsAnimating(false), 300)
  }

  const handlePrev = () => {
    if (isAnimating || isFirstStep) return
    setIsAnimating(true)
    setCurrentStep(prev => prev - 1)
    setTimeout(() => setIsAnimating(false), 300)
  }

  const handleComplete = async () => {
    try {
      const profileRef = doc(db, "profiles", userId)
      await setDoc(profileRef, {
        tour_completed: true,
        tour_completed_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      }, { merge: true })
    } catch {
      // Non-blocking - tour completion tracking is not critical
    }
    onComplete()
  }

  const handleSkip = async () => {
    try {
      const profileRef = doc(db, "profiles", userId)
      await setDoc(profileRef, {
        tour_completed: true,
        tour_skipped: true,
        tour_completed_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      }, { merge: true })
    } catch {
      // Non-blocking - tour skip tracking is not critical
    }
    onSkip()
  }

  if (!isOpen) return null

  const Icon = step.icon

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
