                              <span className="text-sm text-white">
                                {session.problemTitle || session.problemId}
                              </span>
                              <div className="mt-1 flex gap-2">
                                {session.pattern && (
                                  <span className="text-xs text-blue-400">{session.pattern}</span>
                                )}
