                              </span>
                            </div>
                            <p className="text-xs text-gray-400">{insight.description}</p>
                          </div>
                        ))}
                      </div>
                    </Section>
                  )}
                </>
              )}
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  )
}

