"use client"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { cn } from "@/lib/utils"

interface CohortData {
  cohort: string // e.g., "Jan 2025"
  size: number // Number of users in cohort
  retention: number[] // Retention percentages for each period (week/month)
}

interface CohortHeatmapProps {
  title: string
  subtitle?: string
  data: CohortData[]
  periodLabels?: string[] // e.g., ["Week 1", "Week 2", ...]
  loading?: boolean
  icon?: React.ComponentType<{ className?: string }>
}

export function CohortHeatmap({
  title,
  subtitle,
  data,
  periodLabels = ["W1", "W2", "W3", "W4", "W5", "W6", "W7", "W8"],
  loading = false,
  icon: Icon,
}: CohortHeatmapProps) {
  const getRetentionColor = (value: number): string => {
    // Color gradient from red (0%) to green (100%)
    if (value >= 80) return "bg-green-500"
    if (value >= 60) return "bg-green-600/80"
    if (value >= 40) return "bg-yellow-500/80"
    if (value >= 20) return "bg-orange-500/80"
    if (value > 0) return "bg-red-500/80"
    return "bg-gray-800"
  }

  const getTextColor = (value: number): string => {
    if (value >= 40) return "text-black"
    return "text-white"
  }

  if (loading) {
    return (
      <Card className="bg-gray-900/50 border-gray-800">
        <CardHeader>
          <CardTitle className="text-white flex items-center gap-2">
            {Icon && <Icon className="h-5 w-5 text-[#00d9ff]" />}
            {title}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="animate-pulse">
            <div className="h-64 bg-gray-800 rounded" />
          </div>
        </CardContent>
      </Card>
    )
  }

  if (!data || data.length === 0) {
    return (
      <Card className="bg-gray-900/50 border-gray-800">
        <CardHeader>
          <CardTitle className="text-white flex items-center gap-2">
            {Icon && <Icon className="h-5 w-5 text-[#00d9ff]" />}
            {title}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="h-[300px] flex items-center justify-center text-gray-500">
            No cohort data available
          </div>
        </CardContent>
      </Card>
    )
  }

  // Determine the max number of periods
  const maxPeriods = Math.max(...data.map((d) => d.retention.length))
  const displayPeriods = periodLabels.slice(0, maxPeriods)

  return (
    <Card className="bg-gray-900/50 border-gray-800">
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-white flex items-center gap-2">
            {Icon && <Icon className="h-5 w-5 text-[#00d9ff]" />}
            {title}
          </CardTitle>
          {subtitle && (
            <span className="text-sm text-gray-500">{subtitle}</span>
          )}
        </div>
      </CardHeader>
      <CardContent>
        <div className="overflow-x-auto">
          <table className="w-full min-w-max">
            <thead>
              <tr>
                <th className="text-left text-sm font-medium text-gray-400 pb-3 pr-4">
                  Cohort
                </th>
                <th className="text-center text-sm font-medium text-gray-400 pb-3 px-2">
                  Users
                </th>
                {displayPeriods.map((label, i) => (
                  <th
                    key={i}
                    className="text-center text-sm font-medium text-gray-400 pb-3 px-1"
                  >
                    {label}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {data.map((cohort, rowIndex) => (
                <tr key={cohort.cohort}>
                  <td className="text-sm text-white py-1 pr-4 whitespace-nowrap">
                    {cohort.cohort}
                  </td>
                  <td className="text-center text-sm text-gray-400 py-1 px-2">
                    {cohort.size.toLocaleString()}
                  </td>
                  {displayPeriods.map((_, colIndex) => {
                    const value = cohort.retention[colIndex]
                    const hasValue = value !== undefined && value !== null

                    return (
                      <td key={colIndex} className="p-1">
                        <div
                          className={cn(
                            "w-12 h-8 flex items-center justify-center rounded text-xs font-medium transition-colors",
                            hasValue ? getRetentionColor(value) : "bg-gray-800/50",
                            hasValue ? getTextColor(value) : "text-gray-600"
                          )}
                        >
                          {hasValue ? `${value.toFixed(0)}%` : "-"}
                        </div>
                      </td>
                    )
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Legend */}
        <div className="mt-4 pt-4 border-t border-gray-800">
          <div className="flex items-center justify-center gap-4 text-xs text-gray-400">
            <div className="flex items-center gap-1">
              <div className="w-4 h-4 rounded bg-red-500/80" />
              <span>0-20%</span>
            </div>
            <div className="flex items-center gap-1">
              <div className="w-4 h-4 rounded bg-orange-500/80" />
              <span>20-40%</span>
            </div>
            <div className="flex items-center gap-1">
              <div className="w-4 h-4 rounded bg-yellow-500/80" />
              <span>40-60%</span>
            </div>
            <div className="flex items-center gap-1">
              <div className="w-4 h-4 rounded bg-green-600/80" />
              <span>60-80%</span>
            </div>
            <div className="flex items-center gap-1">
              <div className="w-4 h-4 rounded bg-green-500" />
              <span>80-100%</span>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

export default CohortHeatmap

"use client"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { cn } from "@/lib/utils"
import {
  PieChart,
  Pie,
  Cell,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
} from "recharts"

interface DataItem {
  name: string
  value: number
  color?: string
}

interface DistributionChartProps {
  title: string
  subtitle?: string
  data: DataItem[]
  type?: "pie" | "bar" | "horizontal-bar"
  height?: number
  loading?: boolean
  icon?: React.ComponentType<{ className?: string }>
  showLegend?: boolean
  showValues?: boolean
  valueFormatter?: (value: number) => string
}

const DEFAULT_COLORS = [
  "#00d9ff", // cyan
  "#00ff88", // green
  "#FBBF24", // yellow
  "#F97316", // orange
  "#EF4444", // red
  "#A855F7", // purple
  "#EC4899", // pink
  "#6B7280", // gray
]

export function DistributionChart({
  title,
  subtitle,
  data,
  type = "pie",
  height = 300,
  loading = false,
  icon: Icon,
  showLegend = true,
  showValues = true,
  valueFormatter = (v) => v.toLocaleString(),
}: DistributionChartProps) {
  const CustomTooltip = ({ active, payload }: any) => {
    if (!active || !payload || !payload[0]) return null

    const item = payload[0].payload
    const total = data.reduce((sum, d) => sum + d.value, 0)
    const percentage = total > 0 ? ((item.value / total) * 100).toFixed(1) : 0

    return (
      <div className="bg-gray-900 border border-gray-700 rounded-lg p-3 shadow-xl">
        <div className="flex items-center gap-2">
          <div
            className="w-3 h-3 rounded-full"
            style={{ backgroundColor: item.color || DEFAULT_COLORS[0] }}
          />
          <span className="text-gray-300">{item.name}</span>
        </div>
        <div className="mt-1 text-white font-semibold">
          {valueFormatter(item.value)} ({percentage}%)
        </div>
      </div>
    )
  }

  if (loading) {
    return (
      <Card className="bg-gray-900/50 border-gray-800">
        <CardHeader>
          <CardTitle className="text-white flex items-center gap-2">
            {Icon && <Icon className="h-5 w-5 text-[#00d9ff]" />}
            {title}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="animate-pulse">
            <div className="h-[300px] bg-gray-800 rounded" />
          </div>
        </CardContent>
      </Card>
    )
  }

  if (!data || data.length === 0) {
    return (
      <Card className="bg-gray-900/50 border-gray-800">
        <CardHeader>
          <CardTitle className="text-white flex items-center gap-2">
            {Icon && <Icon className="h-5 w-5 text-[#00d9ff]" />}
            {title}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="h-[300px] flex items-center justify-center text-gray-500">
            No data available
          </div>
        </CardContent>
      </Card>
    )
  }

  // Add colors to data if not present
  const coloredData = data.map((item, index) => ({
    ...item,
    color: item.color || DEFAULT_COLORS[index % DEFAULT_COLORS.length],
  }))

  const total = data.reduce((sum, d) => sum + d.value, 0)

  const renderChart = () => {
    if (type === "pie") {
      return (
        <ResponsiveContainer width="100%" height={height}>
          <PieChart>
            <Pie
              data={coloredData}
              cx="50%"
              cy="50%"
              innerRadius={60}
              outerRadius={100}
              paddingAngle={2}
              dataKey="value"
              label={showValues ? ({ name, value }) => `${name}: ${valueFormatter(value)}` : undefined}
              labelLine={false}
            >
              {coloredData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} />
              ))}
            </Pie>
            <Tooltip content={<CustomTooltip />} />
            {showLegend && (
              <Legend
                wrapperStyle={{ paddingTop: 20 }}
                formatter={(value) => (
                  <span className="text-gray-400 text-sm">{value}</span>
                )}
              />
            )}
          </PieChart>
        </ResponsiveContainer>
      )
    }

    if (type === "horizontal-bar") {
      return (
        <ResponsiveContainer width="100%" height={height}>
          <BarChart
            data={coloredData}
            layout="vertical"
            margin={{ top: 0, right: 0, left: 0, bottom: 0 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke="#374151" horizontal={false} />
            <XAxis type="number" stroke="#6B7280" fontSize={12} />
            <YAxis
              type="category"
              dataKey="name"
              stroke="#6B7280"
              fontSize={12}
              width={100}
            />
            <Tooltip content={<CustomTooltip />} />
            <Bar dataKey="value" radius={[0, 4, 4, 0]}>
              {coloredData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      )
    }

    // Default vertical bar chart
    return (
      <ResponsiveContainer width="100%" height={height}>
        <BarChart data={coloredData} margin={{ top: 0, right: 0, left: 0, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#374151" vertical={false} />
          <XAxis dataKey="name" stroke="#6B7280" fontSize={12} />
          <YAxis stroke="#6B7280" fontSize={12} />
          <Tooltip content={<CustomTooltip />} />
          <Bar dataKey="value" radius={[4, 4, 0, 0]}>
            {coloredData.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={entry.color} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>
    )
  }

  return (
    <Card className="bg-gray-900/50 border-gray-800">
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-white flex items-center gap-2">
            {Icon && <Icon className="h-5 w-5 text-[#00d9ff]" />}
            {title}
          </CardTitle>
          {subtitle && (
            <span className="text-sm text-gray-500">{subtitle}</span>
          )}
        </div>
      </CardHeader>
      <CardContent>{renderChart()}</CardContent>
    </Card>
  )
}

export default DistributionChart

"use client"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { cn } from "@/lib/utils"
import { TrendingUp } from "lucide-react"

interface FunnelStage {
  name: string
  value: number
  color?: string
}

interface FunnelChartProps {
  title: string
  subtitle?: string
  stages: FunnelStage[]
  loading?: boolean
  icon?: React.ComponentType<{ className?: string }>
}

export function FunnelChart({
  title,
  subtitle,
  stages,
  loading = false,
  icon: Icon,
}: FunnelChartProps) {
  if (loading) {
    return (
      <Card className="bg-gray-900/50 border-gray-800">
        <CardHeader>
          <CardTitle className="text-white flex items-center gap-2">
            {Icon && <Icon className="h-5 w-5 text-[#00d9ff]" />}
            {title}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="animate-pulse space-y-4">
            {[1, 2, 3, 4, 5].map((i) => (
              <div key={i} className="h-12 bg-gray-800 rounded" style={{ width: `${100 - i * 15}%` }} />
            ))}
          </div>
        </CardContent>
      </Card>
    )
  }

  if (!stages || stages.length === 0) {
    return (
      <Card className="bg-gray-900/50 border-gray-800">
        <CardHeader>
          <CardTitle className="text-white flex items-center gap-2">
            {Icon && <Icon className="h-5 w-5 text-[#00d9ff]" />}
            {title}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="h-[300px] flex items-center justify-center text-gray-500">
            No data available
          </div>
        </CardContent>
      </Card>
    )
  }

  const maxValue = Math.max(...stages.map((s) => s.value))
  const defaultColors = [
    "#00d9ff", // cyan
    "#00ff88", // green
    "#FBBF24", // yellow
    "#F97316", // orange
    "#EF4444", // red
  ]

  return (
    <Card className="bg-gray-900/50 border-gray-800">
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-white flex items-center gap-2">
            {Icon && <Icon className="h-5 w-5 text-[#00d9ff]" />}
            {title}
          </CardTitle>
          {subtitle && (
            <span className="text-sm text-gray-500">{subtitle}</span>
          )}
        </div>
      </CardHeader>
      <CardContent>
        <div className="space-y-3">
          {stages.map((stage, index) => {
            const width = maxValue > 0 ? (stage.value / maxValue) * 100 : 0
            const color = stage.color || defaultColors[index % defaultColors.length]
            const conversionRate = index > 0 && stages[index - 1].value > 0
              ? ((stage.value / stages[index - 1].value) * 100).toFixed(1)
              : null

            return (
              <div key={stage.name} className="relative">
                {/* Stage bar */}
                <div className="relative">
                  <div
                    className="h-14 rounded-lg flex items-center transition-all duration-300"
                    style={{
                      width: `${Math.max(width, 20)}%`,
                      backgroundColor: `${color}20`,
                      borderLeft: `4px solid ${color}`,
                    }}
                  >
                    <div className="flex items-center justify-between w-full px-4">
                      <span className="font-medium text-white">{stage.name}</span>
                      <div className="flex items-center gap-3">
                        <span className="text-xl font-bold text-white">
                          {stage.value.toLocaleString()}
                        </span>
                        {conversionRate && (
                          <span className="text-sm text-gray-400">
                            ({conversionRate}%)
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                </div>

                {/* Conversion arrow */}
                {index < stages.length - 1 && (
                  <div className="flex items-center justify-center py-1">
                    <div className="text-gray-600">↓</div>
                    {stages[index + 1] && stages[index].value > 0 && (
                      <span className="text-xs text-gray-500 ml-2">
                        {((stages[index + 1].value / stage.value) * 100).toFixed(1)}% convert
                      </span>
                    )}
                  </div>
                )}
              </div>
            )
          })}
        </div>

        {/* Overall conversion */}
        {stages.length >= 2 && stages[0].value > 0 && (
          <div className="mt-6 pt-4 border-t border-gray-800">
            <div className="flex items-center justify-between">
              <span className="text-gray-400">Overall Conversion</span>
              <div className="flex items-center gap-2">
                <TrendingUp className="h-4 w-4 text-green-400" />
                <span className="text-lg font-bold text-green-400">
                  {((stages[stages.length - 1].value / stages[0].value) * 100).toFixed(2)}%
                </span>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  )
}

export default FunnelChart

"use client"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { cn } from "@/lib/utils"
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
} from "recharts"
import { format, parseISO } from "date-fns"

interface DataSeries {
  key: string
  name: string
  color: string
  stackId?: string
}

interface TimeSeriesChartProps {
  title: string
  subtitle?: string
  data: Array<Record<string, any>>
  series: DataSeries[]
  xAxisKey?: string
  dateFormat?: string
  height?: number
  stacked?: boolean
  loading?: boolean
  icon?: React.ComponentType<{ className?: string }>
  valueFormatter?: (value: number) => string
}

export function TimeSeriesChart({
  title,
  subtitle,
  data,
  series,
  xAxisKey = "date",
  dateFormat = "MMM d",
  height = 300,
  stacked = false,
  loading = false,
  icon: Icon,
  valueFormatter = (v) => v.toLocaleString(),
}: TimeSeriesChartProps) {
  const formatXAxis = (value: string) => {
    try {
      // Handle both ISO strings and pre-formatted dates
      const date = value.includes("T") ? parseISO(value) : new Date(value)
      return format(date, dateFormat)
    } catch {
      return value
    }
  }

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (!active || !payload) return null

    return (
      <div className="bg-gray-900 border border-gray-700 rounded-lg p-3 shadow-xl">
        <p className="text-gray-400 text-sm mb-2">
          {formatXAxis(label)}
        </p>
        {payload.map((entry: any, index: number) => (
          <div key={entry.name ?? `tooltip-${index}`} className="flex items-center gap-2 text-sm">
            <div
              className="w-3 h-3 rounded-full"
              style={{ backgroundColor: entry.color }}
            />
            <span className="text-gray-300">{entry.name}:</span>
            <span className="font-semibold text-white">
              {valueFormatter(entry.value)}
            </span>
          </div>
        ))}
      </div>
    )
  }

  if (loading) {
    return (
      <Card className="bg-gray-900/50 border-gray-800">
        <CardHeader>
          <CardTitle className="text-white flex items-center gap-2">
            {Icon && <Icon className="h-5 w-5 text-[#00d9ff]" />}
            {title}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="animate-pulse">
            <div className="h-[300px] bg-gray-800 rounded" />
          </div>
        </CardContent>
      </Card>
    )
  }

  if (!data || data.length === 0) {
    return (
      <Card className="bg-gray-900/50 border-gray-800">
        <CardHeader>
          <CardTitle className="text-white flex items-center gap-2">
            {Icon && <Icon className="h-5 w-5 text-[#00d9ff]" />}
            {title}
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="h-[300px] flex items-center justify-center text-gray-500">
            No data available
          </div>
        </CardContent>
      </Card>
    )
  }

  return (
    <Card className="bg-gray-900/50 border-gray-800">
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-white flex items-center gap-2">
            {Icon && <Icon className="h-5 w-5 text-[#00d9ff]" />}
            {title}
          </CardTitle>
          {subtitle && (
            <span className="text-sm text-gray-500">{subtitle}</span>
          )}
        </div>
      </CardHeader>
      <CardContent>
        <div style={{ height }}>
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart
              data={data}
              margin={{ top: 10, right: 10, left: 0, bottom: 0 }}
            >
              <defs>
                {series.map((s) => (
                  <linearGradient
                    key={s.key}
                    id={`gradient-${s.key}`}
                    x1="0"
                    y1="0"
                    x2="0"
                    y2="1"
                  >
                    <stop offset="5%" stopColor={s.color} stopOpacity={0.3} />
                    <stop offset="95%" stopColor={s.color} stopOpacity={0} />
                  </linearGradient>
                ))}
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="#374151" vertical={false} />
              <XAxis
                dataKey={xAxisKey}
                tickFormatter={formatXAxis}
                stroke="#6B7280"
                fontSize={12}
                tickLine={false}
                axisLine={false}
              />
              <YAxis
                stroke="#6B7280"
                fontSize={12}
                tickLine={false}
                axisLine={false}
                tickFormatter={(value) => {
                  if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M`
                  if (value >= 1000) return `${(value / 1000).toFixed(1)}K`
                  return value
                }}
              />
              <Tooltip content={<CustomTooltip />} />
              {series.length > 1 && (
                <Legend
                  wrapperStyle={{ paddingTop: 20 }}
                  formatter={(value) => (
                    <span className="text-gray-400 text-sm">{value}</span>
                  )}
                />
              )}
              {series.map((s) => (
                <Area
                  key={s.key}
                  type="monotone"
                  dataKey={s.key}
                  name={s.name}
                  stroke={s.color}
                  strokeWidth={2}
                  fill={`url(#gradient-${s.key})`}
                  stackId={stacked ? "stack" : s.stackId}
                />
              ))}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </CardContent>
    </Card>
  )
}

export default TimeSeriesChart

"use client"

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Progress } from "@/components/ui/progress"
import {
  BarChart3,
  TrendingUp,
  TrendingDown,
  Minus,
  AlertTriangle,
  CheckCircle,
  XCircle,
  Info,
} from "lucide-react"
import type { TTestResult, PredictionMetrics, SampleSizeAnalysis } from "@/lib/research/statistics"
import type { EnhancedResearchAnalysis } from "@/lib/research/analyzer"

// ============================================
// Significance Test Card
// ============================================

interface SignificanceTestCardProps {
  title: string
  test: TTestResult | null
  description?: string
}

export function SignificanceTestCard({ title, test, description }: SignificanceTestCardProps) {
  if (!test) {
    return (
      <Card className="border-gray-800 bg-gray-900/50">
        <CardContent className="pt-4">
          <div className="flex items-center gap-2 text-gray-400">
            <Info className="h-4 w-4" />
            <span className="text-sm font-medium">{title}</span>
          </div>
          <p className="mt-2 text-xs text-gray-500">Insufficient data</p>
        </CardContent>
      </Card>
    )
  }

  const isSignificant = test.significant
  const pValueFormatted = test.pValue < 0.001 ? "< 0.001" : test.pValue.toFixed(4)

  return (
    <Card
      className={`border-gray-800 bg-gray-900/50 ${isSignificant ? "border-green-500/30" : ""}`}
    >
      <CardContent className="pt-4">
        <div className="mb-3 flex items-center justify-between">
          <span className="text-sm font-medium text-white">{title}</span>
          <Badge
            variant="outline"
            className={
              isSignificant ? "border-green-500 text-green-400" : "border-gray-600 text-gray-400"
            }
          >
            {isSignificant ? "Significant" : "Not Significant"}
          </Badge>
        </div>

        <div className="space-y-2 text-sm">
          <div className="flex justify-between">
            <span className="text-gray-400">p-value</span>
            <span className={isSignificant ? "text-green-400" : "text-gray-300"}>
              {pValueFormatted}
            </span>
          </div>

          <div className="flex justify-between">
            <span className="text-gray-400">Effect Size</span>
            <span className="text-gray-300">
              {test.effectSize.toFixed(3)} ({test.effectSizeInterpretation})
            </span>
          </div>

          <div className="flex justify-between">
            <span className="text-gray-400">t-statistic</span>
            <span className="text-gray-300">{test.tStatistic.toFixed(3)}</span>
          </div>

          <div className="flex justify-between">
            <span className="text-gray-400">Mean Difference</span>
            <span className={test.meanDifference > 0 ? "text-purple-400" : "text-blue-400"}>
              {test.meanDifference > 0 ? "+" : ""}
              {test.meanDifference.toFixed(2)}
              {test.meanDifference > 0 ? " (FSRS)" : " (SM-2)"}
            </span>
          </div>

          <div className="flex justify-between">
            <span className="text-gray-400">Power</span>
            <span className="text-gray-300">
              {(test.powerAnalysis.observedPower * 100).toFixed(0)}%
            </span>
          </div>
        </div>

        {description && <p className="mt-3 text-xs text-gray-500">{description}</p>}
      </CardContent>
    </Card>
  )
}

// ============================================
// Prediction Accuracy Panel
// ============================================

interface PredictionAccuracyPanelProps {
  sm2Metrics: PredictionMetrics
  fsrsMetrics: PredictionMetrics
  comparison: {
    logLossDifference: number
    winner: "sm2" | "fsrs" | "equal"
    improvement: number
  }
}

export function PredictionAccuracyPanel({
  sm2Metrics,
  fsrsMetrics,
  comparison,
}: PredictionAccuracyPanelProps) {
  const metrics = [
    {
      name: "Log Loss",
      sm2: sm2Metrics.logLoss,
      fsrs: fsrsMetrics.logLoss,
      format: (v: number) => v.toFixed(4),
      lowerBetter: true,
    },
    {
      name: "RMSE",
      sm2: sm2Metrics.rmse,
      fsrs: fsrsMetrics.rmse,
      format: (v: number) => v.toFixed(4),
      lowerBetter: true,
    },
    {
      name: "Accuracy",
      sm2: sm2Metrics.accuracy * 100,
      fsrs: fsrsMetrics.accuracy * 100,
      format: (v: number) => `${v.toFixed(1)}%`,
      lowerBetter: false,
    },
    {
      name: "Brier Score",
      sm2: sm2Metrics.brierScore,
      fsrs: fsrsMetrics.brierScore,
      format: (v: number) => v.toFixed(4),
      lowerBetter: true,
    },
    {
      name: "AUC-ROC",
      sm2: sm2Metrics.aucRoc,
      fsrs: fsrsMetrics.aucRoc,
      format: (v: number) => v.toFixed(3),
      lowerBetter: false,
    },
  ]

  return (
    <Card className="border-gray-700 bg-gradient-to-r from-gray-900/80 to-gray-800/50">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <BarChart3 className="h-5 w-5 text-[#00d9ff]" />
          Prediction Accuracy Comparison
        </CardTitle>
        <CardDescription>How well each algorithm predicts user recall</CardDescription>
      </CardHeader>
      <CardContent>
        {/* Winner Banner */}
        {comparison.winner !== "equal" && (
          <div
            className={`mb-4 rounded-lg p-3 ${
              comparison.winner === "fsrs" ? "bg-purple-500/10" : "bg-blue-500/10"
            }`}
          >
            <div className="flex items-center gap-2">
              <CheckCircle
                className={`h-5 w-5 ${
                  comparison.winner === "fsrs" ? "text-purple-400" : "text-blue-400"
                }`}
              />
              <span className="font-medium text-white">
                {comparison.winner.toUpperCase()} has {comparison.improvement.toFixed(1)}% better
                prediction accuracy
              </span>
            </div>
          </div>
        )}

        {/* Metrics Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-700">
                <th className="pb-2 text-left text-gray-400">Metric</th>
                <th className="pb-2 text-center text-blue-400">SM-2</th>
                <th className="pb-2 text-center text-purple-400">FSRS</th>
                <th className="pb-2 text-right text-gray-400">Winner</th>
              </tr>
            </thead>
            <tbody>
              {metrics.map((m) => {
                const sm2Better = m.lowerBetter ? m.sm2 < m.fsrs : m.sm2 > m.fsrs
                const equal = Math.abs(m.sm2 - m.fsrs) < 0.001
                const winner = equal ? "tie" : sm2Better ? "sm2" : "fsrs"

                return (
                  <tr key={m.name} className="border-b border-gray-800">
                    <td className="py-2 text-gray-300">{m.name}</td>
                    <td
                      className={`py-2 text-center ${winner === "sm2" ? "font-medium text-blue-400" : "text-gray-400"}`}
                    >
                      {m.format(m.sm2)}
                    </td>
                    <td
                      className={`py-2 text-center ${winner === "fsrs" ? "font-medium text-purple-400" : "text-gray-400"}`}
                    >
                      {m.format(m.fsrs)}
                    </td>
                    <td className="py-2 text-right">
                      {winner === "tie" ? (
                        <Minus className="ml-auto h-4 w-4 text-gray-500" />
                      ) : winner === "sm2" ? (
                        <Badge variant="outline" className="border-blue-500 text-blue-400">
                          SM-2
                        </Badge>
                      ) : (
                        <Badge variant="outline" className="border-purple-500 text-purple-400">
                          FSRS
                        </Badge>
                      )}
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>

        <p className="mt-4 text-xs text-gray-500">
          Lower Log Loss and RMSE = better predictions. Higher Accuracy and AUC-ROC = better
          predictions.
        </p>
      </CardContent>
    </Card>
  )
}

// ============================================
// Sample Size Analysis Panel
// ============================================

interface SampleSizeAnalysisPanelProps {
  analysis: SampleSizeAnalysis
}

export function SampleSizeAnalysisPanel({ analysis }: SampleSizeAnalysisPanelProps) {
  const progressToMinimum = Math.min(
    100,
    (analysis.totalSample / (analysis.minimumRequired * 2)) * 100
  )
  const progressToPower80 = Math.min(
    100,
    (analysis.totalSample / (analysis.recommendedForPower80 * 2)) * 100
  )

  return (
    <Card className="border-gray-800 bg-gray-900/50">
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-base">
          <BarChart3 className="h-4 w-4 text-[#00d9ff]" />
          Sample Size Analysis
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Status */}
        <div className="flex items-center gap-2">
          {analysis.isSufficient ? (
            <>
              <CheckCircle className="h-5 w-5 text-green-400" />
              <span className="text-green-400">Sufficient sample size</span>
            </>
          ) : (
            <>
              <AlertTriangle className="h-5 w-5 text-yellow-400" />
              <span className="text-yellow-400">Need more data</span>
            </>
          )}
        </div>

        {/* Counts */}
        <div className="grid grid-cols-2 gap-4">
          <div className="rounded bg-blue-500/10 p-3 text-center">
            <p className="text-2xl font-bold text-blue-400">{analysis.currentSampleSm2}</p>
            <p className="text-xs text-gray-400">SM-2 Users</p>
          </div>
          <div className="rounded bg-purple-500/10 p-3 text-center">
            <p className="text-2xl font-bold text-purple-400">{analysis.currentSampleFsrs}</p>
            <p className="text-xs text-gray-400">FSRS Users</p>
          </div>
        </div>

        {/* Progress to targets */}
        <div className="space-y-2">
          <div>
            <div className="mb-1 flex justify-between text-xs">
              <span className="text-gray-400">To Minimum ({analysis.minimumRequired}/group)</span>
              <span className="text-gray-300">{progressToMinimum.toFixed(0)}%</span>
            </div>
            <Progress value={progressToMinimum} className="h-2" />
          </div>

          <div>
            <div className="mb-1 flex justify-between text-xs">
              <span className="text-gray-400">
                To 80% Power ({analysis.recommendedForPower80}/group)
              </span>
              <span className="text-gray-300">{progressToPower80.toFixed(0)}%</span>
            </div>
            <Progress value={progressToPower80} className="h-2" />
          </div>
        </div>

        {/* Power */}
        <div className="flex justify-between text-sm">
          <span className="text-gray-400">Current Statistical Power</span>
          <span
            className={
              analysis.powerWithCurrentSample >= 0.8 ? "text-green-400" : "text-yellow-400"
            }
          >
            {(analysis.powerWithCurrentSample * 100).toFixed(0)}%
          </span>
        </div>

        {/* ETA */}
        {analysis.estimatedDaysToSufficient && (
          <div className="flex justify-between text-sm">
            <span className="text-gray-400">Est. Days to Sufficient</span>
            <span className="text-gray-300">{analysis.estimatedDaysToSufficient} days</span>
          </div>
        )}
      </CardContent>
    </Card>
  )
}

// ============================================
// Research Quality Score Panel
// ============================================

interface QualityScorePanelProps {
  qualityScore: EnhancedResearchAnalysis["qualityScore"]
}

export function QualityScorePanel({ qualityScore }: QualityScorePanelProps) {
  const getScoreColor = (score: number) => {
    if (score >= 80) return "text-green-400"
    if (score >= 60) return "text-blue-400"
    if (score >= 40) return "text-yellow-400"
    return "text-red-400"
  }

  const categories = [
    { name: "Sample Size", score: qualityScore.sampleSize, max: 25 },
    { name: "Statistical Power", score: qualityScore.statisticalPower, max: 25 },
    { name: "Data Quality", score: qualityScore.dataQuality, max: 25 },
    { name: "Consistency", score: qualityScore.consistency, max: 25 },
  ]

  return (
    <Card className="border-gray-800 bg-gray-900/50">
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-base">
          <CheckCircle className="h-4 w-4 text-[#00d9ff]" />
          Research Quality Score
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Overall Score */}
        <div className="text-center">
          <p className={`text-5xl font-bold ${getScoreColor(qualityScore.overall)}`}>
            {qualityScore.overall}
          </p>
          <p className="text-sm text-gray-400">out of 100</p>
        </div>

        {/* Category Breakdown */}
        <div className="space-y-2">
          {categories.map((cat) => (
            <div key={cat.name}>
              <div className="mb-1 flex justify-between text-xs">
                <span className="text-gray-400">{cat.name}</span>
                <span className="text-gray-300">
                  {cat.score}/{cat.max}
                </span>
              </div>
              <Progress value={(cat.score / cat.max) * 100} className="h-1.5" />
            </div>
          ))}
        </div>

        {/* Interpretation */}
        <p className="text-sm text-gray-300">{qualityScore.interpretation}</p>
      </CardContent>
    </Card>
  )
}

// ============================================
// Recommendations Panel
// ============================================

interface RecommendationsPanelProps {
  recommendations: EnhancedResearchAnalysis["recommendations"]
}

export function RecommendationsPanel({ recommendations }: RecommendationsPanelProps) {
  const getPriorityColor = (priority: "high" | "medium" | "low") => {
    switch (priority) {
      case "high":
        return "border-red-500 bg-red-500/10"
      case "medium":
        return "border-yellow-500 bg-yellow-500/10"
      case "low":
        return "border-gray-500 bg-gray-500/10"
    }
  }

  const getPriorityBadge = (priority: "high" | "medium" | "low") => {
    switch (priority) {
      case "high":
        return <Badge className="bg-red-500">High</Badge>
      case "medium":
        return <Badge className="bg-yellow-500 text-black">Medium</Badge>
      case "low":
        return (
          <Badge variant="outline" className="border-gray-500">
            Low
          </Badge>
        )
    }
  }

  return (
    <Card className="border-gray-700 bg-gradient-to-r from-gray-900/80 to-gray-800/50">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <TrendingUp className="h-5 w-5 text-[#00d9ff]" />
          Research Recommendations
        </CardTitle>
        <CardDescription>Actionable insights based on current data</CardDescription>
      </CardHeader>
      <CardContent className="space-y-3">
        {recommendations.length === 0 ? (
          <p className="text-gray-400">No recommendations at this time.</p>
        ) : (
          recommendations.map((rec, i) => (
            <div key={i} className={`rounded-lg border p-4 ${getPriorityColor(rec.priority)}`}>
              <div className="mb-2 flex items-center justify-between">
                <h4 className="font-medium text-white">{rec.title}</h4>
                {getPriorityBadge(rec.priority)}
              </div>
              <p className="text-sm text-gray-300">{rec.description}</p>
              {rec.action && (
                <p className="mt-2 text-sm text-[#00d9ff]">
                  <strong>Action:</strong> {rec.action}
                </p>
              )}
            </div>
          ))
        )}
      </CardContent>
    </Card>
  )
}

"use client"

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Search, RefreshCw, Loader2, ChevronLeft, ChevronRight } from "lucide-react"
import { ReactNode, useState } from "react"
import { cn } from "@/lib/utils"

export interface Column<T> {
  key: string
  label: string
  width?: string
  align?: "left" | "center" | "right"
  render?: (value: any, row: T) => ReactNode
  sortable?: boolean
}

interface DataTableProps<T> {
  title?: string
  description?: string
  icon?: React.ComponentType<{ className?: string }>
  data: T[]
  columns: Column<T>[]
  keyExtractor: (row: T) => string
  loading?: boolean
  searchable?: boolean
  searchPlaceholder?: string
  onSearch?: (query: string) => void
  onRefresh?: () => void
  refreshing?: boolean
  pagination?: {
    page: number
    totalPages: number
    onPageChange: (page: number) => void
  }
  emptyMessage?: string
  actions?: ReactNode
  rowClassName?: (row: T) => string
}

export function DataTable<T>({
  title,
  description,
  icon: Icon,
  data,
  columns,
  keyExtractor,
  loading = false,
  searchable = false,
  searchPlaceholder = "Search...",
  onSearch,
  onRefresh,
  refreshing = false,
  pagination,
  emptyMessage = "No data found",
  actions,
  rowClassName,
}: DataTableProps<T>) {
  const [searchQuery, setSearchQuery] = useState("")
  const [sortColumn, setSortColumn] = useState<string | null>(null)
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("asc")

  const handleSearch = (query: string) => {
    setSearchQuery(query)
    onSearch?.(query)
  }

  const handleSort = (columnKey: string) => {
    if (sortColumn === columnKey) {
      setSortDirection(sortDirection === "asc" ? "desc" : "asc")
    } else {
      setSortColumn(columnKey)
      setSortDirection("asc")
    }
  }

  return (
    <Card className="bg-gray-900/50 border-gray-800">
      {(title || description || searchable || onRefresh || actions) && (
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="flex-1">
              {title && (
                <CardTitle className="text-white flex items-center gap-2">
                  {Icon && <Icon className="h-5 w-5 text-[#00d9ff]" />}
                  {title}
                </CardTitle>
              )}
              {description && (
                <CardDescription className="text-gray-400 mt-1">
                  {description}
                </CardDescription>
              )}
            </div>

            <div className="flex items-center gap-2">
              {searchable && (
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
                  <Input
                    placeholder={searchPlaceholder}
                    value={searchQuery}
                    onChange={(e) => handleSearch(e.target.value)}
                    className="pl-10 w-64 bg-gray-800 border-gray-700 text-white"
                  />
                </div>
              )}

              {actions}

              {onRefresh && (
                <Button
                  onClick={onRefresh}
                  variant="outline"
                  size="sm"
                  disabled={refreshing}
                  className="border-gray-700 text-gray-400 hover:text-white"
                >
                  <RefreshCw
                    className={cn("h-4 w-4 mr-2", refreshing && "animate-spin")}
                  />
                  Refresh
                </Button>
              )}
            </div>
          </div>
        </CardHeader>
      )}

      <CardContent>
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-[#00d9ff]" />
          </div>
        ) : data.length === 0 ? (
          <div className="text-center py-12 text-gray-400">{emptyMessage}</div>
        ) : (
          <>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-gray-800">
                    {columns.map((column) => (
                      <th
                        key={column.key}
                        className={cn(
                          "py-3 px-4 text-gray-400 font-medium text-sm",
                          column.align === "center" && "text-center",
                          column.align === "right" && "text-right",
                          column.align !== "center" && column.align !== "right" && "text-left",
                          column.sortable && "cursor-pointer hover:text-white"
                        )}
                        style={column.width ? { width: column.width } : undefined}
                        onClick={() => column.sortable && handleSort(column.key)}
                      >
                        <div className="flex items-center gap-1">
                          {column.label}
                          {column.sortable && sortColumn === column.key && (
                            <span className="text-[#00d9ff]">
                              {sortDirection === "asc" ? "↑" : "↓"}
                            </span>
                          )}
                        </div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {data.map((row) => (
                    <tr
                      key={keyExtractor(row)}
                      className={cn(
                        "border-b border-gray-800/50 hover:bg-gray-800/30",
                        rowClassName?.(row)
                      )}
                    >
                      {columns.map((column) => {
                        const value = (row as any)[column.key]
                        return (
                          <td
                            key={column.key}
                            className={cn(
                              "py-3 px-4",
                              column.align === "center" && "text-center",
                              column.align === "right" && "text-right"
                            )}
                          >
                            {column.render ? column.render(value, row) : value}
                          </td>
                        )
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {pagination && pagination.totalPages > 1 && (
              <div className="flex items-center justify-between mt-4 pt-4 border-t border-gray-800">
                <div className="text-sm text-gray-400">
                  Page {pagination.page} of {pagination.totalPages}
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => pagination.onPageChange(pagination.page - 1)}
                    disabled={pagination.page === 1}
                    className="border-gray-700 text-gray-400 hover:text-white"
                  >
                    <ChevronLeft className="h-4 w-4 mr-1" />
                    Previous
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => pagination.onPageChange(pagination.page + 1)}
                    disabled={pagination.page === pagination.totalPages}
                    className="border-gray-700 text-gray-400 hover:text-white"
                  >
                    Next
                    <ChevronRight className="h-4 w-4 ml-1" />
                  </Button>
                </div>
              </div>
            )}
          </>
        )}
      </CardContent>
    </Card>
  )
}

export function renderBadge(
  text: string,
  variant: "default" | "success" | "warning" | "error" = "default"
) {
  const colorMap = {
    default: "bg-gray-600/20 text-gray-400 border-gray-600/30",
    success: "bg-green-600/20 text-green-400 border-green-600/30",
    warning: "bg-yellow-600/20 text-yellow-400 border-yellow-600/30",
    error: "bg-red-600/20 text-red-400 border-red-600/30",
  }

  return <Badge className={colorMap[variant]}>{text}</Badge>
}

"use client"

import { Button } from "@/components/ui/button"
import { Download, Loader2 } from "lucide-react"
import { useState } from "react"
import { exportToCSV } from "@/lib/admin"
import { logger } from "@/lib/logger"

interface ExportButtonProps {
  data: any[]
  filename: string
  label?: string
  disabled?: boolean
  variant?: "default" | "outline" | "ghost"
  size?: "default" | "sm" | "lg"
  className?: string
}

export function ExportButton({
  data,
  filename,
  label = "Export CSV",
  disabled = false,
  variant = "outline",
  size = "sm",
  className = "",
}: ExportButtonProps) {
  const [exporting, setExporting] = useState(false)

  const handleExport = async () => {
    if (data.length === 0) {
      alert("No data to export")
      return
    }

    setExporting(true)

    try {
      await new Promise((resolve) => setTimeout(resolve, 100))
      exportToCSV(data, filename)
    } catch (error) {
      logger.error("Export failed", { error, filename, rowCount: data.length })
      alert("Export failed. Please try again.")
    } finally {
      setExporting(false)
    }
  }

  return (
    <Button
      onClick={handleExport}
      variant={variant}
      size={size}
      disabled={disabled || exporting || data.length === 0}
      className={className}
    >
      {exporting ? (
        <Loader2 className="h-4 w-4 mr-2 animate-spin" />
      ) : (
        <Download className="h-4 w-4 mr-2" />
      )}
      {label}
    </Button>
  )
}

interface ExportMenuProps {
  exports: Array<{
    label: string
    data: any[]
    filename: string
  }>
}

export function ExportMenu({ exports }: ExportMenuProps) {
  return (
    <div className="flex gap-2">
      {exports.map((exp, index) => (
        <ExportButton
          key={index}
          data={exp.data}
          filename={exp.filename}
          label={exp.label}
        />
      ))}
    </div>
  )
}

