    const timer = setTimeout(() => setIsVisible(true), 50)
    return () => clearTimeout(timer)
  }, [])

  // Handle exit animation
  const handleClose = useCallback(() => {
    setIsExiting(true)
    setTimeout(() => {
      onClose()
    }, 200)
  }, [onClose])

  const handleDismiss = useCallback(() => {
    setIsExiting(true)
    setTimeout(() => {
      onDismiss()
    }, 200)
  }, [onDismiss])

  // Focus trap and keyboard handling
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && announcement.dismissible) {
        handleDismiss()
      }

      // Focus trap
      if (e.key === "Tab" && modalRef.current) {
        const focusableElements = modalRef.current.querySelectorAll(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        )
        const firstElement = focusableElements[0] as HTMLElement
        const lastElement = focusableElements[focusableElements.length - 1] as HTMLElement

        if (e.shiftKey && document.activeElement === firstElement) {
          e.preventDefault()
          lastElement?.focus()
        } else if (!e.shiftKey && document.activeElement === lastElement) {
          e.preventDefault()
          firstElement?.focus()
        }
      }
    }

    document.addEventListener("keydown", handleKeyDown)

    // Focus the first focusable element
    closeButtonRef.current?.focus()

    // Prevent body scroll
    const originalOverflow = document.body.style.overflow
    document.body.style.overflow = "hidden"

    return () => {
      document.removeEventListener("keydown", handleKeyDown)
      document.body.style.overflow = originalOverflow
    }
  }, [announcement.dismissible, handleDismiss])

  const handleBackdropClick = (e: React.MouseEvent) => {
    if (e.target === e.currentTarget && announcement.dismissible) {
      handleDismiss()
    }
  }

  const handleCtaClick = () => {
    if (announcement.cta?.url) {
      window.open(announcement.cta.url, "_blank", "noopener,noreferrer")
      if (announcement.dismissible) {
        handleDismiss()
      }
    }
  }

  return (
    <div
      className={cn(
        "fixed inset-0 z-[200] flex items-center justify-center p-4 sm:p-6",
        "transition-all duration-200 ease-out",
        isVisible && !isExiting ? "opacity-100" : "opacity-0"
      )}
      onClick={handleBackdropClick}
      role="dialog"
      aria-modal="true"
      aria-labelledby="announcement-title"
      aria-describedby="announcement-message"
    >
      {/* Backdrop */}
      <div
        className={cn(
          "absolute inset-0 bg-black/60 backdrop-blur-sm",
          "transition-opacity duration-200"
        )}
        aria-hidden="true"
      />

      {/* Modal */}
      <div
        ref={modalRef}
        tabIndex={-1}
        className={cn(
          "relative w-full max-w-md overflow-hidden",
          "bg-card border-border rounded-2xl border shadow-2xl",
          "transition-all duration-200 ease-out",
          isVisible && !isExiting
            ? "translate-y-0 scale-100 opacity-100"
            : "translate-y-4 scale-95 opacity-0"
        )}
      >
        {/* Gradient header background */}
        <div
          className={cn(
            "absolute top-0 right-0 left-0 h-32 bg-gradient-to-b opacity-50",
            config.gradient
          )}
          aria-hidden="true"
        />

        {/* Content */}
        <div className="relative p-6 sm:p-8">
          {/* Close button */}
          {announcement.dismissible && (
            <button
              ref={closeButtonRef}
              onClick={handleDismiss}
              className={cn(
                "absolute top-4 right-4 rounded-full p-2",
                "text-muted-foreground hover:text-foreground",
                "bg-secondary/50 hover:bg-secondary",
                "transition-all duration-200",
                "focus-visible:ring-ring focus:outline-none focus-visible:ring-2"
              )}
              aria-label="Close announcement"
            >
              <X className="h-4 w-4" aria-hidden="true" />
            </button>
          )}

          {/* Icon */}
          <div className="mb-6">
            <div
              className={cn(
                "inline-flex h-14 w-14 items-center justify-center rounded-2xl",
                config.iconBg,
                "ring-1",
                config.iconRing,
                "transition-transform duration-300 hover:scale-105"
              )}
            >
              <Icon className={cn("h-7 w-7", config.iconColor)} aria-hidden="true" />
            </div>
          </div>

          {/* Title */}
          <h2
            id="announcement-title"
            className={cn(
              "mb-3 text-xl font-semibold tracking-tight sm:text-2xl",
              config.titleColor
            )}
          >
            {announcement.title}
          </h2>

          {/* Message */}
          <p
            id="announcement-message"
            className="text-muted-foreground mb-8 text-sm leading-relaxed sm:text-base"
          >
            {announcement.message}
          </p>

          {/* Actions */}
          <div className="flex flex-col-reverse gap-3 sm:flex-row">
            {announcement.dismissible && (
              <Button
                variant="outline"
                className={cn(
                  "h-11 flex-1 rounded-xl font-medium",
                  "border-border text-muted-foreground",
                  "hover:bg-secondary hover:text-foreground",
                  "transition-all duration-200"
                )}
                onClick={handleDismiss}
              >
                {announcement.cta ? "Maybe Later" : "Got it"}
              </Button>
            )}

            {announcement.cta && (
              <Button
                className={cn(
                  "h-11 flex-1 rounded-xl font-medium",
                  config.buttonPrimary,
                  "transition-all duration-200",
                  "shadow-lg hover:shadow-xl"
                )}
                onClick={handleCtaClick}
              >
                {announcement.cta.text}
                <ExternalLink className="ml-2 h-4 w-4" aria-hidden="true" />
              </Button>
            )}

            {!announcement.dismissible && !announcement.cta && (
              <Button
                variant="outline"
                className={cn(
                  "h-11 flex-1 rounded-xl font-medium",
                  "border-border text-foreground",
                  "hover:bg-secondary",
                  "transition-all duration-200"
                )}
                onClick={handleClose}
              >
                Close
              </Button>
            )}
          </div>
        </div>

        {/* Bottom accent line */}
        <div
          className={cn(
            "absolute right-0 bottom-0 left-0 h-1",
            `bg-gradient-to-r from-transparent via-${config.accentColor} to-transparent`,
            "opacity-50"
          )}
          aria-hidden="true"
        />
      </div>
    </div>
  )
}

"use client"

import React, { createContext, useContext, useEffect, useState, useCallback, useRef } from "react"
import { useAuth } from "@/lib/auth-context"
import { toast } from "sonner"
import { AnnouncementBanner } from "./AnnouncementBanner"
import { AnnouncementModal } from "./AnnouncementModal"
import { cn } from "@/lib/utils"
import type { Announcement } from "@/lib/types/announcements"

interface AnnouncementContextValue {
  announcements: Announcement[]
  dismissAnnouncement: (id: string) => Promise<void>
  refreshAnnouncements: () => Promise<void>
  getBannerAnnouncements: () => Announcement[]
  getModalAnnouncements: () => Announcement[]
}

const AnnouncementContext = createContext<AnnouncementContextValue | null>(null)

const STORAGE_KEY = "dismissed_announcements"
const FETCH_INTERVAL = 5 * 60 * 1000 // 5 minutes

export function useAnnouncements() {
  const context = useContext(AnnouncementContext)
  if (!context) {
    throw new Error("useAnnouncements must be used within an AnnouncementProvider")
  }
  return context
}

interface AnnouncementProviderProps {
  children: React.ReactNode
}

export function AnnouncementProvider({ children }: AnnouncementProviderProps) {
  const { firebaseUser } = useAuth()
  const [announcements, setAnnouncements] = useState<Announcement[]>([])
  const [dismissedIds, setDismissedIds] = useState<string[]>([])
  const [shownToastIds, setShownToastIds] = useState<Set<string>>(new Set())
  const [shownModalIds, setShownModalIds] = useState<Set<string>>(new Set())
  const [currentModal, setCurrentModal] = useState<Announcement | null>(null)
  const [bannerHeight, setBannerHeight] = useState(0)
  const bannerContainerRef = useRef<HTMLDivElement>(null)

  // Load dismissed IDs from localStorage on mount
  useEffect(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY)
      if (stored) {
        setDismissedIds(JSON.parse(stored))
      }
    } catch {
      // Ignore localStorage errors
    }
  }, [])

  // Fetch announcements
  const fetchAnnouncements = useCallback(async () => {
    try {
      const headers: Record<string, string> = {}

      if (firebaseUser) {
        const token = await firebaseUser.getIdToken()
        headers["Authorization"] = `Bearer ${token}`
      }

      // Send dismissed IDs for non-logged-in users
      if (!firebaseUser && dismissedIds.length > 0) {
        headers["X-Dismissed-Announcements"] = JSON.stringify(dismissedIds)
      }

      const response = await fetch("/api/announcements", { headers })

      if (response.ok) {
        const data = await response.json()
        if (data.success && data.announcements) {
          // Filter out locally dismissed announcements
          const filtered = data.announcements.filter(
            (a: Announcement) => !dismissedIds.includes(a.id)
          )
          setAnnouncements(filtered)
        }
      }
    } catch (error) {
      console.error("[Announcements] Error fetching:", error)
    }
  }, [firebaseUser, dismissedIds])

  // Initial fetch and periodic refresh
  useEffect(() => {
    fetchAnnouncements()

    const interval = setInterval(fetchAnnouncements, FETCH_INTERVAL)
    return () => clearInterval(interval)
  }, [fetchAnnouncements])

  // Show toast announcements when they arrive
  useEffect(() => {
    announcements
      .filter((a) => a.type === "toast" && !shownToastIds.has(a.id))
      .forEach((announcement) => {
        setShownToastIds((prev) => new Set([...prev, announcement.id]))

        const toastOptions = {
          id: announcement.id,
          duration: announcement.dismissible ? 8000 : 15000,
          action: announcement.cta
            ? {
                label: announcement.cta.text,
                onClick: () => window.open(announcement.cta!.url, "_blank"),
              }
            : undefined,
          onDismiss: announcement.dismissible
            ? () => dismissAnnouncement(announcement.id)
            : undefined,
        }

        switch (announcement.priority) {
          case "success":
            toast.success(announcement.title, {
              description: announcement.message,
              ...toastOptions,
            })
            break
          case "warning":
            toast.warning(announcement.title, {
              description: announcement.message,
              ...toastOptions,
            })
            break
          case "critical":
            toast.error(announcement.title, {
              description: announcement.message,
              ...toastOptions,
            })
            break
          default:
            toast.info(announcement.title, {
              description: announcement.message,
              ...toastOptions,
            })
        }
      })
  }, [announcements, shownToastIds])

  // Show modal announcements one at a time
  useEffect(() => {
    if (currentModal) return // Don't show another if one is open

    const modalAnnouncement = announcements.find(
      (a) => a.type === "modal" && !shownModalIds.has(a.id)
    )

    if (modalAnnouncement) {
      setShownModalIds((prev) => new Set([...prev, modalAnnouncement.id]))
      setCurrentModal(modalAnnouncement)
    }
  }, [announcements, currentModal, shownModalIds])

  // Update banner height CSS variable
  useEffect(() => {
    const bannerAnnouncements = announcements.filter((a) => a.type === "banner")

    if (bannerAnnouncements.length > 0) {
      // Each banner is approximately 52px (py-3 = 12px top + 12px bottom + ~28px content)
      const height = bannerAnnouncements.length * 52
      setBannerHeight(height)
      document.documentElement.style.setProperty("--announcement-banner-height", `${height}px`)
    } else {
      setBannerHeight(0)
      document.documentElement.style.setProperty("--announcement-banner-height", "0px")
    }

    return () => {
      document.documentElement.style.setProperty("--announcement-banner-height", "0px")
    }
  }, [announcements])

  // Dismiss announcement
  const dismissAnnouncement = useCallback(
    async (id: string) => {
      // Update local state immediately
      setAnnouncements((prev) => prev.filter((a) => a.id !== id))
      setDismissedIds((prev) => {
        const updated = [...prev, id]
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(updated))
        } catch {
          // Ignore localStorage errors
        }
        return updated
      })

      // Close modal if it's the current one
      if (currentModal?.id === id) {
        setCurrentModal(null)
      }

      // Dismiss toast
      toast.dismiss(id)

      // Notify server
      try {
        const headers: Record<string, string> = {
          "Content-Type": "application/json",
        }

        if (firebaseUser) {
          const token = await firebaseUser.getIdToken()
          headers["Authorization"] = `Bearer ${token}`
        }

        await fetch("/api/announcements", {
          method: "POST",
          headers,
          body: JSON.stringify({ announcementId: id }),
        })
      } catch {
        // Ignore server errors - local dismissal is sufficient
      }
    },
    [firebaseUser, currentModal]
  )

  // Get banner announcements (shown at top of page)
  const getBannerAnnouncements = useCallback(() => {
    return announcements.filter((a) => a.type === "banner")
  }, [announcements])

  // Get modal announcements
  const getModalAnnouncements = useCallback(() => {
    return announcements.filter((a) => a.type === "modal")
  }, [announcements])

  const handleModalClose = useCallback(() => {
    if (currentModal) {
      if (currentModal.dismissible) {
        dismissAnnouncement(currentModal.id)
      } else {
        setCurrentModal(null)
      }
    }
  }, [currentModal, dismissAnnouncement])

  const value: AnnouncementContextValue = {
    announcements,
    dismissAnnouncement,
    refreshAnnouncements: fetchAnnouncements,
    getBannerAnnouncements,
    getModalAnnouncements,
  }

  const bannerAnnouncements = getBannerAnnouncements()

  return (
    <AnnouncementContext.Provider value={value}>
      {/* Render banner announcements at the top */}
      {bannerAnnouncements.length > 0 && (
        <div
          ref={bannerContainerRef}
          className={cn(
            "fixed top-0 right-0 left-0 z-[100]",
            "flex flex-col",
            "transition-all duration-300 ease-out"
          )}
          role="region"
          aria-label="Announcements"
        >
          {bannerAnnouncements.map((announcement, index) => (
            <div
              key={announcement.id}
              style={{
                animationDelay: `${index * 100}ms`,
              }}
            >
              <AnnouncementBanner
                announcement={announcement}
                onDismiss={() => dismissAnnouncement(announcement.id)}
              />
            </div>
          ))}
        </div>
      )}

      {/* Spacer to push content down when banners are visible */}
      {bannerHeight > 0 && (
        <div
          style={{ height: bannerHeight }}
          className="transition-all duration-300 ease-out"
          aria-hidden="true"
        />
      )}

      {children}

      {/* Render modal */}
      {currentModal && (
        <AnnouncementModal
          announcement={currentModal}
          onClose={handleModalClose}
          onDismiss={() => dismissAnnouncement(currentModal.id)}
        />
      )}
    </AnnouncementContext.Provider>
  )
}

