                  </p>
                </div>
              </div>
              <Link href={`/login?redirect=/interview-prep/${company.id}`}>
                <Button size="sm" variant="outline" className="border-emerald-700 text-emerald-400 hover:bg-emerald-900/50 text-xs">
                  Join them
                </Button>
              </Link>
            </div>
          </div>
        )}

