import { PYTHON_WRAPPER_LINE_OFFSET, JAVASCRIPT_WRAPPER_LINE_OFFSET } from "@/lib/piston"

/**
 * CodeConsole - IDE-like console panel for code execution output
 *
 * Features:
 * - Real-time output display
 * - Syntax/runtime error detection with line numbers (adjusted for wrapper code offset)
 * - Console.log capture
 * - Test results display
 * - Auto-scroll to latest output
 */

export interface ConsoleOutput {
  type: "log" | "error" | "warn" | "info" | "result"
  message: string
  timestamp?: number
  lineNumber?: number
}

export interface TestResult {
  description: string
  passed: boolean
  input: any
  expected: any
  actual: any
  error: string | null
  isHidden?: boolean
}

export interface TestSummary {
  total: number
  passed: number
  failed: number
  passRate: number
}

interface CodeConsoleProps {
  outputs?: ConsoleOutput[]
  testResults?: TestResult[]
  testSummary?: TestSummary
  isRunning?: boolean
  className?: string
  onClear?: () => void
  language?: "python" | "javascript" | "typescript"
  userCodeLineCount?: number // Total lines in user's code for validation
  onGoToLine?: (lineNum: number) => void
}

/**
 * Parse error messages to extract line numbers and adjust for wrapper code offset.
 * The code is wrapped with imports, helper classes, etc. before execution,
 * so reported line numbers need to be adjusted to match user's actual code.
 */
function parseErrorLineNumber(
  error: string,
  language: "python" | "javascript" | "typescript" = "python",
  userCodeLineCount?: number
): number | null {
  // Common patterns:
  // JavaScript: "at line 5" or "line 5" or ":5:"
  // Python: "line 5" or ", line 5" or "File "<string>", line 5"
  // TypeScript: "(5,10)" or ":5:"

  const patterns = [
    /File\s+"<string>",\s+line\s+(\d+)/i, // Python: File "<string>", line 5
    /line\s+(\d+)/i, // "line 5", "Line 5"
    /:(\d+):/, // ":5:" (stack trace format)
    /:(\d+)\)/, // ":5)" (TypeScript format)
    /\((\d+),\s*\d+\)/, // "(5, 10)" (TypeScript format)
    /at\s+.*:(\d+):\d+/, // "at function (file:5:10)"
    /^\s+(\d+)\s+\|/m, // "  5 | code" (Python caret format)
  ]

  let rawLineNum: number | null = null
  for (const pattern of patterns) {
    const match = error.match(pattern)
    if (match && match[1]) {
      rawLineNum = parseInt(match[1], 10)
      break
    }
  }

  if (rawLineNum === null) {
    return null
  }

  // Adjust for wrapper code offset
  const offset = language === "python" ? PYTHON_WRAPPER_LINE_OFFSET : JAVASCRIPT_WRAPPER_LINE_OFFSET
  const adjustedLineNum = rawLineNum - offset

  // Validate: line number should be positive and within user's code
  if (adjustedLineNum < 1) {
    // Error is in the wrapper code itself (shouldn't happen normally)
    // Return null to avoid confusing users
    return null
  }

  // If we know the user's code line count, validate against it
  if (userCodeLineCount && adjustedLineNum > userCodeLineCount) {
    // Error is in the execution wrapper after user's code
    // This might be a runtime error - still show it but cap at last line
    return userCodeLineCount
  }

  return adjustedLineNum
}

// Detect error type from message
function getErrorType(
  error: string
): "syntax" | "runtime" | "type" | "logic" | "timeout" | "security" | "unknown" {
  const lowerError = error.toLowerCase()

  // Security / Execution Environment Errors
  if (
    lowerError.includes("content security policy") ||
    lowerError.includes("content-security-policy") ||
    lowerError.includes("unsafe-eval") ||
    lowerError.includes("failed to spawn web worker") ||
    lowerError.includes("web worker") ||
    lowerError.includes("worker error")
  ) {
    return "security"
  }

  // Syntax/Parse errors
  if (
    lowerError.includes("syntaxerror") ||
    lowerError.includes("unexpected token") ||
    lowerError.includes("parse error") ||
    lowerError.includes("indentationerror") ||
    lowerError.includes("invalid syntax") ||
    lowerError.includes("unterminated string") ||
    lowerError.includes("missing )") ||
    lowerError.includes("missing }") ||
    lowerError.includes("expected")
  ) {
    return "syntax"
  }

  // Type errors
  if (
    lowerError.includes("typeerror") ||
    lowerError.includes("compilation error") ||
    lowerError.includes("cannot read property") ||
    lowerError.includes("is not a function") ||
    lowerError.includes("is not defined") ||
    lowerError.includes("has no attribute") ||
    lowerError.includes("attributeerror")
  ) {
    return "type"
  }

  // Timeout/Recursion errors
  if (
    lowerError.includes("timeout") ||
    lowerError.includes("timed out") ||
    lowerError.includes("maximum call stack") ||
    lowerError.includes("too much recursion") ||
    lowerError.includes("recursionerror") ||
    lowerError.includes("maximum recursion depth") ||
    lowerError.includes("infinite loop")
  ) {
    return "timeout"
  }

  // Runtime/Value errors
  if (
    lowerError.includes("referenceerror") ||
    lowerError.includes("rangeerror") ||
    lowerError.includes("nameerror") ||
    lowerError.includes("valueerror") ||
    lowerError.includes("keyerror") ||
    lowerError.includes("indexerror") ||
    lowerError.includes("zerodivisionerror") ||
    lowerError.includes("division by zero") ||
    lowerError.includes("overflowerror") ||
    lowerError.includes("memoryerror") ||
    lowerError.includes("assertionerror") ||
    lowerError.includes("index out of") ||
    lowerError.includes("list index") ||
    lowerError.includes("undefined") ||
    lowerError.includes("null") ||
    lowerError.includes("'nonetype'")
  ) {
    return "runtime"
  }

  // Logic errors (wrong output, usually caught by test comparison)
  if (
    lowerError.includes("expected") ||
    lowerError.includes("assertion") ||
    lowerError.includes("mismatch")
  ) {
    return "logic"
  }

  return "unknown"
}

// Format error message for display with helpful hints
function formatErrorMessage(
  error: string,
  language: "python" | "javascript" | "typescript" = "python",
  userCodeLineCount?: number
): { title: string; details: string; hint?: string } {
  const errorType = getErrorType(error)
  const lineNum = parseErrorLineNumber(error, language, userCodeLineCount)

  const titles: Record<string, string> = {
    syntax: "🔴 Syntax Error",
    type: "🟠 Type Error",
    runtime: "🔴 Runtime Error",
    timeout: "⏱️ Timeout/Recursion Error",
    logic: "🟡 Logic Error",
    security: "🔒 Execution Environment Error",
    unknown: "❌ Error",
  }

  const hints: Record<string, string> = {
    syntax: "Check for missing brackets, quotes, or typos near the indicated line.",
    type: "Verify variable types and function signatures match what you expect.",
    runtime: "Check for null/undefined values, invalid indices, or missing variables.",
    timeout: "Your code may have an infinite loop or too deep recursion. Add base cases.",
    logic: "Your solution runs but produces incorrect output. Review your algorithm.",
    security:
      "An execution environment or security policy issue occurred. Please contact support or try reloading the page.",
    unknown: "Review your code for potential issues.",
  }

  let title = titles[errorType]
  if (lineNum) {
    title += ` on line ${lineNum}`
  }

  // Clean up the error message for display
  // Remove wrapper-specific file paths and adjust line numbers in the message
  let details = error

  // Replace wrapper line numbers with adjusted ones in the error message
  const wrapperOffset =
    language === "python" ? PYTHON_WRAPPER_LINE_OFFSET : JAVASCRIPT_WRAPPER_LINE_OFFSET
  details = details.replace(/line\s+(\d+)/gi, (match, num) => {
    const adjusted = parseInt(num, 10) - wrapperOffset
    return adjusted > 0 ? `line ${adjusted}` : match
  })

  // Remove the cryptic piston file paths
  details = details.replace(/File\s+"[^"]*\/piston\/[^"]*",\s*/gi, "At ")
  details = details.replace(/\/piston\/jobs\/[a-f0-9-]+\/file\d+\.code/gi, "your code")

  return { title, details, hint: hints[errorType] }
}

export function CodeConsole({
  outputs = [],
  testResults = [],
  testSummary = { total: 0, passed: 0, failed: 0, passRate: 0 },
  isRunning = false,
  className,
  onClear,
  language = "python",
  userCodeLineCount,
}: CodeConsoleProps) {
  const consoleRef = useRef<HTMLDivElement>(null)
  const userScrolledUpRef = useRef(false)
  const prevOutputLengthRef = useRef(0)

  // Track if user has scrolled up (to disable auto-scroll)
  const handleScroll = () => {
    if (!consoleRef.current) return
    const { scrollTop, scrollHeight, clientHeight } = consoleRef.current
    // User is "at bottom" if within 50px of the bottom
    const isAtBottom = scrollHeight - scrollTop - clientHeight < 50
    userScrolledUpRef.current = !isAtBottom
  }

  // Auto-scroll to bottom only if user hasn't scrolled up
  // Also reset scroll tracking when new test run starts
  useEffect(() => {
    // Reset scroll state when a new test run starts (going from no results to running)
    if (isRunning && prevOutputLengthRef.current === 0) {
      userScrolledUpRef.current = false
    }
    prevOutputLengthRef.current = outputs.length + testResults.length

    // Only auto-scroll if user hasn't scrolled up to read errors
    if (consoleRef.current && !userScrolledUpRef.current) {
      consoleRef.current.scrollTop = consoleRef.current.scrollHeight
    }
  }, [outputs, testResults, isRunning])

  // Check for code errors
  const errorResults = testResults.filter((r) => r.error)
  const hasCodeError = errorResults.length > 0 && testSummary.passed === 0
  const firstError = errorResults[0]?.error || null
  const errorInfo = firstError ? formatErrorMessage(firstError, language, userCodeLineCount) : null

  const isEmpty = outputs.length === 0 && testResults.length === 0 && !isRunning

  return (
    <div
      className={cn(
        "flex flex-shrink-0 flex-col rounded border border-gray-700 bg-[#1e1e1e]",
        className
      )}
    >
      {/* Console Header */}
      <div className="flex flex-shrink-0 items-center justify-between border-b border-gray-700 bg-[#252526] px-3 py-1.5">
        <div className="flex items-center space-x-2">
          <Terminal className="h-3.5 w-3.5 text-gray-400" />
          <span className="text-xs font-medium text-gray-400">Console</span>
          {hasCodeError && (
            <Badge className="h-4 border-red-500/30 bg-red-500/20 px-1.5 text-[10px] text-red-400">
              Error
            </Badge>
          )}
        </div>
        <div className="flex items-center space-x-2">
          {testResults.length > 0 && !hasCodeError && (
            <Badge
              className={cn(
                "h-5 text-xs",
                testSummary.passRate === 100
                  ? "border-green-500/30 bg-green-500/20 text-green-400"
                  : testSummary.passRate >= 60
                    ? "border-yellow-500/30 bg-yellow-500/20 text-yellow-400"
                    : "border-red-500/30 bg-red-500/20 text-red-400"
              )}
            >
              {testSummary.passed}/{testSummary.total} tests
            </Badge>
          )}
          {isRunning && (
            <Badge className="h-5 animate-pulse border-blue-500/30 bg-blue-500/20 text-xs text-blue-400">
              Running...
            </Badge>
          )}
          {onClear && (outputs.length > 0 || testResults.length > 0) && (
            <Button
              variant="ghost"
              size="sm"
              className="h-5 w-5 p-0 text-gray-500 hover:text-gray-300"
              onClick={onClear}
            >
              <Trash2 className="h-3 w-3" />
            </Button>
          )}
        </div>
      </div>

      {/* Console Content */}
      <div
        ref={consoleRef}
        onScroll={handleScroll}
        className="max-h-[200px] min-h-[100px] flex-1 space-y-1 overflow-y-auto p-2 font-mono text-xs"
      >
        {/* Empty state */}
        {isEmpty && (
          <div className="flex items-center gap-2 py-2 text-gray-500">
            <span className="text-gray-600">{">"}</span>
            <span className="italic">Run your code to see output here...</span>
          </div>
        )}

        {/* Running state */}
        {isRunning && (
          <div className="flex items-center gap-2 text-blue-400">
            <span className="text-gray-600">{">"}</span>
            <span>Executing code</span>
            <span className="animate-pulse">...</span>
          </div>
        )}

        {/* Console.log outputs */}
        {outputs.map((output, index) => (
          <div
            key={`output-${output.type}-${index}`}
            className={cn(
              "flex items-start gap-2",
              output.type === "error" && "text-red-400",
              output.type === "warn" && "text-yellow-400",
              output.type === "info" && "text-blue-400",
              output.type === "log" && "text-gray-300",
              output.type === "result" && "text-green-400"
            )}
          >
            <span className="text-gray-600 select-none">{">"}</span>
            <span className="break-all whitespace-pre-wrap">{output.message}</span>
          </div>
        ))}

        {/* Test Results */}
        {testResults.length > 0 && !isRunning && (
          <>
            {/* Error banner for syntax/runtime errors */}
            {hasCodeError && errorInfo && (
              <div className="mb-2 rounded border border-red-500/30 bg-red-500/10 p-2">
                <div className="flex items-start gap-2 text-red-400">
                  <AlertCircle className="mt-0.5 h-4 w-4 flex-shrink-0" />
                  <div className="flex-1">
                    <div className="mb-1 font-semibold">{errorInfo.title}</div>
                    {errorInfo.hint && (
                      <div className="mb-2 text-[11px] text-yellow-300/80 italic">
                        💡 {errorInfo.hint}
                      </div>
                    )}
                    <div className="rounded bg-black/20 p-2 font-mono text-[11px] break-all whitespace-pre-wrap text-red-300/80">
                      {errorInfo.details}
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Test result header */}
            {!hasCodeError && (
              <div className="mb-1 border-t border-gray-700/50 pt-1 text-gray-500">
                Test Results:
              </div>
            )}

            {/* Individual test results */}
            {testResults.map((result, index) => (
              <div
                key={`test-${result.description?.slice(0, 20) ?? index}-${index}`}
                className="py-0.5"
              >
                <div
                  className={cn(
                    "flex items-center gap-2",
                    result.passed ? "text-green-400" : "text-red-400"
                  )}
                >
                  {result.passed ? (
                    <CheckCircle className="h-3 w-3 flex-shrink-0" />
                  ) : (
                    <XCircle className="h-3 w-3 flex-shrink-0" />
                  )}
                  <span className={result.passed ? "text-gray-300" : "text-gray-400"}>
                    {result.description}
                  </span>
                </div>

                {/* Show details for failed tests */}
                {!result.passed && (
                  <div className="mt-1 ml-5 space-y-0.5 text-[11px]">
                    {result.isHidden ? (
                      <div className="flex items-start gap-2">
                        <span className="text-gray-500 italic">
                          This test case is hidden. The implementation failed to meet the required
                          behavior.
                        </span>
                      </div>
                    ) : (
                      <>
                        {/* Always show input for debugging */}
                        {result.input && (
                          <div className="flex items-start gap-2">
                            <span className="w-14 text-gray-500">Input:</span>
                            <span className="break-all text-blue-300">
                              {JSON.stringify(result.input)}
                            </span>
                          </div>
                        )}
                        {/* Show expected/got for wrong output, show error for code errors */}
                        {result.error ? (
                          <div className="flex items-start gap-2">
                            <span className="w-14 text-gray-500">Error:</span>
                            <span className="break-all text-red-300">{result.error}</span>
                          </div>
                        ) : (
                          <>
                            <div className="flex items-start gap-2">
                              <span className="w-14 text-gray-500">Expected:</span>
                              <span className="break-all text-green-300">
                                {JSON.stringify(result.expected)}
                              </span>
                            </div>
                            <div className="flex items-start gap-2">
                              <span className="w-14 text-gray-500">Got:</span>
                              <span className="break-all text-red-300">
                                {JSON.stringify(result.actual)}
                              </span>
                            </div>
                          </>
                        )}
                      </>
                    )}
                  </div>
                )}
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  )
}

export default CodeConsole

"use client"

import React, { useState, useCallback, useMemo, useEffect } from "react"
import {
  Lightbulb,
  ChevronDown,
  ChevronUp,
  Sparkles,
  RefreshCw,
  AlertTriangle,
  TrendingUp,
  Clock,
  Filter,
} from "lucide-react"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { cn } from "@/lib/utils"
import { RAGHintCard } from "./RAGHintCard"
import type { GeneratedHint, HintLevel, HintCategory } from "@/lib/agents/hints"

/**
 * EnhancedHintsPanel - Progressive hints panel with RAG integration
 *
 * Design philosophy:
 * - Combines static hints with AI-generated RAG hints
 * - Progressive unlock based on time and struggle level
 * - Visual indicators for hint difficulty and personalization
 * - Encourages thinking before revealing hints
 */

interface EnhancedHintsPanelProps {
  // Static hints from scenario
  staticHints: string[]
  // RAG-generated hints
  ragHints: GeneratedHint[]
  // Time tracking
  elapsedMinutes: number
  // Struggle level for adaptive hints
  struggleLevel: "none" | "mild" | "moderate" | "high"
  // Recommended reveal level
  recommendedLevel: HintLevel
  // Whether personalization is applied
  isPersonalized: boolean
  // Callbacks
  onRevealHint?: (hintId: string, isRag: boolean) => void
  onRequestMoreHints?: () => void
  // Loading state
  isLoadingHints?: boolean
  // Error state
  hintsError?: string
  className?: string
}

type FilterCategory = "all" | HintCategory

/**
 * Convert static hint to GeneratedHint format
 */
function staticToGenerated(hint: string, index: number): GeneratedHint {
  return {
    id: `static_${index}`,
    level: Math.min(index + 1, 4) as HintLevel,
    category: index === 0 ? "conceptual" : index === 1 ? "approach" : "implementation",
    title: index === 0 ? "Getting Started" : index === 1 ? "Key Insight" : `Hint ${index + 1}`,
    content: hint,
    isBlurred: true,
    source: "pattern-knowledge",
    relevanceScore: 1 - index * 0.1,
  }
}

/**
 * Calculate unlock time for a hint level
 */
function getUnlockTime(level: HintLevel, struggleLevel: string): number {
  const baseTime = level * 3 // 3, 6, 9, 12 minutes

  // Reduce unlock time if struggling
  switch (struggleLevel) {
    case "high":
      return Math.max(1, baseTime - 4)
    case "moderate":
      return Math.max(2, baseTime - 2)
    case "mild":
      return Math.max(3, baseTime - 1)
    default:
      return baseTime
  }
}

export function EnhancedHintsPanel({
  staticHints,
  ragHints,
  elapsedMinutes,
  struggleLevel,
  recommendedLevel,
  isPersonalized,
  onRevealHint,
  onRequestMoreHints,
  isLoadingHints = false,
  hintsError,
  className,
}: EnhancedHintsPanelProps) {
  const [isExpanded, setIsExpanded] = useState(true)
  const [revealedHintIds, setRevealedHintIds] = useState<Set<string>>(new Set())
  const [filterCategory, setFilterCategory] = useState<FilterCategory>("all")

  // Convert static hints to GeneratedHint format
  const convertedStaticHints = useMemo(
    () => staticHints.map((hint, idx) => staticToGenerated(hint, idx)),
    [staticHints]
  )

  // Combine all hints
  const allHints = useMemo(() => {
    const combined = [...convertedStaticHints, ...ragHints]

    // Sort by level, then by relevance
    return combined.sort((a, b) => {
      if (a.level !== b.level) return a.level - b.level
      return b.relevanceScore - a.relevanceScore
    })
  }, [convertedStaticHints, ragHints])

  // Filter hints by category
  const filteredHints = useMemo(() => {
    if (filterCategory === "all") return allHints
    return allHints.filter((h) => h.category === filterCategory)
  }, [allHints, filterCategory])

  // Group hints by level
  const hintsByLevel = useMemo(() => {
    const grouped: Record<HintLevel, GeneratedHint[]> = {
      1: [],
      2: [],
      3: [],
      4: [],
    }

    for (const hint of filteredHints) {
      grouped[hint.level].push(hint)
    }

    return grouped
  }, [filteredHints])

  // Calculate which levels are unlocked
  const unlockedLevels = useMemo(() => {
    const levels: HintLevel[] = []
    for (let level = 1; level <= 4; level++) {
      const unlockTime = getUnlockTime(level as HintLevel, struggleLevel)
      if (elapsedMinutes >= unlockTime) {
        levels.push(level as HintLevel)
      }
    }
    return levels
  }, [elapsedMinutes, struggleLevel])

  // Handle hint reveal
  const handleReveal = useCallback(
    (hintId: string) => {
      setRevealedHintIds((prev) => new Set([...prev, hintId]))
      const isRag = !hintId.startsWith("static_")
      onRevealHint?.(hintId, isRag)
    },
    [onRevealHint]
  )

  // Get struggle level indicator
  const getStruggleBadge = () => {
    switch (struggleLevel) {
      case "high":
        return (
          <Badge className="border-red-500/30 bg-red-500/20 text-red-400">
            <AlertTriangle className="mr-1 h-3 w-3" />
            Need help?
          </Badge>
        )
      case "moderate":
        return (
          <Badge className="border-yellow-500/30 bg-yellow-500/20 text-yellow-400">
            <Clock className="mr-1 h-3 w-3" />
            Take your time
          </Badge>
        )
      case "mild":
        return (
          <Badge className="border-blue-500/30 bg-blue-500/20 text-blue-400">
            <TrendingUp className="mr-1 h-3 w-3" />
            On track
          </Badge>
        )
      default:
        return null
    }
  }

  // Categories for filter
  const categories: { value: FilterCategory; label: string }[] = [
    { value: "all", label: "All" },
    { value: "conceptual", label: "Conceptual" },
    { value: "approach", label: "Approach" },
    { value: "implementation", label: "Implementation" },
    { value: "debugging", label: "Debugging" },
  ]

  const totalHints = allHints.length
  const revealedCount = revealedHintIds.size
  const ragHintCount = ragHints.length

  if (totalHints === 0 && !isLoadingHints) {
    return null
  }

  return (
    <div className={cn("rounded-lg border border-gray-700 bg-gray-900/50", className)}>
      {/* Header */}
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        className="flex w-full items-center justify-between px-3 py-2 hover:bg-gray-800/30"
      >
        <div className="flex items-center gap-2">
          <Lightbulb className="h-4 w-4 text-yellow-500" />
          <span className="text-sm font-medium text-gray-300">Hints</span>
          <Badge className="border-yellow-500/30 bg-yellow-500/10 text-xs text-yellow-400">
            {revealedCount}/{totalHints}
          </Badge>
          {ragHintCount > 0 && (
            <Badge className="border-purple-500/30 bg-purple-500/10 text-xs text-purple-400">
              <Sparkles className="mr-1 h-3 w-3" />
              {ragHintCount} AI
            </Badge>
          )}
          {isPersonalized && (
            <Badge className="border-green-500/30 bg-green-500/10 text-xs text-green-400">
              Personalized
            </Badge>
          )}
        </div>
        <div className="flex items-center gap-2">
          {getStruggleBadge()}
          {isExpanded ? (
            <ChevronUp className="h-4 w-4 text-gray-500" />
          ) : (
            <ChevronDown className="h-4 w-4 text-gray-500" />
          )}
        </div>
      </button>

      {/* Content */}
      {isExpanded && (
        <div className="space-y-3 px-3 pb-3">
          {/* Category filter */}
          {totalHints > 3 && (
            <div className="flex items-center gap-2 pt-1">
              <Filter className="h-3 w-3 text-gray-500" />
              <div className="flex flex-wrap gap-1">
                {categories.map((cat) => (
                  <button
                    key={cat.value}
                    onClick={() => setFilterCategory(cat.value)}
                    className={cn(
                      "rounded px-2 py-0.5 text-xs transition-colors",
                      filterCategory === cat.value
                        ? "bg-gray-700 text-white"
                        : "bg-gray-800/50 text-gray-500 hover:text-gray-300"
                    )}
                  >
                    {cat.label}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Error state */}
          {hintsError && (
            <div className="rounded border border-red-500/30 bg-red-500/10 p-2 text-xs text-red-400">
              {hintsError}
            </div>
          )}

          {/* Loading state */}
          {isLoadingHints && (
            <div className="flex items-center gap-2 p-2 text-sm text-gray-500">
              <RefreshCw className="h-4 w-4 animate-spin" />
              <span>Generating personalized hints...</span>
            </div>
          )}

          {/* Hints by level */}
          {([1, 2, 3, 4] as HintLevel[]).map((level) => {
            const hints = hintsByLevel[level]
            if (hints.length === 0) return null

            const isUnlocked = unlockedLevels.includes(level)
            const unlockTime = getUnlockTime(level, struggleLevel)
            const isRecommended = level <= recommendedLevel

            return (
              <div key={level} className="space-y-2">
                {/* Level header */}
                <div className="flex items-center gap-2">
                  <span
                    className={cn(
                      "text-xs font-medium",
                      isRecommended ? "text-yellow-400" : "text-gray-500"
                    )}
                  >
                    Level {level}
                    {isRecommended && <span className="ml-1 text-yellow-500">(Recommended)</span>}
                  </span>
                  {!isUnlocked && (
                    <span className="text-[10px] text-gray-600">Unlocks at {unlockTime} min</span>
                  )}
                </div>

                {/* Hints */}
                <div className="space-y-2">
                  {hints.map((hint) => (
                    <RAGHintCard
                      key={hint.id}
                      hint={hint}
                      isLocked={!isUnlocked}
                      unlockTimeMinutes={unlockTime}
                      onReveal={handleReveal}
                    />
                  ))}
                </div>
              </div>
            )
          })}

          {/* Request more hints button */}
          {onRequestMoreHints && !isLoadingHints && (
            <Button
              variant="ghost"
              size="sm"
              onClick={onRequestMoreHints}
              className="w-full text-xs text-gray-500 hover:text-white"
            >
              <Sparkles className="mr-1 h-3 w-3" />
              Generate more hints
            </Button>
          )}

          {/* Progress indicator */}
          <div className="border-t border-gray-700 pt-2">
            <div className="flex items-center justify-between text-[10px] text-gray-500">
              <span>{elapsedMinutes} min elapsed</span>
              <span>
                Next level unlocks at{" "}
                {getUnlockTime(
                  Math.min(Math.max(...unlockedLevels, 0) + 1, 4) as HintLevel,
                  struggleLevel
                )}{" "}
                min
              </span>
            </div>
            <div className="mt-1 h-1 overflow-hidden rounded-full bg-gray-700">
              <div
                className="h-full rounded-full bg-gradient-to-r from-blue-500 via-yellow-500 to-red-500 transition-all duration-300"
                style={{
                  width: `${Math.min((elapsedMinutes / 12) * 100, 100)}%`,
                }}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

export default EnhancedHintsPanel

"use client"

import React, { useState, useCallback, useEffect } from "react"
import {
  Lightbulb,
  Lock,
  Eye,
  EyeOff,
  ChevronDown,
  ChevronUp,
  Sparkles,
  RefreshCw,
} from "lucide-react"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { cn } from "@/lib/utils"
import type { GeneratedHint, HintLevel } from "@/lib/agents/hints"

/**
 * HintsPanel - Progressive hint reveal system with RAG integration
 *
 * Design philosophy:
 * - Hints are revealed progressively based on time spent
 * - Earlier hints are more subtle, later hints more direct
 * - Encourages candidates to think before revealing
 * - Tracks which hints are revealed for scoring
 * - Integrates with RAG for personalized AI hints
 */

interface RAGHintData {
  level: number
  hint: string
  source: string
}

interface HintsPanelProps {
  hints: string[]
  revealedCount: number
  onRevealHint?: (hintIndex: number) => void
  className?: string
  elapsedMinutes?: number
  // RAG integration props
  ragHints?: RAGHintData[]
  isLoadingRagHints?: boolean
  onRequestRagHints?: () => void
  showRagHints?: boolean
}

export function HintsPanel({
  hints,
  revealedCount,
  onRevealHint,
  className,
  elapsedMinutes = 0,
  ragHints = [],
  isLoadingRagHints = false,
  onRequestRagHints,
  showRagHints = true,
}: HintsPanelProps) {
  const [isExpanded, setIsExpanded] = useState(true)
  const [visibleHints, setVisibleHints] = useState<Set<number>>(new Set())
  const [visibleRagHints, setVisibleRagHints] = useState<Set<number>>(new Set())

  const toggleHintVisibility = useCallback(
    (index: number) => {
      setVisibleHints((prev) => {
        const newVisible = new Set(prev)
        if (newVisible.has(index)) {
          newVisible.delete(index)
        } else {
          newVisible.add(index)
          onRevealHint?.(index)
        }
        return newVisible
      })
    },
    [onRevealHint]
  )

  const toggleRagHintVisibility = useCallback((index: number) => {
    setVisibleRagHints((prev) => {
      const newVisible = new Set(prev)
      if (newVisible.has(index)) {
        newVisible.delete(index)
      } else {
        newVisible.add(index)
      }
      return newVisible
    })
  }, [])

  const totalHints = hints.length + ragHints.length
  const totalRevealed = visibleHints.size + visibleRagHints.size

  if (hints.length === 0 && ragHints.length === 0 && !isLoadingRagHints) {
    return null
  }

  // Get color for RAG hint level
  const getRagLevelColor = (level: number) => {
    switch (level) {
      case 1:
        return "border-blue-500/20 bg-blue-500/5"
      case 2:
        return "border-yellow-500/20 bg-yellow-500/5"
      case 3:
        return "border-orange-500/20 bg-orange-500/5"
      default:
        return "border-purple-500/20 bg-purple-500/5"
    }
  }

  const getRagLevelBadge = (level: number) => {
    switch (level) {
      case 1:
        return { text: "Nudge", class: "bg-blue-500/20 text-blue-400 border-blue-500/30" }
      case 2:
        return { text: "Guide", class: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30" }
      case 3:
        return { text: "Explain", class: "bg-orange-500/20 text-orange-400 border-orange-500/30" }
      default:
        return { text: "AI", class: "bg-purple-500/20 text-purple-400 border-purple-500/30" }
    }
  }

  return (
    <div className={cn("rounded-lg border border-gray-700 bg-gray-900/50", className)}>
      {/* Header */}
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        className="flex w-full items-center justify-between px-3 py-2 hover:bg-gray-800/30"
      >
        <div className="flex items-center gap-2">
          <Lightbulb className="h-4 w-4 text-yellow-500" />
          <span className="text-sm font-medium text-gray-300">Hints</span>
          <Badge className="border-yellow-500/30 bg-yellow-500/10 text-xs text-yellow-400">
            {totalRevealed}/{totalHints}
          </Badge>
          {ragHints.length > 0 && (
            <Badge className="border-purple-500/30 bg-purple-500/10 text-xs text-purple-400">
              <Sparkles className="mr-1 h-3 w-3" />
              {ragHints.length} AI
            </Badge>
          )}
        </div>
        {isExpanded ? (
          <ChevronUp className="h-4 w-4 text-gray-500" />
        ) : (
          <ChevronDown className="h-4 w-4 text-gray-500" />
        )}
      </button>

      {/* Hints list */}
      {isExpanded && (
        <div className="space-y-2 px-3 pb-3">
          {/* Static hints */}
          {hints.map((hint, index) => {
            const isRevealed = index < revealedCount
            const isVisible = visibleHints.has(index)

            return (
              <div
                key={`static-${index}`}
                className={cn(
                  "rounded-lg border transition-colors",
                  isRevealed
                    ? "border-yellow-500/20 bg-yellow-500/5"
                    : "border-gray-700 bg-gray-800/30 opacity-50"
                )}
              >
                <div className="flex items-start justify-between p-2">
                  <div className="flex flex-1 items-start gap-2">
                    <span className="mt-0.5 text-xs font-medium text-yellow-500">{index + 1}.</span>
                    <div className="flex-1">
                      {isRevealed ? (
                        <>
                          {isVisible ? (
                            <p className="text-xs leading-relaxed text-gray-300">{hint}</p>
                          ) : (
                            <button
                              onClick={() => toggleHintVisibility(index)}
                              className="group w-full text-left"
                            >
                              <div className="relative">
                                <p className="text-xs text-gray-400 blur-sm select-none">
                                  {hint.substring(0, 50)}...
                                </p>
                                <div className="absolute inset-0 flex items-center justify-center">
                                  <span className="flex items-center gap-1 text-xs text-gray-500 group-hover:text-gray-300">
                                    <Eye className="h-3 w-3" />
                                    Click to reveal
                                  </span>
                                </div>
                              </div>
                            </button>
                          )}
                        </>
                      ) : (
                        <div className="flex items-center gap-1 text-xs text-gray-500">
                          <Lock className="h-3 w-3" />
                          <span>Unlocks after {(index + 1) * 3} minutes</span>
                        </div>
                      )}
                    </div>
                  </div>
                  {isRevealed && isVisible && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => toggleHintVisibility(index)}
                      className="h-6 w-6 p-0 text-gray-400 hover:text-white"
                    >
                      <EyeOff className="h-3 w-3" />
                    </Button>
                  )}
                </div>
              </div>
            )
          })}

          {/* RAG hints section */}
          {showRagHints && ragHints.length > 0 && (
            <>
              <div className="flex items-center gap-2 pt-2">
                <Sparkles className="h-3 w-3 text-purple-400" />
                <span className="text-xs font-medium text-purple-400">AI-Generated Hints</span>
              </div>
              {ragHints.map((ragHint, index) => {
                const isVisible = visibleRagHints.has(index)
                const levelBadge = getRagLevelBadge(ragHint.level)

                return (
                  <div
                    key={`rag-${index}`}
                    className={cn(
                      "rounded-lg border transition-colors",
                      getRagLevelColor(ragHint.level)
                    )}
                  >
                    <div className="flex items-start justify-between p-2">
                      <div className="flex flex-1 items-start gap-2">
                        <Badge className={cn("px-1 py-0 text-[10px]", levelBadge.class)}>
                          {levelBadge.text}
                        </Badge>
                        <div className="flex-1">
                          {isVisible ? (
                            <p className="text-xs leading-relaxed text-gray-300">{ragHint.hint}</p>
                          ) : (
                            <button
                              onClick={() => toggleRagHintVisibility(index)}
                              className="group w-full text-left"
                            >
                              <div className="relative">
                                <p className="text-xs text-gray-400 blur-sm select-none">
                                  {ragHint.hint.substring(0, 50)}...
                                </p>
                                <div className="absolute inset-0 flex items-center justify-center">
                                  <span className="flex items-center gap-1 text-xs text-gray-500 group-hover:text-gray-300">
                                    <Eye className="h-3 w-3" />
                                    Click to reveal
                                  </span>
                                </div>
                              </div>
                            </button>
                          )}
                        </div>
                      </div>
                      {isVisible && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => toggleRagHintVisibility(index)}
                          className="h-6 w-6 p-0 text-gray-400 hover:text-white"
                        >
                          <EyeOff className="h-3 w-3" />
                        </Button>
                      )}
                    </div>
                  </div>
                )
              })}
            </>
          )}

          {/* Loading state for RAG hints */}
          {isLoadingRagHints && (
            <div className="flex items-center gap-2 p-2 text-xs text-gray-500">
              <RefreshCw className="h-3 w-3 animate-spin" />
              <span>Generating personalized hints...</span>
            </div>
          )}

          {/* Request more hints button */}
          {onRequestRagHints && !isLoadingRagHints && (
            <Button
              variant="ghost"
              size="sm"
              onClick={onRequestRagHints}
              className="mt-2 w-full text-xs text-gray-500 hover:text-white"
            >
              <Sparkles className="mr-1 h-3 w-3" />
              Get AI hints
            </Button>
          )}

          {/* Progress indicator */}
          {revealedCount < hints.length && (
            <div className="pt-1 text-center">
              <p className="text-[10px] text-gray-500">
                Next hint unlocks at {(revealedCount + 1) * 3} minutes
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

