// Get icon based on scenario type
function getTypeIcon(type: string) {
  switch (type) {
    case 'dsa':
      return <Code className="h-4 w-4" />;
    case 'bugfix':
      return <Bug className="h-4 w-4" />;
    case 'system-design':
      return <Layers className="h-4 w-4" />;
    default:
      return <Code className="h-4 w-4" />;
  }
}

