              className="mb-2 flex w-full items-center justify-between font-semibold text-white transition-colors hover:text-[#00d9ff]"
            >
              <span className="flex items-center gap-1.5 text-xs">
                <BookOpen className="h-3 w-3 text-[#00d9ff]" />
                Pattern Analysis
                <Badge className="border-[#00d9ff]/50 bg-[#00d9ff]/20 px-1.5 text-[10px] text-[#00d9ff]">
                  {patternMetadata.name}
                </Badge>
              </span>
              {showAnalysis ? (
                <ChevronUp className="h-4 w-4 text-gray-400" />
              ) : (
                <ChevronDown className="h-4 w-4 text-gray-400" />
              )}
            </button>

            {showAnalysis && (
              <div className="animate-in slide-in-from-top-2 space-y-3 duration-200">
                {/* Pattern Description */}
                <div className="rounded-lg border border-[#00d9ff]/30 bg-[#00d9ff]/10 p-2">
                  <p className="text-xs leading-relaxed text-gray-300">
                    {patternMetadata.description}
                  </p>
                </div>

                {/* Key Techniques */}
                <div>
                  <h4 className="mb-1.5 flex items-center gap-1 text-xs font-medium text-gray-400">
                    <Zap className="h-3 w-3 text-yellow-400" />
                    Key Techniques to Consider
                  </h4>
                  <div className="flex flex-wrap gap-1">
                    {patternMetadata.keyTechniques.map((tech, i) => (
                      <Badge
                        key={i}
                        variant="outline"
                        className="border-yellow-500/30 bg-yellow-500/10 text-xs text-yellow-300"
                      >
                        {tech}
                      </Badge>
                    ))}
                  </div>
                </div>

                {/* Expected Complexity */}
                <div className="grid grid-cols-2 gap-2">
                  <div className="rounded border border-green-500/20 bg-green-500/10 p-2">
                    <h4 className="mb-1 flex items-center gap-1 text-xs font-medium text-gray-400">
                      <Clock className="h-3 w-3 text-green-400" />
                      Time Complexity
                    </h4>
                    <div className="space-y-0.5">
                      {patternMetadata.timeComplexityHints.map((hint, i) => (
                        <p key={i} className="text-xs text-green-300">
                          {hint}
                        </p>
                      ))}
                    </div>
                  </div>
                  <div className="rounded border border-blue-500/20 bg-blue-500/10 p-2">
                    <h4 className="mb-1 flex items-center gap-1 text-xs font-medium text-gray-400">
                      <HardDrive className="h-3 w-3 text-blue-400" />
                      Space Complexity
                    </h4>
                    <div className="space-y-0.5">
                      {patternMetadata.spaceComplexityHints.map((hint, i) => (
                        <p key={i} className="text-xs text-blue-300">
                          {hint}
                        </p>
                      ))}
                    </div>
                  </div>
                </div>

                {/* Common Questions for this Pattern */}
                {patternMetadata.commonQuestions && patternMetadata.commonQuestions.length > 0 && (
                  <div className="rounded-lg border border-purple-500/20 bg-purple-500/10 p-2">
                    <h4 className="mb-1.5 text-xs font-medium text-purple-300">
                      Similar Problems to Practice
                    </h4>
                    <div className="flex flex-wrap gap-1">
                      {patternMetadata.commonQuestions.slice(0, 4).map((q, i) => (
                        <span
                          key={i}
                          className="rounded bg-gray-800/50 px-1.5 py-0.5 text-xs text-gray-300"
                        >
                          {q}
                        </span>
                      ))}
                    </div>
                  </div>
                )}

                {/* What to Expect from Interviewer */}
                <div className="rounded-lg border border-orange-500/30 bg-orange-500/10 p-2">
                  <h4 className="mb-1.5 flex items-center gap-1 text-xs font-medium text-orange-300">
                    <AlertCircle className="h-3 w-3" />
                    Expect These Follow-up Questions
                  </h4>
                  <ul className="space-y-1">
                    {patternMetadata.interviewerFollowUps.map((q, i) => (
                      <li key={i} className="flex items-start gap-1.5 text-xs text-gray-300">
                        <span className="flex-shrink-0 text-orange-400">{i + 1}.</span>
                        {q}
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Hints Section */}
        {isInterviewStarted && hints.length > 0 && (
          <div className="mt-3 border-t border-gray-700 pt-3">
            <div className="mb-2 flex items-center justify-between">
              <h3 className="flex items-center space-x-1 text-xs font-semibold text-white">
                <Lightbulb className="h-3 w-3 text-yellow-400" />
                <span>
                  Hints ({revealedHints}/{hints.length})
                </span>
              </h3>
              {revealedHints < hints.length && (
                <span className="text-xs text-gray-400">
                  Next in {Math.ceil((180 - (elapsedTime % 180)) / 60)}m
                </span>
              )}
            </div>
            {revealedHints > 0 ? (
              <div className="space-y-2">
                {hints.slice(0, revealedHints).map((hint: string, i: number) => (
                  <div key={i} className="rounded border border-yellow-500/20 bg-yellow-500/10 p-2">
                    <p className="text-xs leading-relaxed text-yellow-200">
                      <span className="font-semibold">Hint {i + 1}:</span> {hint}
                    </p>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-xs text-gray-400 italic">
                Hints will unlock every 3 minutes as you work on the problem
              </p>
            )}
          </div>
        )}

        {/* Workspace Files Section - Only show for non-DSA scenarios */}
        {scenario.type !== "dsa" && (
          <div className="mt-3 border-t border-gray-700 pt-3">
            <h3 className="mb-2 font-semibold text-white">Workspace Files</h3>
            {scenario.type === "bugfix" && workspaceContext.length > 0 ? (
              <div className="mb-2">
                <p className="mb-2 text-xs text-blue-400">
                  <Code className="mr-1 mb-0.5 inline-block h-3 w-3" />
                  Your codebase files are available as tabs in the code editor.
                </p>
              </div>
            ) : (
              <>
                <input
                  ref={fileInputRef}
                  type="file"
                  multiple
                  accept=".js,.ts,.jsx,.tsx,.py,.java,.cpp,.c,.h,.json,.md,.txt,text/*"
                  onChange={handleFileUpload}
                  className="hidden"
                  aria-label="Upload workspace files"
                  id="workspace-file-upload"
                />
                <Button
                  onClick={() => fileInputRef.current?.click()}
                  variant="outline"
                  className="h-7 w-full border-gray-600 bg-transparent text-xs text-gray-300 hover:bg-gray-800"
                  aria-label="Upload code files to workspace"
                >
                  <Code className="mr-1 h-3 w-3" aria-hidden="true" />
                  Upload Files
                </Button>
                {workspaceContext.length > 0 && (
                  <div className="mt-2 space-y-1">
                    {workspaceContext.map((file, idx) => (
                      <button
                        key={idx}
                        onClick={() => onFileSelect(file)}
                        className="w-full cursor-pointer rounded bg-gray-800/30 px-2 py-1 text-left text-xs text-gray-400 transition-colors hover:bg-gray-700/30 hover:text-blue-400"
                      >
                        <div className="flex items-center gap-1 truncate">
                          <Code className="h-3 w-3 flex-shrink-0" />
                          {file.path}
                        </div>
                      </button>
                    ))}
                  </div>
                )}
              </>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

/**
 * RoadmapModal Component
 *
 * Modal showing detailed problem list for a selected DSA pattern node
 * Includes pattern metadata, difficulty distribution, and actionable problem list
 */

import { Play, Check, ChevronUp, ChevronDown } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Progress } from "@/components/ui/progress"
import { PATTERN_ROADMAP, PATTERN_METADATA } from "@/lib/types/dsa-patterns"
import type { Scenario } from "@/lib/scenarios"
import type { NodeStats } from "@/lib/hooks/useDSARoadmap"
import { NODE_POSITIONS } from "./RoadmapNode"

// Keep tier labels for modal only (progressive disclosure)
const TIER_LABELS: Record<number, string> = {
  1: "Foundation",
  2: "Core",
  3: "Advanced",
  4: "Expert",
}

interface RoadmapModalProps {
  expandedNode: string | null
  nodeStats: Record<string, NodeStats>
  completedProblems: string[]
  onClose: () => void
  onStartInterview: (scenario: Scenario) => void
  getPatternPrerequisites: (nodeId: string) => Array<{ id: string; name: string }>
}

export function RoadmapModal({
  expandedNode,
  nodeStats,
  completedProblems,
  onClose,
  onStartInterview,
  getPatternPrerequisites,
}: RoadmapModalProps) {
  if (!expandedNode) return null

  const node = PATTERN_ROADMAP.find(n => n.id === expandedNode)
  const stats = nodeStats[expandedNode]
  const prerequisites = getPatternPrerequisites(expandedNode)
  const pos = NODE_POSITIONS[expandedNode]
  const tierLabel = TIER_LABELS[pos?.tier || 1]

  // Get pattern metadata for display
  const firstPattern = node?.patterns[0]
  const metadata = firstPattern ? PATTERN_METADATA[firstPattern] : null

  if (!node || !stats) return null

  // Calculate difficulty distribution for this pattern
  const difficultyCount = {
    easy: stats.scenarios.filter(s => s.difficulty === 'easy').length,
    medium: stats.scenarios.filter(s => s.difficulty === 'medium').length,
    hard: stats.scenarios.filter(s => s.difficulty === 'hard').length,
  }

  return (
    <div
      className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4"
      onClick={onClose}
    >
      <div
        className="bg-zinc-900 border border-zinc-700 rounded-xl max-w-2xl w-full max-h-[80vh] overflow-hidden shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Cleaner Header */}
        <div className="p-4 border-b border-zinc-800">
          <div className="flex items-start justify-between">
            <div>
              <div className="flex items-center gap-2 mb-1">
                <h2 className="text-lg font-semibold text-white">{node.name}</h2>
                {stats.isComplete && (
                  <span className="bg-emerald-500 rounded-full p-0.5">
                    <Check className="h-3 w-3 text-black" />
                  </span>
                )}
              </div>
              <p className="text-zinc-400 text-sm">{node.description}</p>

              {/* Tier + Difficulty info (moved here from cards) */}
              <div className="flex items-center gap-3 mt-3">
                <span className="text-xs text-zinc-500 bg-zinc-800 px-2 py-0.5 rounded">
                  {tierLabel}
                </span>
                <div className="flex items-center gap-1.5 text-xs">
                  {difficultyCount.easy > 0 && (
                    <span className="text-emerald-400">{difficultyCount.easy} easy</span>
                  )}
                  {difficultyCount.medium > 0 && (
                    <span className="text-amber-400">{difficultyCount.medium} medium</span>
                  )}
                  {difficultyCount.hard > 0 && (
                    <span className="text-rose-400">{difficultyCount.hard} hard</span>
                  )}
                </div>
              </div>
            </div>
            <button
              onClick={onClose}
              className="text-zinc-500 hover:text-white p-1 -mr-1 -mt-1"
            >
              <ChevronUp className="h-5 w-5" />
            </button>
          </div>

          {/* Progress bar */}
          <div className="mt-3 flex items-center gap-3">
            <Progress value={stats.progress} className="flex-1 h-1.5 bg-zinc-800" />
            <span className="text-xs text-zinc-400">{stats.completed}/{stats.total}</span>
          </div>

          {/* Prerequisites - only show if not all complete */}
          {prerequisites.length > 0 && !prerequisites.every(p => nodeStats[p.id]?.isComplete) && (
            <div className="mt-3 flex items-center gap-2 text-xs">
              <span className="text-zinc-500">Requires:</span>
              {prerequisites.map(p => (
                <span
                  key={p.id}
                  className={`px-1.5 py-0.5 rounded ${
                    nodeStats[p.id]?.isComplete
                      ? 'bg-emerald-500/20 text-emerald-400'
                      : 'bg-zinc-800 text-zinc-400'
                  }`}
                >
                  {p.name}
                </span>
              ))}
            </div>
          )}
        </div>

        {/* Pattern Tips - Collapsed by default, expandable */}
        {metadata && (
          <details className="border-b border-zinc-800 group">
            <summary className="p-3 cursor-pointer text-xs text-zinc-500 hover:text-zinc-300 flex items-center gap-2 select-none">
              <ChevronDown className="h-3 w-3 transition-transform group-open:rotate-180" />
              Pattern tips & common questions
            </summary>
            <div className="px-3 pb-3 space-y-2">
              {/* Key techniques as simple tags */}
              <div className="flex flex-wrap gap-1">
                {metadata.keyTechniques.slice(0, 4).map((tech, i) => (
                  <span key={i} className="text-xs bg-zinc-800 text-zinc-400 px-2 py-0.5 rounded">
                    {tech}
                  </span>
                ))}
              </div>
              {/* One complexity hint */}
              {metadata.timeComplexityHints[0] && (
                <p className="text-xs text-zinc-500">{metadata.timeComplexityHints[0]}</p>
              )}
            </div>
          </details>
        )}

        {/* Problems List - Simplified */}
        <div className="p-3 overflow-y-auto" style={{ maxHeight: '50vh' }}>
          <div className="space-y-1.5">
            {stats.scenarios
              .sort((a, b) => {
                const order = { easy: 0, medium: 1, hard: 2 }
                return order[a.difficulty] - order[b.difficulty]
              })
              .map((scenario) => {
                const isCompleted = completedProblems.includes(scenario.id)
                const diffColor = {
                  easy: 'text-emerald-400',
                  medium: 'text-amber-400',
                  hard: 'text-rose-400'
                }[scenario.difficulty]

                return (
                  <div
                    key={scenario.id}
                    className={`flex items-center justify-between p-2.5 rounded-lg bg-zinc-800/50 hover:bg-zinc-800 transition-colors group ${
                      isCompleted ? 'opacity-60' : ''
                    }`}
                  >
                    <div className="flex items-center gap-2.5 flex-1 min-w-0">
                      {isCompleted ? (
                        <Check className="h-4 w-4 text-emerald-500 flex-shrink-0" />
                      ) : (
                        <Play className="h-4 w-4 text-zinc-500 flex-shrink-0" />
                      )}
                      <div className="min-w-0 flex-1">
                        <p className={`text-sm truncate ${isCompleted ? 'text-zinc-500' : 'text-white'}`}>
                          {scenario.title}
                        </p>
                        <div className="flex items-center gap-2 text-xs text-zinc-500">
                          <span className={diffColor}>{scenario.difficulty}</span>
                          <span>·</span>
                          <span>{scenario.estimatedTime}m</span>
                        </div>
                      </div>
                    </div>
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => {
                        onClose()
                        onStartInterview(scenario)
                      }}
                      className="opacity-0 group-hover:opacity-100 transition-opacity h-7 px-2 text-xs"
                    >
                      {isCompleted ? 'Redo' : 'Start'}
                    </Button>
                  </div>
                )
              })}
          </div>
        </div>
      </div>
    </div>
  )
}

/**
 * RoadmapNode Component
 *
 * Renders an individual DSA pattern node in the skill tree with:
 * - Progress visualization
 * - Lock/unlock states
 * - Mastery indicators
 * - Prerequisite tooltips
 */

import { Lock, Check } from "lucide-react"
import { Card, CardContent } from "@/components/ui/card"
import { Progress } from "@/components/ui/progress"
import type { PatternNode } from "@/lib/types/dsa-patterns"
import type { NodeStats } from "@/lib/hooks/useDSARoadmap"

// Node positions for the tree layout - organized as a proper skill tree
export const NODE_POSITIONS: Record<string, { x: number; y: number; tier: number }> = {
  // Tier 1 - Foundation (top center)
  'arrays-hashing': { x: 50, y: 5, tier: 1 },

  // Tier 2 - Core (branches from foundation)
  'two-pointers': { x: 20, y: 18, tier: 2 },
  'stack': { x: 40, y: 18, tier: 2 },
  'binary-search': { x: 60, y: 18, tier: 2 },
  'sliding-window': { x: 10, y: 30, tier: 2 },
  'linked-list': { x: 30, y: 30, tier: 2 },

  // Tier 3 - Advanced (deeper branches)
  'trees': { x: 35, y: 42, tier: 3 },
  'heap': { x: 65, y: 42, tier: 3 },
  'trie': { x: 20, y: 54, tier: 3 },
  'backtracking': { x: 45, y: 54, tier: 3 },
  'graphs': { x: 70, y: 54, tier: 3 },

  // Tier 4 - Expert (specialized branches)
  'dp-1d': { x: 35, y: 66, tier: 4 },
  'dp-2d': { x: 25, y: 78, tier: 4 },
  'dp-tree': { x: 45, y: 78, tier: 4 },
  'greedy': { x: 55, y: 66, tier: 4 },
  'intervals': { x: 65, y: 78, tier: 4 },
  'bit-manipulation': { x: 80, y: 30, tier: 4 },
  'math-geometry': { x: 90, y: 18, tier: 4 },
  'matrix': { x: 15, y: 90, tier: 4 },
}

// Simplified: single style for unlocked nodes (reduces cognitive load from 4 tier colors to 1)
const NODE_STYLE = {
  unlocked: { bg: "from-zinc-700/50 to-zinc-800/50", border: "border-zinc-600", text: "text-white", glow: "shadow-zinc-500/10" },
  locked: { bg: "bg-zinc-900/50", border: "border-zinc-800", text: "text-zinc-500" },
  mastered: { bg: "from-emerald-900/30 to-emerald-950/30", border: "border-emerald-500/50", text: "text-emerald-400", glow: "shadow-emerald-500/20" },
}

interface RoadmapNodeProps {
  node: PatternNode
  stats: NodeStats
  isUnlocked: boolean
  isHovered: boolean
  isExpanded: boolean
  prerequisites: Array<{ id: string; name: string }>
  nodeStats: Record<string, NodeStats>
  onNodeClick: () => void
  onMouseEnter: () => void
  onMouseLeave: () => void
}

// Simplified: only 3 states instead of 4 tier colors + 3 states
function getNodeStyle(isUnlocked: boolean, isMastered: boolean) {
  if (isMastered) return NODE_STYLE.mastered
  if (isUnlocked) return NODE_STYLE.unlocked
  return NODE_STYLE.locked
}

export function RoadmapNode({
  node,
  stats,
  isUnlocked,
  isHovered,
  isExpanded,
  prerequisites,
  nodeStats,
  onNodeClick,
  onMouseEnter,
  onMouseLeave,
}: RoadmapNodeProps) {
  const pos = NODE_POSITIONS[node.id]
  if (!pos) return null

  const isMastered = stats?.isComplete
  const style = getNodeStyle(isUnlocked, isMastered)

  return (
    <div
      className="absolute transform -translate-x-1/2 -translate-y-1/2 z-10"
      style={{
        left: `${pos.x}%`,
        top: `${pos.y}%`,
      }}
    >
      {/* Simplified Node Card */}
      <div
        onClick={onNodeClick}
        onMouseEnter={onMouseEnter}
        onMouseLeave={onMouseLeave}
        className={`
          relative transition-all duration-200 cursor-pointer
          ${isHovered && isUnlocked ? 'scale-105 z-20' : 'z-10'}
          ${!isUnlocked ? 'opacity-40 cursor-not-allowed' : ''}
        `}
      >
        <Card
          className={`
            relative overflow-hidden w-32 transition-all duration-200
            bg-gradient-to-br ${style.bg} ${style.border} border
            ${isUnlocked && !isMastered ? 'hover:border-zinc-500' : ''}
            ${isMastered ? 'ring-1 ring-emerald-500/40' : ''}
          `}
        >
          {/* Mastered checkmark */}
          {isMastered && (
            <div className="absolute -top-1 -right-1 bg-emerald-500 rounded-full p-0.5">
              <Check className="h-2.5 w-2.5 text-black" />
            </div>
          )}

          {/* Lock icon for locked nodes */}
          {!isUnlocked && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/50 rounded-lg z-20">
              <Lock className="h-4 w-4 text-zinc-600" />
            </div>
          )}

          <CardContent className="p-2.5">
            {/* Node name - larger, clearer */}
            <h3 className={`font-medium text-sm leading-tight mb-2 ${style.text}`}>
              {node.name}
            </h3>

            {/* Simple progress: just the count */}
            <div className="flex items-center justify-between text-xs text-zinc-400 mb-1">
              <span>{stats?.completed || 0}/{stats?.total || 0}</span>
            </div>
            <Progress
              value={stats?.progress || 0}
              className="h-1 bg-zinc-800"
            />
          </CardContent>
        </Card>

        {/* Prerequisites tooltip - only on hover for locked nodes */}
        {isHovered && !isUnlocked && prerequisites.length > 0 && (
          <div className="absolute left-1/2 transform -translate-x-1/2 top-full mt-1.5 z-50 w-40">
            <div className="bg-zinc-800 border border-zinc-700 rounded-lg p-2 shadow-xl text-xs">
              <div className="text-zinc-400 mb-1">Complete first:</div>
              <div className="flex flex-wrap gap-1">
                {prerequisites.map(p => (
                  <span
                    key={p.id}
                    className={`text-xs px-1.5 py-0.5 rounded ${
                      nodeStats[p.id]?.isComplete
                        ? 'bg-emerald-500/20 text-emerald-400'
                        : 'bg-zinc-700 text-zinc-400'
                    }`}
                  >
                    {p.name}
                  </span>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

"use client"

import { memo } from "react"
import Link from "next/link"
import { Play, Check, Clock, Cpu, Bug, Wrench, Zap, Shield, Layers } from "lucide-react"
import { Button } from "@/components/ui/button"
import type { Scenario, ScenarioType, DifficultyLevel } from "@/lib/scenarios"
import type { UsageLimit } from "@/lib/stores"

interface ScenarioCardProps {
  scenario: Scenario
  isSelected: boolean
  isCompleted: boolean
  usageLimit: UsageLimit | null
  onSelect: (scenario: Scenario) => void
  onStart: (scenario: Scenario) => void
}

// Exercise type quick filters with descriptions
const EXERCISE_TYPES = [
  {
    id: "bugfix",
    label: "Bug Fix",
    icon: Bug,
  },
  {
    id: "add-functionality",
    label: "Add Feature",
    icon: Wrench,
  },
  {
    id: "optimization",
    label: "Optimize",
    icon: Zap,
  },
  {
    id: "security",
    label: "Security",
    icon: Shield,
  },
  {
    id: "system-design",
    label: "System Design",
    icon: Layers,
  },
  {
    id: "dsa",
    label: "DSA Drill",
    icon: Cpu,
  },
] as const

const getDifficultyStyle = (difficulty: DifficultyLevel) => {
  switch (difficulty) {
    case "easy":
      return "border-transparent bg-emerald-500/10 text-emerald-300"
    case "medium":
      return "border-transparent bg-amber-500/10 text-amber-200"
    case "hard":
      return "border-transparent bg-rose-500/10 text-rose-300"
    default:
      return "border-transparent bg-white/5 text-zinc-300"
  }
}

const getTypeConfig = (type: ScenarioType) => {
  const config = EXERCISE_TYPES.find((t) => t.id === type)
  return config || EXERCISE_TYPES[0]
}

export const ScenarioCard = memo(function ScenarioCard({
  scenario,
  isSelected,
  isCompleted,
  usageLimit,
  onSelect,
  onStart,
}: ScenarioCardProps) {
  const typeConfig = getTypeConfig(scenario.type)

  return (
    <div
      onClick={() => onSelect(scenario)}
      className={`group relative cursor-pointer overflow-hidden rounded-2xl border bg-white/[0.03] p-5 shadow-[inset_0_1px_0_rgba(255,255,255,0.05)] backdrop-blur-xl transition-all duration-300 ${
        isSelected
          ? "border-white/25 bg-white/[0.06] shadow-[0_20px_50px_rgba(0,0,0,0.4)]"
