                {pattern.tips.slice(0, 3).map((tip, i) => (
                  <li key={i} className="text-muted-foreground flex items-start gap-1 text-[10px]">
                    <Lightbulb className="mt-0.5 h-2.5 w-2.5 shrink-0 text-yellow-500" />
                    {tip}
