/**
 * Collapsible Card Component
 */
function CollapsibleCard({
  title,
  icon: Icon,
  iconColor,
  badge,
  expanded,
  onToggle,
  children,
}: {
  title: string
  icon: typeof Target
  iconColor: string
  badge?: string
  expanded: boolean
  onToggle: () => void
  children: React.ReactNode
}) {
  return (
    <div className="bg-card border-border overflow-hidden rounded-xl border">
      <button
        onClick={onToggle}
        className="hover:bg-muted/50 flex w-full items-center justify-between px-4 py-3 transition-colors"
      >
        <div className="flex items-center gap-2">
          <Icon className={cn("h-4 w-4", iconColor)} />
          <span className="text-foreground text-sm font-medium">{title}</span>
          {badge && (
            <span className="bg-primary/10 text-primary rounded-full px-1.5 py-0.5 text-[10px]">
              {badge}
            </span>
          )}
        </div>
        {expanded ? (
          <ChevronUp className="text-muted-foreground h-4 w-4" />
        ) : (
          <ChevronDown className="text-muted-foreground h-4 w-4" />
        )}
      </button>

      <AnimatePresence>
        {expanded && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2 }}
            className="overflow-hidden"
          >
            <div className="border-border border-t px-4 pt-3 pb-4">{children}</div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

/**
 * Helper Components
 */
function StatBox({ label, value, color }: { label: string; value: number; color?: string }) {
  return (
    <div className="bg-muted/50 rounded-lg p-2 text-center">
      <div className={cn("text-lg font-bold", color || "text-foreground")}>{value}</div>
      <div className="text-muted-foreground text-[10px]">{label}</div>
    </div>
  )
}

function PriorityBar({
  label,
  count,
  total,
  color,
}: {
  label: string
  count: number
  total: number
  color: string
}) {
  const percentage = total > 0 ? (count / total) * 100 : 0

  return (
    <div className="flex-1">
      <div
        className={cn("h-2 rounded-full", color)}
        style={{ width: `${Math.max(percentage, 5)}%` }}
      />
      <p className="text-muted-foreground mt-1 text-center text-[9px]">
        {count} {label}
      </p>
    </div>
  )
}

