                      </span>
                    ))}
                    {roadmap.patternCoverage.length > 6 && (
                      <span className="bg-muted text-muted-foreground rounded-full px-2 py-0.5 text-[10px]">
                        +{roadmap.patternCoverage.length - 6} more
                      </span>
