/**
 * Generate cache key for admin endpoints
 */
export function getCacheKey(endpoint: string, params: Record<string, string | undefined>): string {
  const sortedParams = Object.entries(params)
    .filter(([, v]) => v !== undefined)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([k, v]) => `${k}=${v}`)
    .join('&')

  return `admin:${endpoint}:${sortedParams}`
}

/**
 * Admin API Middleware
 *
 * Reusable middleware for admin API routes.
 * Handles authentication, authorization, and common patterns.
 */

import { NextRequest, NextResponse } from 'next/server'
import { getAdminRole, hasPermission, getUserPermissions, verifyToken, type AdminRole, type Permission } from './rbac'

export interface AdminContext {
  userId: string
  email?: string
  role: AdminRole
  permissions: Permission[]
}

export interface AuthResult {
  authorized: boolean
  context?: AdminContext
  error?: string
  status?: number
}

/**
 * Verify admin access for an API route
 * Returns admin context if authorized, error response if not
 */
export async function verifyAdminAccess(request: NextRequest): Promise<AuthResult> {
  // Extract bearer token
  const authHeader = request.headers.get('authorization')
  if (!authHeader?.startsWith('Bearer ')) {
    return {
      authorized: false,
      error: 'Missing authorization header',
      status: 401,
    }
  }

  const token = authHeader.replace('Bearer ', '')

  // Verify token
  const tokenResult = await verifyToken(token)
  if (!tokenResult.valid || !tokenResult.userId) {
    return {
      authorized: false,
      error: tokenResult.error || 'Invalid token',
      status: 401,
    }
  }

  // Check admin role
  const role = await getAdminRole(tokenResult.userId)
  if (!role) {
    return {
      authorized: false,
      error: 'Access denied - not an admin',
      status: 403,
    }
  }

  // Get permissions
  const permissions = await getUserPermissions(tokenResult.userId)

  return {
    authorized: true,
    context: {
      userId: tokenResult.userId,
      email: tokenResult.email,
      role,
      permissions,
    },
  }
}

/**
 * Require specific permission for an API route
 */
export async function requirePermission(
  request: NextRequest,
  permission: Permission
): Promise<AuthResult> {
  const authResult = await verifyAdminAccess(request)

  if (!authResult.authorized) {
    return authResult
  }

  const hasAccess = await hasPermission(authResult.context!.userId, permission)
  if (!hasAccess) {
    return {
      authorized: false,
      error: `Access denied - missing permission: ${permission}`,
      status: 403,
    }
  }

  return authResult
}

/**
 * Create unauthorized response
 */
export function unauthorizedResponse(error: string, status: number = 403): NextResponse {
  return NextResponse.json(
    { success: false, error },
    { status }
  )
}

/**
 * Create error response
 */
export function errorResponse(error: string, status: number = 500): NextResponse {
  return NextResponse.json(
    { success: false, error },
    { status }
  )
}

/**
 * Create success response
 */
export function successResponse<T>(data: T): NextResponse {
  return NextResponse.json({
    success: true,
    ...data,
  })
}

/**
 * Wrap an admin API handler with auth middleware
 */
export function withAdminAuth<T>(
  handler: (request: NextRequest, context: AdminContext) => Promise<NextResponse>
) {
  return async (request: NextRequest): Promise<NextResponse> => {
    const authResult = await verifyAdminAccess(request)

    if (!authResult.authorized) {
      return unauthorizedResponse(authResult.error!, authResult.status)
    }

    return handler(request, authResult.context!)
  }
}

/**
 * Wrap an admin API handler with permission check
 */
export function withPermission<T>(
  permission: Permission,
  handler: (request: NextRequest, context: AdminContext) => Promise<NextResponse>
) {
  return async (request: NextRequest): Promise<NextResponse> => {
    const authResult = await requirePermission(request, permission)

    if (!authResult.authorized) {
      return unauthorizedResponse(authResult.error!, authResult.status)
    }

    return handler(request, authResult.context!)
  }
}

/**
 * Parse common query parameters for admin APIs
 */
export function parseAdminQueryParams(request: NextRequest): {
  timeRange: '7d' | '30d' | '90d' | 'all'
  startDate: Date | null
  endDate: Date
  page: number
  limit: number
} {
  const { searchParams } = new URL(request.url)

  const timeRange = (searchParams.get('timeRange') || '7d') as '7d' | '30d' | '90d' | 'all'
  const page = Math.max(1, parseInt(searchParams.get('page') || '1', 10))
  const limit = Math.min(100, Math.max(1, parseInt(searchParams.get('limit') || '50', 10)))

  const now = new Date()
  let startDate: Date | null = null

  switch (timeRange) {
    case '7d':
      startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000)
      break
    case '30d':
      startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000)
      break
    case '90d':
      startDate = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000)
      break
    default:
      startDate = null
  }

  return {
    timeRange,
    startDate,
    endDate: now,
    page,
    limit,
  }
}

/**
 * Get date range for a time period
 */
export function getDateRange(timeRange: string): { startDate: Date | null; endDate: Date } {
  const now = new Date()
  let startDate: Date | null = null

  switch (timeRange) {
    case '7d':
      startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000)
      break
    case '30d':
      startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000)
      break
    case '90d':
      startDate = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000)
      break
    case '1y':
      startDate = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000)
      break
    default:
      startDate = null
  }

  return { startDate, endDate: now }
}

/**
 * Role-Based Access Control (RBAC) System for Admin
 *
 * Production-ready admin authentication and authorization.
 * Supports multiple admin roles with granular permissions.
 */

import { adminDb, adminAuth } from '../firebase-admin'
import { Timestamp } from 'firebase-admin/firestore'

/**
 * Admin role definitions
 * - super_admin: Full access, can manage other admins
 * - admin: Full analytics access, can manage users
 * - analyst: Read-only analytics access
 * - support: User management only (for customer support)
 */
export type AdminRole = 'super_admin' | 'admin' | 'analyst' | 'support'

/**
 * Permission definitions
 */
export const PERMISSIONS = {
  // Analytics permissions
  VIEW_ANALYTICS: 'view_analytics',
  VIEW_REVENUE: 'view_revenue',
  EXPORT_DATA: 'export_data',

  // User management permissions
  VIEW_USERS: 'view_users',
  MANAGE_USERS: 'manage_users',
  VIEW_USER_DETAILS: 'view_user_details',

  // System permissions
  VIEW_ERRORS: 'view_errors',
  MANAGE_SETTINGS: 'manage_settings',
  MANAGE_ADMINS: 'manage_admins',

  // AI/Usage permissions
  VIEW_AI_USAGE: 'view_ai_usage',
  MANAGE_BUDGETS: 'manage_budgets',
} as const

export type Permission = typeof PERMISSIONS[keyof typeof PERMISSIONS]

/**
 * Role to permissions mapping
 */
export const ROLE_PERMISSIONS: Record<AdminRole, Permission[]> = {
  super_admin: Object.values(PERMISSIONS), // All permissions

  admin: [
    PERMISSIONS.VIEW_ANALYTICS,
    PERMISSIONS.VIEW_REVENUE,
    PERMISSIONS.EXPORT_DATA,
    PERMISSIONS.VIEW_USERS,
    PERMISSIONS.MANAGE_USERS,
    PERMISSIONS.VIEW_USER_DETAILS,
    PERMISSIONS.VIEW_ERRORS,
    PERMISSIONS.MANAGE_SETTINGS,
    PERMISSIONS.VIEW_AI_USAGE,
    PERMISSIONS.MANAGE_BUDGETS,
  ],

  analyst: [
    PERMISSIONS.VIEW_ANALYTICS,
    PERMISSIONS.VIEW_REVENUE,
    PERMISSIONS.EXPORT_DATA,
    PERMISSIONS.VIEW_USERS,
    PERMISSIONS.VIEW_ERRORS,
    PERMISSIONS.VIEW_AI_USAGE,
  ],

  support: [
    PERMISSIONS.VIEW_USERS,
    PERMISSIONS.MANAGE_USERS,
    PERMISSIONS.VIEW_USER_DETAILS,
    PERMISSIONS.VIEW_ERRORS,
  ],
}

/**
 * Admin role document stored in Firestore
 */
export interface AdminRoleDoc {
  userId: string
  email: string
  role: AdminRole
  grantedBy: string
  grantedAt: Timestamp
  lastAccess?: Timestamp
  active: boolean
}

/**
 * Get admin role for a user
 * Returns null if user is not an admin
 */
export async function getAdminRole(userId: string): Promise<AdminRole | null> {
  // First check environment variable for super admin (bootstrap admin)
  const envAdminId = process.env.ADMIN_USER_ID
  if (envAdminId && userId === envAdminId) {
    return 'super_admin'
  }

  // Check Firestore for additional admins
  if (!adminDb) return null

  try {
    const adminDoc = await adminDb.collection('admin_roles').doc(userId).get()

    if (!adminDoc.exists) return null

    const data = adminDoc.data() as AdminRoleDoc
    if (!data.active) return null

    // Update last access time (fire and forget)
    adminDb.collection('admin_roles').doc(userId).update({
      lastAccess: Timestamp.now(),
    }).catch(() => { /* ignore */ })

    return data.role
  } catch (error) {
    console.error('[RBAC] Error fetching admin role:', error)
    return null
  }
}

/**
 * Check if a user has a specific permission
 */
export async function hasPermission(userId: string, permission: Permission): Promise<boolean> {
  const role = await getAdminRole(userId)
  if (!role) return false

  return ROLE_PERMISSIONS[role].includes(permission)
}

/**
 * Check if a user has any of the specified permissions
 */
export async function hasAnyPermission(userId: string, permissions: Permission[]): Promise<boolean> {
  const role = await getAdminRole(userId)
  if (!role) return false

  const userPermissions = ROLE_PERMISSIONS[role]
  return permissions.some(p => userPermissions.includes(p))
}

/**
 * Check if a user has all of the specified permissions
 */
export async function hasAllPermissions(userId: string, permissions: Permission[]): Promise<boolean> {
  const role = await getAdminRole(userId)
  if (!role) return false

  const userPermissions = ROLE_PERMISSIONS[role]
  return permissions.every(p => userPermissions.includes(p))
}

/**
 * Get all permissions for a user
 */
export async function getUserPermissions(userId: string): Promise<Permission[]> {
  const role = await getAdminRole(userId)
  if (!role) return []

  return ROLE_PERMISSIONS[role]
}

/**
 * Grant admin role to a user (requires super_admin)
 */
export async function grantAdminRole(
  granterId: string,
  targetUserId: string,
  targetEmail: string,
  role: AdminRole
): Promise<{ success: boolean; error?: string }> {
  // Verify granter is super_admin
  const granterRole = await getAdminRole(granterId)
  if (granterRole !== 'super_admin') {
    return { success: false, error: 'Only super admins can grant admin roles' }
  }

  // Cannot grant super_admin role
  if (role === 'super_admin') {
    return { success: false, error: 'Super admin role cannot be granted through API' }
  }

  if (!adminDb) {
    return { success: false, error: 'Database not available' }
  }

  try {
    await adminDb.collection('admin_roles').doc(targetUserId).set({
      userId: targetUserId,
      email: targetEmail,
      role,
      grantedBy: granterId,
      grantedAt: Timestamp.now(),
      active: true,
    })

    // Log admin action
    await logAdminAction(granterId, 'grant_role', {
      targetUserId,
      targetEmail,
      role,
    })

    return { success: true }
  } catch (error) {
    console.error('[RBAC] Error granting admin role:', error)
    return { success: false, error: 'Failed to grant admin role' }
  }
}

/**
 * Revoke admin role from a user (requires super_admin)
 */
export async function revokeAdminRole(
  revokerId: string,
  targetUserId: string
): Promise<{ success: boolean; error?: string }> {
  const revokerRole = await getAdminRole(revokerId)
  if (revokerRole !== 'super_admin') {
    return { success: false, error: 'Only super admins can revoke admin roles' }
  }

  // Cannot revoke env-based super admin
  if (targetUserId === process.env.ADMIN_USER_ID) {
    return { success: false, error: 'Cannot revoke environment-configured super admin' }
  }

  if (!adminDb) {
    return { success: false, error: 'Database not available' }
  }

  try {
    await adminDb.collection('admin_roles').doc(targetUserId).update({
      active: false,
    })

    await logAdminAction(revokerId, 'revoke_role', { targetUserId })

    return { success: true }
  } catch (error) {
    console.error('[RBAC] Error revoking admin role:', error)
    return { success: false, error: 'Failed to revoke admin role' }
  }
}

/**
 * List all admins
 */
export async function listAdmins(): Promise<AdminRoleDoc[]> {
  if (!adminDb) return []

  try {
    const snapshot = await adminDb
      .collection('admin_roles')
      .where('active', '==', true)
      .get()

    const admins = snapshot.docs.map(doc => doc.data() as AdminRoleDoc)

    // Add env-based super admin if set
    const envAdminId = process.env.ADMIN_USER_ID
    if (envAdminId) {
      // Check if already in list
      if (!admins.find(a => a.userId === envAdminId)) {
        admins.unshift({
          userId: envAdminId,
          email: 'Environment Admin',
          role: 'super_admin',
          grantedBy: 'system',
          grantedAt: Timestamp.now(),
          active: true,
        })
      }
    }

    return admins
  } catch (error) {
    console.error('[RBAC] Error listing admins:', error)
    return []
  }
}

/**
 * Log admin action for audit trail
 */
async function logAdminAction(
  adminId: string,
  action: string,
  details: Record<string, any>
): Promise<void> {
  if (!adminDb) return

  try {
    await adminDb.collection('admin_audit_log').add({
      adminId,
      action,
      details,
      timestamp: Timestamp.now(),
      ip: 'server', // In production, pass IP from request
    })
  } catch (error) {
    console.error('[RBAC] Error logging admin action:', error)
  }
}

/**
 * Verify Firebase ID token and return user info
 */
export async function verifyToken(token: string): Promise<{
  valid: boolean
  userId?: string
  email?: string
  error?: string
}> {
  if (!adminAuth) {
    return { valid: false, error: 'Auth not initialized' }
  }

  try {
    const decodedToken = await adminAuth.verifyIdToken(token)
    return {
      valid: true,
      userId: decodedToken.uid,
      email: decodedToken.email,
    }
  } catch (error) {
    return { valid: false, error: 'Invalid token' }
  }
}

/**
 * AI Response Cache
 *
 * Caches AI responses to reduce API costs and improve latency.
 * Uses a combination of in-memory cache (fast) and Firestore (persistent).
 *
 * Cache strategy:
 * - Semantic similarity: Hash the core request elements
 * - TTL: 24 hours for chat, 7 days for feedback
 * - Max entries: 1000 in-memory, unlimited in Firestore
 */

import crypto from "crypto"
import { adminDb } from "./firebase-admin"
import { FieldValue, Timestamp } from "firebase-admin/firestore"

// Cache configuration
const CACHE_CONFIG = {
  // In-memory cache limits
  maxMemoryEntries: 1000,
  memoryTTLMs: 30 * 60 * 1000, // 30 minutes in memory

  // Firestore cache TTLs (in seconds)
  ttlByType: {
    chat: 24 * 60 * 60, // 24 hours
    feedback: 7 * 24 * 60 * 60, // 7 days
    hint: 7 * 24 * 60 * 60, // 7 days
    system: 30 * 24 * 60 * 60, // 30 days for system prompts
  } as Record<string, number>,

  // Default TTL
  defaultTTLSeconds: 24 * 60 * 60,
}

// In-memory cache (LRU-style)
interface MemoryCacheEntry {
  response: string
  createdAt: number
  hitCount: number
}

const memoryCache = new Map<string, MemoryCacheEntry>()

// Negative cache: track keys that don't exist to avoid repeated Firestore reads
// This saves Firestore costs by not querying for keys we recently checked
interface NegativeCacheEntry {
  checkedAt: number
}

const negativeCache = new Map<string, NegativeCacheEntry>()
const NEGATIVE_CACHE_TTL_MS = 5 * 60 * 1000 // 5 minutes - don't re-check Firestore for misses
const MAX_NEGATIVE_CACHE_SIZE = 5000 // Limit memory usage

/**
 * Generate a cache key from request parameters
 * Uses a hash of the FULL semantic content to prevent collisions
 */
export function generateCacheKey(params: {
  type: string
  systemPrompt?: string
  userMessage: string
  context?: string
  scenarioId?: string
  language?: string
}): string {
  // SECURITY FIX: Hash FULL content instead of truncating
  // Truncation caused cache key collisions when prompts shared prefixes
  const normalized = {
    type: params.type,
    // Hash the FULL system prompt to prevent collision on shared prefixes
    systemPromptHash: params.systemPrompt ? hashString(params.systemPrompt) : "",
    // Hash the FULL user message (normalize first)
    userMessageHash: hashString(params.userMessage.trim().toLowerCase()),
    // Hash context if present
    contextHash: params.context ? hashString(params.context) : "",
    scenarioId: params.scenarioId || "",
    language: params.language || "",
  }

  const keyString = JSON.stringify(normalized)
  return hashString(keyString)
}

/**
 * Hash a string using SHA-256
 */
function hashString(str: string): string {
  return crypto.createHash("sha256").update(str).digest("hex").slice(0, 32)
}

/**
 * Get cached response (memory first, then Firestore)
 * Uses negative caching to avoid repeated Firestore reads for missing keys
 */
export async function getCachedResponse(cacheKey: string): Promise<{
  hit: boolean
  response?: string
  source?: "memory" | "firestore"
}> {
  // Check memory cache first
  const memoryEntry = memoryCache.get(cacheKey)
  if (memoryEntry) {
    const age = Date.now() - memoryEntry.createdAt
    if (age < CACHE_CONFIG.memoryTTLMs) {
      memoryEntry.hitCount++
      return { hit: true, response: memoryEntry.response, source: "memory" }
    } else {
      // Expired, remove from memory
      memoryCache.delete(cacheKey)
    }
  }

  // Check negative cache - if we recently checked and it wasn't there, skip Firestore
  const negativeEntry = negativeCache.get(cacheKey)
  if (negativeEntry) {
    const age = Date.now() - negativeEntry.checkedAt
    if (age < NEGATIVE_CACHE_TTL_MS) {
      // Recently checked and it wasn't there - skip Firestore read (saves cost!)
      return { hit: false }
    } else {
      // Expired negative cache entry
      negativeCache.delete(cacheKey)
    }
  }

  // Check Firestore cache
  try {
    const cacheDoc = await adminDb.collection("ai_cache").doc(cacheKey).get()

    if (cacheDoc.exists) {
      const data = cacheDoc.data()!
      const expiresAt = data.expiresAt?.toDate()

      if (expiresAt && expiresAt > new Date()) {
        // Valid cache entry - also store in memory for faster subsequent access
        const response = data.response as string
        memoryCache.set(cacheKey, {
          response,
          createdAt: Date.now(),
          hitCount: 1,
        })
        pruneMemoryCache()

        // Remove from negative cache if it was there
        negativeCache.delete(cacheKey)

        // Update hit count in Firestore (fire and forget)
        adminDb
          .collection("ai_cache")
          .doc(cacheKey)
          .update({
            hitCount: FieldValue.increment(1),
            lastAccessedAt: FieldValue.serverTimestamp(),
          })
          .catch(() => {})

        return { hit: true, response, source: "firestore" }
      } else {
        // Expired, delete from Firestore (fire and forget)
        adminDb
          .collection("ai_cache")
          .doc(cacheKey)
          .delete()
          .catch(() => {})
      }
    }

    // Cache miss - add to negative cache to avoid re-checking Firestore
    addToNegativeCache(cacheKey)
  } catch (error) {
    console.error("[AI Cache] Firestore read error:", error)
  }

  return { hit: false }
}

/**
 * Add a key to the negative cache (tracks cache misses)
 */
function addToNegativeCache(cacheKey: string): void {
  // Prune if over limit
  if (negativeCache.size >= MAX_NEGATIVE_CACHE_SIZE) {
    // Remove oldest 500 entries
    const entries = Array.from(negativeCache.entries()).sort(
      (a, b) => a[1].checkedAt - b[1].checkedAt
    )

    for (let i = 0; i < 500 && i < entries.length; i++) {
      negativeCache.delete(entries[i][0])
    }
  }

  negativeCache.set(cacheKey, { checkedAt: Date.now() })
}

/**
 * Store response in cache
 */
export async function setCachedResponse(
  cacheKey: string,
  response: string,
  type: string = "chat"
): Promise<void> {
  const ttlSeconds = CACHE_CONFIG.ttlByType[type] || CACHE_CONFIG.defaultTTLSeconds
  const expiresAt = new Date(Date.now() + ttlSeconds * 1000)

  // Remove from negative cache since we're storing a value now
  negativeCache.delete(cacheKey)

  // Store in memory
  memoryCache.set(cacheKey, {
    response,
    createdAt: Date.now(),
    hitCount: 0,
  })
  pruneMemoryCache()

  // Store in Firestore (fire and forget)
  try {
    await adminDb
      .collection("ai_cache")
      .doc(cacheKey)
      .set({
        response,
        type,
        createdAt: FieldValue.serverTimestamp(),
        expiresAt: Timestamp.fromDate(expiresAt),
        hitCount: 0,
        lastAccessedAt: FieldValue.serverTimestamp(),
      })
  } catch (error) {
    console.error("[AI Cache] Firestore write error:", error)
  }
}

/**
 * Prune memory cache if it exceeds max entries
 * Uses LRU-style eviction based on hit count
 */
function pruneMemoryCache(): void {
  if (memoryCache.size <= CACHE_CONFIG.maxMemoryEntries) return

  // Convert to array and sort by hit count (ascending)
  const entries = Array.from(memoryCache.entries()).sort((a, b) => a[1].hitCount - b[1].hitCount)

  // Remove least used entries until under limit
  const toRemove = memoryCache.size - CACHE_CONFIG.maxMemoryEntries + 100 // Remove 100 extra
  for (let i = 0; i < toRemove && i < entries.length; i++) {
    memoryCache.delete(entries[i][0])
  }
}

/**
 * Get cache statistics
 */
export function getCacheStats(): {
  memoryCacheSize: number
  memoryHits: number
  negativeCacheSize: number
  negativeCacheSavings: string
} {
  let totalHits = 0
  for (const entry of memoryCache.values()) {
    totalHits += entry.hitCount
  }

  return {
    memoryCacheSize: memoryCache.size,
    memoryHits: totalHits,
    negativeCacheSize: negativeCache.size,
    // Each entry in negative cache = 1 avoided Firestore read
    negativeCacheSavings: `~${negativeCache.size} Firestore reads avoided`,
  }
}

/**
 * Clear all caches (for testing or maintenance)
 */
export async function clearCache(options?: { memoryOnly?: boolean }): Promise<void> {
  memoryCache.clear()
  negativeCache.clear()

  if (!options?.memoryOnly) {
    // Delete expired Firestore entries (batch delete)
    try {
      const expiredDocs = await adminDb
        .collection("ai_cache")
        .where("expiresAt", "<", Timestamp.now())
        .limit(500)
        .get()

      const batch = adminDb.batch()
      expiredDocs.docs.forEach((doc) => batch.delete(doc.ref))
      await batch.commit()

      console.log(`[AI Cache] Cleaned ${expiredDocs.size} expired entries`)
    } catch (error) {
      console.error("[AI Cache] Failed to clean expired entries:", error)
    }
  }
}

/**
 * Wrapper for AI calls with caching
 */
export async function withCache<T>(
  cacheKey: string,
  type: string,
  fetchFn: () => Promise<T>,
  options?: {
    skipCache?: boolean
    forceRefresh?: boolean
  }
): Promise<{ result: T; cached: boolean }> {
  if (options?.skipCache) {
    const result = await fetchFn()
    return { result, cached: false }
  }

  if (!options?.forceRefresh) {
    const cached = await getCachedResponse(cacheKey)
    if (cached.hit && cached.response) {
      return { result: cached.response as T, cached: true }
    }
  }

  const result = await fetchFn()

  // Cache the result if it's a string (most AI responses)
  if (typeof result === "string") {
    await setCachedResponse(cacheKey, result, type)
  }

  return { result, cached: false }
}

