/**
 * API helper utilities for error handling and retry logic
 */

import { toast } from "sonner"

/**
 * Custom error class for API errors
 */
export class APIError extends Error {
  statusCode: number
  data?: any

  constructor(message: string, statusCode: number, data?: any) {
    super(message)
    this.name = "APIError"
    this.statusCode = statusCode
    this.data = data
  }
}

/**
 * Retry configuration
 */
interface RetryConfig {
  maxRetries?: number
  initialDelay?: number
  maxDelay?: number
  backoffMultiplier?: number
  retryableStatusCodes?: number[]
}

const DEFAULT_RETRY_CONFIG: Required<RetryConfig> = {
  maxRetries: 3,
  initialDelay: 1000, // 1 second
  maxDelay: 10000, // 10 seconds
  backoffMultiplier: 2,
  retryableStatusCodes: [408, 429, 500, 502, 503, 504],
}

/**
 * Sleep utility for retry delays
 */
const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms))

/**
 * Fetch with automatic retry on failure
 */
export async function fetchWithRetry(
  url: string,
  options?: RequestInit,
  config: RetryConfig = {}
): Promise<Response> {
  const retryConfig = { ...DEFAULT_RETRY_CONFIG, ...config }
  let lastError: Error | null = null
  let delay = retryConfig.initialDelay

  for (let attempt = 0; attempt <= retryConfig.maxRetries; attempt++) {
    try {
      const response = await fetch(url, options)

      // If response is OK or not retryable, return it
      if (response.ok || !retryConfig.retryableStatusCodes.includes(response.status)) {
        return response
      }

      // Response has retryable error status
      lastError = new APIError(
        `Request failed with status ${response.status}`,
        response.status
      )

      // Don't retry on last attempt
      if (attempt === retryConfig.maxRetries) {
        throw lastError
      }

      // Log retry attempt
      console.warn(`Retry attempt ${attempt + 1}/${retryConfig.maxRetries} after ${delay}ms`)

      // Wait before retrying
      await sleep(delay)
      delay = Math.min(delay * retryConfig.backoffMultiplier, retryConfig.maxDelay)

    } catch (error) {
      lastError = error instanceof Error ? error : new Error("Unknown error")

      // Network errors are always retryable
      if (attempt === retryConfig.maxRetries) {
        throw lastError
      }

      console.warn(`Retry attempt ${attempt + 1}/${retryConfig.maxRetries} after ${delay}ms due to error:`, error)

      await sleep(delay)
      delay = Math.min(delay * retryConfig.backoffMultiplier, retryConfig.maxDelay)
    }
  }

  throw lastError || new Error("Request failed after all retries")
}

/**
 * Parse API error response and show user-friendly message
 */
export async function parseAPIError(response: Response): Promise<string> {
  try {
    const data = await response.json()

    // Check for various error message formats
    if (data.error) {
      return typeof data.error === "string" ? data.error : data.error.message || "An error occurred"
    }

    if (data.message) {
      return data.message
    }

    // Fallback to status text
    return response.statusText || "An error occurred"
  } catch {
    // If parsing fails, return status text
    return response.statusText || "An error occurred"
  }
}

/**
 * Show user-friendly error toast based on error type
 */
export function showErrorToast(error: unknown, fallbackMessage = "Something went wrong") {
  if (error instanceof APIError) {
    // Handle API errors
    if (error.statusCode === 401) {
      toast.error("Authentication failed. Please log in again.")
    } else if (error.statusCode === 403) {
      toast.error("You don't have permission to perform this action.")
    } else if (error.statusCode === 404) {
      toast.error("The requested resource was not found.")
    } else if (error.statusCode === 429) {
      toast.error("Too many requests. Please wait a moment and try again.")
    } else if (error.statusCode >= 500) {
      toast.error("Server error. Please try again later.")
    } else {
      toast.error(error.message || fallbackMessage)
    }
  } else if (error instanceof Error) {
    // Handle generic errors
    if (error.message.includes("network") || error.message.includes("fetch")) {
      toast.error("Network error. Please check your connection and try again.")
    } else {
      toast.error(error.message || fallbackMessage)
    }
  } else {
    // Unknown error type
    toast.error(fallbackMessage)
  }
}

/**
 * Wrapper for API calls with error handling and retry logic
 */
export async function apiCall<T = any>(
  url: string,
  options?: RequestInit,
  config: RetryConfig & { showErrorToast?: boolean } = {}
): Promise<T> {
  const { showErrorToast: shouldShowToast = true, ...retryConfig } = config

  try {
    const response = await fetchWithRetry(url, options, retryConfig)

    if (!response.ok) {
      const errorMessage = await parseAPIError(response)
      const error = new APIError(errorMessage, response.status)

      if (shouldShowToast) {
        showErrorToast(error)
      }

      throw error
    }

    return await response.json()
  } catch (error) {
    if (shouldShowToast && !(error instanceof APIError)) {
      showErrorToast(error)
    }
    throw error
  }
}

/**
 * Validate response data
 */
export function validateResponse<T>(data: any, validator: (data: any) => boolean): T {
  if (!validator(data)) {
    throw new Error("Invalid response data")
  }
  return data as T
}

"use client"

import { createContext, useContext, useEffect, useState, ReactNode } from "react"
import { User as FirebaseUser, onAuthStateChanged, Auth } from "firebase/auth"
import { User as UserType } from "./types"
import { convertFirebaseUser } from "./auth"

interface AuthContextType {
  user: UserType | null
  firebaseUser: FirebaseUser | null
  loading: boolean
  initialized: boolean
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  firebaseUser: null,
  loading: true,
  initialized: false,
})

export function AuthProvider({ children }: { children: ReactNode }) {
  const [firebaseUser, setFirebaseUser] = useState<FirebaseUser | null>(null)
  const [user, setUser] = useState<UserType | null>(null)
  const [loading, setLoading] = useState(true)
  const [initialized, setInitialized] = useState(false)

  useEffect(() => {
    let mounted = true
    let authStateResolved = false
    let unsubscribe: (() => void) | null = null

    // Lazily initialize Firebase Auth
    const initAuth = async () => {
      try {
        // Dynamic import for lazy loading
        const { getAuthLazy } = await import("./firebase-lazy")
        const auth = await getAuthLazy()

        if (!mounted) return

        // Single auth state listener for the entire app
        unsubscribe = onAuthStateChanged(auth, (fbUser) => {
          if (!mounted) return

          authStateResolved = true

          setFirebaseUser(fbUser)

          if (fbUser) {
            const convertedUser = convertFirebaseUser(fbUser)
            setUser(convertedUser)
            // Set auth indicator cookie for middleware (server-side route protection)
            document.cookie = `firebase-auth-token=1; path=/; max-age=${60 * 60 * 24 * 7}; SameSite=Lax`
          } else {
            setUser(null)
            // Clear auth indicator cookie on logout
            document.cookie = 'firebase-auth-token=; path=/; max-age=0; SameSite=Lax'
          }

          setLoading(false)
          setInitialized(true)
        }, () => {
          if (!mounted) return
          // Auth state change error - continue anyway
          authStateResolved = true
          setLoading(false)
          setInitialized(true)
        })
      } catch {
        // Failed to initialize Firebase Auth
        if (mounted) {
          setLoading(false)
          setInitialized(true)
        }
      }
    }

    initAuth()

    // Safety timeout to prevent infinite loading
    // Firebase should respond quickly, but if it doesn't, we mark as initialized anyway
    const timeout = setTimeout(() => {
      if (mounted && !authStateResolved) {
        // Auth initialization timeout - mark as initialized anyway
        setLoading(false)
        setInitialized(true)
      }
    }, 2000) // 2 second timeout for faster loading

    return () => {
      mounted = false
      clearTimeout(timeout)
      if (unsubscribe) unsubscribe()
    }
  }, []) // Empty dependency array - only run once on mount

  // Token refresh - refresh ID token every 50 minutes (tokens expire after 1 hour)
  useEffect(() => {
    if (!firebaseUser) return

    const refreshToken = async () => {
      try {
        // Force token refresh
        await firebaseUser.getIdToken(true)
      } catch {
        // Token refresh failed - will retry on next interval
      }
    }

    // Refresh immediately if token is close to expiration
    const checkAndRefresh = async () => {
      try {
        const tokenResult = await firebaseUser.getIdTokenResult()
        const expirationTime = new Date(tokenResult.expirationTime).getTime()
        const currentTime = Date.now()
        const timeUntilExpiration = expirationTime - currentTime

        // If token expires in less than 10 minutes, refresh now
        if (timeUntilExpiration < 10 * 60 * 1000) {
          await refreshToken()
        }
      } catch {
        // Failed to check token expiration - will check on next interval
      }
    }

    // Check immediately on mount
    checkAndRefresh()

    // Set up periodic refresh every 50 minutes
    const refreshInterval = setInterval(refreshToken, 50 * 60 * 1000)

    return () => {
      clearInterval(refreshInterval)
    }
  }, [firebaseUser])

  return (
    <AuthContext.Provider value={{ user, firebaseUser, loading, initialized }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  const context = useContext(AuthContext)
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider")
  }
  return context
}

/**
 * Server-side authentication helpers for Next.js API routes
 * Handles Firebase ID token verification using Firebase Admin SDK
 */

import { NextRequest } from "next/server"
import { adminAuth } from "./firebase-admin"

// Development mode check - logs only appear in development
const isDev = process.env.NODE_ENV === "development"

/**
 * Get Firebase user ID from request with proper token verification
 * Expects Firebase ID token in Authorization header: "Bearer <token>"
 *
 * Uses Firebase Admin SDK for secure token verification
 */
export async function getUserIdFromRequest(request: NextRequest): Promise<string | null> {
  try {
    const authHeader = request.headers.get("authorization")

    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      if (isDev) console.warn("No authorization header or invalid format")
      return null
    }

    const token = authHeader.substring(7) // Remove "Bearer " prefix

    if (!token) {
      if (isDev) console.warn("Empty token after Bearer prefix")
      return null
    }

    try {
      // Verify the ID token locally using Firebase Admin SDK (without revocation check network hop)
      const decodedToken = await adminAuth.verifyIdToken(token)

      // Return user ID from verified token
      return decodedToken.uid
    } catch (verificationError: any) {
      if (isDev) {
        console.error("Token verification failed:")
        console.error("  Error code:", verificationError?.code)
        console.error("  Error message:", verificationError?.message)

        // Provide more specific error information
        if (verificationError?.code === "auth/argument-error") {
          console.error("  Issue: Invalid token format")
        } else if (verificationError?.code === "auth/id-token-expired") {
          console.error("  Issue: Token has expired")
        } else if (verificationError?.code === "auth/id-token-revoked") {
          console.error("  Issue: Token has been revoked")
        } else if (verificationError?.code === "auth/invalid-id-token") {
          console.error("  Issue: Token is invalid or malformed")
        } else if (verificationError?.code === "auth/project-not-found") {
          console.error("  Issue: Firebase project not found - check Admin SDK initialization")
        }
      }

      return null
    }
  } catch (error) {
    if (isDev) {
      console.error("Error verifying token:", error)
      if (error instanceof Error) {
        console.error("  Error name:", error.name)
        console.error("  Error message:", error.message)
      }
    }
    return null
  }
}

