  return COMPANY_MAP[id]
}

/**
 * Get companies by difficulty level (based on interview difficulty)
 */
export function getCompaniesByDifficulty(
  level: "easier" | "moderate" | "harder"
): CompanyQuestionData[] {
  const harderCompanies: CompanyId[] = [
    "google",
    "netflix",
    "palantir",
    "jane-street",
    "databricks",
    "snowflake",
  ]
  const easierCompanies: CompanyId[] = ["microsoft", "linkedin", "bloomberg", "shopify", "lyft"]

  switch (level) {
    case "harder":
      return ALL_COMPANIES.filter((c) => harderCompanies.includes(c.id))
    case "easier":
      return ALL_COMPANIES.filter((c) => easierCompanies.includes(c.id))
    case "moderate":
      return ALL_COMPANIES.filter(
        (c) => !harderCompanies.includes(c.id) && !easierCompanies.includes(c.id)
      )
  }
}

/**
 * Get top patterns across multiple companies (for generic prep)
 */
export function getTopPatternsAcrossCompanies(
  companyIds: CompanyId[],
  limit: number = 10
): { pattern: DSAPattern; avgFrequency: number; companies: string[] }[] {
  const patternStats: Record<string, { totalFreq: number; count: number; companies: string[] }> = {}

  for (const id of companyIds) {
    const company = COMPANY_MAP[id]
    if (!company) continue

    for (const p of company.topPatterns) {
      if (!patternStats[p.pattern]) {
        patternStats[p.pattern] = { totalFreq: 0, count: 0, companies: [] }
      }
      patternStats[p.pattern].totalFreq += p.frequency
      patternStats[p.pattern].count += 1
      patternStats[p.pattern].companies.push(company.name)
    }
  }

  return Object.entries(patternStats)
    .map(([pattern, stats]) => ({
      pattern: pattern as DSAPattern,
      avgFrequency: Math.round(stats.totalFreq / stats.count),
      companies: stats.companies,
    }))
    .sort((a, b) => b.avgFrequency - a.avgFrequency)
    .slice(0, limit)
}

/**
 * Get estimated preparation time based on company difficulty
 */
export function getEstimatedPrepTime(
  companyId: CompanyId,
  experienceLevel: "beginner" | "intermediate" | "advanced"
): { minWeeks: number; maxWeeks: number; recommendedHoursPerWeek: number } {
  const company = COMPANY_MAP[companyId]
  if (!company) {
    return { minWeeks: 8, maxWeeks: 12, recommendedHoursPerWeek: 15 }
  }

  const hardMultiplier = company.difficultyDistribution.hard / 100
  const basePrepWeeks = {
    beginner: { min: 12, max: 20 },
    intermediate: { min: 6, max: 12 },
    advanced: { min: 3, max: 6 },
  }

  const base = basePrepWeeks[experienceLevel]
  const adjustedMin = Math.ceil(base.min * (1 + hardMultiplier * 0.5))
  const adjustedMax = Math.ceil(base.max * (1 + hardMultiplier * 0.5))

  return {
    minWeeks: adjustedMin,
    maxWeeks: adjustedMax,
    recommendedHoursPerWeek:
      experienceLevel === "beginner" ? 20 : experienceLevel === "intermediate" ? 15 : 10,
  }
}

/**
 * Get company comparison data for UI
 */
export function compareCompanies(ids: CompanyId[]): {
  companies: { id: CompanyId; name: string }[]
  patterns: { pattern: DSAPattern; frequencies: Record<CompanyId, number> }[]
  difficulty: { company: CompanyId; distribution: { easy: number; medium: number; hard: number } }[]
  processLength: { company: CompanyId; rounds: number; timeline: string }[]
} {
  const companies = ids.map((id) => ({ id, name: COMPANY_MAP[id]?.name || id }))

  // Collect all patterns mentioned by any company
  const allPatterns = new Set<DSAPattern>()
  for (const id of ids) {
    const company = COMPANY_MAP[id]
    if (company) {
      company.topPatterns.forEach((p) => allPatterns.add(p.pattern))
    }
  }

  const patterns = Array.from(allPatterns)
    .map((pattern) => {
      const frequencies: Record<CompanyId, number> = {} as Record<CompanyId, number>
      for (const id of ids) {
        const company = COMPANY_MAP[id]
        const patternData = company?.topPatterns.find((p) => p.pattern === pattern)
        frequencies[id] = patternData?.frequency || 0
      }
      return { pattern, frequencies }
    })
    .sort((a, b) => {
      const avgA = Object.values(a.frequencies).reduce((s, v) => s + v, 0) / ids.length
      const avgB = Object.values(b.frequencies).reduce((s, v) => s + v, 0) / ids.length
      return avgB - avgA
    })

  const difficulty = ids.map((id) => ({
    company: id,
    distribution: COMPANY_MAP[id]?.difficultyDistribution || { easy: 33, medium: 34, hard: 33 },
  }))

  const processLength = ids.map((id) => ({
    company: id,
    rounds: COMPANY_MAP[id]?.interviewProcess.totalRounds || 4,
    timeline: COMPANY_MAP[id]?.interviewProcess.timeline || "2-4 weeks",
  }))

  return { companies, patterns, difficulty, processLength }
}

/**
 * Search companies by name
 */
export function searchCompanies(query: string): CompanyQuestionData[] {
  const lowerQuery = query.toLowerCase()
  return ALL_COMPANIES.filter(
    (c) => c.name.toLowerCase().includes(lowerQuery) || c.id.includes(lowerQuery)
  )
}

/**
 * Get companies sorted by a specific pattern's importance
 */
export function getCompaniesByPatternImportance(pattern: DSAPattern): CompanyQuestionData[] {
  return ALL_COMPANIES.map((company) => {
    const patternData = company.topPatterns.find((p) => p.pattern === pattern)
    return {
      company,
      score: patternData ? patternData.frequency * patternData.priority : 0,
    }
  })
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score)
    .map((item) => item.company)
}

/**
 * Brevo (Sendinblue) Email Service
 *
 * Handles all transactional email sending for CodeSparring.
 * Based on Brevo's Node.js SDK: @getbrevo/brevo
 */

import {
  TransactionalEmailsApi,
  TransactionalEmailsApiApiKeys,
  ContactsApi,
  ContactsApiApiKeys,
  SendSmtpEmail,
  CreateContact,
} from "@getbrevo/brevo";
import { logger } from "@/lib/logger";

// Lazy-initialized API instances with API key configured
let emailApi: TransactionalEmailsApi | null = null;
let contactsApi: ContactsApi | null = null;

function getEmailApi(): TransactionalEmailsApi {
  const apiKey = process.env.BREVO_API_KEY;
  if (!apiKey) {
    throw new Error("BREVO_API_KEY not configured");
  }

  if (!emailApi) {
    emailApi = new TransactionalEmailsApi();
    // Set API key using the SDK's setApiKey method
    emailApi.setApiKey(TransactionalEmailsApiApiKeys.apiKey, apiKey);
    logger.debug("Brevo Email API initialized");
  }
  return emailApi;
}

function getContactsApi(): ContactsApi {
  const apiKey = process.env.BREVO_API_KEY;
  if (!apiKey) {
    throw new Error("BREVO_API_KEY not configured");
  }

  if (!contactsApi) {
    contactsApi = new ContactsApi();
    // Set API key using the SDK's setApiKey method
    contactsApi.setApiKey(ContactsApiApiKeys.apiKey, apiKey);
    logger.debug("Brevo Contacts API initialized");
  }
  return contactsApi;
}

// Email sender configuration
// Using personal name improves inbox placement (Primary vs Promotions)
// Research shows emails from "Name from Company" land in Primary more often
const DEFAULT_SENDER = {
  name: "Nikayel from CodeSparring",
  email: "nikayel@codesparring.dev"
};

// Types
export interface EmailRecipient {
  email: string;
  name?: string;
}

export interface SendEmailOptions {
  to: EmailRecipient[];
  subject: string;
  htmlContent: string;
  textContent?: string;
  sender?: { name: string; email: string };
  replyTo?: { email: string; name?: string };
  tags?: string[];
  params?: Record<string, string>;
}

export interface EmailResult {
  success: boolean;
  messageId?: string;
  error?: string;
}

/**
 * Helper to wait for a specified time
 */
function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * Send a transactional email via Brevo with retry logic
 * Retries up to 3 times with exponential backoff for transient failures
 */
export async function sendEmail(options: SendEmailOptions): Promise<EmailResult> {
  // Check if API key is configured
  if (!process.env.BREVO_API_KEY) {
    console.warn("[Brevo] API key not configured, skipping email send");
    return { success: false, error: "BREVO_API_KEY not configured" };
  }

  const MAX_RETRIES = 3;
  const INITIAL_DELAY_MS = 1000;
  let lastError: any;

  // Get API instance - this will configure authentication
  let api: TransactionalEmailsApi;
  try {
    api = getEmailApi();
  } catch (error: any) {
    console.error("[Brevo] Failed to initialize API:", error?.message || error);
    return { success: false, error: error?.message || "Failed to initialize email API" };
  }

  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
    try {
      const message = new SendSmtpEmail();
      message.subject = options.subject;
      message.htmlContent = options.htmlContent;
      message.textContent = options.textContent;
      message.sender = options.sender || DEFAULT_SENDER;
      message.to = options.to.map(r => ({ email: r.email, name: r.name }));

      if (options.replyTo) {
        message.replyTo = options.replyTo;
      }

      if (options.tags) {
        message.tags = options.tags;
      }

      if (options.params) {
        message.params = options.params;
      }

      const result = await api.sendTransacEmail(message);

      logger.info("Email sent successfully", { recipients: options.to.map(r => r.email) });

      return {
        success: true,
        messageId: (result.body as any)?.messageId || "sent"
      };
    } catch (error: any) {
      lastError = error;
      const statusCode = error?.statusCode || error?.response?.statusCode;

      // Only retry on transient errors (5xx, network issues, rate limits)
      const isRetryable =
        statusCode >= 500 ||
        statusCode === 429 ||
        error?.code === 'ECONNRESET' ||
        error?.code === 'ETIMEDOUT' ||
        error?.code === 'ENOTFOUND';

      if (isRetryable && attempt < MAX_RETRIES - 1) {
        const delayMs = INITIAL_DELAY_MS * Math.pow(2, attempt);
        logger.warn("Brevo transient error, retrying", { delayMs, attempt: attempt + 1, maxRetries: MAX_RETRIES, error: error?.body?.message || error?.message });
        await sleep(delayMs);
        continue;
      }

      // Non-retryable error or max retries reached
      break;
    }
  }

  logger.error("Failed to send email after retries", { error: lastError?.body?.message || lastError?.message });
  return {
    success: false,
    error: lastError?.body?.message || lastError?.message || "Unknown error"
  };
}

/**
 * Add or update a contact in Brevo
 */
export async function upsertContact(
  email: string,
  attributes?: Record<string, any>,
  listIds?: number[]
): Promise<boolean> {
  if (!process.env.BREVO_API_KEY) {
    logger.warn("Brevo API key not configured, skipping contact upsert");
    return false;
  }

  try {
    const api = getContactsApi();

    const contact = new CreateContact();
    contact.email = email;
    contact.updateEnabled = true; // Update if exists

    if (attributes) {
      contact.attributes = attributes;
    }

    if (listIds && listIds.length > 0) {
      contact.listIds = listIds;
    }

    await api.createContact(contact);
    logger.debug("Contact upserted", { email });
    return true;
  } catch (error: any) {
    // Ignore "contact already exists" errors when updateEnabled is true
    if (error?.body?.code === "duplicate_parameter") {
      return true;
    }
    logger.error("Failed to upsert contact", { email, error: error?.body?.message || error?.message });
    return false;
  }
}

/**
 * Calculate estimated memory retention based on Ebbinghaus forgetting curve
 * R = e^(-t/S) where t is time in days and S is memory strength
 *
 * @param daysSinceLastPractice - Days since the topic was last practiced
 * @param performanceScore - Last performance score (0-100)
 * @returns Estimated retention percentage (0-100)
 */
export function calculateRetention(daysSinceLastPractice: number, performanceScore: number = 70): number {
  // Memory strength factor based on performance (higher score = stronger memory)
  // S ranges from 3 (weak) to 15 (strong)
  const memoryStrength = 3 + (performanceScore / 100) * 12;

  // Apply forgetting curve formula
  const retention = Math.exp(-daysSinceLastPractice / memoryStrength) * 100;

  // Clamp between 0 and 100
  return Math.max(0, Math.min(100, Math.round(retention)));
}

/**
 * Get optimal hours for sending emails based on user timezone
 * Returns hours in user's local time that are best for engagement
 */
export function getOptimalSendHours(): number[] {
  // Based on research: 9-11 AM, 2-4 PM, 7-8 PM are optimal
  return [9, 10, 11, 14, 15, 16, 19, 20];
}

/**
 * Check if current hour is optimal for sending emails
 */
export function isOptimalSendTime(userTimezoneOffset: number = 0): boolean {
  const now = new Date();
  // Adjust for user timezone
  const userHour = (now.getUTCHours() + userTimezoneOffset + 24) % 24;
  return getOptimalSendHours().includes(userHour);
}

