/**
 * Create an interview session for a guest user
 * Guest sessions are stored with is_guest: true flag and can be migrated later
 */
export async function createGuestInterviewSession(
  guestId: string,
  scenarioTitle: string,
  scenarioType: string,
  difficulty: "easy" | "medium" | "hard",
  scenarioId?: string,
  pattern?: string
): Promise<string> {
  const sessionRef = doc(collection(db, "interview_sessions"))
  const sessionData = {
    id: sessionRef.id,
    user_id: guestId, // Store the guest ID as user_id for consistency
    is_guest: true,
    topic: scenarioTitle,
    type: scenarioType,
    pattern: pattern || scenarioType,
    scenario_id: scenarioId,
    difficulty: difficulty,
    started_at: new Date().toISOString(),
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    // Guest sessions expire after 48 hours if not claimed
    expires_at: new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString(),
  }

  await setDoc(sessionRef, sessionData)
  return sessionRef.id
}

/**
 * Get a guest session by ID
 */
export async function getGuestSession(sessionId: string, guestId: string): Promise<any | null> {
  try {
    const sessionRef = doc(db, "interview_sessions", sessionId)
    const sessionSnap = await getDoc(sessionRef)

    if (!sessionSnap.exists()) return null

    const data = sessionSnap.data()

    // Verify this session belongs to the guest
    if (data.user_id !== guestId || !data.is_guest) {
      return null
    }

    return data
  } catch {
    return null
  }
}

/**
 * Update a guest interview session
 */
export async function updateGuestInterviewSession(
  sessionId: string,
  guestId: string,
  updateData: {
    performanceScore?: number
    feedback?: string
    code?: string
    language?: string
    testResults?: Array<any>
    timeComplexity?: string
    spaceComplexity?: string
    efficiencyScore?: number
  }
): Promise<boolean> {
  try {
    // First verify the session belongs to this guest
    const session = await getGuestSession(sessionId, guestId)
    if (!session) return false

    const sessionRef = doc(db, "interview_sessions", sessionId)
    const data: any = {
      updated_at: new Date().toISOString(),
    }

    if (updateData.performanceScore !== undefined) {
      data.performance_score = updateData.performanceScore
      data.completed_at = new Date().toISOString()
    }
    if (updateData.feedback) data.feedback = updateData.feedback
    if (updateData.code) data.final_code = updateData.code
    if (updateData.language) data.language = updateData.language
    if (updateData.testResults) {
      data.test_results = sanitizeTestResultsForFirestore(updateData.testResults)
      data.tests_passed = updateData.testResults.filter((t: any) => t.passed).length
      data.tests_total = updateData.testResults.length
    }
    if (updateData.timeComplexity) data.time_complexity = updateData.timeComplexity
    if (updateData.spaceComplexity) data.space_complexity = updateData.spaceComplexity
    if (updateData.efficiencyScore) data.efficiency_score = updateData.efficiencyScore

    await setDoc(sessionRef, data, { merge: true })
    return true
  } catch {
    return false
  }
}

/**
 * Migrate a guest session to an authenticated user
 * This transfers ownership from guest ID to user ID
 */
export async function migrateGuestSession(
  sessionId: string,
  guestId: string,
  newUserId: string
): Promise<boolean> {
  try {
    // Verify the session belongs to this guest
    const session = await getGuestSession(sessionId, guestId)
    if (!session) return false

    const sessionRef = doc(db, "interview_sessions", sessionId)
    await setDoc(
      sessionRef,
      {
        user_id: newUserId, // Transfer ownership
        is_guest: false, // No longer a guest session
        migrated_from_guest: guestId, // Keep track of original guest ID
        migrated_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
      { merge: true }
    )

    return true
  } catch {
    return false
  }
}

/**
 * Find all guest sessions for a guest ID
 * Used during migration to find all sessions to transfer
 */
export async function findGuestSessions(
  guestId: string
): Promise<Array<{ id: string; data: any }>> {
  try {
    const sessionsQuery = query(
      collection(db, "interview_sessions"),
      where("user_id", "==", guestId),
      where("is_guest", "==", true),
      limit(10) // Limit to prevent abuse
    )

    const snapshot = await getDocs(sessionsQuery)
    const sessions: Array<{ id: string; data: any }> = []

    snapshot.forEach((doc) => {
      sessions.push({
        id: doc.id,
        data: doc.data(),
      })
    })

    return sessions
  } catch {
    return []
  }
}

/**
 * Migrate all guest sessions to an authenticated user
 */
export async function migrateAllGuestSessions(
  guestId: string,
  newUserId: string
): Promise<{ migrated: number; failed: number }> {
  const sessions = await findGuestSessions(guestId)
  let migrated = 0
  let failed = 0

  for (const session of sessions) {
    const success = await migrateGuestSession(session.id, guestId, newUserId)
    if (success) {
      migrated++
    } else {
      failed++
    }
  }

  return { migrated, failed }
}

/**
 * Save session state for a guest session
 */
export async function saveGuestSessionState(
  sessionId: string,
  guestId: string,
  state: {
    code: string
    selectedLanguage: string
    elapsedTime: number
    chatMessages?: Array<{ type: string; message: string }>
    interviewerMessages?: Array<{ type: string; message: string }>
    testResults?: Array<any>
  }
): Promise<void> {
  try {
    // Verify this session belongs to the guest
    const session = await getGuestSession(sessionId, guestId)
    if (!session) return

    const sessionRef = doc(db, "interview_sessions", sessionId)
    await setDoc(
      sessionRef,
      {
        session_state: {
          code: state.code,
          language: state.selectedLanguage,
          elapsed_time: state.elapsedTime,
          chat_messages: state.chatMessages,
          interviewer_messages: state.interviewerMessages,
          test_results: state.testResults,
          saved_at: new Date().toISOString(),
        },
        updated_at: new Date().toISOString(),
      },
      { merge: true }
    )
  } catch {
    // Non-blocking - localStorage backup exists
  }
}

/**
 * Gemini Prompt Caching Utility
 *
 * Implements prompt caching for Google Gemini API to reduce costs and improve performance.
 * Caches frequently used system instructions to avoid re-sending them with every request.
 *
 * Benefits:
 * - Reduces input tokens by 80%+ for repeated system prompts
 * - Improves response times
 * - Significantly lowers API costs
 *
 * Note: This implementation uses in-memory caching as a simple optimization.
 * For production at scale, consider using Redis for distributed caching.
 */

import { GoogleGenerativeAI } from "@google/generative-ai"
import { logger } from "./logger"

const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY || "")

// Simple in-memory cache for system prompts
// This avoids re-instantiating models with the same system instructions
const modelCache = new Map<
  string,
  {
    model: any
    createdAt: Date
  }
>()

// Cache TTL: 1 hour
const CACHE_TTL_MS = 60 * 60 * 1000

/**
 * Simple hash function for cache key generation
 */
function simpleHash(str: string): string {
  let hash = 0
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i)
    hash = (hash << 5) - hash + char
    hash = hash & hash
  }
  return hash.toString(36)
}

/**
 * Get a Gemini model with system instructions
 * Uses in-memory caching to reuse model instances
 *
 * @param cacheKey Unique identifier for this model configuration
 * @param systemInstruction The system instruction to use
 * @param modelName The Gemini model to use (default: gemini-2.5-flash)
 * @returns Generative model instance
 */
export async function getCachedModel(
  cacheKey: string,
  systemInstruction: string,
  modelName: string = "gemini-2.5-flash"
) {
  // SECURITY FIX: Include systemInstruction hash AND modelName in cache key
  // This prevents returning a cached model with different instructions
  const fullCacheKey = `${cacheKey}:${simpleHash(systemInstruction)}:${modelName}`

  // Check if cached model exists and is not expired
  const cached = modelCache.get(fullCacheKey)
  const now = new Date()

  if (cached && now.getTime() - cached.createdAt.getTime() < CACHE_TTL_MS) {
    logger.debug("Using cached Gemini model", { cacheKey: fullCacheKey })
    return cached.model
  }

  try {
    // Note: Advanced caching with Gemini's cacheManager API is available but requires
    // additional setup. For now, we use simple model instance caching.
    // Future improvement: Implement full prompt caching when SDK supports it robustly.

    logger.debug("Creating new Gemini model instance", { cacheKey: fullCacheKey })

    const model = genAI.getGenerativeModel({
      model: modelName,
      systemInstruction: systemInstruction,
    })

    // Cache the model instance using fullCacheKey
    modelCache.set(fullCacheKey, {
      model,
      createdAt: now,
    })

    return model
  } catch (error) {
    logger.error("Failed to create Gemini model", { cacheKey: fullCacheKey, error })

    // Fallback: create model without caching
    logger.warn("Falling back to non-cached Gemini model", { cacheKey: fullCacheKey })
    return genAI.getGenerativeModel({
      model: modelName,
      systemInstruction: systemInstruction,
    })
  }
}

/**
 * Manually clear cache for a specific key
 * @param cacheKey Key to clear
 */
export function clearCache(cacheKey: string): void {
  modelCache.delete(cacheKey)
  logger.debug("Cleared Gemini cache", { cacheKey })
}

/**
 * Clear all cached content
 */
export function clearAllCaches(): void {
  modelCache.clear()
  logger.debug("Cleared all Gemini caches")
}

/**
 * Get cache statistics
 */
export function getCacheStats() {
  const now = new Date()
  const stats = {
    totalCached: modelCache.size,
    caches: Array.from(modelCache.entries()).map(([key, value]) => ({
      key,
      createdAt: value.createdAt.toISOString(),
      isExpired: now.getTime() - value.createdAt.getTime() >= CACHE_TTL_MS,
    })),
  }
  return stats
}

/**
 * Cleanup expired caches (run periodically)
 */
export function cleanupExpiredCaches(): void {
  const now = new Date()
  let removed = 0

  for (const [key, value] of modelCache.entries()) {
    if (now.getTime() - value.createdAt.getTime() >= CACHE_TTL_MS) {
      modelCache.delete(key)
      removed++
    }
  }

  if (removed > 0) {
    logger.debug("Cleaned up expired Gemini caches", { count: removed })
  }
}

// Auto-cleanup every 10 minutes
setInterval(cleanupExpiredCaches, 10 * 60 * 1000)

/**
 * Guest Session Management
 *
 * Allows users to try one free interview session without signing up.
 * Handles:
 * - Generating and storing temporary guest IDs
 * - Tracking free trial usage
 * - Session data persistence in localStorage
 * - Migration of guest session data to authenticated user
 */

// Storage keys
const GUEST_ID_KEY = 'mockmate_guest_id'
const FREE_TRIAL_USED_KEY = 'mockmate_free_trial_used'
const GUEST_SESSION_KEY = 'mockmate_guest_session'
const GUEST_SESSION_DATA_KEY = 'mockmate_guest_session_data'
const GUEST_SESSION_EXPIRY_KEY = 'mockmate_guest_session_expiry'

// Cookie names (for server-side detection)
const GUEST_ID_COOKIE = 'mockmate_guest_id'
const FREE_TRIAL_COOKIE = 'mockmate_free_trial'

// Session expiry configuration
const GUEST_SESSION_EXPIRY_DAYS = 7 // Sessions expire after 7 days

/**
 * Generate a UUID v4 for guest identification
 */
function generateUUID(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID()
  }
  // Fallback for older browsers
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0
    const v = c === 'x' ? r : (r & 0x3 | 0x8)
    return v.toString(16)
  })
}

/**
 * Set a cookie with the given name and value
 */
function setCookie(name: string, value: string, days: number = 2): void {
  if (typeof document === 'undefined') return
  const expires = new Date()
  expires.setTime(expires.getTime() + days * 24 * 60 * 60 * 1000)
  document.cookie = `${name}=${value}; path=/; expires=${expires.toUTCString()}; SameSite=Lax`
}

/**
 * Get a cookie value by name
 */
function getCookie(name: string): string | null {
  if (typeof document === 'undefined') return null
  const value = `; ${document.cookie}`
  const parts = value.split(`; ${name}=`)
  if (parts.length === 2) {
    return parts.pop()?.split(';').shift() || null
  }
  return null
}

/**
 * Delete a cookie by name
 */
function deleteCookie(name: string): void {
  if (typeof document === 'undefined') return
  document.cookie = `${name}=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT; SameSite=Lax`
}

// ============================================================================
// GUEST ID MANAGEMENT
// ============================================================================

/**
 * Get or create a guest ID
 * Persists in localStorage and cookie for cross-tab/session consistency
 */
export function getOrCreateGuestId(): string {
  if (typeof window === 'undefined') {
    return `guest-${generateUUID()}`
  }

  // Check localStorage first
  let guestId = localStorage.getItem(GUEST_ID_KEY)

  // Check cookie as backup
  if (!guestId) {
    guestId = getCookie(GUEST_ID_COOKIE)
  }

  // Generate new ID if none exists
  if (!guestId) {
    guestId = `guest-${generateUUID()}`
    localStorage.setItem(GUEST_ID_KEY, guestId)
    setCookie(GUEST_ID_COOKIE, guestId, 2) // 2 days expiry
  } else {
    // Sync between localStorage and cookie
    localStorage.setItem(GUEST_ID_KEY, guestId)
    setCookie(GUEST_ID_COOKIE, guestId, 2)
  }

  return guestId
}

/**
 * Get the current guest ID (without creating one)
 */
export function getGuestId(): string | null {
  if (typeof window === 'undefined') return null
  return localStorage.getItem(GUEST_ID_KEY) || getCookie(GUEST_ID_COOKIE)
}

/**
 * Check if a user ID is a guest ID
 */
export function isGuestId(userId: string | null | undefined): boolean {
  if (!userId) return false
  return userId.startsWith('guest-')
}

// ============================================================================
// FREE TRIAL MANAGEMENT
// ============================================================================

/**
 * Check if user has already used their free trial
 */
export function hasFreeTrialBeenUsed(): boolean {
  if (typeof window === 'undefined') return false

  // Check localStorage
  const localUsed = localStorage.getItem(FREE_TRIAL_USED_KEY) === 'true'

  // Check cookie as backup
  const cookieUsed = getCookie(FREE_TRIAL_COOKIE) === 'used'

  return localUsed || cookieUsed
}

/**
 * Mark the free trial as used
 */
export function markFreeTrialUsed(): void {
  if (typeof window === 'undefined') return

  localStorage.setItem(FREE_TRIAL_USED_KEY, 'true')
  setCookie(FREE_TRIAL_COOKIE, 'used', 30) // Longer expiry to prevent abuse
}

/**
 * Check if user can start a free trial session
 */
export function canStartFreeTrial(): boolean {
  return !hasFreeTrialBeenUsed()
}

// ============================================================================
// GUEST SESSION DATA MANAGEMENT
// ============================================================================

export interface GuestSessionData {
  sessionId: string
  scenarioId: string
  scenarioTitle: string
  startedAt: string
  code?: string
  language?: string
  elapsedTime?: number
  chatMessages?: Array<{ type: string; message: string }>
  interviewerMessages?: Array<{ type: string; message: string }>
  testResults?: Array<any>
  feedback?: {
    score: number
    summary: string
    feedbackData: any
  }
}

/**
 * Save guest session data to localStorage
 */
export function saveGuestSessionData(data: Partial<GuestSessionData>): void {
  if (typeof window === 'undefined') return

  const existing = getGuestSessionData()
  const updated = {
    ...existing,
    ...data,
    updatedAt: new Date().toISOString(),
  }

  localStorage.setItem(GUEST_SESSION_DATA_KEY, JSON.stringify(updated))
}

/**
 * Get guest session data from localStorage
 * Automatically cleans up expired sessions (older than 7 days)
 */
export function getGuestSessionData(): GuestSessionData | null {
  if (typeof window === 'undefined') return null

  const data = localStorage.getItem(GUEST_SESSION_DATA_KEY)
  if (!data) return null

  try {
    const sessionData = JSON.parse(data) as GuestSessionData

    // Check if session has expired (7 days from creation)
    const startedAt = new Date(sessionData.startedAt)
    const now = new Date()
    const daysSinceStart = (now.getTime() - startedAt.getTime()) / (1000 * 60 * 60 * 24)

    if (daysSinceStart > GUEST_SESSION_EXPIRY_DAYS) {
      // Session expired - clean it up
      clearGuestSessionData()
      console.log(`[Guest Session] Expired session cleaned up (${Math.floor(daysSinceStart)} days old)`)
      return null
    }

    return sessionData
  } catch {
    return null
  }
}

/**
 * Clear guest session data
 */
export function clearGuestSessionData(): void {
  if (typeof window === 'undefined') return
  localStorage.removeItem(GUEST_SESSION_DATA_KEY)
}

/**
 * Check if there's an active guest session
 */
export function hasActiveGuestSession(): boolean {
  const data = getGuestSessionData()
  if (!data) return false

  // Session is active if it was started within the last 24 hours and not completed
  const startedAt = new Date(data.startedAt)
  const now = new Date()
  const hoursSinceStart = (now.getTime() - startedAt.getTime()) / (1000 * 60 * 60)

  return hoursSinceStart < 24 && !data.feedback
}

// ============================================================================
// SESSION MIGRATION
// ============================================================================

/**
 * Get guest session data for migration to authenticated user
 * Returns data and clears it from local storage
 */
export function extractGuestSessionForMigration(): GuestSessionData | null {
  const data = getGuestSessionData()
  if (!data) return null

  // Keep the data in localStorage until migration is confirmed
  return data
}

/**
 * Confirm guest session migration completed
 * Clears all guest data from local storage
 */
export function confirmGuestSessionMigration(): void {
  if (typeof window === 'undefined') return

  // Clear all guest-related data
  localStorage.removeItem(GUEST_ID_KEY)
  localStorage.removeItem(GUEST_SESSION_DATA_KEY)
  // Keep FREE_TRIAL_USED_KEY to prevent re-abuse

  deleteCookie(GUEST_ID_COOKIE)
}

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

/**
 * Get guest authentication headers for API calls
 */
export function getGuestAuthHeaders(): Record<string, string> {
  const guestId = getGuestId()
  if (!guestId) return {}

  return {
    'X-Guest-Id': guestId,
  }
}

/**
 * Check if the current user is in guest mode (has guest ID but no auth)
 */
export function isInGuestMode(): boolean {
  const guestId = getGuestId()
  return !!guestId && canStartFreeTrial()
}

/**
 * Reset all guest data (for testing purposes)
 */
export function resetGuestData(): void {
  if (typeof window === 'undefined') return

  localStorage.removeItem(GUEST_ID_KEY)
  localStorage.removeItem(FREE_TRIAL_USED_KEY)
  localStorage.removeItem(GUEST_SESSION_KEY)
  localStorage.removeItem(GUEST_SESSION_DATA_KEY)

  deleteCookie(GUEST_ID_COOKIE)
  deleteCookie(FREE_TRIAL_COOKIE)
}

/**
 * Chat Tracking Hook
 *
 * Lightweight hook for tracking chat messages during interview sessions.
 * Sends messages to the session metrics API for scoring analysis.
 *
 * Usage:
 * const { trackMessage } = useChatTracking(sessionId)
 * trackMessage('user', 'I will use a hash map for O(1) lookup', 'interviewer')
 */

import { useCallback, useRef } from "react"
import { useAuth } from "@/lib/auth-context"

export type MessageType = "user" | "ai" | "system"
export type ChatType = "interviewer" | "partner"

interface TrackMessageParams {
  type: MessageType
  message: string
  chatType: ChatType
}

interface UseChatTrackingReturn {
  trackMessage: (type: MessageType, message: string, chatType: ChatType) => void
  trackUserMessage: (message: string, chatType: ChatType) => void
  trackAIMessage: (message: string, chatType: ChatType) => void
}

/**
 * Hook for tracking chat messages during interview sessions
 */
export function useChatTracking(sessionId: string | null): UseChatTrackingReturn {
  const { firebaseUser } = useAuth()
  const pendingRef = useRef<Map<string, boolean>>(new Map())

  const trackMessage = useCallback(
    async (type: MessageType, message: string, chatType: ChatType) => {
      if (!sessionId || !firebaseUser || !message.trim()) return

      // Dedupe: skip if we're already tracking this exact message
      const messageKey = `${type}-${chatType}-${message.slice(0, 50)}`
      if (pendingRef.current.has(messageKey)) return
      pendingRef.current.set(messageKey, true)

      try {
        const token = await firebaseUser.getIdToken()

        // Fire and forget - don't block the UI
        fetch("/api/session/metrics", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            event: "chat_message",
            sessionId,
            data: {
              type,
              message,
              chatType,
            },
          }),
        }).catch((err) => {
          console.error("[ChatTracking] Failed to track message:", err)
        })
      } catch (err) {
        console.error("[ChatTracking] Error getting token:", err)
      } finally {
        // Clean up after a delay
        setTimeout(() => {
          pendingRef.current.delete(messageKey)
        }, 1000)
      }
    },
    [sessionId, firebaseUser]
  )

  const trackUserMessage = useCallback(
    (message: string, chatType: ChatType) => {
      trackMessage("user", message, chatType)
    },
    [trackMessage]
  )

  const trackAIMessage = useCallback(
    (message: string, chatType: ChatType) => {
      trackMessage("ai", message, chatType)
    },
    [trackMessage]
  )

  return {
    trackMessage,
    trackUserMessage,
    trackAIMessage,
  }
}

export default useChatTracking

/**
 * Frontend hook for session metrics tracking
 *
 * Provides easy-to-use functions for tracking session events
 * from React components during interview sessions.
 */

import { useCallback, useRef } from "react"
import { useAuth } from "@/lib/auth-context"
import { logger } from "@/lib/logger"

interface SessionMetricsConfig {
  sessionId: string
  scenarioId: string
  scenarioTitle: string
  pattern: string
  difficulty: "easy" | "medium" | "hard"
  scenarioType?: "dsa" | "bugfix" | "system-design"
  hintsTotal?: number
}

interface UseSessionMetricsReturn {
  startTracking: (config: SessionMetricsConfig) => Promise<void>
  trackChatMessage: (
    type: "user" | "ai",
    message: string,
    chatType: "partner" | "interviewer"
  ) => void
  trackHintReveal: (hintIndex: number) => void
  trackCodeExecution: (
    passed: number,
    total: number,
    hasErrors?: boolean,
    executionTimeMs?: number
  ) => void
  trackFileView: (fileName: string) => void
  trackOptimizationAttempt: () => void
  trackAISuggestionApplied: (wasUnderstood: boolean) => void
  completeSession: (data: {
    finalCode: string
    language: string
    testsPassed: number
    testsTotal: number
    efficiencyScore: number
    communicationScore?: number
    thoughtProcessShared?: number
  }) => Promise<{ performanceScore: number; scoreBreakdown: any; feedback: any } | null>
  isTracking: boolean
}

export function useSessionMetrics(): UseSessionMetricsReturn {
  const { firebaseUser } = useAuth()
  const sessionIdRef = useRef<string | null>(null)
  const isTrackingRef = useRef(false)

  // Helper to make API calls
  const trackEvent = useCallback(
    async (event: string, data?: any) => {
      if (!firebaseUser || !sessionIdRef.current) return

      try {
        const token = await firebaseUser.getIdToken()
        await fetch("/api/session/metrics", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            event,
            sessionId: sessionIdRef.current,
            data,
          }),
        })
      } catch (error) {
        // Log error with proper context
        logger.error("[Session Metrics] Tracking error", {
          error,
          sessionId: sessionIdRef.current,
          eventType: event,
        })
      }
    },
    [firebaseUser]
  )

  const startTracking = useCallback(
    async (config: SessionMetricsConfig) => {
      if (!firebaseUser) return

      sessionIdRef.current = config.sessionId
      isTrackingRef.current = true

      try {
        const token = await firebaseUser.getIdToken()
        await fetch("/api/session/metrics", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            event: "session_start",
            sessionId: config.sessionId,
            data: {
              scenarioId: config.scenarioId,
              scenarioTitle: config.scenarioTitle,
              pattern: config.pattern,
              difficulty: config.difficulty,
              scenarioType: config.scenarioType || "dsa",
              hintsTotal: config.hintsTotal || 3,
            },
          }),
        })
      } catch (error) {
        logger.error("[Session Metrics] Failed to start tracking", {
          error,
          sessionId: config.sessionId,
        })
      }
    },
    [firebaseUser]
  )

  const trackChatMessage = useCallback(
    (type: "user" | "ai", message: string, chatType: "partner" | "interviewer") => {
      // Fire and forget - don't await
      trackEvent("chat_message", { type, message, chatType })
    },
    [trackEvent]
  )

  const trackHintReveal = useCallback(
    (hintIndex: number) => {
      trackEvent("hint_reveal", { hintIndex })
    },
    [trackEvent]
  )

  const trackCodeExecution = useCallback(
    (passed: number, total: number, hasErrors = false, executionTimeMs = 0) => {
      trackEvent("code_execution", { passed, total, hasErrors, executionTimeMs })
    },
    [trackEvent]
  )

  const trackFileView = useCallback(
    (fileName: string) => {
      trackEvent("file_view", { fileName })
    },
    [trackEvent]
  )

  const trackOptimizationAttempt = useCallback(() => {
    trackEvent("optimization_attempt")
  }, [trackEvent])

  const trackAISuggestionApplied = useCallback(
    (wasUnderstood: boolean) => {
      trackEvent("ai_suggestion_applied", { wasUnderstood })
    },
    [trackEvent]
  )

  const completeSession = useCallback(
    async (data: {
      finalCode: string
      language: string
      testsPassed: number
      testsTotal: number
      efficiencyScore: number
      communicationScore?: number
      thoughtProcessShared?: number
    }) => {
      if (!firebaseUser || !sessionIdRef.current) return null

      try {
        const token = await firebaseUser.getIdToken()
        const response = await fetch("/api/session/metrics", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            event: "session_complete",
            sessionId: sessionIdRef.current,
            data,
          }),
        })

        const result = await response.json()

        if (result.success) {
          isTrackingRef.current = false
          sessionIdRef.current = null
          return result.summary
        }

        return null
      } catch (error) {
        logger.error("[Session Metrics] Failed to complete session", {
          error,
          sessionId: sessionIdRef.current,
        })
        return null
      }
    },
    [firebaseUser]
  )

  return {
    startTracking,
    trackChatMessage,
    trackHintReveal,
    trackCodeExecution,
    trackFileView,
    trackOptimizationAttempt,
    trackAISuggestionApplied,
    completeSession,
    isTracking: isTrackingRef.current,
  }
}

export default useSessionMetrics

/**
 * Streaming Feedback Hook
 *
 * Connects to the Edge streaming endpoint and handles
 * Server-Sent Events (SSE) for real-time feedback updates.
 *
 * Flow:
 * 1. Connect to /api/feedback/stream (Edge runtime, no timeout)
 * 2. Receive instant scores immediately
 * 3. Receive refined scores after AI validation
 * 4. Receive full feedback at the end
 * 5. Call /api/feedback/persist to save to Firestore (Edge can't access Firebase)
 *
 * Events:
 * - phase: Current processing phase
 * - scores: Instant algorithmic scores
 * - refined_scores: AI-validated scores
 * - feedback: Full structured feedback
 * - error: Error occurred
 * - done: Stream complete
 */

import { useState, useCallback, useRef } from "react"
import { logger } from "@/lib/logger"

export interface StreamingScores {
  understanding: number
  problemSolving: number
  codeQuality: number
  communication: number
  overall: number
}

export interface SilentNote {
  type: string
  timestamp: number
  userSaid: string
  correct?: string
  context?: string
}

export interface StreamingFeedback {
  raw: string
  tldr: string
  whatWorked: string[]
  fixNext: string[]
  actionPlan: string[]
  silentNotes?: SilentNote[]
  bugfixEvidenceSummary?: unknown
  bugfixScoreBreakdown?: unknown
  bugfixPostSessionReport?: unknown
  scores: StreamingScores
}

export interface StreamingFeedbackState {
  // Connection state
  isConnected: boolean
  isComplete: boolean
  isPersisted: boolean // True after results are saved to Firestore

  // Current phase
  phase:
    | "idle"
    | "calculating_scores"
    | "analyzing"
    | "generating"
    | "persisting"
    | "complete"
    | "error"
  phaseMessage: string

  // Scores (instant first, then refined)
  instantScores: StreamingScores | null
  refinedScores: StreamingScores | null
  flags: {
    silentSolution: boolean
    incompleteSolution: boolean
    aiCopyingDetected: boolean
  } | null

  // Rich feedback (arrives at end)
  feedback: StreamingFeedback | null

  // Persisted scores (from Firestore save)
  masteryScore: number | null
  technicalScore: number | null

  // Error
  error: string | null
}

export interface StreamingFeedbackRequest {
  sessionId: string
  userId: string
  code: string
  language: string
  testsPassed: number
  testsTotal: number
  scenarioType?: string
  scenarioTitle?: string
  scenarioId?: string
  scenarioDifficulty?: string
  scenarioPattern?: string
  conversationTranscript?: unknown[]
  partnerMessages?: string[]
  phaseTracking?: unknown
  silentNotes?: unknown[]
  efficiencyMetrics?: unknown
  submittedFromPhase?: string
  testsRanBeforeSubmit?: boolean
  bugfixEvidenceEvents?: unknown[]
  bugfixExpectedTouchedFiles?: string[]
  bugfixHypothesis?: string
  bugfixRootCause?: string
  bugfixPrevention?: string
  bugfixRootCauseRubric?: string[]
  bugfixGroundTruth?: string
  // For mastery score calculation
  hintsUsed?: number
  elapsedTimeSeconds?: number
}

export function useStreamingFeedback() {
  const [state, setState] = useState<StreamingFeedbackState>({
    isConnected: false,
    isComplete: false,
    isPersisted: false,
    phase: "idle",
    phaseMessage: "",
    instantScores: null,
    refinedScores: null,
    flags: null,
    feedback: null,
    masteryScore: null,
    technicalScore: null,
    error: null,
  })

  const abortControllerRef = useRef<AbortController | null>(null)
  const requestRef = useRef<StreamingFeedbackRequest | null>(null)

  /**
   * Persist feedback to Firestore after streaming completes
   */
  const persistFeedback = useCallback(
    async (
      request: StreamingFeedbackRequest,
      scores: StreamingScores,
      feedback: StreamingFeedback
    ) => {
      setState((prev) => ({
        ...prev,
        phase: "persisting",
        phaseMessage: "Saving your results...",
      }))

      try {
        const response = await fetch("/api/feedback/persist", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            sessionId: request.sessionId,
            userId: request.userId,
            scores,
            feedback: {
              raw: feedback.raw,
              tldr: feedback.tldr,
              whatWorked: feedback.whatWorked,
              fixNext: feedback.fixNext,
              actionPlan: feedback.actionPlan,
            },
            // Include generated silent notes from streaming (takes precedence)
            silentNotes: feedback.silentNotes || request.silentNotes || [],
            bugfixEvidenceSummary: feedback.bugfixEvidenceSummary,
            bugfixScoreBreakdown: feedback.bugfixScoreBreakdown,
            bugfixPostSessionReport: feedback.bugfixPostSessionReport,
            testsPassed: request.testsPassed,
            testsTotal: request.testsTotal,
            timeSpentMinutes: Math.round((request.elapsedTimeSeconds || 1800) / 60),
            hintsUsed: request.hintsUsed || 0,
            difficulty: request.scenarioDifficulty || "medium",
            scenarioType: request.scenarioType || "dsa",
            scenarioTitle: request.scenarioTitle || "Unknown",
            scenarioId: request.scenarioId,
            scenarioPattern: request.scenarioPattern,
            conversationTranscript: request.conversationTranscript,
            efficiencyMetrics: request.efficiencyMetrics,
          }),
        })

        if (!response.ok) {
          throw new Error(`Persist failed: ${response.status}`)
        }

        const result = await response.json()

        setState((prev) => ({
          ...prev,
          isPersisted: true,
          phase: "complete",
          phaseMessage: "Done!",
          masteryScore: result.masteryScore,
          technicalScore: result.technicalScore,
        }))

        return result
      } catch (error) {
        logger.error("[StreamingFeedback] Persist failed:", { error })
        // Don't fail the whole flow if persist fails - feedback is still shown
        setState((prev) => ({
          ...prev,
          isPersisted: false,
          phase: "complete",
          phaseMessage: "Done!",
          error: "Results could not be saved. Your feedback is still available below.",
        }))
        return null
      }
    },
    []
  )

  /**
   * Start streaming feedback
   */
  const startStreaming = useCallback(
    async (request: StreamingFeedbackRequest) => {
      // Abort any existing connection
      if (abortControllerRef.current) {
        abortControllerRef.current.abort()
      }

      // Store request for persist call
      requestRef.current = request

      // Reset state
      setState({
        isConnected: true,
        isComplete: false,
        isPersisted: false,
        phase: "calculating_scores",
        phaseMessage: "Starting...",
        instantScores: null,
        refinedScores: null,
        flags: null,
        feedback: null,
        masteryScore: null,
        technicalScore: null,
        error: null,
      })

      const abortController = new AbortController()
      abortControllerRef.current = abortController

      // Variables to capture final state for persist
      let finalScores: StreamingScores | null = null
      let finalFeedback: StreamingFeedback | null = null

      try {
        const response = await fetch("/api/feedback/stream", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(request),
          signal: abortController.signal,
        })

        if (!response.ok) {
          throw new Error(`Stream failed: ${response.status}`)
        }

        const reader = response.body?.getReader()
        if (!reader) {
          throw new Error("No response body")
        }

        const decoder = new TextDecoder()
        let buffer = ""

        while (true) {
          const { done, value } = await reader.read()

          if (done) {
            break
          }

          buffer += decoder.decode(value, { stream: true })

          // Parse SSE events from buffer
          const lines = buffer.split("\n")
          buffer = lines.pop() || "" // Keep incomplete line in buffer

          let currentEvent = ""
          let currentData = ""

          for (const line of lines) {
            if (line.startsWith("event: ")) {
              currentEvent = line.slice(7)
            } else if (line.startsWith("data: ")) {
              currentData = line.slice(6)

              // Process complete event
              if (currentEvent && currentData) {
                try {
                  const data = JSON.parse(currentData)

                  // Capture final scores and feedback for persist
                  if (currentEvent === "refined_scores") {
                    finalScores = data as StreamingScores
                  } else if (currentEvent === "scores" && !finalScores) {
                    finalScores = data as StreamingScores
                  } else if (currentEvent === "feedback") {
                    finalFeedback = data as StreamingFeedback
                    // Also update finalScores from feedback if available
                    if ((data as StreamingFeedback).scores) {
                      finalScores = (data as StreamingFeedback).scores
                    }
                  }

                  handleEvent(currentEvent, data)
                } catch {
                  // Invalid JSON, skip
                }
                currentEvent = ""
                currentData = ""
              }
            }
          }
        }

        // After streaming completes, persist to Firestore
        if (finalScores && finalFeedback && requestRef.current) {
          await persistFeedback(requestRef.current, finalScores, finalFeedback)
        } else {
          // Streaming completed but missing data
          setState((prev) => ({
            ...prev,
            isConnected: false,
            isComplete: true,
            phase: "complete",
            error: finalFeedback ? null : "Feedback generation did not complete. Please try again.",
          }))
        }
      } catch (error) {
        if ((error as Error).name === "AbortError") {
          // User cancelled, don't treat as error
          return
        }

        logger.error("[StreamingFeedback] Stream failed:", { error })
        setState((prev) => ({
          ...prev,
          isConnected: false,
          phase: "error",
          error: "Something went wrong generating feedback. Please try again.",
        }))
      }
    },
    [persistFeedback]
  )

  /**
   * Handle incoming SSE events
   */
  const handleEvent = useCallback((event: string, data: unknown) => {
    switch (event) {
      case "phase":
        setState((prev) => ({
          ...prev,
          phase: (data as { phase: string }).phase as StreamingFeedbackState["phase"],
          phaseMessage: (data as { message: string }).message || "",
        }))
        break

      case "scores":
        setState((prev) => ({
          ...prev,
          instantScores: {
            understanding: (data as StreamingScores).understanding,
            problemSolving: (data as StreamingScores).problemSolving,
            codeQuality: (data as StreamingScores).codeQuality,
            communication: (data as StreamingScores).communication,
            overall: (data as StreamingScores).overall,
          },
          flags: (data as { flags: StreamingFeedbackState["flags"] }).flags || null,
        }))
        break

      case "refined_scores":
        setState((prev) => ({
          ...prev,
          refinedScores: {
            understanding: (data as StreamingScores).understanding,
            problemSolving: (data as StreamingScores).problemSolving,
            codeQuality: (data as StreamingScores).codeQuality,
            communication: (data as StreamingScores).communication,
            overall: (data as StreamingScores).overall,
          },
        }))
        break

      case "feedback":
        setState((prev) => ({
          ...prev,
          feedback: data as StreamingFeedback,
        }))
        break

      case "error":
        logger.error("[StreamingFeedback] Server error event:", { data })
        setState((prev) => ({
          ...prev,
          phase: "error",
          error: "Something went wrong generating feedback. Please try again.",
        }))
        break

      case "done":
        // Note: Don't set phase to "complete" here - wait for persist
        setState((prev) => ({
          ...prev,
          isConnected: false,
          isComplete: true,
          // Phase will be set to "complete" after persist succeeds
        }))
        break
    }
  }, [])

  /**
   * Cancel the stream
   */
  const cancel = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort()
      abortControllerRef.current = null
    }
    setState((prev) => ({
      ...prev,
      isConnected: false,
    }))
  }, [])

  /**
   * Reset state
   */
  const reset = useCallback(() => {
    cancel()
    requestRef.current = null
    setState({
      isConnected: false,
      isComplete: false,
      isPersisted: false,
      phase: "idle",
      phaseMessage: "",
      instantScores: null,
      refinedScores: null,
      flags: null,
      feedback: null,
      masteryScore: null,
      technicalScore: null,
      error: null,
    })
  }, [cancel])

  /**
   * Get best available scores (refined if available, otherwise instant)
   */
  const getBestScores = useCallback((): StreamingScores | null => {
    return state.refinedScores || state.instantScores
  }, [state.refinedScores, state.instantScores])

  return {
    state,
    startStreaming,
    cancel,
    reset,
    getBestScores,
  }
}

/**
 * Two-Phase Feedback Hook
 *
 * Implements the two-phase feedback flow:
 * 1. Instant: Get algorithmic scores immediately (< 3s)
 * 2. Rich: Poll for AI-generated narrative feedback
 *
 * This provides a much better UX than waiting 30+ seconds for feedback.
 */

import { useState, useCallback, useRef, useEffect } from "react"

export interface FeedbackScores {
  understanding: number
  problemSolving: number
  codeQuality: number
  communication: number
  overall: number
}

export interface StructuredFeedback {
  tldr: string
  whatWorked: string[]
  fixNext: string[]
  actionPlan: string[]
}

export interface TwoPhaseFeedbackState {
  // Phase tracking
  phase: "idle" | "instant" | "polling" | "complete" | "error"

  // Instant feedback (available immediately)
  instantScores: FeedbackScores | null
  instantFlags: {
    silentSolution: boolean
    incompleteSolution: boolean
    aiCopyingDetected: boolean
  } | null
  instantConfidence: "low" | "medium" | "high" | null

  // Rich feedback (available after polling)
  richFeedback: string | null
  richScores: FeedbackScores | null
  structuredFeedback: StructuredFeedback | null
  constitutionalAICritique: Record<string, unknown> | null

  // Technical score (for mastery)
  technicalScore: number | null

  // Job tracking
  jobId: string | null
  pollCount: number

  // Error handling
  error: string | null
}

export interface InstantFeedbackRequest {
  sessionId: string
  userId: string
  code: string
  language: string
  testsPassed: number
  testsTotal: number
  efficiencyScore?: number
  submittedFromPhase?: string
  testsRanBeforeSubmit?: boolean
  scenarioType?: "dsa" | "system-design" | "bugfix"
  scenarioTitle?: string
  scenarioId?: string
  scenarioDifficulty?: "easy" | "medium" | "hard"
  scenarioPattern?: string
  conversationTranscript?: unknown[]
  partnerMessages?: string[]
  phaseTracking?: unknown
  silentNotes?: unknown[]
  aiCollaborationMetrics?: unknown
  interactionMetrics?: unknown
  efficiencyMetrics?: unknown
  scenarioClarifyingQuestions?: string[]
  realInterviewMode?: boolean
}

const POLL_INTERVAL_MS = 2000 // Poll every 2 seconds
const MAX_POLL_COUNT = 90 // Max 3 minutes of polling (90 * 2s)

export function useTwoPhaseFeedback() {
  const [state, setState] = useState<TwoPhaseFeedbackState>({
    phase: "idle",
    instantScores: null,
    instantFlags: null,
    instantConfidence: null,
    richFeedback: null,
    richScores: null,
    structuredFeedback: null,
    constitutionalAICritique: null,
    technicalScore: null,
    jobId: null,
    pollCount: 0,
    error: null,
  })

  const pollIntervalRef = useRef<NodeJS.Timeout | null>(null)
  const isPollingRef = useRef(false)

  // Cleanup polling on unmount
  useEffect(() => {
    return () => {
      if (pollIntervalRef.current) {
        clearInterval(pollIntervalRef.current)
      }
    }
  }, [])

  /**
   * Start the two-phase feedback flow
   */
  const startFeedback = useCallback(async (request: InstantFeedbackRequest) => {
    // Reset state
    setState({
      phase: "instant",
      instantScores: null,
      instantFlags: null,
      instantConfidence: null,
      richFeedback: null,
      richScores: null,
      structuredFeedback: null,
      constitutionalAICritique: null,
      technicalScore: null,
      jobId: null,
      pollCount: 0,
      error: null,
    })

    try {
      // Phase 1: Get instant feedback
      const instantResponse = await fetch("/api/feedback/instant", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(request),
      })

      if (!instantResponse.ok) {
        throw new Error(`Instant feedback failed: ${instantResponse.status}`)
      }

      const instantData = await instantResponse.json()

      // Update state with instant scores
      setState((prev) => ({
        ...prev,
        phase: "polling",
        instantScores: instantData.scores,
        instantFlags: instantData.flags,
        instantConfidence: instantData.confidence,
        jobId: instantData.jobId,
        // Use instant overall as initial technical score
        technicalScore: Math.round(
          (instantData.scores.understanding +
            instantData.scores.problemSolving +
            instantData.scores.codeQuality) /
            3
        ),
      }))

      // Phase 2: Trigger background processing and start polling
      // Fire-and-forget the process request
      fetch("/api/feedback/process", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ jobId: instantData.jobId }),
      }).catch((err) => console.error("Background process trigger failed:", err))

      // Start polling for rich feedback
      startPolling(instantData.jobId)

      return instantData
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : "Failed to get feedback"
      setState((prev) => ({
        ...prev,
        phase: "error",
        error: errorMessage,
      }))
      throw error
    }
  }, [])

  /**
   * Poll for rich feedback completion
   */
  const startPolling = useCallback((jobId: string) => {
    if (isPollingRef.current) return
    isPollingRef.current = true

    const poll = async () => {
      try {
        const response = await fetch(`/api/feedback/status?jobId=${jobId}`)
        if (!response.ok) {
          throw new Error(`Status check failed: ${response.status}`)
        }

        const data = await response.json()

        setState((prev) => {
          const newPollCount = prev.pollCount + 1

          if (data.status === "complete" && data.result) {
            // Rich feedback is ready!
            if (pollIntervalRef.current) {
              clearInterval(pollIntervalRef.current)
              pollIntervalRef.current = null
            }
            isPollingRef.current = false

            return {
              ...prev,
              phase: "complete",
              richFeedback: data.result.feedback,
              richScores: data.result.scores,
              structuredFeedback: data.result.structured
                ? {
                    tldr: data.result.structured.tldr || "",
                    whatWorked: data.result.structured.whatWorked || [],
                    fixNext: data.result.structured.fixNext || [],
                    actionPlan: data.result.structured.actionPlan || [],
                  }
                : null,
              constitutionalAICritique: data.result.constitutionalAICritique || null,
              technicalScore: data.result.technicalScore || prev.technicalScore,
              pollCount: newPollCount,
            }
          }

          if (data.status === "failed") {
            if (pollIntervalRef.current) {
              clearInterval(pollIntervalRef.current)
              pollIntervalRef.current = null
            }
            isPollingRef.current = false

            // Keep instant scores, just note the error
            return {
              ...prev,
              phase: "complete", // Still "complete" - we have instant scores
              error: data.error || "Rich feedback generation failed",
              pollCount: newPollCount,
            }
          }

          // Check for timeout
          if (newPollCount >= MAX_POLL_COUNT) {
            if (pollIntervalRef.current) {
              clearInterval(pollIntervalRef.current)
              pollIntervalRef.current = null
            }
            isPollingRef.current = false

            return {
              ...prev,
              phase: "complete", // Still "complete" - we have instant scores
              error: "Rich feedback timed out",
              pollCount: newPollCount,
            }
          }

          // Still processing
          return {
            ...prev,
            pollCount: newPollCount,
          }
        })
      } catch (error) {
        console.error("Polling error:", error)
        // Don't stop polling on transient errors
        setState((prev) => ({
          ...prev,
          pollCount: prev.pollCount + 1,
        }))
      }
    }

    // Initial poll
    poll()

    // Set up interval
    pollIntervalRef.current = setInterval(poll, POLL_INTERVAL_MS)
  }, [])

  /**
   * Stop polling (e.g., if user navigates away)
   */
  const stopPolling = useCallback(() => {
    if (pollIntervalRef.current) {
      clearInterval(pollIntervalRef.current)
      pollIntervalRef.current = null
    }
    isPollingRef.current = false
  }, [])

  /**
   * Get the best available scores (rich if available, otherwise instant)
   */
  const getBestScores = useCallback((): FeedbackScores | null => {
    return state.richScores || state.instantScores
  }, [state.richScores, state.instantScores])

  /**
   * Get the best available feedback text
   */
  const getBestFeedback = useCallback((): string | null => {
    return state.richFeedback
  }, [state.richFeedback])

  /**
   * Check if we're still loading rich feedback
   */
  const isLoadingRich = useCallback((): boolean => {
    return state.phase === "polling"
  }, [state.phase])

  /**
   * Reset the feedback state
   */
  const reset = useCallback(() => {
    stopPolling()
    setState({
      phase: "idle",
      instantScores: null,
      instantFlags: null,
      instantConfidence: null,
      richFeedback: null,
      richScores: null,
      structuredFeedback: null,
      constitutionalAICritique: null,
      technicalScore: null,
      jobId: null,
      pollCount: 0,
      error: null,
    })
  }, [stopPolling])

  return {
    state,
    startFeedback,
    stopPolling,
    getBestScores,
    getBestFeedback,
    isLoadingRich,
    reset,
  }
}

/**
 * useCodeExecution Hook
 *
 * Manages code execution and test running functionality.
 */

import { useState, useCallback, useRef } from "react"
import { User as FirebaseUser } from "firebase/auth"
import { Scenario } from "@/lib/scenarios"
import { isExecutionServiceError } from "@/lib/piston"
import { executeScenarioInBrowser } from "@/lib/workspace-execution"

export interface TestResult {
  description: string
  passed: boolean
  input: any
  expected: any
  actual: any
  error: string | null
}

export interface EfficiencyMetrics {
  linesOfCode: number
  complexity: string
  estimatedTimeComplexity: string
  estimatedSpaceComplexity: string
  optimalTimeComplexity: string
  optimalSpaceComplexity: string
  efficiencyScore: number
}

export interface TestSummary {
  total: number
  passed: number
  failed: number
  passRate: number
}

export interface UseCodeExecutionOptions {
  firebaseUser: FirebaseUser | null
  userId: string | null
  sessionId?: string | null
}

export interface UseCodeExecutionReturn {
  // State
  testResults: TestResult[]
  isRunningTests: boolean
  testSummary: TestSummary
  efficiencyMetrics: EfficiencyMetrics | null

  // Actions
  runTests: (code: string, scenario: Scenario, language: string) => Promise<TestResult[]>
  clearResults: () => void
}

export function useCodeExecution({
  firebaseUser,
  userId,
  sessionId,
}: UseCodeExecutionOptions): UseCodeExecutionReturn {
  const [testResults, setTestResults] = useState<TestResult[]>([])
  const [isRunningTests, setIsRunningTests] = useState(false)
  const [testSummary, setTestSummary] = useState<TestSummary>({
    total: 0,
    passed: 0,
    failed: 0,
    passRate: 0,
  })
  const [efficiencyMetrics, setEfficiencyMetrics] = useState<EfficiencyMetrics | null>(null)

  const abortRef = useRef<AbortController | null>(null)

  const runTests = useCallback(
    async (code: string, scenario: Scenario, language: string): Promise<TestResult[]> => {
      if (!firebaseUser || !scenario) return []

      // Cancel any pending execution
      if (abortRef.current) {
        abortRef.current.abort()
      }
      abortRef.current = new AbortController()

      setIsRunningTests(true)
      setTestResults([])

      try {
        const browserResult = await executeScenarioInBrowser({ code, scenario, language })

        if (browserResult) {
          if (browserResult.error) {
            throw new Error(browserResult.error)
          }

          const results = browserResult.results as TestResult[]
          setTestResults(results)
          setTestSummary(browserResult.summary)
          return results
        }

        const token = await firebaseUser.getIdToken()

        const response = await fetch("/api/execute", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            code,
            language,
            testCases: "testCases" in scenario ? scenario.testCases : [],
            scenarioId: scenario.id,
            scenarioType: scenario.type,
            sessionId,
            userId,
          }),
          signal: abortRef.current.signal,
        })

        if (!response.ok) {
          const errorData = await response.json().catch(() => ({}))
          throw new Error(errorData.error || "Execution failed")
        }

        const data = await response.json()
        const results: TestResult[] = data.results || []

        setTestResults(results)

        // Calculate summary
        const passed = results.filter((r) => r.passed).length
        const total = results.length
        const failed = total - passed
        const passRate = total > 0 ? Math.round((passed / total) * 100) : 0

        setTestSummary({ total, passed, failed, passRate })

        // Set efficiency metrics if available
        if (data.efficiencyMetrics) {
          setEfficiencyMetrics(data.efficiencyMetrics)
        }

        return results
      } catch (err) {
        if (err instanceof Error && err.name === "AbortError") {
          return [] // Request was cancelled
        }

        const rawMessage = err instanceof Error ? err.message : "Unknown error occurred"
        const displayError = isExecutionServiceError(rawMessage)
          ? "Code execution service is temporarily unavailable. Please try again in a few minutes."
          : rawMessage

        const errorResult: TestResult = {
          description: "Execution Error",
          passed: false,
          input: null,
          expected: null,
          actual: null,
          error: displayError,
        }

        setTestResults([errorResult])
        setTestSummary({ total: 1, passed: 0, failed: 1, passRate: 0 })

        return [errorResult]
      } finally {
        setIsRunningTests(false)
      }
    },
    [firebaseUser, sessionId, userId]
  )

  const clearResults = useCallback(() => {
    // Cancel any pending execution
    if (abortRef.current) {
      abortRef.current.abort()
    }

    setTestResults([])
    setTestSummary({ total: 0, passed: 0, failed: 0, passRate: 0 })
    setEfficiencyMetrics(null)
  }, [])

  return {
    testResults,
    isRunningTests,
    testSummary,
    efficiencyMetrics,
    runTests,
    clearResults,
  }
}

"use client"

import { useState, useCallback, useRef, useEffect } from "react"
import type { GeneratedHint, HintLevel, StruggleMetrics, HintTrigger } from "@/lib/agents/hints"
import type {
  GenerateHintsPayload,
  GetNextHintPayload,
  GenerateHintsApiResponse,
  GetNextHintApiResponse,
} from "@/lib/agents/hints/contracts"
import type { DSAPattern } from "@/lib/types/dsa-patterns"
import { logger } from "@/lib/logger"

/**
 * useHintAgent Hook
 *
 * Client-side hook for interacting with the hint agent API.
 * Manages hint state, loading, and progressive reveal.
 *
 * Features:
 * - Automatic hint generation on problem load
 * - Struggle tracking for adaptive hints
 * - Progressive unlock based on time
 * - Optimistic UI updates
 */

interface UseHintAgentOptions {
  userId: string
  problemId: string
  problemTitle: string
  problemText: string
  problemPattern?: DSAPattern
  difficulty: "easy" | "medium" | "hard"
  staticHints?: string[]
  autoGenerate?: boolean
  getAuthToken?: () => Promise<string | null>
}

interface UseHintAgentReturn {
  // State
  hints: GeneratedHint[]
  staticHints: string[]
  isLoading: boolean
  error: string | null
  struggleLevel: "none" | "mild" | "moderate" | "high"
  recommendedLevel: HintLevel
  isPersonalized: boolean
  revealedHintIds: Set<string>
  elapsedMinutes: number

  // Actions
  generateHints: () => Promise<void>
  regenerateHints: (trigger: HintTrigger) => Promise<void>
  revealHint: (hintId: string) => void
  getNextHint: () => Promise<GeneratedHint | null>
  updateStruggleMetrics: (metrics: Partial<StruggleMetrics>) => void
  updateCode: (code: string) => void
  updateTestResults: (results: { passed: number; total: number; failingTests?: string[] }) => void
  resetHints: () => void
}

export function useHintAgent(options: UseHintAgentOptions): UseHintAgentReturn {
  const {
    userId,
    problemId,
    problemTitle,
    problemText,
    problemPattern,
    difficulty,
    staticHints = [],
    autoGenerate = true,
    getAuthToken,
  } = options

  // State
  const [hints, setHints] = useState<GeneratedHint[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [struggleLevel, setStruggleLevel] = useState<"none" | "mild" | "moderate" | "high">("none")
  const [recommendedLevel, setRecommendedLevel] = useState<HintLevel>(1)
  const [isPersonalized, setIsPersonalized] = useState(false)
  const [revealedHintIds, setRevealedHintIds] = useState<Set<string>>(new Set())
  const [elapsedMinutes, setElapsedMinutes] = useState(0)
  const [lastTrigger, setLastTrigger] = useState<HintTrigger>("initial")

  // Refs for tracking
  const struggleMetricsRef = useRef<StruggleMetrics>({
    timeSpentMinutes: 0,
    codeChanges: 0,
    testsRun: 0,
    testsFailed: 0,
    hintsRevealed: 0,
    lastCodeChangeMinutesAgo: 0,
    errorCount: 0,
  })

  const userCodeRef = useRef<string>("")
  const testResultsRef = useRef<
    { passed: number; total: number; failingTests?: string[] } | undefined
  >(undefined)
  const timerRef = useRef<NodeJS.Timeout | null>(null)
  const buildHeaders = useCallback(async (): Promise<HeadersInit> => {
    const token = getAuthToken ? await getAuthToken() : null
    return token
      ? { "Content-Type": "application/json", Authorization: `Bearer ${token}` }
      : { "Content-Type": "application/json" }
  }, [getAuthToken])

  const buildBasePayload = useCallback(
    () => ({
      userId,
      problemId,
      problemTitle,
      problemText,
      problemPattern,
      difficulty,
      userCode: userCodeRef.current,
      language: "javascript",
      struggleMetrics: struggleMetricsRef.current,
      testResults: testResultsRef.current,
    }),
    [userId, problemId, problemTitle, problemText, problemPattern, difficulty]
  )

  // Timer for elapsed time
  useEffect(() => {
    timerRef.current = setInterval(() => {
      setElapsedMinutes((prev) => {
        const newMinutes = prev + 1 / 60 // Update every second
        struggleMetricsRef.current.timeSpentMinutes = Math.floor(newMinutes)
        struggleMetricsRef.current.lastCodeChangeMinutesAgo += 1 / 60
        return newMinutes
      })
    }, 1000)

    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current)
      }
    }
  }, [])

  // Generate hints from API (internal, uses lastTrigger state)
  const generateHintsInternal = useCallback(
    async (trigger: HintTrigger = "initial") => {
      setIsLoading(true)
      setError(null)

      try {
        const payload: GenerateHintsPayload = {
          action: "generate",
          ...buildBasePayload(),
          existingHints: staticHints,
          trigger,
        }

        const headers = await buildHeaders()
        const response = await fetch("/api/agents/hints", {
          method: "POST",
          headers,
          body: JSON.stringify(payload),
        })

        if (!response.ok) {
          throw new Error("Failed to generate hints")
        }

        const data = (await response.json()) as GenerateHintsApiResponse

        setHints(data.hints || [])
        setStruggleLevel(data.struggleLevel || "none")
        setRecommendedLevel(data.recommendedRevealLevel || 1)
        setIsPersonalized(data.personalizationApplied || false)
      } catch (err) {
        logger.error("[useHintAgent] Generate error", { error: err, problemId, userId, trigger })
        setError(err instanceof Error ? err.message : "Failed to generate hints")
      } finally {
        setIsLoading(false)
      }
    },
    [buildBasePayload, buildHeaders, staticHints]
  )

  // Generate hints (for backwards compatibility, uses 'initial' trigger)
  const generateHints = useCallback(async () => {
    await generateHintsInternal("initial")
  }, [generateHintsInternal])

  // Regenerate hints with a specific trigger (event-driven)
  const regenerateHints = useCallback(
    async (trigger: HintTrigger) => {
      // Skip initial regeneration if no code written yet
      if (
        trigger === "initial" &&
        (!userCodeRef.current || userCodeRef.current.trim().length < 20)
      ) {
        return
      }

      setLastTrigger(trigger)
      await generateHintsInternal(trigger)
    },
    [generateHintsInternal]
  )

  // NOTE: We no longer auto-generate hints on mount.
  // Hints should be generated when user:
  // 1. Clicks "Get Hint" button
  // 2. Runs tests (test_failed/test_passed trigger)
  // 3. Is detected as stuck (stuck trigger)
  // 4. Makes significant code changes (code_change trigger)
  // This prevents showing hints before user has even read the problem.

  // Reveal a hint
  const revealHint = useCallback((hintId: string) => {
    setRevealedHintIds((prev) => {
      const newSet = new Set(prev)
      newSet.add(hintId)
      struggleMetricsRef.current.hintsRevealed = newSet.size
      return newSet
    })
  }, [])

  // Get the next unrevealed hint
  const getNextHint = useCallback(async (): Promise<GeneratedHint | null> => {
    setIsLoading(true)
    setError(null)

    try {
      const payload: GetNextHintPayload = {
        action: "get-next",
        ...buildBasePayload(),
        previousHintIds: Array.from(revealedHintIds),
      }

      const headers = await buildHeaders()
      const response = await fetch("/api/agents/hints", {
        method: "POST",
        headers,
        body: JSON.stringify(payload),
      })

      if (!response.ok) {
        throw new Error("Failed to get next hint")
      }

      const data = (await response.json()) as GetNextHintApiResponse

      if (data.hint) {
        const nextHint = data.hint
        // Add the new hint to the list
        setHints((prev) => {
          const exists = prev.some((h) => h.id === nextHint.id)
          if (exists) return prev
          return [...prev, nextHint]
        })
        return nextHint
      }

      return null
    } catch (err) {
      logger.error("[useHintAgent] Get next error", {
        error: err,
        problemId,
        userId,
        recommendedLevel,
      })
      setError(err instanceof Error ? err.message : "Failed to get next hint")
      return null
    } finally {
      setIsLoading(false)
    }
  }, [buildBasePayload, buildHeaders, revealedHintIds, problemId, recommendedLevel, userId])

  // Update struggle metrics
  const updateStruggleMetrics = useCallback((metrics: Partial<StruggleMetrics>) => {
    if (metrics.codeChanges !== undefined) {
      struggleMetricsRef.current.codeChanges = metrics.codeChanges
      struggleMetricsRef.current.lastCodeChangeMinutesAgo = 0
    }
    if (metrics.testsRun !== undefined) {
      struggleMetricsRef.current.testsRun = metrics.testsRun
    }
    if (metrics.testsFailed !== undefined) {
      struggleMetricsRef.current.testsFailed = metrics.testsFailed
    }
    if (metrics.errorCount !== undefined) {
      struggleMetricsRef.current.errorCount = metrics.errorCount
    }
  }, [])

  const updateCode = useCallback((code: string) => {
    userCodeRef.current = code
    struggleMetricsRef.current.codeChanges++
    struggleMetricsRef.current.lastCodeChangeMinutesAgo = 0
  }, [])

  const updateTestResults = useCallback(
    (results: { passed: number; total: number; failingTests?: string[] }) => {
      testResultsRef.current = results
      struggleMetricsRef.current.testsRun++
      if (results.passed < results.total) {
        struggleMetricsRef.current.testsFailed++
      }
    },
    []
  )

  // Reset hints
  const resetHints = useCallback(() => {
    setHints([])
    setRevealedHintIds(new Set())
    setStruggleLevel("none")
    setRecommendedLevel(1)
    setIsPersonalized(false)
    setError(null)
    setElapsedMinutes(0)
    struggleMetricsRef.current = {
      timeSpentMinutes: 0,
      codeChanges: 0,
      testsRun: 0,
      testsFailed: 0,
      hintsRevealed: 0,
      lastCodeChangeMinutesAgo: 0,
      errorCount: 0,
    }
  }, [])

  return {
    hints,
    staticHints,
    isLoading,
    error,
    struggleLevel,
    recommendedLevel,
    isPersonalized,
    revealedHintIds,
    elapsedMinutes,
    generateHints,
    regenerateHints,
    revealHint,
    getNextHint,
    updateStruggleMetrics,
    updateCode,
    updateTestResults,
    resetHints,
  }
}

export default useHintAgent

/**
 * useInterviewChat Hook
 *
 * Manages AI chat functionality for both:
 * - AI Partner (coding assistance)
 * - AI Interviewer (mock interview questions)
 */

import { useState, useCallback, useRef, useEffect } from "react"
import { User as FirebaseUser } from "firebase/auth"

export interface ChatMessage {
  type: "user" | "ai"
  message: string
}

export interface UseInterviewChatOptions {
  firebaseUser: FirebaseUser | null
  userId: string | null
  scenarioId?: string | null
  scenarioTitle?: string
  scenarioType?: string
  sessionId?: string | null
}

export interface UseInterviewChatReturn {
  // Partner chat state
  partnerMessages: ChatMessage[]
  partnerInput: string
  isLoadingPartner: boolean

  // Interviewer chat state
  interviewerMessages: ChatMessage[]
  interviewerInput: string
  isLoadingInterviewer: boolean

  // Actions
  setPartnerInput: (input: string) => void
  setInterviewerInput: (input: string) => void
  sendPartnerMessage: (
    code: string,
    workspaceContext?: Array<{ path: string; content: string }>
  ) => Promise<void>
  sendInterviewerMessage: (code: string) => Promise<void>
  clearChats: () => void
  setPartnerMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>
  setInterviewerMessages: React.Dispatch<React.SetStateAction<ChatMessage[]>>
}

export function useInterviewChat({
  firebaseUser,
  userId,
  scenarioId,
  scenarioTitle,
  scenarioType,
  sessionId,
}: UseInterviewChatOptions): UseInterviewChatReturn {
  // Partner chat state
  const [partnerMessages, setPartnerMessages] = useState<ChatMessage[]>([])
  const [partnerInput, setPartnerInput] = useState("")
  const [isLoadingPartner, setIsLoadingPartner] = useState(false)

  // Interviewer chat state
  const [interviewerMessages, setInterviewerMessages] = useState<ChatMessage[]>([])
  const [interviewerInput, setInterviewerInput] = useState("")
  const [isLoadingInterviewer, setIsLoadingInterviewer] = useState(false)

  // Abort controllers for cancelling requests
  const partnerAbortRef = useRef<AbortController | null>(null)
  const interviewerAbortRef = useRef<AbortController | null>(null)

  // Cleanup abort controllers on unmount to prevent memory leaks
  // and avoid setting state on unmounted components
  useEffect(() => {
    return () => {
      if (partnerAbortRef.current) {
        partnerAbortRef.current.abort()
      }
      if (interviewerAbortRef.current) {
        interviewerAbortRef.current.abort()
      }
    }
  }, [])

  const sendPartnerMessage = useCallback(
    async (code: string, workspaceContext?: Array<{ path: string; content: string }>) => {
      if (!partnerInput.trim() || !firebaseUser) return

      const userMessage = partnerInput.trim()
      setPartnerInput("")
      setPartnerMessages((prev) => [...prev, { type: "user", message: userMessage }])
      setIsLoadingPartner(true)

      // Cancel any pending request
      if (partnerAbortRef.current) {
        partnerAbortRef.current.abort()
      }
      partnerAbortRef.current = new AbortController()

      try {
        const token = await firebaseUser.getIdToken()

        const response = await fetch("/api/chat", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            message: userMessage,
            currentCode: code,
            role: "partner",
            userContext: {
              scenarioId,
              scenarioTitle,
              scenarioType,
            },
            workspaceContext,
            context: partnerMessages.slice(-10).map((m) => ({
              type: m.type === "user" ? "user" : "ai",
              message: m.message,
            })),
          }),
          signal: partnerAbortRef.current.signal,
        })

        if (!response.ok) {
          const body = await response
            .clone()
            .json()
            .catch(() => ({}))
          console.warn("[API] Request failed:", response.status, response.url, body)
          throw new Error(body?.message || body?.error || "Failed to get response")
        }

        const data = await response.json()
        setPartnerMessages((prev) => [...prev, { type: "ai", message: data.reply }])
      } catch (err) {
        if (err instanceof Error && err.name === "AbortError") {
          return // Request was cancelled
        }
        setPartnerMessages((prev) => [
          ...prev,
          { type: "ai", message: "Sorry, I encountered an error. Please try again." },
        ])
      } finally {
        setIsLoadingPartner(false)
      }
    },
    [partnerInput, firebaseUser, scenarioId, scenarioTitle, scenarioType, partnerMessages]
  )

  const sendInterviewerMessage = useCallback(
    async (code: string) => {
      if (!interviewerInput.trim() || !firebaseUser) return

      const userMessage = interviewerInput.trim()
      setInterviewerInput("")
      setInterviewerMessages((prev) => [...prev, { type: "user", message: userMessage }])
      setIsLoadingInterviewer(true)

      // Cancel any pending request
      if (interviewerAbortRef.current) {
        interviewerAbortRef.current.abort()
      }
      interviewerAbortRef.current = new AbortController()

      try {
        const token = await firebaseUser.getIdToken()

        const response = await fetch("/api/chat", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            message: userMessage,
            currentCode: code,
            role: "interviewer",
            userContext: {
              scenarioId,
              scenarioTitle,
              scenarioType,
            },
            context: interviewerMessages.slice(-10).map((m) => ({
              type: m.type === "user" ? "user" : "ai",
              message: m.message,
            })),
          }),
          signal: interviewerAbortRef.current.signal,
        })

        if (!response.ok) {
          const body = await response
            .clone()
            .json()
            .catch(() => ({}))
          console.warn("[API] Request failed:", response.status, response.url, body)
          throw new Error(body?.message || body?.error || "Failed to get response")
        }

        const data = await response.json()
        setInterviewerMessages((prev) => [...prev, { type: "ai", message: data.reply }])
      } catch (err) {
        if (err instanceof Error && err.name === "AbortError") {
          return // Request was cancelled
        }
        setInterviewerMessages((prev) => [
          ...prev,
          { type: "ai", message: "Sorry, I encountered an error. Please try again." },
        ])
      } finally {
        setIsLoadingInterviewer(false)
      }
    },
    [interviewerInput, firebaseUser, scenarioId, scenarioTitle, scenarioType, interviewerMessages]
  )

  const clearChats = useCallback(() => {
    // Cancel any pending requests
    if (partnerAbortRef.current) {
      partnerAbortRef.current.abort()
    }
    if (interviewerAbortRef.current) {
      interviewerAbortRef.current.abort()
    }

    setPartnerMessages([])
    setInterviewerMessages([])
    setPartnerInput("")
    setInterviewerInput("")
  }, [])

  return {
    partnerMessages,
    partnerInput,
    isLoadingPartner,
    interviewerMessages,
    interviewerInput,
    isLoadingInterviewer,
    setPartnerInput,
    setInterviewerInput,
    sendPartnerMessage,
    sendInterviewerMessage,
    clearChats,
    setPartnerMessages,
    setInterviewerMessages,
  }
}

/**
 * useInterviewPhase Hook
 *
 * Manages interview phase tracking using the conversation tracker
 * from lib/interview/interview-phases.ts
 */

import { useState, useCallback, useMemo } from "react"
import {
  type InterviewPhase,
  type ConversationTracker,
  type PhaseDetectionContext,
  createEmptyTracker,
  updateTrackerFromMessage,
  detectInterviewPhase,
  buildTrackingContext,
  getHintGuidance,
} from "@/lib/interview/interview-phases"
import { PHASE_PROMPTS } from "@/lib/interview/interviewer-prompts"
import {
  extractTopicsFromMessage,
  extractUserAnsweredTopics,
} from "@/lib/interview/topic-extraction"

export interface UseInterviewPhaseOptions {
  // Starter code length for comparison (passed from page)
  starterCodeLength?: number
}

export interface UseInterviewPhaseReturn {
  // State
  currentPhase: InterviewPhase
  conversationTracker: ConversationTracker
  recentNudgeTopics: string[]
  userAnsweredTopics: string[]
  testsHaveRun: boolean
  hasSubmitted: boolean

  // Derived values
  phasePrompt: string
  trackingContext: string
  hintGuidance: string

  // Actions
  updateFromUserMessage: (message: string) => void
  updateFromInterviewerMessage: (message: string) => void
  markTestsRun: (allPassed: boolean) => void
  markSubmitted: () => void
  updateCodeLength: (length: number) => void
  reset: () => void
}

export function useInterviewPhase(options: UseInterviewPhaseOptions = {}): UseInterviewPhaseReturn {
  const { starterCodeLength = 0 } = options

  const [conversationTracker, setConversationTracker] =
    useState<ConversationTracker>(createEmptyTracker())
  const [recentNudgeTopics, setRecentNudgeTopics] = useState<string[]>([])
  const [userAnsweredTopics, setUserAnsweredTopics] = useState<string[]>([])
  const [hasSubmitted, setHasSubmitted] = useState(false)
  const [testsHaveRun, setTestsHaveRun] = useState(false)
  const [currentCodeLength, setCurrentCodeLength] = useState(starterCodeLength)
  const [messageCount, setMessageCount] = useState(0)

  // Derive current phase using DETERMINISTIC signals
  // No regex - just button clicks, code length, and LLM extraction results
  const currentPhase = useMemo(() => {
    const context: PhaseDetectionContext = {
      hasSubmitted,
      testsHaveRun,
      currentCodeLength,
      starterCodeLength,
      approachExplained: conversationTracker.approachExplained,
      messageCount,
    }
    return detectInterviewPhase(context)
  }, [
    hasSubmitted,
    testsHaveRun,
    currentCodeLength,
    starterCodeLength,
    conversationTracker.approachExplained,
    messageCount,
  ])

  // Get phase-specific prompt
  const phasePrompt = useMemo(() => {
    return PHASE_PROMPTS[currentPhase]
  }, [currentPhase])

  // Get tracking context for AI prompt
  const trackingContext = useMemo(() => {
    return buildTrackingContext(conversationTracker)
  }, [conversationTracker])

  // Get hint guidance based on hints given
  const hintGuidance = useMemo(() => {
    return getHintGuidance(conversationTracker.hintsGiven)
  }, [conversationTracker.hintsGiven])

  const updateFromUserMessage = useCallback((message: string) => {
    setMessageCount((prev) => prev + 1)

    // Update conversation tracker
    setConversationTracker((prev) => updateTrackerFromMessage(prev, message, "user"))

    // Extract and track topics the user has answered
    const answeredTopics = extractUserAnsweredTopics(message)
    if (answeredTopics.length > 0) {
      setUserAnsweredTopics((prev) => [...new Set([...prev, ...answeredTopics])])
    }
  }, [])

  const updateFromInterviewerMessage = useCallback((message: string) => {
    setMessageCount((prev) => prev + 1)

    // Update conversation tracker
    setConversationTracker((prev) => updateTrackerFromMessage(prev, message, "interviewer"))

    // Extract topics from interviewer message to track what was asked
    const topics = extractTopicsFromMessage(message)
    if (topics.length > 0) {
      setRecentNudgeTopics((prev) => [...new Set([...prev, ...topics])])
    }
  }, [])

  const markTestsRun = useCallback((allPassed: boolean) => {
    setTestsHaveRun(true)
    // Also update tracker for compatibility
    setConversationTracker((prev) => ({
      ...prev,
      hasRunTests: true,
    }))
  }, [])

  const markSubmitted = useCallback(() => {
    setHasSubmitted(true)
  }, [])

  const updateCodeLength = useCallback((length: number) => {
    setCurrentCodeLength(length)
  }, [])

  const reset = useCallback(() => {
    setConversationTracker(createEmptyTracker())
    setRecentNudgeTopics([])
    setUserAnsweredTopics([])
    setHasSubmitted(false)
    setTestsHaveRun(false)
    setCurrentCodeLength(starterCodeLength)
    setMessageCount(0)
  }, [starterCodeLength])

  return {
    currentPhase,
    conversationTracker,
    recentNudgeTopics,
    userAnsweredTopics,
    testsHaveRun,
    hasSubmitted,
    phasePrompt,
    trackingContext,
    hintGuidance,
    updateFromUserMessage,
    updateFromInterviewerMessage,
    markTestsRun,
    markSubmitted,
    updateCodeLength,
    reset,
  }
}

/**
 * useInterviewSession Hook
 *
 * Manages the core interview session state including:
 * - Session lifecycle (start, end)
 * - Timer management
 * - Scenario selection
 * - Auto-save functionality
 */

import { useState, useEffect, useCallback, useRef } from "react"
import { User as FirebaseUser } from "firebase/auth"
import { Scenario, getScenarioById } from "@/lib/scenarios"
import {
  recordSessionStart,
  createInterviewSession,
  updateInterviewSession,
  saveSessionState,
  getSessionState,
  checkSessionCost,
} from "@/lib/firestore-helpers"
import { toast } from "sonner"

export interface SessionState {
  code: string
  selectedLanguage: string
  elapsedTime: number
  chatMessages?: Array<{ type: string; message: string }>
  interviewerMessages?: Array<{ type: string; message: string }>
  testResults?: Array<any>
}

export interface UseInterviewSessionOptions {
  firebaseUser: FirebaseUser | null
  userId: string | null
  initialSessionId?: string | null
  initialScenarioId?: string | null
  onSessionRestored?: (state: SessionState) => void
}

export interface UseInterviewSessionReturn {
  // State
  selectedScenario: Scenario | null
  isInterviewStarted: boolean
  currentSessionId: string | null
  elapsedTime: number
  startTime: number | null

  // Actions
  selectScenario: (scenario: Scenario) => void
  startInterview: () => Promise<boolean>
  endInterview: (performanceScore?: number, feedback?: string) => Promise<void>
  saveState: (state: Partial<SessionState>) => Promise<void>

  // Status
  isLoading: boolean
  error: string | null
}

export function useInterviewSession({
  firebaseUser,
  userId,
  initialSessionId,
  initialScenarioId,
  onSessionRestored,
}: UseInterviewSessionOptions): UseInterviewSessionReturn {
  const [selectedScenario, setSelectedScenario] = useState<Scenario | null>(null)
  const [isInterviewStarted, setIsInterviewStarted] = useState(false)
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(initialSessionId || null)
  const [elapsedTime, setElapsedTime] = useState(0)
  const [startTime, setStartTime] = useState<number | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const timerRef = useRef<NodeJS.Timeout | null>(null)
  const autoSaveRef = useRef<NodeJS.Timeout | null>(null)
  const lastSaveStateRef = useRef<Partial<SessionState>>({})

  // Timer effect
  useEffect(() => {
    if (isInterviewStarted && startTime) {
      timerRef.current = setInterval(() => {
        setElapsedTime(Math.floor((Date.now() - startTime) / 1000))
      }, 1000)
    }

    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current)
      }
    }
  }, [isInterviewStarted, startTime])

  // Restore session from URL params
  useEffect(() => {
    const restoreSession = async () => {
      if (!initialSessionId || !initialScenarioId || !firebaseUser) return

      setIsLoading(true)
      try {
        // Get scenario
        const scenario = getScenarioById(initialScenarioId)
        if (!scenario) {
          setError("Scenario not found")
          return
        }

        // Get session state
        const savedState = await getSessionState(initialSessionId)
        if (savedState) {
          setSelectedScenario(scenario)
          setCurrentSessionId(initialSessionId)
          setIsInterviewStarted(true)
          setStartTime(Date.now() - (savedState.elapsedTime || 0) * 1000)

          // Notify parent of restored state
          onSessionRestored?.({
            code: savedState.code || "",
            selectedLanguage: savedState.language || "javascript",
            elapsedTime: savedState.elapsedTime || 0,
            chatMessages: savedState.chatMessages,
            interviewerMessages: savedState.interviewerMessages,
            testResults: savedState.testResults,
          })
        }
      } catch {
        setError("Failed to restore session")
      } finally {
        setIsLoading(false)
      }
    }

    restoreSession()
  }, [initialSessionId, initialScenarioId, firebaseUser, onSessionRestored])

  const selectScenario = useCallback((scenario: Scenario) => {
    setSelectedScenario(scenario)
    setError(null)
  }, [])

  const startInterview = useCallback(async (): Promise<boolean> => {
    if (!firebaseUser || !userId || !selectedScenario) {
      setError("Missing required data to start interview")
      return false
    }

    setIsLoading(true)
    setError(null)

    try {
      // Check session cost
      const costCheck = await checkSessionCost(userId)

      if (!costCheck.allowed) {
        toast.error("Session limit reached", {
          description: costCheck.reason,
        })
        return false
      }

      // Record session start
      await recordSessionStart(userId)

      // Create session in Firestore
      // Include pattern for stats aggregation (used by dashboard Performance Insights)
      const scenarioPattern =
        ("pattern" in selectedScenario ? selectedScenario.pattern : selectedScenario.type) ||
        "unknown"
      const sessionId = await createInterviewSession(
        userId,
        selectedScenario.title,
        selectedScenario.type,
        selectedScenario.difficulty,
        selectedScenario.id,
        scenarioPattern
      )

      setCurrentSessionId(sessionId)
      setIsInterviewStarted(true)
      setStartTime(Date.now())
      setElapsedTime(0)

      return true
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to start interview"
      setError(message)
      toast.error(message)
      return false
    } finally {
      setIsLoading(false)
    }
  }, [firebaseUser, userId, selectedScenario])

  const endInterview = useCallback(
    async (performanceScore?: number, feedback?: string) => {
      if (!currentSessionId) return

      try {
        await updateInterviewSession(
          currentSessionId,
          performanceScore,
          feedback,
          // Only mark as complete if we have actual feedback
          feedback ? { feedbackStatus: "complete" } : undefined
        )

        // Clear timer
        if (timerRef.current) {
          clearInterval(timerRef.current)
        }

        // Clear auto-save
        if (autoSaveRef.current) {
          clearInterval(autoSaveRef.current)
        }
      } catch {
        // Non-critical error
      }
    },
    [currentSessionId]
  )

  const saveState = useCallback(
    async (state: Partial<SessionState>) => {
      if (!currentSessionId) return

      // Merge with last state
      const mergedState = { ...lastSaveStateRef.current, ...state }
      lastSaveStateRef.current = mergedState

      try {
        await saveSessionState(currentSessionId, {
          code: mergedState.code || "",
          selectedLanguage: mergedState.selectedLanguage || "javascript",
          elapsedTime: mergedState.elapsedTime || elapsedTime,
          chatMessages: mergedState.chatMessages,
          interviewerMessages: mergedState.interviewerMessages,
          testResults: mergedState.testResults,
        })
      } catch {
        // Non-critical - localStorage backup exists
      }
    },
    [currentSessionId, elapsedTime]
  )

  return {
    selectedScenario,
    isInterviewStarted,
    currentSessionId,
    elapsedTime,
    startTime,
    selectScenario,
    startInterview,
    endInterview,
    saveState,
    isLoading,
    error,
  }
}

/**
