export function useInterviewState({
  firebaseUser,
  userId,
}: UseInterviewStateOptions): UseInterviewStateReturn {
  // Session state
  const [selectedScenario, setSelectedScenario] = useState<Scenario | null>(null)
  const [isInterviewStarted, setIsInterviewStarted] = useState(false)
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null)

  // Code state
  const [code, setCode] = useState("")
  const [selectedLanguage, setSelectedLanguage] = useState<"javascript" | "typescript" | "python" | "java" | "cpp" | "csharp" | "go" | "rust">("javascript")
  const [starterCode, setStarterCode] = useState<string>("")
  const [protectedElements, setProtectedElements] = useState<any>(null)

  // Timer state
  const [startTime, setStartTime] = useState<number | null>(null)
  const [elapsedTime, setElapsedTime] = useState(0)

  // Chat state
  const [interviewerMessages, setInterviewerMessages] = useState<ChatMessage[]>([])
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([])
  const [chatInput, setChatInput] = useState("")
  const [interviewerInput, setInterviewerInput] = useState("")
  const [isLoadingChat, setIsLoadingChat] = useState(false)
  const [isLoadingInterviewer, setIsLoadingInterviewer] = useState(false)

  // Test state
  const [testResults, setTestResults] = useState<TestResult[]>([])
  const [consoleLogs, setConsoleLogs] = useState<Array<{ type: string; message: string; timestamp: number }>>([])
  const [isRunningTests, setIsRunningTests] = useState(false)
  const [testSummary, setTestSummary] = useState({ total: 0, passed: 0, failed: 0, passRate: 0 })
  const [efficiencyMetrics, setEfficiencyMetrics] = useState<EfficiencyMetrics | null>(null)

  // Feedback state
  const [showFeedback, setShowFeedback] = useState(false)
  const [showPostInterviewDiscussion, setShowPostInterviewDiscussion] = useState(false)
  const [comprehensiveFeedback, setComprehensiveFeedback] = useState<string>("")
  const [performanceScore, setPerformanceScore] = useState<number | null>(null)
  const [constitutionalAICritique, setConstitutionalAICritique] = useState<any>(null)
  const [isGeneratingFeedback, setIsGeneratingFeedback] = useState(false)
  const [isGeneratingDiscussion, setIsGeneratingDiscussion] = useState(false)

  // Hints state
  const [revealedHints, setRevealedHints] = useState<number>(0)
  const [revealedHintIndices, setRevealedHintIndices] = useState<Set<number>>(new Set())
  const [ragHints, setRagHints] = useState<Array<{ level: number; hint: string }>>([])
  const [isLoadingHints, setIsLoadingHints] = useState(false)

  // Workspace state
  const [workspaceContext, setWorkspaceContext] = useState<Array<{ path: string; content: string; description?: string }>>([])

  // Guest mode state
  const [isGuestMode, setIsGuestMode] = useState(false)
  const [guestId, setGuestId] = useState<string | null>(null)

  // Completed problems
  const [completedProblems, setCompletedProblems] = useState<string[]>([])

  // Refs
  const lastCodeHashRef = useRef<string>("")
  const previousCodeRef = useRef<string>(code)
  const lastCodeChangeRef = useRef<number>(Date.now())
  const lastInterviewerMessageRef = useRef<number>(Date.now())
  const hasTriggeredInactivityRef = useRef<boolean>(false)
  const hasTriggeredSilenceRef = useRef<boolean>(false)

  // Initialize guest mode if needed
  useEffect(() => {
    if (!firebaseUser) {
      const canTrial = canStartFreeTrial()
      if (canTrial) {
        const gId = getOrCreateGuestId()
        setGuestId(gId)
        setIsGuestMode(true)
      }
    } else {
      // Authenticated user - disable guest mode
      setIsGuestMode(false)
      setGuestId(null)
    }
  }, [firebaseUser])

  // Timer effect
  useEffect(() => {
    let interval: NodeJS.Timeout
    if (isInterviewStarted && !showFeedback && startTime) {
      interval = setInterval(() => {
        setElapsedTime(Math.floor((Date.now() - startTime) / 1000))
      }, 1000)
    }
    return () => clearInterval(interval)
  }, [isInterviewStarted, showFeedback, startTime])

  // Track code changes
  useEffect(() => {
    if (previousCodeRef.current !== code) {
      previousCodeRef.current = code
    }
  }, [code])

  // Reset all state
  const resetAllState = () => {
    setIsInterviewStarted(false)
    setShowFeedback(false)
    setShowPostInterviewDiscussion(false)
    setComprehensiveFeedback("")
    setPerformanceScore(null)
    setIsGeneratingDiscussion(false)
    setCode("")
    setInterviewerMessages([])
    setChatMessages([])
    setTestResults([])
    setTestSummary({ total: 0, passed: 0, failed: 0, passRate: 0 })
    setStartTime(null)
    setElapsedTime(0)
    lastCodeHashRef.current = ""
    setCurrentSessionId(null)
    setRevealedHints(0)
    setRevealedHintIndices(new Set())
    setRagHints([])
    setWorkspaceContext([])
    setEfficiencyMetrics(null)
    setProtectedElements(null)
    setStarterCode("")
    hasTriggeredInactivityRef.current = false
    hasTriggeredSilenceRef.current = false
    lastCodeChangeRef.current = Date.now()
    lastInterviewerMessageRef.current = Date.now()
  }

  return {
    selectedScenario,
    setSelectedScenario,
    isInterviewStarted,
    setIsInterviewStarted,
    currentSessionId,
    setCurrentSessionId,
    code,
    setCode,
    selectedLanguage,
    setSelectedLanguage,
    starterCode,
    setStarterCode,
    protectedElements,
    setProtectedElements,
    startTime,
    setStartTime,
    elapsedTime,
    setElapsedTime,
    interviewerMessages,
    setInterviewerMessages,
    chatMessages,
    setChatMessages,
    chatInput,
    setChatInput,
    interviewerInput,
    setInterviewerInput,
    isLoadingChat,
    setIsLoadingChat,
    isLoadingInterviewer,
    setIsLoadingInterviewer,
    testResults,
    setTestResults,
    consoleLogs,
    setConsoleLogs,
    isRunningTests,
    setIsRunningTests,
    testSummary,
    setTestSummary,
    efficiencyMetrics,
    setEfficiencyMetrics,
    showFeedback,
    setShowFeedback,
    showPostInterviewDiscussion,
    setShowPostInterviewDiscussion,
    comprehensiveFeedback,
    setComprehensiveFeedback,
    performanceScore,
    setPerformanceScore,
    constitutionalAICritique,
    setConstitutionalAICritique,
    isGeneratingFeedback,
    setIsGeneratingFeedback,
    isGeneratingDiscussion,
    setIsGeneratingDiscussion,
    revealedHints,
    setRevealedHints,
    revealedHintIndices,
    setRevealedHintIndices,
    ragHints,
    setRagHints,
    isLoadingHints,
    setIsLoadingHints,
    workspaceContext,
    setWorkspaceContext,
    isGuestMode,
    setIsGuestMode,
    guestId,
    setGuestId,
    lastCodeHashRef,
    previousCodeRef,
    lastCodeChangeRef,
    lastInterviewerMessageRef,
    hasTriggeredInactivityRef,
    hasTriggeredSilenceRef,
    completedProblems,
    setCompletedProblems,
    resetAllState,
  }
}

/**
 * useInterviewUI Hook
 *
 * Manages UI-related state including:
 * - Panel visibility and modes
 * - Dialog states
 * - Focus mode and accessibility features
 * - Mobile panel switcher
 */

import { useState, useEffect } from "react"

export interface UseInterviewUIOptions {
  isInterviewStarted?: boolean
}

export interface UseInterviewUIReturn {
  // Browser and main views
  showScenarioBrowser: boolean
  setShowScenarioBrowser: (show: boolean) => void

  // Dialog states
  showCloseDialog: boolean
  setShowCloseDialog: (show: boolean) => void
  showSignupPrompt: boolean
  setShowSignupPrompt: (show: boolean) => void
  showCodeInDiscussion: boolean
  setShowCodeInDiscussion: (show: boolean) => void

  // Code viewer
  selectedFile: { path: string; content: string } | null
  setSelectedFile: (file: { path: string; content: string } | null) => void
  isCodeViewerOpen: boolean
  setIsCodeViewerOpen: (open: boolean) => void

  // AI tips and hints
  showAITips: boolean
  setShowAITips: (show: boolean) => void
  isAIPartnerExpanded: boolean
  setIsAIPartnerExpanded: (expanded: boolean) => void

  // Accessibility and focus modes
  focusMode: boolean
  setFocusMode: (mode: boolean) => void
  calmMode: boolean
  setCalmMode: (mode: boolean) => void
  hideTimer: boolean
  setHideTimer: (hide: boolean) => void
  showProblemPeek: boolean
  setShowProblemPeek: (show: boolean) => void

  // Mobile panel switcher
  activePanel: "problem" | "editor" | "chat"
  setActivePanel: (panel: "problem" | "editor" | "chat") => void
}

export function useInterviewUI({
  isInterviewStarted = false,
}: UseInterviewUIOptions = {}): UseInterviewUIReturn {
  // Browser and main views
  const [showScenarioBrowser, setShowScenarioBrowser] = useState(true)

  // Dialog states
  const [showCloseDialog, setShowCloseDialog] = useState(false)
  const [showSignupPrompt, setShowSignupPrompt] = useState(false)
  const [showCodeInDiscussion, setShowCodeInDiscussion] = useState(false)

  // Code viewer
  const [selectedFile, setSelectedFile] = useState<{ path: string; content: string } | null>(null)
  const [isCodeViewerOpen, setIsCodeViewerOpen] = useState(false)

  // AI tips and hints
  const [showAITips, setShowAITips] = useState(false)
  const [isAIPartnerExpanded, setIsAIPartnerExpanded] = useState(false)

  // Accessibility and focus modes
  const [focusMode, setFocusMode] = useState(false)
  const [calmMode, setCalmMode] = useState(false)
  const [hideTimer, setHideTimer] = useState(false)
  const [showProblemPeek, setShowProblemPeek] = useState(false)

  // Mobile panel switcher
  const [activePanel, setActivePanel] = useState<"problem" | "editor" | "chat">("editor")

  // Toggle calm mode on document for CSS cascade
  useEffect(() => {
    if (calmMode) {
      document.documentElement.classList.add("calm")
    } else {
      document.documentElement.classList.remove("calm")
    }
    return () => document.documentElement.classList.remove("calm")
  }, [calmMode])

  // Toggle focus mode class on document for CSS cascade
  useEffect(() => {
    if (focusMode) {
      document.documentElement.classList.add("focus-mode-active")
    } else {
      document.documentElement.classList.remove("focus-mode-active")
      setShowProblemPeek(false) // Close peek when exiting focus mode
    }
    return () => document.documentElement.classList.remove("focus-mode-active")
  }, [focusMode])

  return {
    showScenarioBrowser,
    setShowScenarioBrowser,
    showCloseDialog,
    setShowCloseDialog,
    showSignupPrompt,
    setShowSignupPrompt,
    showCodeInDiscussion,
    setShowCodeInDiscussion,
    selectedFile,
    setSelectedFile,
    isCodeViewerOpen,
    setIsCodeViewerOpen,
    showAITips,
    setShowAITips,
    isAIPartnerExpanded,
    setIsAIPartnerExpanded,
    focusMode,
    setFocusMode,
    calmMode,
    setCalmMode,
    hideTimer,
    setHideTimer,
    showProblemPeek,
    setShowProblemPeek,
    activePanel,
    setActivePanel,
  }
}

/**
 * useNotifications Hook
 *
 * React hook for managing notifications in the UI.
 * Provides:
 * - Real-time notification fetching
 * - Read/unread state management
 * - Preference updates
 * - Notification actions
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { useAuth } from '@/lib/auth-context'
import type { InAppNotification, NotificationPreferences } from '@/lib/types/notifications'
import type { NotificationType } from '@/lib/rag/knowledge-base/notification-knowledge'
import { logger } from '@/lib/logger'

export interface UseNotificationsOptions {
  /** Polling interval in ms (0 to disable) */
  pollInterval?: number
  /** Initial fetch on mount */
  fetchOnMount?: boolean
}

export interface UseNotificationsReturn {
  /** In-app notifications */
  notifications: InAppNotification[]
  /** Number of unread notifications */
  unreadCount: number
  /** User preferences */
  preferences: NotificationPreferences | null
  /** Loading state */
  loading: boolean
  /** Error state */
  error: string | null

  /** Fetch notifications */
  refresh: () => Promise<void>
  /** Mark single notification as read */
  markRead: (notificationId: string) => Promise<void>
  /** Mark all notifications as read */
  markAllRead: () => Promise<void>

  /** Update preferences */
  updatePreferences: (updates: Partial<NotificationPreferences>) => Promise<void>
  /** Toggle notification type */
  toggleType: (type: NotificationType, enabled: boolean) => Promise<void>
  /** Toggle global notifications */
  toggleGlobal: (enabled: boolean) => Promise<void>
  /** Update quiet hours */
  updateQuietHours: (start: number, end: number, enabled: boolean) => Promise<void>
}

export function useNotifications(
  options: UseNotificationsOptions = {}
): UseNotificationsReturn {
  const { pollInterval = 60000, fetchOnMount = true } = options
  const { firebaseUser, initialized } = useAuth()

  const [notifications, setNotifications] = useState<InAppNotification[]>([])
  const [unreadCount, setUnreadCount] = useState(0)
  const [preferences, setPreferences] = useState<NotificationPreferences | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const pollRef = useRef<NodeJS.Timeout | null>(null)

  // Helper to get auth headers
  const getAuthHeaders = useCallback(async (): Promise<HeadersInit | null> => {
    if (!firebaseUser) return null
    try {
      const token = await firebaseUser.getIdToken()
      return {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,
      }
    } catch (error) {
      logger.error('[useNotifications] Failed to get auth token', { error })
      return null
    }
  }, [firebaseUser])

  // Fetch notifications
  const refresh = useCallback(async () => {
    // Don't fetch if not authenticated
    if (!firebaseUser) {
      return
    }

    try {
      setLoading(true)
      setError(null)

      const headers = await getAuthHeaders()
      if (!headers) {
        // Not authenticated
        return
      }

      const response = await fetch('/api/notifications', {
        headers,
      })

      if (!response.ok) {
        if (response.status === 401) {
          // User not authenticated - not an error state
          return
        }
        throw new Error('Failed to fetch notifications')
      }

      const data = await response.json()

      setNotifications(data.notifications || [])
      setUnreadCount(data.unreadCount || 0)
    } catch (err: any) {
      logger.error('[useNotifications] Error fetching notifications', { error: err })
      setError(err.message || 'Failed to fetch notifications')
    } finally {
      setLoading(false)
    }
  }, [firebaseUser, getAuthHeaders])

  // Fetch preferences
  const fetchPreferences = useCallback(async () => {
    if (!firebaseUser) return

    try {
      const headers = await getAuthHeaders()
      if (!headers) return

      const response = await fetch('/api/notifications/preferences', {
        headers,
      })

      if (!response.ok) {
        if (response.status === 401) return
        throw new Error('Failed to fetch preferences')
      }

      const data = await response.json()
      setPreferences(data.preferences)
    } catch (err: any) {
      logger.error('Error fetching notification preferences', { error: err })
    }
  }, [firebaseUser, getAuthHeaders])

  // Mark single notification as read
  const markRead = useCallback(async (notificationId: string) => {
    try {
      const headers = await getAuthHeaders()
      if (!headers) return

      const response = await fetch('/api/notifications', {
        method: 'POST',
        headers,
        body: JSON.stringify({ action: 'read', notificationId }),
      })

      if (!response.ok) {
        throw new Error('Failed to mark notification as read')
      }

      // Optimistic update
      setNotifications((prev) =>
        prev.map((n) =>
          n.id === notificationId ? { ...n, read: true } : n
        )
      )
      setUnreadCount((prev) => Math.max(0, prev - 1))
    } catch (err: any) {
      setError(err.message)
    }
  }, [getAuthHeaders])

  // Mark all notifications as read
  const markAllRead = useCallback(async () => {
    try {
      const headers = await getAuthHeaders()
      if (!headers) return

      const response = await fetch('/api/notifications', {
        method: 'POST',
        headers,
        body: JSON.stringify({ action: 'readAll' }),
      })

      if (!response.ok) {
        throw new Error('Failed to mark all as read')
      }

      // Optimistic update
      setNotifications((prev) => prev.map((n) => ({ ...n, read: true })))
      setUnreadCount(0)
    } catch (err: any) {
      setError(err.message)
    }
  }, [getAuthHeaders])

  // Update preferences (generic)
  const updatePreferences = useCallback(
    async (updates: Partial<NotificationPreferences>) => {
      try {
        const headers = await getAuthHeaders()
        if (!headers) return

        const response = await fetch('/api/notifications/preferences', {
          method: 'PUT',
          headers,
          body: JSON.stringify({ preferences: updates }),
        })

        if (!response.ok) {
          throw new Error('Failed to update preferences')
        }

        const data = await response.json()
        if (data.preferences) {
          setPreferences(data.preferences)
        }
      } catch (err: any) {
        setError(err.message)
        throw err
      }
    },
    [getAuthHeaders]
  )

  // Toggle notification type
  const toggleType = useCallback(
    async (type: NotificationType, enabled: boolean) => {
      try {
        const headers = await getAuthHeaders()
        if (!headers) return

        const response = await fetch('/api/notifications/preferences', {
          method: 'PUT',
          headers,
          body: JSON.stringify({ toggleType: type, enabled }),
        })

        if (!response.ok) {
          throw new Error('Failed to toggle notification type')
        }

        // Optimistic update
        setPreferences((prev) =>
          prev
            ? {
                ...prev,
                typePreferences: {
                  ...prev.typePreferences,
                  [type]: {
                    ...prev.typePreferences[type],
                    enabled,
                  },
                },
              }
            : null
        )
      } catch (err: any) {
        setError(err.message)
      }
    },
    [getAuthHeaders]
  )

  // Toggle global notifications
  const toggleGlobal = useCallback(async (enabled: boolean) => {
    try {
      const headers = await getAuthHeaders()
      if (!headers) return

      const response = await fetch('/api/notifications/preferences', {
        method: 'PUT',
        headers,
        body: JSON.stringify({ enabled }),
      })

      if (!response.ok) {
        throw new Error('Failed to toggle notifications')
      }

      // Optimistic update
      setPreferences((prev) => (prev ? { ...prev, enabled } : null))
    } catch (err: any) {
      setError(err.message)
    }
  }, [getAuthHeaders])

  // Update quiet hours
  const updateQuietHours = useCallback(
    async (start: number, end: number, enabled: boolean) => {
      try {
        const headers = await getAuthHeaders()
        if (!headers) return

        const response = await fetch('/api/notifications/preferences', {
          method: 'PUT',
          headers,
          body: JSON.stringify({ quietHours: { start, end, enabled } }),
        })

        if (!response.ok) {
          throw new Error('Failed to update quiet hours')
        }

        // Optimistic update
        setPreferences((prev) =>
          prev ? { ...prev, quietHours: { start, end, enabled } } : null
        )
      } catch (err: any) {
        setError(err.message)
      }
    },
    [getAuthHeaders]
  )

  // Track if initial fetch has been done
  const initialFetchDone = useRef(false)

  // Initial fetch - only runs once when fetchOnMount becomes true AND user is authenticated
  useEffect(() => {
    if (fetchOnMount && initialized && firebaseUser && !initialFetchDone.current) {
      initialFetchDone.current = true
      refresh()
      fetchPreferences()
    }
  }, [fetchOnMount, initialized, firebaseUser, refresh, fetchPreferences])

  // Polling - only active when pollInterval > 0 and user is authenticated
  useEffect(() => {
    // Clear any existing interval
    if (pollRef.current) {
      clearInterval(pollRef.current)
      pollRef.current = null
    }

    // Only start polling if interval is positive and user is authenticated
    if (pollInterval > 0 && firebaseUser) {
      pollRef.current = setInterval(refresh, pollInterval)
    }

    return () => {
      if (pollRef.current) {
        clearInterval(pollRef.current)
        pollRef.current = null
      }
    }
  }, [pollInterval, firebaseUser, refresh])

  return {
    notifications,
    unreadCount,
    preferences,
    loading,
    error,
    refresh,
    markRead,
    markAllRead,
    updatePreferences,
    toggleType,
    toggleGlobal,
    updateQuietHours,
  }
}

export default useNotifications

/**
 * useTestExecution Hook
 *
 * Manages test execution, code analysis, and efficiency metrics:
 * - Running code tests
 * - Analyzing code efficiency
 * - Code submission and feedback generation
 * - System design submission
 */

import { useState, useCallback } from "react"
import { Scenario } from "@/lib/scenarios"
import { toast } from "sonner"
import { logger } from "@/lib/logger"
import { isExecutionServiceError } from "@/lib/piston"
import { executeScenarioInBrowser } from "@/lib/workspace-execution"

export interface TestResult {
  description: string
  passed: boolean
  input: any
  expected: any
  actual: any
  error: string | null
  isHidden?: boolean
}

export interface EfficiencyMetrics {
  linesOfCode: number
  complexity: string
  estimatedTimeComplexity: string
  estimatedSpaceComplexity: string
  optimalTimeComplexity: string
  optimalSpaceComplexity: string
  efficiencyScore: number
}

export interface UseTestExecutionOptions {
  selectedScenario: Scenario | null
  code: string
  selectedLanguage: string
  onTestComplete?: (results: TestResult[], summary: any) => void
  onTestError?: (error: string) => void
  playSound?: (type: "hint" | "success" | "fail" | "milestone") => void
}

export interface UseTestExecutionReturn {
  isRunning: boolean
  testResults: TestResult[]
  testSummary: { total: number; passed: number; failed: number; passRate: number }
  consoleLogs: Array<{ type: string; message: string; timestamp: number }>
  efficiencyMetrics: EfficiencyMetrics | null
  runTests: () => Promise<void>
  analyzeEfficiency: (codeToAnalyze: string) => EfficiencyMetrics
}

export function useTestExecution({
  selectedScenario,
  code,
  selectedLanguage,
  onTestComplete,
  onTestError,
  playSound,
}: UseTestExecutionOptions): UseTestExecutionReturn {
  const [isRunning, setIsRunning] = useState(false)
  const [testResults, setTestResults] = useState<TestResult[]>([])
  const [testSummary, setTestSummary] = useState({ total: 0, passed: 0, failed: 0, passRate: 0 })
  const [consoleLogs, setConsoleLogs] = useState<
    Array<{ type: string; message: string; timestamp: number }>
  >([])
  const [efficiencyMetrics, setEfficiencyMetrics] = useState<EfficiencyMetrics | null>(null)

  const analyzeEfficiency = useCallback(
    (codeToAnalyze: string): EfficiencyMetrics => {
      // Calculate lines of code (excluding empty lines and comments)
      const lines = codeToAnalyze.split("\n")
      const linesOfCode = lines.filter((line) => {
        const trimmed = line.trim()
        return (
          trimmed.length > 0 &&
          !trimmed.startsWith("//") &&
          !trimmed.startsWith("/*") &&
          !trimmed.startsWith("*")
        )
      }).length

      // Basic complexity estimation based on control structures
      const controlStructures = (
        codeToAnalyze.match(/\b(if|else|for|while|switch|case|catch)\b/g) || []
      ).length
      const complexityLevel =
        controlStructures <= 3 ? "Low" : controlStructures <= 7 ? "Medium" : "High"

      // Estimate time complexity based on nested loops
      const nestedLoopCount =
        (codeToAnalyze.match(/for.*{[^}]*for/g) || []).length +
        (codeToAnalyze.match(/while.*{[^}]*while/g) || []).length
      let estimatedTimeComplexity = "O(n)"
      if (nestedLoopCount >= 2) {
        estimatedTimeComplexity = "O(n³)"
      } else if (nestedLoopCount === 1) {
        estimatedTimeComplexity = "O(n²)"
      } else if (codeToAnalyze.includes("sort")) {
        estimatedTimeComplexity = "O(n log n)"
      }

      // Get optimal complexity from scenario (needed for bounded space check)
      const optimalSpaceComplexity = (selectedScenario as any)?.optimalComplexity?.space || "N/A"

      // Estimate space complexity based on data structures
      // Only count CREATION of new data structures, not access/indexing
      const hasHashMapCreation =
        /new\s+Map\s*\(/.test(codeToAnalyze) || // new Map()
        /new\s+Set\s*\(/.test(codeToAnalyze) || // new Set()
        /=\s*\{\s*\}/.test(codeToAnalyze) || // = {} (empty object literal)
        /dict\s*\(\s*\)/.test(codeToAnalyze) || // dict() in Python
        /set\s*\(\s*\)/.test(codeToAnalyze) || // set() in Python
        /defaultdict\s*\(/.test(codeToAnalyze) || // defaultdict in Python
        /Counter\s*\(/.test(codeToAnalyze) // Counter in Python

      // Detect array CREATION, not just indexing
      // Creation patterns: [], Array(), list(), .split(), .slice() returning new array
      const hasArrayCreation =
        /=\s*\[\s*\]/.test(codeToAnalyze) || // = [] (empty array literal)
        /=\s*\[[^\]]+\](?!\s*=)/.test(codeToAnalyze) || // = [items] (array literal with items, not destructuring)
        /new\s+Array\s*\(/.test(codeToAnalyze) || // new Array()
        /Array\s*\.\s*from\s*\(/.test(codeToAnalyze) || // Array.from()
        /list\s*\(\s*\)/.test(codeToAnalyze) || // list() in Python
        /\.split\s*\(/.test(codeToAnalyze) || // .split() creates new array
        /\.slice\s*\(/.test(codeToAnalyze) || // .slice() creates new array
        /\.map\s*\(/.test(codeToAnalyze) || // .map() creates new array
        /\.filter\s*\(/.test(codeToAnalyze) || // .filter() creates new array
        /\[\s*for\s+/.test(codeToAnalyze) // [x for x in ...] list comprehension

      // Check if this is a bounded space problem (e.g., 26-char alphabet, digits only)
      // If optimal space is O(1) but code uses hash map/array, it's likely bounded
      // Common bounded space problems: anagrams, character frequency, digit counting
      const isBoundedSpaceProblem = optimalSpaceComplexity === "O(1)"

      let estimatedSpaceComplexity = "O(1)"
      if (hasHashMapCreation || hasArrayCreation) {
        // If the problem's optimal is O(1), trust that - it means the data structure
        // has bounded size (e.g., 26 chars for alphabet, 10 digits, etc.)
        // Otherwise, assume the data structure grows with input size
        estimatedSpaceComplexity = isBoundedSpaceProblem ? "O(1)" : "O(n)"
      }

      // Get optimal time complexity from scenario
      const optimalTimeComplexity = (selectedScenario as any)?.optimalComplexity?.time || "N/A"

      // Calculate efficiency score (0-100)
      let efficiencyScore = 100

      // Deduct points for suboptimal time complexity
      if (optimalTimeComplexity !== "N/A" && estimatedTimeComplexity !== optimalTimeComplexity) {
        efficiencyScore -= 20
      }

      // Deduct points for suboptimal space complexity
      if (optimalSpaceComplexity !== "N/A" && estimatedSpaceComplexity !== optimalSpaceComplexity) {
        efficiencyScore -= 10
      }

      // Deduct points for excessive complexity
      if (complexityLevel === "High") {
        efficiencyScore -= 15
      } else if (complexityLevel === "Medium") {
        efficiencyScore -= 5
      }

      // Deduct points for excessive lines of code
      if (linesOfCode > 30) {
        efficiencyScore -= 10
      } else if (linesOfCode > 20) {
        efficiencyScore -= 5
      }

      return {
        linesOfCode,
        complexity: complexityLevel,
        estimatedTimeComplexity,
        estimatedSpaceComplexity,
        optimalTimeComplexity,
        optimalSpaceComplexity,
        efficiencyScore: Math.max(0, efficiencyScore),
      }
    },
    [selectedScenario]
  )

  const runTests = useCallback(async () => {
    if (!selectedScenario) return

    setIsRunning(true)
    setTestResults([])
    setConsoleLogs([])

    // Analyze code efficiency
    const metrics = analyzeEfficiency(code)
    setEfficiencyMetrics(metrics)

    try {
      const browserResult = await executeScenarioInBrowser({
        code,
        scenario: selectedScenario,
        language: selectedLanguage,
      })

      if (browserResult) {
        if (browserResult.error) {
          throw new Error(browserResult.error)
        }

        const data = browserResult

        setTestResults(data.results as TestResult[])
        setTestSummary(data.summary)

        if (data.consoleLogs && data.consoleLogs.length > 0) {
          setConsoleLogs(data.consoleLogs)
        }

        const errorResults = (data.results as TestResult[]).filter((result) => result.error)
        const allFailed = data.summary.passRate === 0

        if (allFailed && errorResults.length > 0) {
          const firstError = errorResults[0].error
          const isServiceDown = isExecutionServiceError(firstError)

          if (isServiceDown) {
            toast.error("Code execution unavailable", {
              description:
                "Our code runner is temporarily unavailable. Please try again in a few minutes.",
              duration: 8000,
            })
          }
          playSound?.("fail")
          setIsRunning(false)
          return
        }

        if (data.summary.passRate === 100) {
          playSound?.("success")
        } else if (data.summary.passRate >= 50) {
          playSound?.("milestone")
        } else {
          playSound?.("fail")
        }

        onTestComplete?.(data.results as TestResult[], data.summary)
        setIsRunning(false)
        return
      }

      const response = await fetch("/api/execute", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          code,
          scenarioId: selectedScenario.id,
          language: selectedLanguage,
        }),
      })

      const data = await response.json()

      // Handle API errors (scenario not found, execution timeout, etc.)
      if (!response.ok || data.error) {
        const errorMessage = data.error || `Server error (${response.status})`
        const isServiceDown = isExecutionServiceError(errorMessage)

        setConsoleLogs([
          {
            type: "error",
            message: isServiceDown
              ? "❌ Code execution service is temporarily unavailable. Please try again in a few minutes."
              : `❌ Execution Error: ${errorMessage}`,
            timestamp: Date.now(),
          },
        ])
        setTestResults([
          {
            description: "Execution Error",
            passed: false,
            error: errorMessage,
            input: "",
            expected: "",
            actual: "",
          },
        ])

        if (isServiceDown) {
          toast.error("Code execution unavailable", {
            description:
              "Our code runner is temporarily unavailable. Please try again in a few minutes.",
            duration: 8000,
          })
        }
        playSound?.("fail")
        onTestError?.(errorMessage)
        setIsRunning(false)
        return
      }

      if (data.results) {
        setTestResults(data.results)
        setTestSummary(data.summary)

        // Store console logs from execution
        if (data.consoleLogs && data.consoleLogs.length > 0) {
          setConsoleLogs(data.consoleLogs)
        }

        // Check for syntax/compilation errors vs service unavailability
        const errorResults = data.results.filter((r: TestResult) => r.error)
        const allFailed = data.summary.passRate === 0

        if (allFailed && errorResults.length > 0) {
          const firstError = errorResults[0].error
          const isServiceDown = isExecutionServiceError(firstError)

          if (isServiceDown) {
            toast.error("Code execution unavailable", {
              description:
                "Our code runner is temporarily unavailable. Please try again in a few minutes.",
              duration: 8000,
            })
            playSound?.("fail")
            setIsRunning(false)
            return
          }

          playSound?.("fail")
          setIsRunning(false)
          return // Don't proceed to callback (code errors)
        }

        // Play sound based on results
        if (data.summary.passRate === 100) {
          playSound?.("success")
        } else if (data.summary.passRate >= 50) {
          playSound?.("milestone")
        } else {
          playSound?.("fail")
        }

        // Call completion callback
        onTestComplete?.(data.results, data.summary)
        setIsRunning(false)
      }
    } catch (error) {
      logger.error("Code execution error", { error, scenarioId: selectedScenario?.id })
      toast.error("Failed to run tests", {
        description: "There was a problem executing your code. Please try again.",
      })
      setIsRunning(false)
    }
  }, [
    selectedScenario,
    code,
    selectedLanguage,
    analyzeEfficiency,
    onTestComplete,
    onTestError,
    playSound,
  ])

  return {
    isRunning,
    testResults,
    testSummary,
    consoleLogs,
    efficiencyMetrics,
    runTests,
    analyzeEfficiency,
  }
}

/**
 * Clarifying Questions Checker
 *
 * Uses a small LLM (Gemini Flash Lite → DeepSeek Chat → Claude Haiku)
 * to semantically match whether a candidate asked expected clarifying questions.
 *
 * This is called at the phase transition from discussion → coding in Real Interview Mode.
 * Instead of regex matching, we use semantic understanding to catch variations like:
 * - "Should I return indices or values?" matches "do I return the index or actual number?"
 *
 * Cost-optimized: Only runs once per interview, uses cheapest models.
 */

import { generateAIResponse, type AIResponse } from "@/lib/ai-providers"
import type { ClarifyingQuestion } from "@/lib/scenarios/types"
import type { ChatMessage } from "@/lib/stores/interview-store"
import { logger } from "@/lib/logger"

/**
 * Result of checking a single clarifying question
 */
export interface ClarifyingQuestionResult {
  question: string
  expected: boolean // Was this a required question?
  asked: boolean // Did the candidate ask it?
  confidence: number // 0-100, how confident the LLM is
  matchedPhrase?: string // What the candidate said that matched
}

/**
 * Overall result of the clarifying questions check
 */
export interface ClarifyingQuestionsCheckResult {
  results: ClarifyingQuestionResult[]
  totalExpected: number
  totalAsked: number
  requiredAsked: number
  requiredTotal: number
  score: number // 0-100, weighted score
  provider: string // Which LLM was used
  latencyMs: number
}

/**
 * Build the prompt for the LLM to check clarifying questions
 * Uses topic-based semantic matching for flexible detection
 */
function buildCheckPrompt(
  expectedQuestions: ClarifyingQuestion[],
  conversation: ChatMessage[]
): string {
  const conversationText = conversation
    .filter((msg) => msg.type === "user")
    .map((msg) => `- "${msg.message}"`)
    .join("\n")

  // Use topic field for better semantic grouping, fallback to question
  const questionsToCheck = expectedQuestions
    .map(
      (q, i) =>
        `${i + 1}. Topic: "${q.topic || q.question}"
   - Example phrasing: "${q.question}"
   - Required: ${q.required ? "YES" : "NO"}
   - Any question about this topic counts as asked`
    )
    .join("\n")

  return `You are analyzing an interview conversation to determine if the candidate asked about specific TOPICS.

CANDIDATE'S MESSAGES:
${conversationText || "(No messages from candidate)"}

TOPICS TO CHECK:
${questionsToCheck}

For each topic, determine if the candidate asked about it IN ANY FORM.
Match semantic intent, not exact words. The candidate may phrase questions differently.

Examples of topic matches:
- Topic "output_format": matches "What should I return?", "length or substring?", "do I return the actual string?"
- Topic "case_sensitivity": matches "Is it case sensitive?", "Are A and a different?", "uppercase vs lowercase?"
- Topic "repeating_definition": matches "What counts as repeating?", "consecutive only or any duplicate?"

Respond in JSON format:
{
  "results": [
    {
      "questionIndex": 1,
      "asked": true,
      "confidence": 85,
      "matchedPhrase": "what do I return, the length or the actual substring?"
    },
    {
      "questionIndex": 2,
      "asked": false,
      "confidence": 95,
      "matchedPhrase": null
    }
  ]
}

Only respond with the JSON, no other text.`
}

/**
 * Parse the LLM response into structured results
 */
function parseCheckResponse(
  response: string,
  expectedQuestions: ClarifyingQuestion[]
): ClarifyingQuestionResult[] {
  try {
    // Extract JSON from response (handle markdown code blocks)
    let jsonStr = response.trim()
    if (jsonStr.startsWith("```")) {
      jsonStr = jsonStr
        .replace(/```json?\n?/g, "")
        .replace(/```$/g, "")
        .trim()
    }

    const parsed = JSON.parse(jsonStr)
    const results: ClarifyingQuestionResult[] = []

    for (let i = 0; i < expectedQuestions.length; i++) {
      const expected = expectedQuestions[i]
      const result = parsed.results?.find((r: any) => r.questionIndex === i + 1)

      results.push({
        question: expected.question,
        expected: expected.required,
        asked: result?.asked ?? false,
        confidence: result?.confidence ?? 50,
        matchedPhrase: result?.matchedPhrase || undefined,
      })
    }

    return results
  } catch (error) {
    logger.error("[ClarifyingQuestionsChecker] Failed to parse LLM response", {
      response: response.substring(0, 500),
      error,
    })

    // Return default results (all questions not asked)
    return expectedQuestions.map((q) => ({
      question: q.question,
      expected: q.required,
      asked: false,
      confidence: 0,
    }))
  }
}

/**
 * Calculate the weighted score based on which questions were asked
 * Required questions are worth more than optional ones
 */
function calculateScore(results: ClarifyingQuestionResult[]): number {
  if (results.length === 0) return 100 // No questions expected = full score

  const requiredQuestions = results.filter((r) => r.expected)
  const optionalQuestions = results.filter((r) => !r.expected)

  // Required questions are worth 70%, optional 30%
  const requiredWeight = 0.7
  const optionalWeight = 0.3

  let requiredScore = 0
  if (requiredQuestions.length > 0) {
    const requiredAsked = requiredQuestions.filter((r) => r.asked).length
    requiredScore = (requiredAsked / requiredQuestions.length) * 100 * requiredWeight
  } else {
    requiredScore = 100 * requiredWeight // No required questions = full required score
  }

  let optionalScore = 0
  if (optionalQuestions.length > 0) {
    const optionalAsked = optionalQuestions.filter((r) => r.asked).length
    optionalScore = (optionalAsked / optionalQuestions.length) * 100 * optionalWeight
  } else {
    optionalScore = 100 * optionalWeight // No optional questions = full optional score
  }

  return Math.round(requiredScore + optionalScore)
}

/**
 * Check if the candidate asked the expected clarifying questions
 *
 * @param expectedQuestions - The clarifying questions defined in the scenario
 * @param conversation - The conversation messages from the interview
 * @returns Results of the check including which questions were asked
 */
export async function checkClarifyingQuestions(
  expectedQuestions: ClarifyingQuestion[],
  conversation: ChatMessage[],
  options?: {
    userId?: string
    sessionId?: string
    scenarioId?: string
  }
): Promise<ClarifyingQuestionsCheckResult> {
  const startTime = Date.now()

  // If no questions to check, return perfect score
  if (!expectedQuestions || expectedQuestions.length === 0) {
    return {
      results: [],
      totalExpected: 0,
      totalAsked: 0,
      requiredAsked: 0,
      requiredTotal: 0,
      score: 100,
      provider: "none",
      latencyMs: 0,
    }
  }

  // If no conversation, return zero score
  const userMessages = conversation.filter((msg) => msg.type === "user")
  if (userMessages.length === 0) {
    return {
      results: expectedQuestions.map((q) => ({
        question: q.question,
        expected: q.required,
        asked: false,
        confidence: 100, // Very confident they didn't ask since they said nothing
      })),
      totalExpected: expectedQuestions.length,
      totalAsked: 0,
      requiredAsked: 0,
      requiredTotal: expectedQuestions.filter((q) => q.required).length,
      score: 0,
      provider: "none",
      latencyMs: Date.now() - startTime,
    }
  }

  try {
    const systemPrompt =
      "You are a precise analyzer that checks if interview questions were asked. Respond only in JSON format."
    const userMessage = buildCheckPrompt(expectedQuestions, conversation)

    // Use "simple" complexity to get cheapest providers (Flash Lite → DeepSeek Chat → Haiku)
    const response: AIResponse = await generateAIResponse(systemPrompt, userMessage, [], {
      complexity: "simple",
      temperature: 0.1, // Low temperature for consistent analysis
      userId: options?.userId,
      sessionId: options?.sessionId,
      scenarioId: options?.scenarioId,
      eventType: "chat_message", // Categorize as chat for cost tracking
      skipCache: true, // Don't cache this - each interview is unique
    })

    const results = parseCheckResponse(response.text, expectedQuestions)
    const totalAsked = results.filter((r) => r.asked).length
    const requiredResults = results.filter((r) => r.expected)
    const requiredAsked = requiredResults.filter((r) => r.asked).length

    return {
      results,
      totalExpected: expectedQuestions.length,
      totalAsked,
      requiredAsked,
      requiredTotal: requiredResults.length,
      score: calculateScore(results),
      provider: response.provider,
      latencyMs: Date.now() - startTime,
    }
  } catch (error) {
    logger.error("[ClarifyingQuestionsChecker] LLM check failed", { error })

    // Return default results on error
    return {
      results: expectedQuestions.map((q) => ({
        question: q.question,
        expected: q.required,
        asked: false,
        confidence: 0,
      })),
      totalExpected: expectedQuestions.length,
      totalAsked: 0,
      requiredAsked: 0,
      requiredTotal: expectedQuestions.filter((q) => q.required).length,
      score: 0,
      provider: "error",
      latencyMs: Date.now() - startTime,
    }
  }
}

/**
 * Generate feedback about clarifying questions for the candidate
 */
export function generateClarifyingQuestionsFeedback(
  checkResult: ClarifyingQuestionsCheckResult
): string {
  if (checkResult.totalExpected === 0) {
    return ""
  }

  const lines: string[] = []

  // Score-based header
  if (checkResult.score >= 80) {
    lines.push("**Clarifying Questions: Excellent!**")
    lines.push("You asked great clarifying questions before diving into the solution.")
  } else if (checkResult.score >= 50) {
    lines.push("**Clarifying Questions: Good Start**")
    lines.push("You asked some clarifying questions, but missed a few important ones.")
  } else {
    lines.push("**Clarifying Questions: Needs Improvement**")
    lines.push(
      "In real interviews, asking clarifying questions shows strong problem-solving skills."
    )
  }

  // Required questions that were missed
  const missedRequired = checkResult.results.filter((r) => r.expected && !r.asked)
  if (missedRequired.length > 0) {
    lines.push("")
    lines.push("**Questions you should have asked:**")
    missedRequired.forEach((q) => {
      lines.push(`- ${q.question}`)
    })
  }

  // Questions they did ask (positive reinforcement)
  const askedQuestions = checkResult.results.filter((r) => r.asked)
  if (askedQuestions.length > 0) {
    lines.push("")
    lines.push("**Good questions you asked:**")
    askedQuestions.forEach((q) => {
      lines.push(`- ${q.question}${q.matchedPhrase ? ` (you asked: "${q.matchedPhrase}")` : ""}`)
    })
  }

  return lines.join("\n")
}

