import {
  doc,
  setDoc,
  getDoc,
  getDocs,
  collection,
  query,
  where,
  orderBy,
  limit,
  updateDoc,
  deleteDoc,
  writeBatch,
  increment,
  Timestamp,
} from "firebase/firestore"
import type {
  NotificationPreferences,
  Notification,
  InAppNotification,
  NotificationAnalytics,
