 * Get all in-app notifications (for notification center)
 */
export async function getInAppNotifications(
  userId: string,
  limitCount: number = 50
): Promise<InAppNotification[]> {
  const q = query(
    collection(db, "in_app_notifications"),
    where("userId", "==", userId),
