import sys
import time
from typing import Optional, List, Dict, Set, Tuple, Any
from collections import deque, defaultdict, Counter
import heapq
import math

# Common DSA classes used in problems
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

# Helper to build tree from array (for test input)
def _build_tree(arr):
    if not arr or len(arr) == 0:
        return None
    if arr[0] is None:
        return None
    root = TreeNode(arr[0])
    queue = [root]
    i = 1
    while queue and i < len(arr):
        node = queue.pop(0)
        if i < len(arr) and arr[i] is not None:
            node.left = TreeNode(arr[i])
            queue.append(node.left)
        i += 1
        if i < len(arr) and arr[i] is not None:
            node.right = TreeNode(arr[i])
            queue.append(node.right)
        i += 1
    return root

# Helper to convert tree to array (for output)
def _tree_to_array(root):
    if not root:
        return []
    result = []
    queue = [root]
    while queue:
        node = queue.pop(0)
        if node:
            result.append(node.val)
            queue.append(node.left)
            queue.append(node.right)
        else:
            result.append(None)
    # Remove trailing Nones
    while result and result[-1] is None:
        result.pop()
    return result

# Helper to build linked list from array (for test input)
def _build_list(arr):
    if not arr:
        return None
    head = ListNode(arr[0])
    current = head
    for val in arr[1:]:
        current.next = ListNode(val)
        current = current.next
    return head

# Helper to convert linked list to array (for output)
def _list_to_array(head):
    result = []
    current = head
    seen = set()  # Detect cycles
    while current and id(current) not in seen:
        seen.add(id(current))
        result.append(current.val)
        current = current.next
    return result

# Capture print statements
_console_logs = []
_original_print = print

def _capture_print(*args, **kwargs):
    msg = ' '.join(str(a) for a in args)
    _console_logs.append({"type": "log", "message": msg, "timestamp": int(time.time() * 1000)})
    _original_print(*args, **kwargs)

# Override print
print = _capture_print

${code}

# Execute with test input
try:
    _input = json.loads('${inputJson.replace(/'/g, "\\'")}')
    _input_keys = json.loads('${inputKeysJson.replace(/'/g, "\\'")}')

${
  isClassBased && className
    ? `
