import { Pinecone } from "@pinecone-database/pinecone"
import { GEMINI_DIM, OPENAI_DIM, SUPPORTED_DIMENSIONS, TFIDF_DIM } from "./config"

let pineconeClient: Pinecone | null = null

export function getPineconeClient(): Pinecone {
  if (!pineconeClient) {
    const apiKey = process.env.PINECONE_API_KEY
    if (!apiKey) {
      throw new Error("PINECONE_API_KEY environment variable is required")
    }
    pineconeClient = new Pinecone({ apiKey })
  }
  return pineconeClient
}

export async function getVerifiedPineconeIndex(
  indexName: string,
  onDimensionResolved: (dimension: number) => void
) {
  const client = getPineconeClient()

  try {
    const indexList = await client.listIndexes()
    const indexInfo = indexList.indexes?.find((idx) => idx.name === indexName)

    if (!indexInfo) {
      throw new Error(
        `Pinecone index '${indexName}' does not exist. ` +
          `Please create it by running: npx ts-node scripts/setup-pinecone.ts ` +
          `or set PINECONE_INDEX_NAME to an existing index name.`
      )
    }

    const dimension = indexInfo.dimension
    if (
      !dimension ||
      !SUPPORTED_DIMENSIONS.includes(dimension as (typeof SUPPORTED_DIMENSIONS)[number])
    ) {
      throw new Error(
        `Pinecone index '${indexName}' has unsupported dimensions. ` +
          `Supported dimensions: ${SUPPORTED_DIMENSIONS.join(", ")} (256 for TF-IDF, 768 for Gemini, 1536 for OpenAI). ` +
          `Index has ${dimension ?? "unknown"} dimensions. ` +
          `Please delete the existing index and create a new one with one of the supported dimensions, ` +
          `or update your embedding provider to match the index dimensions.`
      )
    }

    onDimensionResolved(dimension)

    if (dimension === GEMINI_DIM) {
      console.log("[Pinecone] Index configured for Gemini embeddings (768 dimensions)")
    } else if (dimension === OPENAI_DIM) {
      console.log("[Pinecone] Index configured for OpenAI embeddings (1536 dimensions)")
    } else if (dimension === TFIDF_DIM) {
      console.log("[Pinecone] Index configured for TF-IDF embeddings (256 dimensions)")
    }
  } catch (error: any) {
    if (
      error.message?.includes("does not exist") ||
      error.message?.includes("dimension mismatch")
    ) {
      throw error
    }
    console.warn("[Pinecone] Could not verify index existence:", error.message)
  }

  return client.index(indexName)
}

import type { QueryOptions } from "../../types"

export function buildMetadataFilter(
  filter: QueryOptions["filter"]
): Record<string, any> | undefined {
  if (!filter) return undefined

  const conditions: Record<string, any>[] = []

  if (filter.type) {
    conditions.push({ type: { $eq: filter.type } })
  }

  if (filter.userId) {
    conditions.push({
      $or: [{ userId: { $eq: filter.userId } }, { user_id: { $eq: filter.userId } }],
    })
  }

  if (filter.problemType) {
    conditions.push({ problemType: { $eq: filter.problemType } })
  }

  if (conditions.length === 0) return undefined
  if (conditions.length === 1) return conditions[0]
  return { $and: conditions }
}

import type { VectorDocument } from "../../types"

export function flattenMetadata(doc: VectorDocument): Record<string, any> {
  const flatMetadata: Record<string, any> = {
    ...doc.metadata,
    text: doc.text || "",
  }

  if (doc.metadata?.tags && Array.isArray(doc.metadata.tags)) {
    flatMetadata.tags = doc.metadata.tags.join(",")
  }

  if (doc.metadata?.topPatterns && Array.isArray(doc.metadata.topPatterns)) {
    flatMetadata.topPatterns = doc.metadata.topPatterns.join(",")
  }

  if (
    doc.metadata?.difficultyDistribution &&
    typeof doc.metadata.difficultyDistribution === "object"
  ) {
    const dist = doc.metadata.difficultyDistribution as Record<string, any>
    flatMetadata.difficultyDistribution = `easy:${dist.easy || 0},medium:${dist.medium || 0},hard:${dist.hard || 0}`
  }

  Object.keys(flatMetadata).forEach((key) => {
    const value = flatMetadata[key]
    if (
      value !== null &&
      typeof value === "object" &&
      !Array.isArray(value) &&
      !(value instanceof Date)
    ) {
      flatMetadata[key] = JSON.stringify(value)
    } else if (Array.isArray(value) && value.length > 0 && typeof value[0] !== "string") {
      flatMetadata[key] = value.join(",")
    }
  })

  return flatMetadata
}

export function restoreMetadata(metadata: Record<string, any>): Record<string, any> {
  const restored: Record<string, any> = { ...metadata }

  if (typeof restored.tags === "string") {
    restored.tags = restored.tags.split(",").filter(Boolean)
  }

  if (typeof restored.topPatterns === "string") {
    restored.topPatterns = restored.topPatterns.split(",").filter(Boolean)
  }

  if (typeof restored.difficultyDistribution === "string") {
    const dist: Record<string, number> = {}
    restored.difficultyDistribution.split(",").forEach((part: string) => {
      const [key, value] = part.split(":")
      if (key && value) {
        dist[key.trim()] = parseFloat(value.trim()) || 0
      }
    })
    restored.difficultyDistribution = dist
  }

  return restored
}

import { VECTOR_CONTENT_TYPES } from "../../types"
import type { QueryOptions, QueryResult, VectorDB, VectorDocument } from "../../types"
import { GEMINI_DIM, INDEX_NAME, NAMESPACE_PREFIX, TFIDF_DIM } from "./config"
import { getPineconeClient, getVerifiedPineconeIndex } from "./client"
import { buildMetadataFilter } from "./filters"
import { flattenMetadata, restoreMetadata } from "./metadata"

export class PineconeVectorDB implements VectorDB {
  private indexName: string
  private cachedDimension: number | null = null

  constructor(indexName: string = INDEX_NAME) {
    this.indexName = indexName
  }

  async getDimension(): Promise<number> {
    await this.getIndex()
    if (this.cachedDimension == null) {
      return GEMINI_DIM
    }
    return this.cachedDimension
  }

  private async validateVectorDimension(vector: number[]): Promise<void> {
    const expected = await this.getDimension()
    if (vector.length !== expected) {
      const hint =
        vector.length === TFIDF_DIM && expected === GEMINI_DIM
          ? " Embedding fell back to TF-IDF (256D). Ensure GEMINI_API_KEY is set and Gemini is available."
          : ""
      throw new Error(
        `Vector dimension ${vector.length} does not match the index dimension ${expected}.${hint}`
      )
    }
  }

  private async getIndex() {
    return getVerifiedPineconeIndex(this.indexName, (dimension) => {
      this.cachedDimension = dimension
    })
  }

  async upsert(documents: VectorDocument[]): Promise<void> {
    if (documents.length === 0) return

    for (const doc of documents) {
      await this.validateVectorDimension(doc.vector)
    }

    const index = await this.getIndex()
    const documentsByType = new Map<string, VectorDocument[]>()
    for (const doc of documents) {
      const docType = doc.metadata?.type || "general"
      const groupedDocuments = documentsByType.get(docType) || []
      groupedDocuments.push(doc)
      documentsByType.set(docType, groupedDocuments)
    }

    const batchSize = 100
    for (const [docType, typedDocuments] of documentsByType.entries()) {
      const namespace = `${NAMESPACE_PREFIX}${docType}`
      const vectors = typedDocuments.map((doc) => ({
        id: doc.id,
        values: doc.vector,
        metadata: flattenMetadata(doc),
      }))

      for (let i = 0; i < vectors.length; i += batchSize) {
        const batch = vectors.slice(i, i + batchSize)
        await index.namespace(namespace).upsert(batch)
      }
    }

    console.log(
      `[Pinecone] Upserted ${documents.length} vectors across ${documentsByType.size} namespace(s)`
    )
  }

  async query(vector: number[], options: QueryOptions = {}): Promise<QueryResult[]> {
    await this.validateVectorDimension(vector)

    const { topK = 5, filter = {}, includeMetadata = true, includeValues = false } = options
    const index = await this.getIndex()
    const docType = filter.type || "general"
    const namespace = `${NAMESPACE_PREFIX}${docType}`
    const metadataFilter = buildMetadataFilter(filter)

    try {
      const queryResponse = await index.namespace(namespace).query({
        vector,
        topK: filter.excludeIds ? topK + filter.excludeIds.length : topK,
        includeMetadata,
        includeValues,
        filter: metadataFilter,
      })

      let results = queryResponse.matches || []

      if (filter.excludeIds && filter.excludeIds.length > 0) {
        results = results.filter((match) => !filter.excludeIds!.includes(match.id))
      }

      if (filter.minSimilarity) {
        results = results.filter((match) => (match.score || 0) >= filter.minSimilarity!)
      }

      results = results.slice(0, topK)

      return results.map((match) => {
        if (!match.metadata) {
          return {
            id: match.id,
            score: match.score || 0,
            metadata: undefined,
            vector: includeValues ? match.values : undefined,
          }
        }

        return {
          id: match.id,
          score: match.score || 0,
          metadata: restoreMetadata(match.metadata),
          vector: includeValues ? match.values : undefined,
        }
      })
    } catch (error: any) {
      if (error.message?.includes("Namespace not found")) {
        console.log(`[Pinecone] Namespace ${namespace} not found, returning empty results`)
        return []
      }
      if (
        error.message?.includes("404") ||
        error.message?.includes("not found") ||
        error.status === 404 ||
        error.response?.status === 404
      ) {
        throw new Error(
          `Pinecone index '${this.indexName}' does not exist. ` +
            `Please create it by running: npx ts-node scripts/setup-pinecone.ts`
        )
      }
      throw error
    }
  }

  async delete(ids: string[]): Promise<void> {
    if (ids.length === 0) return

    const index = await this.getIndex()
    const namespaces = [...VECTOR_CONTENT_TYPES, "general"]

    for (const ns of namespaces) {
      try {
        await index.namespace(`${NAMESPACE_PREFIX}${ns}`).deleteMany(ids)
      } catch {
        // Ignore errors for namespaces that don't exist.
      }
    }

    console.log(`[Pinecone] Deleted ${ids.length} vectors`)
  }

  async healthCheck(): Promise<boolean> {
    try {
      const client = getPineconeClient()
      const indexList = await client.listIndexes()
      const hasIndex = indexList.indexes?.some((idx) => idx.name === this.indexName)

      if (!hasIndex) {
        console.warn(
          `[Pinecone] Index '${this.indexName}' not found. Available indexes:`,
          indexList.indexes?.map((i) => i.name)
        )
        return false
      }

      return true
    } catch (error) {
      console.error("[Pinecone] Health check failed:", error)
      return false
    }
  }

  async getStats(): Promise<{
    totalVectors: number
    namespaces: Record<string, number>
  }> {
    const index = await this.getIndex()
    const stats = await index.describeIndexStats()

    return {
      totalVectors: stats.totalRecordCount || 0,
      namespaces: stats.namespaces
        ? Object.fromEntries(
            Object.entries(stats.namespaces).map(([ns, data]) => [ns, data.recordCount || 0])
          )
        : {},
    }
  }
}

import { INDEX_NAME } from "./config"
import { getPineconeClient } from "./client"

export async function createPineconeIndex(
  dimension: number = 768,
  metric: "cosine" | "euclidean" | "dotproduct" = "cosine"
): Promise<void> {
  const client = getPineconeClient()
  const indexList = await client.listIndexes()
  const exists = indexList.indexes?.some((idx) => idx.name === INDEX_NAME)

  if (exists) {
    console.log(`[Pinecone] Index '${INDEX_NAME}' already exists`)
    return
  }

  await client.createIndex({
    name: INDEX_NAME,
    dimension,
    metric,
    spec: {
      serverless: {
        cloud: "aws",
        region: "us-east-1",
      },
    },
  })

  console.log(`[Pinecone] Created index '${INDEX_NAME}' with dimension ${dimension}`)

  let ready = false
  while (!ready) {
    const description = await client.describeIndex(INDEX_NAME)
    ready = description.status?.ready || false
    if (!ready) {
      console.log("[Pinecone] Waiting for index to be ready...")
      await new Promise((resolve) => setTimeout(resolve, 2000))
    }
  }

  console.log(`[Pinecone] Index '${INDEX_NAME}' is ready`)
}

/**
 * Vectorization Infrastructure for Analytics & Recommendations
 *
 * This module provides:
 * 1. Session metrics vectorization for ML analysis
 * 2. Code embedding generation for similarity search
 * 3. User performance pattern analysis
 * 4. Recommendation engine based on session history
 */

import { adminDb } from "../firebase-admin"
import { Timestamp } from "firebase-admin/firestore"
import { cosineSimilarity } from "./utils"
import type { SessionMetrics, SessionVector, CodeFeatures, UserPerformanceProfile } from "./types"

// Vector dimensions
const METRICS_VECTOR_DIM = 25
const CODE_FEATURES_DIM = 15

/**
 * Convert session metrics to a normalized vector
 */
export function vectorizeSessionMetrics(metrics: Partial<SessionMetrics>): number[] {
  const vector: number[] = []

  // Time features (normalized to 0-1)
  const maxSessionTime = 3600 // 1 hour max
  vector.push(Math.min(1, (metrics.timeSpentSeconds || 0) / maxSessionTime))
  vector.push(Math.min(1, (metrics.timeToFirstCode || 0) / 300)) // First code within 5 min
  vector.push(
    metrics.timeBetweenMessages?.length
      ? Math.min(
          1,
          metrics.timeBetweenMessages.reduce((a, b) => a + b, 0) /
            metrics.timeBetweenMessages.length /
            60
        )
      : 0.5
  )

  // Collaboration features (normalized)
  const totalInterviewer =
    (metrics.interviewerMessagesSent || 0) + (metrics.interviewerMessagesReceived || 0)
  const totalPartner = (metrics.partnerMessagesSent || 0) + (metrics.partnerMessagesReceived || 0)
  vector.push(Math.min(1, totalInterviewer / 20))
  vector.push(Math.min(1, totalPartner / 20))
  vector.push(Math.min(1, (metrics.interviewerMessagesSent || 0) / 10))
  vector.push(Math.min(1, (metrics.partnerMessagesSent || 0) / 10))

  // Hint usage
  const hintsTotal = metrics.hintsTotal || 3
  vector.push(hintsTotal > 0 ? (metrics.hintsRevealed || 0) / hintsTotal : 0)

  // Test performance
  const testsTotal = metrics.testsTotal || 1
  vector.push(testsTotal > 0 ? (metrics.testsPassed || 0) / testsTotal : 0)
  vector.push(Math.min(1, (metrics.testsRunCount || 0) / 10))

  // Code metrics
  vector.push(Math.min(1, (metrics.linesOfCode || 0) / 200))
  vector.push(Math.min(1, (metrics.codeChangesCount || 0) / 50))
  vector.push(Math.min(1, (metrics.finalCodeLength || 0) / 5000))

  // Efficiency scores (already 0-100, normalize to 0-1)
  vector.push((metrics.codeEfficiencyScore || 50) / 100)
  vector.push((metrics.timeComplexityScore || 50) / 100)
  vector.push((metrics.spaceComplexityScore || 50) / 100)

  // Problem context (one-hot encoded)
  // Difficulty: easy=0, medium=0.5, hard=1
  const difficultyMap: Record<string, number> = { easy: 0, medium: 0.5, hard: 1 }
  vector.push(difficultyMap[metrics.problemDifficulty || "medium"] ?? 0.5)

  // Type: one-hot [dsa, bugfix, system-design]
  vector.push(metrics.problemType === "dsa" ? 1 : 0)
  vector.push(metrics.problemType === "bugfix" ? 1 : 0)
  vector.push(metrics.problemType === "system-design" ? 1 : 0)

  // Final scores (normalized)
  vector.push((metrics.correctnessScore || 50) / 100)
  vector.push((metrics.overallScore || 50) / 100)

  // Derived features
  const collaborationRatio =
    totalInterviewer + totalPartner > 0
      ? metrics.interviewerMessagesSent! / (totalInterviewer + totalPartner)
      : 0.5
  vector.push(collaborationRatio)

  const testEfficiency =
    testsTotal > 0 && (metrics.testsRunCount || 0) > 0
      ? (metrics.testsPassed || 0) / (metrics.testsRunCount || 1)
      : 0.5
  vector.push(testEfficiency)

  // Pad to fixed dimension
  while (vector.length < METRICS_VECTOR_DIM) {
    vector.push(0)
  }

  return vector.slice(0, METRICS_VECTOR_DIM)
}

/**
 * Extract code features for analysis
 */
export function extractCodeFeatures(code: string, language: string): CodeFeatures {
  const lines = code.split("\n")

  // Count patterns based on language
  const functionPatterns: Record<string, RegExp> = {
    javascript: /function\s+\w+|const\s+\w+\s*=\s*(?:async\s*)?\(|=>\s*[{(]/g,
    typescript: /function\s+\w+|const\s+\w+\s*=\s*(?:async\s*)?\(|=>\s*[{(]/g,
    python: /def\s+\w+\s*\(/g,
    java: /(?:public|private|protected)?\s*(?:static\s+)?[\w<>]+\s+\w+\s*\([^)]*\)\s*\{/g,
  }

  const classPatterns: Record<string, RegExp> = {
    javascript: /class\s+\w+/g,
    typescript: /class\s+\w+/g,
    python: /class\s+\w+/g,
    java: /class\s+\w+/g,
  }

  const loopPatterns = /for\s*\(|while\s*\(|\.forEach|\.map|\.filter|\.reduce|for\s+\w+\s+in/gi
  const conditionalPatterns = /if\s*\(|else\s*{|switch\s*\(|\?.*:/gi
  const recursionPattern = /(\w+)\s*\([^)]*\)[^{]*{[^}]*\1\s*\(/

  const funcPattern = functionPatterns[language] || functionPatterns.javascript
  const classPattern = classPatterns[language] || classPatterns.javascript

  const functionCount = (code.match(funcPattern) || []).length
  const classCount = (code.match(classPattern) || []).length
  const loopCount = (code.match(loopPatterns) || []).length
  const conditionalCount = (code.match(conditionalPatterns) || []).length

  // Calculate nesting depth
  let maxNestingDepth = 0
  let currentDepth = 0
  for (const char of code) {
    if (char === "{") {
      currentDepth++
      maxNestingDepth = Math.max(maxNestingDepth, currentDepth)
    } else if (char === "}") {
      currentDepth = Math.max(0, currentDepth - 1)
    }
  }

  // Pattern detection
  const usesHashMap = /Map\(|HashMap|new\s+Map|{}\s*;|\[\]|dict\(|{}/i.test(code)
  const usesSorting = /\.sort\(|sorted\(|Arrays\.sort|Collections\.sort/i.test(code)
  const usesRecursion = recursionPattern.test(code)
  const usesDynamicProgramming = /dp\[|memo\[|cache\[|@lru_cache|memoize/i.test(code)
  const usesGreedy = /greedy|Math\.max|Math\.min|max\(|min\(/i.test(code) && loopCount > 0

  // Quality features
  const hasComments = /\/\/|\/\*|#\s|"""/i.test(code)
  const hasErrorHandling = /try\s*{|catch\s*\(|except\s*:|throw\s+|raise\s+/i.test(code)
  const hasInputValidation =
    /if\s*\([^)]*null|if\s*\([^)]*undefined|if\s*\(.*\.length|if\s*\(.*==\s*None/i.test(code)

  const nonEmptyLines = lines.filter((l) => l.trim().length > 0)
  const averageLineLength =
    nonEmptyLines.length > 0
      ? nonEmptyLines.reduce((sum, l) => sum + l.length, 0) / nonEmptyLines.length
      : 0

  return {
    functionCount,
    classCount,
    loopCount,
    conditionalCount,
    recursionDetected: usesRecursion,
    hasComments,
    hasErrorHandling,
    hasInputValidation,
    averageLineLength,
    maxNestingDepth,
    usesHashMap,
    usesSorting,
    usesRecursion,
    usesDynamicProgramming,
    usesGreedy,
  }
}

/**
 * Convert code features to vector
 */
export function vectorizeCodeFeatures(features: CodeFeatures): number[] {
  return [
    Math.min(1, features.functionCount / 10),
    Math.min(1, features.classCount / 5),
    Math.min(1, features.loopCount / 10),
    Math.min(1, features.conditionalCount / 15),
    features.recursionDetected ? 1 : 0,
    features.hasComments ? 1 : 0,
    features.hasErrorHandling ? 1 : 0,
    features.hasInputValidation ? 1 : 0,
    Math.min(1, features.averageLineLength / 100),
    Math.min(1, features.maxNestingDepth / 6),
    features.usesHashMap ? 1 : 0,
    features.usesSorting ? 1 : 0,
    features.usesRecursion ? 1 : 0,
    features.usesDynamicProgramming ? 1 : 0,
    features.usesGreedy ? 1 : 0,
  ]
}

/**
 * Store session vector in Firestore
 */
export async function storeSessionVector(sessionVector: SessionVector): Promise<string> {
  try {
    const docRef = await adminDb.collection("session_vectors").add({
      ...sessionVector,
      userId: sessionVector.userId,
      user_id: sessionVector.userId, // For Firestore rules compatibility
      timestamp: Timestamp.fromDate(sessionVector.timestamp),
      createdAt: Timestamp.now(),
    })
    return docRef.id
  } catch (error) {
    console.error("Error storing session vector:", error)
    throw error
  }
}

/**
 * Find similar sessions based on vector similarity
 */
export async function findSimilarSessions(
  targetVector: number[],
  userId: string,
  options: {
    limit?: number
    excludeSessionId?: string
    sameType?: string
    sameDifficulty?: string
  } = {}
): Promise<Array<SessionVector & { similarity: number }>> {
  try {
    const q = adminDb
      .collection("session_vectors")
      .where("userId", "==", userId)
      .orderBy("timestamp", "desc")
      .limit(100)

    const snapshot = await q.get()
    const sessions: SessionVector[] = []

    snapshot.forEach((doc) => {
      const data = doc.data()
      if (options.excludeSessionId && doc.id === options.excludeSessionId) return
      if (options.sameType && data.metadata?.type !== options.sameType) return
      if (options.sameDifficulty && data.metadata?.difficulty !== options.sameDifficulty) return

      const timestamp =
        data.timestamp instanceof Timestamp
          ? data.timestamp.toDate()
          : data.timestamp?.toDate?.() || new Date(data.timestamp)

      sessions.push({
        ...data,
        sessionId: doc.id,
        timestamp,
      } as SessionVector)
    })

    const withSimilarity = sessions.map((session) => ({
      ...session,
      similarity: cosineSimilarity(targetVector, session.vector),
    }))

    return withSimilarity.sort((a, b) => b.similarity - a.similarity).slice(0, options.limit || 5)
  } catch (error) {
    console.error("Error finding similar sessions:", error)
    return []
  }
}

/**
 * Get or create user performance profile
 */
export async function getUserPerformanceProfile(
  userId: string
): Promise<UserPerformanceProfile | null> {
  try {
    const docRef = adminDb.collection("performance_profiles").doc(userId)
    const docSnap = await docRef.get()

    if (docSnap.exists) {
      const data = docSnap.data()
      if (!data) return null

      const lastUpdated =
        data.lastUpdated instanceof Timestamp
          ? data.lastUpdated.toDate()
          : data.lastUpdated?.toDate?.() || new Date(data.lastUpdated)

      return {
        ...data,
        lastUpdated,
      } as UserPerformanceProfile
    }

    return null
  } catch (error) {
    console.error("Error getting user profile:", error)
    return null
  }
}

/**
 * Update user performance profile with new session data
 */
export async function updateUserPerformanceProfile(
  userId: string,
  sessionVector: SessionVector
): Promise<void> {
  try {
    const existingProfile = await getUserPerformanceProfile(userId)

    const scoresByType = existingProfile?.scoresByType || {}
    const scoresByDifficulty = existingProfile?.scoresByDifficulty || {}

    const type = sessionVector.metadata.type
    const difficulty = sessionVector.metadata.difficulty

    scoresByType[type] = [...(scoresByType[type] || []), sessionVector.scores.overall]
    scoresByDifficulty[difficulty] = [
      ...(scoresByDifficulty[difficulty] || []),
      sessionVector.scores.overall,
    ]

    Object.keys(scoresByType).forEach((key) => {
      scoresByType[key] = scoresByType[key].slice(-20)
    })
    Object.keys(scoresByDifficulty).forEach((key) => {
      scoresByDifficulty[key] = scoresByDifficulty[key].slice(-20)
    })

    const allScores = Object.values(scoresByType).flat()
    const averageScore =
      allScores.length > 0 ? allScores.reduce((a, b) => a + b, 0) / allScores.length : 50

    const typeAverages = Object.entries(scoresByType).map(([type, scores]) => ({
      type,
      avg: scores.reduce((a, b) => a + b, 0) / scores.length,
    }))

    const strengthAreas = typeAverages
      .filter((t) => t.avg >= 70)
      .sort((a, b) => b.avg - a.avg)
      .slice(0, 3)
      .map((t) => t.type)

    const weaknessAreas = typeAverages
      .filter((t) => t.avg < 60)
      .sort((a, b) => a.avg - b.avg)
      .slice(0, 3)
      .map((t) => t.type)

    const recentScores = allScores.slice(-5)
    let recentTrend: "improving" | "stable" | "declining" = "stable"
    if (recentScores.length >= 3) {
      const firstHalf = recentScores.slice(0, Math.floor(recentScores.length / 2))
      const secondHalf = recentScores.slice(Math.floor(recentScores.length / 2))
      const firstAvg = firstHalf.reduce((a, b) => a + b, 0) / firstHalf.length
      const secondAvg = secondHalf.reduce((a, b) => a + b, 0) / secondHalf.length

      if (secondAvg - firstAvg > 5) recentTrend = "improving"
      else if (firstAvg - secondAvg > 5) recentTrend = "declining"
    }

    const vectorizedProfile = new Array(METRICS_VECTOR_DIM).fill(0)
    if (existingProfile?.vectorizedProfile) {
      const weight = 0.9
      for (let i = 0; i < METRICS_VECTOR_DIM; i++) {
        vectorizedProfile[i] =
          existingProfile.vectorizedProfile[i] * weight + sessionVector.vector[i] * (1 - weight)
      }
    } else {
      sessionVector.vector.forEach((v, i) => {
        if (i < METRICS_VECTOR_DIM) vectorizedProfile[i] = v
      })
    }

    const updatedProfile: UserPerformanceProfile = {
      userId,
      totalSessions: (existingProfile?.totalSessions || 0) + 1,
      averageScore,
      scoresByType,
      scoresByDifficulty,
      strengthAreas,
      weaknessAreas,
      recentTrend,
      vectorizedProfile,
      lastUpdated: new Date(),
    }

    const docRef = adminDb.collection("performance_profiles").doc(userId)
    await docRef.set(
      {
        ...updatedProfile,
        lastUpdated: Timestamp.fromDate(updatedProfile.lastUpdated),
      },
      { merge: true }
    )
  } catch (error) {
    console.error("Error updating user profile:", error)
  }
}

/**
 * Get recommended scenarios based on user profile
 */
export async function getRecommendedScenarios(
  userId: string,
  availableScenarios: Array<{ id: string; type: string; difficulty: string; title: string }>
): Promise<Array<{ id: string; reason: string; priority: number }>> {
  try {
    const profile = await getUserPerformanceProfile(userId)

    if (!profile) {
      return availableScenarios
        .filter((s) => s.difficulty === "easy")
        .slice(0, 3)
        .map((s) => ({
          id: s.id,
          reason: "Great starting point for new users",
          priority: 1,
        }))
    }

    const recommendations: Array<{ id: string; reason: string; priority: number }> = []

    for (const weakness of profile.weaknessAreas) {
      const matching = availableScenarios.filter((s) => s.type === weakness)
      if (matching.length > 0) {
        recommendations.push({
          id: matching[0].id,
          reason: `Practice ${weakness} to improve - currently a weak area`,
          priority: 1,
        })
      }
    }

    if (profile.recentTrend === "improving" && profile.averageScore > 70) {
      const hardProblems = availableScenarios.filter((s) => s.difficulty === "hard")
      if (hardProblems.length > 0) {
        recommendations.push({
          id: hardProblems[0].id,
          reason: "You're improving! Try a harder challenge",
          priority: 2,
        })
      }
    }

    if (profile.recentTrend === "declining") {
      for (const strength of profile.strengthAreas) {
        const matching = availableScenarios.filter(
          (s) => s.type === strength && s.difficulty === "easy"
        )
        if (matching.length > 0) {
          recommendations.push({
            id: matching[0].id,
            reason: `Rebuild confidence with ${strength} - your strength`,
            priority: 2,
          })
          break
        }
      }
    }

    const remainingSlots = 5 - recommendations.length
    const usedIds = new Set(recommendations.map((r) => r.id))
    const remaining = availableScenarios.filter((s) => !usedIds.has(s.id))

    for (let i = 0; i < Math.min(remainingSlots, remaining.length); i++) {
      recommendations.push({
        id: remaining[i].id,
        reason: "Diverse practice",
        priority: 3,
      })
    }

    return recommendations.sort((a, b) => a.priority - b.priority).slice(0, 5)
  } catch (error) {
    console.error("Error getting recommendations:", error)
    return []
  }
}

/**
 * Analytics: Get aggregate statistics for admin dashboard
 */
export async function getAggregateAnalytics(timeRange: "day" | "week" | "month" = "week"): Promise<{
  totalSessions: number
  averageScore: number
  scoreDistribution: Record<string, number>
  popularScenarios: Array<{ id: string; title: string; count: number }>
  providerUsage: Record<string, number>
  averageLatency: number
}> {
  try {
    const now = new Date()
    const startDate = new Date()

    switch (timeRange) {
      case "day":
        startDate.setDate(now.getDate() - 1)
        break
      case "week":
        startDate.setDate(now.getDate() - 7)
        break
      case "month":
        startDate.setMonth(now.getMonth() - 1)
        break
    }

    const q = adminDb
      .collection("session_vectors")
      .where("timestamp", ">=", Timestamp.fromDate(startDate))
      .orderBy("timestamp", "desc")

    const snapshot = await q.get()

    let totalScore = 0
    const scenarioCounts: Record<string, { title: string; count: number }> = {}
    const scoreRanges = { "0-20": 0, "21-40": 0, "41-60": 0, "61-80": 0, "81-100": 0 }

    snapshot.forEach((doc) => {
      const data = doc.data()
      totalScore += data.scores?.overall || 0

      const score = data.scores?.overall || 0
      if (score <= 20) scoreRanges["0-20"]++
      else if (score <= 40) scoreRanges["21-40"]++
      else if (score <= 60) scoreRanges["41-60"]++
      else if (score <= 80) scoreRanges["61-80"]++
      else scoreRanges["81-100"]++

      const scenarioId = data.scenarioId
      if (!scenarioCounts[scenarioId]) {
        scenarioCounts[scenarioId] = { title: data.scenarioTitle, count: 0 }
      }
      scenarioCounts[scenarioId].count++
    })

    const totalSessions = snapshot.size
    const averageScore = totalSessions > 0 ? totalScore / totalSessions : 0

    const popularScenarios = Object.entries(scenarioCounts)
      .map(([id, data]) => ({ id, ...data }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 10)

    return {
      totalSessions,
      averageScore: Math.round(averageScore),
      scoreDistribution: scoreRanges,
      popularScenarios,
      providerUsage: {},
      averageLatency: 0,
    }
  } catch (error) {
    console.error("Error getting aggregate analytics:", error)
    return {
      totalSessions: 0,
      averageScore: 0,
      scoreDistribution: {},
      popularScenarios: [],
      providerUsage: {},
      averageLatency: 0,
    }
  }
}

/**
 * Rate Limiting Metrics Tracking
 *
 * Tracks rate limit events for monitoring and abuse detection.
 * - Tracks blocked requests by endpoint
 * - Identifies repeat offenders
 * - Provides visibility into API abuse patterns
 */

import { adminDb } from './firebase-admin'
import { FieldValue } from 'firebase-admin/firestore'
import { logger } from './logger'

export interface RateLimitEvent {
  id?: string
  identifier: string // IP address or user ID
  endpoint: string // API endpoint that was rate limited
  blocked: boolean // Was the request blocked?
  remaining: number // Requests remaining in window
  resetTime: number // When the window resets
  timestamp: Date
  userAgent?: string
  country?: string // If available from headers
}

export interface RateLimitMetrics {
  totalRequests: number
  blockedRequests: number
  blockRate: number // Percentage of requests blocked
  uniqueIdentifiers: number // Unique IPs/users
  byEndpoint: Record<string, {
    total: number
    blocked: number
    blockRate: number
  }>
  topOffenders: Array<{
    identifier: string
    blockedCount: number
    lastBlocked: Date
    endpoints: string[]
  }>
  hourlyTrend: Array<{
    hour: string
    total: number
    blocked: number
  }>
  // Alert indicators
  alerts: {
    highBlockRate: boolean // Block rate > 10%
    ddosIndicator: boolean // Many blocks from single IP
    bruteForceIndicator: boolean // Repeated blocks on sensitive endpoints
  }
}

/**
 * Track a rate limit check (both allowed and blocked)
 */
export async function trackRateLimitEvent(event: Omit<RateLimitEvent, 'id' | 'timestamp'>): Promise<void> {
  try {
    // Only store blocked events to save space
    // For allowed requests, just increment counters
    if (event.blocked) {
      await adminDb.collection('rate_limit_events').add({
        ...event,
        timestamp: FieldValue.serverTimestamp(),
      })
    }

    // Update aggregate counters
    const now = new Date()
    const hourKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}-${String(now.getHours()).padStart(2, '0')}`

    const aggregateRef = adminDb.collection('rate_limit_aggregates').doc(hourKey)

    await adminDb.runTransaction(async (transaction) => {
      const doc = await transaction.get(aggregateRef)

      if (!doc.exists) {
        transaction.set(aggregateRef, {
          hour: hourKey,
          total: 1,
          blocked: event.blocked ? 1 : 0,
          byEndpoint: {
            [event.endpoint]: {
              total: 1,
              blocked: event.blocked ? 1 : 0,
            },
          },
          uniqueIdentifiers: [event.identifier],
          createdAt: FieldValue.serverTimestamp(),
        })
      } else {
        const data = doc.data()!
        const byEndpoint = data.byEndpoint || {}

        if (!byEndpoint[event.endpoint]) {
          byEndpoint[event.endpoint] = { total: 0, blocked: 0 }
        }
        byEndpoint[event.endpoint].total++
        if (event.blocked) byEndpoint[event.endpoint].blocked++

        const identifiers = new Set(data.uniqueIdentifiers || [])
        identifiers.add(event.identifier)

        transaction.update(aggregateRef, {
          total: FieldValue.increment(1),
          blocked: FieldValue.increment(event.blocked ? 1 : 0),
          byEndpoint,
          uniqueIdentifiers: Array.from(identifiers),
        })
      }
    })

    // Track repeat offenders
    if (event.blocked) {
      const offenderRef = adminDb.collection('rate_limit_offenders').doc(event.identifier.replace(/[\/\.]/g, '_'))

      await adminDb.runTransaction(async (transaction) => {
        const doc = await transaction.get(offenderRef)

        if (!doc.exists) {
          transaction.set(offenderRef, {
            identifier: event.identifier,
            blockedCount: 1,
            firstBlocked: FieldValue.serverTimestamp(),
            lastBlocked: FieldValue.serverTimestamp(),
            endpoints: [event.endpoint],
          })
        } else {
          const endpoints = new Set(doc.data()?.endpoints || [])
          endpoints.add(event.endpoint)

          transaction.update(offenderRef, {
            blockedCount: FieldValue.increment(1),
            lastBlocked: FieldValue.serverTimestamp(),
            endpoints: Array.from(endpoints),
          })
        }
      })
    }
  } catch (error) {
    // Don't let metrics tracking break the app
    logger.error('Failed to track rate limit event', { error, endpoint: event.endpoint })
  }
}

/**
 * Get rate limit metrics for admin dashboard
 */
export async function getRateLimitMetrics(hours: number = 24): Promise<RateLimitMetrics> {
  const metrics: RateLimitMetrics = {
    totalRequests: 0,
    blockedRequests: 0,
    blockRate: 0,
    uniqueIdentifiers: 0,
    byEndpoint: {},
    topOffenders: [],
    hourlyTrend: [],
    alerts: {
      highBlockRate: false,
      ddosIndicator: false,
      bruteForceIndicator: false,
    },
  }

  try {
    const now = new Date()
    const cutoffTime = new Date(now.getTime() - hours * 60 * 60 * 1000)

    // Get hourly aggregates
    const aggregatesSnapshot = await adminDb
      .collection('rate_limit_aggregates')
      .orderBy('createdAt', 'desc')
      .limit(hours)
      .get()

    const allIdentifiers = new Set<string>()

    for (const doc of aggregatesSnapshot.docs) {
      const data = doc.data()

      metrics.totalRequests += data.total || 0
      metrics.blockedRequests += data.blocked || 0

      // Merge endpoint stats
      for (const [endpoint, stats] of Object.entries(data.byEndpoint || {})) {
        if (!metrics.byEndpoint[endpoint]) {
          metrics.byEndpoint[endpoint] = { total: 0, blocked: 0, blockRate: 0 }
        }
        const s = stats as { total: number; blocked: number }
        metrics.byEndpoint[endpoint].total += s.total
        metrics.byEndpoint[endpoint].blocked += s.blocked
      }

      // Track unique identifiers
      for (const id of data.uniqueIdentifiers || []) {
        allIdentifiers.add(id)
      }

      // Add to hourly trend
      metrics.hourlyTrend.push({
        hour: data.hour,
        total: data.total || 0,
        blocked: data.blocked || 0,
      })
    }

    metrics.uniqueIdentifiers = allIdentifiers.size

    // Calculate block rates
    if (metrics.totalRequests > 0) {
      metrics.blockRate = (metrics.blockedRequests / metrics.totalRequests) * 100
    }

    for (const endpoint of Object.keys(metrics.byEndpoint)) {
      const stats = metrics.byEndpoint[endpoint]
      if (stats.total > 0) {
        stats.blockRate = (stats.blocked / stats.total) * 100
      }
    }

    // Get top offenders
    const offendersSnapshot = await adminDb
      .collection('rate_limit_offenders')
      .orderBy('blockedCount', 'desc')
      .limit(20)
      .get()

    metrics.topOffenders = offendersSnapshot.docs.map(doc => {
      const data = doc.data()
      return {
        identifier: data.identifier,
        blockedCount: data.blockedCount,
        lastBlocked: data.lastBlocked?.toDate() || new Date(),
        endpoints: data.endpoints || [],
      }
    })

    // Set alerts
    metrics.alerts.highBlockRate = metrics.blockRate > 10

    // DDoS indicator: single IP with > 100 blocks in 24h
    metrics.alerts.ddosIndicator = metrics.topOffenders.some(o => o.blockedCount > 100)

    // Brute force indicator: multiple blocks on sensitive endpoints
    const sensitiveEndpoints = ['rl:sensitive', 'rl:promo', 'rl:guest']
    metrics.alerts.bruteForceIndicator = metrics.topOffenders.some(o =>
      o.blockedCount > 10 && o.endpoints.some(e => sensitiveEndpoints.some(s => e.includes(s)))
    )

    // Sort hourly trend
    metrics.hourlyTrend.sort((a, b) => a.hour.localeCompare(b.hour))

  } catch (error) {
    logger.error('Failed to get rate limit metrics', { error })
  }

  return metrics
}

/**
 * Clear old rate limit data (run daily via cron)
 */
export async function cleanupRateLimitData(daysToKeep: number = 7): Promise<void> {
  try {
    const cutoffDate = new Date()
    cutoffDate.setDate(cutoffDate.getDate() - daysToKeep)

    // Delete old events
    const oldEventsSnapshot = await adminDb
      .collection('rate_limit_events')
      .where('timestamp', '<', cutoffDate)
      .limit(500)
      .get()

    const batch = adminDb.batch()
    for (const doc of oldEventsSnapshot.docs) {
      batch.delete(doc.ref)
    }
    await batch.commit()

    logger.info('Cleaned up old rate limit data', {
      deletedEvents: oldEventsSnapshot.size,
    })
  } catch (error) {
    logger.error('Failed to cleanup rate limit data', { error })
  }
}

/**
 * Rate limiting utilities for API endpoints
 * Prevents abuse by limiting requests per IP/user
 *
 * IMPORTANT: This implementation supports both in-memory (development)
 * and distributed (production) rate limiting stores.
 *
 * For production with serverless (Vercel, Cloudflare Workers, etc.):
 * - Set UPSTASH_REDIS_REST_URL and UPSTASH_REDIS_REST_TOKEN env vars
 * - Or implement a custom RateLimitStore using Firestore/Redis
 */

import { NextRequest, NextResponse } from "next/server"
import { logger } from "./logger"

interface RateLimitConfig {
  interval: number // Time window in milliseconds
  uniqueTokenPerInterval: number // Max number of unique tokens (IPs/users) to track
  maxRequests: number // Max requests per interval
  prefix?: string // Prefix for rate limit keys (helps identify endpoint)
}

interface RateLimitEntry {
  count: number
  resetTime: number
}

interface RateLimitResult {
  allowed: boolean
  remaining: number
  resetTime: number
  retryAfter?: number
}

/**
 * Rate Limit Store Interface
 * Implement this for different backends (Redis, Firestore, etc.)
 */
interface RateLimitStore {
  get(key: string): Promise<RateLimitEntry | null>
  set(key: string, entry: RateLimitEntry, ttlMs: number): Promise<void>
  increment(key: string, config: RateLimitConfig): Promise<RateLimitResult>
}

/**
 * In-Memory Rate Limit Store
 * WARNING: Only suitable for single-instance deployments or development
 * Each serverless instance will have its own store, allowing bypass
 *
 * NOTE: Uses lazy cleanup instead of setInterval to avoid memory leaks
 * in serverless environments where global intervals never get cleared
 */
class InMemoryRateLimitStore implements RateLimitStore {
  private store = new Map<string, RateLimitEntry>()
  private lastCleanupTime = Date.now()
  private readonly CLEANUP_INTERVAL_MS = 5 * 60 * 1000 // 5 minutes

  /**
   * Perform lazy cleanup of expired entries
   * Called before each operation to prevent memory buildup
   */
  private lazyCleanup(): void {
    const now = Date.now()
    if (now - this.lastCleanupTime > this.CLEANUP_INTERVAL_MS) {
      for (const [key, entry] of this.store.entries()) {
        if (entry.resetTime < now) {
          this.store.delete(key)
        }
      }
      this.lastCleanupTime = now
    }
  }

  async get(key: string): Promise<RateLimitEntry | null> {
    // Perform lazy cleanup on each access
    this.lazyCleanup()

    const entry = this.store.get(key)
    if (!entry) return null
    if (entry.resetTime < Date.now()) {
      this.store.delete(key)
      return null
    }
    return entry
  }

  async set(key: string, entry: RateLimitEntry, _ttlMs: number): Promise<void> {
    this.store.set(key, entry)
  }

  async increment(key: string, config: RateLimitConfig): Promise<RateLimitResult> {
    // Perform lazy cleanup on each access
    this.lazyCleanup()

    const now = Date.now()
    let entry = this.store.get(key)

    if (!entry || entry.resetTime < now) {
      // Create new window
      entry = {
        count: 1,
        resetTime: now + config.interval,
      }
      this.store.set(key, entry)
      return {
        allowed: true,
        remaining: config.maxRequests - 1,
        resetTime: entry.resetTime,
      }
    }

    // Check if limit exceeded BEFORE incrementing
    if (entry.count >= config.maxRequests) {
      return {
        allowed: false,
        remaining: 0,
        resetTime: entry.resetTime,
        retryAfter: Math.ceil((entry.resetTime - now) / 1000),
      }
    }

    // Increment count
    entry.count++
    this.store.set(key, entry)

    return {
      allowed: true,
      remaining: config.maxRequests - entry.count,
      resetTime: entry.resetTime,
    }
  }

  // For testing: clear the store
  clear(): void {
    this.store.clear()
  }

  // For testing: get store size
  size(): number {
    return this.store.size
  }
}

/**
 * Upstash Redis Rate Limit Store
 * Production-ready distributed rate limiting using Upstash Redis
 * Requires UPSTASH_REDIS_REST_URL and UPSTASH_REDIS_REST_TOKEN env vars
 */
class UpstashRateLimitStore implements RateLimitStore {
  private baseUrl: string
  private token: string

  constructor() {
    this.baseUrl = process.env.UPSTASH_REDIS_REST_URL || ""
    this.token = process.env.UPSTASH_REDIS_REST_TOKEN || ""
  }

  private async redis(command: string[]): Promise<any> {
    const response = await fetch(`${this.baseUrl}`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${this.token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(command),
    })

    if (!response.ok) {
      throw new Error(`Upstash Redis error: ${response.statusText}`)
    }

    const data = await response.json()
    return data.result
  }

  async get(key: string): Promise<RateLimitEntry | null> {
    try {
      const result = await this.redis(["GET", key])
      if (!result) return null
      return JSON.parse(result) as RateLimitEntry
    } catch (error) {
      logger.error("Upstash get error", { key, error })
      return null
    }
  }

  async set(key: string, entry: RateLimitEntry, ttlMs: number): Promise<void> {
    try {
      await this.redis(["SET", key, JSON.stringify(entry), "PX", ttlMs.toString()])
    } catch (error) {
      logger.error("Upstash set error", { key, error })
    }
  }

  async increment(key: string, config: RateLimitConfig): Promise<RateLimitResult> {
    const now = Date.now()

    try {
      // Use Lua script for atomic increment operation
      // This ensures consistency in distributed environments
      const luaScript = `
        local key = KEYS[1]
        local now = tonumber(ARGV[1])
        local interval = tonumber(ARGV[2])
        local maxRequests = tonumber(ARGV[3])

        local data = redis.call('GET', key)
        local count = 1
        local resetTime = now + interval

        if data then
          local parsed = cjson.decode(data)
          if parsed.resetTime > now then
            count = parsed.count + 1
            resetTime = parsed.resetTime
          end
        end

        local entry = cjson.encode({count = count, resetTime = resetTime})
        local ttl = math.ceil((resetTime - now) / 1000) + 1
        redis.call('SET', key, entry, 'EX', ttl)

        return cjson.encode({count = count, resetTime = resetTime, maxRequests = maxRequests})
      `

      // For simplicity, we'll use a simpler approach with GET + SET
      // A production implementation should use EVAL with Lua script above
      const entry = await this.get(key)

      if (!entry || entry.resetTime < now) {
        const newEntry = {
          count: 1,
          resetTime: now + config.interval,
        }
        await this.set(key, newEntry, config.interval + 1000)
        return {
          allowed: true,
          remaining: config.maxRequests - 1,
          resetTime: newEntry.resetTime,
        }
      }

      if (entry.count >= config.maxRequests) {
        return {
          allowed: false,
          remaining: 0,
          resetTime: entry.resetTime,
          retryAfter: Math.ceil((entry.resetTime - now) / 1000),
        }
      }

      entry.count++
      const ttl = entry.resetTime - now + 1000
      await this.set(key, entry, ttl)

      return {
        allowed: true,
        remaining: config.maxRequests - entry.count,
        resetTime: entry.resetTime,
      }
    } catch (error) {
      logger.error("Upstash increment error, falling back to allow", { key, error })
      // Fail open on errors - don't block users if Redis is down
      return {
        allowed: true,
        remaining: config.maxRequests,
        resetTime: now + config.interval,
      }
    }
  }
}

/**
 * Firestore Rate Limit Store
 * Uses Firebase Firestore for distributed rate limiting
 * Good option if you're already using Firebase
 */
class FirestoreRateLimitStore implements RateLimitStore {
  async get(key: string): Promise<RateLimitEntry | null> {
    try {
      const { adminDb } = await import("./firebase-admin")
      const doc = await adminDb.collection("rate_limits").doc(key).get()
      if (!doc.exists) return null

      const data = doc.data()
      if (!data) return null

      const entry: RateLimitEntry = {
        count: data.count || 0,
        resetTime: data.resetTime || 0,
      }

      if (entry.resetTime < Date.now()) {
        await adminDb.collection("rate_limits").doc(key).delete()
        return null
      }

      return entry
    } catch (error) {
      logger.error("Firestore rate limit get error", { key, error })
      return null
    }
  }

  async set(key: string, entry: RateLimitEntry, _ttlMs: number): Promise<void> {
    try {
      const { adminDb } = await import("./firebase-admin")
      await adminDb.collection("rate_limits").doc(key).set({
        count: entry.count,
        resetTime: entry.resetTime,
        updatedAt: Date.now(),
      })
    } catch (error) {
      logger.error("Firestore rate limit set error", { key, error })
    }
  }

  async increment(key: string, config: RateLimitConfig): Promise<RateLimitResult> {
    const now = Date.now()

    try {
      const { adminDb, FieldValue } = await import("./firebase-admin")
      const docRef = adminDb.collection("rate_limits").doc(key)

      // Use transaction for atomic increment
      const result = await adminDb.runTransaction(async (transaction) => {
        const doc = await transaction.get(docRef)
        let count = 1
        let resetTime = now + config.interval

        if (doc.exists) {
          const data = doc.data()
          if (data && data.resetTime > now) {
            count = (data.count || 0) + 1
            resetTime = data.resetTime
          }
        }

        transaction.set(docRef, {
          count,
          resetTime,
          updatedAt: now,
        })

        return { count, resetTime }
      })

      const allowed = result.count <= config.maxRequests

      return {
        allowed,
        remaining: Math.max(0, config.maxRequests - result.count),
        resetTime: result.resetTime,
        retryAfter: allowed ? undefined : Math.ceil((result.resetTime - now) / 1000),
      }
    } catch (error) {
      logger.error("Firestore rate limit increment error, falling back to allow", { key, error })
      // Fail open
      return {
        allowed: true,
        remaining: config.maxRequests,
        resetTime: now + config.interval,
      }
    }
  }
}

/**
 * Get the appropriate rate limit store based on environment
 *
 * Priority:
 * 1. Upstash Redis (fastest, recommended for Vercel)
 * 2. Firestore (good if already using Firebase, default for production)
 * 3. In-memory (development only)
 */
function getRateLimitStore(): RateLimitStore {
  // Check for Upstash Redis (recommended for Vercel - fastest option)
  if (process.env.UPSTASH_REDIS_REST_URL && process.env.UPSTASH_REDIS_REST_TOKEN) {
    logger.info("Using Upstash Redis for rate limiting")
    return new UpstashRateLimitStore()
  }

  // In production, default to Firestore if Firebase is configured
  // This ensures distributed rate limiting works across serverless instances
  const isProduction = process.env.NODE_ENV === "production"
  const hasFirebaseConfig =
    process.env.FIREBASE_ADMIN_PRIVATE_KEY || process.env.GOOGLE_APPLICATION_CREDENTIALS

  if (hasFirebaseConfig) {
    // Use Firestore in production by default, or if explicitly enabled
    if (isProduction || process.env.USE_FIRESTORE_RATE_LIMIT === "true") {
      logger.info("Using Firestore for distributed rate limiting")
      return new FirestoreRateLimitStore()
    }
  }

  // Fallback to in-memory (development only)
  if (isProduction) {
    // SECURITY: In production, require distributed rate limiting to prevent bypass
    // Each serverless instance has its own in-memory store, allowing attackers
    // to bypass limits by distributing requests across instances
    const errorMessage =
      "SECURITY ERROR: No distributed rate limiting configured in production. " +
      "Configure UPSTASH_REDIS_REST_URL/TOKEN or ensure Firebase Admin is properly configured. " +
      "Set ALLOW_INSECURE_RATE_LIMIT=true to override (NOT RECOMMENDED)."

    if (process.env.ALLOW_INSECURE_RATE_LIMIT !== "true") {
      logger.error(errorMessage)
      throw new Error(errorMessage)
    }

    logger.warn(
      "Using in-memory rate limiting in production - this may allow rate limit bypass. " +
        "Configure UPSTASH_REDIS_REST_URL/TOKEN or ensure Firebase Admin is properly configured."
    )
  }
  return new InMemoryRateLimitStore()
}

// Singleton store instance
let rateLimitStore: RateLimitStore | null = null

function getStore(): RateLimitStore {
  if (!rateLimitStore) {
    rateLimitStore = getRateLimitStore()
  }
  return rateLimitStore
}

/**
 * Get client identifier (IP address or user ID)
 */
function getClientIdentifier(request: NextRequest): string {
  // Try to get IP from headers (works with proxies/load balancers)
  const forwarded = request.headers.get("x-forwarded-for")
  const realIp = request.headers.get("x-real-ip")
  const cfConnectingIp = request.headers.get("cf-connecting-ip") // Cloudflare

  if (cfConnectingIp) {
    return cfConnectingIp
  }

  if (forwarded) {
    return forwarded.split(",")[0].trim()
  }

  if (realIp) {
    return realIp
  }

  // Fallback to a generic identifier
  return "unknown"
}

/**
 * Rate limit middleware
 * Returns null if allowed, or NextResponse with 429 if rate limited
 */
export function rateLimit(config: RateLimitConfig) {
  const prefix = config.prefix || "rl"

  return async (request: NextRequest): Promise<NextResponse | null> => {
    const identifier = getClientIdentifier(request)
    const key = `${prefix}:${identifier}`
    const store = getStore()

    try {
      const result = await store.increment(key, config)

      if (!result.allowed) {
        logger.warn("Rate limit exceeded", {
          key,
          identifier,
          retryAfter: result.retryAfter,
        })

        return NextResponse.json(
          {
            error: "Too many requests. Please try again later.",
            retryAfter: result.retryAfter,
          },
          {
            status: 429,
            headers: {
              "Retry-After": (result.retryAfter || 60).toString(),
              "X-RateLimit-Limit": config.maxRequests.toString(),
              "X-RateLimit-Remaining": "0",
              "X-RateLimit-Reset": result.resetTime.toString(),
            },
          }
        )
      }

      return null // Allow request
    } catch (error) {
      logger.error("Rate limiting error, allowing request", { key, error })
      // Fail open - don't block users if rate limiting fails
      return null
    }
  }
}

