/**
 * Diagnostic Quiz for Cold Start Problem
 *
 * Solves the "cold start" problem by assessing user ability
 * before generating a personalized roadmap.
 *
 * Uses Item Response Theory (IRT) for rapid ability estimation
 * from a small number of adaptive questions.
 */

import { DSAPattern } from '@/lib/types/dsa-patterns';

/**
 * Difficulty parameters for IRT
 * Based on 3-parameter logistic model
 */
export interface ProblemIRTParams {
  scenarioId: string;
  title: string;
  pattern: DSAPattern;
  difficulty: 'easy' | 'medium' | 'hard';

  // IRT parameters
  a: number;  // Discrimination (how well it separates abilities)
  b: number;  // Difficulty (ability level at 50% success)
  c: number;  // Guessing (lower asymptote)
}

/**
 * User's estimated ability
 */
export interface AbilityEstimate {
  theta: number;              // Overall ability (-3 to 3 scale)
  standardError: number;      // Confidence interval
  patternAbilities: Map<DSAPattern, number>;  // Per-pattern estimates
}

/**
 * Quiz response
 */
export interface QuizResponse {
  scenarioId: string;
  pattern: DSAPattern;
  correct: boolean;          // Solved successfully
  partialScore: number;      // 0-100
  timeSeconds: number;       // Time taken
  hintsUsed: number;
}

/**
 * Diagnostic quiz configuration
 */
export interface DiagnosticQuizConfig {
  minQuestions: number;      // Minimum questions before stopping
  maxQuestions: number;      // Maximum questions
  targetSE: number;          // Target standard error for stopping
  timeLimit: number;         // Total time limit in minutes
  perQuestionLimit: number;  // Per-question limit in minutes
}

export const DEFAULT_QUIZ_CONFIG: DiagnosticQuizConfig = {
  minQuestions: 5,
  maxQuestions: 10,
  targetSE: 0.4,           // Stop when SE < 0.4
  timeLimit: 30,
  perQuestionLimit: 5,
};

/**
 * Core patterns to assess (covers major interview topics)
 */
export const DIAGNOSTIC_PATTERNS: DSAPattern[] = [
  'arrays-hashing',     // Foundation
  'two-pointers',       // Foundation
  'trees',              // Core data structure
  'graphs',             // Intermediate
  'dp-1d',              // Advanced
];

/**
 * Difficulty to IRT b-parameter mapping
 */
const DIFFICULTY_B: Record<'easy' | 'medium' | 'hard', number> = {
  easy: -1.0,
  medium: 0.0,
  hard: 1.5,
};

/**
 * Calculate probability of correct response using 3PL IRT model
 */
export function calculateProbability(
  theta: number,
  params: ProblemIRTParams
): number {
  const { a, b, c } = params;
  const exponent = -a * (theta - b);
  return c + (1 - c) / (1 + Math.exp(exponent));
}

/**
 * Calculate information provided by a question at ability level theta
 */
export function calculateInformation(
  theta: number,
  params: ProblemIRTParams
): number {
  const { a, b, c } = params;
  const p = calculateProbability(theta, params);
  const q = 1 - p;

  // Fisher information for 3PL model
  const numerator = Math.pow(a, 2) * q * Math.pow(p - c, 2);
  const denominator = p * Math.pow(1 - c, 2);

  return denominator > 0 ? numerator / denominator : 0;
}

/**
 * Update ability estimate using Maximum Likelihood Estimation
 */
export function updateAbilityEstimate(
  currentTheta: number,
  responses: QuizResponse[],
  problems: Map<string, ProblemIRTParams>
): AbilityEstimate {
  // Newton-Raphson iteration for MLE
  let theta = currentTheta;
  const maxIterations = 20;
  const tolerance = 0.001;

  for (let iter = 0; iter < maxIterations; iter++) {
    let numerator = 0;
    let denominator = 0;

    for (const response of responses) {
      const params = problems.get(response.scenarioId);
      if (!params) continue;

      const p = calculateProbability(theta, params);
      const q = 1 - p;
      const { a, c } = params;

      // Use partial score as weighted response
      const u = response.partialScore / 100;

      const pStar = (p - c) / (1 - c);
      const weight = a * pStar * q;

      numerator += weight * (u - p) / p;
      denominator += a * a * pStar * pStar * q / p;
    }

    if (Math.abs(denominator) < 0.0001) break;

    const delta = numerator / denominator;
    theta += delta;

    // Bound theta
    theta = Math.max(-4, Math.min(4, theta));

    if (Math.abs(delta) < tolerance) break;
  }

  // Calculate standard error
  let totalInfo = 0;
  for (const response of responses) {
    const params = problems.get(response.scenarioId);
    if (params) {
      totalInfo += calculateInformation(theta, params);
    }
  }
  const standardError = totalInfo > 0 ? 1 / Math.sqrt(totalInfo) : 2.0;

  // Calculate per-pattern abilities
  const patternAbilities = new Map<DSAPattern, number>();
  const patternResponses = new Map<DSAPattern, QuizResponse[]>();

  for (const response of responses) {
    const existing = patternResponses.get(response.pattern) || [];
    existing.push(response);
    patternResponses.set(response.pattern, existing);
  }

  for (const [pattern, resps] of patternResponses) {
    // Simple average-based adjustment from overall theta
    const avgScore = resps.reduce((s, r) => s + r.partialScore, 0) / resps.length;
    const adjustment = (avgScore - 50) / 100; // -0.5 to 0.5
    patternAbilities.set(pattern, theta + adjustment);
  }

  return {
    theta,
    standardError,
    patternAbilities,
  };
}

/**
 * Select next question adaptively
 */
export function selectNextQuestion(
  currentTheta: number,
  availableProblems: ProblemIRTParams[],
  usedIds: Set<string>,
  responses: QuizResponse[]
): ProblemIRTParams | null {
  // Filter out used problems
  const unused = availableProblems.filter(p => !usedIds.has(p.scenarioId));
  if (unused.length === 0) return null;

  // Calculate information for each problem
  const withInfo = unused.map(p => ({
    problem: p,
    information: calculateInformation(currentTheta, p),
  }));

  // Balance between maximum information and pattern coverage
  const usedPatterns = new Set(responses.map(r => r.pattern));
  const uncoveredPatterns = DIAGNOSTIC_PATTERNS.filter(p => !usedPatterns.has(p));

  // If we haven't covered all patterns, prioritize uncovered
  if (uncoveredPatterns.length > 0 && responses.length < 5) {
    const uncoveredProblems = withInfo.filter(
      x => uncoveredPatterns.includes(x.problem.pattern)
    );
    if (uncoveredProblems.length > 0) {
      // Pick highest information from uncovered patterns
      uncoveredProblems.sort((a, b) => b.information - a.information);
      return uncoveredProblems[0].problem;
    }
  }

  // Otherwise, pick maximum information
  withInfo.sort((a, b) => b.information - a.information);
  return withInfo[0]?.problem || null;
}

/**
 * Check if quiz should stop
 */
export function shouldStopQuiz(
  responses: QuizResponse[],
  ability: AbilityEstimate,
  config: DiagnosticQuizConfig = DEFAULT_QUIZ_CONFIG
): { stop: boolean; reason: string } {
  // Not enough questions
  if (responses.length < config.minQuestions) {
    return { stop: false, reason: 'Need more responses' };
  }

  // Too many questions
  if (responses.length >= config.maxQuestions) {
    return { stop: true, reason: 'Maximum questions reached' };
  }

  // Standard error low enough
  if (ability.standardError < config.targetSE) {
    return { stop: true, reason: 'Sufficient precision achieved' };
  }

  return { stop: false, reason: 'Continue for better precision' };
}

/**
 * Convert ability estimate to experience level
 */
export function abilityToExperienceLevel(
  theta: number
): 'intern' | 'beginner' | 'intermediate' | 'advanced' {
  if (theta < -1.0) return 'intern';
  if (theta < 0.0) return 'beginner';
  if (theta < 1.0) return 'intermediate';
  return 'advanced';
}

/**
 * Convert ability estimate to pattern familiarity
 */
export function abilityToFamiliarity(
  theta: number
): 'unknown' | 'seen' | 'practiced' | 'confident' {
  if (theta < -1.5) return 'unknown';
  if (theta < -0.5) return 'seen';
  if (theta < 0.5) return 'practiced';
  return 'confident';
}

/**
 * Generate initial assessment from quiz results
 */
export function generateAssessmentFromQuiz(
  responses: QuizResponse[],
  ability: AbilityEstimate
): {
  experienceLevel: 'intern' | 'beginner' | 'intermediate' | 'advanced';
  patternFamiliarity: Array<{ pattern: DSAPattern; level: 'unknown' | 'seen' | 'practiced' | 'confident' }>;
  problemsSolvedEstimate: number;
  confidence: number;
} {
  const experienceLevel = abilityToExperienceLevel(ability.theta);

  // Generate familiarity for all patterns
  const patternFamiliarity: Array<{ pattern: DSAPattern; level: 'unknown' | 'seen' | 'practiced' | 'confident' }> = [];

  for (const pattern of DIAGNOSTIC_PATTERNS) {
    const patternTheta = ability.patternAbilities.get(pattern) ?? ability.theta;
    patternFamiliarity.push({
      pattern,
      level: abilityToFamiliarity(patternTheta),
    });
  }

  // Estimate problems solved based on ability
  const problemsSolvedEstimate = Math.round(
    Math.max(0, (ability.theta + 2) * 50) // -2 -> 0, 0 -> 100, 2 -> 200
  );

  // Confidence based on standard error
  const confidence = Math.round(
    Math.max(0, Math.min(100, 100 - ability.standardError * 50))
  );

  return {
    experienceLevel,
    patternFamiliarity,
    problemsSolvedEstimate,
    confidence,
  };
}

/**
 * Create IRT parameters for a problem
 */
export function createProblemParams(
  scenarioId: string,
  title: string,
  pattern: DSAPattern,
  difficulty: 'easy' | 'medium' | 'hard'
): ProblemIRTParams {
  return {
    scenarioId,
    title,
    pattern,
    difficulty,
    a: difficulty === 'medium' ? 1.2 : (difficulty === 'easy' ? 0.8 : 1.5),
    b: DIFFICULTY_B[difficulty],
    c: 0.15, // 15% guess rate
  };
}

/**
 * Quiz state for managing the diagnostic process
 */
export interface QuizState {
  status: 'not_started' | 'in_progress' | 'completed';
  currentQuestion: ProblemIRTParams | null;
  responses: QuizResponse[];
  usedIds: Set<string>;
  ability: AbilityEstimate;
  startTime: Date | null;
  config: DiagnosticQuizConfig;
}

/**
 * Create initial quiz state
 */
export function createQuizState(
  config: DiagnosticQuizConfig = DEFAULT_QUIZ_CONFIG
): QuizState {
  return {
    status: 'not_started',
    currentQuestion: null,
    responses: [],
    usedIds: new Set(),
    ability: {
      theta: 0, // Start at average
      standardError: 2.0,
      patternAbilities: new Map(),
    },
    startTime: null,
    config,
  };
}

/**
 * Start the quiz
 */
export function startQuiz(
  state: QuizState,
  availableProblems: ProblemIRTParams[]
): QuizState {
  const nextQuestion = selectNextQuestion(
    state.ability.theta,
    availableProblems,
    state.usedIds,
    state.responses
  );

  return {
    ...state,
    status: 'in_progress',
    currentQuestion: nextQuestion,
    startTime: new Date(),
  };
}

/**
 * Submit a response and get next question
 */
export function submitResponse(
  state: QuizState,
  response: QuizResponse,
  availableProblems: ProblemIRTParams[],
  problemParams: Map<string, ProblemIRTParams>
): QuizState {
  // Add response
  const responses = [...state.responses, response];
  const usedIds = new Set(state.usedIds);
  usedIds.add(response.scenarioId);

  // Update ability estimate
  const ability = updateAbilityEstimate(
    state.ability.theta,
    responses,
    problemParams
  );

  // Check if should stop
  const { stop } = shouldStopQuiz(responses, ability, state.config);

  if (stop) {
    return {
      ...state,
      responses,
      usedIds,
      ability,
      status: 'completed',
      currentQuestion: null,
    };
  }

  // Select next question
  const nextQuestion = selectNextQuestion(
    ability.theta,
    availableProblems,
    usedIds,
    responses
  );

  if (!nextQuestion) {
    return {
      ...state,
      responses,
      usedIds,
      ability,
      status: 'completed',
      currentQuestion: null,
    };
  }

  return {
    ...state,
    responses,
    usedIds,
    ability,
    currentQuestion: nextQuestion,
  };
}

/**
 * Get quiz progress
 */
export function getQuizProgress(state: QuizState): {
  questionsAnswered: number;
  maxQuestions: number;
  currentAbility: number;
  confidence: number;
  estimatedLevel: string;
} {
  return {
    questionsAnswered: state.responses.length,
    maxQuestions: state.config.maxQuestions,
    currentAbility: Math.round((state.ability.theta + 2) * 25), // Scale to 0-100
    confidence: Math.round((1 - state.ability.standardError / 2) * 100),
    estimatedLevel: abilityToExperienceLevel(state.ability.theta),
  };
}

/**
 * Edge Case Handlers for Roadmap
 *
 * Handles all the edge cases and scenarios that can occur
 * during interview preparation.
 */

import { PersonalizedRoadmap, DailyPlan } from "@/lib/data/company-questions/types"
import { DSAPattern } from "@/lib/types/dsa-patterns"
import { formatPatternLabel } from "@/lib/pattern-labels"

/**
 * Roadmap health status
 */
export type RoadmapHealth =
  | "healthy"
  | "slightly_behind"
  | "significantly_behind"
  | "ahead"
  | "struggling"
  | "inactive"
  | "cramming"
  | "expired"
  | "completed"

/**
 * Intervention type
 */
export type InterventionType =
  | "none"
  | "gentle_nudge"
  | "catch_up_mode"
  | "difficulty_adjustment"
  | "pattern_focus"
  | "re_engagement"
  | "celebration"
  | "final_review"

/**
 * User struggle indicators
 */
export interface StruggleIndicators {
  consecutiveLowScores: number
  patternFailStreak: Map<DSAPattern, number>
  skippedInARow: number
  averageScore: number
  hintUsageRate: number
}

/**
 * Health check result
 */
export interface HealthCheckResult {
  health: RoadmapHealth
  intervention: InterventionType
  message: string
  suggestions: string[]
  adjustments: RoadmapAdjustments
}

/**
 * Adjustments to apply to roadmap
 */
export interface RoadmapAdjustments {
  difficultyOverride?: "easy" | "medium" | null
  filterToMustKnows?: boolean
  dailyTargetMultiplier?: number
  enableTutorialMode?: boolean
  skipHardProblems?: boolean
  focusPatterns?: DSAPattern[]
  showWorkedExamples?: boolean
}

/**
 * Check roadmap health and determine intervention
 */
export function checkRoadmapHealth(
  roadmap: PersonalizedRoadmap,
  struggleIndicators: StruggleIndicators,
  lastSessionDate: Date | null
): HealthCheckResult {
  const now = new Date()
  const interviewDate = new Date(roadmap.interviewDate)
  const daysRemaining = Math.ceil((interviewDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24))

  // Check expired
  if (daysRemaining < 0) {
    return handleExpired(roadmap)
  }

  // Check completed
  if (roadmap.questionsCompleted >= roadmap.totalQuestions) {
    return handleCompleted(roadmap, daysRemaining)
  }

  // Check inactive
  if (lastSessionDate) {
    const daysSinceSession = Math.floor(
      (now.getTime() - lastSessionDate.getTime()) / (1000 * 60 * 60 * 24)
    )
    if (daysSinceSession >= 7) {
      return handleInactive(roadmap, daysSinceSession)
    }
  }

  // Check struggling
  if (isStruggling(struggleIndicators)) {
    return handleStruggling(roadmap, struggleIndicators)
  }

  // Check progress status
  const expectedProgress = getExpectedProgress(roadmap, daysRemaining)
  const actualProgress = roadmap.questionsCompleted / roadmap.totalQuestions
  const progressDiff = actualProgress - expectedProgress

  if (progressDiff < -0.15) {
    return handleSignificantlyBehind(roadmap, daysRemaining, progressDiff)
  }

  if (progressDiff < -0.05) {
    return handleSlightlyBehind(roadmap, daysRemaining)
  }

  if (progressDiff > 0.15) {
    return handleAhead(roadmap, daysRemaining)
  }

  // Check cramming (close to interview with lots to do)
  if (daysRemaining <= 3 && actualProgress < 0.8) {
    return handleCramming(roadmap, daysRemaining)
  }

  // Final review mode
  if (daysRemaining <= 2) {
    return handleFinalReview(roadmap, daysRemaining)
  }

  // All good
  return {
    health: "healthy",
    intervention: "none",
    message: "You're on track! Keep up the great work.",
    suggestions: [],
    adjustments: {},
  }
}

/**
 * Check if user is struggling
 */
function isStruggling(indicators: StruggleIndicators): boolean {
  return (
    indicators.consecutiveLowScores >= 3 ||
    indicators.skippedInARow >= 5 ||
    indicators.averageScore < 40 ||
    indicators.hintUsageRate > 0.8
  )
}

/**
 * Get expected progress at this point
 */
function getExpectedProgress(roadmap: PersonalizedRoadmap, daysRemaining: number): number {
  // Null safety: check if assessment exists and has daysRemaining
  const totalDays = roadmap.assessment?.daysRemaining ?? roadmap.dailyPlans?.length ?? 1
  if (totalDays <= 0) return 1 // Avoid division by zero
  const daysElapsed = totalDays - daysRemaining
  return Math.min(1, Math.max(0, daysElapsed / totalDays))
}

/**
 * Handle expired roadmap
 */
function handleExpired(roadmap: PersonalizedRoadmap): HealthCheckResult {
  const progress = Math.round((roadmap.questionsCompleted / roadmap.totalQuestions) * 100)

  return {
    health: "expired",
    intervention: "none",
    message: `Your interview date has passed. You completed ${progress}% of your roadmap.`,
    suggestions: [
      "Archive this roadmap and create a new one",
      "Review what you learned for future interviews",
      "If you have another interview coming, start fresh!",
    ],
    adjustments: {},
  }
}

/**
 * Handle completed roadmap
 */
function handleCompleted(roadmap: PersonalizedRoadmap, daysRemaining: number): HealthCheckResult {
  const suggestions: string[] = []

  if (daysRemaining > 0) {
    suggestions.push("Practice mock interviews to stay sharp")
    suggestions.push("Review your weakest patterns")
    suggestions.push(`${daysRemaining} days to rest and prepare mentally`)
  } else {
    suggestions.push("You did it! Now go ace that interview!")
  }

  return {
    health: "completed",
    intervention: "celebration",
    message: `Congratulations! You completed your entire ${roadmap.companyName} roadmap!`,
    suggestions,
    adjustments: {},
  }
}

/**
 * Handle inactive user (7+ days without practice)
 */
function handleInactive(roadmap: PersonalizedRoadmap, daysSinceSession: number): HealthCheckResult {
  return {
    health: "inactive",
    intervention: "re_engagement",
    message: `Welcome back! It's been ${daysSinceSession} days since your last session.`,
    suggestions: [
      "Let's start with an easy warm-up problem",
      "No pressure - pick up where you left off",
      "Consider adjusting your daily target if needed",
    ],
    adjustments: {
      difficultyOverride: "easy", // Start easy after break
      dailyTargetMultiplier: 0.7, // Reduce expectations
      showWorkedExamples: true,
    },
  }
}

/**
 * Handle struggling user
 */
function handleStruggling(
  roadmap: PersonalizedRoadmap,
  indicators: StruggleIndicators
): HealthCheckResult {
  // Find which pattern is causing issues
  let worstPattern: DSAPattern | null = null
  let maxFails = 0

  for (const [pattern, fails] of indicators.patternFailStreak) {
    if (fails > maxFails) {
      maxFails = fails
      worstPattern = pattern
    }
  }

  const suggestions: string[] = [
    "Take a breath - struggling means you're learning!",
    "Try watching solution explanations before attempting",
  ]

  if (worstPattern) {
    suggestions.push(`Let's focus on building ${formatPatternLabel(worstPattern)} fundamentals`)
  }

  if (indicators.consecutiveLowScores >= 3) {
    suggestions.push("Consider stepping down to easier problems temporarily")
  }

  return {
    health: "struggling",
    intervention: "difficulty_adjustment",
    message: "You're facing some tough problems. Let's adjust the approach.",
    suggestions,
    adjustments: {
      difficultyOverride: "easy",
      enableTutorialMode: true,
      showWorkedExamples: true,
      skipHardProblems: true,
      focusPatterns: worstPattern ? [worstPattern] : undefined,
    },
  }
}

/**
 * Handle significantly behind schedule
 */
function handleSignificantlyBehind(
  roadmap: PersonalizedRoadmap,
  daysRemaining: number,
  progressDiff: number
): HealthCheckResult {
  const behindBy = Math.round(Math.abs(progressDiff) * 100)

  const suggestions: string[] = []

  if (daysRemaining > 7) {
    suggestions.push("Focus on must-know questions for this company")
    suggestions.push("Consider increasing daily study time if possible")
    suggestions.push("Quality > quantity - it's better to master fewer patterns")
  } else {
    suggestions.push("Prioritize the highest-value problems only")
    suggestions.push("Skip advanced patterns and focus on fundamentals")
    suggestions.push("Make sure to get enough rest too!")
  }

  return {
    health: "significantly_behind",
    intervention: "catch_up_mode",
    message: `You're about ${behindBy}% behind schedule. Let's prioritize what matters most.`,
    suggestions,
    adjustments: {
      filterToMustKnows: true,
      skipHardProblems: daysRemaining <= 7,
      dailyTargetMultiplier: 0.7, // Focus on quality
      difficultyOverride: "medium",
    },
  }
}

/**
 * Handle slightly behind schedule
 */
function handleSlightlyBehind(
  roadmap: PersonalizedRoadmap,
  daysRemaining: number
): HealthCheckResult {
  return {
    health: "slightly_behind",
    intervention: "gentle_nudge",
    message: "You're slightly behind schedule, but easily recoverable!",
    suggestions: [
      "Try to complete one extra problem today",
      "Consider a focused study session this weekend",
      "You've got this!",
    ],
    adjustments: {},
  }
}

/**
 * Handle ahead of schedule
 */
function handleAhead(roadmap: PersonalizedRoadmap, daysRemaining: number): HealthCheckResult {
  return {
    health: "ahead",
    intervention: "none",
    message: "Excellent progress! You're ahead of schedule.",
    suggestions: [
      "Consider tackling some harder problems",
      "Deep dive into your weakest patterns",
      "Try timed mock interviews",
    ],
    adjustments: {},
  }
}

/**
 * Handle cramming (close to interview with lots to do)
 */
function handleCramming(roadmap: PersonalizedRoadmap, daysRemaining: number): HealthCheckResult {
  return {
    health: "cramming",
    intervention: "catch_up_mode",
    message: `Only ${daysRemaining} days left. Let's maximize what you can learn.`,
    suggestions: [
      "Focus ONLY on must-know problems",
      "Skip hard problems - medium is enough",
      "Review patterns you already know",
      "Get good sleep - it helps retention!",
    ],
    adjustments: {
      filterToMustKnows: true,
      skipHardProblems: true,
      difficultyOverride: "medium",
      dailyTargetMultiplier: 0.6,
    },
  }
}

/**
 * Handle final review mode
 */
function handleFinalReview(roadmap: PersonalizedRoadmap, daysRemaining: number): HealthCheckResult {
  const isIntern = roadmap.assessment?.experienceLevel === "intern"

  const suggestions = isIntern
    ? [
        "Practice explaining your thought process out loud",
        "Review completed problems, don't try new ones",
        "Focus on communication - it matters for interns!",
        "Get plenty of sleep tonight",
      ]
    : [
        "Light review of must-know problems",
        "Don't learn anything new",
        "Review your strongest patterns for confidence",
        "Rest and prepare mentally",
      ]

  return {
    health: "healthy",
    intervention: "final_review",
    message:
      daysRemaining === 0
        ? "Interview day! You've prepared well. Trust yourself!"
        : `${daysRemaining} day${daysRemaining > 1 ? "s" : ""} until your interview. Focus on rest and confidence.`,
    suggestions,
    adjustments: {
      skipHardProblems: true,
      filterToMustKnows: true,
      dailyTargetMultiplier: 0.3,
    },
  }
}

/**
 * Calculate struggle indicators from roadmap data
 */
export function calculateStruggleIndicators(
  roadmap: PersonalizedRoadmap,
  recentScores: number[],
  recentHintsUsed: number[],
  recentStatuses: Array<"completed" | "skipped">
): StruggleIndicators {
  // Count consecutive low scores (< 50)
  let consecutiveLowScores = 0
  for (let i = recentScores.length - 1; i >= 0; i--) {
    if (recentScores[i] < 50) {
      consecutiveLowScores++
    } else {
      break
    }
  }

  // Count skipped in a row
  let skippedInARow = 0
  for (let i = recentStatuses.length - 1; i >= 0; i--) {
    if (recentStatuses[i] === "skipped") {
      skippedInARow++
    } else {
      break
    }
  }

  // Average score
  const averageScore =
    recentScores.length > 0 ? recentScores.reduce((a, b) => a + b, 0) / recentScores.length : 0

  // Hint usage rate
  const totalAttempts = recentScores.length
  const attemptsWithHints = recentHintsUsed.filter((h) => h > 0).length
  const hintUsageRate = totalAttempts > 0 ? attemptsWithHints / totalAttempts : 0

  // Pattern fail streaks (simplified - would need more data)
  const patternFailStreak = new Map<DSAPattern, number>()

  return {
    consecutiveLowScores,
    patternFailStreak,
    skippedInARow,
    averageScore,
    hintUsageRate,
  }
}

/**
 * Apply adjustments to a daily plan
 */
export function applyAdjustments(
  plan: DailyPlan,
  adjustments: RoadmapAdjustments,
  mustKnowIds: Set<string>
): DailyPlan {
  let questions = [...plan.questions]

  // IMPORTANT: Apply difficulty filters BEFORE must-know filtering
  // This ensures must-know questions are never filtered out by difficulty rules

  // Apply difficulty override (but preserve must-knows)
  if (adjustments.difficultyOverride) {
    questions = questions.filter(
      (q) =>
        q.difficulty === adjustments.difficultyOverride ||
        q.difficulty === "easy" || // Always allow easy
        mustKnowIds.has(q.scenarioId) // Always preserve must-knows
    )
  }

  // Skip hard problems (but preserve must-knows)
  if (adjustments.skipHardProblems) {
    questions = questions.filter((q) => q.difficulty !== "hard" || mustKnowIds.has(q.scenarioId))
  }

  // Filter to must-knows if needed (applied AFTER difficulty filters)
  if (adjustments.filterToMustKnows) {
    const mustKnows = questions.filter((q) => mustKnowIds.has(q.scenarioId))
    if (mustKnows.length > 0) {
      questions = mustKnows
    }
  }

  // Apply daily target multiplier
  if (adjustments.dailyTargetMultiplier) {
    const targetCount = Math.ceil(questions.length * adjustments.dailyTargetMultiplier)
    questions = questions.slice(0, targetCount)
  }

  // Focus on specific patterns
  if (adjustments.focusPatterns && adjustments.focusPatterns.length > 0) {
    const focused = questions.filter((q) =>
      adjustments.focusPatterns!.includes(q.pattern as DSAPattern)
    )
    if (focused.length > 0) {
      questions = focused
    }
  }

  return {
    ...plan,
    questions,
    targetMinutes: questions.reduce((sum, q) => sum + q.estimatedMinutes, 0),
  }
}

