/**
 * Get user's performance trends
 */
export async function getPerformanceTrends(
  userId: string,
  days: number = 30
): Promise<{
  daily: Array<{ date: string; score: number; sessions: number }>
  weeklyAverage: number
  trend: "improving" | "stable" | "declining"
}> {
  try {
    const startDate = new Date()
    startDate.setDate(startDate.getDate() - days)

    const snapshot = await adminDb
      .collection("users")
      .doc(userId)
      .collection("session_summaries")
      .where("completedAt", ">=", startDate.toISOString())
      .orderBy("completedAt", "asc")
      .get()

    // Group by date
    const dailyMap = new Map<string, { total: number; count: number }>()

    snapshot.docs.forEach((doc) => {
      const data = doc.data()
      // Skip sessions without a valid performance score
      const score = data.performanceScore ?? data.performance_score
      if (score === undefined || score === null || score === 0) return

      const date = data.completedAt.split("T")[0]
      const existing = dailyMap.get(date) || { total: 0, count: 0 }
      existing.total += score
      existing.count++
      dailyMap.set(date, existing)
    })

    const daily = Array.from(dailyMap.entries()).map(([date, { total, count }]) => ({
      date,
      score: Math.round(total / count),
      sessions: count,
    }))

    // Calculate weekly average (last 7 days)
    const lastWeek = daily.slice(-7)
    const weeklyAverage =
      lastWeek.length > 0
        ? Math.round(lastWeek.reduce((sum, d) => sum + d.score, 0) / lastWeek.length)
        : 0

    // Calculate trend
    let trend: "improving" | "stable" | "declining" = "stable"
    if (daily.length >= 4) {
      const firstHalf = daily.slice(0, Math.floor(daily.length / 2))
      const secondHalf = daily.slice(Math.floor(daily.length / 2))

      const firstAvg = firstHalf.reduce((s, d) => s + d.score, 0) / firstHalf.length
      const secondAvg = secondHalf.reduce((s, d) => s + d.score, 0) / secondHalf.length

      if (secondAvg - firstAvg > 5) trend = "improving"
      else if (firstAvg - secondAvg > 5) trend = "declining"
    }

    return { daily, weeklyAverage, trend }
  } catch (error) {
    console.error("[Session Metrics] Failed to get trends:", error)
    return { daily: [], weeklyAverage: 0, trend: "stable" }
  }
}

/**
 * Algorithm Router for A/B Testing
 *
 * Routes spaced repetition calculations to either SM-2 or FSRS
 * based on user's assigned algorithm. Handles:
 * - Algorithm assignment for new users (50/50 random)
 * - Routing calculations to the correct algorithm
 * - Converting between algorithm-specific data structures
 * - Recording research events for analysis
 */

import { adminDb } from "../firebase-admin"
import type { SpacedRepetitionAlgorithm, SpacedRepetitionMasteryLevel } from "../types"
import type { Difficulty, MasteryLevel as SM2MasteryLevel } from "./sm2-algorithm"
import {
  calculateNextInterval as sm2Calculate,
  mapScoreToQuality,
  calculateConfidence as sm2Confidence,
  determineMasteryLevel as sm2MasteryLevel,
  estimateRetention as sm2EstimateRetention,
  type SM2Input,
  type SM2Output,
} from "./sm2-algorithm"
import {
  scheduleFSRS,
  createFSRSCard,
  mapPerformanceToFSRSRating,
  getEstimatedRetention as fsrsEstimateRetention,
  getMasteryLevel as fsrsMasteryLevel,
  getConfidence as fsrsConfidence,
  calculateRetrievability,
  DEFAULT_FSRS_CONFIG,
  type FSRSCard,
  type FSRSRating,
} from "./fsrs-algorithm"

// ============================================
// Types
// ============================================

export interface AlgorithmState {
  algorithm: SpacedRepetitionAlgorithm

  // Unified state (stored in problem_mastery)
  interval_days: number
  next_review_at: string
  review_count: number
  mastery_level: SpacedRepetitionMasteryLevel
  confidence: number

  // SM-2 specific
  ease_factor?: number
  scores_history?: number[]

  // FSRS specific
  fsrs_state?: FSRSCard
}

export interface ReviewInput {
  performance_score: number // 0-100 (interview score - includes communication)
  time_spent_minutes: number
  hints_used: number
  problem_difficulty: Difficulty
