    hints_used?: number
  }
): Promise<ProblemMastery> {
  const masteryRef = adminDb
    .collection("problem_mastery")
    .doc(userId)
    .collection("problems")
    .doc(sessionData.scenario_id)

  const doc = await masteryRef.get()
  const now = new Date()

  // Use mastery_score for last_score if provided, otherwise use performance_score
  const scoreForLastScore = sessionData.mastery_score ?? sessionData.performance_score

  if (doc.exists) {
    // Update existing record
    return updateProblemMastery(userId, sessionData.scenario_id, {
      performance_score: sessionData.performance_score,
      last_score: scoreForLastScore,
      time_spent_minutes: sessionData.time_spent_minutes,
      hints_used: sessionData.hints_used,
    })
  }

  // Get user's assigned algorithm (SM-2 or FSRS)
  const userAlgorithm = await getUserAlgorithm(userId)

  // Create initial state for the algorithm
  const initialState = createInitialState(userAlgorithm, sessionData.difficulty)

  // Calculate the next review using the algorithm router
  // This respects the user's assigned algorithm and the performance score
  const reviewResult = await calculateNextReview(userId, initialState, {
    performance_score: sessionData.performance_score,
    time_spent_minutes: sessionData.time_spent_minutes || 0,
    hints_used: sessionData.hints_used || 0,
    problem_difficulty: sessionData.difficulty,
    is_early_review: false,
    days_overdue: 0,
  })

  // Prepare storage data from algorithm result
  const storageData = prepareStateForStorage({
    algorithm: reviewResult.algorithm,
    interval_days: reviewResult.next_interval_days,
    next_review_at: reviewResult.next_review_at,
    review_count: 1,
    mastery_level: reviewResult.mastery_level,
    confidence: reviewResult.confidence,
    ease_factor: reviewResult.ease_factor,
    fsrs_state: reviewResult.fsrs_state,
  })

  // Create new record with algorithm-calculated review data
  const newMastery: ProblemMastery = {
    problem_id: sessionData.scenario_id,
    scenario_id: sessionData.scenario_id,
    title: sessionData.title,
    pattern: sessionData.pattern,
    difficulty: sessionData.difficulty,
    ease_factor: (storageData.ease_factor as number) || 2.5,
    interval_days: storageData.interval_days as number,
    review_count: 1,
    next_review_at: storageData.next_review_at as string,
    last_score: scoreForLastScore,
    average_score: sessionData.performance_score,
    best_score: sessionData.performance_score,
    scores_history: [sessionData.performance_score],
    first_seen_at: now.toISOString(),
    last_reviewed_at: now.toISOString(),
    time_spent_minutes: sessionData.time_spent_minutes || 0,
    hints_used_total: sessionData.hints_used || 0,
    mastery_level: reviewResult.mastery_level as MasteryLevel,
    confidence: reviewResult.confidence,
    fsrs_difficulty: storageData.fsrs_difficulty as number | undefined,
    fsrs_stability: storageData.fsrs_stability as number | undefined,
    fsrs_state: storageData.fsrs_state as string | undefined,
    fsrs_lapses: storageData.fsrs_lapses as number | undefined,
  }

  await masteryRef.set(newMastery)
  return newMastery
}

// ============================================
// Batch Deferral (Overflow Management)
// ============================================

export interface BatchDeferralResult {
  deferred_count: number
  deferred_problem_ids: string[]
  remaining_due_count: number
  spread_days: number
}

/**
 * Batch defer low-priority problems to reduce review overload
 *
 * This function integrates properly with both SM-2 and FSRS algorithms
 * by simulating a "struggled" review rather than applying manual penalties.
 *
 * Algorithm behavior:
 * - SM-2: performance_score=50 triggers quality=2, reducing ease_factor
 * - FSRS: Maps to rating=2 (Hard), adjusting difficulty/stability properly
 *
 * Spreading logic prevents future backlog:
 * - 50% of items deferred to tomorrow
 * - 30% to day 2
 * - 20% spread across days 3-7
 *
 * @param userId - User ID
 * @param targetLimit - Maximum problems to keep in queue
 * @param maxDaysToSpread - Max days to spread deferrals (default 7)
 */
export async function batchDeferProblems(
  userId: string,
  targetLimit: number,
  maxDaysToSpread: number = 7
): Promise<BatchDeferralResult> {
  // Get all due problems
  const dueQueue = await getDueProblems(userId, {
    limit: 100, // Get more than needed to see full picture
    includeUpcoming: false,
  })

  // Combine all due items (due_now + due_in_minutes + due_today)
  const allDueItems = [...dueQueue.due_now, ...dueQueue.due_in_minutes, ...dueQueue.due_today]

  // If not over limit, nothing to defer
  if (allDueItems.length <= targetLimit) {
    return {
      deferred_count: 0,
      deferred_problem_ids: [],
      remaining_due_count: allDueItems.length,
      spread_days: 0,
    }
  }

  // Sort by priority (highest first - we want to KEEP high priority)
  const sorted = [...allDueItems].sort((a, b) => b.priority_score - a.priority_score)

  // Keep the top N items, defer the rest
  const toKeep = sorted.slice(0, targetLimit)
  const toDefer = sorted.slice(targetLimit)

  // Get user's algorithm for proper deferral
  const userAlgorithm = await getUserAlgorithm(userId)

  // Calculate spread distribution
  const totalToDefer = toDefer.length
  const day1Count = Math.ceil(totalToDefer * 0.5) // 50% tomorrow
  const day2Count = Math.ceil(totalToDefer * 0.3) // 30% day 2
  // remaining 20% spread across days 3-7

  // Assign each deferred item to a day
  const deferredProblemIds: string[] = []
  let maxDayUsed = 1

  for (let i = 0; i < toDefer.length; i++) {
    const item = toDefer[i]
    let daysToAdd: number

    if (i < day1Count) {
      daysToAdd = 1 // Tomorrow
    } else if (i < day1Count + day2Count) {
      daysToAdd = 2 // Day 2
    } else {
      // Spread remaining across days 3-7
      const remainingIndex = i - day1Count - day2Count
      const daysAvailable = Math.min(maxDaysToSpread - 2, 5) // Days 3-7
      daysToAdd = 3 + (remainingIndex % daysAvailable)
    }

    maxDayUsed = Math.max(maxDayUsed, daysToAdd)

    // Defer this item using algorithm-appropriate method
    await deferSingleProblem(userId, item.problem_id, item.difficulty, daysToAdd, userAlgorithm)
    deferredProblemIds.push(item.problem_id)
  }

  return {
    deferred_count: toDefer.length,
    deferred_problem_ids: deferredProblemIds,
    remaining_due_count: toKeep.length,
    spread_days: maxDayUsed,
  }
}

/**
 * Defer a single problem using algorithm-integrated logic
 *
 * Instead of manually adjusting ease_factor or FSRS difficulty,
 * this simulates a "struggled" review to get proper algorithm behavior.
 */
async function deferSingleProblem(
  userId: string,
  problemId: string,
  difficulty: Difficulty,
  daysToDefer: number,
  algorithm: "sm2" | "fsrs"
): Promise<void> {
  const masteryRef = adminDb
    .collection("problem_mastery")
    .doc(userId)
    .collection("problems")
    .doc(problemId)

  const doc = await masteryRef.get()
  if (!doc.exists) return

  const current = doc.data() as ProblemMastery

  // Reconstruct current state for algorithm
  const currentState = reconstructState(algorithm, {
    interval_days: current.interval_days,
    next_review_at: current.next_review_at,
    review_count: current.review_count,
    mastery_level: current.mastery_level as any,
    confidence: current.confidence,
    ease_factor: current.ease_factor,
    fsrs_difficulty: (current as any).fsrs_difficulty,
    fsrs_stability: (current as any).fsrs_stability,
    fsrs_state: (current as any).fsrs_state,
    fsrs_lapses: (current as any).fsrs_lapses,
    last_reviewed_at: current.last_reviewed_at,
    scores_history: current.scores_history,
  })

  // Simulate a "struggled" review (score=50 maps to quality=2 for SM-2, rating=2 for FSRS)
  // This properly reduces ease_factor/stability without fully resetting progress
  const deferInput = {
    performance_score: 50, // "Struggled" score
    time_spent_minutes: 0,
    hints_used: 0,
    problem_difficulty: difficulty,
    is_early_review: false,
    days_overdue: 0,
  }

  const reviewResult = await calculateNextReview(userId, currentState, deferInput)

  // Override the next_review_at to spread items across days
  const deferDate = new Date()
  deferDate.setDate(deferDate.getDate() + daysToDefer)
  deferDate.setHours(9, 0, 0, 0) // Set to 9 AM for consistent scheduling

  // Prepare update data
  const storageData = prepareStateForStorage({
    algorithm: reviewResult.algorithm,
    interval_days: daysToDefer, // Use the defer days as the new interval
    next_review_at: deferDate.toISOString(),
    review_count: currentState.review_count, // Don't increment - this wasn't a real review
    mastery_level: reviewResult.mastery_level,
    confidence: reviewResult.confidence,
    ease_factor: reviewResult.ease_factor,
    fsrs_state: reviewResult.fsrs_state,
  })

  // Update the mastery record
  await masteryRef.update({
    ...storageData,
    // Mark that this was a deferral, not a real review
    last_deferred_at: new Date().toISOString(),
  })
}

/**
 * Enhanced SM-2 Spaced Repetition Algorithm
 *
 * Improvements over standard SM-2:
 * - Difficulty weighting (hard problems have shorter intervals)
 * - Streak bonus (7+ day streak increases intervals)
 * - Time decay (early reviews reduce interval growth)
 * - Performance trend (consecutive perfect scores = bonus)
 * - Forgetting curve (overdue by 2x interval resets to learning)
 */

import type { MasteryLevel } from "@/lib/scoring/types"

export type Difficulty = "easy" | "medium" | "hard"

// Re-export MasteryLevel for backwards compatibility with existing imports
export type { MasteryLevel }

export interface SM2Input {
  previousInterval: number // Days since last review
  previousEaseFactor: number // 1.3 - 2.5 (default 2.5)
  performanceScore: number // 0-100 performance score
  reviewCount: number // Total times reviewed
  lastReviewDate: Date
  problemDifficulty: Difficulty
  streakDays?: number // Current streak (optional)
  scoresHistory?: number[] // Recent scores for trend analysis
  isEarlyReview?: boolean // True if reviewed before due date
  daysOverdue?: number // How many days past due date
}

export interface SM2Output {
  nextInterval: number // Days until next review
  newEaseFactor: number // Updated ease factor
  masteryLevel: MasteryLevel // Current mastery status
  confidence: number // 0-100 confidence score
  quality: number // 0-5 SM-2 quality score
}

// Difficulty weight multipliers
const DIFFICULTY_WEIGHTS: Record<Difficulty, number> = {
  easy: 1.2,
  medium: 1.0,
  hard: 0.8,
}

// Streak bonus thresholds
const STREAK_BONUS_THRESHOLD = 7
const STREAK_BONUS_MULTIPLIER = 1.1

// Early review penalty
const EARLY_REVIEW_MULTIPLIER = 0.7

// Performance trend bonus (3+ consecutive perfect scores)
const PERFECT_SCORE_THRESHOLD = 86
const CONSECUTIVE_PERFECT_BONUS = 1.15

// Overdue threshold for reset (2x interval)
const OVERDUE_RESET_MULTIPLIER = 2

// Max interval cap
const MAX_INTERVAL_DAYS = 180

// Ease factor bounds (standard SM-2 uses 1.3 - 2.5)
const MIN_EASE_FACTOR = 1.3
const MAX_EASE_FACTOR = 2.5
const DEFAULT_EASE_FACTOR = 2.5

/**
 * Maps performance score (0-100) to SM-2 quality rating (0-5)
 *
 * Quality mappings:
 * 0-20   → quality 0 (complete blackout)
 * 21-40  → quality 1 (incorrect but remembered something)
 * 41-55  → quality 2 (incorrect but easy to recall)
 * 56-70  → quality 3 (correct with difficulty)
 * 71-85  → quality 4 (correct with hesitation)
 * 86-100 → quality 5 (perfect response)
 */
export function mapScoreToQuality(performanceScore: number): number {
  if (performanceScore <= 20) return 0
  if (performanceScore <= 40) return 1
  if (performanceScore <= 55) return 2
  if (performanceScore <= 70) return 3
  if (performanceScore <= 85) return 4
  return 5
}

/**
 * Calculate confidence score based on multiple factors
 */
export function calculateConfidence(
  interval: number,
  quality: number,
  reviewCount: number,
  scoresHistory?: number[]
): number {
  let confidence = 0

  // Base confidence from quality (0-40)
  confidence += quality * 8

  // Interval contribution (0-30) - longer intervals = higher confidence
  const intervalScore = Math.min(30, (interval / MAX_INTERVAL_DAYS) * 30)
  confidence += intervalScore

  // Review count contribution (0-20)
  const reviewScore = Math.min(20, reviewCount * 2)
  confidence += reviewScore

  // Consistency bonus (0-10) - if recent scores are consistent
  if (scoresHistory && scoresHistory.length >= 3) {
    const recentScores = scoresHistory.slice(-3)
    const avgScore = recentScores.reduce((a, b) => a + b, 0) / recentScores.length
    const variance =
      recentScores.reduce((sum, s) => sum + Math.pow(s - avgScore, 2), 0) / recentScores.length
    const consistency = Math.max(0, 10 - variance / 100)
    confidence += consistency
  }

  return Math.min(100, Math.round(confidence))
}

/**
 * Determine mastery level based on interval and review count
 *
 * Note: reviewCount here is the NEW count AFTER the review (so first review = 1)
 *
 * Mastery progression:
 * - 'new': Never reviewed
 * - 'learning': Short intervals (< 7 days) or failed reviews
 * - 'reviewing': Medium intervals (7-20 days), building confidence
 * - 'mastered': Long intervals (21+ days), consistently good performance
 *
 * With perfect scores, typical progression:
 * - Review 1: 1 day → learning
 * - Review 2: 3 days → learning
 * - Review 3: 7-8 days → reviewing
 * - Review 4: 20+ days → mastered (if interval >= 21)
 */
export function determineMasteryLevel(
  interval: number,
  reviewCount: number,
  quality: number
): MasteryLevel {
  // Failed review = back to learning
  if (quality < 3) return "learning"

  // Never reviewed = new (reviewCount is post-review, so 0 means never reviewed)
  if (reviewCount === 0) return "new"

  // Based on interval thresholds (lowered from 30 to 21 for faster mastery progression)
  // 21 days = 3 weeks of consistent good performance = reasonable mastery indicator
  if (interval >= 21) return "mastered"
  if (interval >= 7) return "reviewing"

  // First few reviews with short intervals = still learning
  return "learning"
}

/**
 * Apply difficulty weight to interval
 */
export function applyDifficultyWeight(interval: number, difficulty: Difficulty): number {
  return Math.round(interval * DIFFICULTY_WEIGHTS[difficulty])
}

/**
 * Apply streak bonus to interval
 */
export function applyStreakBonus(interval: number, streakDays?: number): number {
  if (streakDays && streakDays >= STREAK_BONUS_THRESHOLD) {
    return Math.round(interval * STREAK_BONUS_MULTIPLIER)
  }
  return interval
}

/**
 * Check if user has consecutive perfect scores
 */
export function hasConsecutivePerfectScores(scoresHistory?: number[]): boolean {
  if (!scoresHistory || scoresHistory.length < 3) return false
  const recent = scoresHistory.slice(-3)
  return recent.every((score) => score >= PERFECT_SCORE_THRESHOLD)
}

/**
 * Check if problem is severely overdue (needs reset)
 */
export function isSeverelyOverdue(daysOverdue: number, previousInterval: number): boolean {
  return daysOverdue > previousInterval * OVERDUE_RESET_MULTIPLIER
}

/**
 * Main SM-2 calculation function with enhancements
 */
export function calculateNextInterval(input: SM2Input): SM2Output {
  const {
    previousInterval,
    previousEaseFactor,
    performanceScore,
    reviewCount,
    problemDifficulty,
    streakDays,
    scoresHistory,
    isEarlyReview,
    daysOverdue,
  } = input

  const quality = mapScoreToQuality(performanceScore)

  // Check for severe overdue - reset to learning
  if (daysOverdue && isSeverelyOverdue(daysOverdue, previousInterval)) {
    return {
      nextInterval: 1,
      newEaseFactor: Math.max(MIN_EASE_FACTOR, previousEaseFactor - 0.15),
      masteryLevel: "learning",
      confidence: 10,
      quality,
    }
  }

  // Failed review (quality < 3) - reset to beginning
  if (quality < 3) {
    return {
      nextInterval: 1,
      newEaseFactor: Math.max(MIN_EASE_FACTOR, previousEaseFactor - 0.2),
      masteryLevel: "learning",
      confidence: Math.min(20, calculateConfidence(1, quality, reviewCount, scoresHistory)),
      quality,
    }
  }

  // Successful review - calculate new interval
  let interval: number

  if (reviewCount === 0) {
    // First successful review
    interval = 1
  } else if (reviewCount === 1) {
    // Second successful review
    interval = 3
  } else {
    // Subsequent reviews - use SM-2 formula
    interval = Math.round(previousInterval * previousEaseFactor)
  }

  // Apply modifiers
  interval = applyDifficultyWeight(interval, problemDifficulty)
  interval = applyStreakBonus(interval, streakDays)

  // Apply early review penalty
  if (isEarlyReview) {
    interval = Math.round(interval * EARLY_REVIEW_MULTIPLIER)
  }

  // Apply consecutive perfect scores bonus
  if (hasConsecutivePerfectScores(scoresHistory)) {
    interval = Math.round(interval * CONSECUTIVE_PERFECT_BONUS)
  }

  // Cap at max interval
  interval = Math.min(interval, MAX_INTERVAL_DAYS)

  // Ensure minimum of 1 day
  interval = Math.max(1, interval)

  // Update ease factor using SM-2 formula
  let newEaseFactor = previousEaseFactor + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02))

  // Ensure ease factor stays within bounds (1.3 - 2.5)
  newEaseFactor = Math.max(MIN_EASE_FACTOR, Math.min(MAX_EASE_FACTOR, newEaseFactor))

  const masteryLevel = determineMasteryLevel(interval, reviewCount + 1, quality)
  const confidence = calculateConfidence(interval, quality, reviewCount + 1, scoresHistory)

  return {
    nextInterval: interval,
    newEaseFactor,
    masteryLevel,
    confidence,
    quality,
  }
}

/**
 * Calculate initial values for a new problem
 */
export function getInitialSM2State(difficulty: Difficulty): {
  easeFactor: number
  interval: number
  masteryLevel: MasteryLevel
} {
  return {
    easeFactor: DEFAULT_EASE_FACTOR,
    interval: 0,
    masteryLevel: "new",
  }
}

/**
 * Estimate retention probability based on days since last review
 * Uses Ebbinghaus forgetting curve
 */
export function estimateRetention(
  daysSinceReview: number,
  interval: number,
  reviewCount: number
): number {
  if (daysSinceReview <= 0) return 100

  // Base retention curve (exponential decay)
  // Higher review counts and longer intervals mean slower decay
  const stability = Math.log(interval + 1) * (1 + reviewCount * 0.1)
  const retention = 100 * Math.exp(-daysSinceReview / (stability * 2))

  return Math.max(0, Math.min(100, Math.round(retention)))
}

/**
 * Calculate priority score for review scheduling
 * Higher priority = should be reviewed sooner
 */
export function calculateReviewPriority(
  daysOverdue: number,
  difficulty: Difficulty,
  lastScore: number,
  masteryLevel: MasteryLevel
): number {
  let priority = 50 // Base priority

  // Overdue boost (up to +40)
  if (daysOverdue > 0) {
    priority += Math.min(40, daysOverdue * 10)
  }

  // Difficulty boost
  const difficultyBoost = { easy: 0, medium: 5, hard: 10 }
  priority += difficultyBoost[difficulty]

  // Low last score boost (up to +20)
  if (lastScore < 70) {
    priority += (70 - lastScore) / 3
  }

  // Mastery level adjustments
  const masteryAdjust = { new: 10, learning: 5, reviewing: 0, mastered: -10 }
  priority += masteryAdjust[masteryLevel]

  return Math.min(100, Math.max(0, Math.round(priority)))
}

/**
 * Zustand Store for Company-Specific DSA Roadmap
 */

import { create } from "zustand"
import { persist } from "zustand/middleware"
import {
  PersonalizedRoadmap,
  UserRoadmapAssessment,
  CompanyId,
  DailyPlan,
} from "@/lib/data/company-questions/types"
import { DSAPattern } from "@/lib/types/dsa-patterns"
import { getCurrentUserToken } from "@/lib/firebase-lazy"

interface RoadmapState {
  // Current roadmap
  activeRoadmap: PersonalizedRoadmap | null

  // Wizard state
  wizardStep: "company" | "date" | "assessment" | "generating" | "complete"
  selectedCompany: CompanyId | null
  selectedDate: Date | null
  assessmentAnswers: {
    experienceLevel: "beginner" | "intermediate" | "advanced" | null
    problemsSolved: number
    hoursPerDay: number
    patternFamiliarity: {
      pattern: DSAPattern
      level: "unknown" | "seen" | "practiced" | "confident"
    }[]
  }

  // UI state
  isLoading: boolean
  error: string | null
  showCompletionModal: boolean
  selectedDayIndex: number

  // Actions - Wizard
  setWizardStep: (step: RoadmapState["wizardStep"]) => void
  selectCompany: (company: CompanyId) => void
  selectDate: (date: Date) => void
  setExperienceLevel: (level: "beginner" | "intermediate" | "advanced") => void
  setProblemsSolved: (count: number) => void
  setHoursPerDay: (hours: number) => void
  setPatternFamiliarity: (
    pattern: DSAPattern,
    level: "unknown" | "seen" | "practiced" | "confident"
  ) => void
  resetWizard: () => void

  // Actions - Roadmap
  setActiveRoadmap: (roadmap: PersonalizedRoadmap | null) => void
  markQuestionCompleted: (scenarioId: string, score?: number, timeSpentMinutes?: number) => void
  markQuestionSkipped: (scenarioId: string) => void
  markQuestionPending: (scenarioId: string) => void
  markQuestionEvaluating: (scenarioId: string) => void
  selectDay: (index: number) => void
  addActualTime: (minutes: number) => void

  // Actions - UI
  setLoading: (loading: boolean) => void
  setError: (error: string | null) => void
  showCompletion: () => void
  hideCompletion: () => void

  // Computed helpers
  getTodaysPlan: () => DailyPlan | null
  getProgress: () => { completed: number; total: number; percentage: number }
  getDaysRemaining: () => number
  isOnTrack: () => boolean
}

const initialAssessmentAnswers = {
  experienceLevel: null as "beginner" | "intermediate" | "advanced" | null,
  problemsSolved: 0,
  hoursPerDay: 2,
  patternFamiliarity: [] as {
    pattern: DSAPattern
    level: "unknown" | "seen" | "practiced" | "confident"
  }[],
}

export const useRoadmapStore = create<RoadmapState>()(
  persist(
    (set, get) => ({
      // Initial state
      // NOTE: activeRoadmap is NOT persisted to avoid cross-user data leaks
      // It's always loaded fresh from Firebase when the page mounts
      activeRoadmap: null,
      wizardStep: "company",
      selectedCompany: null,
      selectedDate: null,
      assessmentAnswers: { ...initialAssessmentAnswers },
      isLoading: false,
      error: null,
      showCompletionModal: false,
      selectedDayIndex: 0,

      // Wizard actions
      setWizardStep: (step) => set({ wizardStep: step }),

      selectCompany: (company) =>
        set({
          selectedCompany: company,
          wizardStep: "date",
        }),

      selectDate: (date) =>
        set({
          selectedDate: date,
          wizardStep: "assessment",
        }),

      setExperienceLevel: (level) =>
        set((state) => ({
          assessmentAnswers: {
            ...state.assessmentAnswers,
            experienceLevel: level,
          },
        })),

      setProblemsSolved: (count) =>
        set((state) => ({
          assessmentAnswers: {
            ...state.assessmentAnswers,
            problemsSolved: count,
          },
        })),

      setHoursPerDay: (hours) =>
        set((state) => ({
          assessmentAnswers: {
            ...state.assessmentAnswers,
            hoursPerDay: hours,
          },
        })),

      setPatternFamiliarity: (pattern, level) =>
        set((state) => {
          const existing = state.assessmentAnswers.patternFamiliarity.filter(
            (p) => p.pattern !== pattern
          )
          return {
            assessmentAnswers: {
              ...state.assessmentAnswers,
              patternFamiliarity: [...existing, { pattern, level }],
            },
          }
        }),

      resetWizard: () =>
        set({
          wizardStep: "company",
          selectedCompany: null,
          selectedDate: null,
          assessmentAnswers: { ...initialAssessmentAnswers },
          error: null,
        }),

      // Roadmap actions
      // NOTE: We don't reset selectedDayIndex here - the page component
      // calls selectDay() immediately after loading to set the correct day.
      // This prevents a flash of the wrong day on initial navigation.
      setActiveRoadmap: (roadmap) =>
        set((state) => ({
          activeRoadmap: roadmap,
          wizardStep: roadmap ? "complete" : "company",
          // Keep current selectedDayIndex - the page will set it correctly
          selectedDayIndex: state.selectedDayIndex,
        })),

      markQuestionCompleted: (scenarioId, score, timeSpentMinutes) => {
        const state = get()
        if (!state.activeRoadmap) return

        const updatedPlans = state.activeRoadmap.dailyPlans.map((plan) => ({
          ...plan,
          questions: plan.questions.map((q) =>
            q.scenarioId === scenarioId
              ? { ...q, status: "completed" as const, completedAt: new Date(), score }
              : q
          ),
        }))

        const allQuestions = updatedPlans.flatMap((p) => p.questions)
        const completedCount = allQuestions.filter((q) => q.status === "completed").length

        // Update pattern coverage - count per pattern
        const patternCoverage = state.activeRoadmap.patternCoverage.map((pc) => {
          const patternQuestions = allQuestions.filter((q) => q.pattern === pc.pattern)
          const patternCompleted = patternQuestions.filter((q) => q.status === "completed").length
          const total = patternQuestions.length || pc.total
          return {
            ...pc,
            total,
            completed: patternCompleted,
            percentage: total > 0 ? Math.round((patternCompleted / total) * 100) : 0,
          }
        })

        // Update actualHoursSpent if timeSpentMinutes is provided
        let actualHoursSpent = state.activeRoadmap.actualHoursSpent
        if (timeSpentMinutes) {
          actualHoursSpent += timeSpentMinutes / 60
        }

        const updatedRoadmap = {
          ...state.activeRoadmap,
          dailyPlans: updatedPlans,
          questionsCompleted: completedCount,
          patternCoverage,
          actualHoursSpent,
          updatedAt: new Date(),
        }

        // Update local state immediately (optimistic update)
        set({ activeRoadmap: updatedRoadmap })

        // Sync to Firebase with retry logic
        const roadmapId = state.activeRoadmap.id
        if (roadmapId) {
          const syncToFirebase = async (retries = 3): Promise<boolean> => {
            for (let attempt = 1; attempt <= retries; attempt++) {
              try {
                const token = await getCurrentUserToken()
                if (!token) {
                  console.error("Failed to sync progress: No auth token")
                  return false
                }
                const response = await fetch("/api/roadmap/progress", {
                  method: "PATCH",
                  headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                  },
                  body: JSON.stringify({
                    roadmapId,
                    scenarioId,
                    status: "completed",
                    score,
                    timeSpentMinutes,
                  }),
                })

                if (response.ok) {
                  return true
                }

                // Log error but don't throw on last attempt
                const errorData = await response.json().catch(() => ({}))
                console.error(`Roadmap sync attempt ${attempt} failed:`, errorData)

                if (attempt < retries) {
                  // Exponential backoff: 1s, 2s, 4s
                  await new Promise((resolve) =>
                    setTimeout(resolve, 1000 * Math.pow(2, attempt - 1))
                  )
                }
              } catch (error) {
                console.error(`Roadmap sync attempt ${attempt} error:`, error)
                if (attempt < retries) {
                  await new Promise((resolve) =>
                    setTimeout(resolve, 1000 * Math.pow(2, attempt - 1))
                  )
                }
              }
            }
            return false
          }

          // Run sync in background - the toast is shown by the interview page
          syncToFirebase().then((success) => {
            if (!success) {
              // Revert local state if all retries failed
              // This ensures UI stays in sync with Firebase
              console.error("All roadmap sync retries failed for scenario:", scenarioId)
              // Note: We don't revert because the session IS completed in Firebase
              // The roadmap will sync correctly on next page load
            }
          })
        }
      },

      markQuestionSkipped: (scenarioId) => {
        const state = get()
        if (!state.activeRoadmap) return

        const updatedPlans = state.activeRoadmap.dailyPlans.map((plan) => ({
          ...plan,
          questions: plan.questions.map((q) =>
            q.scenarioId === scenarioId ? { ...q, status: "skipped" as const } : q
          ),
        }))

        const skippedCount = updatedPlans
          .flatMap((p) => p.questions)
          .filter((q) => q.status === "skipped").length

        const updatedRoadmap = {
          ...state.activeRoadmap,
          dailyPlans: updatedPlans,
          questionsSkipped: skippedCount,
          updatedAt: new Date(),
        }

        // Update local state immediately (optimistic update)
        set({ activeRoadmap: updatedRoadmap })

        // Sync to Firebase with retry logic
        const roadmapId = state.activeRoadmap.id
        if (roadmapId) {
          const syncToFirebase = async (retries = 2): Promise<void> => {
            for (let attempt = 1; attempt <= retries; attempt++) {
              try {
                const token = await getCurrentUserToken()
                if (!token) {
                  console.error("Failed to sync skipped status: No auth token")
                  return
                }
                const response = await fetch("/api/roadmap/progress", {
                  method: "PATCH",
                  headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                  },
                  body: JSON.stringify({
                    roadmapId,
                    scenarioId,
                    status: "skipped",
                  }),
                })

                if (response.ok) return

                if (attempt < retries) {
                  await new Promise((resolve) => setTimeout(resolve, 1000 * attempt))
                }
              } catch (error) {
                console.error(`Skipped sync attempt ${attempt} error:`, error)
                if (attempt < retries) {
                  await new Promise((resolve) => setTimeout(resolve, 1000 * attempt))
                }
              }
            }
          }
          syncToFirebase()
        }
      },

      markQuestionPending: (scenarioId) =>
        set((state) => {
          if (!state.activeRoadmap) return state

          const updatedPlans = state.activeRoadmap.dailyPlans.map((plan) => ({
            ...plan,
            questions: plan.questions.map((q) =>
              q.scenarioId === scenarioId
                ? { ...q, status: "pending" as const, completedAt: undefined, score: undefined }
                : q
            ),
          }))

          return {
            activeRoadmap: {
              ...state.activeRoadmap,
              dailyPlans: updatedPlans,
              updatedAt: new Date(),
            },
          }
        }),

      markQuestionEvaluating: (scenarioId) => {
        const state = get()
        if (!state.activeRoadmap) return

        const updatedPlans = state.activeRoadmap.dailyPlans.map((plan) => ({
          ...plan,
          questions: plan.questions.map((q) =>
            q.scenarioId === scenarioId ? { ...q, status: "evaluating" as const } : q
          ),
        }))

        const updatedRoadmap = {
          ...state.activeRoadmap,
          dailyPlans: updatedPlans,
          updatedAt: new Date(),
        }

        // Update local state immediately (optimistic update)
        set({ activeRoadmap: updatedRoadmap })

        // Sync to Firebase with retry logic
        const roadmapId = state.activeRoadmap.id
        if (roadmapId) {
          const syncToFirebase = async (retries = 2): Promise<void> => {
            for (let attempt = 1; attempt <= retries; attempt++) {
              try {
                const token = await getCurrentUserToken()
                if (!token) {
                  console.error("Failed to sync evaluating status: No auth token")
                  return
                }
                const response = await fetch("/api/roadmap/progress", {
                  method: "PATCH",
                  headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                  },
                  body: JSON.stringify({
                    roadmapId,
                    scenarioId,
                    status: "evaluating",
                  }),
                })

                if (response.ok) return

                if (attempt < retries) {
                  await new Promise((resolve) => setTimeout(resolve, 1000 * attempt))
                }
              } catch (error) {
                console.error(`Evaluating sync attempt ${attempt} error:`, error)
                if (attempt < retries) {
                  await new Promise((resolve) => setTimeout(resolve, 1000 * attempt))
                }
              }
            }
          }
          syncToFirebase()
        }
      },

      selectDay: (index) => set({ selectedDayIndex: index }),

      addActualTime: (minutes) => {
        const state = get()
        if (!state.activeRoadmap) return

        const updatedRoadmap = {
          ...state.activeRoadmap,
          actualHoursSpent: state.activeRoadmap.actualHoursSpent + minutes / 60,
          updatedAt: new Date(),
        }

        // Update local state immediately
        set({ activeRoadmap: updatedRoadmap })

        // Sync to Firebase in the background
        // Note: We'll update the actualHoursSpent on the next progress update
        // For now, we just update locally. If needed, we can add a separate endpoint.
      },

      // UI actions
      setLoading: (loading) => set({ isLoading: loading }),
      setError: (error) => set({ error }),
      showCompletion: () => set({ showCompletionModal: true }),
      hideCompletion: () => set({ showCompletionModal: false }),

      // Computed helpers
      getTodaysPlan: () => {
        const roadmap = get().activeRoadmap
        if (!roadmap) return null

        const today = new Date()
        today.setHours(0, 0, 0, 0)

        return (
          roadmap.dailyPlans.find((plan) => {
            const planDate = new Date(plan.date)
            planDate.setHours(0, 0, 0, 0)
            return planDate.getTime() === today.getTime()
          }) || null
        )
      },

      getProgress: () => {
        const roadmap = get().activeRoadmap
        if (!roadmap) return { completed: 0, total: 0, percentage: 0 }

        return {
          completed: roadmap.questionsCompleted,
          total: roadmap.totalQuestions,
          percentage: Math.round((roadmap.questionsCompleted / roadmap.totalQuestions) * 100),
        }
      },

      getDaysRemaining: () => {
        const roadmap = get().activeRoadmap
        if (!roadmap) return 0

        const now = new Date()
        const interview = new Date(roadmap.interviewDate)
        return Math.max(0, Math.ceil((interview.getTime() - now.getTime()) / (1000 * 60 * 60 * 24)))
      },

      isOnTrack: () => {
        const roadmap = get().activeRoadmap
        return roadmap?.isOnTrack ?? true
      },
    }),
    {
      name: "roadmap-storage",
      // IMPORTANT: Do NOT persist activeRoadmap - it must be loaded fresh from Firebase
      // to prevent cross-user data leaks when multiple users use the same browser
      partialize: (state) => ({
        // Only persist wizard state, NOT the roadmap itself
        selectedCompany: state.selectedCompany,
        selectedDate: state.selectedDate,
        // wizardStep and assessmentAnswers are not persisted to ensure clean state
      }),
    }
  )
)

