/**
 * Validator runner - executes validation against user output
 */

import {
  ValidatorConfig,
  ValidatorContext,
  ValidatedTestCase,
  Normalizers,
  PropertyBuilders,
  OutputNormalization,
} from "./types"

export interface ValidationResult {
  passed: boolean
  reason?: string
  details?: {
    propertyName?: string
    propertyDescription?: string
    expected?: any
    actual?: any
    normalizedExpected?: any
    normalizedActual?: any
  }
}

/**
 * Apply normalization steps to a value
 */
function applyNormalization(value: any, steps: OutputNormalization[]): any {
  let result = Normalizers.parseOutput(value)

  for (const step of steps) {
    switch (step) {
      case "sort-array":
        result = Normalizers.sortArray(result)
        break
      case "sort-nested":
        result = Normalizers.sortNested(result)
        break
      case "set":
        result = Array.from(Normalizers.toSet(result))
        break
      case "multiset":
        result = Normalizers.sortArray(result)
        break
      case "normalize-whitespace":
        result = Normalizers.normalizeWhitespace(result)
        break
      case "none":
      default:
        break
    }
  }

  return result
}

/**
 * Deep equality check with numeric tolerance
 */
function deepEquals(a: any, b: any, tolerance = 0.0001): boolean {
  // Handle null/undefined
  if (a === null || a === undefined) return b === null || b === undefined
  if (b === null || b === undefined) return false

  // Handle numbers with tolerance
  if (typeof a === "number" && typeof b === "number") {
    if (Number.isNaN(a) && Number.isNaN(b)) return true
    const diff = Math.abs(a - b)
    const relativeTolerance = Math.max(tolerance, Math.abs(a) * tolerance)
    return diff < relativeTolerance
  }

  // Handle booleans
  if (typeof a === "boolean" && typeof b === "boolean") {
    return a === b
  }

  // Handle strings
  if (typeof a === "string" && typeof b === "string") {
    return a === b
  }

  // Handle arrays
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false
    return a.every((val, idx) => deepEquals(val, b[idx], tolerance))
  }

  // Handle objects
  if (typeof a === "object" && typeof b === "object") {
    const keysA = Object.keys(a).sort()
    const keysB = Object.keys(b).sort()
    if (keysA.length !== keysB.length) return false
    if (keysA.join(",") !== keysB.join(",")) return false
    return keysA.every((key) => deepEquals(a[key], b[key], tolerance))
  }

  // Fallback to strict equality
  return a === b
}

/**
 * Main validation function
 */
export async function validateOutput(
  testCase: ValidatedTestCase,
  actualOutput: any,
  context: Omit<ValidatorContext, "input" | "output" | "expected">
): Promise<ValidationResult> {
  const config = testCase.validation
  const parsedOutput = Normalizers.parseOutput(actualOutput)

  const ctx: ValidatorContext = {
    input: testCase.input,
    output: parsedOutput,
    expected: config.expected ?? testCase.expected,
    ...context,
  }

  // Apply custom validator first if provided
  if (config.customValidator) {
    try {
      const result = await config.customValidator(ctx)
      return {
        passed: result,
        reason: result ? undefined : "Custom validator returned false",
      }
    } catch (error) {
      return {
        passed: false,
        reason: `Custom validator error: ${error instanceof Error ? error.message : "Unknown error"}`,
      }
    }
  }

  switch (config.mode) {
    case "property":
      return validateProperties(ctx, config)

    case "reference":
      // Reference validation would require executing reference solution
      // For now, fall through to exact mode
      return validateExact(ctx, config)

    case "any-valid":
      return validateAnyValid(ctx, config)

    case "exact":
    default:
      return validateExact(ctx, config)
  }
}

/**
 * Property-based validation
 */
function validateProperties(ctx: ValidatorContext, config: ValidatorConfig): ValidationResult {
  const properties = config.properties || []

  if (properties.length === 0) {
    return {
      passed: false,
      reason: "No properties defined for property-based validation",
    }
  }

  for (const prop of properties) {
    try {
      const result = prop.check(ctx)
      // Handle both sync and async (though we expect sync for now)
      const passed = result instanceof Promise ? false : result

      if (!passed) {
        return {
          passed: false,
          reason: `Property "${prop.name}" failed: ${prop.description}`,
          details: {
            propertyName: prop.name,
            propertyDescription: prop.description,
            actual: ctx.output,
          },
        }
      }
    } catch (error) {
      return {
        passed: false,
        reason: `Property "${prop.name}" threw error: ${error instanceof Error ? error.message : "Unknown"}`,
        details: {
          propertyName: prop.name,
          propertyDescription: prop.description,
        },
      }
    }
  }

  return { passed: true }
}

/**
 * Exact value validation with normalization
 */
function validateExact(ctx: ValidatorContext, config: ValidatorConfig): ValidationResult {
  const expected = config.expected ?? ctx.expected
  const normalizeSteps = config.normalize || []

  const normalizedActual = applyNormalization(ctx.output, normalizeSteps)
  const normalizedExpected = applyNormalization(expected, normalizeSteps)

  const tolerance = config.tolerance ?? 0.0001
  const passed = deepEquals(normalizedActual, normalizedExpected, tolerance)

  return {
    passed,
    reason: passed ? undefined : "Output does not match expected value",
    details: {
      expected,
      actual: ctx.output,
      normalizedExpected,
      normalizedActual,
    },
  }
}

/**
 * Any valid output validation - checks against multiple valid outputs
 */
function validateAnyValid(ctx: ValidatorContext, config: ValidatorConfig): ValidationResult {
  const validOutputs = config.multipleValidOutputs || []

  if (validOutputs.length === 0) {
    // Fall back to expected if no multiple outputs defined
    if (config.expected !== undefined) {
      return validateExact(ctx, { ...config, mode: "exact" })
    }
    return {
      passed: false,
      reason: "No valid outputs defined for any-valid mode",
    }
  }

  const normalizeSteps = config.normalize || []
  const normalizedActual = applyNormalization(ctx.output, normalizeSteps)
  const tolerance = config.tolerance ?? 0.0001

  for (const validOutput of validOutputs) {
    const normalizedValid = applyNormalization(validOutput, normalizeSteps)
    if (deepEquals(normalizedActual, normalizedValid, tolerance)) {
      return { passed: true }
    }
  }

  return {
    passed: false,
    reason: "Output does not match any valid output",
    details: {
      actual: ctx.output,
      normalizedActual,
    },
  }
}

/**
 * Legacy compatibility: Convert old test case format to new format
 */
export function convertLegacyTestCase(
  testCase: {
    input: any
    expected: any
    description: string
    compareAsSet?: boolean
    orderMatters?: boolean
    caseSensitive?: boolean
  },
  scenarioId: string
): ValidatedTestCase {
  const normalize: OutputNormalization[] = []

  if (testCase.compareAsSet || testCase.orderMatters === false) {
    normalize.push("sort-nested")
  }

  // Auto-detect problem type from scenarioId for property-based validation
  const propertyValidators = detectPropertyValidators(scenarioId, testCase)

  if (propertyValidators.length > 0) {
    return {
      input: testCase.input,
      description: testCase.description,
      validation: {
        mode: "property",
        properties: propertyValidators,
        expected: testCase.expected, // Keep for debugging
      },
      expected: testCase.expected, // Backwards compat
    }
  }

  return {
    input: testCase.input,
    description: testCase.description,
    validation: {
      mode: "exact",
      expected: testCase.expected,
      normalize,
    },
    expected: testCase.expected,
  }
}

/**
 * Auto-detect appropriate property validators based on scenario ID and input shape
 */
function detectPropertyValidators(
  scenarioId: string,
  testCase: { input: any; expected: any }
): Array<ReturnType<(typeof PropertyBuilders)[keyof typeof PropertyBuilders]>> {
  const validators: Array<ReturnType<(typeof PropertyBuilders)[keyof typeof PropertyBuilders]>> = []
  const { input, expected } = testCase

  // Two-sum pattern detection
  if (
    scenarioId.includes("two-sum") ||
    (input.nums && input.target !== undefined && Array.isArray(expected) && expected.length === 2)
  ) {
    validators.push(PropertyBuilders.twoSumValid("nums", "target"))
    return validators
  }

  // Group anagrams pattern
  if (
    scenarioId.includes("anagram") &&
    input.strs &&
    Array.isArray(expected) &&
    Array.isArray(expected[0])
  ) {
    validators.push(PropertyBuilders.validAnagramGroups())
    return validators
  }

  // Palindrome check
  if (scenarioId.includes("palindrome") && typeof expected === "boolean") {
    validators.push(PropertyBuilders.isPalindrome())
    return validators
  }

  // Cycle detection
  if (scenarioId.includes("cycle") && typeof expected === "boolean") {
    validators.push(PropertyBuilders.hasCycle())
    return validators
  }

  return validators
}

/**
 * Enhanced result validation that uses the new system
 */
export function validateResultEnhanced(
  actual: any,
  testCase: {
    input: any
    expected: any
    description: string
    compareAsSet?: boolean
    orderMatters?: boolean
  },
  scenarioId: string,
  language: string
): ValidationResult {
  const validatedTestCase = convertLegacyTestCase(testCase, scenarioId)

  // Use sync version for backwards compatibility
  const ctx: ValidatorContext = {
    input: testCase.input,
    output: Normalizers.parseOutput(actual),
    expected: testCase.expected,
    language,
    scenarioId,
  }

  const config = validatedTestCase.validation

  if (config.mode === "property" && config.properties) {
    return validateProperties(ctx, config)
  }

  return validateExact(ctx, config)
}

/**
 * Property-based validation system for coding challenges
 *
 * Instead of hardcoded expected values, we define:
 * 1. Properties that a correct answer must satisfy
 * 2. Optional reference solutions that generate expected outputs
 * 3. Flexible output parsing/normalization
 */

/**
 * Reference solution for dynamic validation
 * Imported from ast-validator.ts - re-exported here for convenience
 */
export interface ReferenceSolution {
  code: {
    python: string
    javascript: string
    typescript?: string
  }
  functionName: string
  inputSpec?: {
    params: Array<{
      name: string
      type: 'int' | 'float' | 'string' | 'boolean' | 'array' | 'matrix' | 'object'
      minLength?: number
      maxLength?: number
      min?: number
      max?: number
      elementType?: 'int' | 'float' | 'string' | 'boolean'
      elementMin?: number
      elementMax?: number
    }>
    constraints?: Array<{
      type: 'sum-exists' | 'sorted' | 'unique' | 'custom'
      params?: string[]
    }>
  }
  outputComparison?: 'exact' | 'set' | 'any-valid' | 'property-based'
}

export type ValidationMode =
  | 'exact'           // Must match exactly (default for simple cases)
  | 'property'        // Must satisfy defined properties
  | 'reference'       // Compare against reference solution output
  | 'any-valid'       // Any output satisfying constraints is valid

export type OutputNormalization =
  | 'none'            // No normalization
  | 'sort-array'      // Sort arrays before comparison
  | 'sort-nested'     // Sort arrays and nested arrays
  | 'set'             // Treat as set (order doesn't matter, no duplicates)
  | 'multiset'        // Order doesn't matter, duplicates allowed
  | 'normalize-whitespace'  // Trim and normalize whitespace

export interface ValidatorContext {
  input: Record<string, any>
  output: any
  expected?: any  // Optional - not needed for property-based
  language: string
  scenarioId: string
}

/**
 * A validator function returns true if the output is correct
 * It receives the full context to make intelligent decisions
 */
export type ValidatorFn = (ctx: ValidatorContext) => boolean | Promise<boolean>

/**
 * Property definition - a named check that must pass
 */
export interface Property {
  name: string
  description: string
  check: ValidatorFn
}

/**
 * Validator configuration for a test case
 */
export interface ValidatorConfig {
  mode: ValidationMode

  // For 'exact' mode - traditional expected value
  expected?: any

  // For 'property' mode - list of properties that must hold
  properties?: Property[]

  // For 'reference' mode - reference solution code
  referenceSolution?: {
    [language: string]: string
  }

  // Output normalization before comparison
  normalize?: OutputNormalization[]

  // Numeric tolerance for floating point comparisons
  tolerance?: number

  // Allow multiple valid outputs
  multipleValidOutputs?: any[]

  // Custom validator function (escape hatch for complex cases)
  customValidator?: ValidatorFn
}

/**
 * Enhanced test case with validator support
 */
export interface ValidatedTestCase {
  input: Record<string, any>
  description: string

  // NEW: Validation config instead of just 'expected'
  validation: ValidatorConfig

  // DEPRECATED: Keep for backwards compatibility, but prefer validation.expected
  expected?: any

  // Hints for debugging when test fails
  debugHints?: string[]
}

/**
 * Common property builders for DSA problems
 */
export const PropertyBuilders = {
  /**
   * Two-sum style: output indices point to values that sum to target
   */
  twoSumValid: (numsKey = 'nums', targetKey = 'target'): Property => ({
    name: 'valid-two-sum',
    description: 'Output indices point to values that sum to target',
    check: (ctx) => {
      const { input, output } = ctx
      const nums = input[numsKey]
      const target = input[targetKey]

      if (!Array.isArray(output) || output.length !== 2) return false
      const [i, j] = output

      // Indices must be valid, different, and values must sum to target
      return (
        Number.isInteger(i) && Number.isInteger(j) &&
        i >= 0 && i < nums.length &&
        j >= 0 && j < nums.length &&
        i !== j &&
        nums[i] + nums[j] === target
      )
    }
  }),

  /**
   * Array contains exactly the expected elements (order doesn't matter)
   */
  arrayAsSet: (expectedKey: string): Property => ({
    name: 'array-as-set',
    description: 'Output contains exactly the expected elements (any order)',
    check: (ctx) => {
      const { output, expected } = ctx
      if (!Array.isArray(output) || !Array.isArray(expected)) return false
      if (output.length !== expected.length) return false

      const sortedOutput = [...output].sort()
      const sortedExpected = [...expected].sort()
      return JSON.stringify(sortedOutput) === JSON.stringify(sortedExpected)
    }
  }),

  /**
   * Linked list cycle detection: output is boolean or node reference
   */
  hasCycle: (): Property => ({
    name: 'cycle-detection',
    description: 'Correctly identifies if cycle exists',
    check: (ctx) => {
      const { output, expected } = ctx
      // Accept boolean or truthy/falsy
      return Boolean(output) === Boolean(expected)
    }
  }),

  /**
   * Valid BST traversal
   */
  validBSTTraversal: (order: 'inorder' | 'preorder' | 'postorder'): Property => ({
    name: `valid-${order}-traversal`,
    description: `Output is valid ${order} BST traversal`,
    check: (ctx) => {
      const { output, expected } = ctx
      if (!Array.isArray(output)) return false
      // For traversals, exact match is usually required
      return JSON.stringify(output) === JSON.stringify(expected)
    }
  }),

  /**
   * Valid palindrome check
   */
  isPalindrome: (): Property => ({
    name: 'palindrome-check',
    description: 'Correctly identifies palindrome',
    check: (ctx) => {
      const { input, output } = ctx
      const str = (input.s || input.str || '').toLowerCase().replace(/[^a-z0-9]/g, '')
      const isPalin = str === str.split('').reverse().join('')
      return output === isPalin
    }
  }),

  /**
   * Valid anagram grouping (order of groups and within groups doesn't matter)
   */
  validAnagramGroups: (): Property => ({
    name: 'valid-anagram-groups',
    description: 'Groups are valid anagram sets',
    check: (ctx) => {
      const { input, output } = ctx
      if (!Array.isArray(output)) return false

      const strs = input.strs || input.words || []

      // Each string should appear exactly once across all groups
      const outputFlat = output.flat()
      if (outputFlat.length !== strs.length) return false

      // Check each group contains only anagrams
      for (const group of output) {
        if (!Array.isArray(group)) return false
        const sorted = group.map((s: string) => s.split('').sort().join(''))
        if (new Set(sorted).size !== 1) return false
      }

      // Check all strings are accounted for
      const inputSet = new Set(strs)
      const outputSet = new Set(outputFlat)
      if (inputSet.size !== outputSet.size) return false
      for (const s of inputSet) {
        if (!outputSet.has(s)) return false
      }

      return true
    }
  }),

  /**
   * Output length matches expected
   */
  lengthMatches: (expectedLength: number): Property => ({
    name: 'length-matches',
    description: `Output length is ${expectedLength}`,
    check: (ctx) => {
      const { output } = ctx
      if (Array.isArray(output)) return output.length === expectedLength
      if (typeof output === 'string') return output.length === expectedLength
      return false
    }
  }),

  /**
   * Output is within numeric range
   */
  inRange: (min: number, max: number): Property => ({
    name: 'in-range',
    description: `Output is between ${min} and ${max}`,
    check: (ctx) => {
      const { output } = ctx
      return typeof output === 'number' && output >= min && output <= max
    }
  }),

  /**
   * Subarray sum equals target
   */
  subarraySumEquals: (targetKey = 'target'): Property => ({
    name: 'subarray-sum',
    description: 'Subarray elements sum to target',
    check: (ctx) => {
      const { input, output } = ctx
      const nums = input.nums || input.arr
      const target = input[targetKey]

      if (!Array.isArray(output) || output.length !== 2) return false
      const [start, end] = output

      let sum = 0
      for (let i = start; i <= end; i++) {
        sum += nums[i]
      }
      return sum === target
    }
  }),
}

/**
 * Output normalizers
 */
export const Normalizers = {
  sortArray: (val: any): any => {
    if (!Array.isArray(val)) return val
    return [...val].sort((a, b) => {
      if (typeof a === 'number' && typeof b === 'number') return a - b
      return String(a).localeCompare(String(b))
    })
  },

  sortNested: (val: any): any => {
    if (!Array.isArray(val)) return val
    return Normalizers.sortArray(val.map(Normalizers.sortNested))
  },

  toSet: (val: any): Set<any> => {
    if (!Array.isArray(val)) return new Set([val])
    return new Set(val.map(v => JSON.stringify(v)))
  },

  normalizeWhitespace: (val: any): any => {
    if (typeof val === 'string') {
      return val.trim().replace(/\s+/g, ' ')
    }
    return val
  },

  // Parse various output formats to a standard form
  parseOutput: (raw: any): any => {
    if (raw === null || raw === undefined) return raw

    // Already parsed
    if (typeof raw !== 'string') return raw

    const trimmed = raw.trim()

    // Try JSON parse
    try {
      return JSON.parse(trimmed)
    } catch {}

    // Try Python tuple -> array: (1, 2) -> [1, 2]
    if (trimmed.startsWith('(') && trimmed.endsWith(')')) {
      try {
        return JSON.parse('[' + trimmed.slice(1, -1) + ']')
      } catch {}
    }

    // Try Python set -> array: {1, 2} -> [1, 2]
    if (trimmed.startsWith('{') && trimmed.endsWith('}') && !trimmed.includes(':')) {
      try {
        return JSON.parse('[' + trimmed.slice(1, -1) + ']')
      } catch {}
    }

    // Boolean strings
    if (trimmed.toLowerCase() === 'true') return true
    if (trimmed.toLowerCase() === 'false') return false

    // Number strings
    const num = Number(trimmed)
    if (!isNaN(num) && trimmed !== '') return num

    // Return as-is
    return raw
  }
}

/**
 * useDeepgram Hook
 *
 * React hook for real-time speech-to-text transcription using Deepgram
 * Provides easy integration with interview components
 */

"use client"

import { useState, useCallback, useRef, useEffect } from "react"
import { DeepgramVoiceService, DeepgramConfig } from "./deepgram-service"
import { VOICE } from "@/lib/constants"
import { logger } from "@/lib/logger"

// Web Speech API types (not included in standard TypeScript lib)
interface SpeechRecognitionResult {
  readonly isFinal: boolean
  readonly length: number
  item(index: number): SpeechRecognitionAlternative
  [index: number]: SpeechRecognitionAlternative
}

interface SpeechRecognitionAlternative {
  readonly transcript: string
  readonly confidence: number
}

interface SpeechRecognitionResultList {
  readonly length: number
  item(index: number): SpeechRecognitionResult
  [index: number]: SpeechRecognitionResult
}

interface SpeechRecognitionEvent extends Event {
  readonly resultIndex: number
  readonly results: SpeechRecognitionResultList
}

interface SpeechRecognitionErrorEvent extends Event {
  readonly error: string
  readonly message: string
}

interface SpeechRecognition extends EventTarget {
  continuous: boolean
  interimResults: boolean
  lang: string
  onresult: ((event: SpeechRecognitionEvent) => void) | null
  onerror: ((event: SpeechRecognitionErrorEvent) => void) | null
  onend: (() => void) | null
  start(): void
  stop(): void
  abort(): void
}

export type VoiceStatus = "idle" | "connecting" | "recording" | "error"

export interface UseDeepgramOptions extends DeepgramConfig {
  onTranscript?: (transcript: string, isFinal: boolean) => void
  onError?: (error: Error) => void
  onStatusChange?: (status: VoiceStatus) => void
  onUtteranceEnd?: (transcript: string) => void
  onMaxDuration?: (transcript: string) => void // Called when max recording duration reached
  autoSubmitOnSilence?: boolean
  silenceThresholdMs?: number
  // Auto-send configuration
  autoSendEnabled?: boolean // Enable auto-send on utterance end (default: true)
  autoSendDelayMs?: number // Delay before auto-send for cancel window (default: 500ms)
  // Usage tracking
  sessionId?: string
  authToken?: string // Firebase auth token for tracking API
}

export interface UseDeepgramReturn {
  // State
  isRecording: boolean
  status: VoiceStatus
  transcript: string
  error: Error | null
  countdownActive: boolean // True during pre-send countdown

  // Actions
  startRecording: () => Promise<void>
  stopRecording: () => string
  resetTranscript: () => void
  toggleRecording: () => Promise<void>
  clearSentTracker: () => void
  cancelCountdown: () => void // Cancel pending auto-send

  // Info
  isConfigured: boolean
}

/**
 * Hook for using Deepgram real-time transcription
 */
export function useDeepgram(options: UseDeepgramOptions = {}): UseDeepgramReturn {
  const [isRecording, setIsRecording] = useState(false)
  const [status, setStatus] = useState<VoiceStatus>("idle")
  const [transcript, setTranscript] = useState("")
  const [error, setError] = useState<Error | null>(null)
  const [countdownActive, setCountdownActive] = useState(false)

  const serviceRef = useRef<DeepgramVoiceService | null>(null)
  const silenceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const recordingStartTimeRef = useRef<number | null>(null)
  const countdownTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const pendingTranscriptRef = useRef<string>("")

  // Store latest callbacks in refs to avoid stale closure issues
  const onUtteranceEndRef = useRef(options.onUtteranceEnd)
  const onTranscriptRef = useRef(options.onTranscript)
  const onMaxDurationRef = useRef(options.onMaxDuration)
  onUtteranceEndRef.current = options.onUtteranceEnd
  onTranscriptRef.current = options.onTranscript
  onMaxDurationRef.current = options.onMaxDuration

  // Initialize service on mount
  useEffect(() => {
    const service = new DeepgramVoiceService({
      apiKey: options.apiKey,
      language: options.language,
      model: options.model,
      punctuate: options.punctuate,
      interimResults: options.interimResults,
      smartFormat: options.smartFormat,
      utteranceEndMs: options.utteranceEndMs,
      vadEvents: options.vadEvents,
      endpointing: options.endpointing,
    })

    // Pass auth token so the service can fetch the API key from the server
    if (options.authToken) {
      service.setAuthToken(options.authToken)
    }

    serviceRef.current = service

    // Set up callbacks
    serviceRef.current.setOnTranscript((text, isFinal) => {
      setTranscript(text)
      onTranscriptRef.current?.(text, isFinal)

      // Reset silence timer on new transcript
      if (silenceTimerRef.current) {
        clearTimeout(silenceTimerRef.current)
      }

      // Auto-submit on silence if enabled
      if (options.autoSubmitOnSilence && isFinal) {
        silenceTimerRef.current = setTimeout(() => {
          // Silence detected after final transcript
        }, options.silenceThresholdMs || 2000)
      }
    })

    serviceRef.current.setOnError((err) => {
      setError(err)
      options.onError?.(err)
    })

    serviceRef.current.setOnStatus((newStatus) => {
      const mappedStatus: VoiceStatus =
        newStatus === "connecting"
          ? "connecting"
          : newStatus === "connected"
            ? "recording"
            : newStatus === "error"
              ? "error"
              : "idle"

      setStatus(mappedStatus)
      setIsRecording(newStatus === "connected")
      options.onStatusChange?.(mappedStatus)
    })

    // Set max recording duration from constants (prevents abuse)
    serviceRef.current.setMaxDuration(VOICE.MAX_RECORDING_SECONDS * 1000)

    // Set up max duration callback
    serviceRef.current.setOnMaxDuration((text) => {
      logger.info("[useDeepgram] Max duration reached, auto-stopping")
      setStatus("idle")
      setIsRecording(false)
      onMaxDurationRef.current?.(text)
    })

    // Set up utterance end callback for live mode auto-send
    serviceRef.current.setOnUtteranceEnd((text) => {
      // If auto-send is disabled, just call the callback directly
      if (options.autoSendEnabled === false) {
        onUtteranceEndRef.current?.(text)
        return
      }

      // Start countdown before auto-send
      if (text.trim()) {
        // Cancel any existing countdown
        if (countdownTimerRef.current) {
          clearTimeout(countdownTimerRef.current)
        }

        pendingTranscriptRef.current = text
        setCountdownActive(true)

        const delayMs = options.autoSendDelayMs ?? 500
        countdownTimerRef.current = setTimeout(() => {
          setCountdownActive(false)
          countdownTimerRef.current = null
          onUtteranceEndRef.current?.(pendingTranscriptRef.current)
          pendingTranscriptRef.current = ""
        }, delayMs)
      }
    })

    return () => {
      if (silenceTimerRef.current) {
        clearTimeout(silenceTimerRef.current)
      }
      if (countdownTimerRef.current) {
        clearTimeout(countdownTimerRef.current)
      }
      serviceRef.current?.stopTranscription()
    }
  }, [])

  const startRecording = useCallback(async () => {
    if (!serviceRef.current) {
      throw new Error("Deepgram service not initialized")
    }

    setError(null)
    setStatus("connecting")
    recordingStartTimeRef.current = Date.now()

    try {
      await serviceRef.current.startTranscription()
    } catch (err) {
      recordingStartTimeRef.current = null
      const error = err instanceof Error ? err : new Error(String(err))
      setError(error)
      setStatus("error")
      throw error
    }
  }, [])

  const stopRecording = useCallback((): string => {
    if (!serviceRef.current) {
      return ""
    }

    const finalTranscript = serviceRef.current.stopTranscription()
    setStatus("idle")
    setIsRecording(false)

    // Track voice usage if we have a valid recording session
    if (recordingStartTimeRef.current && options.authToken) {
      const durationSeconds = (Date.now() - recordingStartTimeRef.current) / 1000

      // Only track if recording was at least 1 second
      if (durationSeconds >= 1) {
        fetch("/api/usage/voice", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${options.authToken}`,
          },
          body: JSON.stringify({
            sessionId: options.sessionId,
            durationSeconds,
            model: options.model || "nova-2",
            transcriptLength: finalTranscript.length,
          }),
        }).catch((err) => {
          // Non-critical - log but don't throw
          logger.warn("[Voice Usage] Failed to track usage", { error: err })
        })
      }
    }

    recordingStartTimeRef.current = null
    return finalTranscript
  }, [options.authToken, options.sessionId, options.model])

  const resetTranscript = useCallback(() => {
    serviceRef.current?.resetTranscript()
    setTranscript("")
  }, [])

  const clearSentTracker = useCallback(() => {
    serviceRef.current?.clearSentTracker()
  }, [])

  const cancelCountdown = useCallback(() => {
    if (countdownTimerRef.current) {
      clearTimeout(countdownTimerRef.current)
      countdownTimerRef.current = null
    }
    setCountdownActive(false)
    pendingTranscriptRef.current = ""
  }, [])

  const toggleRecording = useCallback(async () => {
    if (isRecording) {
      stopRecording()
    } else {
      await startRecording()
    }
  }, [isRecording, startRecording, stopRecording])

  const isConfigured = serviceRef.current?.isConfigured() ?? false

  return {
    isRecording,
    status,
    transcript,
    error,
    countdownActive,
    startRecording,
    stopRecording,
    resetTranscript,
    toggleRecording,
    clearSentTracker,
    cancelCountdown,
    isConfigured,
  }
}

/**
 * Fallback to Web Speech API if Deepgram is not available
 */
export function useVoiceInput(
  options: UseDeepgramOptions & { fallbackToWebSpeech?: boolean } = {}
) {
  const deepgram = useDeepgram(options)

  // Check if we should use Web Speech API as fallback
  const useWebSpeech = options.fallbackToWebSpeech && !deepgram.isConfigured

  const [webSpeechRecording, setWebSpeechRecording] = useState(false)
  const [webSpeechTranscript, setWebSpeechTranscript] = useState("")
  const recognitionRef = useRef<SpeechRecognition | null>(null)

  // Cleanup Web Speech recognition on unmount
  useEffect(() => {
    return () => {
      if (recognitionRef.current) {
        try {
          recognitionRef.current.stop()
          recognitionRef.current = null
        } catch {
          // Ignore errors during cleanup
        }
      }
    }
  }, [])

  const startWebSpeechRecording = useCallback(async () => {
    const SpeechRecognition =
      (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition

    if (!SpeechRecognition) {
      throw new Error("Speech recognition not supported in this browser")
    }

    // Request microphone permission
    await navigator.mediaDevices
      .getUserMedia({ audio: true })
      .then((stream) => stream.getTracks().forEach((track) => track.stop()))

    const recognition = new SpeechRecognition()
    recognition.continuous = true
    recognition.interimResults = true
    recognition.lang = options.language || "en-US"

    recognition.onresult = (event: SpeechRecognitionEvent) => {
      let transcript = ""
      for (let i = 0; i < event.results.length; i++) {
        transcript += event.results[i][0].transcript
      }
      setWebSpeechTranscript(transcript)
      options.onTranscript?.(transcript, event.results[event.results.length - 1]?.isFinal ?? false)
    }

    recognition.onerror = (event: SpeechRecognitionErrorEvent) => {
      logger.error("Web Speech API error", { error: event.error })
      options.onError?.(new Error(`Speech recognition error: ${event.error}`))
      setWebSpeechRecording(false)
    }

    recognition.onend = () => {
      setWebSpeechRecording(false)
    }

    recognitionRef.current = recognition
    recognition.start()
    setWebSpeechRecording(true)
  }, [options.language, options.onTranscript, options.onError])

  const stopWebSpeechRecording = useCallback((): string => {
    recognitionRef.current?.stop()
    recognitionRef.current = null
    setWebSpeechRecording(false)
    return webSpeechTranscript
  }, [webSpeechTranscript])

  // Return appropriate interface based on which service is used
  if (useWebSpeech) {
    return {
      isRecording: webSpeechRecording,
      status: webSpeechRecording ? ("recording" as VoiceStatus) : ("idle" as VoiceStatus),
      transcript: webSpeechTranscript,
      error: null,
      countdownActive: false, // Web Speech doesn't support countdown
      startRecording: startWebSpeechRecording,
      stopRecording: stopWebSpeechRecording,
      resetTranscript: () => setWebSpeechTranscript(""),
      toggleRecording: async () => {
        if (webSpeechRecording) {
          stopWebSpeechRecording()
        } else {
          await startWebSpeechRecording()
        }
      },
      clearSentTracker: () => {}, // No-op for Web Speech API
      cancelCountdown: () => {}, // No-op for Web Speech API
      isConfigured: true,
      provider: "web-speech" as const,
    }
  }

  return {
    ...deepgram,
    provider: "deepgram" as const,
  }
}

import type { DsaExecutionResult, DsaTestResult } from "../types"
import { validateResultEnhanced } from "@/lib/validators"
import { stripComments } from "./comments"
import { transpileIfNeeded } from "./transpiler"
import { buildJsWrapper } from "./dsa-wrapper"
import { runInWorker } from "./worker-runner"

export async function executeJsClientSide(
  code: string,
  language: string,
  testCases: any[],
  scenarioId: string
): Promise<DsaExecutionResult> {
  const results: DsaTestResult[] = []
  let allPassed = true
  let allConsoleLogs: any[] = []

  try {
    const jsCode = await transpileIfNeeded(code, language)
    const cleanCode = stripComments(jsCode, "javascript")

    for (let i = 0; i < testCases.length; i++) {
      const testCase = testCases[i]
      const wrappedCode = buildJsWrapper(jsCode, testCase, cleanCode, scenarioId)

      const runResult = await runInWorker({ code: wrappedCode })

      if (runResult.logs && runResult.logs.length > 0) {
        allConsoleLogs = [...allConsoleLogs, ...runResult.logs]
      }

      if (!runResult.success || runResult.error) {
        allPassed = false
        results.push({
          description: testCase.description || `Test case ${i + 1}`,
          input: testCase.input,
          expected: testCase.expected,
          actual: null,
          passed: false,
          error: runResult.error || "Execution failed",
        })
        continue
      }

      const parsedActual = runResult.result
      const validation = validateResultEnhanced(parsedActual, testCase, scenarioId, "javascript")

      if (!validation.passed) {
        allPassed = false
      }

      results.push({
        description: testCase.description || `Test case ${i + 1}`,
        input: testCase.input,
        expected: testCase.expected,
        actual: parsedActual,
        passed: validation.passed,
        error: validation.reason || null,
      })
    }

    const passedCount = results.filter((r) => r.passed).length
    const totalCount = results.length
    const passRate = totalCount > 0 ? Math.round((passedCount / totalCount) * 100) : 0

    return {
      success: allPassed,
      results,
      consoleLogs: allConsoleLogs,
      summary: {
        total: totalCount,
        passed: passedCount,
        failed: totalCount - passedCount,
        passRate,
        serviceErrors: 0,
        effectiveTotal: totalCount,
      },
      error: null,
    }
  } catch (err) {
    return {
      success: false,
      results: [],
      consoleLogs: [],
      summary: { total: 0, passed: 0, failed: 0, passRate: 0, serviceErrors: 0, effectiveTotal: 0 },
      error: err instanceof Error ? err.message : "Failed to execute JavaScript client-side",
    }
  }
}

function isValidIdentifier(name: string): boolean {
  return /^[a-zA-Z_$][a-zA-Z0-9_$]*$/.test(name)
}

function getFunctionCandidates(cleanCode: string): string[] {
  const candidates: string[] = []

  // 1. Classic function declarations: function name(...)
  const funcDeclMatches = cleanCode.matchAll(/function\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\(/g)
  for (const match of funcDeclMatches) {
    candidates.push(match[1])
  }

  // 2. Arrow functions: const name = (...) =>
  const arrowFuncMatches = cleanCode.matchAll(
    /(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=\s*(?:\([^)]*\)|[a-zA-Z_$][a-zA-Z0-9_$]*)\s*=>/g
  )
  for (const match of arrowFuncMatches) {
    candidates.push(match[1])
  }

  // 3. Function expressions: const name = function(...)
  const funcExprMatches = cleanCode.matchAll(
    /(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=\s*function\s*\(/g
  )
  for (const match of funcExprMatches) {
    candidates.push(match[1])
  }

  const helperClassNames = new Set([
    "Node",
    "ListNode",
    "TreeNode",
    "TrieNode",
    "GraphNode",
    "NestedInteger",
    "eval",
    "_buildTree",
    "_treeToArray",
    "_buildList",
    "_listToArray",
  ])

  return Array.from(new Set(candidates)).filter((name) => !helperClassNames.has(name))
}

export function buildJsWrapper(
  code: string,
  testCase: any,
  cleanCode: string,
  scenarioId: string
): string {
  const inputKeys = Object.keys(testCase.input)
  const inputValues = Object.values(testCase.input)
  const inputJson = JSON.stringify(inputValues)
  const inputKeysJson = JSON.stringify(inputKeys)

  // Check if class-based problem
  const isClassBased =
    inputKeys.includes("operations") &&
    inputKeys.includes("values") &&
    Array.isArray(testCase.input.operations)

  let className: string | null = null
  if (isClassBased && testCase.input.operations && testCase.input.operations.length > 0) {
    const operationClassName = testCase.input.operations[0]
    const specificClassMatch = cleanCode.match(new RegExp(`class\\s+${operationClassName}\\b`))
    if (specificClassMatch) {
      className = operationClassName
    }
  }

  if (!className && isClassBased) {
    const allClasses = cleanCode.matchAll(/class\s+(\w+)/g)
    const helperClassNames = new Set([
      "Node",
      "ListNode",
      "TreeNode",
      "TrieNode",
      "GraphNode",
      "NestedInteger",
    ])
    for (const match of allClasses) {
      const foundClassName = match[1]
      if (!helperClassNames.has(foundClassName)) {
        className = foundClassName
        break
      }
    }
    if (!className) {
      const classMatch = cleanCode.match(/class\s+(\w+)/)
      className = classMatch ? classMatch[1] : null
    }
  }

  const candidates = getFunctionCandidates(cleanCode)
  // Check candidates in reverse order (typically main entry point is defined at/near bottom, helpers at top)
  const candidateChecks = candidates
    .reverse()
    .map((name) => `else if (typeof ${name} === 'function') _func = ${name};`)
    .join("\n  ")

  // Derive target camelCase name from scenario ID
  const cleanId = scenarioId.replace(/^dsa-/, "")
  const camelCasedId = cleanId.replace(/-([a-z])/g, (g) => g[1].toUpperCase())
  const scenarioIdentifier = isValidIdentifier(camelCasedId) ? camelCasedId : null

  return `
class TreeNode {
  constructor(val = 0, left = null, right = null) {
    this.val = val;
    this.left = left;
    this.right = right;
  }
}

class ListNode {
  constructor(val = 0, next = null) {
    this.val = val;
    this.next = next;
  }
}

function _buildTree(arr) {
  if (!arr || arr.length === 0 || arr[0] === null) return null;
  const root = new TreeNode(arr[0]);
  const queue = [root];
  let i = 1;
  while (queue.length > 0 && i < arr.length) {
    const node = queue.shift();
    if (i < arr.length && arr[i] !== null) {
      node.left = new TreeNode(arr[i]);
      queue.push(node.left);
    }
    i++;
    if (i < arr.length && arr[i] !== null) {
      node.right = new TreeNode(arr[i]);
      queue.push(node.right);
    }
    i++;
  }
  return root;
}

function _treeToArray(root) {
  if (!root) return [];
  const result = [];
  const queue = [root];
  while (queue.length > 0) {
    const node = queue.shift();
    if (node) {
      result.push(node.val);
      queue.push(node.left);
      queue.push(node.right);
    } else {
      result.push(null);
    }
  }
  while (result.length > 0 && result[result.length - 1] === null) {
    result.pop();
  }
  return result;
}

function _buildList(arr) {
  if (!arr || arr.length === 0) return null;
  const head = new ListNode(arr[0]);
  let current = head;
  for (let i = 1; i < arr.length; i++) {
    current.next = new ListNode(arr[i]);
    current = current.next;
  }
  return head;
}

function _listToArray(head) {
  const result = [];
  let current = head;
  const seen = new Set();
  while (current && !seen.has(current)) {
    seen.add(current);
    result.push(current.val);
    current = current.next;
  }
  return result;
}

${code}

const _input = ${inputJson};
const _inputKeys = ${inputKeysJson};

${
  isClassBased && className
    ? `
  const _operations = _input[_inputKeys.indexOf('operations')];
  const _values = _input[_inputKeys.indexOf('values')];
  const _results = [];
  let _instance = null;

  for (let i = 0; i < _operations.length; i++) {
    const op = _operations[i];
    const args = _values[i] || [];
    if (op === '${className}' || i === 0) {
      _instance = new ${className}(...args);
      _results.push(null);
    } else {
      const result = _instance[op](...args);
      _results.push(result === undefined ? null : result);
    }
  }
  return _results;
`
    : `
  let _func;
  let _instance;

  // Support LeetCode class Solution style wrappers
  if (typeof Solution === 'function') {
    try {
      _instance = new Solution();
      if (typeof _instance.solution === 'function') {
        _func = _instance.solution.bind(_instance);
      }
      ${scenarioIdentifier ? `else if (typeof _instance.${scenarioIdentifier} === 'function') _func = _instance.${scenarioIdentifier}.bind(_instance);` : ""}
      else if (typeof _instance.twoSum === 'function') _func = _instance.twoSum.bind(_instance);
      else if (typeof _instance.isAnagram === 'function') _func = _instance.isAnagram.bind(_instance);
      else if (typeof _instance.groupAnagrams === 'function') _func = _instance.groupAnagrams.bind(_instance);
      else if (typeof _instance.longestConsecutive === 'function') _func = _instance.longestConsecutive.bind(_instance);
      else if (typeof _instance.firstMissingPositive === 'function') _func = _instance.firstMissingPositive.bind(_instance);
      else if (typeof _instance.majorityElement === 'function') _func = _instance.majorityElement.bind(_instance);
      else if (typeof _instance.nextPermutation === 'function') _func = _instance.nextPermutation.bind(_instance);
      else if (typeof _instance.productExceptSelf === 'function') _func = _instance.productExceptSelf.bind(_instance);
      else if (typeof _instance.rotate === 'function') _func = _instance.rotate.bind(_instance);
      else if (typeof _instance.subarraySum === 'function') _func = _instance.subarraySum.bind(_instance);
      else if (typeof _instance.topKFrequent === 'function') _func = _instance.topKFrequent.bind(_instance);
      else if (typeof _instance.findDuplicates === 'function') _func = _instance.findDuplicates.bind(_instance);
      else if (typeof _instance.main === 'function') _func = _instance.main.bind(_instance);
      else if (typeof _instance.isSameTree === 'function') _func = _instance.isSameTree.bind(_instance);
      else if (typeof _instance.invertTree === 'function') _func = _instance.invertTree.bind(_instance);
      else if (typeof _instance.processAdjacentPairs === 'function') _func = _instance.processAdjacentPairs.bind(_instance);
      else if (typeof _instance.getUserEmailFormatted === 'function') _func = _instance.getUserEmailFormatted.bind(_instance);
      else {
        const methods = Object.getOwnPropertyNames(Solution.prototype).filter(
          m => m !== 'constructor' && typeof _instance[m] === 'function'
        );
        if (methods.length > 0) {
          _func = _instance[methods[0]].bind(_instance);
        }
      }
    } catch (e) {
      // Ignore construction error and fallback to global functions
    }
  }

  // Fallback to global functions/arrow functions/candidates
  if (!_func) {
    if (typeof solution === 'function') _func = solution;
    ${scenarioIdentifier ? `else if (typeof ${scenarioIdentifier} === 'function') _func = ${scenarioIdentifier};` : ""}
    else if (typeof twoSum === 'function') _func = twoSum;
    else if (typeof isAnagram === 'function') _func = isAnagram;
    else if (typeof groupAnagrams === 'function') _func = groupAnagrams;
    else if (typeof longestConsecutive === 'function') _func = longestConsecutive;
    else if (typeof firstMissingPositive === 'function') _func = firstMissingPositive;
    else if (typeof majorityElement === 'function') _func = majorityElement;
    else if (typeof nextPermutation === 'function') _func = nextPermutation;
    else if (typeof productExceptSelf === 'function') _func = productExceptSelf;
    else if (typeof rotate === 'function') _func = rotate;
    else if (typeof subarraySum === 'function') _func = subarraySum;
    else if (typeof topKFrequent === 'function') _func = topKFrequent;
    else if (typeof findDuplicates === 'function') _func = findDuplicates;
    else if (typeof main === 'function') _func = main;
    else if (typeof isSameTree === 'function') _func = isSameTree;
    else if (typeof invertTree === 'function') _func = invertTree;
    else if (typeof processAdjacentPairs === 'function') _func = processAdjacentPairs;
    else if (typeof getUserEmailFormatted === 'function') _func = getUserEmailFormatted;
    ${candidateChecks ? `\n    ${candidateChecks}` : ""}
  }

  if (!_func) {
    const funcNames = Object.keys(this).filter(k => typeof this[k] === 'function' && k !== 'eval' && k !== '_buildTree' && k !== '_treeToArray' && k !== '_buildList' && k !== '_listToArray');
    if (funcNames.length > 0) _func = this[funcNames[0]];
  }

  if (typeof _func !== 'function') {
    throw new Error('No callable function found');
  }

  const _treeKeywords = new Set(['root', 'tree', 'node', 'p', 'q', 't1', 't2', 'left', 'right', 'subroot']);
  const _listKeywords = new Set(['head', 'list', 'l1', 'l2']);

  const _processedInput = _input.map((arg, i) => {
    const key = (_inputKeys[i] || '').toLowerCase();
    if (Array.isArray(arg)) {
      if (_treeKeywords.has(key)) return arg.length > 0 ? _buildTree(arg) : null;
      if (_listKeywords.has(key)) return arg.length > 0 ? _buildList(arg) : null;
    }
    return arg;
  });

  let _result;
  if (typeof encode === 'function' && typeof decode === 'function') {
    _result = decode(encode(..._processedInput));
  } else if (typeof Solution === 'function' && _instance && typeof _instance.encode === 'function' && typeof _instance.decode === 'function') {
    _result = _instance.decode(_instance.encode(..._processedInput));
  } else {
    _result = _func(..._processedInput);
  }

  const _hadTreeInput = _processedInput.some((arg, i) => {
    const key = (_inputKeys[i] || '').toLowerCase();
    return Array.isArray(_input[i]) && _treeKeywords.has(key);
  });

  if (_result instanceof TreeNode) {
    _result = _treeToArray(_result);
  } else if (_result instanceof ListNode) {
    _result = _listToArray(_result);
  } else if (_result === null && _hadTreeInput) {
    _result = [];
  }

  return _result;
`
}
`
}

// Function to execute wrapped code string in Web Worker with a 5s timeout
export function runInWorker(
  workerData: { code?: string; files?: { path: string; content: string }[]; entrypoint?: string },
  timeoutMs = 5000
): Promise<{ success: boolean; result?: any; logs: any[]; error?: string }> {
  return new Promise((resolve) => {
    if (typeof window === "undefined") {
      resolve({ success: false, logs: [], error: "Execution environment is not browser" })
      return
    }

    let worker: Worker
    try {
      worker = new Worker("/workers/js-sandbox-worker.js")
    } catch (err) {
      resolve({ success: false, logs: [], error: `Failed to spawn Web Worker: ${err}` })
      return
    }

    const timer = setTimeout(() => {
      worker.terminate()
      resolve({
        success: false,
        logs: [],
        error: "Code execution timed out. Try checking for infinite loops.",
      })
    }, timeoutMs)

    worker.onmessage = (e) => {
      clearTimeout(timer)
      worker.terminate()
      resolve(e.data)
    }

    worker.onerror = (err) => {
      clearTimeout(timer)
      worker.terminate()
      resolve({
        success: false,
        logs: [],
        error: err.message || "Unknown worker error",
      })
    }

    worker.postMessage(workerData)
  })
}

import type {
  WorkspaceExecutionResult,
  WorkspaceFileEdit,
  WorkspaceScenario,
  WorkspaceTestResult,
} from "../types"
import { overlayWorkspaceFiles } from "../files"
import { transpileIfNeeded } from "./transpiler"
import { runInWorker } from "./worker-runner"

export async function executeWorkspaceScenarioJsClientSide(
  scenario: WorkspaceScenario,
  edits: WorkspaceFileEdit[]
): Promise<WorkspaceExecutionResult> {
  let allConsoleLogs: any[] = []
  try {
    const files = overlayWorkspaceFiles(scenario, edits)
    const runner = files.find((file) => file.path === scenario.workspace.testRunnerPath)
    if (!runner) {
      throw new Error(`Workspace runner not found: ${scenario.workspace.testRunnerPath}`)
    }

    const processedFiles = await Promise.all(
      files.map(async (file) => {
        const isTS = file.path.endsWith(".ts") || file.path.endsWith(".tsx")
        const cleanPath = file.path.replace(/\.tsx?$/, ".js")

        let content = file.content
        if (isTS) {
          content = await transpileIfNeeded(content, "typescript")
        }

        return {
          path: cleanPath,
          content,
        }
      })
    )

    const cleanRunnerPath = runner.path.replace(/\.tsx?$/, ".js")

    const runResult = await runInWorker({
      entrypoint: cleanRunnerPath,
      files: processedFiles,
    })

    if (runResult.logs && runResult.logs.length > 0) {
      allConsoleLogs = runResult.logs
    }

    if (!runResult.success || runResult.error) {
      return {
        success: false,
        results: [
          {
            suite: "workspace",
            name: "Workspace test runner",
            passed: false,
            error: runResult.error || "Execution failed",
          },
        ],
        consoleLogs: allConsoleLogs.map((log) => ({
          ...log,
          message: log.message.startsWith("__WORKSPACE_TEST_RESULTS__:") ? "" : log.message,
        })),
        summary: {
          total: 1,
          passed: 0,
          failed: 1,
          passRate: 0,
          serviceErrors: 0,
          effectiveTotal: 1,
        },
        error: null,
      }
    }

    const results: WorkspaceTestResult[] = []
    const cleanLogs: any[] = []

    for (const log of allConsoleLogs) {
      const message = log.message || ""
      if (message.startsWith("__WORKSPACE_TEST_RESULTS__:")) {
        try {
          const parsed = JSON.parse(message.slice("__WORKSPACE_TEST_RESULTS__:".length))
          if (Array.isArray(parsed)) {
            results.push(...parsed)
          }
        } catch {
          // ignore parse errors
        }
      } else {
        cleanLogs.push(log)
      }
    }

    const finalResults =
      results.length > 0
        ? results
        : [
            {
              suite: "workspace",
              name: "Workspace test runner",
              passed: false,
              error: "Test runner did not report any test results.",
            },
          ]

    const passedCount = finalResults.filter((r) => r.passed).length
    const totalCount = finalResults.length
    const failedCount = totalCount - passedCount
    const passRate = totalCount > 0 ? Math.round((passedCount / totalCount) * 100) : 0

    return {
      success: failedCount === 0,
      results: finalResults,
      consoleLogs: cleanLogs,
      summary: {
        total: totalCount,
        passed: passedCount,
        failed: failedCount,
        passRate,
        serviceErrors: 0,
        effectiveTotal: totalCount,
      },
      error: null,
    }
  } catch (err) {
    return {
      success: false,
      results: [],
      consoleLogs: [],
      summary: { total: 0, passed: 0, failed: 0, passRate: 0, serviceErrors: 0, effectiveTotal: 0 },
      error:
        err instanceof Error ? err.message : "Failed to execute workspace scenario client-side",
    }
  }
}

import type { DsaExecutionResult, DsaTestResult } from "../types"
import { validateResultEnhanced } from "@/lib/validators"
import { stripComments } from "../js-sandbox/comments"
import { buildPythonWrapper } from "./dsa-wrapper"
import { runPythonInWorker } from "./worker-runner"

export async function executePythonClientSide(
  code: string,
  testCases: unknown[],
  scenarioId: string
): Promise<DsaExecutionResult> {
  const results: DsaTestResult[] = []
  const consoleLogs: DsaExecutionResult["consoleLogs"] = []

  try {
    const cleanCode = stripComments(code, "python")

    for (let index = 0; index < testCases.length; index++) {
      const testCase = testCases[index] as {
        description?: string
        input?: unknown
        expected?: unknown
      }
      const wrappedCode = buildPythonWrapper(code, testCase, cleanCode, scenarioId)
      const runResult = await runPythonInWorker(wrappedCode)

      consoleLogs.push(...runResult.logs)

      if (!runResult.success || runResult.error) {
        results.push({
          description: testCase.description || `Test case ${index + 1}`,
          input: testCase.input,
          expected: testCase.expected,
          actual: null,
          passed: false,
          error: runResult.error || "Execution failed",
        })
        continue
      }

      const validation = validateResultEnhanced(
        runResult.result,
        testCase as any,
        scenarioId,
        "python"
      )

      results.push({
        description: testCase.description || `Test case ${index + 1}`,
        input: testCase.input,
        expected: testCase.expected,
        actual: runResult.result,
        passed: validation.passed,
        error: validation.reason || null,
      })
    }

    const passedCount = results.filter((result) => result.passed).length
    const totalCount = results.length

    return {
      success: passedCount === totalCount,
      results,
      consoleLogs,
      summary: {
        total: totalCount,
        passed: passedCount,
        failed: totalCount - passedCount,
        passRate: totalCount > 0 ? Math.round((passedCount / totalCount) * 100) : 0,
        serviceErrors: 0,
        effectiveTotal: totalCount,
      },
      error: null,
    }
  } catch (error) {
    return {
      success: false,
      results: [],
      consoleLogs,
      summary: { total: 0, passed: 0, failed: 0, passRate: 0, serviceErrors: 0, effectiveTotal: 0 },
      error: error instanceof Error ? error.message : "Failed to execute Python client-side",
    }
  }
}

