/**
 * Next.js Edge Proxy
 *
 * Provides server-side protection for admin routes BEFORE pages render.
 * This prevents admin pages from briefly flashing before client-side auth check.
 *
 * SECURITY: This proxy runs on Edge runtime (before page render).
 * - Checks for authentication token in cookies or Authorization header
 * - For /admin/* routes, requires authentication to proceed
 * - Actual admin role verification happens in admin layout (defense-in-depth)
 */

import { NextResponse } from "next/server"
import type { NextRequest } from "next/server"

// Routes that require authentication
const PROTECTED_ROUTES = ["/admin"]

// Routes that should redirect authenticated users away
const AUTH_ROUTES = ["/login", "/signup"]

// Public routes that never require auth
const PUBLIC_ROUTES = ["/", "/pricing", "/blog", "/about", "/privacy", "/terms"]

/**
 * Check if user appears to be authenticated
 * Note: This is a quick check - full verification happens server-side
 */
function hasAuthToken(request: NextRequest): boolean {
  // Check for Firebase session cookie (set by Firebase Auth)
  const sessionCookie = request.cookies.get("__session")
  if (sessionCookie?.value) {
    return true
  }

  // Check for Firebase auth token in local storage indicator cookie
  // Firebase client SDK stores auth state - we check for indicator cookie
  const firebaseAuth = request.cookies.get("firebase-auth-token")
  if (firebaseAuth?.value) {
    return true
  }

  // Check Authorization header (for API-like requests to pages)
  const authHeader = request.headers.get("authorization")
  if (authHeader?.startsWith("Bearer ")) {
    return true
  }

  return false
}

/**
 * Check if path matches any protected route patterns
 */
function isProtectedRoute(pathname: string): boolean {
  return PROTECTED_ROUTES.some((route) => pathname === route || pathname.startsWith(`${route}/`))
}

/**
 * Check if path is an auth route (login/signup)
 */
function isAuthRoute(pathname: string): boolean {
  return AUTH_ROUTES.some((route) => pathname === route || pathname.startsWith(`${route}/`))
}

export function proxy(request: NextRequest) {
  const { pathname } = request.nextUrl

  // Skip proxy for API routes, static files, etc.
  if (
    pathname.startsWith("/api/") ||
    pathname.startsWith("/_next/") ||
    pathname.startsWith("/static/") ||
    pathname.includes(".") // Files with extensions
  ) {
    return NextResponse.next()
  }

  const isAuthenticated = hasAuthToken(request)

  // Protect admin routes - redirect to login if not authenticated
  if (isProtectedRoute(pathname)) {
    if (!isAuthenticated) {
      const loginUrl = new URL("/login", request.url)
      loginUrl.searchParams.set("redirect", pathname)

      // Add security header to indicate this was a proxy redirect
      const response = NextResponse.redirect(loginUrl)
      response.headers.set("X-Proxy-Redirect", "auth-required")
      return response
    }
  }

  // Optionally redirect authenticated users away from auth pages
  // Uncomment if you want this behavior:
  // if (isAuthRoute(pathname) && isAuthenticated) {
  //   return NextResponse.redirect(new URL('/dashboard', request.url))
  // }

  return NextResponse.next()
}

// Configure which routes use this proxy
export const config = {
  matcher: [
    /*
     * Match all request paths except:
     * - api (API routes)
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     * - public files (images, etc.)
     */
    "/((?!api|_next/static|_next/image|favicon.ico|.*\\..*|_next).*)",
  ],
}

// Web Worker for JavaScript Execution Sandbox
self.onmessage = async function (e) {
  const { code, files, entrypoint } = e.data

  // Track captured logs
  const logs = []

  let resolveResults
  const resultsPromise = new Promise((resolve) => {
    resolveResults = resolve
  })

  // Capture console functions inside the worker
  const originalLog = console.log
  const originalWarn = console.warn
  const originalError = console.error
  const originalInfo = console.info

  console.log = function (...args) {
    const message = args
      .map((a) => (typeof a === "object" ? JSON.stringify(a) : String(a)))
      .join(" ")
    logs.push({
      type: "log",
      message: message,
      timestamp: Date.now(),
    })
    originalLog.apply(console, args)
    if (resolveResults && message.startsWith("__WORKSPACE_TEST_RESULTS__:")) {
      resolveResults()
    }
  }
  console.warn = function (...args) {
    logs.push({
      type: "warn",
      message: args.map((a) => (typeof a === "object" ? JSON.stringify(a) : String(a))).join(" "),
      timestamp: Date.now(),
    })
    originalWarn.apply(console, args)
  }
  console.error = function (...args) {
    logs.push({
      type: "error",
      message: args.map((a) => (typeof a === "object" ? JSON.stringify(a) : String(a))).join(" "),
      timestamp: Date.now(),
    })
    originalError.apply(console, args)
  }
  console.info = function (...args) {
    logs.push({
      type: "info",
      message: args.map((a) => (typeof a === "object" ? JSON.stringify(a) : String(a))).join(" "),
      timestamp: Date.now(),
    })
    originalInfo.apply(console, args)
  }

  try {
    let result

    if (files && entrypoint) {
      // Workspace CommonJS Mode
      const modules = {}
      const cache = {}

      const deepEquals = (a, b) => {
        if (a === b) return true
        if (typeof a !== typeof b) return false
        if (a === null || b === null) return a === b
        if (typeof a === "object") {
          const keysA = Object.keys(a).sort()
          const keysB = Object.keys(b).sort()
          if (keysA.length !== keysB.length) return false
          if (keysA.join(",") !== keysB.join(",")) return false
          return keysA.every((key) => deepEquals(a[key], b[key]))
        }
        return false
      }

      const assertMock = {
        ok: (val, msg) => {
          if (!val) throw new Error(msg || `Expected truthy, got ${val}`)
        },
        equal: (a, b, msg) => {
          if (a != b) throw new Error(msg || `Expected ${a} == ${b}`)
        },
        notEqual: (a, b, msg) => {
          if (a == b) throw new Error(msg || `Expected ${a} != ${b}`)
        },
        strictEqual: (a, b, msg) => {
          if (a !== b) throw new Error(msg || `Expected ${a} === ${b}`)
        },
        notStrictEqual: (a, b, msg) => {
          if (a === b) throw new Error(msg || `Expected ${a} !== ${b}`)
        },
        deepStrictEqual: (a, b, msg) => {
          if (!deepEquals(a, b)) {
            throw new Error(
              msg || `Expected deep equality, got ${JSON.stringify(a)} vs ${JSON.stringify(b)}`
            )
          }
        },
        throws: (fn, reg) => {
          try {
            fn()
          } catch (e) {
            if (reg && reg instanceof RegExp && !reg.test(e.message)) {
              throw new Error(`Expected error matching ${reg}, got: ${e.message}`)
            }
            return
          }
          throw new Error("Expected function to throw an error")
        },
        rejects: async (fn) => {
          try {
            await fn()
          } catch {
            return
          }
          throw new Error("Expected promise to reject")
        },
      }

      // Populate module code map
      for (const file of files) {
        const cleanPath = file.path.replace(/^\.\//, "")
        modules[cleanPath] = file.content
      }

      // Inject assert mock cache entries
      cache["node:assert/strict"] = { exports: assertMock }
      cache["node:assert"] = { exports: assertMock }
      cache["assert"] = { exports: assertMock }

      function resolvePath(currentDir, targetPath) {
        let cleanTarget = targetPath
        if (!cleanTarget.endsWith(".js") && !cleanTarget.endsWith(".json")) {
          cleanTarget += ".js"
        }
        if (!cleanTarget.startsWith(".")) {
          return cleanTarget // e.g. "assert"
        }
        const parts = (currentDir ? currentDir.split("/") : []).concat(cleanTarget.split("/"))
        const stack = []
        for (const part of parts) {
          if (part === "." || part === "") continue
          if (part === "..") {
            stack.pop()
          } else {
            stack.push(part)
          }
        }
        return stack.join("/")
      }

      function requireModule(path, currentDir = "") {
        if (path === "node:assert/strict" || path === "node:assert" || path === "assert") {
          return assertMock
        }

        const resolved = resolvePath(currentDir, path)
        if (cache[resolved]) {
          return cache[resolved].exports
        }

        const moduleCode = modules[resolved]
        if (moduleCode === undefined) {
          throw new Error(`Module not found: ${path} (resolved as: ${resolved})`)
        }

        // eslint-disable-next-line @next/next/no-assign-module-variable
        const module = { exports: {} }
        cache[resolved] = module

        const nextDir = resolved.includes("/")
          ? resolved.substring(0, resolved.lastIndexOf("/"))
          : ""
        const wrapper = new Function(
          "exports",
          "require",
          "module",
          "__filename",
          "__dirname",
          moduleCode
        )

        const localRequire = (targetPath) => requireModule(targetPath, nextDir)
        wrapper(module.exports, localRequire, module, resolved, nextDir)
        return module.exports
      }

      const resolvedEntry = entrypoint.replace(/^\.\//, "")
      result = requireModule(resolvedEntry)

      // Wait for the test runner to finish and log results
      // Set a fallback timeout of 4.5s so we don't hang forever if the runner crashes
      const timeoutPromise = new Promise((_, reject) =>
        setTimeout(() => reject(new Error("Test execution timed out")), 4500)
      )
      await Promise.race([resultsPromise, timeoutPromise])
    } else {
      // Single-file Mode
      const executionFn = new Function(code)
      result = executionFn()
    }

    // Restore original console methods
    console.log = originalLog
    console.warn = originalWarn
    console.error = originalError
    console.info = originalInfo

    self.postMessage({
      success: true,
      result: result,
      logs: logs,
    })
  } catch (error) {
    // Restore original console methods
    console.log = originalLog
    console.warn = originalWarn
    console.error = originalError
    console.info = originalInfo

    self.postMessage({
      success: false,
      error: error.message || String(error),
      stack: error.stack,
      logs: logs,
    })
  }
}

